number, number]> implements IUniform<[number, number]> {\n    constructor(context: Context) {\n        super(context);\n        this.current = [0, 0];\n    }\n\n    set(program: WebGLProgram, name: string, v: [number, number]): void {\n        if (!this.fetchUniformLocation(program, name)) return;\n        if (v[0] !== this.current[0] || v[1] !== this.current[1]) {\n            this.current = v;\n            this.gl.uniform2f(this.location, v[0], v[1]);\n        }\n    }\n}\n\nclass Uniform3f extends Uniform<[number, number, number]> implements IUniform<[number, number, number]> {\n    constructor(context: Context) {\n        super(context);\n        this.current = [0, 0, 0];\n    }\n\n    set(program: WebGLProgram, name: string, v: [number, number, number]): void {\n        if (!this.fetchUniformLocation(program, name)) return;\n        if (v[0] !== this.current[0] || v[1] !== this.current[1] || v[2] !== this.current[2]) {\n            this.current = v;\n            this.gl.uniform3f(this.location, v[0], v[1], v[2]);\n        }\n    }\n}\n\nclass Uniform4f extends Uniform<[number, number, number, number]> implements IUniform<[number, number, number, number]> {\n    constructor(context: Context) {\n        super(context);\n        this.current = [0, 0, 0, 0];\n    }\n\n    set(program: WebGLProgram, name: string, v: [number, number, number, number]): void {\n        if (!this.fetchUniformLocation(program, name)) return;\n        if (v[0] !== this.current[0] || v[1] !== this.current[1] ||\n            v[2] !== this.current[2] || v[3] !== this.current[3]) {\n            this.current = v;\n            this.gl.uniform4f(this.location, v[0], v[1], v[2], v[3]);\n        }\n    }\n}\n\nclass UniformColor extends Uniform<RenderColor> implements IUniform<RenderColor> {\n    constructor(context: Context) {\n        super(context);\n        this.current = Color.transparent.toRenderColor(null);\n    }\n\n    set(program: WebGLProgram, name: string, v: RenderColor): void {\n        if (!this.fetchUniformLocation(program, name)) return;\n        if (v.r !== this.current.r || v.g !== this.current.g ||\n            v.b !== this.current.b || v.a !== this.current.a) {\n            this.current = v;\n            this.gl.uniform4f(this.location, v.r, v.g, v.b, v.a);\n        }\n    }\n}\n\nconst emptyMat4 = new Float32Array(16);\nclass UniformMatrix4f extends Uniform<Float32Array> implements IUniform<Float32Array> {\n    constructor(context: Context) {\n        super(context);\n        this.current = emptyMat4;\n    }\n\n    set(program: WebGLProgram, name: string, v: Float32Array): void {\n        if (!this.fetchUniformLocation(program, name)) return;\n        // The vast majority of matrix comparisons that will trip this set\n        // happen at i=12 or i=0, so we check those first to avoid lots of\n        // unnecessary iteration:\n        if (v[12] !== this.current[12] || v[0] !== this.current[0]) {\n            this.current = v;\n            this.gl.uniformMatrix4fv(this.location, false, v);\n            return;\n        }\n        for (let i = 1; i < 16; i++) {\n            if (v[i] !== this.current[i]) {\n                this.current = v;\n                this.gl.uniformMatrix4fv(this.location, false, v);\n                break;\n            }\n        }\n    }\n}\n\nconst emptyMat3 = new Float32Array(9);\nclass UniformMatrix3f extends Uniform<Float32Array> implements IUniform<Float32Array> {\n    constructor(context: Context) {\n        super(context);\n        this.current = emptyMat3;\n    }\n\n    set(program: WebGLProgram, name: string, v: Float32Array): void {\n        if (!this.fetchUniformLocation(program, name)) return;\n        for (let i = 0; i < 9; i++) {\n            if (v[i] !== this.current[i]) {\n                this.current = v;\n                this.gl.uniformMatrix3fv(this.location, false, v);\n                break;\n            }\n        }\n    }\n}\n\nconst emptyMat2 = new Float32Array(4);\nclass UniformMatrix2f extends Uniform<Float32Array> implements IUniform<Float32Array> {\n    constructor(context: Context) {\n        super(context);\n        this.current = emptyMat2;\n    }\n\n    set(program: WebGLProgram, name: string, v: Float32Array): void {\n        if (!this.fetchUniformLocation(program, name)) return;\n        for (let i = 0; i < 4; i++) {\n            if (v[i] !== this.current[i]) {\n                this.current = v;\n                this.gl.uniformMatrix2fv(this.location, false, v);\n                break;\n            }\n        }\n    }\n}\n\nexport {\n    Uniform1i,\n    Uniform1f,\n    Uniform2f,\n    Uniform3f,\n    Uniform4f,\n    UniformColor,\n    UniformMatrix2f,\n    UniformMatrix3f,\n    UniformMatrix4f\n};\n\nexport type UniformBindings = {\n    [_: string]: IUniform<any>;\n};\n","import {packUint8ToFloat} from '../shaders/encode_attribute';\nimport Color from '../style-spec/util/color';\nimport {supportsPropertyExpression} from '../style-spec/util/properties';\nimport {register} from '../util/web_worker_transfer';\nimport {PossiblyEvaluatedPropertyValue} from '../style/properties';\nimport {StructArrayLayout1f4, StructArrayLayout2f8, StructArrayLayout4f16, PatternLayoutArray, DashLayoutArray} from './array_types';\nimport {clamp} from '../util/util';\nimport patternAttributes from './bucket/pattern_attributes';\nimport dashAttributes from './bucket/dash_attributes';\nimport EvaluationParameters from '../style/evaluation_parameters';\nimport FeaturePositionMap from './feature_position_map';\nimport {\n    Uniform1f,\n    UniformColor,\n    Uniform4f\n} from '../render/uniform_binding';\nimport assert from 'assert';\n\nimport type {Class} from '../../src/types/class';\nimport type {CanonicalTileID} from '../source/tile_id';\nimport type Context from '../gl/context';\nimport type {TypedStyleLayer} from '../style/style_layer/typed_style_layer';\nimport type {StructArray, StructArrayMember} from '../util/struct_array';\nimport type VertexBuffer from '../gl/vertex_buffer';\nimport type {SpritePosition, SpritePositions} from '../util/image';\nimport type {\n    Feature,\n    FeatureState,\n    GlobalProperties,\n    SourceExpression,\n    CompositeExpression\n} from '../style-spec/expression/index';\nimport type {PossiblyEvaluated} from '../style/properties';\nimport type {FeatureStates} from '../source/source_state';\nimport type {FormattedSection} from '../style-spec/expression/types/formatted';\nimport type {VectorTileLayer} from '@mapbox/vector-tile';\nimport type {IUniform} from '../render/uniform_binding';\nimport type {LUT} from \"../util/lut\";\nimport type {RenderColor} from \"../style-spec/util/color\";\n\nexport type BinderUniform = {\n    name: string;\n    property: string;\n    binding: IUniform<any>;\n};\n\nexport type ProgramConfigurationContext = {\n    zoom: number;\n    lut: LUT | null;\n};\n\nfunction packColor(color: RenderColor): [number, number] {\n    return [\n        packUint8ToFloat(255 * color.r, 255 * color.g),\n        packUint8ToFloat(255 * color.b, 255 * color.a)\n    ];\n}\n\n/**\n *  `Binder` is the interface definition for the strategies for constructing,\n *  uploading, and binding paint property data as GLSL attributes. Most style-\n *  spec properties have a 1:1 relationship to shader attribute/uniforms, but\n *  some require multiple values per feature to be passed to the GPU, and in\n *  those cases we bind multiple attributes/uniforms.\n *\n *  It has three implementations, one for each of the three strategies we use:\n *\n *  * For _constant_ properties -- those whose value is a constant, or the constant\n *    result of evaluating a camera expression at a particular camera position -- we\n *    don't need a vertex attribute buffer, and instead use a uniform.\n *  * For data expressions, we use a vertex buffer with a single attribute value,\n *    the evaluated result of the source function for the given feature.\n *  * For composite expressions, we use a vertex buffer with two attributes: min and\n *    max values covering the range of zooms at which we expect the tile to be\n *    displayed. These values are calculated by evaluating the composite expression for\n *    the given feature at strategically chosen zoom levels. In addition to this\n *    attribute data, we also use a uniform value which the shader uses to interpolate\n *    between the min and max value at the final displayed zoom level. The use of a\n *    uniform allows us to cheaply update the value on every frame.\n *\n *  Note that the shader source varies depending on whether we're using a uniform or\n *  attribute. We dynamically compile shaders at runtime to accommodate this.\n *\n * @private\n */\n\ninterface AttributeBinder {\n    context: ProgramConfigurationContext;\n    populatePaintArray(\n        length: number,\n        feature: Feature,\n        imagePositions: SpritePositions,\n        availableImages: Array<string>,\n        canonical?: CanonicalTileID,\n        brightness?: number | null | undefined,\n        formattedSection?: FormattedSection,\n    ): void;\n    updatePaintArray(\n        start: number,\n        length: number,\n        feature: Feature,\n        featureState: FeatureState,\n        availableImages: Array<string>,\n        imagePositions: SpritePositions,\n        brightness: number,\n    ): void;\n    upload(arg1: Context): void;\n    destroy(): void;\n}\n\ninterface UniformBinder {\n    uniformNames: Array<string>;\n    context: ProgramConfigurationContext;\n    setUniform(\n        program: WebGLProgram,\n        uniform: IUniform<any>,\n        globals: GlobalProperties,\n        currentValue: PossiblyEvaluatedPropertyValue<any>,\n        uniformName: string,\n    ): void;\n    getBinding(context: Context, name: string): Partial<IUniform<any>>;\n}\n\nclass ConstantBinder implements UniformBinder {\n    value: unknown;\n    type: string;\n    uniformNames: Array<string>;\n    context: ProgramConfigurationContext;\n\n    constructor(value: unknown, names: Array<string>, type: string, context: ProgramConfigurationContext) {\n        this.value = value;\n        this.uniformNames = names.map(name => `u_${name}`);\n        this.type = type;\n        this.context = context;\n    }\n\n    setUniform(\n        program: WebGLProgram,\n        uniform: IUniform<any>,\n        globals: GlobalProperties,\n        currentValue: PossiblyEvaluatedPropertyValue<unknown>,\n        uniformName: string,\n    ): void {\n        const value = currentValue.constantOr(this.value);\n        if (value instanceof Color) {\n            uniform.set(program, uniformName, value.toRenderColor(this.context.lut));\n        } else {\n            uniform.set(program, uniformName, value);\n        }\n    }\n\n    getBinding(context: Context, _: string): Partial<IUniform<any>> {\n        return (this.type === 'color') ?\n            new UniformColor(context) :\n            new Uniform1f(context);\n    }\n}\n\nclass PatternConstantBinder implements UniformBinder {\n    uniformNames: Array<string>;\n    pattern: Array<number> | null | undefined;\n    pixelRatio: number;\n    context: ProgramConfigurationContext;\n\n    constructor(value: unknown, names: Array<string>) {\n        this.uniformNames = names.map(name => `u_${name}`);\n        this.pattern = null;\n        this.pixelRatio = 1;\n    }\n\n    setConstantPatternPositions(posTo: SpritePosition) {\n        this.pixelRatio = posTo.pixelRatio || 1;\n        this.pattern = posTo.tl.concat(posTo.br);\n    }\n\n    setUniform(program: WebGLProgram, uniform: IUniform<any>, globals: GlobalProperties, currentValue: PossiblyEvaluatedPropertyValue<unknown>, uniformName: string) {\n        const pos =\n            uniformName === 'u_pattern' || uniformName === 'u_dash' ? this.pattern :\n            uniformName === 'u_pixel_ratio' ? this.pixelRatio : null;\n        if (pos) uniform.set(program, uniformName, pos);\n    }\n\n    getBinding(context: Context, name: string): Partial<IUniform<any>> {\n        return name === 'u_pattern' || name === 'u_dash' ?\n            new Uniform4f(context) :\n            new Uniform1f(context);\n    }\n}\n\nclass SourceExpressionBinder implements AttributeBinder {\n    expression: SourceExpression;\n    type: string;\n    maxValue: number;\n    context: ProgramConfigurationContext;\n\n    paintVertexArray: StructArray;\n    paintVertexAttributes: Array<StructArrayMember>;\n    paintVertexBuffer: VertexBuffer | null | undefined;\n\n    constructor(expression: SourceExpression, names: Array<string>, type: string, PaintVertexArray: Class<StructArray>) {\n        this.expression = expression;\n        this.type = type;\n        this.maxValue = 0;\n        this.paintVertexAttributes = names.map((name) => ({\n            name: `a_${name}`,\n            type: 'Float32',\n            components: type === 'color' ? 2 : 1,\n            offset: 0\n        }));\n        this.paintVertexArray = new PaintVertexArray();\n    }\n\n    populatePaintArray(newLength: number, feature: Feature, imagePositions: SpritePositions, availableImages: Array<string>, canonical?: CanonicalTileID, brightness?: number | null, formattedSection?: FormattedSection) {\n        const start = this.paintVertexArray.length;\n        assert(Array.isArray(availableImages));\n        const value = this.expression.evaluate(new EvaluationParameters(0, {brightness}), feature, {}, canonical, availableImages, formattedSection);\n        this.paintVertexArray.resize(newLength);\n        this._setPaintValue(start, newLength, value, this.context);\n    }\n\n    updatePaintArray(start: number, end: number, feature: Feature, featureState: FeatureState, availableImages: Array<string>, spritePositions: SpritePositions, brightness: number) {\n        const value = this.expression.evaluate({zoom: 0, brightness}, feature, featureState, undefined, availableImages);\n        this._setPaintValue(start, end, value, this.context);\n    }\n\n    _setPaintValue(start: number, end: number, value: any, context: ProgramConfigurationContext) {\n        if (this.type === 'color') {\n            const color = packColor(value.toRenderColor(context.lut));\n            for (let i = start; i < end; i++) {\n                this.paintVertexArray.emplace(i, color[0], color[1]);\n            }\n        } else {\n            for (let i = start; i < end; i++) {\n                this.paintVertexArray.emplace(i, value);\n            }\n            this.maxValue = Math.max(this.maxValue, Math.abs(value));\n        }\n    }\n\n    upload(context: Context) {\n        if (this.paintVertexArray && this.paintVertexArray.arrayBuffer) {\n            if (this.paintVertexBuffer && this.paintVertexBuffer.buffer) {\n                this.paintVertexBuffer.updateData(this.paintVertexArray);\n            } else {\n                this.paintVertexBuffer = context.createVertexBuffer(this.paintVertexArray, this.paintVertexAttributes, this.expression.isStateDependent || !this.expression.isLightConstant);\n            }\n        }\n    }\n\n    destroy() {\n        if (this.paintVertexBuffer) {\n            this.paintVertexBuffer.destroy();\n        }\n    }\n}\n\nclass CompositeExpressionBinder implements AttributeBinder, UniformBinder {\n    expression: CompositeExpression;\n    uniformNames: Array<string>;\n    type: string;\n    useIntegerZoom: boolean;\n    context: ProgramConfigurationContext;\n    maxValue: number;\n\n    paintVertexArray: StructArray;\n    paintVertexAttributes: Array<StructArrayMember>;\n    paintVertexBuffer: VertexBuffer | null | undefined;\n\n    constructor(expression: CompositeExpression, names: Array<string>, type: string, useIntegerZoom: boolean, context: ProgramConfigurationContext, PaintVertexArray: Class<StructArray>) {\n        this.expression = expression;\n        this.uniformNames = names.map(name => `u_${name}_t`);\n        this.type = type;\n        this.useIntegerZoom = useIntegerZoom;\n        this.context = context;\n        this.maxValue = 0;\n        this.paintVertexAttributes = names.map((name) => ({\n            name: `a_${name}`,\n            type: 'Float32',\n            components: type === 'color' ? 4 : 2,\n            offset: 0\n        }));\n        this.paintVertexArray = new PaintVertexArray();\n    }\n\n    populatePaintArray(newLength: number, feature: Feature, imagePositions: SpritePositions, availableImages: Array<string>, canonical?: CanonicalTileID, brightness?: number | null, formattedSection?: FormattedSection) {\n        const min = this.expression.evaluate(new EvaluationParameters(this.context.zoom, {brightness}), feature, {}, canonical, availableImages, formattedSection);\n        const max = this.expression.evaluate(new EvaluationParameters(this.context.zoom + 1, {brightness}), feature, {}, canonical, availableImages, formattedSection);\n        const start = this.paintVertexArray.length;\n        this.paintVertexArray.resize(newLength);\n        this._setPaintValue(start, newLength, min, max, this.context);\n    }\n\n    updatePaintArray(start: number, end: number, feature: Feature, featureState: FeatureState, availableImages: Array<string>, spritePositions: SpritePositions, brightness: number) {\n        const min = this.expression.evaluate({zoom: this.context.zoom, brightness}, feature, featureState, undefined, availableImages);\n        const max = this.expression.evaluate({zoom: this.context.zoom + 1, brightness}, feature, featureState, undefined, availableImages);\n        this._setPaintValue(start, end, min, max, this.context);\n    }\n\n    _setPaintValue(start: number, end: number, min: any, max: any, context: ProgramConfigurationContext) {\n        if (this.type === 'color') {\n            const minColor = packColor(min.toRenderColor(context.lut));\n            const maxColor = packColor(min.toRenderColor(context.lut));\n            for (let i = start; i < end; i++) {\n                this.paintVertexArray.emplace(i, minColor[0], minColor[1], maxColor[0], maxColor[1]);\n            }\n        } else {\n            for (let i = start; i < end; i++) {\n                this.paintVertexArray.emplace(i, min, max);\n            }\n            this.maxValue = Math.max(this.maxValue, Math.abs(min), Math.abs(max));\n        }\n    }\n\n    upload(context: Context) {\n        if (this.paintVertexArray && this.paintVertexArray.arrayBuffer) {\n            if (this.paintVertexBuffer && this.paintVertexBuffer.buffer) {\n                this.paintVertexBuffer.updateData(this.paintVertexArray);\n            } else {\n                this.paintVertexBuffer = context.createVertexBuffer(this.paintVertexArray, this.paintVertexAttributes, this.expression.isStateDependent || !this.expression.isLightConstant);\n            }\n        }\n    }\n\n    destroy() {\n        if (this.paintVertexBuffer) {\n            this.paintVertexBuffer.destroy();\n        }\n    }\n\n    setUniform(\n        program: WebGLProgram,\n        uniform: IUniform<any>,\n        globals: GlobalProperties,\n        _: PossiblyEvaluatedPropertyValue<any>,\n        uniformName: string,\n    ): void {\n        const currentZoom = this.useIntegerZoom ? Math.floor(globals.zoom) : globals.zoom;\n        const factor = clamp(this.expression.interpolationFactor(currentZoom, this.context.zoom, this.context.zoom + 1), 0, 1);\n        uniform.set(program, uniformName, factor);\n    }\n\n    getBinding(context: Context, _: string): Uniform1f {\n        return new Uniform1f(context);\n    }\n}\n\nclass PatternCompositeBinder implements AttributeBinder {\n    expression: CompositeExpression;\n    layerId: string;\n    context: ProgramConfigurationContext;\n\n    paintVertexArray: StructArray;\n    paintVertexBuffer: VertexBuffer | null | undefined;\n    paintVertexAttributes: Array<StructArrayMember>;\n\n    constructor(expression: CompositeExpression, names: Array<string>, type: string, PaintVertexArray: Class<StructArray>, layerId: string) {\n        this.expression = expression;\n        this.layerId = layerId;\n\n        this.paintVertexAttributes = (type === 'array' ? dashAttributes : patternAttributes).members;\n        for (let i = 0; i < names.length; ++i) {\n            assert(`a_${names[i]}` === this.paintVertexAttributes[i].name);\n        }\n\n        this.paintVertexArray = new PaintVertexArray();\n    }\n\n    populatePaintArray(length: number, feature: Feature, imagePositions: SpritePositions, _availableImages: Array<string>) {\n        const start = this.paintVertexArray.length;\n        this.paintVertexArray.resize(length);\n        this._setPaintValues(start, length, feature.patterns && feature.patterns[this.layerId], imagePositions);\n    }\n\n    updatePaintArray(start: number, end: number, feature: Feature, featureState: FeatureState, availableImages: Array<string>, imagePositions: SpritePositions, _?: number | null) {\n        this._setPaintValues(start, end, feature.patterns && feature.patterns[this.layerId], imagePositions);\n    }\n\n    _setPaintValues(start: number, end: number, patterns: string | null | undefined, positions: SpritePositions) {\n        if (!positions || !patterns) return;\n\n        const pos = positions[patterns];\n        if (!pos) return;\n\n        const {tl, br, pixelRatio} = pos;\n        for (let i = start; i < end; i++) {\n            this.paintVertexArray.emplace(i, tl[0], tl[1], br[0], br[1], (pixelRatio));\n        }\n    }\n\n    upload(context: Context) {\n        if (this.paintVertexArray && this.paintVertexArray.arrayBuffer) {\n            this.paintVertexBuffer = context.createVertexBuffer(this.paintVertexArray, this.paintVertexAttributes, this.expression.isStateDependent || !this.expression.isLightConstant);\n        }\n    }\n\n    destroy() {\n        if (this.paintVertexBuffer) this.paintVertexBuffer.destroy();\n    }\n}\n\n/**\n * ProgramConfiguration contains the logic for binding style layer properties and tile\n * layer feature data into GL program uniforms and vertex attributes.\n *\n * Non-data-driven property values are bound to shader uniforms. Data-driven property\n * values are bound to vertex attributes. In order to support a uniform GLSL syntax over\n * both, [Mapbox GL Shaders](https://github.com/mapbox/mapbox-gl-shaders) defines a `#pragma`\n * abstraction, which ProgramConfiguration is responsible for implementing. At runtime,\n * it examines the attributes of a particular layer, combines this with fixed knowledge\n * about how layers of the particular type are implemented, and determines which uniforms\n * and vertex attributes will be required. It can then substitute the appropriate text\n * into the shader source code, create and link a program, and bind the uniforms and\n * vertex attributes in preparation for drawing.\n *\n * When a vector tile is parsed, this same configuration information is used to\n * populate the attribute buffers needed for data-driven styling using the zoom\n * level and feature property data.\n *\n * @private\n */\nexport default class ProgramConfiguration {\n    binders: {\n        [_: string]: AttributeBinder | UniformBinder;\n    };\n    cacheKey: string;\n    context: ProgramConfigurationContext;\n\n    _buffers: Array<VertexBuffer>;\n\n    constructor(layer: TypedStyleLayer, context: ProgramConfigurationContext, filterProperties: (_: string) => boolean = () => true) {\n        this.binders = {};\n        this._buffers = [];\n        this.context = context;\n\n        const keys = [];\n\n        for (const property in layer.paint._values) {\n            // @ts-expect-error - TS2349 - This expression is not callable.\n            const value = layer.paint.get(property);\n            if (!filterProperties(property)) continue;\n            if (!(value instanceof PossiblyEvaluatedPropertyValue) || !supportsPropertyExpression(value.property.specification)) {\n                continue;\n            }\n            const names = paintAttributeNames(property, layer.type);\n            const expression = value.value;\n            const type = value.property.specification.type;\n            const useIntegerZoom = !!value.property.useIntegerZoom;\n            const isPattern = property === 'line-dasharray' || property.endsWith('pattern');\n            const sourceException = property === 'line-dasharray' && (layer.layout as any).get('line-cap').value.kind !== 'constant';\n\n            if (expression.kind === 'constant' && !sourceException) {\n                this.binders[property] = isPattern ?\n                    new PatternConstantBinder(expression.value, names) :\n                    new ConstantBinder(expression.value, names, type, context);\n                keys.push(`/u_${property}`);\n\n            } else if (expression.kind === 'source' || sourceException || isPattern) {\n                const StructArrayLayout = layoutType(property, type, 'source');\n                this.binders[property] = isPattern ?\n                // @ts-expect-error - TS2345 - Argument of type 'PossiblyEvaluatedValue<any>' is not assignable to parameter of type 'CompositeExpression'.\n                    new PatternCompositeBinder(expression, names, type, StructArrayLayout, layer.id) :\n                // @ts-expect-error - TS2345 - Argument of type 'PossiblyEvaluatedValue<any>' is not assignable to parameter of type 'SourceExpression'.\n                    new SourceExpressionBinder(expression, names, type, StructArrayLayout);\n\n                keys.push(`/a_${property}`);\n\n            } else {\n                const StructArrayLayout = layoutType(property, type, 'composite');\n                // @ts-expect-error - TS2345 - Argument of type 'CompositeExpression | { kind: \"constant\"; value: any; }' is not assignable to parameter of type 'CompositeExpression'.\n                this.binders[property] = new CompositeExpressionBinder(expression, names, type, useIntegerZoom, context, StructArrayLayout);\n                keys.push(`/z_${property}`);\n            }\n        }\n\n        this.cacheKey = keys.sort().join('');\n    }\n\n    getMaxValue(property: string): number {\n        const binder = this.binders[property];\n        return binder instanceof SourceExpressionBinder || binder instanceof CompositeExpressionBinder ? binder.maxValue : 0;\n    }\n\n    populatePaintArrays(newLength: number, feature: Feature, imagePositions: SpritePositions, availableImages: Array<string>, canonical?: CanonicalTileID, brightness?: number | null, formattedSection?: FormattedSection) {\n        for (const property in this.binders) {\n            const binder = this.binders[property];\n            binder.context = this.context;\n            if (binder instanceof SourceExpressionBinder || binder instanceof CompositeExpressionBinder || binder instanceof PatternCompositeBinder)\n                (binder as AttributeBinder).populatePaintArray(newLength, feature, imagePositions, availableImages, canonical, brightness, formattedSection);\n        }\n    }\n    setConstantPatternPositions(posTo: SpritePosition) {\n        for (const property in this.binders) {\n            const binder = this.binders[property];\n            if (binder instanceof PatternConstantBinder)\n                binder.setConstantPatternPositions(posTo);\n        }\n    }\n\n    updatePaintArrays(\n        featureStates: FeatureStates,\n        featureMap: FeaturePositionMap,\n        featureMapWithoutIds: FeaturePositionMap,\n        vtLayer: VectorTileLayer,\n        layer: TypedStyleLayer,\n        availableImages: Array<string>,\n        imagePositions: SpritePositions,\n        brightness: number,\n    ): boolean {\n        let dirty: boolean = false;\n        const keys = Object.keys(featureStates);\n        const featureStateUpdate = (keys.length !== 0);\n        const ids = featureStateUpdate ? keys : featureMap.uniqueIds;\n        this.context.lut = layer.lut;\n        for (const property in this.binders) {\n            const binder = this.binders[property];\n            binder.context = this.context;\n            if ((binder instanceof SourceExpressionBinder || binder instanceof CompositeExpressionBinder ||\n                 binder instanceof PatternCompositeBinder) && ((binder as any).expression.isStateDependent === true || (binder as any).expression.isLightConstant === false)) {\n                //AHM: Remove after https://github.com/mapbox/mapbox-gl-js/issues/6255\n                // @ts-expect-error - TS2349 - This expression is not callable.\n                const value = layer.paint.get(property);\n\n                (binder as any).expression = value.value;\n                for (const id of ids) {\n                    const state = featureStates[id.toString()];\n                    featureMap.eachPosition(id, (index, start, end) => {\n                        const feature = vtLayer.feature(index);\n                        // @ts-expect-error - TS2345 - Argument of type 'VectorTileFeature' is not assignable to parameter of type 'Feature'.\n                        (binder as AttributeBinder).updatePaintArray(start, end, feature, state, availableImages, imagePositions, brightness);\n                    });\n                }\n                if (!featureStateUpdate) {\n                    for (const id of featureMapWithoutIds.uniqueIds) {\n                        const state = featureStates[id.toString()];\n                        featureMapWithoutIds.eachPosition(id, (index, start, end) => {\n                            const feature = vtLayer.feature(index);\n                            // @ts-expect-error - TS2345 - Argument of type 'VectorTileFeature' is not assignable to parameter of type 'Feature'.\n                            (binder as AttributeBinder).updatePaintArray(start, end, feature, state, availableImages, imagePositions, brightness);\n                        });\n                    }\n                }\n                dirty = true;\n            }\n        }\n        return dirty;\n    }\n\n    defines(): Array<string> {\n        const result = [];\n        for (const property in this.binders) {\n            const binder = this.binders[property];\n            if (binder instanceof ConstantBinder || binder instanceof PatternConstantBinder) {\n                result.push(...binder.uniformNames.map(name => `#define HAS_UNIFORM_${name}`));\n            }\n        }\n        return result;\n    }\n\n    getBinderAttributes(): Array<string> {\n        const result = [];\n        for (const property in this.binders) {\n            const binder = this.binders[property];\n            if (binder instanceof SourceExpressionBinder || binder instanceof CompositeExpressionBinder || binder instanceof PatternCompositeBinder) {\n                for (let i = 0; i < binder.paintVertexAttributes.length; i++) {\n                    result.push(binder.paintVertexAttributes[i].name);\n                }\n            }\n        }\n        return result;\n    }\n\n    getBinderUniforms(): Array<string> {\n        const uniforms = [];\n        for (const property in this.binders) {\n            const binder = this.binders[property];\n            if (binder instanceof ConstantBinder || binder instanceof PatternConstantBinder || binder instanceof CompositeExpressionBinder) {\n                for (const uniformName of binder.uniformNames) {\n                    uniforms.push(uniformName);\n                }\n            }\n        }\n        return uniforms;\n    }\n\n    getPaintVertexBuffers(): Array<VertexBuffer> {\n        return this._buffers;\n    }\n\n    getUniforms(context: Context): Array<BinderUniform> {\n        const uniforms = [];\n        for (const property in this.binders) {\n            const binder = this.binders[property];\n            if (binder instanceof ConstantBinder || binder instanceof PatternConstantBinder || binder instanceof CompositeExpressionBinder) {\n                for (const name of binder.uniformNames) {\n                    uniforms.push({name, property, binding: binder.getBinding(context, name)});\n                }\n            }\n        }\n        return uniforms;\n    }\n\n    setUniforms<Properties extends any>(\n        program: WebGLProgram,\n        context: Context,\n        binderUniforms: Array<BinderUniform>,\n        properties: PossiblyEvaluated<Properties>,\n        globals: GlobalProperties,\n    ) {\n        // Uniform state bindings are owned by the Program, but we set them\n        // from within the ProgramConfiguration's binder members.\n        for (const {name, property, binding} of binderUniforms) {\n            // @ts-expect-error - TS2345 - Argument of type 'string' is not assignable to parameter of type 'keyof Properties'.\n            (this.binders[property] as any).setUniform(program, binding, globals, properties.get(property), name);\n        }\n    }\n\n    updatePaintBuffers() {\n        this._buffers = [];\n\n        for (const property in this.binders) {\n            const binder = this.binders[property];\n            if ((\n                binder instanceof SourceExpressionBinder ||\n                binder instanceof CompositeExpressionBinder ||\n                binder instanceof PatternCompositeBinder) && binder.paintVertexBuffer) {\n                this._buffers.push(binder.paintVertexBuffer);\n            }\n        }\n    }\n\n    upload(context: Context) {\n        for (const property in this.binders) {\n            const binder = this.binders[property];\n            if (binder instanceof SourceExpressionBinder || binder instanceof CompositeExpressionBinder || binder instanceof PatternCompositeBinder)\n                binder.upload(context);\n        }\n        this.updatePaintBuffers();\n    }\n\n    destroy() {\n        for (const property in this.binders) {\n            const binder = this.binders[property];\n            if (binder instanceof SourceExpressionBinder || binder instanceof CompositeExpressionBinder || binder instanceof PatternCompositeBinder)\n                binder.destroy();\n        }\n    }\n}\n\nexport class ProgramConfigurationSet<Layer extends TypedStyleLayer> {\n    programConfigurations: {\n        [_: string]: ProgramConfiguration;\n    };\n    needsUpload: boolean;\n    _featureMap: FeaturePositionMap;\n    _featureMapWithoutIds: FeaturePositionMap;\n    _bufferOffset: number;\n    _idlessCounter: number;\n\n    constructor(layers: ReadonlyArray<Layer>, context: ProgramConfigurationContext, filterProperties: (_: string) => boolean = () => true) {\n        this.programConfigurations = {};\n        for (const layer of layers) {\n            this.programConfigurations[layer.id] = new ProgramConfiguration(layer, context, filterProperties);\n        }\n        this.needsUpload = false;\n        this._featureMap = new FeaturePositionMap();\n        this._featureMapWithoutIds = new FeaturePositionMap();\n        this._bufferOffset = 0;\n        this._idlessCounter = 0;\n    }\n\n    populatePaintArrays(length: number, feature: Feature, index: number, imagePositions: SpritePositions, availableImages: Array<string>, canonical: CanonicalTileID, brightness?: number | null, formattedSection?: FormattedSection) {\n        for (const key in this.programConfigurations) {\n            this.programConfigurations[key].populatePaintArrays(length, feature, imagePositions, availableImages, canonical, brightness, formattedSection);\n        }\n\n        if (feature.id !== undefined) {\n            this._featureMap.add(feature.id, index, this._bufferOffset, length);\n        } else {\n            this._featureMapWithoutIds.add(this._idlessCounter, index, this._bufferOffset, length);\n            this._idlessCounter += 1;\n        }\n        this._bufferOffset = length;\n\n        this.needsUpload = true;\n    }\n\n    updatePaintArrays(featureStates: FeatureStates, vtLayer: VectorTileLayer, layers: ReadonlyArray<TypedStyleLayer>, availableImages: Array<string>, imagePositions: SpritePositions, brightness?: number | null) {\n        for (const layer of layers) {\n            this.needsUpload = this.programConfigurations[layer.id].updatePaintArrays(featureStates, this._featureMap, this._featureMapWithoutIds, vtLayer, layer, availableImages, imagePositions, brightness || 0) || this.needsUpload;\n        }\n    }\n\n    get(layerId: string): ProgramConfiguration {\n        return this.programConfigurations[layerId];\n    }\n\n    upload(context: Context) {\n        if (!this.needsUpload) return;\n        for (const layerId in this.programConfigurations) {\n            this.programConfigurations[layerId].upload(context);\n        }\n        this.needsUpload = false;\n    }\n\n    destroy() {\n        for (const layerId in this.programConfigurations) {\n            this.programConfigurations[layerId].destroy();\n        }\n    }\n}\n\nconst attributeNameExceptions = {\n    'text-opacity': ['opacity'],\n    'icon-opacity': ['opacity'],\n    'text-occlusion-opacity': ['occlusion_opacity'],\n    'icon-occlusion-opacity': ['occlusion_opacity'],\n    'text-color': ['fill_color'],\n    'icon-color': ['fill_color'],\n    'text-emissive-strength': ['emissive_strength'],\n    'icon-emissive-strength': ['emissive_strength'],\n    'text-halo-color': ['halo_color'],\n    'icon-halo-color': ['halo_color'],\n    'text-halo-blur': ['halo_blur'],\n    'icon-halo-blur': ['halo_blur'],\n    'text-halo-width': ['halo_width'],\n    'icon-halo-width': ['halo_width'],\n    'line-gap-width': ['gapwidth'],\n    'line-pattern': ['pattern', 'pixel_ratio'],\n    'fill-pattern': ['pattern', 'pixel_ratio'],\n    'fill-extrusion-pattern': ['pattern', 'pixel_ratio'],\n    'line-dasharray': ['dash']\n};\n\nfunction paintAttributeNames(property: string, type: string) {\n    return attributeNameExceptions[property] || [property.replace(`${type}-`, '').replace(/-/g, '_')];\n}\n\nconst propertyExceptions = {\n    'line-pattern': {\n        'source': PatternLayoutArray,\n        'composite': PatternLayoutArray\n    },\n    'fill-pattern': {\n        'source': PatternLayoutArray,\n        'composite': PatternLayoutArray\n    },\n    'fill-extrusion-pattern':{\n        'source': PatternLayoutArray,\n        'composite': PatternLayoutArray\n    },\n    'line-dasharray': { // temporary layout\n        'source': DashLayoutArray,\n        'composite': DashLayoutArray\n    }\n};\n\nconst defaultLayouts = {\n    'color': {\n        'source': StructArrayLayout2f8,\n        'composite': StructArrayLayout4f16\n    },\n    'number': {\n        'source': StructArrayLayout1f4,\n        'composite': StructArrayLayout2f8\n    }\n};\n\ntype LayoutType = 'array' | 'boolean' | 'color' | 'enum' | 'number' | 'resolvedImage' | 'string';\n\nfunction layoutType(property: string, type: LayoutType, binderType: string): Class<StructArray> {\n    const layoutException = propertyExceptions[property];\n    return (layoutException && layoutException[binderType]) || defaultLayouts[type][binderType];\n}\n\nregister(ConstantBinder, 'ConstantBinder');\nregister(PatternConstantBinder, 'PatternConstantBinder');\nregister(SourceExpressionBinder, 'SourceExpressionBinder');\nregister(PatternCompositeBinder, 'PatternCompositeBinder');\nregister(CompositeExpressionBinder, 'CompositeExpressionBinder');\nregister(ProgramConfiguration, 'ProgramConfiguration', {omit: ['_buffers']});\nregister(ProgramConfigurationSet, 'ProgramConfigurationSet');\n","import EXTENT from '../../style-spec/data/extent';\n\nexport const GLOBE_RADIUS = EXTENT / Math.PI / 2.0;\n\nexport const GLOBE_ZOOM_THRESHOLD_MIN = 5;\nexport const GLOBE_ZOOM_THRESHOLD_MAX = 6;\n\n// At low zoom levels the globe gets rendered so that the scale at this\n// latitude matches it's scale in a mercator map. The choice of latitude is\n// a bit arbitrary. Different choices will match mercator more closely in different\n// views. 45 is a good enough choice because:\n// - it's half way from the pole to the equator\n// - matches most middle latitudes reasonably well\n// - biases towards increasing size rather than decreasing\n// - makes the globe slightly larger at very low zoom levels, where it already\n//   covers less pixels than mercator (due to the curved surface)\n//\n//   Changing this value will change how large a globe is rendered and could affect\n//   end users. This should only be done of the tradeoffs between change and improvement\n//   are carefully considered.\nexport const GLOBE_SCALE_MATCH_LATITUDE = 45;\n\nconst GLOBE_NORMALIZATION_BIT_RANGE = 15;\nexport const GLOBE_NORMALIZATION_MASK = (1 << (GLOBE_NORMALIZATION_BIT_RANGE - 1)) - 1;\nexport const GLOBE_VERTEX_GRID_SIZE = 64;\nexport const GLOBE_LATITUDINAL_GRID_LOD_TABLE = [GLOBE_VERTEX_GRID_SIZE, GLOBE_VERTEX_GRID_SIZE / 2, GLOBE_VERTEX_GRID_SIZE / 4] as const;\nexport const TILE_SIZE = 512;\n\nexport const GLOBE_MIN = -GLOBE_RADIUS;\nexport const GLOBE_MAX = GLOBE_RADIUS;\n","import assert from 'assert';\nimport {wrap, degToRad, radToDeg} from '../util/util';\nimport {GLOBE_RADIUS} from '../geo/projection/globe_constants';\n\nexport function csLatLngToECEF(cosLat: number, sinLat: number, lng: number, radius: number = GLOBE_RADIUS): [number, number, number] {\n    lng = degToRad(lng);\n\n    // Convert lat & lng to spherical representation. Use zoom=0 as a reference\n    const sx = cosLat * Math.sin(lng) * radius;\n    const sy = -sinLat * radius;\n    const sz = cosLat * Math.cos(lng) * radius;\n\n    return [sx, sy, sz];\n}\n\nexport function ecefToLatLng([x, y, z]: [any, any, any]): LngLat {\n    const radius = Math.hypot(x, y, z);\n    const lng = Math.atan2(x, z);\n    const lat = Math.PI * 0.5 - Math.acos(-y / radius);\n\n    return new LngLat(radToDeg(lng), radToDeg(lat));\n}\n\nexport function latLngToECEF(lat: number, lng: number, radius?: number): [number, number, number] {\n    assert(lat <= 90 && lat >= -90, 'Lattitude must be between -90 and 90');\n    return csLatLngToECEF(Math.cos(degToRad(lat)), Math.sin(degToRad(lat)), lng, radius);\n}\n\n/*\n* Approximate radius of the earth in meters.\n* Uses the WGS-84 approximation. The radius at the equator is ~6378137 and at the poles is ~6356752. https://en.wikipedia.org/wiki/World_Geodetic_System#WGS84\n* 6371008.8 is one published \"average radius\" see https://en.wikipedia.org/wiki/Earth_radius#Mean_radius, or ftp://athena.fsv.cvut.cz/ZFG/grs80-Moritz.pdf p.4\n*/\nexport const earthRadius = 6371008.8;\n\n/*\n * The average circumference of the earth in meters.\n */\nexport const earthCircumference = 2 * Math.PI * earthRadius;\n\n/**\n * A `LngLat` object represents a given longitude and latitude coordinate, measured in degrees.\n * These coordinates use longitude, latitude coordinate order (as opposed to latitude, longitude)\n * to match the [GeoJSON specification](https://datatracker.ietf.org/doc/html/rfc7946#section-4),\n * which is equivalent to the OGC:CRS84 coordinate reference system.\n *\n * Note that any Mapbox GL method that accepts a `LngLat` object as an argument or option\n * can also accept an `Array` of two numbers and will perform an implicit conversion.\n * This flexible type is documented as {@link LngLatLike}.\n *\n * @param {number} lng Longitude, measured in degrees.\n * @param {number} lat Latitude, measured in degrees.\n * @example\n * const ll = new mapboxgl.LngLat(-123.9749, 40.7736);\n * console.log(ll.lng); // = -123.9749\n * @see [Example: Get coordinates of the mouse pointer](https://www.mapbox.com/mapbox-gl-js/example/mouse-position/)\n * @see [Example: Display a popup](https://www.mapbox.com/mapbox-gl-js/example/popup/)\n * @see [Example: Highlight features within a bounding box](https://www.mapbox.com/mapbox-gl-js/example/using-box-queryrenderedfeatures/)\n * @see [Example: Create a timeline animation](https://www.mapbox.com/mapbox-gl-js/example/timeline-animation/)\n */\nclass LngLat {\n    lng: number;\n    lat: number;\n\n    constructor(lng: number, lat: number) {\n        if (isNaN(lng) || isNaN(lat)) {\n            throw new Error(`Invalid LngLat object: (${lng}, ${lat})`);\n        }\n        this.lng = +lng;\n        this.lat = +lat;\n        if (this.lat > 90 || this.lat < -90) {\n            throw new Error('Invalid LngLat latitude value: must be between -90 and 90');\n        }\n    }\n\n    /**\n     * Returns a new `LngLat` object whose longitude is wrapped to the range (-180, 180).\n     *\n     * @returns {LngLat} The wrapped `LngLat` object.\n     * @example\n     * const ll = new mapboxgl.LngLat(286.0251, 40.7736);\n     * const wrapped = ll.wrap();\n     * console.log(wrapped.lng); // = -73.9749\n     */\n    wrap(): LngLat {\n        return new LngLat(wrap(this.lng, -180, 180), this.lat);\n    }\n\n    /**\n     * Returns the coordinates represented as an array of two numbers.\n     *\n     * @returns {Array<number>} The coordinates represeted as an array of longitude and latitude.\n     * @example\n     * const ll = new mapboxgl.LngLat(-73.9749, 40.7736);\n     * ll.toArray(); // = [-73.9749, 40.7736]\n     */\n    toArray(): [number, number] {\n        return [this.lng, this.lat];\n    }\n\n    /**\n     * Returns the coordinates represent as a string.\n     *\n     * @returns {string} The coordinates represented as a string of the format `'LngLat(lng, lat)'`.\n     * @example\n     * const ll = new mapboxgl.LngLat(-73.9749, 40.7736);\n     * ll.toString(); // = \"LngLat(-73.9749, 40.7736)\"\n     */\n    toString(): string {\n        return `LngLat(${this.lng}, ${this.lat})`;\n    }\n\n    /**\n     * Returns the approximate distance between a pair of coordinates in meters.\n     * Uses the Haversine Formula (from R.W. Sinnott, \"Virtues of the Haversine\", Sky and Telescope, vol. 68, no. 2, 1984, p. 159).\n     *\n     * @param {LngLat} lngLat Coordinates to compute the distance to.\n     * @returns {number} Distance in meters between the two coordinates.\n     * @example\n     * const newYork = new mapboxgl.LngLat(-74.0060, 40.7128);\n     * const losAngeles = new mapboxgl.LngLat(-118.2437, 34.0522);\n     * newYork.distanceTo(losAngeles); // = 3935751.690893987, \"true distance\" using a non-spherical approximation is ~3966km\n     */\n    distanceTo(lngLat: LngLat): number {\n        const rad = Math.PI / 180;\n        const lat1 = this.lat * rad;\n        const lat2 = lngLat.lat * rad;\n        const a = Math.sin(lat1) * Math.sin(lat2) + Math.cos(lat1) * Math.cos(lat2) * Math.cos((lngLat.lng - this.lng) * rad);\n\n        const maxMeters = earthRadius * Math.acos(Math.min(a, 1));\n        return maxMeters;\n    }\n\n    /**\n     * Returns a `LngLatBounds` from the coordinates extended by a given `radius`. The returned `LngLatBounds` completely contains the `radius`.\n     *\n     * @param {number} [radius=0] Distance in meters from the coordinates to extend the bounds.\n     * @returns {LngLatBounds} A new `LngLatBounds` object representing the coordinates extended by the `radius`.\n     * @example\n     * const ll = new mapboxgl.LngLat(-73.9749, 40.7736);\n     * ll.toBounds(100).toArray(); // = [[-73.97501862141328, 40.77351016847229], [-73.97478137858673, 40.77368983152771]]\n     */\n    toBounds(radius: number = 0): LngLatBounds {\n        const earthCircumferenceInMetersAtEquator = 40075017;\n        const latAccuracy = 360 * radius / earthCircumferenceInMetersAtEquator,\n            lngAccuracy = latAccuracy / Math.cos((Math.PI / 180) * this.lat);\n\n        return new LngLatBounds({lng: this.lng - lngAccuracy, lat: this.lat - latAccuracy},\n            {lng: this.lng + lngAccuracy, lat: this.lat + latAccuracy});\n    }\n\n    toEcef(altitude: number): [number, number, number] {\n        const altInEcef = altitude * GLOBE_RADIUS / earthRadius;\n        const radius = GLOBE_RADIUS + altInEcef;\n        return latLngToECEF(this.lat, this.lng, radius) as any;\n    }\n\n    /**\n     * Converts an array of two numbers or an object with `lng` and `lat` or `lon` and `lat` properties\n     * to a `LngLat` object.\n     *\n     * If a `LngLat` object is passed in,