  const candidateTriangles = [];\n    region.footprint.grid.queryPoint(p, candidateTriangles);\n\n    // finally check if the point is in any of the triangles.\n    const fpIndices: Array<number> = region.footprint.indices;\n    const fpVertices: Array<Point> = region.footprint.vertices;\n    for (let j = 0; j < candidateTriangles.length; j++) {\n        const triIdx = candidateTriangles[j];\n        const triangle = [\n            fpVertices[fpIndices[triIdx * 3 + 0]],\n            fpVertices[fpIndices[triIdx * 3 + 1]],\n            fpVertices[fpIndices[triIdx * 3 + 2]]\n        ];\n\n        if (polygonContainsPoint(triangle, p)) {\n            return true;\n        }\n    }\n\n    return false;\n}\n\nexport type {TileFootprint, FootprintSource, Region};\nexport {ReplacementSource, regionsEquals, footprintTrianglesIntersect, transformPointToTile, pointInFootprint};\n","import {vec3} from 'gl-matrix';\nimport {number as interpolate} from '../style-spec/util/interpolate';\nimport {clamp} from '../util/util';\n\nimport type DEMData from './dem_data';\n\nclass MipLevel {\n    size: number;\n    minimums: Array<number>;\n    maximums: Array<number>;\n    leaves: Array<number>;\n\n    constructor(size_: number) {\n        this.size = size_;\n        this.minimums = [];\n        this.maximums = [];\n        this.leaves = [];\n    }\n\n    getElevation(x: number, y: number): {\n        min: number;\n        max: number;\n    } {\n        const idx = this.toIdx(x, y);\n        return {\n            min: this.minimums[idx],\n            max: this.maximums[idx]\n        };\n    }\n\n    isLeaf(x: number, y: number): number {\n        return this.leaves[this.toIdx(x, y)];\n    }\n\n    toIdx(x: number, y: number): number {\n        return y * this.size + x;\n    }\n}\n\nfunction aabbRayIntersect(min: vec3, max: vec3, pos: vec3, dir: vec3): number | null | undefined {\n    let tMin = 0;\n    let tMax = Number.MAX_VALUE;\n\n    const epsilon = 1e-15;\n\n    for (let i = 0; i < 3; i++) {\n        if (Math.abs(dir[i]) < epsilon) {\n            // Parallel ray\n            if (pos[i] < min[i] || pos[i] > max[i])\n                return null;\n        } else {\n            const ood = 1.0 / dir[i];\n            let t1 = (min[i] - pos[i]) * ood;\n            let t2 = (max[i] - pos[i]) * ood;\n            if (t1 > t2) {\n                const temp = t1;\n                t1 = t2;\n                t2 = temp;\n            }\n            if (t1 > tMin)\n                tMin = t1;\n            if (t2 < tMax)\n                tMax = t2;\n            if (tMin > tMax)\n                return null;\n        }\n    }\n\n    return tMin;\n}\n\nfunction triangleRayIntersect(\n    ax: number,\n    ay: number,\n    az: number,\n    bx: number,\n    by: number,\n    bz: number,\n    cx: number,\n    cy: number,\n    cz: number,\n    pos: vec3,\n    dir: vec3,\n): number | null | undefined {\n    // Compute barycentric coordinates u and v to find the intersection\n    const abX = bx - ax;\n    const abY = by - ay;\n    const abZ = bz - az;\n\n    const acX = cx - ax;\n    const acY = cy - ay;\n    const acZ = cz - az;\n\n    // pvec = cross(dir, a), det = dot(ab, pvec)\n    const pvecX = dir[1] * acZ - dir[2] * acY;\n    const pvecY = dir[2] * acX - dir[0] * acZ;\n    const pvecZ = dir[0] * acY - dir[1] * acX;\n    const det = abX * pvecX + abY * pvecY + abZ * pvecZ;\n\n    if (Math.abs(det) < 1e-15)\n        return null;\n\n    const invDet = 1.0 / det;\n    const tvecX = pos[0] - ax;\n    const tvecY = pos[1] - ay;\n    const tvecZ = pos[2] - az;\n    const u = (tvecX * pvecX + tvecY * pvecY + tvecZ * pvecZ) * invDet;\n\n    if (u < 0.0 || u > 1.0)\n        return null;\n\n    // qvec = cross(tvec, ab)\n    const qvecX = tvecY * abZ - tvecZ * abY;\n    const qvecY = tvecZ * abX - tvecX * abZ;\n    const qvecZ = tvecX * abY - tvecY * abX;\n    const v = (dir[0] * qvecX + dir[1] * qvecY + dir[2] * qvecZ) * invDet;\n\n    if (v < 0.0 || u + v > 1.0)\n        re