ete removal of state at that scope\n * @private\n*/\nclass SourceFeatureState {\n    state: LayerFeatureStates;\n    stateChanges: LayerFeatureStates;\n    deletedStates: LayerFeatureStates;\n\n    constructor() {\n        this.state = {};\n        this.stateChanges = {};\n        this.deletedStates = {};\n    }\n\n    updateState(sourceLayer: string, featureId: number | string, newState: FeatureState) {\n        const feature = String(featureId);\n        this.stateChanges[sourceLayer] = this.stateChanges[sourceLayer] || {};\n        this.stateChanges[sourceLayer][feature] = this.stateChanges[sourceLayer][feature] || {};\n        extend(this.stateChanges[sourceLayer][feature], newState);\n\n        if (this.deletedStates[sourceLayer] === null) {\n            this.deletedStates[sourceLayer] = {};\n            for (const ft in this.state[sourceLayer]) {\n                if (ft !== feature) this.deletedStates[sourceLayer][ft] = null;\n            }\n        } else {\n            const featureDeletionQueued = this.deletedStates[sourceLayer] && this.deletedStates[sourceLayer][feature] === null;\n            if (featureDeletionQueued) {\n                this.deletedStates[sourceLayer][feature] = {};\n                for (const prop in this.state[sourceLayer][feature]) {\n                    if (!newState[prop]) this.deletedStates[sourceLayer][feature][prop] = null;\n                }\n            } else {\n                for (const key in newState) {\n                    const deletionInQueue = this.deletedStates[sourceLayer] && this.deletedStates[sourceLayer][feature] && this.deletedStates[sourceLayer][feature][key] === null;\n                    if (deletionInQueue) delete this.deletedStates[sourceLayer][feature][key];\n                }\n            }\n        }\n    }\n\n    removeFeatureState(sourceLayer: string, featureId?: number | string, key?: string) {\n        const sourceLayerDeleted = this.deletedStates[sourceLayer] === null;\n        if (sourceLayerDeleted) return;\n\n        const feature = String(featureId);\n\n        this.deletedStates[sourceLayer] = this.deletedStates[sourceLayer] || {};\n\n        if (key && featureId !== undefined) {\n            if (this.deletedStates[sourceLayer][feature] !== null) {\n                this.deletedStates[sourceLayer][feature] = this.deletedStates[sourceLayer][feature] || {};\n                this.deletedStates[sourceLayer][feature][key] = null;\n            }\n        } else if (featureId !== undefined) {\n            const updateInQueue = this.stateChanges[sourceLayer] && this.stateChanges[sourceLayer][feature];\n            if (updateInQueue) {\n                this.deletedStates[sourceLayer][feature] = {};\n                for (key in this.stateChanges[sourceLayer][feature]) this.deletedStates[sourceLayer][feature][key] = null;\n\n            } else {\n                this.deletedStates[sourceLayer][feature] = null;\n            }\n        } else {\n            this.deletedStates[sourceLayer] = null;\n        }\n    }\n\n    getState(sourceLayer: string, featureId: number | string): FeatureState {\n        const feature = String(featureId);\n        const base = this.state[sourceLayer] || {};\n        const changes = this.stateChanges[sourceLayer] || {};\n\n        const reconciledState = extend({}, base[feature], changes[feature]);\n\n        //return empty object if the whole source layer is awaiting deletion\n        if (this.deletedStates[sourceLayer] === null) return {};\n        else if (this.deletedStates[sourceLayer]) {\n            const featureDeletions = this.deletedStates[sourceLayer][featureId];\n            if (featureDeletions === null) return {};\n            for (const prop in featureDeletions) delete reconciledState[prop];\n        }\n        return reconciledState;\n    }\n\n    initializeTileState(tile: Tile, painter?: Painter | null) {\n        tile.setFeatureState(this.state, painter);\n    }\n\n    coalesceChanges(tiles: Record<string | number, Tile>, painter: Painter) {\n        //track changes with full state objects, but only for features that got modified\n        const featuresChanged: LayerFeatureStates = {};\n\n        for (const sourceLayer in this.stateChanges) {\n            this.state[sourceLayer] = this.state[sourceLayer] || {};\n            const layerStates: Record<string, FeatureState> = {};\n            for (const feature in this.stateChanges[sourceLayer]) {\n                if (!this.state[sourceLayer][feature]) this.state[sourceLayer][feature] = {};\n                extend(this.state[sourceLayer][feature], this.stateChanges[sourceLayer][feature]);\n                layerStates[feature] = this.state[sourceLayer][feature];\n            }\n            featuresChanged[sourceLayer] = layerStates;\n        }\n\n        for (const sourceLayer in this.deletedStates) {\n            this.state[sourceLayer] = this.state[sourceLayer] || {};\n            const layerStates: Record<string, FeatureState> = {};\n\n            if (this.deletedStates[sourceLayer] === null) {\n                for (const ft in this.state[sourceLayer]) {\n                    layerStates[ft] = {};\n                    this.state[sourceLayer][ft] = {};\n                }\n            } else {\n                for (const feature in this.deletedStates[sourceLayer]) {\n                    const deleteWholeFeatureState = this.deletedStates[sourceLayer][feature] === null;\n                    if (deleteWholeFeatureState) this.state[sourceLayer][feature] = {};\n                    else if (this.state[sourceLayer][feature]) {\n                        for (const key of Object.keys(this.deletedStates[sourceLayer][feature])) {\n                            delete this.state[sourceLayer][feature][key];\n                        }\n                    }\n                    layerStates[feature] = this.state[sourceLayer][feature];\n                }\n            }\n\n            featuresChanged[sourceLayer] = featuresChanged[sourceLayer] || {};\n            extend(featuresChanged[sourceLayer], layerStates);\n        }\n\n        this.stateChanges = {};\n        this.deletedStates = {};\n\n        if (Object.keys(featuresChanged).length === 0) return;\n\n        for (const id in tiles) {\n            const tile = tiles[id];\n            tile.setFeatureState(featuresChanged, painter);\n        }\n    }\n}\n\nexport default SourceFeatureState;\n","import Point from '@mapbox/point-geometry';\n\nimport loadGeometry from './load_geometry';\nimport toEvaluationFeature from './evaluation_feature';\nimport EXTENT from '../style-spec/data/extent';\nimport featureFilter from '../style-spec/feature_filter/index';\nimport Grid from 'grid-index';\nimport DictionaryCoder from '../util/dictionary_coder';\nimport {VectorTile} from '@mapbox/vector-tile';\nimport Protobuf from 'pbf';\nimport Feature from '../util/vectortile_to_geojson';\nimport {arraysIntersect, mapObject, extend} from '../util/util';\nimport {OverscaledTileID} from '../source/tile_id';\nimport {register} from '../util/web_worker_transfer';\nimport EvaluationParameters from '../style/evaluation_parameters';\nimport SourceFeatureState from '../source/source_state';\nimport {polygonIntersectsBox} from '../util/intersection_tests';\nimport {PossiblyEvaluated} from '../style/properties';\nimport {FeatureIndexArray} from './array_types';\nimport {DEMSampler} from '../terrain/elevation';\n\nimport type StyleLayer from '../style/style_layer';\nimport type {QueryResult} from '../source/query_features';\nimport type {FeatureStates} from '../source/source_state';\nimport type {FeatureFilter} from '../style-spec/feature_filter/index';\nimport type Transform from '../geo/transform';\nimport type {GeoJSONFeature} from '../util/vectortile_to_geojson';\nimport type {FilterSpecification, PromoteIdSpecification} from '../style-spec/types';\nimport type {TilespaceQueryGeometry} from '../style/query_geometry';\nimport type {FeatureIndex as FeatureIndexStruct} from './array_types';\nimport type {TileTransform} from '../geo/projection/tile_transform';\nimport type {VectorTileLayer, VectorTileFeature} from '@mapbox/vector-tile';\nimport type {GridIndex} from '../types/grid-index';\n\ntype QueryParameters = {\n    pixelPosMatrix: Float32Array;\n    transform: Transform;\n    tileResult: TilespaceQueryGeometry;\n    tileTransform: TileTransform;\n    params: {\n        filter: FilterSpecification;\n        layers: Array<string>;\n        availableImages: Array<string>;\n    };\n};\n\ntype FeatureIndices = {\n    bucketIndex: number;\n    sourceLayerIndex: number;\n    featureIndex: number;\n    layoutVertexArrayOffset: number;\n} | FeatureIndexStruct;\n\nclass FeatureIndex {\n    tileID: OverscaledTileID;\n    x: number;\n    y: number;\n    z: number;\n    grid: GridIndex;\n    featureIndexArray: FeatureIndexArray;\n    promoteId: PromoteIdSpecification | null | undefined;\n\n    rawTileData: ArrayBuffer;\n    bucketLayerIDs: Array<Array<string>>;\n\n    vtLayers: {\n        [_: string]: VectorTileLayer;\n    };\n    vtFeatures: {\n        [_: string]: VectorTileFeature[];\n    };\n    sourceLayerCoder: DictionaryCoder;\n    is3DTile: boolean; // no vector source layers\n\n    constructor(tileID: OverscaledTileID, promoteId?: PromoteIdSpecification | null) {\n        this.tileID = tileID;\n        this.x = tileID.canonical.x;\n        this.y = tileID.canonical.y;\n        this.z = tileID.canonical.z;\n        this.grid = new Grid(EXTENT, 16, 0);\n        this.featureIndexArray = new FeatureIndexArray();\n        this.promoteId = promoteId;\n        this.is3DTile = false;\n    }\n\n    insert(feature: VectorTileFeature, geometry: Array<Array<Point>>, featureIndex: number, sourceLayerIndex: number, bucketIndex: number, layoutVertexArrayOffset: number = 0, envelopePadding: number = 0) {\n        const key = this.featureIndexArray.length;\n        this.featureIndexArray.emplaceBack(featureIndex, sourceLayerIndex, bucketIndex, layoutVertexArrayOffset);\n\n        const grid = this.grid;\n\n        for (let r = 0; r < geometry.length; r++) {\n            const ring = geometry[r];\n\n            const bbox = [Infinity, Infinity, -Infinity, -Infinity];\n            for (let i = 0; i < ring.length; i++) {\n                const p = ring[i];\n                bbox[0] = Math.min(bbox[0], p.x);\n                bbox[1] = Math.min(bbox[1], p.y);\n                bbox[2] = Math.max(bbox[2], p.x);\n                bbox[3] = Math.max(bbox[3], p.y);\n            }\n\n            if (envelopePadding !== 0) {\n                bbox[0] -= envelopePadding;\n                bbox[1] -= envelopePadding;\n                bbox[2] += envelopePadding;\n                bbox[3] += envelopePadding;\n            }\n\n            if (bbox[0] < EXTENT &&\n                bbox[1] < EXTENT &&\n                bbox[2] >= 0 &&\n                bbox[3] >= 0) {\n                grid.insert(key, bbox[0], bbox[1], bbox[2], bbox[3]);\n            }\n        }\n    }\n\n    loadVTLayers(): {\n        [_: string]: VectorTileLayer;\n        } {\n        if (!this.vtLayers) {\n            this.vtLayers = new VectorTile(new Protobuf(this.rawTileData)).layers;\n            this.sourceLayerCoder = new DictionaryCoder(this.vtLayers ? Object.keys(this.vtLayers).sort() : ['_geojsonTileLayer']);\n            this.vtFeatures = {};\n            for (const layer in this.vtLayers) {\n                this.vtFeatures[layer] = [];\n            }\n        }\n        return this.vtLayers;\n    }\n\n    // Finds non-symbol features in this tile at a particular position.\n    query(\n        args: QueryParameters,\n        styleLayers: {\n            [_: string]: StyleLayer;\n        },\n        serializedLayers: {\n            [_: string]: any;\n        },\n        sourceFeatureState: SourceFeatureState,\n    ): QueryResult {\n        this.loadVTLayers();\n        const params = args.params || {},\n            // @ts-expect-error - TS2339 - Property 'filter' does not exist on type '{}'.\n            filter = featureFilter(params.filter);\n        const tilespaceGeometry = args.tileResult;\n        const transform = args.transform;\n\n        const bounds = tilespaceGeometry.bufferedTilespaceBounds;\n        const queryPredicate = (bx1: number, by1: number, bx2: number, by2: number) => {\n            return polygonIntersectsBox(tilespaceGeometry.bufferedTilespaceGeometry, bx1, by1, bx2, by2);\n        };\n        const matching = this.grid.query(bounds.min.x, bounds.min.y, bounds.max.x, bounds.max.y, queryPredicate);\n        matching.sort(topDownFeatureComparator);\n\n        let elevationHelper = null;\n        if (transform.elevation && matching.length > 0) {\n            elevationHelper = DEMSampler.create(transform.elevation, this.tileID);\n        }\n\n        const result: QueryResult = {};\n        let previousIndex;\n        for (let k = 0; k < matching.length; k++) {\n            const index = matching[k];\n\n            // don't check the same feature more than once\n            if (index === previousIndex) continue;\n            previousIndex = index;\n\n            const match = this.featureIndexArray.get(index);\n            let featureGeometry = null;\n\n            if (this.is3DTile) {\n                // 3D tile is a single bucket tile.\n                const layerID = this.bucketLayerIDs[0][0];\n                const layer = styleLayers[layerID];\n                if (layer.type !== \"model\") continue;\n                const {queryFeature, intersectionZ} = layer.queryIntersectsMatchingFeature(tilespaceGeometry, match.featureIndex, filter, transform);\n                if (queryFeature) {\n                    this.appendToResult(result, layerID, match.featureIndex, queryFeature, intersectionZ);\n                }\n                continue;\n            }\n\n            this.loadMatchingFeature(\n                result,\n                match,\n                filter,\n                // @ts-expect-error - TS2339 - Property 'layers' does not exist on type '{}'.\n                params.layers,\n                // @ts-expect-error - TS2339 - Property 'availableImages' does not exist on type '{}'.\n                params.availableImages,\n                styleLayers,\n                serializedLayers,\n                sourceFeatureState,\n                (feature: VectorTileFeature, styleLayer: StyleLayer, featureState: any, layoutVertexArrayOffset: number = 0) => {\n                    if (!featureGeometry) {\n                        // @ts-expect-error - TS2345 - Argument of type 'VectorTileFeature' is not assignable to parameter of type 'FeatureWithGeometry'.\n                        featureGeometry = loadGeometry(feature, this.tileID.canonical, args.tileTransform);\n                    }\n\n                    return styleLayer.queryIntersectsFeature(tilespaceGeometry, feature, featureState, featureGeometry, this.z, args.transform, args.pixelPosMatrix, elevationHelper, layoutVertexArrayOffset);\n                }\n            );\n        }\n\n        return result;\n    }\n\n    loadMatchingFeature(\n        result: QueryResult,\n        featureIndexData: FeatureIndices,\n        filter: FeatureFilter,\n        filterLayerIDs: Array<string>,\n        availableImages: Array<string>,\n        styleLayers: {\n            [_: string]: StyleLayer;\n        },\n        serializedLayers: {\n            [_: string]: any;\n        },\n        sourceFeatureState?: SourceFeatureState,\n        intersectionTest?: (\n            feature: VectorTileFeature,\n            styleLayer: StyleLayer,\n            featureState: any,\n            layoutVertexArrayOffset: number,\n        ) => boolean | number) {\n\n        const {featureIndex, bucketIndex, sourceLayerIndex, layoutVertexArrayOffset} = featureIndexData;\n        const layerIDs = this.bucketLayerIDs[bucketIndex];\n        if (filterLayerIDs && !arraysIntersect(filterLayerIDs, layerIDs))\n            return;\n\n        const sourceLayerName = this.sourceLayerCoder.decode(sourceLayerIndex);\n        const sourceLayer = this.vtLayers[sourceLayerName];\n        const feature = sourceLayer.feature(featureIndex);\n\n        if (filter.needGeometry) {\n            const evaluationFeature = toEvaluationFeature(feature, true);\n            if (!filter.filter(new EvaluationParameters(this.tileID.overscaledZ), evaluationFeature, this.tileID.canonical)) {\n                return;\n            }\n            // @ts-expect-error - TS2345 - Argument of type 'VectorTileFeature' is not assignable to parameter of type 'Feature'.\n        } else if (!filter.filter(new EvaluationParameters(this.tileID.overscaledZ), feature)) {\n            return;\n        }\n\n        const id = this.getId(feature, sourceLayerName);\n\n        for (let l = 0; l < layerIDs.length; l++) {\n            const layerID = layerIDs[l];\n\n            if (filterLayerIDs && filterLayerIDs.indexOf(layerID) < 0) {\n                continue;\n            }\n\n            const styleLayer = styleLayers[layerID];\n\n            if (!styleLayer) continue;\n\n            let featureState: Record<string, any> = {};\n            if (id !== undefined && sourceFeatureState) {\n                // `feature-state` expression evaluation requires feature state to be available\n                featureState = sourceFeatureState.getState(styleLayer.sourceLayer || '_geojsonTileLayer', id);\n            }\n\n            const intersectionZ = !intersectionTest || intersectionTest(feature, styleLayer, featureState, layoutVertexArrayOffset);\n            if (!intersectionZ) {\n                // Only applied for non-symbol features\n                continue;\n            }\n\n            const geojsonFeature = new Feature(feature, this.z, this.x, this.y, id);\n\n            const serializedLayer = extend({}, serializedLayers[layerID]);\n\n            serializedLayer.paint = evaluateProperties(serializedLayer.paint, styleLayer.paint, feature, featureState, availableImages);\n            serializedLayer.layout = evaluateProperties(serializedLayer.layout, styleLayer.layout, feature, featureState, availableImages);\n\n            geojsonFeature.layer = serializedLayer;\n            this.appendToResult(result, layerID, featureIndex, geojsonFeature, intersectionZ);\n        }\n    }\n\n    appendToResult(result: QueryResult, layerID: string, featureIndex: number, geojsonFeature: GeoJSONFeature, intersectionZ: boolean | number) {\n        let layerResult = result[layerID];\n        if (layerResult === undefined) {\n            layerResult = result[layerID] = [];\n        }\n\n        layerResult.push({featureIndex, feature: geojsonFeature, intersectionZ});\n    }\n\n    // Given a set of symbol indexes that have already been looked up,\n    // return a matching set of GeoJSONFeatures\n    lookupSymbolFeatures(\n        symbolFeatureIndexes: Array<number>,\n        serializedLayers: {\n            [key: string]: StyleLayer;\n        },\n        bucketIndex: number,\n        sourceLayerIndex: number,\n        filterSpec: FilterSpecification,\n        filterLayerIDs: Array<string>,\n        availableImages: Array<string>,\n        styleLayers: {\n            [_: string]: StyleLayer;\n        },\n    ): QueryResult {\n        const result: Record<string, any> = {};\n        this.loadVTLayers();\n\n        const filter = featureFilter(filterSpec);\n\n        for (const symbolFeatureIndex of symbolFeatureIndexes) {\n            this.loadMatchingFeature(\n                result, {\n                    bucketIndex,\n                    sourceLayerIndex,\n                    featureIndex: symbolFeatureIndex,\n                    layoutVertexArrayOffset: 0\n                },\n                filter,\n                filterLayerIDs,\n                availableImages,\n                styleLayers,\n                serializedLayers\n            );\n\n        }\n        return result;\n    }\n\n    loadFeature(featureIndexData: FeatureIndices): VectorTileFeature {\n        const {featureIndex, sourceLayerIndex} = featureIndexData;\n\n        this.loadVTLayers();\n        const sourceLayerName = this.sourceLayerCoder.decode(sourceLayerIndex);\n\n        const featureCache = this.vtFeatures[sourceLayerName];\n        if (featureCache[featureIndex]) {\n            return featureCache[featureIndex];\n        }\n        const sourceLayer = this.vtLayers[sourceLayerName];\n        const feature = sourceLayer.feature(featureIndex);\n        featureCache[featureIndex] = feature;\n\n        return feature;\n    }\n\n    hasLayer(id: string): boolean {\n        for (const layerIDs of this.bucketLayerIDs) {\n            for (const layerID of layerIDs) {\n                if (id === layerID) return true;\n            }\n        }\n\n        return false;\n    }\n\n    getId(feature: VectorTileFeature, sourceLayerId: string): string | number {\n        let id: string | number = feature.id;\n        if (this.promoteId) {\n            const propName = typeof this.promoteId === 'string' ? this.promoteId : this.promoteId[sourceLayerId];\n            if (propName != null)\n                id = feature.properties[propName] as string | number;\n            if (typeof id === 'boolean') id = Number(id);\n        }\n        return id;\n    }\n}\n\nregister(FeatureIndex, 'FeatureIndex', {omit: ['rawTileData', 'sourceLayerCoder']});\n\nexport default FeatureIndex;\n\nfunction evaluateProperties(serializedProperties: unknown, styleLayerProperties: unknown, feature: VectorTileFeature, featureState: FeatureStates, availableImages: Array<string>) {\n    return mapObject(serializedProperties, (property, key) => {\n        const prop = styleLayerProperties instanceof PossiblyEvaluated ? styleLayerProperties.get(key) : null;\n        // @ts-expect-error - TS2339 - Property 'evaluate' does not exist on type 'unknown'. | TS2339 - Property 'evaluate' does not exist on type 'unknown'.\n        return prop && prop.evaluate ? prop.evaluate(feature, featureState, availableImages) : prop;\n    });\n}\n\nfunction topDownFeatureComparator(a: number, b: number) {\n    return b - a;\n}\n","// ONE_EM constant used to go between \"em\" units used in style spec and \"points\" used internally for layout\n\nexport default 24;\n","import {number as interpolate} from '../style-spec/util/interpolate';\nimport Interpolate from '../style-spec/expression/definitions/interpolate';\nimport {clamp} from '../util/util';\nimport EvaluationParameters from '../style/evaluation_parameters';\n\nimport type {PropertyValue, PossiblyEvaluatedPropertyValue} from '../style/properties';\nimport type {InterpolationType} from '../style-spec/expression/definitions/interpolate';\n\nconst SIZE_PACK_FACTOR = 128;\n\nexport {getSizeData, evaluateSizeForFeature, evaluateSizeForZoom, SIZE_PACK_FACTOR};\n\nexport type SizeData = {\n    kind: 'constant';\n    layoutSize: number;\n} | {\n    kind: 'source';\n} | {\n    kind: 'camera';\n    minZoom: number;\n    maxZoom: number;\n    minSize: number;\n    maxSize: number;\n    interpolationType: InterpolationType | null | undefined;\n} | {\n    kind: 'composite';\n    minZoom: number;\n    maxZoom: number;\n    interpolationType: InterpolationType | null | undefined;\n};\n\nexport type InterpolatedSize = {\n    uSize: number;\n    uSizeT: number;\n};\n\n// For {text,icon}-size, get the bucket-level data that will be needed by\n// the painter to set symbol-size-related uniforms\nfunction getSizeData(\n    tileZoom: number,\n    value: PropertyValue<number, PossiblyEvaluatedPropertyValue<number>>,\n): SizeData {\n    const {expression} = value;\n\n    if (expression.kind === 'constant') {\n        const layoutSize = expression.evaluate(new EvaluationParameters(tileZoom + 1));\n        return {kind: 'constant', layoutSize};\n\n    } else if (expression.kind === 'source') {\n        return {kind: 'source'};\n\n    } else {\n        const {zoomStops, interpolationType} = expression;\n\n        // calculate covering zoom stops for zoom-dependent values\n        let lower = 0;\n        while (lower < zoomStops.length && zoomStops[lower] <= tileZoom) lower++;\n        lower = Math.max(0, lower - 1);\n        let upper = lower;\n        while (upper < zoomStops.length && zoomStops[upper] < tileZoom + 1) upper++;\n        upper = Math.min(zoomStops.length - 1, upper);\n\n        const minZoom = zoomStops[lower];\n        const maxZoom = zoomStops[upper];\n\n        // We'd like to be able to use CameraExpression or CompositeExpression in these\n        // return types rather than ExpressionSpecification, but the former are not\n        // transferrable across Web Worker boundaries.\n        if (expression.kind === 'composite') {\n            return {kind: 'composite', minZoom, maxZoom, interpolationType};\n        }\n\n        // for camera functions, also save off the function values\n        // evaluated at the covering zoom levels\n        const minSize = expression.evaluate(new EvaluationParameters(minZoom));\n        const maxSize = expression.evaluate(new EvaluationParameters(maxZoom));\n\n        return {kind: 'camera', minZoom, maxZoom, minSize, maxSize, interpolationType};\n    }\n}\n\nfunction evaluateSizeForFeature(\n    sizeData: SizeData,\n    {\n        uSize,\n        uSizeT,\n    }: InterpolatedSize,\n    {\n        lowerSize,\n        upperSize,\n    }: {\n        readonly lowerSize: number;\n        readonly upperSize: number;\n    },\n): number {\n    if (sizeData.kind === 'source') {\n        return lowerSize / SIZE_PACK_FACTOR;\n    } else if (sizeData.kind === 'composite') {\n        return interpolate(lowerSize / SIZE_PACK_FACTOR, upperSize / SIZE_PACK_FACTOR, uSizeT);\n    }\n    return uSize;\n}\n\nfunction evaluateSizeForZoom(sizeData: SizeData, zoom: number): InterpolatedSize {\n    let uSizeT = 0;\n    let uSize = 0;\n\n    if (sizeData.kind === 'constant') {\n        uSize = sizeData.layoutSize;\n\n    } else if (sizeData.kind !== 'source') {\n        const {interpolationType, minZoom, maxZoom} = sizeData;\n\n        // Even though we could get the exact value of the camera function\n        // at z = tr.zoom, we intentionally do not: instead, we interpolate\n        // between the camera function values at a pair of zoom stops covering\n        // [tileZoom, tileZoom + 1] in order to be consistent with this\n        // restriction on composite functions\n        const t = !interpolationType ? 0 : clamp(\n            Interpolate.interpolationFactor(interpolationType, zoom, minZoom, maxZoom), 0, 1);\n\n        if (sizeData.kind === 'camera') {\n            uSize = interpolate(sizeData.minSize, sizeData.maxSize, t);\n        } else {\n            uSizeT = t;\n        }\n    }\n\n    return {uSizeT, uSize};\n}\n","import {plugin as rtlTextPlugin} from '../source/rtl_text_plugin';\n\nimport type SymbolStyleLayer from '../style/style_layer/symbol_style_layer';\nimport type {Feature} from '../style-spec/expression/index';\nimport Formatted from '../style-spec/expression/types/formatted';\n\nfunction transformText(text: string, layer: SymbolStyleLayer, feature: Feature) {\n\n    const transform = layer.layout.get('text-transform').evaluate(feature, {});\n    if (transform === 'uppercase') {\n        text = text.toLocaleUpperCase();\n    } else if (transform === 'lowercase') {\n        text = text.toLocaleLowerCase();\n    }\n\n    if (rtlTextPlugin.applyArabicShaping) {\n        text = rtlTextPlugin.applyArabicShaping(text);\n    }\n\n    return text;\n}\n\nexport default function(text: Formatted, layer: SymbolStyleLayer, feature: Feature): Formatted {\n    text.sections.forEach(section => {\n        section.text = transformText(section.text, layer, feature);\n    });\n    return text;\n}\n","import {charHasRotatedVerticalOrientation} from './script_detection';\n\nexport const verticalizedCharacterMap = {\n    '!': '︕',\n    '#': '＃',\n    '$': '＄',\n    '%': '％',\n    '&': '＆',\n    '(': '︵',\n    ')': '︶',\n    '*': '＊',\n    '+': '＋',\n    ',': '︐',\n    '-': '︲',\n    '.': '・',\n    '/': '／',\n    ':': '︓',\n    ';': '︔',\n    '<': '︿',\n    '=': '＝',\n    '>': '﹀',\n    '?': '︖',\n    '@': '＠',\n    '[': '﹇',\n    '\\\\': '＼',\n    ']': '﹈',\n    '^': '＾',\n    '_': '︳',\n    '`': '｀',\n    '{': '︷',\n    '|': '―',\n    '}': '︸',\n    '~': '～',\n    '¢': '￠',\n    '£': '￡',\n    '¥': '￥',\n    '¦': '￤',\n    '¬': '￢',\n    '¯': '￣',\n    '–': '︲',\n    '—': '︱',\n    '‘': '﹃',\n    '’': '﹄',\n    '“': '﹁',\n    '”': '﹂',\n    '…': '︙',\n    '‧': '・',\n    '₩': '￦',\n    '、': '︑',\n    '。': '︒',\n    '〈': '︿',\n    '〉': '﹀',\n    '《': '︽',\n    '》': '︾',\n    '「': '﹁',\n    '」': '﹂',\n    '『': '﹃',\n    '』': '﹄',\n    '【': '︻',\n    '】': '︼',\n    '〔': '︹',\n    '〕': '︺',\n    '〖': '︗',\n    '〗': '︘',\n    '！': '︕',\n    '（': '︵',\n    '）': '︶',\n    '，': '︐',\n    '－': '︲',\n    '．': '・',\n    '：': '︓',\n    '；': '︔',\n    '＜': '︿',\n    '＞': '﹀',\n    '？': '︖',\n    '［': '﹇',\n    '］': '﹈',\n    '＿': '︳',\n    '｛': '︷',\n    '｜': '―',\n    '｝': '︸',\n    '｟': '︵',\n    '｠': '︶',\n    '｡': '︒',\n    '｢': '﹁',\n    '｣': '﹂',\n    '←': '↑',\n    '→': '↓'\n} as const;\n\nexport default function verticalizePunctuation(input: string, skipContextChecking: boolean): string {\n    let output = '';\n\n    for (let i = 0; i < input.length; i++) {\n        const nextCharCode = input.charCodeAt(i + 1) || null;\n        const prevCharCode = input.charCodeAt(i - 1) || null;\n\n        const canReplacePunctuation = skipContextChecking || (\n            (!nextCharCode || !charHasRotatedVerticalOrientation(nextCharCode) || verticalizedCharacterMap[input[i + 1]]) &&\n            (!prevCharCode || !charHasRotatedVerticalOrientation(prevCharCode) || verticalizedCharacterMap[input[i - 1]])\n        );\n\n        if (canReplacePunctuation && verticalizedCharacterMap[input[i]]) {\n            output += verticalizedCharacterMap[input[i]];\n        } else {\n            output += input[i];\n        }\n    }\n\n    return output;\n}\n\nexport function isVerticalClosePunctuation(chr: string): boolean {\n    return chr === '︶' || chr === '﹈' || chr === '︸' || chr === '﹄' || chr === '﹂' || chr === '︾' ||\n           chr === '︼' || chr === '︺' || chr === '︘' || chr === '﹀' || chr === '︐' || chr === '︓' ||\n           chr === '︔' || chr === '｀' || chr === '￣' || chr === '︑' || chr === '︒';\n}\n\nexport function isVerticalOpenPunctuation(chr: string): boolean {\n    return chr === '︵' || chr === '﹇' || chr === '︷' || chr === '﹃' || chr === '﹁' || chr === '︽' ||\n           chr === '︻' || chr === '︹' || chr === '︗' || chr === '︿';\n}\n","import {AlphaImage} from '../util/image';\n\nimport Protobuf from 'pbf';\nconst border = 3;\n\nimport type {StyleGlyph} from './style_glyph';\n\nfunction readFontstacks(tag: number, glyphData: {\n    glyphs: Array<StyleGlyph>;\n    ascender?: number;\n    descender?: number;\n}, pbf: Protobuf) {\n    glyphData.glyphs = [];\n    if (tag === 1) {\n        pbf.readMessage(readFontstack, glyphData);\n    }\n}\n\nfunction readFontstack(tag: number,  glyphData: {\n    glyphs: Array<StyleGlyph>;\n    ascender?: number;\n    descender?: number;\n}, pbf: Protobuf) {\n    if (tag === 3) {\n        const {id, bitmap, width, height, left, top, advance} = pbf.readMessage(readGlyph, {});\n        glyphData.glyphs.push({\n            id,\n            bitmap: new AlphaImage({\n                width: width + 2 * border,\n                height: height + 2 * border\n            }, bitmap),\n            metrics: {width, height, left, top, advance}\n        });\n    } else if (tag === 4) {\n        glyphData.ascender = pbf.readSVarint();\n    } else if (tag === 5) {\n        glyphData.descender = pbf.readSVarint();\n    }\n}\n\nfunction readGlyph(tag: number, glyph: any, pbf: Protobuf) {\n    if (tag === 1) glyph.id = pbf.readVarint();\n    else if (tag === 2) glyph.bitmap = pbf.readBytes();\n    else if (tag === 3) glyph.width = pbf.readVarint();\n    else if (tag === 4) glyph.height = pbf.readVarint();\n    else if (tag === 5) glyph.left = pbf.readSVarint();\n    else if (tag === 6) glyph.top = pbf.readSVarint();\n    else if (tag === 7) glyph.advance = pbf.readVarint();\n}\n\nexport default function(data: ArrayBuffer | Uint8Array): {\n    glyphs: Array<StyleGlyph>;\n    ascender?: number;\n    descender?: number;\n} {\n// @ts-expect-error - TS2345 - Argument of type '{}' is not assignable to parameter of type '{ glyphs: StyleGlyph[]; ascender?: number; descender?: number; }'.\n    return new Protobuf(data).readFields(readFontstacks, {});\n}\n\nexport const GLYPH_PBF_BORDER = border;\n","import assert from 'assert';\nimport {\n    charHasUprightVerticalOrientation,\n    charAllowsIdeographicBreaking,\n    charInComplexShapingScript\n} from '../util/script_detection';\nimport verticalizePunctuation from '../util/verticalize_punctuation';\nimport {plugin as rtlTextPlugin} from '../source/rtl_text_plugin';\nimport ONE_EM from './one_em';\nimport {warnOnce} from '../util/util';\n\nimport type {StyleGlyph, GlyphMetrics} from '../style/style_glyph';\nimport {GLYPH_PBF_BORDER} from '../style/parse_glyph_pbf';\nimport type {ImagePosition} from '../render/image_atlas';\nimport type {GlyphRect, GlyphPositions} from '../render/glyph_atlas';\nimport Formatted, {FormattedSection} from '../style-spec/expression/types/formatted';\n\nconst WritingMode = {\n    horizontal: 1,\n    vertical: 2,\n    horizontalOnly: 3\n};\n\nconst SHAPING_DEFAULT_OFFSET = -17;\nexport {shapeText, shapeIcon, fitIconToText, getAnchorAlignment, WritingMode, SHAPING_DEFAULT_OFFSET};\n\n// The position of a glyph relative to the text's anchor point.\nexport type PositionedGlyph = {\n    glyph: number;\n    imageName: string | null;\n    x: number;\n    y: number;\n    vertical: boolean;\n    scale: number;\n    fontStack: string;\n    sectionIndex: number;\n    metrics: GlyphMetrics;\n    rect: GlyphRect | null;\n    localGlyph?: boolean;\n};\n\nexport type PositionedLine = {\n    positionedGlyphs: Array<PositionedGlyph>;\n    lineOffset: number;\n};\n\n// A collection of positioned glyphs and some metadata\nexport type Shaping = {\n    positionedLines: Array<PositionedLine>;\n    top: number;\n    bottom: number;\n    left: number;\n    right: number;\n    writingMode: 1 | 2;\n    text: string;\n    iconsInText: boolean;\n    verticalizable: boolean;\n    hasBaseline: boolean;\n};\n\ntype AnchorAlignment = {\n    horizontalAlign: number;\n    verticalAlign: number;\n};\n\nfunction isEmpty(positionedLines: Array<PositionedLine>) {\n    for (const line of positionedLines) {\n        if (line.positionedGlyphs.length !== 0) {\n            return false;\n        }\n    }\n    return true;\n}\n\nexport type SymbolAnchor = 'center' | 'left' | 'right' | 'top' | 'bottom' | 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right';\nexport type TextJustify = 'left' | 'center' | 'right';\n\n// Max number of images in label is 6401 U+E000–U+F8FF that covers\n// Basic Multilingual Plane Unicode Private Use Area (PUA).\nconst PUAbegin = 0xE000;\nconst PUAend = 0xF8FF;\n\nclass SectionOptions {\n    // Text options\n    scale: number;\n    fontStack: string;\n    // Image options\n    imageName: string | null;\n\n    constructor() {\n        this.scale = 1.0;\n        this.fontStack = \"\";\n        this.imageName = null;\n    }\n\n    static forText(scale: number | null | undefined, fontStack: string): SectionOptions {\n        const textOptions = new SectionOptions();\n        textOptions.scale = scale || 1;\n        textOptions.fontStack = fontStack;\n        return textOptions;\n    }\n\n    static forImage(imageName: string): SectionOptions {\n        const imageOptions = new SectionOptions();\n        imageOptions.imageName = imageName;\n        return imageOptions;\n    }\n\n}\n\nclass TaggedString {\n    text: string;\n    sectionIndex: Array<number>; // maps each character in 'text' to its corresponding entry in 'sections'\n    sections: Array<SectionOptions>;\n    imageSectionID: number | null;\n\n    constructor() {\n        this.text = \"\";\n        this.sectionIndex = [];\n        this.sections = [];\n        this.imageSectionID = null;\n    }\n\n    static fromFeature(text: Formatted, defaultFontStack: string): TaggedString {\n        const result = new TaggedString();\n        for (let i = 0; i < text.sections.length; i++) {\n            const section = text.sections[i];\n            if (!section.image) {\n                result.addTextSection(section, defaultFontStack);\n            } else {\n                result.addImageSection(section);\n            }\n        }\n        return result;\n    }\n\n    length(): number {\n        return this.text.length;\n    }\n\n    getSection(index: number): SectionOptions {\n        return this.sections[this.sectionIndex[index]];\n    }\n\n    getSections(): Array<SectionOptions> {\n        return this.sections;\n    }\n\n    getSectionIndex(index: number): number {\n        return this.sectionIndex[index];\n    }\n\n    getCodePoint(index: number): number {\n        return this.text.codePointAt(index);\n    }\n\n    verticalizePunctuation(skipContextChecking: boolean) {\n        this.text = verticalizePunctuation(this.text, skipContextChecking);\n    }\n\n    trim() {\n        let beginningWhitespace = 0;\n        for (let i = 0;\n            i < this.text.length && whitespace[this.text.charCodeAt(i)];\n            i++) {\n            beginningWhitespace++;\n        }\n        let trailingWhitespace = this.text.length;\n        for (let i = this.text.length - 1;\n            i >= 0 && i >= beginningWhitespace && whitespace[this.text.charCodeAt(i)];\n            i--) {\n            trailingWhitespace--;\n        }\n        this.text = this.text.substring(beginningWhitespace, trailingWhitespace);\n        this.sectionIndex = this.sectionIndex.slice(beginningWhitespace, trailingWhitespace);\n    }\n\n    substring(start: number, end: number): TaggedString {\n        const substring = new TaggedString();\n        substring.text = this.text.substring(start, end);\n        substring.sectionIndex = this.sectionIndex.slice(start, end);\n        substring.sections = this.sections;\n        return substring;\n    }\n\n    toString(): string {\n        return this.text;\n    }\n\n    getMaxScale(): number {\n        return this.sectionIndex.reduce((max, index) => Math.max(max, this.sections[index].scale), 0);\n    }\n\n    addTextSection(section: FormattedSection, defaultFontStack: string) {\n        this.text += section.text;\n        this.sections.push(SectionOptions.forText(section.scale, section.fontStack || defaultFontStack));\n        const index = this.sections.length - 1;\n        for (let i = 0; i < section.text.length; ++i) {\n            this.sectionIndex.push(index);\n        }\n    }\n\n    addImageSection(section: FormattedSection) {\n        const imageName = section.image ? section.image.namePrimary : '';\n        if (imageName.length === 0) {\n            warnOnce(`Can't add FormattedSection with an empty image.`);\n            return;\n        }\n\n        const nextImageSectionCharCode = this.getNextImageSectionCharCode();\n        if (!nextImageSectionCharCode) {\n            warnOnce(`Reached maximum number of images ${PUAend - PUAbegin + 2}`);\n            return;\n        }\n\n        this.text += String.fromCodePoint(nextImageSectionCharCode);\n        this.sections.push(SectionOptions.forImage(imageName));\n        this.sectionIndex.push(this.sections.length - 1);\n    }\n\n    getNextImageSectionCharCode(): number | null {\n        if (!this.imageSectionID) {\n            this.imageSectionID = PUAbegin;\n            return this.imageSectionID;\n        }\n\n        if (this.imageSectionID >= PUAend) return null;\n        return ++this.imageSectionID;\n    }\n}\n\nfunction breakLines(input: TaggedString, lineBreakPoints: Array<number>): Array<TaggedString> {\n    const lines = [];\n    const text = input.text;\n    let start = 0;\n    for (const lineBreak of lineBreakPoints) {\n        lines.push(input.substring(start, lineBreak));\n        start = lineBreak;\n    }\n\n    if (start < text.length) {\n        lines.push(input.substring(start, text.length));\n    }\n    return lines;\n}\n\nfunction shapeText(\n    text: Formatted,\n    glyphMap: {\n        [_: string]: {\n            glyphs: {\n                [_: number]: StyleGlyph | null | undefined;\n            };\n            ascender?: number;\n            descender?: number;\n        };\n    },\n    glyphPositions: GlyphPositions,\n    imagePositions: {\n        [_: string]: ImagePosition;\n    },\n    defaultFontStack: string,\n    maxWidth: number,\n    lineHeight: number,\n    textAnchor: SymbolAnchor,\n    textJustify: TextJustify,\n    spacing: number,\n    translate: [number, number],\n    writingMode: 1 | 2,\n    allowVerticalPlacement: boolean,\n    layoutTextSize: number,\n    layoutTextSizeThisZoom: number,\n): Shaping | false {\n    const logicalInput = TaggedString.fromFeature(text, defaultFontStack);\n\n    if (writingMode === WritingMode.vertical) {\n        logicalInput.verticalizePunctuation(allowVerticalPlacement);\n    }\n\n    let lines: Array<TaggedString> = [];\n\n    const lineBreaks = determineLineBreaks(logicalInput, spacing, maxWidth, glyphMap, imagePositions, layoutTextSize);\n\n    const {processBidirectionalText, processStyledBidirectionalText} = rtlTextPlugin;\n    if (processBidirectionalText && logicalInput.sections.length === 1) {\n        // Bidi doesn't have to be style-aware\n        const untaggedLines = processBidirectionalText(logicalInput.toString(), lineBreaks);\n        for (const line of untaggedLines) {\n            const taggedLine = new TaggedString();\n            taggedLine.text = line;\n            taggedLine.sections = logicalInput.sections;\n            for (let i = 0; i < line.length; i++) {\n                taggedLine.sectionIndex.push(0);\n            }\n            lines.push(taggedLine);\n        }\n    } else if (processStyledBidirectionalText) {\n        // Need version of mapbox-gl-rtl-text with style support for combining RTL text with formatting\n        const processedLines = processStyledBidirectionalText(logicalInput.text, logicalInput.sectionIndex, lineBreaks);\n        for (const line of processedLines) {\n            const taggedLine = new TaggedString();\n            taggedLine.text = line[0];\n            taggedLine.sectionIndex = line[1];\n            taggedLine.sections = logicalInput.sections;\n            lines.push(taggedLine);\n        }\n    } else {\n        lines = breakLines(logicalInput, lineBreaks);\n    }\n\n    const positionedLines = [];\n    const shaping = {\n        positionedLines,\n        text: logicalInput.toString(),\n        top: translate[1],\n        bottom: translate[1],\n        left: translate[0],\n        right: translate[0],\n        writingMode,\n        iconsInText: false,\n        verticalizable: false,\n        hasBaseline: false\n    };\n\n    shapeLines(shaping, glyphMap, glyphPositions, imagePositions, lines, lineHeight, textAnchor, textJustify, writingMode, spacing, allowVerticalPlacement, layoutTextSizeThisZoom);\n    if (isEmpty(positionedLines)) return false;\n\n    return shaping;\n}\n\n// using computed properties due to https://github.com/facebook/flow/issues/380\n/* eslint no-useless-computed-key: 0 */\n\nconst whitespace: {\n    [_: number]: boolean;\n} = {\n    [0x09]: true, // tab\n    [0x0a]: true, // newline\n    [0x0b]: true, // vertical tab\n    [0x0c]: true, // form feed\n    [0x0d]: true, // carriage return\n    [0x20]: true, // space\n};\n\nconst breakable: {\n    [_: number]: boolean;\n} = {\n    [0x0a]:   true, // newline\n    [0x20]:   true, // space\n    [0x26]:   true, // ampersand\n    [0x28]:   true, // left parenthesis\n    [0x29]:   true, // right parenthesis\n    [0x2b]:   true, // plus sign\n    [0x2d]:   true, // hyphen-minus\n    [0x2f]:   true, // solidus\n    [0xad]:   true, // soft hyphen\n    [0xb7]:   true, // middle dot\n    [0x200b]: true, // zero-width space\n    [0x2010]: true, // hyphen\n    [0x2013]: true, // en dash\n    [0x2027]: true  // interpunct\n    // Many other characters may be reasonable breakpoints\n    // Consider \"neutral orientation\" characters at scriptDetection.charHasNeutralVerticalOrientation\n    // See https://github.com/mapbox/mapbox-gl-js/issues/3658\n};\n\nfunction getGlyphAdvance(\n    codePoint: number,\n    section: SectionOptions,\n    glyphMap: {\n        [_: string]: {\n            glyphs: {\n                [_: number]: StyleGlyph | null | undefined;\n            };\n            ascender?: number;\n            descender?: number;\n        };\n    },\n    imagePositions: {\n        [_: string]: ImagePosition;\n    },\n    spacing: number,\n    layoutTextSize: number,\n): number {\n    if (!section.imageName) {\n        const positions = glyphMap[section.fontStack];\n        const glyph = positions && positions.glyphs[codePoint];\n        if (!glyph) return 0;\n        return glyph.metrics.advance * section.scale + spacing;\n    } else {\n        const imagePosition = imagePositions[section.imageName];\n        if (!imagePosition) return 0;\n        return imagePosition.displaySize[0] * section.scale * ONE_EM / layoutTextSize + spacing;\n    }\n}\n\nfunction determineAverageLineWidth(logicalInput: TaggedString,\n                                   spacing: number,\n                                   maxWidth: number,\n                                   glyphMap: {\n                                       [_: string]: {\n                                           glyphs: {\n                                               [_: number]: StyleGlyph | null | undefined;\n                                           };\n                                           ascender?: number;\n                                           descender?: number;\n                                       };\n                                   },\n                                   imagePositions: {\n                                       [_: string]: ImagePosition;\n                                   },\n                                   layoutTextSize: number) {\n    let totalWidth = 0;\n\n    for (let index = 0; index < logicalInput.length(); index++) {\n        const section = logicalInput.getSection(index);\n        totalWidth += getGlyphAdvance(logicalInput.getCodePoint(index), section, glyphMap, imagePositions, spacing, layoutTextSize);\n    }\n\n    const lineCount = Math.max(1, Math.ceil(totalWidth / maxWidth));\n    return totalWidth / lineCount;\n}\n\nfunction calculateBadness(lineWidth: number,\n                          targetWidth: number,\n                          penalty: number,\n                          isLastBreak: boolean) {\n    const raggedness = Math.pow(lineWidth - targetWidth, 2);\n    if (isLastBreak) {\n        // Favor finals lines shorter than average over longer than average\n        if (lineWidth < targetWidth) {\n            return raggedness / 2;\n        } else {\n            return raggedness * 2;\n        }\n    }\n\n    return raggedness + Math.abs(penalty) * penalty;\n}\n\nfunction calculatePenalty(codePoint: number, nextCodePoint: number, penalizableIdeographicBreak: boolean) {\n    let penalty = 0;\n    // Force break on newline\n    if (codePoint === 0x0a) {\n        penalty -= 10000;\n    }\n    // Penalize breaks between characters that allow ideographic breaking because\n    // they are less preferable than breaks at spaces (or zero width spaces).\n    if (penalizableIdeographicBreak) {\n        penalty += 150;\n    }\n\n    // Penalize open parenthesis at end of line\n    if (codePoint === 0x28 || codePoint === 0xff08) {\n        penalty += 50;\n    }\n\n    // Penalize close parenthesis at beginning of line\n    if (nextCodePoint === 0x29 || nextCodePoint === 0xff09) {\n        penalty += 50;\n    }\n    return penalty;\n}\n\ntype Break = {\n    index: number;\n    x: number;\n    priorBreak: Break | null | undefined;\n    badness: number;\n};\n\nfunction evaluateBreak(\n    breakIndex: number,\n    breakX: number,\n    targetWidth: number,\n    potentialBreaks: Array<Break>,\n    penalty: number,\n    isLastBreak: boolean,\n): Break {\n    // We could skip evaluating breaks where the line length (breakX - priorBreak.x) > maxWidth\n    //  ...but in fact we allow lines longer than maxWidth (if there's no break points)\n    //  ...and when targetWidth and maxWidth are close, strictly enforcing maxWidth can give\n    //     more lopsided results.\n\n    let bestPriorBreak: Break | null | undefined = null;\n    let bestBreakBadness = calculateBadness(breakX, targetWidth, penalty, isLastBreak);\n\n    for (const potentialBreak of potentialBreaks) {\n        const lineWidth = breakX - potentialBreak.x;\n        const breakBadness =\n            calculateBadness(lineWidth, targetWidth, penalty, isLastBreak) + potentialBreak.badness;\n        if (breakBadness <= bestBreakBadness) {\n            bestPriorBreak = potentialBreak;\n            bestBreakBadness = breakBadness;\n        }\n    }\n\n    return {\n        index: breakIndex,\n        x: breakX,\n        priorBreak: bestPriorBreak,\n        badness: bestBreakBadness\n    };\n}\n\nfunction leastBadBreaks(lastLineBreak?: Break | null): Array<number> {\n    if (!lastLineBreak) {\n        return [];\n    }\n    return leastBadBreaks(lastLineBreak.priorBreak).concat(lastLineBreak.index);\n}\n\nfunction determineLineBreaks(\n    logicalInput: TaggedString,\n    spacing: number,\n    maxWidth: number,\n    glyphMap: {\n        [_: string]: {\n            glyphs: {\n                [_: number]: StyleGlyph | null | undefined;\n            };\n            ascender?: number;\n            descender?: number;\n        };\n    },\n    imagePositions: {\n        [_: string]: ImagePosition;\n    },