rthestPixelDistanceOnSphere(tr: Transform, pixelsPerMeter: number): number {\n    // Find farthest distance of the globe that is potentially visible to the camera.\n    // First check if the view frustum is fully covered by the map by casting a ray\n    // from the top left/right corner and see if it intersects with the globe. In case\n    // of no intersection we need to find distance to the horizon point where the\n    // surface normal is perpendicular to the camera forward direction.\n    const cameraDistance = tr.cameraToCenterDistance;\n    const centerPixelAltitude = tr._centerAltitude * pixelsPerMeter;\n\n    const camera = tr._camera;\n    const forward = tr._camera.forward();\n    const cameraPosition = vec3.add([] as any, vec3.scale([] as any, forward, -cameraDistance), [0, 0, centerPixelAltitude]);\n\n    const globeRadius = tr.worldSize / (2.0 * Math.PI);\n    const globeCenter = [0, 0, -globeRadius];\n\n    const aspectRatio = tr.width / tr.height;\n    const tanFovAboveCenter = Math.tan(tr.fovAboveCenter);\n\n    const up = vec3.scale([] as any, camera.up(), tanFovAboveCenter);\n    const right = vec3.scale([] as any, camera.right(), tanFovAboveCenter * aspectRatio);\n    const dir = vec3.normalize([] as any, vec3.add([] as any, vec3.add([] as any, forward, up), right));\n\n    const pointOnGlobe = [];\n    const ray = new Ray(cameraPosition, dir);\n\n    let pixelDistance;\n    // @ts-expect-error - TS2345 - Argument of type 'number[]' is not assignable to parameter of type 'vec3'.\n    if (ray.closestPointOnSphere(globeCenter, globeRadius, pointOnGlobe)) {\n        // @ts-expect-error - TS2345 - Argument of type '[]' is not assignable to parameter of type 'ReadonlyVec3'.\n        const p0 = vec3.add([] as any, pointOnGlobe as [], globeCenter as [number, number, number]);\n        const p1 = vec3.sub([] as any, p0, cameraPosition);\n        // Globe is fully covering the view frustum. Project the intersection\n        // point to the camera view vector in order to find the pixel distance\n        pixelDistance = Math.cos(tr.fovAboveCenter) * vec3.length(p1);\n    } else {\n        // Background space is visible. Find distance to the point of the\n        // globe where surface normal is parallel to the view vector\n        const globeCenterToCamera = vec3.sub([] as any, cameraPosition, globeCenter as [number, number, number]);\n        const cameraToGlobe = vec3.sub([] as any, globeCenter as [number, number, number], cameraPosition);\n        vec3.normalize(cameraToGlobe, cameraToGlobe);\n\n        const cameraHeight = vec3.length(globeCenterToCamera) - globeRadius;\n        pixelDistance = Math.sqrt(cameraHeight * (cameraHeight + 2 * globeRadius));\n        const angle = Math.acos(pixelDistance / (globeRadius + cameraHeight)) - Math.acos(vec3.dot(forward, cameraToGlobe));\n        pixelDistance *= Math.cos(angle);\n    }\n\n    return pixelDistance * 1.01;\n}\n","import Point from '@mapbox/point-geometry';\nimport MercatorCoordinate, {altitudeFromMercatorZ, lngFromMercatorX, latFromMercatorY} from '../mercator_coordinate';\nimport EXTENT from '../../style-spec/data/extent';\nimport {vec3} from 'gl-matrix';\nimport {Aabb} from '../../util/primitives';\nimport {aabbForTileOnGlobe} from './globe_util';\nimport assert from 'assert';\nimport {CanonicalTileID} from '../../source/tile_id';\n\nimport type Projection from './projection';\nimport type {ProjectedPoint} from './projection';\nimport type Transform from '../transform';\n\nexport type TileTransform = {\n    scale: number;\n    x: number;\n    y: number;\n    x2: number;\n    y2: number;\n    projection: Projection;\n};\n\nexport default function tileTransform(id: any, projection: Projection): TileTransform {\n    if (!projection.isReprojectedInTileSpace) {\n        return {scale: 1 << id.z, x: id.x, y: id.y, x2: id.x + 1, y2: id.y + 1, projection};\n    }\n\n    const s = Math.pow(2, -id.z);\n\n    const x1 = (id.x) * s;\n    const x2 = (id.x + 1) * s;\n    const y1 = (id.y) * s;\n    const y2 = (id.y + 1) * s;\n\n    const lng1 = lngFromMercatorX(x1);\n    const lng2 = lngFromMercatorX(x2);\n    const lat1 = latFromMercatorY(y1);\n    const lat2 = latFromMercatorY(y2);\n\n    const p0 = projection.project(lng1, lat1);\n    const p1 = projection.project(lng2, lat1);\n    const p2 = projection.project(lng2, lat2);\n    const p3 = projection.project(lng1, lat2);\n\n    let minX = Math.min(p0.x, p1.x, p2.x, p3.x);\n    let minY = Math.min(p0.y, p1.y, p2.y, p3.y);\n    let maxX = Math.max(p0.x, p1.x, p2.x, p3.x);\n    let maxY = Math.max(p0.y, p1.y, p2.y, p3.y);\n\n    // we pick an error threshold for calculating the bbox that balances between performance and precision\n    const maxErr = s / 16;\n\n    function processSegment(pa: ProjectedPoint, pb: ProjectedPoint, ax: number, ay: number, bx: number, by: number) {\n        const mx = (ax + bx) / 2;\n        const my = (ay + by) / 2;\n\n        const pm = projection.project(lngFromMercatorX(mx), latFromMercatorY(my));\n        const err = Math.max(0, minX - pm.x, minY - pm.y, pm.x - maxX, pm.y - maxY);\n\n        minX = Math.min(minX, pm.x);\n        maxX = Math.max(maxX, pm.x);\n        minY = Math.min(minY, pm.y);\n        maxY = Math.max(maxY, pm.y);\n\n        if (err > maxErr) {\n            processSegment(pa, pm, ax, ay, mx, my);\n            processSegment(pm, pb, mx, my, bx, by);\n        }\n    }\n\n    processSegment(p0, p1, x1, y1, x2, y1);\n    processSegment(p1, p2, x2, y1, x2, y2);\n    processSegment(p2, p3, x2, y2, x1, y2);\n    processSegment(p3, p0, x1, y2, x1, y1);\n\n    // extend the bbox by max error to make sure coords don't go past tile extent\n    minX -= maxErr;\n    minY -= maxErr;\n    maxX += maxErr;\n    maxY += maxErr;\n\n    const max = Math.max(maxX - minX, maxY - minY);\n    const scale = 1 / max;\n\n    return {\n        scale,\n        x: minX * scale,\n        y: minY * scale,\n        x2: maxX * scale,\n        y2: maxY * scale,\n        projection\n    };\n}\n\nexport function tileAABB(\n    tr: Transform,\n    numTiles: number,\n    z: number,\n    x: number,\n    y: number,\n    wrap: number,\n    min: number,\n    max: number,\n    projection: Projection,\n): Aabb {\n    if (projection.name === 'globe') {\n        const tileId = new CanonicalTileID(z, x, y);\n        return aabbForTileOnGlobe(tr, numTiles, tileId, false);\n    }\n\n    const tt = tileTransform({z, x, y}, projection);\n    const tx = tt.x / tt.scale;\n    const ty = tt.y / tt.scale;\n    const tx2 = tt.x2 / tt.scale;\n    const ty2 = tt.y2 / tt.scale;\n\n    if (isNaN(tx) || isNaN(tx2) || isNaN(ty) || isNaN(ty2)) {\n        assert(false);\n    }\n\n    return new Aabb(\n        [(wrap + tx) * numTiles, numTiles * ty, min],\n        [(wrap  + tx2) * numTiles, numTiles * ty2, max]);\n}\n\nexport function getTilePoint(\n    tileTransform: TileTransform,\n    {\n        x,\n        y,\n    }: {\n        x: number;\n        y: number;\n    },\n    wrap: number = 0,\n): Point {\n    return new Point(\n        ((x - wrap) * tileTransform.scale - tileTransform.x) * EXTENT,\n        (y * tileTransform.scale - tileTransform.y) * EXTENT);\n}\n\nexport function getTileVec3(tileTransform: TileTransform, coord: MercatorCoordinate, wrap: number = 0): vec3 {\n    const x = ((coord.x - wrap) * tileTransform.scale - tileTransform.x) * EXTENT;\n    const y = (coord.y * tileTransform.scale - tileTransform.y) * EXTENT;\n    return vec3.fromValues(x, y, altitudeFromMercatorZ(coord.z, coord.y));\n}\n","import LngLat from '../lng_lat';\nimport {mercatorZfromAltitude} from '../mercator_coordinate';\nimport Point from '@mapbox/point-geometry';\nimport {farthestPixelDistanceOnPlane} from './far_z';\nimport {mat4} from 'gl-matrix';\nimport EXTENT from '../../style-spec/data/extent';\nimport tileTransform from './tile_transform';\n\nimport type Transform from '../../geo/transform';\nimport type {vec3} from 'gl-matrix';\nimport type MercatorCoordinate from '../mercator_coordinate';\nimport type {ProjectionSpecification} from '../../style-spec/types';\nimport type {CanonicalTileID, UnwrappedTileID} from '../../source/tile_id';\n\nexport type ProjectedPoint = {\n    x: number;\n    y: number;\n    z: number;\n};\n\nexport type ElevationScale = {\n    // `metersToTile` converts meters to units used to describe elevation in tile space.\n    // Default units in mercator space are x & y: [0, 8192] and z: meters\n    metersToTile: number;\n};\n\nconst identity = mat4.identity(new Float32Array(16));\n\nexport default class Projection {\n    name: string;\n    wrap: boolean;\n    conic: boolean;\n    requiresDraping: boolean;\n    supportsWorldCopies: boolean;\n    supportsTerrain: boolean;\n    supportsFog: boolean;\n    supportsFreeCamera: boolean;\n    zAxisUnit: 'meters' | 'pixels';\n    isReprojectedInTileSpace: boolean;\n    center: [number, number];\n    range: [number, number] | null | undefined;\n    parallels: [number, number] | null | undefined;\n    unsupportedLayers: Array<string>;\n    spec: ProjectionSpecification;\n\n    constructor(options: ProjectionSpecification) {\n        this.spec = options;\n        this.name = options.name;\n        this.wrap = false;\n        this.requiresDraping = false;\n        this.supportsWorldCopies = false;\n        this.supportsTerrain = false;\n        this.supportsFog = false;\n        this.supportsFreeCamera = false;\n        this.zAxisUnit = 'meters';\n        this.isReprojectedInTileSpace = true;\n        this.unsupportedLayers = ['custom'];\n        this.center = [0, 0];\n        this.range = [3.5, 7];\n    }\n\n    project(lng: number, lat: number): ProjectedPoint { // eslint-disable-line\n        return {x: 0, y: 0, z: 0}; // overriden in subclasses\n    }\n\n    unproject(x: number, y: number): LngLat { // eslint-disable-line\n        return new LngLat(0, 0); // overriden in subclasses\n    }\n\n    projectTilePoint(x: number, y: number, _: CanonicalTileID): ProjectedPoint {\n        return {x, y, z: 0};\n    }\n\n    locationPoint(tr: Transform, lngLat: LngLat, terrain: boolean = true): Point {\n        return tr._coordinatePoint(tr.locationCoordinate(lngLat), terrain);\n    }\n\n    pixelsPerMeter(lat: number, worldSize: number): number {\n        return mercatorZfromAltitude(1, lat) * worldSize;\n    }\n\n    // pixels-per-meter is used to describe relation between real world and pixel distances.\n    // `pixelSpaceConversion` can be used to convert the ratio from mercator projection to\n    // the currently active projection.\n    //\n    // `pixelSpaceConversion` is useful for converting between pixel spaces where some logic\n    // expects mercator pixels, such as raycasting where the scale is expected to be in\n    // mercator pixels.\n    pixelSpaceConversion(lat: number, worldSize: number, interpolationT: number): number { // eslint-disable-line\n        return 1.0;\n    }\n\n    farthestPixelDistance(tr: Transform): number {\n        return farthestPixelDistanceOnPlane(tr, tr.pixelsPerMeter);\n    }\n\n    pointCoordinate(tr: Transform, x: number, y: number, z: number): MercatorCoordinate {\n        const horizonOffset = tr.horizonLineFromTop(false);\n        const clamped = new Point(x, Math.max(horizonOffset, y));\n        return tr.rayIntersectionCoordinate(tr.pointRayIntersection(clamped, z));\n    }\n\n    pointCoordinate3D(tr: Transform, x: number, y: number): vec3 | null | undefined {\n        const p = new Point(x, y);\n        if (tr.elevation) {\n            // @ts-expect-error - TS2322 - Type 'vec4' is not assignable to type 'vec3'.\n            return tr.elevation.pointCoordinate(p);\n        } else {\n            const mc = this.pointCoordinate(tr, p.x, p.y, 0);\n            return [mc.x, mc.y, mc.z];\n        }\n    }\n\n    isPointAboveHorizon(tr: Transform, p: Point): boolean {\n        if (tr.elevation && tr.elevation.visibleDemTiles.length) {\n            const raycastOnTerrain = this.pointCoordinate3D(tr, p.x, p.y);\n            return !raycastOnTerrain;\n        }\n        const horizon = tr.horizonLineFromTop();\n        return p.y < horizon;\n    }\n\n    createInversionMatrix(tr: Transform, id: CanonicalTileID): Float32Array { // eslint-disable-line\n        // @ts-expect-error - TS2322 - Type 'mat4' is not assignable to type 'Float32Array'.\n        return identity;\n    }\n\n    createTileMatrix(tr: Transform, worldSize: number, id: UnwrappedTileID): Float64Array {\n        let scale, scaledX, scaledY;\n        const canonical = id.canonical;\n        // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'mat4'.\n        const posMatrix = mat4.identity(new Float64Array(16));\n\n        if (this.isReprojectedInTileSpace) {\n            const cs = tileTransform(canonical, this);\n            scale = 1;\n            scaledX = cs.x + id.wrap * cs.scale;\n            scaledY = cs.y;\n            mat4.scale(posMatrix, posMatrix, [scale / cs.scale, scale / cs.scale, tr.pixelsPerMeter / worldSize]);\n        } else {\n            scale = worldSize / tr.zoomScale(canonical.z);\n            const unwrappedX = canonical.x + Math.pow(2, canonical.z) * id.wrap;\n            scaledX = unwrappedX * scale;\n            scaledY = canonical.y * scale;\n        }\n\n        mat4.translate(posMatrix, posMatrix, [scaledX, scaledY, 0]);\n        mat4.scale(posMatrix, posMatrix, [scale / EXTENT, scale / EXTENT, 1]);\n\n        // @ts-expect-error - TS2322 - Type 'mat4' is not assignable to type 'Float64Array'.\n        return posMatrix;\n    }\n\n    upVector(id: CanonicalTileID, x: number, y: number): [number, number, number] {\n        return [0, 0, 1];\n    }\n\n    upVectorScale(id: CanonicalTileID, latitude: number, worldSize: number): ElevationScale {\n        return {metersToTile: 1};\n    }\n}\n","import LngLat from '../lng_lat';\nimport {clamp, wrap, degToRad, radToDeg} from '../../util/util';\nimport {MAX_MERCATOR_LATITUDE} from '../mercator_coordinate';\nimport Projection from './projection';\n\nimport type {ProjectionSpecification} from '../../style-spec/types';\nimport type {ProjectedPoint} from './projection';\n\n// based on https://github.com/d3/d3-geo-projection, MIT-licensed\nexport default class Albers extends Projection {\n    n: number;\n    c: number;\n    r0: number;\n\n    constructor(options: ProjectionSpecification) {\n        super(options);\n        this.range = [4, 7];\n        this.center = options.center || [-96, 37.5];\n        const [lat0, lat1] = this.parallels = options.parallels || [29.5, 45.5];\n\n        const sy0 = Math.sin(degToRad(lat0));\n        this.n = (sy0 + Math.sin(degToRad(lat1))) / 2;\n        this.c = 1 + sy0 * (2 * this.n - sy0);\n        this.r0 = Math.sqrt(this.c) / this.n;\n    }\n\n    project(lng: number, lat: number): ProjectedPoint {\n        const {n, c, r0} = this;\n        const lambda = degToRad(lng - this.center[0]);\n        const phi = degToRad(lat);\n\n        const r = Math.sqrt(c - 2 * n * Math.sin(phi)) / n;\n        const x = r * Math.sin(lambda * n);\n        const y = r * Math.cos(lambda * n) - r0;\n        return {x, y, z: 0};\n    }\n\n    unproject(x: number, y: number): LngLat {\n        const {n, c, r0} = this;\n        const r0y = r0 + y;\n        let l = Math.atan2(x, Math.abs(r0y)) * Math.sign(r0y);\n        if (r0y * n < 0) {\n            l -= Math.PI * Math.sign(x) * Math.sign(r0y);\n        }\n        const dt = degToRad(this.center[0]) * n;\n        l = wrap(l, -Math.PI - dt, Math.PI - dt);\n\n        const lng = clamp(radToDeg(l / n) + this.center[0], -180, 180);\n        const phi = Math.asin(clamp((c - (x * x + r0y * r0y) * n * n) / (2 * n), -1, 1));\n        const lat = clamp(radToDeg(phi), -MAX_MERCATOR_LATITUDE, MAX_MERCATOR_LATITUDE);\n\n        return new LngLat(lng, lat);\n    }\n}\n","import LngLat from '../lng_lat';\nimport {clamp} from '../../util/util';\nimport {MAX_MERCATOR_LATITUDE} from '../mercator_coordinate';\nimport Projection from './projection';\n\nimport type {ProjectedPoint} from './projection';\n\nconst a1 = 1.340264;\nconst a2 = -0.081106;\nconst a3 = 0.000893;\nconst a4 = 0.003796;\nconst M = Math.sqrt(3) / 2;\n\nexport default class EqualEarth extends Projection {\n\n    project(lng: number, lat: number): ProjectedPoint {\n        // based on https://github.com/d3/d3-geo, MIT-licensed\n        lat = lat / 180 * Math.PI;\n        lng = lng / 180 * Math.PI;\n        const theta = Math.asin(M * Math.sin(lat));\n        const theta2 = theta * theta;\n        const theta6 = theta2 * theta2 * theta2;\n        const x = lng * Math.cos(theta) / (M * (a1 + 3 * a2 * theta2 + theta6 * (7 * a3 + 9 * a4 * theta2)));\n        const y = theta * (a1 + a2 * theta2 + theta6 * (a3 + a4 * theta2));\n\n        return {\n            x: (x / Math.PI + 0.5) * 0.5,\n            y: 1 - (y / Math.PI + 1) * 0.5,\n            z: 0\n        };\n    }\n\n    unproject(x: number, y: number): LngLat {\n        // based on https://github.com/d3/d3-geo, MIT-licensed\n        x = (2 * x - 0.5) * Math.PI;\n        y = (2 * (1 - y) - 1) * Math.PI;\n        let theta = y;\n        let theta2 = theta * theta;\n        let theta6 = theta2 * theta2 * theta2;\n\n        for (let i = 0, delta, fy, fpy; i < 12; ++i) {\n            fy = theta * (a1 + a2 * theta2 + theta6 * (a3 + a4 * theta2)) - y;\n            fpy = a1 + 3 * a2 * theta2 + theta6 * (7 * a3 + 9 * a4 * theta2);\n            delta = fy / fpy;\n            theta = clamp(theta - delta, -Math.PI / 3, Math.PI / 3);\n            theta2 = theta * theta;\n            theta6 = theta2 * theta2 * theta2;\n            if (Math.abs(delta) < 1e-12) break;\n        }\n\n        const lambda = M * x * (a1 + 3 * a2 * theta2 + theta6 * (7 * a3 + 9 * a4 * theta2)) / Math.cos(theta);\n        const phi = Math.asin(Math.sin(theta) / M);\n        const lng = clamp(lambda * 180 / Math.PI, -180, 180);\n        const lat = clamp(phi * 180 / Math.PI, -MAX_MERCATOR_LATITUDE, MAX_MERCATOR_LATITUDE);\n\n        return new LngLat(lng, lat);\n    }\n}\n","import LngLat from '../lng_lat';\nimport {clamp} from '../../util/util';\nimport {MAX_MERCATOR_LATITUDE} from '../mercator_coordinate';\nimport Projection from './projection';\n\nimport type {ProjectionSpecification} from '../../style-spec/types';\nimport type {ProjectedPoint} from './projection';\n\nexport default class Equirectangular extends Projection {\n\n    constructor(options: ProjectionSpecification) {\n        super(options);\n        this.wrap = true;\n        this.supportsWorldCopies = true;\n    }\n\n    project(lng: number, lat: number): ProjectedPoint {\n        const x = 0.5 + lng / 360;\n        const y = 0.5 - lat / 360;\n        return {x, y, z: 0};\n    }\n\n    unproject(x: number, y: number): LngLat {\n        const lng = (x - 0.5) * 360;\n        const lat = clamp((0.5 - y) * 360, -MAX_MERCATOR_LATITUDE, MAX_MERCATOR_LATITUDE);\n        return new LngLat(lng, lat);\n    }\n}\n","import LngLat from '../lng_lat';\nimport {clamp, degToRad, radToDeg} from '../../util/util';\nimport {MAX_MERCATOR_LATITUDE} from '../mercator_coordinate';\nimport Projection from './projection';\n\nimport type {ProjectionSpecification} from '../../style-spec/types';\nimport type {ProjectedPoint} from './projection';\n\nconst halfPi = Math.PI / 2;\n\nfunction tany(y: number) {\n    return Math.tan((halfPi + y) / 2);\n}\n\n// based on https://github.com/d3/d3-geo, MIT-licensed\nexport default class LambertConformalConic extends Projection {\n    n: number;\n    f: number;\n    southernCenter: boolean;\n\n    constructor(options: ProjectionSpecification) {\n        super(options);\n        this.center = options.center || [0, 30];\n        const [lat0, lat1] = this.parallels = options.parallels || [30, 30];\n\n        let y0 = degToRad(lat0);\n        let y1 = degToRad(lat1);\n        // Run projection math on inverted lattitudes if the paralell lines are south of the equator\n        // This fixes divide by zero errors with a South polar projection\n        this.southernCenter = (y0 + y1) < 0;\n        if (this.southernCenter) {\n            y0 = -y0;\n            y1 = -y1;\n        }\n        const cy0 = Math.cos(y0);\n        const tany0 = tany(y0);\n\n        this.n = y0 === y1 ? Math.sin(y0) : Math.log(cy0 / Math.cos(y1)) / Math.log(tany(y1) / tany0);\n        this.f = cy0 * Math.pow(tany(y0), this.n) / this.n;\n    }\n\n    project(lng: number, lat: number): ProjectedPoint {\n        lat = degToRad(lat);\n        if (this.southernCenter) lat = -lat;\n        lng = degToRad(lng - this.center[0]);\n\n        const epsilon = 1e-6;\n        const {n, f} = this;\n\n        if (f > 0) {\n            if (lat < -halfPi + epsilon) lat = -halfPi + epsilon;\n        } else {\n            if (lat > halfPi - epsilon) lat = halfPi - epsilon;\n        }\n\n        const r = f / Math.pow(tany(lat), n);\n        let x = r * Math.sin(n * lng);\n        let y = f - r * Math.cos(n * lng);\n        x = (x / Math.PI + 0.5) * 0.5;\n        y = (y / Math.PI + 0.5) * 0.5;\n\n        return {\n            x,\n            y: this.southernCenter ? y : 1 - y,\n            z: 0\n        };\n    }\n\n    unproject(x: number, y: number): LngLat {\n        x = (2 * x - 0.5) * Math.PI;\n        if (this.southernCenter) y = 1 - y;\n        y = (2 * (1 - y) - 0.5) * Math.PI;\n        const {n, f} = this;\n        const fy = f - y;\n        const signFy = Math.sign(fy);\n        const r = Math.sign(n) * Math.sqrt(x * x + fy * fy);\n        let l = Math.atan2(x, Math.abs(fy)) * signFy;\n\n        if (fy * n < 0) l -= Math.PI * Math.sign(x) * signFy;\n\n        const lng = clamp(radToDeg(l / n) + this.center[0], -180, 180);\n        const phi = 2 * Math.atan(Math.pow(f / r, 1 / n)) - halfPi;\n        const lat = clamp(radToDeg(phi), -MAX_MERCATOR_LATITUDE, MAX_MERCATOR_LATITUDE);\n\n        return new LngLat(lng, this.southernCenter ? -lat : lat);\n    }\n}\n","import LngLat from '../lng_lat';\nimport {mercatorXfromLng, mercatorYfromLat, lngFromMercatorX, latFromMercatorY} from '../mercator_coordinate';\nimport Projection from './projection';\n\nimport type {ProjectionSpecification} from '../../style-spec/types';\nimport type {ProjectedPoint} from './projection';\n\nexport default class Mercator extends Projection {\n\n    constructor(options: ProjectionSpecification) {\n        super(options);\n        this.wrap = true;\n        this.supportsWorldCopies = true;\n        this.supportsTerrain = true;\n        this.supportsFog = true;\n        this.supportsFreeCamera = true;\n        this.isReprojectedInTileSpace = false;\n        this.unsupportedLayers = [];\n        this.range = null;\n    }\n\n    project(lng: number, lat: number): ProjectedPoint {\n        const x = mercatorXfromLng(lng);\n        const y = mercatorYfromLat(lat);\n        return {x, y, z: 0};\n    }\n\n    unproject(x: number, y: number): LngLat {\n        const lng = lngFromMercatorX(x);\n        const lat = latFromMercatorY(y);\n        return new LngLat(lng, lat);\n    }\n}\n","import LngLat from '../lng_lat';\nimport {clamp, degToRad, radToDeg} from '../../util/util';\nimport {MAX_MERCATOR_LATITUDE} from '../mercator_coordinate';\nimport Projection from './projection';\n\nimport type {ProjectedPoint} from './projection';\n\nconst maxPhi = degToRad(MAX_MERCATOR_LATITUDE);\n\nexport default class NaturalEarth extends Projection {\n\n    project(lng: number, lat: number): ProjectedPoint {\n        // based on https://github.com/d3/d3-geo, MIT-licensed\n        lat = degToRad(lat);\n        lng = degToRad(lng);\n\n        const phi2 = lat * lat;\n        const phi4 = phi2 * phi2;\n        const x = lng * (0.8707 - 0.131979 * phi2 + phi4 * (-0.013791 + phi4 * (0.003971 * phi2 - 0.001529 * phi4)));\n        const y = lat * (1.007226 + phi2 * (0.015085 + phi4 * (-0.044475 + 0.028874 * phi2 - 0.005916 * phi4)));\n\n        return {\n            x: (x / Math.PI + 0.5) * 0.5,\n            y: 1 - (y / Math.PI + 1) * 0.5,\n            z: 0\n        };\n    }\n\n    unproject(x: number, y: number): LngLat {\n        // based on https://github.com/d3/d3-geo, MIT-licensed\n        x = (2 * x - 0.5) * Math.PI;\n        y = (2 * (1 - y) - 1) * Math.PI;\n        const epsilon = 1e-6;\n        let phi = y;\n        let i = 25;\n        let delta = 0;\n        let phi2 = phi * phi;\n\n        do {\n            phi2 = phi * phi;\n            const phi4 = phi2 * phi2;\n            delta = (phi * (1.007226 + phi2 * (0.015085 + phi4 * (-0.044475 + 0.028874 * phi2 - 0.005916 * phi4))) - y) /\n                (1.007226 + phi2 * (0.015085 * 3 + phi4 * (-0.044475 * 7 + 0.028874 * 9 * phi2 - 0.005916 * 11 * phi4)));\n            phi = clamp(phi - delta, -maxPhi, maxPhi);\n        } while (Math.abs(delta) > epsilon && --i > 0);\n\n        phi2 = phi * phi;\n        const lambda = x / (0.8707 + phi2 * (-0.131979 + phi2 * (-0.013791 + phi2 * phi2 * phi2 * (0.003971 - 0.001529 * phi2))));\n\n        const lng = clamp(radToDeg(lambda), -180, 180);\n        const lat = radToDeg(phi);\n\n        return new LngLat(lng, lat);\n    }\n}\n","import LngLat from '../lng_lat';\nimport {clamp, degToRad, radToDeg} from '../../util/util';\nimport {MAX_MERCATOR_LATITUDE} from '../mercator_coordinate';\nimport Projection from './projection';\n\nimport type {ProjectedPoint} from './projection';\n\nconst maxPhi = degToRad(MAX_MERCATOR_LATITUDE);\n\nexport default class WinkelTripel extends Projection {\n\n    project(lng: number, lat: number): ProjectedPoint {\n        lat = degToRad(lat);\n        lng = degToRad(lng);\n        const cosLat = Math.cos(lat);\n        const twoOverPi = 2 / Math.PI;\n        const alpha = Math.acos(cosLat * Math.cos(lng / 2));\n        const sinAlphaOverAlpha = Math.sin(alpha) / alpha;\n        const x = 0.5 * (lng * twoOverPi + (2 * cosLat * Math.sin(lng / 2)) / sinAlphaOverAlpha) || 0;\n        const y = 0.5 * (lat + Math.sin(lat) / sinAlphaOverAlpha) || 0;\n        return {\n            x: (x / Math.PI + 0.5) * 0.5,\n            y: 1 - (y / Math.PI + 1) * 0.5,\n            z: 0\n        };\n    }\n\n    unproject(x: number, y: number): LngLat {\n        // based on https://github.com/d3/d3-geo-projection, MIT-licensed\n        x = (2 * x - 0.5) * Math.PI;\n        y = (2 * (1 - y) - 1) * Math.PI;\n        let lambda = x;\n        let phi = y;\n        let i = 25;\n        const epsilon = 1e-6;\n        let dlambda = 0, dphi = 0;\n        do {\n            const cosphi = Math.cos(phi),\n                sinphi = Math.sin(phi),\n                sinphi2 = 2 * sinphi * cosphi,\n                sin2phi = sinphi * sinphi,\n                cos2phi = cosphi * cosphi,\n                coslambda2 = Math.cos(lambda / 2),\n                sinlambda2 = Math.sin(lambda / 2),\n                sinlambda = 2 * coslambda2 * sinlambda2,\n                sin2lambda2 = sinlambda2 * sinlambda2,\n                C = 1 - cos2phi * coslambda2 * coslambda2,\n                F = C ? 1 / C : 0,\n                E = C ? Math.acos(cosphi * coslambda2) * Math.sqrt(1 / C) : 0,\n                fx = 0.5 * (2 * E * cosphi * sinlambda2 + lambda * 2 / Math.PI) - x,\n                fy = 0.5 * (E * sinphi + phi) - y,\n                dxdlambda = 0.5 * F * (cos2phi * sin2lambda2 + E * cosphi * coslambda2 * sin2phi) + 1 / Math.PI,\n                dxdphi = F * (sinlambda * sinphi2 / 4 - E * sinphi * sinlambda2),\n                dydlambda = 0.125 * F * (sinphi2 * sinlambda2 - E * sinphi * cos2phi * sinlambda),\n                dydphi = 0.5 * F * (sin2phi * coslambda2 + E * sin2lambda2 * cosphi) + 0.5,\n                denominator = dxdphi * dydlambda - dydphi * dxdlambda;\n\n            dlambda = (fy * dxdphi - fx * dydphi) / denominator;\n            dphi = (fx * dydlambda - fy * dxdlambda) / denominator;\n            lambda = clamp(lambda - dlambda, -Math.PI, Math.PI);\n            phi = clamp(phi - dphi, -maxPhi, maxPhi);\n\n        } while ((Math.abs(dlambda) > epsilon || Math.abs(dphi) > epsilon) && --i > 0);\n\n        return new LngLat(radToDeg(lambda), radToDeg(phi));\n    }\n}\n","import LngLat from '../lng_lat';\nimport {clamp, degToRad, radToDeg} from '../../util/util';\nimport {MAX_MERCATOR_LATITUDE} from '../mercator_coordinate';\nimport Projection from './projection';\n\nimport type {ProjectionSpecification} from '../../style-spec/types';\nimport type {ProjectedPoint} from './projection';\n\nexport default class CylindricalEqualArea extends Projection {\n    cosPhi: number;\n    scale: number;\n\n    constructor(options: ProjectionSpecification) {\n        super(options);\n        this.center = options.center || [0, 0];\n        this.parallels = options.parallels || [0, 0];\n        this.cosPhi = Math.max(0.01, Math.cos(degToRad(this.parallels[0])));\n        // scale coordinates between 0 and 1 to avoid constraint issues\n        this.scale = 1 / (2 * Math.max(Math.PI * this.cosPhi, 1 / this.cosPhi));\n        this.wrap = true;\n        this.supportsWorldCopies = true;\n    }\n\n    project(lng: number, lat: number): ProjectedPoint {\n        const {scale, cosPhi} = this;\n        const x = degToRad(lng) * cosPhi;\n        const y = Math.sin(degToRad(lat)) / cosPhi;\n\n        return {\n            x: (x * scale) + 0.5,\n            y: (-y * scale) + 0.5,\n            z: 0\n        };\n    }\n\n    unproject(x: number, y: number): LngLat {\n        const {scale, cosPhi} = this;\n        const x_ = (x - 0.5) / scale;\n        const y_ = -(y - 0.5) / scale;\n        const lng = clamp(radToDeg(x_) / cosPhi, -180, 180);\n        const y2 = y_ * cosPhi;\n        const y3 = Math.asin(clamp(y2, -1, 1));\n        const lat = clamp(radToDeg(y3), -MAX_MERCATOR_LATITUDE, MAX_MERCATOR_LATITUDE);\n\n        return new LngLat(lng, lat);\n    }\n}\n","import {mat4, vec3} from 'gl-matrix';\nimport EXTENT from '../../style-spec/data/extent';\nimport LngLat, {latLngToECEF} from '../lng_lat';\nimport {degToRad} from '../../util/util';\nimport MercatorCoordinate, {\n    mercatorZfromAltitude,\n} from '../mercator_coordinate';\nimport Mercator from './mercator';\nimport Point from '@mapbox/point-geometry';\nimport {farthestPixelDistanceOnPlane, farthestPixelDistanceOnSphere} from './far_z';\nimport {number as interpolate} from '../../style-spec/util/interpolate';\nimport {\n    globeTileBounds,\n    globeNormalizeECEF,\n    globeDenormalizeECEF,\n    globeECEFNormalizationScale,\n    globeToMercatorTransition,\n    globePointCoordinate,\n    tileCoordToECEF,\n    globeMetersToEcef\n} from './globe_util';\nimport {GLOBE_SCALE_MATCH_LATITUDE} from './globe_constants';\n\nimport type Transform from '../transform';\nimport type {ElevationScale} from './projection';\nimport type {ProjectionSpecification} from '../../style-spec/types';\nimport type {CanonicalTileID, UnwrappedTileID} from '../../source/tile_id';\n\nexport default class Globe extends Mercator {\n\n    constructor(options: ProjectionSpecification) {\n        super(options);\n        this.requiresDraping = true;\n        this.supportsWorldCopies = false;\n        this.supportsFog = true;\n        this.zAxisUnit = \"pixels\";\n        this.unsupportedLayers = ['debug'];\n        this.range = [3, 5];\n    }\n\n    projectTilePoint(x: number, y: number, id: CanonicalTileID): {\n        x: number;\n        y: number;\n        z: number;\n    } {\n        const pos = tileCoordToECEF(x, y, id);\n        const bounds = globeTileBounds(id);\n        const normalizationMatrix = globeNormalizeECEF(bounds);\n        // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'ReadonlyMat4'.\n        vec3.transformMat4(pos, pos, normalizationMatrix);\n\n        return {x: pos[0], y: pos[1], z: pos[2]};\n    }\n\n    locationPoint(tr: Transform, lngLat: LngLat): Point {\n        const pos = latLngToECEF(lngLat.lat, lngLat.lng);\n        const up = vec3.normalize([] as any, pos);\n\n        const elevation = tr.elevation ?\n            tr.elevation.getAtPointOrZero(tr.locationCoordinate(lngLat), tr._centerAltitude) :\n            tr._centerAltitude;\n\n        const upScale = mercatorZfromAltitude(1, 0) * EXTENT * elevation;\n        vec3.scaleAndAdd(pos, pos, up, upScale);\n        // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'mat4'.\n        const matrix = mat4.identity(new Float64Array(16));\n        // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'ReadonlyMat4'.\n        mat4.multiply(matrix, tr.pixelMatrix, tr.globeMatrix);\n        vec3.transformMat4(pos, pos, matrix);\n\n        return new Point(pos[0], pos[1]);\n    }\n\n    pixelsPerMeter(lat: number, worldSize: number): number {\n        return mercatorZfromAltitude(1, 0) * worldSize;\n    }\n\n    pixelSpaceConversion(lat: number, worldSize: number, interpolationT: number): number {\n        // Using only the center latitude to determine scale causes the globe to rapidly change\n        // size as you pan up and down. As you approach the pole, the globe's size approaches infinity.\n        // This is because zoom levels are based on mercator.\n        //\n        // Instead, use a fixed reference latitude at lower zoom levels. And transition between\n        // this latitude and the center's latitude as you zoom in. This is a compromise that\n        // makes globe view more usable with existing camera parameters, styles and data.\n        const centerScale = mercatorZfromAltitude(1, lat) * worldSize;\n        const referenceScale = mercatorZfromAltitude(1, GLOBE_SCALE_MATCH_LATITUDE) * worldSize;\n        const combinedScale = interpolate(referenceScale, centerScale, interpolationT);\n        return this.pixelsPerMeter(lat, worldSize) / combinedScale;\n    }\n\n    createTileMatrix(tr: Transform, worldSize: number, id: UnwrappedTileID): Float64Array {\n        const decode = globeDenormalizeECEF(globeTileBounds(id.canonical));\n        // @ts-expect-error - TS2322 - Type 'mat4' is not assignable to type 'Float64Array'. | TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'mat4'.\n        return mat4.multiply(new Float64Array(16), tr.globeMatrix, decode);\n    }\n\n    createInversionMatrix(tr: Transform, id: CanonicalTileID): Float32Array {\n        const {center} = tr;\n        const matrix = globeNormalizeECEF(globeTileBounds(id));\n        // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'mat4'.\n        mat4.rotateY(matrix, matrix, degToRad(center.lng));\n        // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'mat4'.\n        mat4.rotateX(matrix, matrix, degToRad(center.lat));\n        // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'mat4'.\n        mat4.scale(matrix, matrix, [tr._pixelsPerMercatorPixel, tr._pixelsPerMercatorPixel, 1.0]);\n        return Float32Array.from(matrix);\n    }\n\n    pointCoordinate(tr: Transform, x: number, y: number, _: number): MercatorCoordinate {\n        const coord = globePointCoordinate(tr, x, y, true);\n        if (!coord) { return new MercatorCoordinate(0, 0); } // This won't happen, is here for Flow\n        return coord;\n    }\n\n    pointCoordinate3D(tr: Transform, x: number, y: number): vec3 | null | undefined {\n        const coord = this.pointCoordinate(tr, x, y, 0);\n        return [coord.x, coord.y, coord.z];\n    }\n\n    isPointAboveHorizon(tr: Transform, p: Point): boolean {\n        const raycastOnGlobe = globePointCoordinate(tr, p.x, p.y, false);\n        return !raycastOnGlobe;\n    }\n\n    farthestPixelDistance(tr: Transform): number {\n        const pixelsPerMeter = this.pixelsPerMeter(tr.center.lat, tr.worldSize);\n        const globePixelDistance = farthestPixelDistanceOnSphere(tr, pixelsPerMeter);\n        const t = globeToMercatorTransition(tr.zoom);\n        if (t > 0.0) {\n            const mercatorPixelsPerMeter = mercatorZfromAltitude(1, tr.center.lat) * tr.worldSize;\n            const mercatorPixelDistance = farthestPixelDistanceOnPlane(tr, mercatorPixelsPerMeter);\n            const pixelRadius = tr.worldSize / (2.0 * Math.PI);\n            const approxTileArcHalfAngle = Math.max(tr.width, tr.height) / tr.worldSize * Math.PI;\n            const padding = pixelRadius * (1.0 - Math.cos(approxTileArcHalfAngle));\n\n            // During transition to mercator we would like to keep\n            // the far plane lower to ensure that geometries (e.g. circles) that are far away and are not supposed\n            // to be rendered get culled out correctly. see https://github.com/mapbox/mapbox-gl-js/issues/11476\n            // To achieve this we dampen the interpolation.\n            return interpolate(globePixelDistance, mercatorPixelDistance + padding, Math.pow(t, 10.0));\n        }\n        return globePixelDistance;\n    }\n\n    upVector(id: CanonicalTileID, x: number, y: number): [number, number, number] {\n        return tileCoordToECEF(x, y, id, 1);\n    }\n\n    upVectorScale(id: CanonicalTileID): ElevationScale {\n        return {metersToTile: globeMetersToEcef(globeECEFNormalizationScale(globeTileBounds(id)))};\n    }\n}\n","import Albers from './albers';\nimport EqualEarth from './equal_earth';\nimport Equirectangular from './equirectangular';\nimport LambertConformalConic from './lambert';\nimport Mercator from './mercator';\nimport NaturalEarth from './natural_earth';\nimport WinkelTripel from './winkel_tripel';\nimport CylindricalEqualArea from './cylindrical_equal_area';\nimport Globe from './globe';\n\nimport type {ProjectionSpecification} from '../../style-spec/types';\nimport type Projection from './projection';\n\nexport function getProjection(config: ProjectionSpecification): Projection {\n\n    const parallels = config.parallels;\n    const isDegenerateConic = parallels ? Math.abs(parallels[0] + parallels[1]) < 0.01 : false;\n\n    switch (config.name) {\n    case 'mercator':\n        return new Mercator(config);\n    case 'equirectangular':\n        return new Equirectangular(config);\n    case 'naturalEarth':\n        return new NaturalEarth(config);\n    case 'equalEarth':\n        return new EqualEarth(config);\n    case 'winkelTripel':\n        return new WinkelTripel(config);\n    case 'albers':\n        return isDegenerateConic ? new CylindricalEqualArea(config) : new Albers(config);\n    case 'lambertConformalConic':\n        return isDegenerateConic ? new CylindricalEqualArea(config) : new LambertConformalConic(config);\n    case 'globe':\n        return new Globe(config);\n    }\n\n    throw new Error(`Invalid projection name: ${config.name}`);\n}\n","import {\n    symbolLayoutAttributes,\n    symbolGlobeExtAttributes,\n    collisionVertexAttributes,\n    collisionVertexAttributesExt,\n    collisionBoxLayout,\n    dynamicLayoutAttributes,\n    iconTransitioningAttributes,\n    zOffsetAttributes\n} from './symbol_attributes';\n\nimport {SymbolLayoutArray,\n    SymbolGlobeExtArray,\n    SymbolDynamicLayoutArray,\n    SymbolOpacityArray,\n    CollisionBoxLayoutArray,\n    CollisionVertexExtArray,\n    CollisionVertexArray,\n    PlacedSymbolArray,\n    SymbolInstanceArray,\n    GlyphOffsetArray,\n    SymbolLineVertexArray,\n    SymbolIconTransitioningArray,\n    ZOffsetVertexArray\n} from '../array_types';\n\nimport ONE_EM from '../../symbol/one_em';\nimport * as symbolSize from '../../symbol/symbol_size';\nimport Point from '@mapbox/point-geometry';\nimport SegmentVector from '../segment';\nimport {ProgramConfigurationSet} from '../program_configuration';\nimport {TriangleIndexArray, LineIndexArray} from '../index_array_type';\nimport transformText from '../../symbol/transform_text';\nimport mergeLines from '../../symbol/mergelines';\nimport {allowsVerticalWritingMode, stringContainsRTLText} from '../../util/script_detection';\nimport {WritingMode} from '../../symbol/shaping';\nimport loadGeometry from '../load_geometry';\nimport toEvaluationFeature from '../evaluation_feature';\nimport {VectorTileFeature} from '@mapbox/vector-tile';\nconst vectorTileFeatureTypes = VectorTileFeature.types;\nimport {verticalizedCharacterMap} from '../../util/verticalize_punctuation';\nimport Anchor from '../../symbol/anchor';\nimport {getSizeData} from '../../symbol/symbol_size';\nimport {MAX_PACKED_SIZE} from '../../symbol/symbol_layout';\nimport {register} from '../../util/web_worker_transfer';\nimport EvaluationParameters from '../../style/evaluation_parameters';\nimport Formatted from '../../style-spec/expression/types/formatted';\nimport ResolvedImage from '../../style-spec/expression/types/resolved_image';\nimport {plugin as globalRTLTextPlugin, getRTLTextPluginStatus} from '../../source/rtl_text_plugin';\nimport {resamplePred} from '../../geo/projection/resample';\nimport {tileCoordToECEF} from '../../geo/projection/globe_util';\nimport {getProjection} from '../../geo/projection/index';\nimport {mat4, vec3} from 'gl-matrix';\nimport assert from 'assert';\nimport {ReplacementSource, regionsEquals} from '../../../3d-style/source/replacement_source';\n\nimport type SymbolStyleLayer from '../../style/style_layer/symbol_style_layer';\n\nimport type {Class} from '../../types/class';\nimport type {ProjectionSpecification} from '../../style-spec/types';\nimport type Projection from '../../geo/projection/projection';\nimport type {CanonicalTileID, OverscaledTileID, UnwrappedTileID} from '../../source/tile_id';\nimport type {\n    Bucket,\n    BucketParameters,\n    IndexedFeature,\n    PopulateParameters\n} from '../bucket';\nimport type {CollisionBoxArray, CollisionBox, SymbolInstance, StructArrayLayout1f4} from '../array_types';\nimport type {StructArray, StructArrayMember} from '../../util/struct_array';\nimport type Context from '../../gl/context';\nimport type IndexBuffer from '../../gl/index_buffer';\nimport type VertexBuffer from '../../gl/vertex_buffer';\nimport type {SymbolQuad} from '../../symbol/quads';\nimport type {SizeData} from '../../symbol/symbol_size';\nimport type {FeatureStates} from '../../source/source_state';\nimport type {TileTransform} from '../../geo/projection/tile_transform';\nimport type {TileFootprint} from '../../../3d-style/util/conflation';\nimport type {LUT} from '../../util/lut';\n\nexport type SingleCollisionBox = {\n    x1: number;\n    y1: number;\n    x2: number;\n    y2: number;\n    padding: number;\n    projectedAnchorX: number;\n    projectedAnchorY: number;\n    projectedAnchorZ: number;\n    tileAnchorX: number;\n    tileAnchorY: number;\n    elevation?: number;\n    tileID?: OverscaledTileID;\n};\n\nimport type {SpritePositions} from '../../util/image';\nimport type {VectorTileLayer} from '@mapbox/vector-tile';\n\nimport {clamp} from '../../util/util';\n\nexport type CollisionArrays = {\n    textBox?: SingleCollisionBox;\n    verticalTextBox?: SingleCollisionBox;\n    iconBox?: SingleCollisionBox;\n    verticalIconBox?: SingleCollisionBox;\n    textFeatureIndex?: number;\n    verticalTextFeatureIndex?: number;\n    iconFeatureIndex?: number;\n    verticalIconFeatureIndex?: number;\n};\n\nexport type SymbolFeature = {\n    sortKey: number | undefined;\n    text: Formatted | undefined;\n    icon: ResolvedImage | null | undefined;\n    index: number;\n    sourceLayerIndex: number;\n    geometry: Array<Array<Point>>;\n    properties: any;\n    type: 'Point' | 'LineString' | 'Polygon';\n    id?: any;\n};\n\nexport type SortKeyRange = {\n    sortKey: number;\n    symbolInstanceStart: number;\n    symbolInstanceEnd: number;\n};\n\ntype LineVertexRange = {\n    lineLength: number;\n    lineStartIndex: number;\n};\n\n// Opacity arrays are frequently updated but don't contain a lot of information, so we pack them\n// tight. Each Uint32 is actually four duplicate Uint8s for the four corners of a glyph\n// 7 bits are for the current opacity, and the lowest bit is the target opacity\n\n// actually defined in symbol_attributes.js\n// const placementOpacityAttributes = [\n//     { name: 'a_fade_opacity', components: 1, type: 'Uint32' }\n// ];\nconst shaderOpacityAttributes = [\n    {name: 'a_fade_opacity', components: 1, type: 'Uint8', offset: 0}\n];\n\nfunction addVertex(array: SymbolLayoutArray, tileAnchorX: number, tileAnchorY: number, ox: number, oy: number, tx: number, ty: number, sizeVertex: any, isSDF: boolean, pixelOffsetX: number, pixelOffsetY: number, minFontScaleX: number, minFontScaleY: number) {\n    const aSizeX = sizeVertex ? Math.min(MAX_PACKED_SIZE, Math.round(sizeVertex[0])) : 0;\n    const aSizeY = sizeVertex ? Math.min(MAX_PACKED_SIZE, Math.round(sizeVertex[1])) : 0;\n\n    array.emplaceBack(\n        // a_pos_offset\n        tileAnchorX,\n        tileAnchorY,\n        Math.round(ox * 32),\n        Math.round(oy * 32),\n\n        // a_data\n        tx, // x coordinate of symbol on glyph atlas texture\n        ty, // y coordinate of symbol on glyph atlas texture\n        (aSizeX << 1) + (isSDF ? 1 : 0),\n        aSizeY,\n        pixelOffsetX * 16,\n        pixelOffsetY * 16,\n        minFontScaleX * 256,\n        minFontScaleY * 256\n    );\n}\n\nfunction addTransitioningVertex(array: SymbolIconTransitioningArray, tx: number, ty: number) {\n    array.emplaceBack(tx, ty);\n}\n\nfunction addGlobeVertex(array: SymbolGlobeExtArray, projAnchorX: number, projAnchorY: number, projAnchorZ: number, normX: number, normY: number, normZ: number) {\n    array.emplaceBack(\n        // a_globe_anchor\n        projAnchorX,\n        projAnchorY,\n        projAnchorZ,\n\n        // a_globe_normal\n        normX,\n        normY,\n        normZ\n    );\n}\n\nfunction updateGlobeVertexNormal(array: SymbolGlobeExtArray, vertexIdx: number, normX: number, normY: number, normZ: number) {\n    // Modify float32 array directly. 20 bytes per entry, 3xInt16 for position, 3xfloat32 for normal\n    const offset = vertexIdx * 5 + 2;\n    array.float32[offset + 0] = normX;\n    array.float32[offset + 1] = normY;\n    array.float32[offset + 2] = normZ;\n}\n\nfunction addDynamicAttributes(dynamicLayoutVertexArray: StructArray, x: number, y: number, z: number, angle: number) {\n    dynamicLayoutVertexArray.emplaceBack(x, y, z, angle);\n    dynamicLayoutVertexArray.emplaceBack(x, y, z, angle);\n    dynamicLayoutVertexArray.emplaceBack(x, y, z, angle);\n    dynamicLayoutVertexArray.emplaceBack(x, y, z, angle);\n}\n\nfunction containsRTLText(formattedText: Formatted): boolean {\n    for (const section of formattedText.sections) {\n        if (stringContainsRTLText(section.text)) {\n            return true;\n        }\n    }\n    return false;\n}\n\nexport class SymbolBuffers {\n    layoutVertexArray: SymbolLayoutArray;\n    layoutVertexBuffer: VertexBuffer;\n\n    indexArray: TriangleIndexArray;\n    indexBuffer: IndexBuffer;\n\n    programConfigurations: ProgramConfigurationSet<SymbolStyleLayer>;\n    segments: SegmentVector;\n\n    dynamicLayoutVertexArray: SymbolDynamicLayoutArray;\n    dynamicLayoutVertexBuffer: VertexBuffer;\n\n    opacityVertexArray: SymbolOpacityArray;\n    opacityVertexBuffer: VertexBuffer;\n\n    zOffsetVertexArray: ZOffsetVertexArray;\n    zOffsetVertexBuffer: VertexBuffer;\n\n    iconTransitioningVertexArray: SymbolIconTransitioningArray;\n    iconTransitioningVertexBuffer: VertexBuffer | null | undefined;\n\n    globeExtVertexArray: SymbolGlobeExtArray;\n    globeExtVertexBuffer: VertexBuffer | null | undefined;\n\n    placedSymbolArray: PlacedSymbolArray;\n\n    constructor(programConfigurations: ProgramConfigurationSet<SymbolStyleLayer>) {\n        this.layoutVertexArray = new SymbolLayoutArray();\n        this.indexArray = new TriangleIndexArray();\n        this.programConfigurations = programConfigurations;\n        this.segments = new SegmentVector();\n        this.dynamicLayoutVertexArray = new SymbolDynamicLayoutArray();\n        this.opacityVertexArray = new SymbolOpacityArray();\n        this.placedSymbolArray = new PlacedSymbolArray();\n        this.iconTransitioningVertexArray = new SymbolIconTransitioningArray();\n        this.globeExtVertexArray = new SymbolGlobeExtArray();\n        this.zOffsetVertexArray = new ZOffsetVertexArray();\n    }\n\n    isEmpty(): boolean {\n        return this.layoutVertexArray.length === 0 &&\n            this.indexArray.length === 0 &&\n            this.dynamicLayoutVertexArray.length === 0 &&\n            this.opacityVertexArray.length === 0 &&\n            this.iconTransitioningVertexArray.length === 0;\n    }\n\n    upload(context: Context, dynamicIndexBuffer: boolean, upload?: boolean, update?: boolean, createZOffsetBuffer?: boolean) {\n        if (this.isEmpty()) {\n            return;\n        }\n\n        if (upload) {\n            this.layoutVertexBuffer = context.createVertexBuffer(this.layoutVertexArray, symbolLayoutAttributes.members);\n            this.indexBuffer = context.createIndexBuffer(this.indexArray, dynamicIndexBuffer);\n            this.dynamicLayoutVertexBuffer = context.createVertexBuffer(this.dynamicLayoutVertexArray, dynamicLayoutAttributes.members, true);\n            // @ts-expect-error - TS2345 - Argument of type '{ name: string; components: number; type: string; offset: number; }[]' is not assignable to parameter of type 'readonly StructArrayMember[]'.\n            this.opacityVertexBuffer = context.createVertexBuffer(this.opacityVertexArray, shaderOpacityAttributes, true);\n            if (this.iconTransitioningVertexArray.length > 0) {\n                this.iconTransitioningVertexBuffer = context.createVertexBuffer(this.iconTransitioningVertexArray, iconTransitioningAttributes.members, true);\n            }\n            if (this.globeExtVertexArray.length > 0) {\n                this.globeExtVertexBuffer = context.createVertexBuffer(this.globeExtVertexArray, symbolGlobeExtAttributes.members, true);\n            }\n            if (!this.zOffsetVertexBuffer && (this.zOffsetVertexArray.length > 0 || !!createZOffsetBuffer)) {\n                this.zOffsetVertexBuffer = context.createVertexBuffer(this.zOffsetVertexArray, zOffsetAttributes.members, true);\n            }\n            // This is a performance hack so that we can write to opacityVertexArray with uint32s\n            // even though the shaders read uint8s\n            this.opacityVertexBuffer.itemSize = 1;\n        }\n        if (upload || update) {\n            this.programConfigurations.upload(context);\n        }\n    }\n\n    destroy() {\n        if (!this.layoutVertexBuffer) return;\n        this.layoutVertexBuffer.destroy();\n        this.indexBuffer.destroy();\n        this.programConfigurations.destroy();\n        this.segments.destroy();\n        this.dynamicLayoutVertexBuffer.destroy();\n        this.opacityVertexBuffer.destroy();\n        if (this.iconTransitioningVertexBuffer) {\n            this.iconTransitioningVertexBuffer.destroy();\n        }\n        if (this.globeExtVertexBuffer) {\n            this.globeExtVertexBuffer.destroy();\n        }\n        if (this.zOffsetVertexBuffer) {\n            this.zOffsetVertexBuffer.destroy();\n        }\n    }\n}\n\nregister(SymbolBuffers, 'SymbolBuffers');\n\nclass CollisionBuffers {\n    layoutVertexArray: StructArray;\n    layoutAttributes: Array<StructArrayMember>;\n    layoutVertexBuffer: VertexBuffer;\n\n    indexArray: TriangleIndexArray | LineIndexArray;\n    indexBuffer: IndexBuffer;\n\n    segments: SegmentVector;\n\n    collisionVertexArray: CollisionVertexArray;\n    collisionVertexBuffer: VertexBuffer;\n\n    collisionVertexArrayExt: CollisionVertexExtArray;\n    collisionVertexBufferExt: VertexBuffer;\n\n    constructor(LayoutArray: Class<StructArray>,\n                layoutAttributes: Array<StructArrayMember>,\n                IndexArray: Class<TriangleIndexArray | LineIndexArray>) {\n        this.layoutVertexArray = new LayoutArray();\n        this.layoutAttributes = layoutAttributes;\n        this.indexArray = new IndexArray();\n        this.segments = new SegmentVector();\n        this.collisionVertexArray = new CollisionVertexArray();\n        this.collisionVertexArrayExt = new CollisionVertexExtArray();\n    }\n\n    upload(context: Context) {\n        this.layoutVertexBuffer = context.createVertexBuffer(this.layoutVertexArray, this.layoutAttributes);\n        this.indexBuffer = context.createIndexBuffer(this.indexArray);\n        this.collisionVertexBuffer = context.createVertexBuffer(this.collisionVertexArray, collisionVertexAttributes.members, true);\n        this.collisionVertexBufferExt = context.createVertexBuffer(this.collisionVertexArrayExt, collisionVertexAttributesExt.members, true);\n    }\n\n    destroy() {\n        if (!this.layoutVertexBuffer) return;\n        this.layoutVertexBuffer.destroy();\n        this.indexBuffer.destroy();\n        this.segments.destroy();\n        this.collisionVertexBuffer.destroy();\n        this.collisionVertexBufferExt.destroy();\n    }\n}\n\nregister(CollisionBuffers, 'CollisionBuffers');\n\n/**\n * Unlike other buckets, which simply implement #addFeature with type-specific\n * logic for (essentially) triangulating feature geometries, SymbolBucket\n * requires specialized behavior:\n *\n * 1. WorkerTile#parse(), the logical owner of the bucket creation process,\n *    calls SymbolBucket#populate(), which resolves text and icon tokens on\n *    each feature, adds each glyphs and symbols needed to the passed-in\n *    collections options.glyphDependencies and options.iconDependencies, and\n *    stores the feature data for use in subsequent step (this.features).\n *\n * 2. WorkerTile asynchronously requests from the main thread all of the glyphs\n *    and icons needed (by this bucket and any others). When glyphs and icons\n *    have been received, the WorkerTile creates a CollisionIndex and invokes:\n *\n * 3. performSymbolLayout(bucket, stacks, icons) perform texts shaping and\n *    layout on a Symbol Bucket. This step populates:\n *      `this.symbolInstances`: metadata on generated symbols\n *      `collisionBoxArray`: collision data for use by foreground\n *      `this.text`: SymbolBuffers for text symbols\n *      `this.icons`: SymbolBuffers for icons\n *      `this.iconCollisionBox`: Debug SymbolBuffers for icon collision boxes\n *      `this.textCollisionBox`: Debug SymbolBuffers for text collision boxes\n *    The results are sent to the foreground for rendering\n *\n * 4. Placement.updateBucketOpacities() is run on the foreground,\n *    and uses the CollisionIndex along with current camera settings to determine\n *    which symbols can actually show on the map. Collided symbols are hidden\n *    using a dynamic \"OpacityVertexArray\".\n *\n * @private\n */\nclass SymbolBucket implements Bucket {\n    static addDynamicAttributes: typeof addDynamicAttributes;\n\n    collisionBoxArray: CollisionBoxArray;\n    zoom: number;\n    lut: LUT | null;\n    overscaling: number;\n    layers: Array<SymbolStyleLayer>;\n    layerIds: Array<string>;\n    stateDependentLayers: Array<SymbolStyleLayer>;\n    stateDependentLayerIds: Array<string>;\n\n    index: number;\n    sdfIcons: boolean;\n    iconsInText: boolean;\n    iconsNeedLinear: boolean;\n    bucketInstanceId: number;\n    justReloaded: boolean;\n    hasPattern: boolean;\n    fullyClipped: boolean;\n\n    textSizeData: SizeData;\n    iconSizeData: SizeData;\n\n    glyphOffsetArray: GlyphOffsetArray;\n    lineVertexArray: SymbolLineVertexArray;\n    features: Array<SymbolFeature>;\n    symbolInstances: SymbolInstanceArray;\n    collisionArrays: Array<CollisionArrays>;\n    sortKeyRanges: Array<SortKeyRange>;\n    pixelRatio: number;\n    tilePixelRatio: number;\n    compareText: {\n        [_: string]: Array<Point>;\n    };\n    fadeStartTime: number;\n    sortFeaturesByKey: boolean;\n    sortFeaturesByY: boolean;\n    canOverlap: boolean;\n    sortedAngle: number;\n    featureSortOrder: Array<number>;\n\n    collisionCircleArray: Array<number>;\n    placementInvProjMatrix: mat4;\n    placementViewportMatrix: mat4;\n\n    text: SymbolBuffers;\n    icon: SymbolBuffers;\n    textCollisionBox: CollisionBuffers;\n    iconCollisionBox: CollisionBuffers;\n    uploaded: boolean;\n    sourceLayerIndex: number;\n    sourceID: string;\n    symbolInstanceIndexes: Array<number>;\n    writingModes: Array<number>;\n    allowVerticalPlacement: boolean;\n    hasRTLText: boolean;\n    projection: ProjectionSpecification;\n    projectionInstance: Projection | null | undefined;\n    hasAnyIconTextFit: boolean;\n    hasAnyZOffset: boolean;\n    symbolInstanceIndexesSortedZOffset: Array<number>;\n    zOffsetSortDirty: boolean;\n    zOffsetBuffersNeedUpload: boolean;\n\n    activeReplacements: Array<any>;\n    replacementUpdateTime: number;\n\n    constructor(options: BucketParameters<SymbolStyleLayer>) {\n        this.collisionBoxArray = options.collisionBoxArray;\n        this.zoom = options.zoom;\n        this.lut = options.lut;\n        this.overscaling = options.overscaling;\n        this.layers = options.layers;\n        this.layerIds = this.layers.map(layer => layer.fqid);\n        this.index = options.index;\n        this.pixelRatio = options.pixelRatio;\n        this.sourceLayerIndex = options.sourceLayerIndex;\n        this.hasPattern = false;\n        this.hasRTLText = false;\n        this.fullyClipped = false;\n        this.hasAnyIconTextFit = false;\n        this.sortKeyRanges = [];\n\n        this.collisionCircleArray = [];\n        this.placementInvProjMatrix = mat4.identity([] as any);\n        this.placementViewportMatrix = mat4.identity([] as any);\n\n        const layer = this.layers[0];\n        const unevaluatedLayoutValues = layer._unevaluatedLayout._values;\n\n        this.textSizeData = getSizeData(this.zoom, unevaluatedLayoutValues['text-size']);\n\n        this.iconSizeData = getSizeData(this.zoom, unevaluatedLayoutValues['icon-size']);\n\n        const layout = this.layers[0].layout;\n        const sortKey = layout.get('symbol-sort-key');\n        const zOrder = layout.get('symbol-z-order');\n\n        this.canOverlap =\n            layout.get('text-allow-overlap') ||\n            layout.get('icon-allow-overlap') ||\n            layout.get('text-ignore-placement') ||\n            layout.get('icon-ignore-placement');\n\n        this.sortFeaturesByKey = zOrder !== 'viewport-y' && sortKey.constantOr(1) !== undefined;\n        const zOrderByViewportY = zOrder === 'viewport-y' || (zOrder === 'auto' && !this.sortFeaturesByKey);\n        this.sortFeaturesByY = zOrderByViewportY && this.canOverlap;\n\n        this.writingModes = layout.get('text-writing-mode').map(wm => WritingMode[wm]);\n\n        this.stateDependentLayerIds = this.layers.filter((l) => l.isStateDependent()).map((l) => l.id);\n\n        this.sourceID = options.sourceID;\n        this.projection = options.projection;\n        this.hasAnyZOffset = false;\n        this.zOffsetSortDirty = false;\n\n        this.zOffsetBuffersNeedUpload = layout.get('symbol-z-elevate');\n\n        this.activeReplacements = [];\n        this.replacementUpdateTime = 0;\n    }\n\n    createArrays() {\n        this.text = new SymbolBuffers(new ProgramConfigurationSet(this.layers, {zoom: this.zoom, lut: this.lut}, (property) => /^text/.test(property)));\n        this.icon = new SymbolBuffers(new ProgramConfigurationSet(this.layers, {zoom: this.zoom, lut: this.lut}, (property) => /^icon/.test(property)));\n\n        this.glyphOffsetArray = new GlyphOffsetArray();\n        this.lineVertexArray = new SymbolLineVertexArray();\n        this.symbolInstances = new SymbolInstanceArray();\n    }\n\n    calculateGlyphDependencies(text: string, stack: {\n        [_: number]: boolean;\n    }, textAlongLine: boolean, allowVerticalPlacement: boolean, doesAllowVerticalWritingMode: boolean) {\n        for (let i = 0; i < text.le