y),\n            sizeVertex ? sizeVertex[0] : 0, sizeVertex ? sizeVertex[1] : 0,\n            lineOffset[0], lineOffset[1],\n            writingMode,\n            // placedOrientation is null initially; will be updated to horizontal(1)/vertical(2) if placed\n            0,\n            (false as any),\n            // The crossTileID is only filled/used on the foreground for dynamic text anchors\n            0,\n            associatedIconIndex,\n            // flipState is unknown initially; will be updated to flipRequired(1)/flipNotRequired(2) during line label reprojection\n            0\n        );\n    }\n\n    _commitLayoutVertex(array: StructArray, boxTileAnchorX: number, boxTileAnchorY: number, boxTileAnchorZ: number, tileAnchorX: number, tileAnchorY: number, extrude: Point) {\n        array.emplaceBack(\n            // pos\n            boxTileAnchorX,\n            boxTileAnchorY,\n            boxTileAnchorZ,\n            // a_anchor_pos\n            tileAnchorX,\n            tileAnchorY,\n            // extrude\n            Math.round(extrude.x),\n            Math.round(extrude.y));\n    }\n\n    _addCollisionDebugVertices(box: CollisionBox, scale: number, arrays: CollisionBuffers, boxTileAnchorX: number, boxTileAnchorY: number, boxTileAnchorZ: number, symbolInstance: SymbolInstance) {\n        const segment = arrays.segments.prepareSegment(4, arrays.layoutVertexArray, arrays.indexArray);\n        const index = segment.vertexLength;\n        const symbolTileAnchorX = symbolInstance.tileAnchorX;\n        const symbolTileAnchorY = symbolInstance.tileAnchorY;\n\n        for (let i = 0; i < 4; i++) {\n            arrays.collisionVertexArray.emplaceBack(0, 0, 0, 0);\n        }\n\n        this._commitDebugCollisionVertexUpdate(arrays.collisionVertexArrayExt, scale, box.padding, symbolInstance.zOffset);\n\n        this._commitLayoutVertex(arrays.layoutVertexArray, boxTileAnchorX, boxTileAnchorY, boxTileAnchorZ, symbolTileAnchorX, symbolTileAnchorY, new Point(box.x1, box.y1));\n        this._commitLayoutVertex(arrays.layoutVertexArray, boxTileAnchorX, boxTileAnchorY, boxTileAnchorZ, symbolTileAnchorX, symbolTileAnchorY, new Point(box.x2, box.y1));\n        this._commitLayoutVertex(arrays.layoutVertexArray, boxTileAnchorX, boxTileAnchorY, boxTileAnchorZ, symbolTileAnchorX, symbolTileAnchorY, new Point(box.x2, box.y2));\n        this._commitLayoutVertex(arrays.layoutVertexArray, boxTileAnchorX, boxTileAnchorY, boxTileAnchorZ, symbolTileAnchorX, symbolTileAnchorY, new Point(box.x1, box.y2));\n\n        segment.vertexLength += 4;\n\n        const indexArray: LineIndexArray = (arrays.indexArray as any);\n        indexArray.emplaceBack(index, index + 1);\n        indexArray.emplaceBack(index + 1, index + 2);\n        indexArray.emplaceBack(index + 2, index + 3);\n        indexArray.emplaceBack(index + 3, index);\n\n        segment.primitiveLength += 4;\n    }\n\n    _addTextDebugCollisionBoxes(size: any, zoom: number, collisionBoxArray: CollisionBoxArray, startIndex: number, endIndex: number, instance: SymbolInstance) {\n        for (let b = startIndex; b < endIndex; b++) {\n            const box: CollisionBox = (collisionBoxArray.get(b) as any);\n            const scale = this.getSymbolInstanceTextSize(size, instance, zoom, b);\n\n            this._addCollisionDebugVertices(box, scale, this.textCollisionBox, box.projectedAnchorX, box.projectedAnchorY, box.projectedAnchorZ, instance);\n        }\n    }\n\n    _addIconDebugCollisionBoxes(size: any, zoom: number, collisionBoxArray: CollisionBoxArray, startIndex: number, endIndex: number, instance: SymbolInstance) {\n        for (let b = startIndex; b < endIndex; b++) {\n            const box: CollisionBox = (collisionBoxArray.get(b) as any);\n            const scale = this.getSymbolInstanceIconSize(size, zoom, instance.placedIconSymbolIndex);\n\n            this._addCollisionDebugVertices(box, scale, this.iconCollisionBox, box.projectedAnchorX, box.projectedAnchorY, box.projectedAnchorZ, instance);\n        }\n    }\n\n    generateCollisionDebugBuffers(zoom: number, collisionBoxArray: CollisionBoxArray) {\n        if (this.hasDebugData()) {\n            this.destroyDebugData();\n        }\n\n        this.textCollisionBox = new CollisionBuffers(CollisionBoxLayoutArray, collisionBoxLayout.members, LineIndexArray);\n        this.iconCollisionBox = new CollisionBuffers(CollisionBoxLayoutArray, collisionBoxLayout.members, LineIndexArray);\n\n        const iconSize = symbolSize.evaluateSizeForZoom(this.iconSizeData, zoom);\n        const textSize = symbolSize.evaluateSizeForZoom(this.textSizeData, zoom);\n\n        for (let i = 0; i < this.symbolInstances.length; i++) {\n            const symbolInstance = this.symbolInstances.get(i);\n            this._addTextDebugCollisionBoxes(textSize, zoom, collisionBoxArray, symbolInstance.textBoxStartIndex, symbolInstance.textBoxEndIndex, symbolInstance);\n            this._addTextDebugCollisionBoxes(textSize, zoom, collisionBoxArray, symbolInstance.verticalTextBoxStartIndex, symbolInstance.verticalTextBoxEndIndex, symbolInstance);\n            this._addIconDebugCollisionBoxes(iconSize, zoom, collisionBoxArray, symbolInstance.iconBoxStartIndex, symbolInstance.iconBoxEndIndex, symbolInstance);\n            this._addIconDebugCollisionBoxes(iconSize, zoom, collisionBoxArray, symbolInstance.verticalIconBoxStartIndex, symbolInstance.verticalIconBoxEndIndex, symbolInstance);\n        }\n    }\n\n    getSymbolInstanceTextSize(textSize: any, instance: SymbolInstance, zoom: number, boxIndex: number): number {\n        const symbolIndex = instance.rightJustifiedTextSymbolIndex >= 0 ?\n            instance.rightJustifiedTextSymbolIndex : instance.centerJustifiedTextSymbolIndex >= 0 ?\n                instance.centerJustifiedTextSymbolIndex : instance.leftJustifiedTextSymbolIndex >= 0 ?\n                    instance.leftJustifiedTextSymbolIndex : instance.verticalPlacedTextSymbolIndex >= 0 ?\n                        instance.verticalPlacedTextSymbolIndex : boxIndex;\n\n        const symbol = this.text.placedSymbolArray.get(symbolIndex);\n        const featureSize = symbolSize.evaluateSizeForFeature(this.textSizeData, textSize, symbol) / ONE_EM;\n\n        return this.tilePixelRatio * featureSize;\n    }\n\n    getSymbolInstanceIconSize(iconSize: any, zoom: number, iconIndex: number): number {\n        const symbol = this.icon.placedSymbolArray.get(iconIndex);\n        const featureSize = symbolSize.evaluateSizeForFeature(this.iconSizeData, iconSize, symbol);\n\n        return this.tilePixelRatio * featureSize;\n    }\n\n    _commitDebugCollisionVertexUpdate(array: StructArray, scale: number, padding: number, zOffset: number) {\n        array.emplaceBack(scale, -padding, -padding, zOffset);\n        array.emplaceBack(scale,  padding, -padding, zOffset);\n        array.emplaceBack(scale,  padding,  padding, zOffset);\n        array.emplaceBack(scale, -padding,  padding, zOffset);\n    }\n\n    _updateTextDebugCollisionBoxes(size: any, zoom: number, collisionBoxArray: CollisionBoxArray, startIndex: number, endIndex: number, instance: SymbolInstance) {\n        for (let b = startIndex; b < endIndex; b++) {\n            const box: CollisionBox = (collisionBoxArray.get(b) as any);\n            const scale = this.getSymbolInstanceTextSize(size, instance, zoom, b);\n            const array = this.textCollisionBox.collisionVertexArrayExt;\n            this._commitDebugCollisionVertexUpdate(array, scale, box.padding, instance.zOffset);\n        }\n    }\n\n    _updateIconDebugCollisionBoxes(size: any, zoom: number, collisionBoxArray: CollisionBoxArray, startIndex: number, endIndex: number, instance: SymbolInstance) {\n        for (let b = startIndex; b < endIndex; b++) {\n            const box = (collisionBoxArray.get(b));\n            const scale = this.getSymbolInstanceIconSize(size, zoom, instance.placedIconSymbolIndex);\n            const array = this.iconCollisionBox.collisionVertexArrayExt;\n            this._commitDebugCollisionVertexUpdate(array, scale, box.padding, instance.zOffset);\n        }\n    }\n\n    updateCollisionDebugBuffers(zoom: number, collisionBoxArray: CollisionBoxArray) {\n        if (!this.hasDebugData()) {\n            return;\n        }\n\n        if (this.hasTextCollisionBoxData()) this.textCollisionBox.collisionVertexArrayExt.clear();\n        if (this.hasIconCollisionBoxData()) this.iconCollisionBox.collisionVertexArrayExt.clear();\n\n        const iconSize = symbolSize.evaluateSizeForZoom(this.iconSizeData, zoom);\n        const textSize = symbolSize.evaluateSizeForZoom(this.textSizeData, zoom);\n\n        for (let i = 0; i < this.symbolInstances.length; i++) {\n            const symbolInstance = this.symbolInstances.get(i);\n            this._updateTextDebugCollisionBoxes(textSize, zoom, collisionBoxArray, symbolInstance.textBoxStartIndex, symbolInstance.textBoxEndIndex, symbolInstance);\n            this._updateTextDebugCollisionBoxes(textSize, zoom, collisionBoxArray, symbolInstance.verticalTextBoxStartIndex, symbolInstance.verticalTextBoxEndIndex, symbolInstance);\n            this._updateIconDebugCollisionBoxes(iconSize, zoom, collisionBoxArray, symbolInstance.iconBoxStartIndex, symbolInstance.iconBoxEndIndex, symbolInstance);\n            this._updateIconDebugCollisionBoxes(iconSize, zoom, collisionBoxArray, symbolInstance.verticalIconBoxStartIndex, symbolInstance.verticalIconBoxEndIndex, symbolInstance);\n        }\n\n        if (this.hasTextCollisionBoxData() && this.textCollisionBox.collisionVertexBufferExt) {\n            this.textCollisionBox.collisionVertexBufferExt.updateData(this.textCollisionBox.collisionVertexArrayExt);\n        }\n        if (this.hasIconCollisionBoxData() && this.iconCollisionBox.collisionVertexBufferExt) {\n            this.iconCollisionBox.collisionVertexBufferExt.updateData(this.iconCollisionBox.collisionVertexArrayExt);\n        }\n    }\n\n    // These flat arrays are meant to be quicker to iterate over than the source\n    // CollisionBoxArray\n    _deserializeCollisionBoxesForSymbol(\n        collisionBoxArray: CollisionBoxArray,\n        textStartIndex: number,\n        textEndIndex: number,\n        verticalTextStartIndex: number,\n        verticalTextEndIndex: number,\n        iconStartIndex: number,\n        iconEndIndex: number,\n        verticalIconStartIndex: number,\n        verticalIconEndIndex: number,\n    ): CollisionArrays {\n\n        // Only one box allowed per instance\n        const collisionArrays: Record<string, any> = {};\n        if (textStartIndex < textEndIndex) {\n            const {x1, y1, x2, y2, padding, projectedAnchorX, projectedAnchorY, projectedAnchorZ, tileAnchorX, tileAnchorY, featureIndex} = collisionBoxArray.get(textStartIndex);\n            collisionArrays.textBox = {x1, y1, x2, y2, padding, projectedAnchorX, projectedAnchorY, projectedAnchorZ, tileAnchorX, tileAnchorY};\n            collisionArrays.textFeatureIndex = featureIndex;\n        }\n        if (verticalTextStartIndex < verticalTextEndIndex) {\n            const {x1, y1, x2, y2, padding, projectedAnchorX, projectedAnchorY, projectedAnchorZ, tileAnchorX, tileAnchorY, featureIndex} = collisionBoxArray.get(verticalTextStartIndex);\n            collisionArrays.verticalTextBox = {x1, y1, x2, y2, padding, projectedAnchorX, projectedAnchorY, projectedAnchorZ, tileAnchorX, tileAnchorY};\n            collisionArrays.verticalTextFeatureIndex = featureIndex;\n        }\n        if (iconStartIndex < iconEndIndex) {\n            const {x1, y1, x2, y2, padding, projectedAnchorX, projectedAnchorY, projectedAnchorZ, tileAnchorX, tileAnchorY, featureIndex} = collisionBoxArray.get(iconStartIndex);\n            collisionArrays.iconBox = {x1, y1, x2, y2, padding, projectedAnchorX, projectedAnchorY, projectedAnchorZ, tileAnchorX, tileAnchorY};\n            collisionArrays.iconFeatureIndex = featureIndex;\n        }\n        if (verticalIconStartIndex < verticalIconEndIndex) {\n            const {x1, y1, x2, y2, padding, projectedAnchorX, projectedAnchorY, projectedAnchorZ, tileAnchorX, tileAnchorY, featureIndex} = collisionBoxArray.get(verticalIconStartIndex);\n            collisionArrays.verticalIconBox = {x1, y1, x2, y2, padding, projectedAnchorX, projectedAnchorY, projectedAnchorZ, tileAnchorX, tileAnchorY};\n            collisionArrays.verticalIconFeatureIndex = featureIndex;\n        }\n        return collisionArrays;\n    }\n\n    deserializeCollisionBoxes(collisionBoxArray: CollisionBoxArray) {\n        this.collisionArrays = [];\n        for (let i = 0; i < this.symbolInstances.length; i++) {\n            const symbolInstance = this.symbolInstances.get(i);\n            this.collisionArrays.push(this._deserializeCollisionBoxesForSymbol(\n                collisionBoxArray,\n                symbolInstance.textBoxStartIndex,\n                symbolInstance.textBoxEndIndex,\n                symbolInstance.verticalTextBoxStartIndex,\n                symbolInstance.verticalTextBoxEndIndex,\n                symbolInstance.iconBoxStartIndex,\n                symbolInstance.iconBoxEndIndex,\n                symbolInstance.verticalIconBoxStartIndex,\n                symbolInstance.verticalIconBoxEndIndex\n            ));\n        }\n    }\n\n    hasTextData(): boolean {\n        return this.text.segments.get().length > 0;\n    }\n\n    hasIconData(): boolean {\n        return this.icon.segments.get().length > 0;\n    }\n\n    hasDebugData(): CollisionBuffers {\n        return this.textCollisionBox && this.iconCollisionBox;\n    }\n\n    hasTextCollisionBoxData(): boolean {\n        return this.hasDebugData() && this.textCollisionBox.segments.get().length > 0;\n    }\n\n    hasIconCollisionBoxData(): boolean {\n        return this.hasDebugData() && this.iconCollisionBox.segments.get().length > 0;\n    }\n\n    hasIconTextFit(): boolean {\n        return this.hasAnyIconTextFit;\n    }\n\n    addIndicesForPlacedSymbol(iconOrText: SymbolBuffers, placedSymbolIndex: number) {\n        const placedSymbol = iconOrText.placedSymbolArray.get(placedSymbolIndex);\n\n        const endIndex = placedSymbol.vertexStartIndex + placedSymbol.numGlyphs * 4;\n        for (let vertexIndex = placedSymbol.vertexStartIndex; vertexIndex < endIndex; vertexIndex += 4) {\n            iconOrText.indexArray.emplaceBack(vertexIndex, vertexIndex + 1, vertexIndex + 2);\n            iconOrText.indexArray.emplaceBack(vertexIndex + 1, vertexIndex + 2, vertexIndex + 3);\n        }\n    }\n\n    getSortedSymbolIndexes(angle: number): Array<number> {\n        if (this.sortedAngle === angle && this.symbolInstanceIndexes !== undefined) {\n            return this.symbolInstanceIndexes;\n        }\n        const sin = Math.sin(angle);\n        const cos = Math.cos(angle);\n        const rotatedYs = [];\n        const featureIndexes = [];\n        const result = [];\n\n        for (let i = 0; i < this.symbolInstances.length; ++i) {\n            result.push(i);\n            const symbolInstance = this.symbolInstances.get(i);\n            rotatedYs.push(Math.round(sin * symbolInstance.tileAnchorX + cos * symbolInstance.tileAnchorY) | 0);\n            featureIndexes.push(symbolInstance.featureIndex);\n        }\n\n        result.sort((aIndex, bIndex) => (rotatedYs[aIndex] - rotatedYs[bIndex]) || (featureIndexes[bIndex] - featureIndexes[aIndex]));\n\n        return result;\n    }\n\n    getSortedIndexesByZOffset(): Array<number> {\n        if (!this.zOffsetSortDirty) {\n            assert(this.symbolInstanceIndexesSortedZOffset.length === this.symbolInstances.length);\n            return this.symbolInstanceIndexesSortedZOffset;\n        }\n        if (!this.symbolInstanceIndexesSortedZOffset) {\n            this.symbolInstanceIndexesSortedZOffset = [];\n            for (let i = 0; i < this.symbolInstances.length; ++i) {\n                this.symbolInstanceIndexesSortedZOffset.push(i);\n            }\n        }\n        this.zOffsetSortDirty = false;\n        return this.symbolInstanceIndexesSortedZOffset.sort((aIndex, bIndex) => this.symbolInstances.get(bIndex).zOffset - this.symbolInstances.get(aIndex).zOffset);\n    }\n\n    addToSortKeyRanges(symbolInstanceIndex: number, sortKey: number) {\n        const last = this.sortKeyRanges[this.sortKeyRanges.length - 1];\n        if (last && last.sortKey === sortKey) {\n            last.symbolInstanceEnd = symbolInstanceIndex + 1;\n        } else {\n            this.sortKeyRanges.push({\n                sortKey,\n                symbolInstanceStart: symbolInstanceIndex,\n                symbolInstanceEnd: symbolInstanceIndex + 1\n            });\n        }\n    }\n\n    sortFeatures(angle: number) {\n        if (!this.sortFeaturesByY) return;\n        if (this.sortedAngle === angle) return;\n\n        // The current approach to sorting doesn't sort across segments so don't try.\n        // Sorting within segments separately seemed not to be worth the complexity.\n        if (this.text.segments.get().length > 1 || this.icon.segments.get().length > 1) return;\n\n        // If the symbols are allowed to overlap sort them by their vertical screen position.\n        // The index array buffer is rewritten to reference the (unchanged) vertices in the\n        // sorted order.\n\n        // To avoid sorting the actual symbolInstance array we sort an array of indexes.\n        this.symbolInstanceIndexes = this.getSortedSymbolIndexes(angle);\n        this.sortedAngle = angle;\n\n        this.text.indexArray.clear();\n        this.icon.indexArray.clear();\n\n        this.featureSortOrder = [];\n\n        for (const i of this.symbolInstanceIndexes) {\n            const symbol = this.symbolInstances.get(i);\n            this.featureSortOrder.push(symbol.featureIndex);\n            const {\n                rightJustifiedTextSymbolIndex: right, centerJustifiedTextSymbolIndex: center,\n                leftJustifiedTextSymbolIndex: left, verticalPlacedTextSymbolIndex: vertical,\n                placedIconSymbolIndex: icon, verticalPlacedIconSymbolIndex: iconVertical\n            } = symbol;\n\n            // Only add a given index the first time it shows up, to avoid duplicate\n            // opacity entries when multiple justifications share the same glyphs.\n            if (right >= 0) this.addIndicesForPlacedSymbol(this.text, right);\n            if (center >= 0 && center !== right) this.addIndicesForPlacedSymbol(this.text, center);\n            if (left >= 0 && left !== center && left !== right) this.addIndicesForPlacedSymbol(this.text, left);\n\n            if (vertical >= 0) this.addIndicesForPlacedSymbol(this.text, vertical);\n            if (icon >= 0) this.addIndicesForPlacedSymbol(this.icon, icon);\n            if (iconVertical >= 0) this.addIndicesForPlacedSymbol(this.icon, iconVertical);\n        }\n\n        if (this.text.indexBuffer) this.text.indexBuffer.updateData(this.text.indexArray);\n        if (this.icon.indexBuffer) this.icon.indexBuffer.updateData(this.icon.indexArray);\n    }\n}\n\nregister(SymbolBucket, 'SymbolBucket', {\n    omit: ['layers', 'collisionBoxArray', 'features', 'compareText']\n});\n\nSymbolBucket.addDynamicAttributes = addDynamicAttributes;\n\nexport default SymbolBucket;\nexport {addDynamicAttributes, updateGlobeVertexNormal};\n","import type Point from '@mapbox/point-geometry';\nimport type {SymbolFeature} from '../data/bucket/symbol_bucket';\n\nexport default function(features: Array<SymbolFeature>): Array<SymbolFeature> {\n    const leftIndex: {\n        [_: string]: number;\n    } = {};\n    const rightIndex: {\n        [_: string]: number;\n    } = {};\n    const mergedFeatures = [];\n    let mergedIndex = 0;\n\n    function add(k: number) {\n        mergedFeatures.push(features[k]);\n        mergedIndex++;\n    }\n\n    function mergeFromRight(leftKey: string, rightKey: string, geom: Array<Array<Point>>) {\n        const i = rightIndex[leftKey];\n        delete rightIndex[leftKey];\n        rightIndex[rightKey] = i;\n\n        mergedFeatures[i].geometry[0].pop();\n        mergedFeatures[i].geometry[0] = mergedFeatures[i].geometry[0].concat(geom[0]);\n        return i;\n    }\n\n    function mergeFromLeft(leftKey: string, rightKey: string, geom: Array<Array<Point>>) {\n        const i = leftIndex[rightKey];\n        delete leftIndex[rightKey];\n        leftIndex[leftKey] = i;\n\n        mergedFeatures[i].geometry[0].shift();\n        mergedFeatures[i].geometry[0] = geom[0].concat(mergedFeatures[i].geometry[0]);\n        return i;\n    }\n\n    function getKey(text: string, geom: Array<Array<Point>>, onRight?: boolean | null) {\n        const point = onRight ? geom[0][geom[0].length - 1] : geom[0][0];\n        return `${text}:${point.x}:${point.y}`;\n    }\n\n    for (let k = 0; k < features.length; k++) {\n        const feature = features[k];\n        const geom = feature.geometry;\n        const text = feature.text ? feature.text.toString() : null;\n\n        if (!text) {\n            add(k);\n            continue;\n        }\n\n        const leftKey = getKey(text, geom),\n            rightKey = getKey(text, geom, true);\n\n        if ((leftKey in rightIndex) && (rightKey in leftIndex) && (rightIndex[leftKey] !== leftIndex[rightKey])) {\n            // found lines with the same text adjacent to both ends of the current line, merge all three\n            const j = mergeFromLeft(leftKey, rightKey, geom);\n            const i = mergeFromRight(leftKey, rightKey, mergedFeatures[j].geometry);\n\n            delete leftIndex[leftKey];\n            delete rightIndex[rightKey];\n\n            rightIndex[getKey(text, mergedFeatures[i].geometry, true)] = i;\n            mergedFeatures[j].geometry = (null as any);\n\n        } else if (leftKey in rightIndex) {\n            // found mergeable line adjacent to the start of the current line, merge\n            mergeFromRight(leftKey, rightKey, geom);\n\n        } else if (rightKey in leftIndex) {\n            // found mergeable line adjacent to the end of the current line, merge\n            mergeFromLeft(leftKey, rightKey, geom);\n\n        } else {\n            // no adjacent lines, add as a new item\n            add(k);\n            leftIndex[leftKey] = mergedIndex - 1;\n            rightIndex[rightKey] = mergedIndex - 1;\n        }\n    }\n\n    return mergedFeatures.filter((f) => f.geometry);\n}\n","import type Context from '../gl/context';\nimport type {RGBAImage, AlphaImage} from '../util/image';\nimport {Float32Image} from '../util/image';\nimport assert from 'assert';\n\nexport type TextureFormat = WebGL2RenderingContext['RGBA'] | WebGL2RenderingContext['DEPTH_COMPONENT'] | WebGL2RenderingContext['DEPTH_STENCIL'] | WebGL2RenderingContext['R8'] | WebGL2RenderingContext['R32F'] | WebGL2RenderingContext['RED'];\nexport type TextureType = WebGL2RenderingContext['UNSIGNED_INT_24_8'] | WebGL2RenderingContext['UNSIGNED_BYTE'] | WebGL2RenderingContext['UNSIGNED_SHORT'] | WebGL2RenderingContext['FLOAT'];\nexport type TextureFilter = WebGL2RenderingContext['LINEAR'] | WebGL2RenderingContext['NEAREST_MIPMAP_NEAREST'] | WebGL2RenderingContext['LINEAR_MIPMAP_NEAREST'] | WebGL2RenderingContext['NEAREST_MIPMAP_LINEAR'] | WebGL2RenderingContext['LINEAR_MIPMAP_LINEAR'] | WebGL2RenderingContext['NEAREST'];\nexport type TextureWrap = WebGL2RenderingContext['REPEAT'] | WebGL2RenderingContext['CLAMP_TO_EDGE'] | WebGL2RenderingContext['MIRRORED_REPEAT'];\n\ntype EmptyImage = {\n    width: number;\n    height: number;\n    data: null;\n};\n\nexport type TextureImage = RGBAImage | AlphaImage | Float32Image | HTMLImageElement | HTMLCanvasElement | HTMLVideoElement | ImageData | EmptyImage | ImageBitmap;\n\nclass Texture {\n    context: Context;\n    size: [number, number];\n    texture: WebGLTexture;\n    format: TextureFormat;\n    minFilter: TextureFilter | null | undefined;\n    magFilter: TextureFilter | null | undefined;\n    wrapS: TextureWrap | null | undefined;\n    wrapT: TextureWrap | null | undefined;\n    useMipmap: boolean;\n\n    constructor(context: Context, image: TextureImage, format: TextureFormat, options?: {\n        premultiply?: boolean;\n        useMipmap?: boolean;\n    } | null) {\n        this.context = context;\n        this.format = format;\n        this.texture = (context.gl.createTexture());\n        this.update(image, options);\n    }\n\n    update(image: TextureImage, options?: {\n        premultiply?: boolean;\n        useMipmap?: boolean;\n    } | null, position?: {\n        x: number;\n        y: number;\n    }) {\n        const {width, height} = image;\n        const {context} = this;\n        const {gl} = context;\n\n        gl.bindTexture(gl.TEXTURE_2D, this.texture);\n\n        context.pixelStoreUnpackFlipY.set(false);\n        context.pixelStoreUnpack.set(1);\n        context.pixelStoreUnpackPremultiplyAlpha.set(this.format === gl.RGBA && (!options || options.premultiply !== false));\n\n        this.useMipmap = Boolean(options && options.useMipmap);\n\n        if (!position && (!this.size || this.size[0] !== width || this.size[1] !== height)) {\n            this.size = [width, height];\n\n            if (image instanceof HTMLImageElement || image instanceof HTMLCanvasElement || image instanceof HTMLVideoElement || image instanceof ImageData || (ImageBitmap && image instanceof ImageBitmap)) {\n                let baseFormat = this.format;\n                if (this.format === gl.R8) {\n                    baseFormat = gl.RED;\n                }\n                gl.texImage2D(gl.TEXTURE_2D, 0, this.format, baseFormat, gl.UNSIGNED_BYTE, image);\n            } else {\n                let internalFormat = this.format;\n                let format = this.format;\n                let type: TextureType = gl.UNSIGNED_BYTE;\n                let preferTexStorage = false;\n\n                if (this.format === gl.DEPTH_COMPONENT) {\n                    // @ts-expect-error - TS2322 - Type '33189' is not assignable to type 'TextureFormat'.\n                    internalFormat = gl.DEPTH_COMPONENT16;\n                    type = gl.UNSIGNED_SHORT;\n                }\n                if (this.format === gl.DEPTH_STENCIL) {\n                    // @ts-expect-error - TS2322 - Type '33189' is not assignable to type 'TextureFormat'.\n                    internalFormat = gl.DEPTH24_STENCIL8;\n                    type = gl.UNSIGNED_INT_24_8;\n                    preferTexStorage = true;\n                }\n                if (this.format === gl.R8) {\n                    format = gl.RED;\n                }\n                if (this.format === gl.R32F) {\n                    assert(image instanceof Float32Image);\n                    type = gl.FLOAT;\n                    format = gl.RED;\n                }\n                if (!this.useMipmap && preferTexStorage) {\n                    gl.texStorage2D(gl.TEXTURE_2D, 1, internalFormat, width, height);\n                } else {\n                    // @ts-expect-error - TS2339 - Property 'data' does not exist on type 'ImageBitmap | RGBAImage | AlphaImage | Float32Image | EmptyImage'.\n                    gl.texImage2D(gl.TEXTURE_2D, 0, internalFormat, width, height, 0, format, type, image.data);\n                }\n            }\n        } else {\n            const {x, y} = position || {x: 0, y: 0};\n            if (image instanceof HTMLImageElement || image instanceof HTMLCanvasElement || image instanceof HTMLVideoElement || image instanceof ImageData || (ImageBitmap && image instanceof ImageBitmap)) {\n                gl.texSubImage2D(gl.TEXTURE_2D, 0, x, y, gl.RGBA, gl.UNSIGNED_BYTE, image);\n            } else {\n                let format = this.format;\n                let type: TextureType = gl.UNSIGNED_BYTE;\n\n                if (this.format === gl.R32F) {\n                    assert(image instanceof Float32Image);\n\n                    format = gl.RED;\n                    type = gl.FLOAT;\n                }\n                // @ts-expect-error - TS2339 - Property 'data' does not exist on type 'ImageBitmap | RGBAImage | AlphaImage | Float32Image | EmptyImage'.\n                gl.texSubImage2D(gl.TEXTURE_2D, 0, x, y, width, height, format, type, image.data);\n            }\n        }\n\n        if (this.useMipmap) {\n            gl.generateMipmap(gl.TEXTURE_2D);\n        }\n    }\n\n    bind(filter: TextureFilter, wrap: TextureWrap, ignoreMipMap: boolean = false) {\n        const {context} = this;\n        const {gl} = context;\n        gl.bindTexture(gl.TEXTURE_2D, this.texture);\n\n        if (filter !== this.minFilter) {\n            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, filter);\n            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER,\n                (this.useMipmap && !ignoreMipMap) ? (filter === gl.NEAREST ? gl.NEAREST_MIPMAP_NEAREST : gl.LINEAR_MIPMAP_LINEAR) : filter\n            );\n            this.minFilter = filter;\n        }\n\n        if (wrap !== this.wrapS) {\n            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, wrap);\n            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, wrap);\n            this.wrapS = wrap;\n        }\n    }\n\n    bindExtraParam(minFilter: TextureFilter, magFilter: TextureFilter, wrapS: TextureWrap, wrapT: TextureWrap) {\n        const {context} = this;\n        const {gl} = context;\n        gl.bindTexture(gl.TEXTURE_2D, this.texture);\n\n        if (magFilter !== this.magFilter) {\n            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, magFilter);\n            this.magFilter = magFilter;\n        }\n        if (minFilter !== this.minFilter) {\n            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER,\n                this.useMipmap ? (minFilter === gl.NEAREST ? gl.NEAREST_MIPMAP_NEAREST : gl.LINEAR_MIPMAP_LINEAR) : minFilter\n            );\n            this.minFilter = minFilter;\n        }\n\n        if (wrapS !== this.wrapS) {\n            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, wrapS);\n            this.wrapS = wrapS;\n        }\n\n        if (wrapT !== this.wrapT) {\n            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, wrapT);\n            this.wrapT = wrapT;\n        }\n    }\n\n    destroy() {\n        const {gl} = this.context;\n        gl.deleteTexture(this.texture);\n        this.texture = (null as any);\n    }\n}\n\nexport default Texture;\nexport class Texture3D {\n    context: Context;\n    size: [number, number, number];\n    texture: WebGLTexture;\n    format: TextureFormat;\n    minFilter: TextureFilter | null | undefined;\n    magFilter: TextureFilter | null | undefined;\n    wrapS: TextureWrap | null | undefined;\n    wrapT: TextureWrap | null | undefined;\n\n    constructor(context: Context, image: TextureImage, size: [number, number, number], format: TextureFormat) {\n        this.context = context;\n        this.format = format;\n        this.size = size;\n        this.texture = (context.gl.createTexture());\n\n        const [width, height, depth] = this.size;\n        const {gl} = context;\n\n        gl.bindTexture(gl.TEXTURE_3D, this.texture);\n\n        context.pixelStoreUnpackFlipY.set(false);\n        context.pixelStoreUnpack.set(1);\n        context.pixelStoreUnpackPremultiplyAlpha.set(false);\n\n        let internalFormat = this.format;\n        let type: TextureType = gl.UNSIGNED_BYTE;\n\n        if (this.format === gl.DEPTH_COMPONENT) {\n            // @ts-expect-error - TS2322 - Type '33189' is not assignable to type 'TextureFormat'.\n            internalFormat = gl.DEPTH_COMPONENT16;\n            type = gl.UNSIGNED_SHORT;\n        }\n        if (this.format === gl.R8) {\n            format = gl.RED;\n        }\n        if (this.format === gl.R32F) {\n            assert(image instanceof Float32Image);\n            type = gl.FLOAT;\n            format = gl.RED;\n        }\n        assert(image.width === (image.height * image.height));\n        assert(image.height === height);\n        assert(image.width === width * depth);\n\n        // @ts-expect-error - TS2339 - Property 'data' does not exist on type 'TextureImage'.\n        gl.texImage3D(gl.TEXTURE_3D, 0, internalFormat, width, height, depth, 0, format, type, image.data);\n    }\n\n    bind(filter: TextureFilter, wrap: TextureWrap) {\n        const {context} = this;\n        const {gl} = context;\n        gl.bindTexture(gl.TEXTURE_3D, this.texture);\n\n        if (filter !== this.minFilter) {\n            gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MAG_FILTER, filter);\n            gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MIN_FILTER, filter);\n            this.minFilter = filter;\n        }\n\n        if (wrap !== this.wrapS) {\n            gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_WRAP_S, wrap);\n            gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_WRAP_T, wrap);\n            this.wrapS = wrap;\n        }\n    }\n\n    destroy() {\n        const {gl} = this.context;\n        gl.deleteTexture(this.texture);\n        this.texture = (null as any);\n    }\n}\n\nexport class UserManagedTexture {\n    context: Context;\n    texture: WebGLTexture;\n    minFilter: TextureFilter | null | undefined;\n    wrapS: TextureWrap | null | undefined;\n\n    constructor(context: Context, texture: WebGLTexture) {\n        this.context = context;\n        this.texture = texture;\n    }\n\n    bind(filter: TextureFilter, wrap: TextureWrap) {\n        const {context} = this;\n        const {gl} = context;\n        gl.bindTexture(gl.TEXTURE_2D, this.texture);\n\n        if (filter !== this.minFilter) {\n            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, filter);\n            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, filter);\n            this.minFilter = filter;\n        }\n\n        if (wrap !== this.wrapS) {\n            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, wrap);\n            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, wrap);\n            this.wrapS = wrap;\n        }\n    }\n\n}\n","// logic for generating non-Mercator adaptive raster tile reprojection meshes with MARTINI\n\nimport tileTransform from '../geo/projection/tile_transform';\nimport EXTENT from '../style-spec/data/extent';\nimport {lngFromMercatorX, latFromMercatorY} from '../geo/mercator_coordinate';\nimport {TileBoundsArray, TriangleIndexArray} from '../data/array_types';\n\nimport type {CanonicalTileID} from './tile_id';\nimport type Projection from '../geo/projection/projection';\n\nconst meshSize = 32;\nconst gridSize = meshSize + 1;\n\nconst numTriangles = meshSize * meshSize * 2 - 2;\nconst numParentTriangles = numTriangles - meshSize * meshSize;\n\nconst coords = new Uint16Array(numTriangles * 4);\n\n// precalculate RTIN triangle coordinates\nfor (let i = 0; i < numTriangles; i++) {\n    let id = i + 2;\n    let ax = 0, ay = 0, bx = 0, by = 0, cx = 0, cy = 0;\n\n    if (id & 1) {\n        bx = by = cx = meshSize; // bottom-left triangle\n\n    } else {\n        ax = ay = cy = meshSize; // top-right triangle\n    }\n\n    while ((id >>= 1) > 1) {\n        const mx = (ax + bx) >> 1;\n        const my = (ay + by) >> 1;\n\n        if (id & 1) { // left half\n            bx = ax; by = ay;\n            ax = cx; ay = cy;\n\n        } else { // right half\n            ax = bx; ay = by;\n            bx = cx; by = cy;\n        }\n\n        cx = mx; cy = my;\n    }\n\n    const k = i * 4;\n    coords[k + 0] = ax;\n    coords[k + 1] = ay;\n    coords[k + 2] = bx;\n    coords[k + 3] = by;\n}\n\n// temporary arrays we'll reuse for MARTINI mesh code\nconst reprojectedCoords = new Uint16Array(gridSize * gridSize * 2);\nconst used = new Uint8Array(gridSize * gridSize);\nconst indexMap = new Uint16Array(gridSize * gridSize);\n\ntype TileMesh = {\n    vertices: TileBoundsArray;\n    indices: TriangleIndexArray;\n};\n\n// There can be visible seams between neighbouring tiles because of precision issues\n// and resampling differences. Adding a bit of padding around the edges of tiles hides\n// most of these issues.\nconst commonRasterTileSize = 256;\nconst paddingSize = meshSize / commonRasterTileSize / 4;\nfunction seamPadding(n: number) {\n    if (n === 0) return -paddingSize;\n    else if (n === gridSize - 1) return paddingSize;\n    else return 0;\n}\n\nexport default function getTileMesh(canonical: CanonicalTileID, projection: Projection): TileMesh {\n    const cs = tileTransform(canonical, projection);\n    const z2 = Math.pow(2, canonical.z);\n\n    for (let y = 0; y < gridSize; y++) {\n        for (let x = 0; x < gridSize; x++) {\n            const lng = lngFromMercatorX((canonical.x + (x + seamPadding(x)) / meshSize) / z2);\n            const lat = latFromMercatorY((canonical.y + (y + seamPadding(y)) / meshSize) / z2);\n            const p = projection.project(lng, lat);\n            const k = y * gridSize + x;\n            reprojectedCoords[2 * k + 0] = Math.round((p.x * cs.scale - cs.x) * EXTENT);\n            reprojectedCoords[2 * k + 1] = Math.round((p.y * cs.scale - cs.y) * EXTENT);\n        }\n    }\n\n    used.fill(0);\n    indexMap.fill(0);\n\n    // iterate over all possible triangles, starting from the smallest level\n    for (let i = numTriangles - 1; i >= 0; i--) {\n        const k = i * 4;\n        const ax = coords[k + 0];\n        const ay = coords[k + 1];\n        const bx = coords[k + 2];\n        const by = coords[k + 3];\n        const mx = (ax + bx) >> 1;\n        const my = (ay + by) >> 1;\n        const cx = mx + my - ay;\n        const cy = my + ax - mx;\n\n        const aIndex = ay * gridSize + ax;\n        const bIndex = by * gridSize + bx;\n        const mIndex = my * gridSize + mx;\n\n        // calculate error in the middle of the long edge of the triangle\n        const rax = reprojectedCoords[2 * aIndex + 0];\n        const ray = reprojectedCoords[2 * aIndex + 1];\n        const rbx = reprojectedCoords[2 * bIndex + 0];\n        const rby = reprojectedCoords[2 * bIndex + 1];\n        const rmx = reprojectedCoords[2 * mIndex + 0];\n        const rmy = reprojectedCoords[2 * mIndex + 1];\n\n        // raster tiles are typically 512px, and we use 1px as an error threshold; 8192 / 512 = 16\n        const isUsed = Math.hypot((rax + rbx) / 2 - rmx, (ray + rby) / 2 - rmy) >= 16;\n\n        used[mIndex] = used[mIndex] || (isUsed ? 1 : 0);\n\n        if (i < numParentTriangles) { // bigger triangles; accumulate error with children\n            const leftChildIndex = ((ay + cy) >> 1) * gridSize + ((ax + cx) >> 1);\n            const rightChildIndex = ((by + cy) >> 1) * gridSize + ((bx + cx) >> 1);\n            used[mIndex] = used[mIndex] || used[leftChildIndex] || used[rightChildIndex];\n        }\n    }\n\n    const vertices = new TileBoundsArray();\n    const indices = new TriangleIndexArray();\n\n    let numVertices = 0;\n\n    function addVertex(x: number, y: number) {\n        const k = y * gridSize + x;\n\n        if (indexMap[k] === 0) {\n            vertices.emplaceBack(\n                reprojectedCoords[2 * k + 0],\n                reprojectedCoords[2 * k + 1],\n                x * EXTENT / meshSize,\n                y * EXTENT / meshSize);\n\n            // save new vertex index so that we can reuse it\n            indexMap[k] = ++numVertices;\n        }\n\n        return indexMap[k] - 1;\n    }\n\n    function addTriangles(ax: number, ay: number, bx: number, by: number, cx: number, cy: number) {\n        const mx = (ax + bx) >> 1;\n        const my = (ay + by) >> 1;\n\n        if (Math.abs(ax - cx) + Math.abs(ay - cy) > 1 && used[my * gridSize + mx]) {\n            // triangle doesn't approximate the surface well enough; drill down further\n            addTriangles(cx, cy, ax, ay, mx, my);\n            addTriangles(bx, by, cx, cy, mx, my);\n\n        } else {\n            const ai = addVertex(ax, ay);\n            const bi = addVertex(bx, by);\n            const ci = addVertex(cx, cy);\n            indices.emplaceBack(ai, bi, ci);\n        }\n    }\n\n    addTriangles(0, 0, meshSize, meshSize, meshSize, 0);\n    addTriangles(meshSize, meshSize, 0, 0, 0, meshSize);\n\n    return {vertices, indices};\n}\n","import {createLayout} from '../util/struct_array';\n\nimport type {StructArrayLayout} from '../util/struct_array';\n\nexport default createLayout([\n    {name: 'a_pos', type: 'Int16', components: 2},\n    {name: 'a_texture_pos', type: 'Int16', components: 2}\n]);\n","import assert from 'assert';\n\nimport type {StructArray} from '../util/struct_array';\nimport type {TriangleIndexArray, LineIndexArray, LineStripIndexArray} from '../data/index_array_type';\nimport type Context from '../gl/context';\n\nclass IndexBuffer {\n    context: Context;\n    buffer: WebGLBuffer | null | undefined;\n    dynamicDraw: boolean;\n    id: number; // Unique ID, iterated on construction and data upload\n\n    static uniqueIdxCounter: number;\n    constructor(context: Context, array: TriangleIndexArray | LineIndexArray | LineStripIndexArray, dynamicDraw?: boolean, noDestroy?: boolean) {\n        this.id = IndexBuffer.uniqueIdxCounter;\n        IndexBuffer.uniqueIdxCounter++;\n\n        this.context = context;\n        const gl = context.gl;\n        this.buffer = gl.createBuffer();\n        this.dynamicDraw = Boolean(dynamicDraw);\n\n        // The bound index buffer is part of vertex array object state. We don't want to\n        // modify whatever VAO happens to be currently bound, so make sure the default\n        // vertex array provided by the context is bound instead.\n        this.context.unbindVAO();\n\n        context.bindElementBuffer.set(this.buffer);\n        gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, array.arrayBuffer, this.dynamicDraw ? gl.DYNAMIC_DRAW : gl.STATIC_DRAW);\n\n        if (!this.dynamicDraw && !noDestroy) {\n            array.destroy();\n        }\n    }\n\n    bind() {\n        this.context.bindElementBuffer.set(this.buffer);\n    }\n\n    updateData(array: StructArray) {\n        this.id = IndexBuffer.uniqueIdxCounter;\n        IndexBuffer.uniqueIdxCounter++;\n\n        const gl = this.context.gl;\n        assert(this.dynamicDraw);\n        // The right VAO will get this buffer re-bound later in VertexArrayObject#bind\n        // See https://github.com/mapbox/mapbox-gl-js/issues/5620\n        this.context.unbindVAO();\n        this.bind();\n        gl.bufferSubData(gl.ELEMENT_ARRAY_BUFFER, 0, array.arrayBuffer);\n    }\n\n    destroy() {\n        const gl = this.context.gl;\n        if (this.buffer) {\n            gl.deleteBuffer(this.buffer);\n            delete this.buffer;\n        }\n    }\n}\n\nIndexBuffer.uniqueIdxCounter = 0;\n\nexport default IndexBuffer;\n","import type {DepthFuncType, DepthMaskType, DepthRangeType} from './types';\n\nconst ALWAYS = 0x0207;\n\nclass DepthMode {\n    func: DepthFuncType;\n    mask: DepthMaskType;\n    range: DepthRangeType;\n\n    // DepthMask enums\n    static ReadOnly: boolean;\n    static ReadWrite: boolean;\n\n    constructor(depthFunc: DepthFuncType, depthMask: DepthMaskType, depthRange: DepthRangeType) {\n        this.func = depthFunc;\n        this.mask = depthMask;\n        this.range = depthRange;\n    }\n\n    static disabled: Readonly<DepthMode>;\n}\n\nDepthMode.ReadOnly = false;\nDepthMode.ReadWrite = true;\n\nDepthMode.disabled = new DepthMode(ALWAYS, DepthMode.ReadOnly, [0, 1]);\n\nexport default DepthMode;\n","import type {StencilOpConstant, StencilTest} from './types';\n\nconst ALWAYS = 0x0207;\nconst KEEP = 0x1E00;\n\nclass StencilMode {\n    test: StencilTest;\n    ref: number;\n    mask: number;\n    fail: StencilOpConstant;\n    depthFail: StencilOpConstant;\n    pass: StencilOpConstant;\n\n    constructor(test: StencilTest, ref: number, mask: number, fail: StencilOpConstant,\n        depthFail: StencilOpConstant, pass: StencilOpConstant) {\n        this.test = test;\n        this.ref = ref;\n        this.mask = mask;\n        this.fail = fail;\n        this.depthFail = depthFail;\n        this.pass = pass;\n    }\n\n    static disabled: Readonly<StencilMode>;\n}\n\nStencilMode.disabled = new StencilMode({func: ALWAYS, mask: 0}, 0, 0, KEEP, KEEP, KEEP);\n\nexport default StencilMode;\n","import Color from '../style-spec/util/color';\n\nimport type {BlendEquationType, BlendFuncType, ColorMaskType} from './types';\n\nexport const ZERO = 0x0000;\nexport const ONE = 0x0001;\nexport const SRC_ALPHA = 0x0302;\nexport const ONE_MINUS_SRC_ALPHA = 0x0303;\nexport const DST_COLOR = 0x0306;\n\nexport default class ColorMode {\n    blendFunction: BlendFuncType;\n    blendColor: Color;\n    mask: ColorMaskType;\n    blendEquation: BlendEquationType | null | undefined;\n\n    constructor(blendFunction: BlendFuncType, blendColor: Color, mask: ColorMaskType, blendEquation?: BlendEquationType | null) {\n        this.blendFunction = blendFunction;\n        this.blendColor = blendColor;\n        this.mask = mask;\n        this.blendEquation = blendEquation;\n    }\n\n    static Replace: BlendFuncType;\n\n    static disabled: Readonly<ColorMode>;\n    static unblended: Readonly<ColorMode>;\n    static alphaBlended: Readonly<ColorMode>;\n    static alphaBlendedNonPremultiplied: Readonly<ColorMode>;\n    static multiply: Readonly<ColorMode>;\n}\n\nColorMode.Replace = [ONE, ZERO, ONE, ZERO];\n\nColorMode.disabled = new ColorMode(ColorMode.Replace, Color.transparent, [false, false, false, false]);\nColorMode.unblended = new ColorMode(ColorMode.Replace, Color.transparent, [true, true, true, true]);\nColorMode.alphaBlended = new ColorMode([ONE, ONE_MINUS_SRC_ALPHA, ONE, ONE_MINUS_SRC_ALPHA], Color.transparent, [true, true, true, true]);\nColorMode.alphaBlendedNonPremultiplied = new ColorMode([SRC_ALPHA, ONE_MINUS_SRC_ALPHA, SRC_ALPHA, ONE_MINUS_SRC_ALPHA], Color.transparent, [true, true, true, true]);\nColorMode.multiply = new ColorMode([DST_COLOR, ZERO, DST_COLOR, ZERO], Color.transparent, [true, true, true, true]);\n","import type {CullFaceModeType, FrontFaceType} from './types';\n\nconst BACK = 0x0405;\nconst FRONT = 0x0404;\nconst CCW = 0x0901;\nconst CW = 0x0900;\n\nclass CullFaceMode {\n    enable: boolean;\n    mode: CullFaceModeType;\n    frontFace: FrontFaceType;\n\n    constructor(enable: boolean, mode: CullFaceModeType, frontFace: FrontFaceType) {\n        this.enable = enable;\n        this.mode = mode;\n        this.frontFace = frontFace;\n    }\n\n    static disabled: Readonly<CullFaceMode>;\n    static backCCW: Readonly<CullFaceMode>;\n    static backCW: Readonly<CullFaceMode>;\n    static frontCW: Readonly<CullFaceMode>;\n    static frontCCW: Readonly<CullFaceMode>;\n}\n\nCullFaceMode.disabled = new CullFaceMode(false, BACK, CCW);\nCullFaceMode.backCCW = new CullFaceMode(true, BACK, CCW);\nCullFaceMode.backCW = new CullFaceMode(true, BACK, CW);\nCullFaceMode.frontCW = new CullFaceMode(true, FRONT, CW);\nCullFaceMode.frontCCW = new CullFaceMode(true, FRONT, CCW);\n\nexport default CullFaceMode;\n","import {createLayout} from '../util/struct_array';\nimport type {StructArrayLayout} from '../util/struct_array';\n\nexport default createLayout([\n    {name: 'a_index', type: 'Int16', components: 1}\n]);\n","import {uniqueId, parseCacheControl} from '../util/util';\nimport {deserialize as deserializeBucket} from '../data/bucket';\nimport FeatureIndex from '../data/feature_index';\nimport Feature from '../util/vectortile_to_geojson';\nimport featureFilter from '../style-spec/feature_filter/index';\nimport SymbolBucket from '../data/bucket/symbol_bucket';\nimport FillBucket from '../data/bucket/fill_bucket';\nimport LineBucket from '../data/bucket/line_bucket';\nimport {CollisionBoxArray, TileBoundsArray, PosArray, TriangleIndexArray, LineStripIndexArray, PosGlobeExtArray} from '../data/array_types';\nimport Texture from '../render/texture';\nimport browser from '../util/browser';\nimport {Debug} from '../util/debug';\nimport toEvaluationFeature from '../data/evaluation_feature';\nimport EvaluationParameters from '../style/evaluation_parameters';\nimport SourceFeatureState from '../source/source_state';\nimport {lazyLoadRTLTextPlugin} from './rtl_text_plugin';\nimport {TileSpaceDebugBuffer} from '../data/debug_viz';\nimport Color from '../style-spec/util/color';\nimport loadGeometry from '../data/load_geometry';\nimport earcut from 'earcut';\nimport getTileMesh from './tile_mesh';\nimport tileTransform from '../geo/projection/tile_transform';\nimport {mercatorXfromLng, mercatorYfromLat} from '../geo/mercator_coordinate';\nimport boundsAttributes from '../data/bounds_attributes';\nimport posAttributes, {posAttributesGlobeExt} from '../data/pos_attributes';\nimport EXTENT from '../style-spec/data/extent';\nimport Point from '@mapbox/point-geometry';\nimport RasterParticleState from '../render/raster_particle_state';\nimport SegmentVector from '../data/segment';\nimport {transitionTileAABBinECEF, globeNormalizeECEF, tileCoordToECEF, globeToMercatorTransition, interpolateVec3} from '../geo/projection/globe_util';\nimport {vec3, mat4} from 'gl-matrix';\n\nimport type {Bucket} from '../data/bucket';\nimport type StyleLayer from '../style/style_layer';\nimport type {WorkerTileResult} from './worker_source';\nimport type Actor from '../util/actor';\nimport type DEMData from '../data/dem_data';\nimport type {AlphaImage, SpritePositions} from '../util/image';\nimport type ImageAtlas from '../render/image_atlas';\nimport type LineAtlas from '../render/line_atlas';\nimport type ImageManager from '../render/image_manager';\nimport type Context from '../gl/context';\nimport type {CanonicalTileID, OverscaledTileID} from './tile_id';\nimport type Framebuffer from '../gl/framebuffer';\nimport type Transform from '../geo/transform';\nimport type {GeoJSONFeature} from '../util/vectortile_to_geojson';\nimport type {LayerFeatureStates} from './source_state';\nimport type {Cancelable} from '../types/cancelable';\nimport type {FilterSpecification, ExpressionSpecification} from '../style-spec/types';\nimport type {TilespaceQueryGeometry} from '../style/query_geometry';\nimport type VertexBuffer from '../gl/vertex_buffer';\nimport type IndexBuffer from '../gl/index_buffer';\nimport type Projection from '../geo/projection/projection';\nimport type {TileTransform} from '../geo/projection/tile_transform';\nimport type Painter from '../render/painter';\nimport type {QueryResult} from '../source/query_features';\nimport type {UserManagedTexture, TextureImage} from '../render/texture';\nimport type {VectorTileLayer} from '@mapbox/vector-tile';\n\nconst CLOCK_SKEW_RETRY_TIMEOUT = 30000;\nexport type TileState = // Tile data is in the process of loading.\n'loading' | // Tile data has been loaded. Tile can be rendered.\n'loaded' | // Tile data has been loaded but has no content for rendering.\n'empty' | // Tile data has been loaded and is being updated. Tile can be rendered.\n'reloading' | // Tile data has been deleted.\n'unloaded' | // Tile data was not loaded because of an error.\n'errored' | 'expired';/* Tile data was previously loaded, but has expired per its\n * HTTP headers and is in the process of refreshing. */\n\n// a tile bounds outline used for getting reprojected tile geometry in non-mercator projections\nconst BOUNDS_FEATURE = (() => {\n    return {\n        type: 2,\n        extent: EXTENT,\n        loadGeometry() {\n            return [[\n                new Point(0, 0),\n                new Point(EXTENT + 1, 0),\n                new Point(EXTENT + 1, EXTENT + 1),\n                new Point(0, EXTENT + 1),\n                new Point(0, 0)\n            ]];\n        }\n    };\n})();\n\n/**\n * A tile object is the combination of a Coordinate, which defines\n * its place, as well as a unique ID and data tracking for its content\n *\n * @private\n */\nclass Tile {\n    tileID: OverscaledTileID;\n    uid: number;\n    uses: number;\n    tileSize: number;\n    tileZoom: number;\n    buckets: {\n        [_: string]: Bucket;\n    };\n    latestFeatureIndex: FeatureIndex | null | undefined;\n    latestRawTileData: ArrayBuffer | null | undefined;\n    imageAtlas: ImageAtlas | null | undefined;\n    imageAtlasTexture: Texture | null | undefined;\n    lineAtlas: LineAtlas | null | undefined;\n    lineAtlasTexture: Texture | null | undefined;\n    glyphAtlasImage: AlphaImage | null | undefined;\n    glyphAtlasTexture: Texture | null | undefined;\n    expirationTime: any;\n    expiredRequestCount: number;\n    state: TileState;\n    timeAdded: any;\n    fadeEndTime: any;\n    collisionBoxArray: CollisionBoxArray | null | undefined;\n    redoWhenDone: boolean;\n    showCollisionBoxes: boolean;\n    placementSource: any;\n    actor: Actor | null | undefined;\n    vtLayers: {\n        [_: string]: VectorTileLayer;\n    };\n    isSymbolTile: boolean | null | undefined;\n    isExtraShadowCaster: boolean | null | undefined;\n    isRaster: boolean | null | undefined;\n    _tileTransform: TileTransform;\n\n    neighboringTiles: any | null | undefined;\n    dem: DEMData | null | undefined;\n    aborted: boolean | null | undefined;\n    needsHillshadePrepare: boolean | null | undefined;\n    needsDEMTextureUpload: boolean | null | undefined;\n    request: Cancelable | null | undefined;\n    texture: Texture | null | undefined | UserManagedTexture;\n    hillshadeFBO: Framebuffer | null | undefined;\n    demTexture: Texture | null | undefined;\n    refreshedUponExpiration: boolean;\n    reloadCallback: any;\n    resourceTiming: Array<PerformanceResourceTiming> | null | undefined;\n    queryPadding: number;\n    rasterParticleState: RasterParticleState | null | undefined;\n\n    symbolFadeHoldUntil: number | null | undefined;\n    hasSymbolBuckets: boolean;\n    hasRTLText: boolean;\n    dependencies: any;\n    projection: Projection;\n\n    queryGeometryDebugViz: TileSpaceDebugBuffer | null | undefined;\n    queryBoundsDebugViz: TileSpaceDebugBuffer | null | undefined;\n\n    _tileDebugBuffer: VertexBuffer | null | undefined;\n    _tileBoundsBuffer: VertexBuffer | null | undefined;\n    _tileDebugIndexBuffer: IndexBuffer | null | undefined;\n    _tileBoundsIndexBuffer: IndexBuffer;\n    _tileDebugSegments: SegmentVector;\n    _tileBoundsSegments: SegmentVector;\n    _globeTileDebugBorderBuffer: VertexBuffer | null | undefined;\n    _tileDebugTextBuffer: VertexBuffer | null | undefined;\n    _tileDebugTextSegments: SegmentVector;\n    _tileDebugTextIndexBuffer: IndexBuffer;\n    _globeTileDebugTextBuffer: VertexBuffer | null | undefined;\n    _lastUpdatedBrightness: number | null | undefined;\n\n    /**\n     * @param {OverscaledTileID} tileID\n     * @param size\n     * @private\n     */\n    constructor(tileID: OverscaledTileID, size: number, tileZoom: number, painter?: Painter | null, isRaster?: boolean) {\n        this.tileID = tileID;\n        this.uid = uniqueId();\n        this.uses = 0;\n        this.tileSize = size;\n        this.tileZoom = tileZoom;\n        this.buckets = {};\n        this.expirationTime = null;\n        this.queryPadding = 0;\n        this.hasSymbolBuckets = false;\n        this.hasRTLText = false;\n        this.dependencies = {};\n        this.isRaster = isRaster;\n        if (painter && painter.style) {\n            this._lastUpdatedBrightness = painter.style.getBrightness();\n        }\n\n        // Counts the number of times a response was already expired when\n        // received. We're using this to add a delay when making a new request\n        // so we don't have to keep retrying immediately in case of a server\n        // serving expired tiles.\n        this.expiredRequestCount = 0;\n\n        this.state = 'loading';\n\n        if (painter && painter.transform) {\n            this.projection = painter.transform.projection;\n        }\n    }\n\n    registerFadeDuration(duration: number) {\n        const fadeEndTime = duration + this.timeAdded;\n        if (fadeEndTime < browser.now()) return;\n        if (this.fadeEndTime && fadeEndTime < this.fadeEndTime) return;\n\n        this.fadeEndTime = fadeEndTime;\n    }\n\n    wasRequested(): boolean {\n        return this.state === 'errored' || this.state === 'loaded' || this.state === 'reloading';\n    }\n\n    get tileTransform(): TileTransform {\n        if (!this._tileTransform) {\n            this._tileTransform = tileTransform(this.tileID.canonical, this.projection);\n        }\n        return this._tileTransform;\n    }\n\n    /**\n     * Given a data object with a 'buffers' property, load it into\n     * this tile's elementGroups and buffers properties and set loaded\n     * to true. If the data is null, like in the case of an empty\n     * GeoJSON tile, no-op but still set loaded to true.\n     * @param {Object} data\n     * @param painter\n     * @returns {undefined}\n     * @private\n     */\n    loadVectorData(data: WorkerTileResult | null | undefined, painter: Painter, justReloaded?: boolean | null) {\n        this.unloadVectorData();\n\n        this.state = 'loaded';\n\n        // empty GeoJSON tile\n        if (!data) {\n            this.collisionBoxArray = new CollisionBoxArray();\n            return;\n        }\n\n        if (data.featureIndex) {\n            this.latestFeatureIndex = data.featureIndex;\n            if (data.rawTileData) {\n                // Only vector tiles have rawTileData, and they won't update it for\n                // 'reloadTile'\n                this.latestRawTileData = data.rawTileData;\n                this.latestFeatureIndex.rawTileData = data.rawTileData;\n            } else if (this.latestRawTileData) {\n                // If rawTileData hasn't updated, hold onto a pointer to the last\n                // one we received\n                this.latestFeatureIndex.rawTileData = this.latestRawTileData;\n            }\n        }\n        this.collisionBoxArray = data.collisionBoxArray;\n        this.buckets = deserializeBucket(data.buckets, painter.style);\n\n        this.hasSymbolBuckets = false;\n        for (const id in this.buckets) {\n            const bucket = this.buckets[id];\n            if (bucket instanceof SymbolBucket) {\n                this.hasSymbolBuckets = true;\n                if (justReloaded) {\n                    bucket.justReloaded = true;\n                } else {\n                    break;\n                }\n            }\n        }\n\n        this.hasRTLText = false;\n        if (this.hasSymbolBuckets) {\n            for (const id in this.buckets) {\n                const bucket = this.buckets[id];\n                if (bucket instanceof SymbolBucket) {\n                    if (bucket.hasRTLText) {\n                        this.hasRTLText = true;\n                        lazyLoadRTLTextPlugin();\n                        break;\n                    }\n                }\n            }\n        }\n\n        this.queryPadding = 0;\n        for (const id in this.buckets) {\n            const bucket = this.buckets[id];\n            const layer = painter.style.getOwnLayer(id);\n            if (!layer) continue;\n            const queryRadius = layer.queryRadius(bucket);\n            this.queryPadding = Math.max(this.queryPadding, queryRadius);\n        }\n\n        if (data.imageAtlas) {\n            this.imageAtlas = data.imageAtlas;\n        }\n        if (data.glyphAtlasImage) {\n            this.glyphAtlasImage = data.glyphAtlasImage;\n        }\n        if (data.lineAtlas) {\n            this.lineAtlas = data.lineAtlas;\n        }\n        this._lastUpdatedBrightness = data.brightness;\n    }\n\n    /**\n     * Release any data or WebGL resources referenced by this tile.\n     * @returns {undefined}\n     * @private\n     */\n    unloadVectorData() {\n        if (!this.hasData()) return;\n\n        for (const id in this.buckets) {\n            this.buckets[id].destroy();\n        }\n        this.buckets = {};\n\n        if (this.imageAtlas) {\n            this.imageAtlas = null;\n        }\n\n        if (this.lineAtlas) {\n            this.lineAtlas = null;\n        }\n\n        if (this.imageAtlasTexture) {\n            this.imageAtlasTexture.destroy();\n        }\n\n        if (this.glyphAtlasTexture) {\n            this.glyphAtlasTexture.destroy();\n        }\n\n        if (this.lineAtlasTexture) {\n            this.lineAtlasTexture.destroy();\n        }\n\n        if (this._tileBoundsBuffer) {\n            this._tileBoundsBuffer.destroy();\n            this._tileBoundsIndexBuffer.destroy();\n            this._tileBoundsSegments.destroy();\n            this._tileBoundsBuffer = null;\n        }\n\n        if (this._tileDebugBuffer) {\n            this._tileDebugBuffer.destroy();\n            this._tileDebugSegments.destroy();\n            this._tileDebugBuffer = null;\n        }\n\n        if (this._tileDebugIndexBuffer) {\n            this._tileDebugIndexBuffer.destroy();\n            this._tileDebugIndexBuffer = null;\n        }\n\n        if (this._globeTileDebugBorderBuffer) {\n            this._globeTileDebugBorderBuffer.destroy();\n            this._globeTileDebugBorderBuffer = null;\n        }\n\n        if (this._tileDebugTextBuffer) {\n            this._tileDebugTextBuffer.destroy();\n            this._tileDebugTextSegments.destroy();\n            this._tileDebugTextIndexBuffer.destroy();\n            this._tileDebugTextBuffer = null;\n        }\n\n        if (this._globeTileDebugTextBuffer) {\n            this._globeTileDebugTextBuffer.destroy();\n            this._globeTileDebugTextBuffer = null;\n        }\n\n        Debug.run(() => {\n            if (this.queryGeometryDebugViz) {\n                this.queryGeometryDebugViz.unload();\n                delete this.queryGeometryDebugViz;\n            }\n            if (this.queryBoundsDebugViz) {\n                this.queryBoundsDebugViz.unload();\n                delete this.queryBoundsDebugViz;\n            }\n        });\n        this.latestFeatureIndex = null;\n        this.state = 'unloaded';\n    }\n\n    getBucket(layer: StyleLayer): Bucket {\n        return this.buckets[layer.fqid];\n    }\n\n    upload(context: Context) {\n        for (const id in this.buckets) {\n            const bucket = this.buckets[id];\n            if (bucket.uploadPending()) {\n                bucket.upload(context);\n            }\n        }\n\n        const gl = context.gl;\n        const atlas = this.imageAtlas;\n        if (atlas && !atlas.uploaded) {\n            const hasPattern = !!Object.keys(atlas.patternPositions).length;\n            this.imageAtlasTexture = new Texture(context, atlas.image, gl.RGBA, {useMipmap: hasPattern});\n            (this.imageAtlas).uploaded = true;\n        }\n\n        if (this.glyphAtlasImage) {\n            this.glyphAtlasTexture = new Texture(context, this.glyphAtlasImage, gl.R8);\n            this.glyphAtlasImage = null;\n        }\n\n        if (this.lineAtlas && !this.lineAtlas.uploaded) {\n            this.lineAtlasTexture = new Texture(context, this.lineAtlas.image, gl.R8);\n            (this.lineAtlas).uploaded = true;\n        }\n    }\n\n    prepare(imageManager: ImageManager, painter: Painter | null | undefined, scope: string) {\n        if (this.imageAtlas && this.imageAtlasTexture) {\n            this.imageAtlas.patchUpdatedImages(imageManager, this.imageAtlasTexture, scope);\n        }\n\n        if (!painter || !this.latestFeatureIndex || !this.latestFeatureIndex.rawTileData) {\n            return;\n        }\n        const brightness = painter.style.getBrightness();\n        if (!this._lastUpdatedBrightness && !brightness) {\n            return;\n        }\n        if (this._lastUpdatedBrightness && brightness && Math.abs(this._lastUpdatedBrightness - brightness) < 0.001) {\n            return;\n        }\n        this._lastUpdatedBrightness = brightness;\n        this.updateBuckets(undefined, painter);\n    }\n\n    // Queries non-symbol features rendered for this tile.\n    // Symbol features are queried globally\n    queryRenderedFeatures(\n        layers: {\n            [_: string]: StyleLayer;\n        },\n        serializedLayers: {\n            [key: string]: any;\n        },\n        sourceFeatureState: SourceFeatureState,\n        tileResult: TilespaceQueryGeometry,\n        params: {\n            filter: FilterSpecification;\n            layers: Array<string>;\n            availableImages: Array<string>;\n        },\n        transform: Transform,\n        pixelPosMatrix: Float32Array,\n        visualizeQueryGeometry: boolean,\n    ): QueryResult {\n        Debug.run(() => {\n            if (visualizeQueryGeometry) {\n                let geometryViz = this.queryGeometryDebugViz;\n                let boundsViz = this.queryBoundsDebugViz;\n                if (!geometryViz) {\n                    geometryViz = this.queryGeometryDebugViz = new TileSpaceDebugBuffer(this.tileSize);\n                }\n                if (!boundsViz) {\n                    boundsViz = this.queryBoundsDebugViz = new TileSpaceDebugBuffer(this.tileSize, Color.blue);\n                }\n\n                geometryViz.addPoints(tileResult.tilespaceGeometry);\n                boundsViz.addPoints(tileResult.bufferedTilespaceGeometry);\n            }\n        });\n\n        if (!this.latestFeatureIndex || !(this.latestFeatureIndex.rawTileData || this.latestFeatureIndex.is3DTile))\n            return {};\n\n        return this.latestFeatureIndex.query({\n            tileResult,\n            pixelPosMatrix,\n            transform,\n            params,\n            tileTransform: this.tileTransform\n        }, layers, serializedLayers, sourceFeatureState);\n    }\n\n    querySourceFeatures(result: Array<GeoJSONFeature>, params?: {\n        sourceLayer?: string;\n        filter?: FilterSpecification;\n        validate?: boolean;\n    }) {\n        const featureIndex = this.latestFeatureIndex;\n        if (!featureIndex || !featureIndex.rawTileData) return;\n\n        const vtLayers = featureIndex.loadVTLayers();\n\n        const sourceLayer = params ? params.sourceLayer : '';\n        const layer = vtLayers._geojsonTileLayer || vtLayers[sourceLayer];\n\n        if (!layer) return;\n\n        const filter = featureFilter(params && params.filter);\n        const {z, x, y} = this.tileID.canonical;\n        const coord = {z, x, y};\n\n        for (let i = 0; i < layer.length; i++) {\n            const feature = layer.feature(i);\n            if (filter.needGeometry) {\n                const evaluationFeature = toEvaluationFeature(feature, true);\n                if (!filter.filter(new EvaluationParameters(this.tileID.overscaledZ), evaluationFeature, this.tileID.canonical))\n                    continue;\n                // @ts-expect-error - TS2345 - Argument of type 'VectorTileFeature' is not assignable to parameter of type 'Feature'.\n            } else if (!filter.filter(new EvaluationParameters(this.tileID.overscaledZ), feature)) {\n                continue;\n            }\n            const id = featureIndex.getId(feature, sourceLayer);\n            const geojsonFeature = new Feature(feature, z, x, y, id);\n            geojsonFeature.tile = coord;\n\n            result.push(geojsonFeature);\n        }\n    }\n\n    hasData(): boolean {\n        return this.state === 'loaded' || this.state === 'reloading' || this.state === 'expired';\n    }\n\n    patternsLoaded(): boolean {\n        return !!this.imageAtlas && !!Object.keys(this.imageAtlas.patternPositions).length;\n    }\n\n    setExpiryData(data: any) {\n        const prior = this.expirationTime;\n\n        if (data.cacheControl) {\n            const parsedCC = parseCacheControl(data.cacheControl);\n            if (parsedCC['max-age']) this.expirationTime = Date.now() + parsedCC['max-age'] * 1000;\n        } else if (data.expires) {\n            this.expirationTime = new Date(data.expires).getTime();\n        }\n\n        if (this.expirationTime) {\n            const now = Date.now();\n            let isExpired = false;\n\n            if (this.expirationTime > now) {\n                isExpired = false;\n            } else if (!prior) {\n                isExpired = true;\n            } else if (this.expirationTime < prior) {\n                // Expiring date is going backwards:\n                // fall back to exponential backoff\n                isExpired = true;\n\n            } else {\n                const delta = this.expirationTime - prior;\n\n                if (!delta) {\n                    // Server is serving the same expired resource over and over: fall\n                    // back to exponential backoff.\n                    isExpired = true;\n\n                } else {\n                    // Assume that either the client or the server clock is wrong and\n                    // try to interpolate a valid expiration date (from the client POV)\n                    // observing a minimum timeout.\n                    this.expirationTime = now + Math.max(delta, CLOCK_SKEW_RETRY_TIMEOUT);\n\n                }\n            }\n\n            if (isExpired) {\n                this.expiredRequestCount++;\n                this.state = 'expired';\n            } else {\n                this.expiredRequestCount = 0;\n            }\n        }\n    }\n\n    getExpiryTimeout(): void | number {\n        if (this.expirationTime) {\n            if (this.expiredRequestCount) {\n                return 1000 * (1 << Math.min(this.expiredRequestCount - 1, 31));\n            } else {\n                // Max value for `setTimeout` implementations is a 32 bit integer; cap this accordingly\n                return Math.min(this.expirationTime - new Date().getTime(), Math.pow(2, 31) - 1);\n            }\n        }\n    }\n\n    setFeatureState(states: LayerFeatureStates, painter?: Painter | null) {\n        if (!this.latestFeatureIndex ||\n            !this.latestFeatureIndex.rawTileData ||\n            Object.keys(states).length === 0 ||\n            !painter) {\n            return;\n        }\n\n        this.updateBuckets(states, painter);\n    }\n\n    updateBuckets(states: LayerFeatureStates | null | undefined, painter: Painter) {