xture.image, textureFormat, {useMipmap});\n        texture.uploaded = true;\n        texture.image = (null as any);\n    }\n}\n\nexport function uploadMesh(mesh: Mesh, context: Context, useSingleChannelOcclusionTexture?: boolean) {\n    // Buffers\n    // Note: array buffers could reused for different nodes so destroy them in a later pass\n    mesh.indexBuffer = context.createIndexBuffer(mesh.indexArray, false, true);\n    mesh.vertexBuffer = context.createVertexBuffer(mesh.vertexArray, modelAttributes.members, false, true);\n    if (mesh.normalArray) {\n        mesh.normalBuffer = context.createVertexBuffer(mesh.normalArray, normalAttributes.members, false, true);\n    }\n    if (mesh.texcoordArray) {\n        mesh.texcoordBuffer = context.createVertexBuffer(mesh.texcoordArray, texcoordAttributes.members, false, true);\n    }\n    if (mesh.colorArray) {\n        const colorAttributes = mesh.colorArray.bytesPerElement === 12 ? color3fAttributes : color4fAttributes;\n        mesh.colorBuffer = context.createVertexBuffer(mesh.colorArray, colorAttributes.members, false, true);\n    }\n    if (mesh.featureArray) {\n        mesh.pbrBuffer = context.createVertexBuffer(mesh.featureArray, featureAttributes.members, true);\n    }\n    mesh.segments = SegmentVector.simpleSegment(0, 0, mesh.vertexArray.length, mesh.indexArray.length);\n\n    // Textures\n    const material = mesh.material;\n    if (material.pbrMetallicRoughness.baseColorTexture) {\n        uploadTexture(material.pbrMetallicRoughness.baseColorTexture, context);\n    }\n    if (material.pbrMetallicRoughness.metallicRoughnessTexture) {\n        uploadTexture(material.pbrMetallicRoughness.metallicRoughnessTexture, context);\n    }\n    if (material.normalTexture) {\n        uploadTexture(material.normalTexture, context);\n    }\n    if (material.occlusionTexture) {\n        uploadTexture(material.occlusionTexture, context, useSingleChannelOcclusionTexture);\n    }\n    if (material.emissionTexture) {\n        uploadTexture(material.emissionTexture, context);\n    }\n}\n\nexport function uploadNode(node: Node, context: Context, useSingleChannelOcclusionTexture?: boolean) {\n    if (node.meshes) {\n        for (const mesh of node.meshes) {\n            uploadMesh(mesh, context, useSingleChannelOcclusionTexture);\n        }\n    }\n    if (node.children) {\n        for (const child of node.children) {\n            uploadNode(child, context, useSingleChannelOcclusionTexture);\n        }\n    }\n}\n\nexport function destroyNodeArrays(node: Node) {\n    if (node.meshes) {\n        for (const mesh of node.meshes) {\n            mesh.indexArray.destroy();\n            mesh.vertexArray.destroy();\n            if (mesh.colorArray) mesh.colorArray.destroy();\n            if (mesh.normalArray) mesh.normalArray.destroy();\n            if (mesh.texcoordArray) mesh.texcoordArray.destroy();\n            if (mesh.featureArray) {\n                mesh.featureArray.destroy();\n            }\n        }\n    }\n    if (node.children) {\n        for (const child of node.children) {\n            destroyNodeArrays(child);\n        }\n    }\n}\n\nexport function destroyTextures(material: Material) {\n    if (material.pbrMetallicRoughness.baseColorTexture && material.pbrMetallicRoughness.baseColorTexture.gfxTexture) {\n        material.pbrMetallicRoughness.baseColorTexture.gfxTexture.destroy();\n    }\n    if (material.pbrMetallicRoughness.metallicRoughnessTexture && material.pbrMetallicRoughness.metallicRoughnessTexture.gfxTexture) {\n        material.pbrMetallicRoughness.metallicRoughnessTexture.gfxTexture.destroy();\n    }\n    if (material.normalTexture && material.normalTexture.gfxTexture) {\n        material.normalTexture.gfxTexture.destroy();\n    }\n    if (material.emissionTexture && material.emissionTexture.gfxTexture) {\n        material.emissionTexture.gfxTexture.destroy();\n    }\n    if (material.occlusionTexture && material.occlusionTexture.gfxTexture) {\n        material.occlusionTexture.gfxTexture.destroy();\n    }\n}\n\nexport function destroyBuffers(node: Node) {\n    if (node.meshes) {\n        for (const mesh of node.meshes) {\n            if (!mesh.vertexBuffer) continue;\n            mesh.vertexBuffer.destroy();\n            mesh.indexBuffer.destroy();\n            if (mesh.normalBuffer) {\n                mesh.normalBuffer.destroy();\n            }\n            if (mesh.texcoordBuffer) {\n                mesh.texcoordBuffer.destroy();\n            }\n            if (mesh.colorBuffer) {\n                mesh.colorBuffer.destroy();\n            }\n            if (mesh.pbrBuffer) {\n                mesh.pbrBuffer.destroy();\n            }\n\n            mesh.segments.destroy();\n            if (mesh.material) {\n                destroyTextures(mesh.material);\n            }\n        }\n    }\n    if (node.children) {\n        for (const child of node.children) {\n            destroyBuffers(child);\n        }\n    }\n}\n","/**\n * Invokes the wrapped function in a non-blocking way when trigger() is called. Invocation requests\n * are ignored until the function was actually invoked.\n *\n * @private\n */\nclass ThrottledInvoker {\n    _channel: MessageChannel | null | undefined;\n    _triggered: boolean;\n    _callback: any;\n\n    constructor(callback: any) {\n        this._callback = callback;\n        this._triggered = false;\n        if (typeof MessageChannel !== 'undefined') {\n            this._channel = new MessageChannel();\n            this._channel.port2.onmessage = () => {\n                this._triggered = false;\n                this._callback();\n            };\n        }\n    }\n\n    trigger() {\n        if (!this._triggered) {\n            this._triggered = true;\n            if (this._channel) {\n                this._channel.port1.postMessage(true);\n            } else {\n                setTimeout(() => {\n                    this._triggered = false;\n                    this._callback();\n                }, 0);\n            }\n        }\n    }\n\n    remove() {\n        this._channel = undefined;\n        this._callback = () => {};\n    }\n}\n\nexport default ThrottledInvoker;\n","import ThrottledInvoker from './throttled_invoker';\nimport {bindAll, isWorker} from './util';\nimport {PerformanceUtils} from './performance';\n\nimport type {Cancelable} from '../types/cancelable';\n\ntype TaskMetadata = {\n    type: 'message' | 'maybePrepare' | 'parseTile';\n    isSymbolTile: boolean | null | undefined;\n    zoom?: number;\n};\n\ntype TaskFunction = () => void;\n\ntype Task = {\n    fn: TaskFunction;\n    metadata: TaskMetadata;\n    priority: number;\n    id: number;\n};\n\nclass Scheduler {\n\n    tasks: {\n        [key: number]: Task;\n    };\n    taskQueue: Array<number>;\n    invoker: ThrottledInvoker;\n    nextId: number;\n\n    constructor() {\n        this.tasks = {};\n        this.taskQueue = [];\n        bindAll(['process'], this);\n        this.invoker = new ThrottledInvoker(this.process);\n\n        this.nextId = 0;\n    }\n\n    add(fn: TaskFunction, metadata: TaskMetadata): Cancelable | null {\n        const id = this.nextId++;\n        const priority = getPriority(metadata);\n\n        if (priority === 0) {\n            // Process tasks with priority 0 immediately. Do not yield to the event loop.\n            const m = isWorker() ? PerformanceUtils.beginMeasure('workerTask') : undefined;\n            try {\n                fn();\n            } finally {\n                if (m) PerformanceUtils.endMeasure(m);\n            }\n            // Don't return an empty cancel because we can't actually be cancelled\n            return null;\n        }\n\n        this.tasks[id] = {fn, metadata, priority, id};\n        this.taskQueue.push(id);\n        this.invoker.trigger();\n        return {\n            cancel: () => {\n                delete this.tasks[id];\n            }\n        };\n    }\n\n    process() {\n        const m = isWorker() ? PerformanceUtils.beginMeasure('workerTask') : undefined;\n        try {\n            this.taskQueue = this.taskQueue.filter(id => !!this.tasks[id]);\n\n            if (!this.taskQueue.length) {\n                return;\n            }\n            const id = this.pick();\n            if (id === null) return;\n\n            const task = this.tasks[id];\n            delete this.tasks[id];\n            // Schedule another process call if we know there's more to process _before_ invoking the\n            // current task. This is necessary so that processing continues even if the current task\n            // doesn't execute successfully.\n            if (this.taskQueue.length) {\n                this.invoker.trigger();\n            }\n            if (!task) {\n                // If the task ID doesn't have associated task data anymore, it was canceled.\n                return;\n            }\n\n            task.fn();\n        } finally {\n            if (m) PerformanceUtils.endMeasure(m);\n        }\n    }\n\n    pick(): null | number {\n        let minIndex = null;\n        let minPriority = Infinity;\n        for (let i = 0; i < this.taskQueue.length; i++) {\n            const id = this.taskQueue[i];\n            const task = this.tasks[id];\n            if (task.priority < minPriority) {\n                minPriority = task.priority;\n                minIndex = i;\n            }\n        }\n        if (minIndex === null) return null;\n        const id = this.taskQueue[minIndex];\n        this.taskQueue.splice(minIndex, 1);\n        return id;\n    }\n\n    remove() {\n        this.invoker.remove();\n    }\n}\n\nfunction getPriority(\n    {\n        type,\n        isSymbolTile,\n        zoom,\n    }: TaskMetadata,\n): number {\n    zoom = zoom || 0;\n    if (type === 'message') return 0;\n    if (type === 'maybePrepare' && !isSymbolTile) return 100 - zoom;\n    if (type === 'parseTile' && !isSymbolTile) return 200 - zoom;\n    if (type === 'parseTile' && isSymbolTile) return 300 - zoom;\n    if (type === 'maybePrepare' && isSymbolTile) return 400 - zoom;\n    return 500;\n}\n\nexport default Scheduler;\n","import {bindAll, isWorker} from './util';\nimport {serialize, deserialize} from './web_worker_transfer';\nimport Scheduler from './scheduler';\n\nimport type {Transferable} from '../types/transferable';\nimport type {Cancelable} from '../types/cancelable';\n\n/**\n * An implementation of the [Actor design pattern](http://en.wikipedia.org/wiki/Actor_model)\n * that maintains the relationship between asynchronous tasks and the objects\n * that spin them off - in this case, tasks like parsing parts of styles,\n * owned by the styles\n *\n * @param {WebWorker} target\n * @param {WebWorker} parent\n * @param {string|number} mapId A unique identifier for the Map instance using this Actor.\n * @private\n */\nclass Actor {\n    target: any;\n    parent: any;\n    mapId: number | null | undefined;\n    callbacks: {\n        number: any;\n    };\n    name: string;\n    cancelCallbacks: {\n        number: Cancelable;\n    };\n    scheduler: Scheduler;\n\n    constructor(target: any, parent: any, mapId?: number | null) {\n        this.target = target;\n        this.parent = parent;\n        this.mapId = mapId;\n        // @ts-expect-error - TS2741 - Property 'number' is missing in type '{}' but required in type '{ number: any; }'.\n        this.callbacks = {};\n        // @ts-expect-error - TS2741 - Property 'number' is missing in type '{}' but required in type '{ number: Cancelable; }'.\n        this.cancelCallbacks = {};\n        bindAll(['receive'], this);\n        this.target.addEventListener('message', this.receive, false);\n        this.scheduler = new Scheduler();\n    }\n\n    /**\n     * Sends a message from a main-thread map to a Worker or from a Worker back to\n     * a main-thread map instance.\n     *\n     * @param type The name of the target method to invoke or '[source-type].[source-name].name' for a method on a WorkerSource.\n     * @param targetMapId A particular mapId to which to send this message.\n     * @private\n     */\n    send(\n        type: string,\n        data: unknown,\n        callback?: any | null,\n        targetMapId?: string | null,\n        mustQueue: boolean = false,\n        callbackMetadata?: any,\n    ): Cancelable | null | undefined {\n        // We're using a string ID instead of numbers because they are being used as object keys\n        // anyway, and thus stringified implicitly. We use random IDs because an actor may receive\n        // message from multiple other actors which could run in different execution context. A\n        // linearly increasing ID could produce collisions.\n        const id = Math.round((Math.random() * 1e18)).toString(36).substring(0, 10);\n        if (callback) {\n            callback.metadata = callbackMetadata;\n            this.callbacks[id] = callback;\n        }\n        const buffers: Set<Transferable> = new Set();\n        this.target.postMessage({\n            id,\n            type,\n            hasCallback: !!callback,\n            targetMapId,\n            mustQueue,\n            sourceMapId: this.mapId,\n            data: serialize(data, buffers)\n        }, buffers);\n        return {\n            cancel: () => {\n                if (callback) {\n                    // Set the callback to null so that it never fires after the request is aborted.\n                    delete this.callbacks[id];\n                }\n                this.target.postMessage({\n                    id,\n                    type: '<cancel>',\n                    targetMapId,\n                    sourceMapId: this.mapId\n                });\n            }\n        };\n    }\n\n    receive(message: any) {\n        const data = message.data,\n            id = data.id;\n\n        if (!id) {\n            return;\n        }\n\n        if (data.targetMapId && this.mapId !== data.targetMapId) {\n            return;\n        }\n\n        if (data.type === '<cancel>') {\n            // Remove the original request from the queue. This is only possible if it\n            // hasn't been kicked off yet. The id will remain in the queue, but because\n            // there is no associated task, it will be dropped once it's time to execute it.\n            const cancel = this.cancelCallbacks[id];\n            delete this.cancelCallbacks[id];\n            if (cancel) {\n                cancel.cancel();\n            }\n        } else {\n            if (data.mustQueue || isWorker()) {\n                // for worker tasks that are often cancelled, such as loadTile, store them before actually\n                // processing them. This is necessary because we want to keep receiving <cancel> messages.\n                // Some tasks may take a while in the worker thread, so before executing the next task\n                // in our queue, postMessage preempts this and <cancel> messages can be processed.\n                // We're using a MessageChannel object to get throttle the process() flow to one at a time.\n                const callback = this.callbacks[id];\n                const metadata = (callback && callback.metadata) || {type: \"message\"};\n                const cancel = this.scheduler.add(() => this.processTask(id, data), metadata);\n                if (cancel) this.cancelCallbacks[id] = cancel;\n            } else {\n                // In the main thread, process messages immediately so that other work does not slip in\n                // between getting partial data back from workers.\n                this.processTask(id, data);\n            }\n        }\n    }\n\n    processTask(id: number, task: any) {\n        // Always delete since we are no longer cancellable\n        delete this.cancelCallbacks[id];\n        if (task.type === '<response>') {\n            // The done() function in the counterpart has been called, and we are now\n            // firing the callback in the originating actor, if there is one.\n            const callback = this.callbacks[id];\n            delete this.callbacks[id];\n            if (callback) {\n                // If we get a response, but don't have a callback, the request was canceled.\n                if (task.error) {\n                    callback(deserialize(task.error));\n                } else {\n                    callback(null, deserialize(task.data));\n                }\n            }\n        } else {\n            const buffers: Set<Transferable> = new Set();\n            const done = task.hasCallback ? (err: Error | null | undefined, data: unknown) => {\n                this.target.postMessage({\n                    id,\n                    type: '<response>',\n                    sourceMapId: this.mapId,\n                    error: err ? serialize(err) : null,\n                    data: serialize(data, buffers)\n                }, buffers);\n            } : (_) => {\n            };\n\n            const params = (deserialize(task.data) as any);\n            if (this.parent[task.type]) {\n                // task.type == 'loadTile', 'removeTile', etc.\n                this.parent[task.type](task.sourceMapId, params, done);\n            } else if (this.parent.getWorkerSource) {\n                // task.type == sourcetype.method\n                const keys = task.type.split('.');\n                const scope = (this.parent).getWorkerSource(task.sourceMapId, keys[0], params.source, params.scope);\n                scope[keys[1]](params, done);\n            } else {\n                // No function was found.\n                // @ts-expect-error - TS2554 - Expected 2 arguments, but got 1.\n                done(new Error(`Could not find function ${task.type}`));\n            }\n        }\n    }\n\n    remove() {\n        this.scheduler.remove();\n        this.target.removeEventListener('message', this.receive, false);\n    }\n}\n\nexport default Actor;\n","import {uniqueId, asyncAll} from './util';\nimport Actor from './actor';\nimport assert from 'assert';\n\nimport type WorkerPool from './worker_pool';\nimport type {Class} from '../types/class';\n\n/**\n * Responsible for sending messages from a {@link Source} to an associated\n * {@link WorkerSource}.\n *\n * @private\n */\nclass Dispatcher {\n    workerPool: WorkerPool;\n    actors: Array<Actor>;\n    currentActor: number;\n    id: number;\n    ready: boolean;\n\n    // exposed to allow stubbing in unit tests\n    static Actor: Class<Actor>;\n\n    constructor(workerPool: WorkerPool, parent: any) {\n        this.workerPool = workerPool;\n        this.actors = [];\n        this.currentActor = 0;\n        this.id = uniqueId();\n        const workers = this.workerPool.acquire(this.id);\n        for (let i = 0; i < workers.length; i++) {\n            const worker = workers[i];\n            const actor = new Dispatcher.Actor(worker, parent, this.id);\n            actor.name = `Worker ${i}`;\n            this.actors.push(actor);\n        }\n        assert(this.actors.length);\n\n        // track whether all workers are instantiated and ready to receive messages;\n        // used for optimizations on initial map load\n        this.ready = false;\n        this.broadcast('checkIfReady', null, () => { this.ready = true; });\n    }\n\n    /**\n     * Broadcast a message to all Workers.\n     * @private\n     */\n    broadcast(type: string, data: unknown, cb?: any) {\n        assert(this.actors.length);\n        cb = cb || function () {};\n        asyncAll(this.actors, (actor, done) => {\n            actor.send(type, data, done);\n        }, cb);\n    }\n\n    /**\n     * Acquires an actor to dispatch messages to. The actors are distributed in round-robin fashion.\n     * @returns {Actor} An actor object backed by a web worker for processing messages.\n     */\n    getActor(): Actor {\n        assert(this.actors.length);\n        this.currentActor = (this.currentActor + 1) % this.actors.length;\n        return this.actors[this.currentActor];\n    }\n\n    remove() {\n        this.actors.forEach((actor) => { actor.remove(); });\n        this.actors = [];\n        this.workerPool.release(this.id);\n    }\n}\n\nDispatcher.Actor = Actor;\n\nexport default Dispatcher;\n","export default {\n    workerUrl: '',\n    workerClass: null,\n    workerParams: undefined,\n};\n","import WorkerClass from './worker_class';\nimport type {Class} from '../types/class';\nimport type {WorkerSource} from '../source/worker_source';\n\ntype MessageListener = (\n    arg1: {\n        data: any;\n    },\n) => unknown;\n\n// The main thread interface. Provided by Worker in a browser environment,\n// and MessageBus below in a node environment.\nexport interface WorkerInterface {\n    addEventListener(type: 'message', listener: MessageListener): void;\n    removeEventListener(type: 'message', listener: MessageListener): void;\n    postMessage(message?: any): void;\n    terminate(): void;\n}\n\nexport interface WorkerGlobalScopeInterface {\n    importScripts(...urls: Array<string>): void;\n    registerWorkerSource?: (arg1: string, arg2: Class<WorkerSource>) => void;\n    registerRTLTextPlugin?: (_?: any) => void;\n}\n\nexport default function(): WorkerInterface {\n    return (WorkerClass.workerClass != null) ? new WorkerClass.workerClass() : (new self.Worker(WorkerClass.workerUrl, WorkerClass.workerParams) as any); // eslint-disable-line new-cap\n}\n","import WebWorker from './web_worker';\nimport type {WorkerInterface} from './web_worker';\n\nexport const PRELOAD_POOL_ID = 'mapboxgl_preloaded_worker_pool';\n\n/**\n * Constructs a worker pool.\n * @private\n */\nexport default class WorkerPool {\n    static workerCount: number;\n\n    active: Partial<Record<number | string, boolean>>;\n    workers: Array<WorkerInterface>;\n\n    constructor() {\n        this.active = {};\n    }\n\n    acquire(mapId: number | string): Array<WorkerInterface> {\n        if (!this.workers) {\n            // Lazily look up the value of mapboxgl.workerCount so that\n            // client code has had a chance to set it.\n            this.workers = [];\n            while (this.workers.length < WorkerPool.workerCount) {\n                // @ts-expect-error - TS2350 - Only a void function can be called with the 'new' keyword.\n                this.workers.push(new WebWorker());\n            }\n        }\n\n        this.active[mapId] = true;\n        return this.workers.slice();\n    }\n\n    release(mapId: number | string) {\n        delete this.active[mapId];\n        if (this.workers && this.numActive() === 0) {\n            this.workers.forEach((w) => {\n                w.terminate();\n            });\n            this.workers = (null as any);\n        }\n    }\n\n    isPreloaded(): boolean {\n        return !!this.active[PRELOAD_POOL_ID];\n    }\n\n    numActive(): number {\n        return Object.keys(this.active).length;\n    }\n}\n\n// extensive benchmarking showed 2 to be the best default for both desktop and mobile devices;\n// we can't rely on hardwareConcurrency because of wild inconsistency of reported numbers between browsers\nWorkerPool.workerCount = 2;\n","import WorkerPool, {PRELOAD_POOL_ID} from './worker_pool';\n\nlet globalWorkerPool: WorkerPool | null | undefined;\n\n/**\n * Creates (if necessary) and returns the single, global WorkerPool instance\n * to be shared across each Map\n * @private\n */\nexport default function getGlobalWorkerPool(): WorkerPool {\n    if (!globalWorkerPool) {\n        globalWorkerPool = new WorkerPool();\n    }\n    return globalWorkerPool;\n}\n\nexport function prewarm() {\n    const workerPool = getGlobalWorkerPool();\n    workerPool.acquire(PRELOAD_POOL_ID);\n}\n\nexport function clearPrewarmedResources() {\n    const pool = globalWorkerPool;\n    if (pool) {\n        // Remove the pool only if all maps that referenced the preloaded global worker pool have been removed.\n        if (pool.isPreloaded() && pool.numActive() === 1) {\n            pool.release(PRELOAD_POOL_ID);\n            globalWorkerPool = null;\n        } else {\n            console.warn('Could not clear WebWorkers since there are active Map instances that still reference it. The pre-warmed WebWorker pool can only be cleared when all map instances have been removed with map.remove()');\n        }\n    }\n}\n","/* eslint-disable new-cap */\n\nimport config from '../../src/util/config';\nimport browser from '../../src/util/browser';\nimport Dispatcher from '../../src/util/dispatcher';\nimport getWorkerPool from '../../src/util/global_worker_pool';\nimport {Evented} from '../../src/util/evented';\nimport {isWorker, warnOnce} from '../../src/util/util';\nimport assert from 'assert';\nimport {DracoDecoderModule} from './draco_decoder_gltf';\nimport {MeshoptDecoder} from './meshopt_decoder';\n\nimport type {Class} from '../../src/types/class';\n\nlet dispatcher = null;\n\nlet dracoLoading: Promise<any> | undefined;\nlet dracoUrl: string | null | undefined;\nlet draco: any;\nlet meshoptUrl: string | null | undefined;\nlet meshopt: any;\n\nexport function getDracoUrl(): string {\n// @ts-expect-error - TS2551 - Property 'worker' does not exist on type 'Window & typeof globalThis'. Did you mean 'Worker'? | TS2551 - Property 'worker' does not exist on type 'Window & typeof globalThis'. Did you mean 'Worker'?\n    if (isWorker() && self.worker && self.worker.dracoUrl) {\n        // @ts-expect-error - TS2551 - Property 'worker' does not exist on type 'Window & typeof globalThis'. Did you mean 'Worker'?\n        return self.worker.dracoUrl;\n    }\n\n    return dracoUrl ? dracoUrl : config.DRACO_URL;\n}\n\nexport function setDracoUrl(url: string) {\n    dracoUrl = browser.resolveURL(url);\n\n    if (!dispatcher) {\n        dispatcher = new Dispatcher(getWorkerPool(), new Evented());\n    }\n\n    // Sets the Draco URL in all workers.\n    dispatcher.broadcast('setDracoUrl', dracoUrl);\n}\n\nfunction waitForDraco() {\n    if (draco) return;\n    if (dracoLoading) return dracoLoading;\n\n    dracoLoading = DracoDecoderModule(fetch(getDracoUr