le;\n        const tangent = [-light.normal[1], light.normal[0], 0];\n        // 0---3  (at light.height above light.points)\n        // |   |\n        // 1-p-2  (p for light.position at bottom edge)\n\n        // horizontalSpread is tangent of the angle between light geometry and light normal.\n        // Cap it for doors with large inset (depth) to prevent intersecting door posts.\n        const horizontalSpread = Math.min(0.29, 0.1 * light.width / light.depth);\n        // A simple geometry, that starts at door, starts towards the centre of door to prevent intersecting\n        // door posts. Later, additional vertices at depth distance from door could be reconsidered.\n        // 0.01f to prevent intersection with door post.\n        const width = light.width - 2 * light.depth * zScale * (horizontalSpread + 0.01);\n        const v1 = vec3.scaleAndAdd([] as any, light.pos, tangent as [number, number, number], width / 2);\n        const v2 = vec3.scaleAndAdd([] as any, light.pos, tangent as [number, number, number], -width / 2);\n        const v0 = [v1[0], v1[1], v1[2] + light.height];\n        const v3 = [v2[0], v2[1], v2[2] + light.height];\n\n        const v1extrusion = vec3.scaleAndAdd([] as any, light.normal, tangent as [number, number, number], horizontalSpread);\n        vec3.scale(v1extrusion, v1extrusion, fallOff);\n        const v2extrusion = vec3.scaleAndAdd([] as any, light.normal, tangent as [number, number, number], -horizontalSpread);\n        vec3.scale(v2extrusion, v2extrusion, fallOff);\n\n        vec3.add(v1extrusion, v1, v1extrusion);\n        vec3.add(v2extrusion, v2, v2extrusion);\n\n        v1[2] += 0.1;\n        v2[2] += 0.1;\n        mesh.vertexArray.emplaceBack(v1extrusion[0], v1extrusion[1], v1extrusion[2]);\n        mesh.vertexArray.emplaceBack(v2extrusion[0], v2extrusion[1], v2extrusion[2]);\n        mesh.vertexArray.emplaceBack(v1[0], v1[1], v1[2]);\n        mesh.vertexArray.emplaceBack(v2[0], v2[1], v2[2]);\n        // side: top\n        mesh.vertexArray.emplaceBack(v0[0], v0[1], v0[2]);\n        mesh.vertexArray.emplaceBack(v3[0], v3[1], v3[2]);\n        // side\n        mesh.vertexArray.emplaceBack(v1[0], v1[1], v1[2]);\n        mesh.vertexArray.emplaceBack(v2[0], v2[1], v2[2]);\n        mesh.vertexArray.emplaceBack(v1extrusion[0], v1extrusion[1], v1extrusion[2]);\n        mesh.vertexArray.emplaceBack(v2extrusion[0], v2extrusion[1], v2extrusion[2]);\n        // Light doesnt include light coordinates - instead it includes offset to light area segment. Distances are\n        // normalized by dividing by fallOff. Normalized lighting coordinate system is used where center of\n        // coord system is on half of door and +Y is direction of extrusion.\n        // z includes half width - this is used to calculate distance to segment.\n\n        // 2 and 3 are bottom of the door, fully lit.\n        const halfWidth = width / fallOff / 2.0;\n        // right ground extruded looking out from door\n        // x Coordinate is used to model angle (for spot)\n        mesh.colorArray.emplaceBack(-halfWidth - horizontalSpread, -1, halfWidth, 0.8);\n        mesh.colorArray.emplaceBack(halfWidth + horizontalSpread, -1, halfWidth, 0.8);\n        // keep shine at bottom of door even for reduced emissive strength\n        mesh.colorArray.emplaceBack(-halfWidth, 0, halfWidth, 1.3);\n        mesh.colorArray.emplaceBack(halfWidth, 0, halfWidth, 1.3);\n        // for all vertices on the side, push the light origin behind the door top\n        mesh.colorArray.emplaceBack(halfWidth + horizontalSpread, -0.8, halfWidth, 0.7);\n        mesh.colorArray.emplaceBack(halfWidth + horizontalSpread, -0.8, halfWidth, 0.7);\n        // side at door, ground\n        mesh.colorArray.emplaceBack(0, 0, halfWidth, 1.3);\n        mesh.colorArray.emplaceBack(0, 0, halfWidth, 1.3);\n        // extruded side\n        mesh.colorArray.emplaceBack(halfWidth + horizontalSpread, -1.2, halfWidth, 0.8);\n        mesh.colorArray.emplaceBack(halfWidth + horizontalSpread, -1.2, halfWidth, 0.8);\n\n        // Finally, the triangle indices\n        mesh.indexArray.emplaceBack(6 + currentVertex, 4 + currentVertex, 8 + currentVertex);\n        mesh.indexArray.emplaceBack(7 + currentVertex, 9 + currentVertex, 5 + currentVertex);\n        mesh.indexArray.emplaceBack(0 + currentVertex, 1 + currentVertex, 2 + currentVertex);\n        mesh.indexArray.emplaceBack(1 + currentVertex, 3 + currentVertex, 2 + currentVertex);\n        currentVertex += 10;\n    }\n    //mesh.featureArray = new FeatureVertexArray();\n    //mesh.featureArray.reserve(10 * lights.length);\n    //for (let i = 0; i < 10 * lights.length; i++) {\n    //    mesh.featureArray.emplaceBack(0xffff, 0xffff, 0xffff, 0xffff, 0, 0, 0);\n    //}\n    // @ts-expect-error - TS2740 - Type '{}' is missing the following properties from type 'Material': normalTexture, occlusionTexture, emissionTexture, pbrMetallicRoughness, and 5 more.\n    const material: Material = {};\n    material.defined = true;\n    material.emissiveFactor = [0, 0, 0];\n    const pbrMetallicRoughness: Record<string, any> = {};\n    pbrMetallicRoughness.baseColorFactor = Color.white;\n    // @ts-expect-error - TS2739 - Type 'Record<string, any>' is missing the following properties from type 'PbrMetallicRoughness': baseColorFactor, metallicFactor, roughnessFactor, baseColorTexture, metallicRoughnessTexture\n    material.pbrMetallicRoughness = pbrMetallicRoughness;\n    mesh.material = material;\n    mesh.aabb = new Aabb([Infinity, Infinity, Infinity], [-Infinity, -Infinity, -Infinity]);\n    return mesh;\n}\n\nfunction decodeLights(base64: string): Array<AreaLight> {\n    if (!base64.length) return [];\n    const decoded = base64DecToArr(base64);\n    const lights: AreaLight[] = [];\n    const lightCount = decoded.length / 24; // 24 bytes (4 uint16 & 4 floats) per light\n    // Each door light is defined by two endpoiunts in tile coordinates, left and bottom right\n    // (where normal is implied from those two), depth and height.\n    // https://github.com/mapbox/mapbox-3dtile-tools/pull/100\n    const lightData = new Uint16Array(decoded.buffer);\n    const lightDataFloat = new Float32Array(decoded.buffer);\n    const stride = 6;\n    for (let i = 0; i < lightCount; i++) {\n        const height = lightData[i * 2 * stride] / 30;\n        const elevation = lightData[i * 2 * stride + 1 ] / 30;\n        const depth = lightData[i * 2 * stride + 10] / 100;\n        const x0 = lightDataFloat[i * stride + 1];\n        const y0 = lightDataFloat[i * stride + 2];\n        const x1 = lightDataFloat[i * stride + 3];\n        const y1 = lightDataFloat[i * stride + 4];\n        const dx = x1 - x0;\n        const dy = y1 - y0;\n        const width = Math.hypot(dx, dy);\n        const normal = [dy / width, -dx / width, 0];\n        const pos = [x0 + dx * 0.5, y0 + dy * 0.5, elevation];\n        const points = [x0, y0, x1, y1];\n        // @ts-expect-error - TS2322 - Type 'number[]' is not assignable to type 'vec3'. | TS2322 - Type 'number[]' is not assignable to type 'vec3'. | TS2322 - Type 'number[]' is not assignable to type 'vec4'.\n        lights.push({pos, normal, width, height, depth, points});\n    }\n    return lights;\n}\n","import assert from 'assert';\nimport Point from '@mapbox/point-geometry';\nimport browser from '../../../src/util/browser';\nimport {register} from '../../../src/util/web_worker_transfer';\nimport {uploadNode, destroyNodeArrays, destroyBuffers, ModelTraits, HEIGHTMAP_DIM} from '../model';\nimport {OverscaledTileID} from '../../../src/source/tile_id';\nimport {FeatureVertexArray} from '../../../src/data/array_types';\nimport {number as interpolate} from '../../../src/style-spec/util/interpolate';\nimport {clamp} from '../../../src/util/util';\nimport {DEMSampler} from '../../../src/terrain/elevation';\nimport {ZoomConstantExpression} from '../../../src/style-spec/expression/index';\nimport {Aabb} from '../../../src/util/primitives';\nimport {vec3, mat4} from 'gl-matrix';\n\nimport type ModelStyleLayer from '../../style/style_layer/model_style_layer';\nimport type {ReplacementSource} from '../../source/replacement_source';\nimport type {Bucket} from '../../../src/data/bucket';\nimport type {Node} from '../model';\nimport type {EvaluationFeature} from '../../../src/data/evaluation_feature';\nimport type {CanonicalTileID, UnwrappedTileID} from '../../../src/source/tile_id';\nimport type Context from '../../../src/gl/context';\nimport type {ProjectionSpecification} from '../../../src/style-spec/types';\nimport type Painter from '../../../src/render/painter';\nimport type {vec4} from 'gl-matrix';\nimport type {Terrain} from '../../../src/terrain/terrain';\nimport FeatureIndex from '../../../src/data/feature_index';\nimport type {GridIndex} from '../../../src/types/grid-index';\nimport type {TileFootprint} from '../../../3d-style/util/conflation';\n\nconst lookup = new Float32Array(512 * 512);\nconst passLookup = new Uint8Array(512 * 512);\n\nfunction getNodeHeight(node: Node): number {\n    let height = 0;\n    if (node.meshes) {\n        for (const mesh of node.meshes) {\n            height = Math.max(height, mesh.aabb.max[2]);\n        }\n    }\n    if (node.children) {\n        for (const child of node.children) {\n            height = Math.max(height, getNodeHeight(child));\n        }\n    }\n    return height;\n}\n\nfunction addAABBsToGridIndex(node: Node, key: number, grid: GridIndex) {\n    if (node.meshes) {\n        for (const mesh of node.meshes) {\n            if (mesh.aabb.min[0] === Infinity) continue;\n            grid.insert(key, mesh.aabb.min[0], mesh.aabb.min[1], mesh.aabb.max[0], mesh.aabb.max[1]);\n        }\n    }\n    if (node.children) {\n        for (const child of node.children) {\n            addAABBsToGridIndex(child, key, grid);\n        }\n    }\n}\n\nexport const PartIndices = {\n    wall: 1,\n    door: 2,\n    roof: 3,\n    window: 4,\n    lamp: 5,\n    logo: 6\n} as const;\n\nexport const PartNames = ['', 'wall', 'door', 'roof', 'window', 'lamp', 'logo'] as const;\n\nexport class Tiled3dModelFeature {\n    feature: EvaluationFeature;\n    evaluatedColor: Array<vec4>;\n    evaluatedRMEA: Array<vec4>;\n    evaluatedScale: [number, number, number];\n    hiddenByReplacement: boolean;\n    hasTranslucentParts: boolean;\n    node: Node;\n    aabb: Aabb;\n    emissionHeightBasedParams: Array<[number, number, number, number, number]>;\n    constructor(node: Node) {\n        this.node = node;\n        this.evaluatedRMEA = [[1, 0, 0, 1],\n            [1, 0, 0, 1],   // wall\n            [1, 0, 0, 1],   // door\n            [1, 0, 0, 1],   // roof\n            [0.4, 1, 0, 1], // window\n            [1, 0, 0, 1],   // lamp\n            [1, 0, 0, 1]];  // logo\n        this.hiddenByReplacement = false;\n        this.evaluatedScale = [1, 1, 1];\n        this.evaluatedColor = [];\n        this.emissionHeightBasedParams = [];\n        // Needs to calculate geometry\n        this.feature = {type: 'Point', id: node.id, geometry: [], properties: {'height' : getNodeHeight(node)}};\n        this.aabb = this._getLocalBounds();\n    }\n    _getLocalBounds(): Aabb {\n        if (!this.node.meshes) {\n            return new Aabb([Infinity, Infinity, Infinity], [-Infinity, -Infinity, -Infinity]);\n        }\n        if (!this.aabb) {\n            let i = 0;\n            const aabb = new Aabb([Infinity, Infinity, Infinity], [-Infinity, -Infinity, -Infinity]);\n            for (const mesh of this.node.meshes) {\n                if (this.node.lightMeshIndex !== i) {\n                    mesh.transformedAabb = Aabb.applyTransformFast(mesh.aabb, this.node.matrix);\n                    aabb.encapsulate(mesh.transformedAabb);\n                }\n                i++;\n            }\n            this.aabb = aabb;\n        }\n        return this.aabb;\n    }\n}\n\nclass Tiled3dModelBucket implements Bucket {\n    id: OverscaledTileID;\n    uploaded: boolean;\n    modelTraits: number;\n    hasPattern: boolean;\n    layers: Array<ModelStyleLayer>;\n    layerIds: Array<string>;\n    stateDependentLayers: Array<ModelStyleLayer>;\n    stateDependentLayerIds: Array<string>;\n    nodesInfo: Array<Tiled3dModelFeature>;\n    zoom: number;\n    projection: ProjectionSpecification;\n    terrainTile: CanonicalTileID | null | undefined;\n    terrainExaggeration: number | null | undefined;\n    replacementUpdateTime: number;\n    elevationReadFromZ: number;\n    dirty: boolean;\n    brightness: number | null | undefined;\n    needsUpload: boolean;\n    constructor(\n        nodes: Array<Node>,\n        id: OverscaledTileID,\n        hasMbxMeshFeatures: boolean,\n        hasMeshoptCompression: boolean,\n        brightness: number | null | undefined,\n        featureIndex: FeatureIndex,\n    ) {\n        this.id = id;\n        this.modelTraits |= ModelTraits.CoordinateSpaceTile;\n        this.uploaded = false;\n        this.hasPattern = false;\n        if (hasMbxMeshFeatures) {\n            this.modelTraits |= ModelTraits.HasMapboxMeshFeatures;\n        }\n        if (hasMeshoptCompression) {\n            this.modelTraits |= ModelTraits.HasMeshoptCompression;\n        }\n        this.zoom = -1;\n        this.terrainExaggeration = 1;\n        this.projection = {name: 'mercator'};\n        this.replacementUpdateTime = 0;\n        this.elevationReadFromZ = 0xff; // Re-read if underlying DEM zoom changes.\n        this.brightness = brightness;\n        this.dirty = true;\n        this.needsUpload = false;\n\n        this.nodesInfo = [];\n        for (const node of nodes) {\n            this.nodesInfo.push(new Tiled3dModelFeature(node));\n            addAABBsToGridIndex(node, featureIndex.featureIndexArray.length, featureIndex.grid);\n            featureIndex.featureIndexArray.emplaceBack(this.nodesInfo.length - 1, 0 /*sourceLayerIndex*/, featureIndex.bucketLayerIDs.length - 1, 0);\n        }\n    }\n\n    updateFootprints(id: UnwrappedTileID, footprints: Array<TileFootprint>) {\n        for (const nodeInfo of this.getNodesInfo()) {\n            const node = nodeInfo.node;\n            if (!node.footprint) {\n                continue;\n            }\n            footprints.push({\n                footprint: node.footprint,\n                id\n            });\n        }\n    }\n\n    update() {\n        console.log(\"Update 3D model bucket\");\n    }\n    populate() {\n        console.log(\"populate 3D model bucket\");\n    }\n    uploadPending(): boolean {\n        return !this.uploaded || this.needsUpload;\n    }\n\n    upload(context: Context) {\n        if (!this.needsUpload) return;\n        const nodesInfo = this.getNodesInfo();\n        for (const nodeInfo of nodesInfo) {\n            const node = nodeInfo.node;\n            if (this.uploaded) {\n                this.updatePbrBuffer(node);\n                continue;\n            }\n            uploadNode(node, context, true);\n        }\n        // Now destroy all buffers\n        for (const nodeInfo of nodesInfo) {\n            destroyNodeArrays(nodeInfo.node);\n        }\n        this.uploaded = true;\n        this.needsUpload = false;\n    }\n\n    updatePbrBuffer(node: Node): boolean {\n        let result = false;\n        if (!node.meshes) return result;\n        for (const mesh of node.meshes) {\n            if (mesh.pbrBuffer) {\n                mesh.pbrBuffer.updateData(mesh.featureArray);\n                result = true;\n            }\n        }\n        return result;\n    }\n\n    needsReEvaluation(painter: Painter, zoom: number, layer: ModelStyleLayer): boolean {\n        const projection = painter.transform.projectionOptions;\n        const calculatedBrightness = painter.style.getBrightness();\n        const brightnessChanged = this.brightness !== calculatedBrightness;\n        if (!this.uploaded || this.dirty || projection.name !== this.projection.name ||\n\n            expressionRequiresReevaluation(layer.paint.get('model-color').value, brightnessChanged) ||\n\n            expressionRequiresReevaluation(layer.paint.get('model-color-mix-intensity').value, brightnessChanged) ||\n\n            expressionRequiresReevaluation(layer.paint.get('model-roughness').value, brightnessChanged) ||\n\n            expressionRequiresReevaluation(layer.paint.get('model-emissive-strength').value, brightnessChanged) ||\n\n            expressionRequiresReevaluation(layer.paint.get('model-height-based-emissive-strength-multiplier').value, brightnessChanged)) {\n            this.projection = projection;\n            this.brightness = calculatedBrightness;\n            return true;\n        }\n        return false;\n    }\n\n    evaluateScale(painter: Painter, layer: ModelStyleLayer) {\n        if (painter.transform.zoom === this.zoom) return;\n        this.zoom = painter.transform.zoom;\n        const nodesInfo = this.getNodesInfo();\n        const canonical = this.id.canonical;\n        for (const nodeInfo of nodesInfo) {\n            const evaluationFeature = nodeInfo.feature;\n\n            nodeInfo.evaluatedScale = layer.paint.get('model-scale').evaluate(evaluationFeature, {}, canonical);\n        }\n    }\n\n    evaluate(layer: ModelStyleLayer) {\n        const nodesInfo = this.getNodesInfo();\n        for (const nodeInfo of nodesInfo) {\n            if (!nodeInfo.node.meshes) continue;\n            const evaluationFeature = nodeInfo.feature;\n            const hasFeatures = nodeInfo.node.meshes && nodeInfo.node.meshes[0].featureData;\n            const previousDoorColor = nodeInfo.evaluatedColor[PartIndices.door];\n            const previousDoorRMEA = nodeInfo.evaluatedRMEA[PartIndices.door];\n            const canonical = this.id.canonical;\n            nodeInfo.hasTranslucentParts = false;\n\n            if (hasFeatures) {\n                for (let i = 0; i < PartNames.length; i++) {\n                    const part = PartNames[i];\n                    if (part.length) {\n                        evaluationFeature.properties['part'] = part;\n                    }\n\n                    const color = layer.paint.get('model-color').evaluate(evaluationFeature, {}, canonical).toRenderColor(null);\n\n                    const colorMixIntensity = layer.paint.get('model-color-mix-intensity').evaluate(evaluationFeature, {}, canonical);\n                    nodeInfo.evaluatedColor[i] = [color.r, color.g, color.b, colorMixIntensity];\n\n                    nodeInfo.evaluatedRMEA[i][0] = layer.paint.get('model-roughness').evaluate(evaluationFeature, {}, canonical);\n                    // For the first version metallic is not styled\n\n                    nodeInfo.evaluatedRMEA[i][2] = layer.paint.get('model-emissive-strength').evaluate(evaluationFeature, {}, canonical);\n                    nodeInfo.evaluatedRMEA[i][3] = color.a;\n\n                    nodeInfo.emissionHeightBasedParams[i] = layer.paint.get('model-height-based-emissive-strength-multiplier').evaluate(evaluationFeature, {}, canonical);\n\n                    if (!nodeInfo.hasTranslucentParts && color.a < 1.0) {\n                        nodeInfo.hasTranslucentParts = true;\n                    }\n                }\n                delete evaluationFeature.properties['part'];\n                const doorLightChanged = previousDoorColor !== nodeInfo.evaluatedColor[PartIndices.door] ||\n                                         previousDoorRMEA !== nodeInfo.evaluatedRMEA[PartIndices.door];\n                updateNodeFeatureVertices(nodeInfo, doorLightChanged, this.modelTraits);\n            } else {\n\n                nodeInfo.evaluatedRMEA[0][2] = layer.paint.get('model-emissive-strength').evaluate(evaluationFeature, {}, canonical);\n            }\n\n            nodeInfo.evaluatedScale = layer.paint.get('model-scale').evaluate(evaluationFeature, {}, canonical);\n            if (!this.updatePbrBuffer(nodeInfo.node)) {\n                this.needsUpload = true;\n            }\n        }\n        this.dirty = false;\n    }\n\n    elevationUpdate(terrain: Terrain, exaggeration: number, coord: OverscaledTileID, source: string) {\n        assert(terrain);\n        const demTile = terrain.findDEMTileFor(coord);\n        if (!demTile) return;\n        if (demTile.tileID.canonical === this.terrainTile && exaggeration === this.terrainExaggeration) return;\n\n        if (demTile.dem && demTile.tileID.overscaledZ !== this.elevationReadFromZ) {\n            this.elevationReadFromZ = demTile.tileID.overscaledZ;\n            const dem = DEMSampler.create(terrain, coord, demTile);\n            if (!dem) return;\n            if (this.modelTraits & ModelTraits.HasMapboxMeshFeatures) {\n                this.updateDEM(terrain, dem, coord, source);\n            }\n            for (const nodeInfo of this.getNodesInfo()) {\n                const node = nodeInfo.node;\n                if (!node.footprint || !node.footprint.vertices || !node.footprint.vertices.length) {\n                    continue;\n                }\n                const vertices = node.footprint.vertices;\n                let elevation = dem.getElevationAt(vertices[0].x, vertices[0].y, true, true);\n                for (let i = 1; i < vertices.length; i++) {\n                    elevation = Math.min(elevation, dem.getElevationAt(vertices[i].x, vertices[i].y, true, true));\n                }\n                node.elevation = elevation;\n            }\n        }\n        this.terrainTile = demTile.tileID.canonical;\n        this.terrainExaggeration = exaggeration;\n    }\n\n    updateDEM(terrain: Terrain, dem: DEMSampler, coord: OverscaledTileID, source: string) {\n        let tiles = dem._dem._modifiedForSources[source];\n        if (tiles === undefined) {\n            dem._dem._modifiedForSources[source] = [];\n            tiles = dem._dem._modifiedForSources[source];\n        }\n        if (tiles.includes(coord.canonical)) {\n            return;\n        }\n\n        // Resolution of the DEM data.\n        const demRes = dem._dem.dim;\n\n        tiles.push(coord.canonical);\n        assert(lookup.length <= demRes * demRes);\n\n        let changed = false;\n        for (const nodeInfo of this.getNodesInfo()) {\n            const node = nodeInfo.node;\n            if (!node.footprint || !node.footprint.grid) {\n                continue;\n            }\n\n            // Convert the bounds of the footprint for this node from its tile coordinates to DEM pixel coordinates.\n            const grid = node.footprint.grid;\n            const minDem = dem.tileCoordToPixel(grid.min.x, grid.min.y);\n            const maxDem = dem.tileCoordToPixel(grid.max.x, grid.max.y);\n\n            const distanceToBorder = Math.min(Math.min(demRes - maxDem.y, minDem.x), Math.min(minDem.y, demRes - maxDem.x));\n            if (distanceToBorder < 0) {\n                continue; // don't deal with neighbors and landmarks crossing tile borders, fix terrain only for buildings within the tile\n            }\n            // demAtt is a number of pixels we use to propagate attenuated change to surrounding pixels.\n            // this is clamped further when sampling near tile border.\n            // The footprint covers a certain region of DEM pixels as indicated with 'minDem' and 'maxDem' (region A).\n            // This region is further padded by demAtt pixels to form the region B.\n            // First mark all the DEM pixels in region B as unchanged (using 'passLookup' array).\n            // +------------+\n            // |  +-----+   |\n            // |  |  A  |   |\n            // |  +-----+ B |\n            // +------------+\n            const demAtt = clamp(distanceToBorder, 2, 5);\n            let minx = Math.max(0, minDem.x - demAtt);\n            let miny = Math.max(0, minDem.y - demAtt);\n            let maxx = Math.min(maxDem.x + demAtt, demRes - 1);\n            let maxy = Math.min(maxDem.y + demAtt, demRes - 1);\n            for (let y = miny; y <= maxy; ++y) {\n                for (let x = minx; x <= maxx; ++x) {\n                    passLookup[y * demRes + x] = 255;\n                }\n            }\n\n            // Next go through all eligible DEM pixels in region A, mark them as changed and calculate the average height(elevation).\n            // Some pixels may be skipped (and therefore aren't eligible) because no footprint geometry overlaps them.\n            // This is indicated by the existence of a 'Cell' at a given pixel's position.\n            let heightAcc = 0;\n            let count = 0;\n            for (let celly = 0; celly < grid.cellsY; ++celly) {\n                for (let cellx = 0; cellx < grid.cellsX; ++cellx) {\n                    const cell = grid.cells[celly * grid.cellsX + cellx];\n                    if (!cell) {\n                        continue;\n                    }\n                    const demP = dem.tileCoordToPixel(grid.min.x + cellx / grid.xScale, grid.min.y + celly / grid.yScale);\n                    const demPMax = dem.tileCoordToPixel(grid.min.x + (cellx + 1) / grid.xScale, grid.min.y + (celly + 1) / grid.yScale);\n                    for (let y = demP.y; y <= Math.min(demPMax.y + 1, demRes - 1); ++y) {\n                        for (let x = demP.x; x <= Math.min(demPMax.x + 1, demRes - 1); ++x) {\n                            if (passLookup[y * demRes + x] === 255) {\n                                passLookup[y * demRes + x] = 0;\n                                const height = dem.getElevationAtPixel(x, y);\n                                heightAcc += height;\n                                count++;\n                            }\n                        }\n                    }\n                }\n            }\n\n            assert(count);\n            const avgHeight = heightAcc / count;\n            // See https://github.com/mapbox/mapbox-gl-js-internal/pull/804#issuecomment-1738720351\n            // for explanation why bounds should be clamped to 1 and demRes - 2 respectively.\n            minx = Math.max(1, minDem.x - demAtt);\n            miny = Math.max(1, minDem.y - demAtt);\n            maxx = Math.min(maxDem.x + demAtt, demRes - 2);\n            maxy = Math.min(maxDem.y + demAtt, demRes - 2);\n\n            // Next, update the DEM pixels in region A (which the footprint overlaps with) by the average height.\n            // This effectively flattens the terrain for the given footprint/building.\n            // Store the difference of the original height with the average height in 'lookup' array.\n            changed = true;\n            for (let y = miny; y <= maxy; ++y) {\n                for (let x = minx; x <= maxx; ++x) {\n                    if (passLookup[y * demRes + x] === 0) {\n                        lookup[y * demRes + x] = dem._dem.set(x, y, avgHeight);\n                    }\n                }\n            }\n\n            // Finally propagate the flattened out values to the remaining surrounding pixels (as goverened by demAtt padding) in region B.\n            // This ensures a smooth transition between the flattened and the non-flattened regions.\n            for (let p = 1; p < demAtt; ++p) {\n                minx = Math.max(1, minDem.x - p);\n                miny = Math.max(1, minDem.y - p);\n                maxx = Math.min(maxDem.x + p, demRes - 2);\n                maxy = Math.min(maxDem.y + p, demRes - 2);\n                for (let y = miny; y <= maxy; ++y) {\n                    for (let x = minx; x <= maxx; ++x) {\n                        const indexThis = y * demRes + x;\n                        // If DEM pixel is not modified.\n                        if (passLookup[indexThis] === 255) {\n                            let maxDiff = 0;\n                            let maxDiffAbs = 0;\n                            let xoffset = -1;\n                            let yoffset = -1;\n                            for (let j = -1; j <= 1; ++j) {\n                                for (let i = -1; i <= 1; ++i) {\n                                    const index = (y + j) * demRes + x + i;\n                                    if (passLookup[index] >= p) {\n                                        continue;\n                                    }\n                                    const diff = lookup[index];\n                                    const diffAbs = Math.abs(diff);\n                                    if (diffAbs  > maxDiffAbs) {\n                                        maxDiff = diff;\n                                        maxDiffAbs = diffAbs;\n                                        xoffset = i;\n                                        yoffset = j;\n                                    }\n                                }\n                            }\n\n                            if (maxDiffAbs > 0.1) {\n                                const diagonalAttenuation = Math.abs(xoffset * yoffset) * 0.5;\n                                const attenuation = 1 - (p + diagonalAttenuation) / demAtt;\n                                assert(attenuation > 0);\n                                const prev = dem._dem.get(x, y);\n                                let next = prev + maxDiff * attenuation;\n\n                                // parent - child in the meaning of wave propagation\n                                const parent = dem._dem.get(x + xoffset, y + yoffset);\n                                const child = dem._dem.get(x - xoffset, y - yoffset, true);\n                                // prevent waves\n                                if ((next - parent) * (next - child) > 0) {\n                                    next = (parent + child) / 2;\n                                }\n                                lookup[indexThis] = dem._dem.set(x, y, next);\n                                passLookup[indexThis] = p;\n                            }\n                        }\n                    }\n                }\n            }\n        }\n        if (changed) {\n            dem._demTile.needsDEMTextureUpload = true;\n            dem._dem._timestamp = browser.now();\n        }\n    }\n\n    getNodesInfo(): Array<Tiled3dModelFeature> {\n        return this.nodesInfo;\n    }\n\n    destroy() {\n        const nodesInfo = this.getNodesInfo();\n        for (const nodeInfo of nodesInfo) {\n            destroyNodeArrays(nodeInfo.node);\n            destroyBuffers(nodeInfo.node);\n        }\n    }\n\n    isEmpty(): boolean {\n        return !this.nodesInfo.length;\n    }\n\n    updateReplacement(coord: OverscaledTileID, source: ReplacementSource) {\n        // Replacement has to be re-checked if the source has been updated since last time\n        if (source.updateTime === this.replacementUpdateTime) {\n            return;\n        }\n\n        this.replacementUpdateTime = source.updateTime;\n        const activeReplacements = source.getReplacementRegionsForTile(coord.toUnwrapped());\n        const nodesInfo = this.getNodesInfo();\n\n        for (let i = 0; i < this.nodesInfo.length; i++) {\n            const node = nodesInfo[i].node;\n\n            // Node is visible if its footprint passes the replacement check\n            nodesInfo[i].hiddenByReplacement = !!node.footprint && !activeReplacements.find(region => region.footprint === node.footprint);\n        }\n    }\n\n    getHeightAtTileCoord(x: number, y: number): {\n        height: number | null | undefined;\n        maxHeight: number;\n        hidden: boolean;\n        verticalScale: number;\n    } | null | undefined {\n        const nodesInfo = this.getNodesInfo();\n        const candidates = [];\n\n        const tmpVertex = [0, 0, 0];\n\n        const nodeInverse = mat4.identity([] as any);\n\n        for (let i = 0; i < this.nodesInfo.length; i++) {\n            const nodeInfo = nodesInfo[i];\n            assert(nodeInfo.node.meshes.length > 0);\n            const mesh = nodeInfo.node.meshes[0];\n            const meshAabb = mesh.transformedAabb;\n            if (x < meshAabb.min[0] || y < meshAabb.min[1] || x > meshAabb.max[0] || y > meshAabb.max[1]) continue;\n            if (nodeInfo.node.hidden === true) return {height: 0.0, maxHeight: nodeInfo.feature.properties[\"height\"], hidden: false, verticalScale: nodeInfo.evaluatedScale[2]};\n\n            assert(mesh.heightmap);\n\n            mat4.invert(nodeInverse, nodeInfo.node.matrix);\n            tmpVertex[0] = x;\n            tmpVertex[1] = y;\n            vec3.transformMat4(tmpVertex as [number, number, number], tmpVertex as [number, number, number], nodeInverse);\n\n            const xCell = ((tmpVertex[0] - mesh.aabb.min[0]) / (mesh.aabb.max[0] - mesh.aabb.min[0]) * HEIGHTMAP_DIM) | 0;\n            const yCell = ((tmpVertex[1] - mesh.aabb.min[1]) / (mesh.aabb.max[1] - mesh.aabb.min[1]) * HEIGHTMAP_DIM) | 0;\n            const heightmapIndex = Math.min(HEIGHTMAP_DIM - 1, yCell) * HEIGHTMAP_DIM + Math.min(HEIGHTMAP_DIM - 1, xCell);\n            const heightValue = mesh.heightmap[heightmapIndex];\n            if (heightValue < 0 && nodeInfo.node.footprint) {\n                // unpopulated cell. If it is in the building footprint, return undefined height\n                nodeInfo.node.footprint.grid.query(new Point(x, y), new Point(x, y), candidates);\n                if (candidates.length > 0) {\n                    return {height: undefined, maxHeight: nodeInfo.feature.properties[\"height\"], hidden: nodeInfo.hiddenByReplacement, verticalScale: nodeInfo.evaluatedScale[2]};\n                }\n                continue;\n            }\n            if (nodeInfo.hiddenByReplacement) return; // better luck with the next source\n            return {height: heightValue, maxHeight: nodeInfo.feature.properties[\"height\"], hidden: false, verticalScale: nodeInfo.evaluatedScale[2]};\n        }\n    }\n}\n\nfunction expressionRequiresReevaluation(e: any, brightnessChanged: boolean): boolean {\n    assert(e.kind === 'constant' || e instanceof ZoomConstantExpression);\n    return !e.isLightConstant && brightnessChanged;\n}\n\nfunction encodeEmissionToByte(emission: number) {\n    const clampedEmission = clamp(emission, 0, 2);\n    return Math.min(Math.round(0.5 * clampedEmission * 255), 255);\n}\n\nfunction addPBRVertex(vertexArray: FeatureVertexArray, color: number, colorMix: vec4, rmea: vec4, heightBasedEmissionMultiplierParams: [number, number, number, number, number], zMin: number, zMax: number, lightsFeatureArray?: FeatureVertexArray) {\n    let r = ((color & 0xF000) | ((color & 0xF000) >> 4)) >> 8;\n    let g = ((color & 0x0F00) | ((color & 0x0F00) >> 4)) >> 4;\n    let b = (color & 0x00F0) | ((color & 0x00F0) >> 4);\n    if (colorMix[3] > 0) {\n        r = interpolate(r, 255 * colorMix[0], colorMix[3]);\n        g = interpolate(g, 255 * colorMix[1], colorMix[3]);\n        b = interpolate(b, 255 * colorMix[2], colorMix[3]);\n    }\n\n    const a0 = (r << 8) | g;\n    const a1 = (b << 8) | Math.floor(rmea[3] * 255);\n    const a2 = (encodeEmissionToByte(rmea[2]) << 8) | ((rmea[0] * 15) << 4) | (rmea[1] * 15);\n\n    const emissionMultiplierStart = clamp(heightBasedEmissionMultiplierParams[0], 0, 1);\n    const emissionMultiplierFinish = clamp(heightBasedEmissionMultiplierParams[1], 0, 1);\n    const emissionMultiplierValueStart = clamp(heightBasedEmissionMultiplierParams[2], 0, 1);\n    const emissionMultiplierValueFinish = clamp(heightBasedEmissionMultiplierParams[3], 0, 1);\n\n    let a3, b0, b1, b2;\n\n    if (emissionMultiplierStart !== emissionMultiplierFinish && zMax !== zMin &&\n        emissionMultiplierFinish !== emissionMultiplierStart) {\n        const zRange = zMax - zMin;\n        b0 = 1.0 / (zRange * (emissionMultiplierFinish - emissionMultiplierStart));\n        b1 = -(zMin + zRange * emissionMultiplierStart) /\n                       (zRange * (emissionMultiplierFinish - emissionMultiplierStart));\n        const power = clamp(heightBasedEmissionMultiplierParams[4], -1, 1);\n        b2 = Math.pow(10, power);\n        a3 = (emissionMultiplierValueStart * 255.0 << 8) | (emissionMultiplierValueFinish * 255.0);\n    } else {\n        a3 = (255 << 8) | 255;\n        b0 = 0;\n        b1 = 1;\n        b2 = 1;\n    }\n\n    vertexArray.emplaceBack(a0, a1, a2, a3, b0, b1, b2);\n    if (lightsFeatureArray) {\n        const size = lightsFeatureArray.length;\n        lightsFeatureArray.clear();\n        for (let j = 0; j < size; j++) {\n            lightsFeatureArray.emplaceBack(a0, a1, a2, a3, b0, b1, b2);\n        }\n    }\n}\n\nfunction updateNodeFeatureVertices(nodeInfo: Tiled3dModelFeature, doorLightChanged: boolean, modelTraits: number) {\n    const node = nodeInfo.node;\n    let i = 0;\n    const isV2Tile = modelTraits & ModelTraits.HasMeshoptCompression;\n    for (const mesh of node.meshes) {\n        if (node.lights && node.lightMeshIndex === i) continue;\n        if (!mesh.featureData) continue;\n        // initialize featureArray\n        mesh.featureArray = new FeatureVertexArray();\n        // @ts-expect-error - TS2339 - Property 'length' does not exist on type 'ArrayBufferView'.\n        mesh.featureArray.reserve(mesh.featureData.length);\n        let pendingDoorLightUpdate = doorLightChanged;\n        // @ts-expect-error - TS2488 - Type 'ArrayBufferView' must have a '[Symbol.iterator]()' method that returns an iterator.\n        for (const feature of mesh.featureData) {\n            // V1 and V2 tiles have a different bit structure\n            // In V2, meshopt compression forces to use values less than 2^24 to not lose any information\n            // That's why colors are in the least significant bits and use the following LSB to encode\n            // part ids.\n            const featureColor = isV2Tile ? feature & 0xffff : (feature >> 16) & 0xffff;\n            const id = isV2Tile ? (feature >> 16) & 0xffff : feature & 0xffff;\n            const partId = (id & 0xf) < 8 ? (id & 0xf) : 0;\n\n            const rmea = nodeInfo.evaluatedRMEA[partId];\n            const evaluatedColor = nodeInfo.evaluatedColor[partId];\n            const emissionParams = nodeInfo.emissionHeightBasedParams[partId];\n\n            let lightsFeatureArray: FeatureVertexArray | null;\n            if (pendingDoorLightUpdate && partId === PartIndices.door && node.lights) {\n                lightsFeatureArray = new FeatureVertexArray();\n                lightsFeatureArray.resize(node.lights.length * 10);\n            }\n            addPBRVertex(mesh.featureArray, featureColor, evaluatedColor, rmea, emissionParams, mesh.aabb.min[2], mesh.aabb.max[2], lightsFeatureArray);\n            if (lightsFeatureArray && pendingDoorLightUpdate) {\n                pendingDoorLightUpdate = false;\n                const lightsMesh = node.meshes[node.lightMeshIndex];\n                lightsMesh.featureArray = lightsFeatureArray;\n                lightsMesh.featureArray._trim();\n            }\n        }\n        mesh.featureArray._trim();\n        i++;\n    }\n\n}\n\nregister(Tiled3dModelBucket, 'Tiled3dModelBucket', {omit: ['layers']});\nregister(Tiled3dModelFeature, 'Tiled3dModelFeature');\n\nexport default Tiled3dModelBucket;\n","import StyleLayer from '../../../src/style/style_layer';\nimport ModelBucket from '../../data/bucket/model_bucket';\nimport {getLayoutProperties, getPaintProperties} from './model_style_layer_properties';\nimport {Transitionable, Transitioning, PossiblyEvaluated, PropertyValue} from '../../../src/style/properties';\nimport Point from '@mapbox/point-geometry';\nimport {ZoomDependentExpression} from '../../../src/style-spec/expression/index';\nimport {mat4} from 'gl-matrix';\n\nimport type {LayerSpecification} from '../../../src/style-spec/types';\nimport type {PaintProps, LayoutProps} from './model_style_layer_properties';\nimport type {BucketParameters, Bucket} from '../../../src/data/bucket';\nimport type {ConfigOptions} from '../../../src/style/properties';\nimport type {TilespaceQueryGeometry} from '../../../src/style/query_geometry';\nimport type {FeatureState} from '../../../src/style-spec/expression/index';\nimport type Transform from '../../../src/geo/transform';\nimport ModelManager from '../../render/model_manager';\nimport {calculateModelMatrix} from '../../data/model';\nimport type {Node} from '../../data/model';\nimport LngLat from '../../../src/geo/lng_lat';\n\nimport {latFromMercatorY, lngFromMercatorX} from '../../../src/geo/mercator_coordinate';\nimport EXTENT from '../../../src/style-spec/data/extent';\nimport {convertModelMatrixForGlobe, queryGeometryIntersectsProjectedAabb} from '../../util/model_util';\nimport type {VectorTileFeature} from '@mapbox/vector-tile';\nimport Tiled3dModelBucket from '../../data/bucket/tiled_3d_model_bucket';\nimport type {FeatureFilter} from '../../../src/style-spec/feature_filter/index';\nimport type {GeoJSONFeature} from '../../../src/util/vectortile_to_geojson';\nimport {CanonicalTileID} from '../../../src/source/tile_id';\nimport EvaluationParameters from '../../../src/style/evaluation_parameters';\nimport type {LUT} from \"../../../src/util/lut\";\n\nclass ModelStyleLayer extends StyleLayer {\n    _transitionablePaint: Transitionable<PaintProps>;\n    _transitioningPaint: Transitioning<PaintProps>;\n    paint: PossiblyEvaluated<PaintProps>;\n    layout: PossiblyEvaluated<LayoutProps>;\n    modelManager: ModelManager;\n\n    constructor(layer: LayerSpecification, scope: string, lut: LUT | null, options?: ConfigOptions | null) {\n        const properties = {\n            layout: getLayoutProperties(),\n            paint: getPaintProperties()\n        };\n        super(layer, properties, scope, lut, options);\n        this._stats = {numRenderedVerticesInShadowPass : 0, numRenderedVerticesInTransparentPass: 0};\n    }\n\n    createBucket(parameters: BucketParameters<ModelStyleLayer>): ModelBucket {\n        return new ModelBucket(parameters);\n    }\n\n    getProgramIds(): Array<string> {\n        return ['model'];\n    }\n\n    is3D(): boolean {\n        return true;\n    }\n\n    hasShadowPass(): boolean {\n        return true;\n    }\n\n    canCastShadows(): boolean {\n        return true;\n    }\n\n    hasLightBeamPass(): boolean {\n        return true;\n    }\n\n    cutoffRange(): number {\n\n        return this.paint.get('model-cutoff-fade-range');\n    }\n\n    queryRadius(bucket: Bucket): number {\n        return (bucket instanceof Tiled3dModelBucket) ? EXTENT - 1 : 0;\n    }\n\n    queryIntersectsFeature(\n        queryGeometry: TilespaceQueryGeometry,\n        feature: VectorTileFeature,\n        featureState: FeatureState,\n        geometry: Array<Array<Point>>,\n        zoom: number,\n        transform: Transform,\n    ): number | boolean {\n        if (!this.modelManager) return false;\n        const modelManager = this.modelManager;\n        const b = queryGeometry.tile.getBucket(this);\n        if (!b || !(b instanceof ModelBucket)) return false;\n        const bucket: ModelBucket = (b as any);\n\n        for (const modelId in bucket.instancesPerModel) {\n            const instances = bucket.instancesPerModel[modelId];\n            const featureId = feature.id !== undefined ? feature.id :\n                (feature.properties && feature.properties.hasOwnProperty(\"id\")) ? feature.properties[\"id\"] : undefined;\n            if (instances.idToFeaturesIndex.hasOwnProperty(featureId)) {\n                const modelFeature = instances.features[instances.idToFeaturesIndex[featureId]];\n                const model = modelManager.getModel(modelId, this.scope);\n                if (!model) return false;\n\n                let matrix: mat4 = mat4.create();\n                const position = new LngLat(0, 0);\n                const id = bucket.canonical;\n                let minDepth = Number.MAX_VALUE;\n                for (let i = 0; i < modelFeature.instancedDataCount; ++i) {\n                    const instanceOffset = modelFeature.instancedDataOffset + i;\n                    const offset = instanceOffset * 16;\n\n                    const va = instances.instancedDataArray.float32;\n                    const translation = [va[offset + 4], va[offset + 5], va[offset + 6]];\n                    const pointX = va[offset];\n                    const pointY = va[offset + 1] | 0; // point.y stored in integer part\n\n                    tileToLngLat(id, position, pointX, pointY);\n\n                    calculateModelMatrix(matrix,\n                                         model,\n                                         transform,\n                                         position,\n                                         modelFeature.rotation,\n                                         modelFeature.scale,\n                                         // @ts-expect-error - TS2345 - Argument of type 'any[]' is not assignable to parameter of type 'vec3'.\n                                         translation,\n                                         false,\n                                         false,\n                                         false);\n                    if (transform.projection.name === 'globe') {\n                        matrix = convertModelMatrixForGlobe(matrix, transform);\n                    }\n                    // @ts-expect-error - TS2345 - Argument of type 'number[] | Float32Array | Float64Array' is not assignable to parameter of type 'ReadonlyMat4'.\n                    const worldViewProjection = mat4.multiply([] as any, transform.projMatrix, matrix);\n                    // Collision checks are performed in screen space. Corners are in ndc space.\n                    const screenQuery = queryGeometry.queryGeometry;\n                    const projectedQueryGeometry = screenQuery.isPointQuery() ? screenQuery.screenBounds : screenQuery.screenGeometry;\n                    const depth = queryGeometryIntersectsProjectedAabb(projectedQueryGeometry, transform, worldViewProjection, model.aabb);\n                    if (depth != null) {\n                        minDepth = Math.min(depth, minDepth);\n                    }\n                }\n                if (minDepth !== Number.MAX_VALUE) {\n                    return minDepth;\n                }\n                return false;\n            }\n        }\n        return false;\n    }\n\n    _handleOverridablePaintPropertyUpdate<T, R>(name: string, oldValue: PropertyValue<T, R>, newValue: PropertyValue<T, R>): boolean {\n        if (!this.layout || oldValue.isDataDriven() || newValue.isDataDriven()) {\n            return false;\n        }\n        // relayout on programatically setPaintProperty for all non-data-driven properties that get baked into vertex data.\n        // Buckets could be updated without relayout later, if needed to optimize.\n        return name === \"model-color\" || name === \"model-color-mix-intensity\" || name === \"model-rotation\" || name === \"model-scale\" || name === \"model-translation\" || name === \"model-emissive-strength\";\n    }\n\n    _isPropertyZoomDependent(name: string): boolean {\n        const prop = this._transitionablePaint._values[name];\n        return prop != null && prop.value != null &&\n            prop.value.expression != null &&\n            prop.value.expression instanceof ZoomDependentExpression;\n    }\n\n    isZoomDependent(): boolean {\n        return this._isPropertyZoomDependent('model-scale') ||\n            this._isPropertyZoomDependent('model-rotation') ||\n            this._isPropertyZoomDependent('model-translation');\n    }\n\n    queryIntersectsMatchingFeature(\n        queryGeometry: TilespaceQueryGeometry,\n        featureIndex: number,\n        filter: FeatureFilter,\n        transform: Transform,\n    ): {\n        queryFeature: GeoJSONFeature | null | undefined;\n        intersectionZ: number;\n    } {\n\n        const tile = queryGeometry.tile;\n        const b = tile.getBucket(this);\n        let queryFeature = null;\n        let intersectionZ = Number.MAX_VALUE;\n        if (!b || !(b instanceof Tiled3dModelBucket)) return {queryFeature, intersectionZ};\n        const bucket: Tiled3dModelBucket = (b as any);\n\n        const nodeInfo = bucket.getNodesInfo()[featureIndex];\n\n        if (nodeInfo.hiddenByReplacement ||\n            !nodeInfo.node.meshes ||\n            !filter.filter(new EvaluationParameters(tile.tileID.overscaledZ), nodeInfo.feature, tile.tileID.canonical)) {\n            return {queryFeature, intersectionZ};\n        }\n\n        // AABB check\n        const node = nodeInfo.node;\n        const tileMatrix = transform.calculatePosMatrix(tile.tileID.toUnwrapped(), transform.worldSize);\n        const modelMatrix = tileMatrix;\n        const scale = nodeInfo.evaluatedScale;\n        let elevation = 0;\n        if (transform.elevation && node.elevation) {\n            elevation = node.elevation * transform.elevation.exaggeration();\n        }\n        const anchorX = node.anchor ? node.anchor[0] : 0;\n        const anchorY = node.anchor ? node.anchor[1] : 0;\n\n        // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'mat4'.\n        mat4.translate(modelMatrix, modelMatrix, [anchorX * (scale[0] - 1),\n            anchorY * (scale[1] - 1),\n            elevation]);\n        // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'mat4'.\n        mat4.scale(modelMatrix, modelMatrix, scale);\n\n        // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'mat4'.\n        mat4.multiply(modelMatrix, modelMatrix, node.matrix);\n\n        // Collision checks are performed in screen space. Corners are in ndc space.\n        const screenQuery = queryGeometry.queryGeometry;\n        const projectedQueryGeometry = screenQuery.isPointQuery() ? screenQuery.screenBounds : screenQuery.screenGeometry;\n\n        const checkNode = function(n: Node) {\n            // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'ReadonlyMat4'.\n            const nodeModelMatrix = mat4.multiply([] as any, modelMatrix, n.matrix);\n            // @ts-expect-error - TS2345 - Argument of type 'number[] | Float32Array | Float64Array' is not assignable to parameter of type 'ReadonlyMat4'.\n            const worldViewProjection = mat4.multiply(nodeModelMatrix, transform.expandedFarZProjMatrix, nodeModelMatrix);\n            for (let i = 0; i < n.meshes.length; ++i) {\n                const mesh = n.meshes[i];\n                if (i === n.lightMeshIndex) {\n                    continue;\n                }\n                const depth = queryGeometryIntersectsProjectedAabb(projectedQueryGeometry, transform, worldViewProjection, mesh.aabb);\n                if (depth != null) {\n                    intersectionZ = Math.min(depth, intersectionZ);\n                }\n            }\n            if (n.children) {\n                for (const child of n.children) {\n                    checkNode(child);\n                }\n            }\n        };\n\n        checkNode(node);\n        if (intersectionZ === Number.MAX_VALUE) {\n            return {queryFeature, intersectionZ};\n        }\n\n        const position = new LngLat(0, 0);\n        tileToLngLat(tile.tileID.canonical, position, nodeInfo.node.anchor[0], nodeInfo.node.anchor[1]);\n        queryFeature = {\n            type: 'Feature',\n            geometry: {type: \"Point\", coordinates: [position.lng, position.lat]},\n            properties: nodeInfo.feature.properties,\n            id: nodeInfo.feature.id,\n            state: {}, // append later\n            layer: this.serialize()\n        };\n        return {queryFeature, intersectionZ};\n    }\n}\n\nexport default ModelStyleLayer;\n\nfunction tileToLngLat(id: CanonicalTileID, position: LngLat, pointX: number, pointY: number) {\n    const tileCount = 1 << id.z;\n    position.lat = latFromMercatorY((pointY / EXTENT + id.y) / tileCount);\n    position.lng = lngFromMercatorX((pointX / EXTENT + id.x) / tileCount);\n}\n","import type StyleLayer from './style_layer';\nimport circle from './style_layer/circle_style_layer';\nimport heatmap from './style_layer/heatmap_style_layer';\nimport hillshade from './style_layer/hillshade_style_layer';\nimport fill from './style_layer/fill_style_layer';\nimport clip from './style_layer/clip_style_layer';\nimport fillExtrusion from './style_layer/fill_extrusion_style_layer';\nimport line from './style_layer/line_style_layer';\nimport symbol from './style_layer/symbol_style_layer';\nimport background from './style_layer/background_style_layer';\nimport raster from './style_layer/raster_style_layer';\nimport rasterParticle from './style_layer/raster_particle_style_layer';\nimport CustomStyleLayer from './style_layer/custom_style_layer';\nimport sky from './style_layer/sky_style_layer';\nimport slot from './style_layer/slot_style_layer';\nimport type {CustomLayerInterface} from './style_layer/custom_style_layer';\nimport model from '../../3d-style/style/style_layer/model_style_layer';\n\nimport type {LayerSpecification} from '../style-spec/types';\nimport type {ConfigOptions} from './properties';\nimport type {LUT} from \"../util/lut\";\n\nconst subclasses = {\n    circle,\n    heatmap,\n    hillshade,\n    fill,\n    'fill-extrusion': fillExtrusion,\n    line,\n    symbol,\n    background,\n    raster,\n    'raster-particle': rasterParticle,\n    sky,\n    slot,\n    model,\n    clip\n};\n\nexport default function createStyleLayer(\n    layer: LayerSpecification | CustomLayerInterface,\n    scope: string,\n    lut: LUT | null,\n    options?: ConfigOptions | null,\n): StyleLayer | CustomStyleLayer {\n    if (layer.type === 'custom') {\n        return new CustomStyleLayer(layer, scope);\n    } else {\n        return new subclasses[layer.type](layer, scope, lut, options);\n    }\n}\n","import StyleLayer from '../style_layer';\n\nimport HeatmapBucket from '../../data/bucket/heatmap_bucket';\nimport {RGBAImage} from '../../util/image';\nimport {getLayoutProperties, getPaintProperties} from './heatmap_style_layer_properties';\nimport {renderColorRamp} from '../../util/color_ramp';\nimport {Transitionable, Transitioning, PossiblyEvaluated} from '../properties';\nimport {queryIntersectsCircle} from './circle_style_layer';\nimport {getMaximumPaintValue} from '../query_utils';\nimport Point from '@mapbox/point-geometry';\n\nimport type {Bucket, BucketParameters} from '../../data/bucket';\nimport type Texture from '../../render/texture';\nimport type Framebuffer from '../../gl/framebuffer';\nimport type {PaintProps} from './heatmap_style_layer_properties';\nimport type {LayerSpecification} from '../../style-spec/types';\nimport ProgramConfiguration from '../../data/program_configuration';\nimport type {TilespaceQueryGeometry} from '../query_geometry';\nimport type {DEMSampler} from '../../terrain/elevation';\nimport type {FeatureState} from '../../style-spec/expression/index';\nimport type Transform from '../../geo/transform';\nimport type CircleBucket from '../../data/bucket/circle_bucket';\nimport type {VectorTileFeature} from '@mapbox/vector-tile';\nimport type {CreateProgramParams} from '../../render/painter';\nimport type {ConfigOptions} from '../properties';\nimport type {LUT} from \"../../util/lut\";\n\nclass HeatmapStyleLayer extends StyleLayer {\n\n    heatmapFbo: Framebuffer | null | undefined;\n    colorRamp: RGBAImage;\n    colorRampTexture: Texture | null | undefined;\n\n    _transitionablePaint: Transitionable<PaintProps>;\n    _transitioningPaint: Transitioning<PaintProps>;\n    paint: PossiblyEvaluated<PaintProps>;\n\n    createBucket(parameters: BucketParameters<HeatmapStyleLayer>): HeatmapBucket {\n        return new HeatmapBucket(parameters);\n    }\n\n    constructor(layer: LayerSpecification, scope: string, lut: LUT | null, options?: ConfigOptions | null) {\n        const properties = {\n            layout: getLayoutProperties(),\n            paint: getPaintProperties()\n        };\n        super(layer, properties, scope, lut, options);\n\n        // make sure color ramp texture is generated for default heatmap color too\n        this._updateColorRamp();\n    }\n\n    _handleSpecialPaintPropertyUpdate(name: string) {\n        if (name === 'heatmap-color') {\n            this._updateColorRamp();\n        }\n    }\n\n    _updateColorRamp() {\n        const expression = this._transitionablePaint._values['heatmap-color'].value.expression;\n        this.colorRamp = renderColorRamp({\n            expression,\n            evaluationKey: 'heatmapDensity',\n            image: this.colorRamp\n        });\n        this.colorRampTexture = null;\n    }\n\n    resize() {\n        if (this.heatmapFbo) {\n            this.heatmapFbo.destroy();\n            this.heatmapFbo = null;\n        }\n    }\n\n    queryRadius(bucket: Bucket): number {\n        return getMaximumPaintValue('heatmap-radius', this, (bucket as CircleBucket<any>));\n    }\n\n    queryIntersectsFeature(\n        queryGeometry: TilespaceQueryGeometry,\n        feature: VectorTileFeature,\n        featureState: FeatureState,\n        geometry: Array<Array<Point>>,\n        zoom: number,\n        transform: Transform,\n        pixelPosMatrix: Float32Array,\n        elevationHelper?: DEMSampler | null,\n    ): boolean {\n\n        // @ts-expect-error - TS2339 - Property 'evaluate' does not exist on type 'unknown'.\n        const size = this.paint.get('heatmap-radius').evaluate(feature, featureState);\n        return queryIntersectsCircle(\n            queryGeometry, geometry, transform, pixelPosMatrix, elevationHelper,\n            true, true, new Point(0, 0), size);\n    }\n\n    hasOffscreenPass(): boolean {\n        return this.paint.get('heatmap-opacity') !== 0 && this.visibility !== 'none';\n    }\n\n    getProgramIds(): Array<string> {\n        return ['heatmap', 'heatmapTexture'];\n    }\n\n    getDefaultProgramParams(name: string, zoom: number, lut: LUT | null): CreateProgramParams | null {\n        if (name === 'heatmap') {\n            return {\n                config: new ProgramConfiguration(this, {zoom, lut}),\n                overrideFog: false\n            };\n        }\n        return {};\n    }\n}\n\nexport default HeatmapStyleLayer;\n","import StyleLayer from '../style_layer';\n\nimport {getLayoutProperties, getPaintProperties} from './hillshade_style_layer_properties';\nimport {Transitionable, Transitioning, PossiblyEvaluated} from '../properties';\n\nimport type {PaintProps} from './hillshade_style_layer_properties';\nimport type {LayerSpecification} from '../../style-spec/types';\nimport type {CreateProgramParams} from '../../render/painter';\nimport type {ConfigOptions} from '../properties';\nimport type {LUT} from \"../../util/lut\";\n\nclass HillshadeStyleLayer extends StyleLayer {\n    _transitionablePaint: Transitionable<PaintProps>;\n    _transitioningPaint: Transitioning<PaintProps>;\n    paint: PossiblyEvaluated<PaintProps>;\n\n    constructor(layer: LayerSpecification, scope: string, lut: LUT | null, options?: ConfigOptions | null) {\n        const properties = {\n            layout: getLayoutProperties(),\n            paint: getPaintProperties()\n        };\n        super(layer, properties, scope, lut, options);\n    }\n\n    hasOffscreenPass(): boolean {\n        return this.paint.get('hillshade-exaggeration') !== 0 && this.visibility !== 'none';\n    }\n\n    getProgramIds(): Array<string> {\n        return ['hillshade', 'hillshadePrepare'];\n    }\n\n    // eslint-disable-next-line no-unused-vars\n    getDefaultProgramParams(name: string, zoom: number, lut: LUT | null): CreateProgramParams | null {\n        return {\n            overrideFog: false\n        };\n    }\n}\n\nexport default HillshadeStyleLayer;\n","import StyleLayer from '../style_layer';\n\nimport FillBucket from '../../data/bucket/fill_bucket';\nimport {polygonIntersectsMultiPolygon} from '../../util/intersection_tests';\nimport {translateDistance, translate} from '../query_utils';\nimport {getLayoutProperties, getPaintProperties} from './fill_style_layer_properties';\nimport {Transitionable, Transitioning, Layout, PossiblyEvaluated} from '../properties';\nimport ProgramConfiguration from '../../data/program_configuration';\n\nimport type {FeatureState} from '../../style-spec/expression/index';\nimport type {BucketParameters} from '../../data/bucket';\nimport type Point from '@mapbox/point-geometry';\nimport type {LayoutProps, PaintProps} from './fill_style_layer_properties';\nimport type EvaluationParameters from '../evaluation_parameters';\nimport type Transform from '../../geo/transform';\nimport type {LayerSpecification} from '../../style-spec/types';\nimport type {TilespaceQueryGeometry} from '../query_geometry';\nimport type {VectorTileFeature} from '@mapbox/vector-tile';\nimport type {CreateProgramParams} from '../../render/painter';\nimport type {ConfigOptions} from '../properties';\nimport type {LUT} from \"../../util/lut\";\n\nclass FillStyleLayer extends StyleLayer {\n    _unevaluatedLayout: Layout<LayoutProps>;\n    layout: PossiblyEvaluated<LayoutProps>;\n\n    _transitionablePaint: Transitionable<PaintProps>;\n    _transitioningPaint: Transitioning<PaintProps>;\n    paint: PossiblyEvaluated<PaintProps>;\n\n    constructor(layer: LayerSpecification, scope: string, lut: LUT | null, options?: ConfigOptions | null) {\n        const properties = {\n            layout: getLayoutProperties(),\n            paint: getPaintProperties()\n        };\n        super(layer, properties, scope, lut, options);\n    }\n\n    getProgramIds(): string[] {\n        const pattern = this.paint.get('fill-pattern');\n\n        const image = pattern && pattern.constantOr((1 as any));\n\n        const ids = [image ? 'fillPattern' : 'fill'];\n\n        if (this.paint.get('fill-antialias')) {\n            ids.push(image && !this.getPaintProperty('fill-outline-color') ? 'fillOutlinePattern' : 'fillOutline');\n        }\n\n        return ids;\n    }\n\n    getDefaultProgramParams(name: string, zoom: number, lut: LUT | null): CreateProgramParams | null {\n        return {\n            config: new ProgramConfiguration(this, {zoom, lut}),\n            overrideFog: false\n        };\n    }\n\n    recalculate(parameters: EvaluationParameters, availableImages: Array<string>) {\n        super.recalculate(parameters, availableImages);\n\n        const outlineColor = this.paint._values['fill-outline-color'];\n\n        if (outlineColor.value.kind === 'constant' && outlineColor.value.value === undefined) {\n            this.paint._values['fill-outline-color'] = this.paint._values['fill-color'];\n        }\n    }\n\n    createBucket(parameters: BucketParameters<FillStyleLayer>): FillBucket {\n        return new FillBucket(parameters);\n    }\n\n    queryRadius(): number {\n\n        return translateDistance(this.paint.get('fill-translate'));\n    }\n\n    queryIntersectsFeature(\n        queryGeometry: TilespaceQueryGeometry,\n        feature: VectorTileFeature,\n        featureState: FeatureState,\n        geometry: Array<Array<Point>>,\n        zoom: number,\n        transform: Transform,\n    ): boolean {\n        if (queryGeometry.queryGeometry.isAboveHorizon) return false;\n\n        const translatedPolygon = translate(queryGeometry.tilespaceGeometry,\n\n            this.paint.get('fill-translate'),\n            this.paint.get('fill-translate-anchor'),\n            transform.angle, queryGeometry.pixelToTileUnitsFactor);\n        return polygonIntersectsMultiPolygon(translatedPolygon, geometry);\n    }\n\n    isTileClipped(): boolean {\n        return true;\n    }\n}\n\nexport default FillStyleLayer;\n","import StyleLayer from '../style_layer';\n\nimport {getLayoutProperties, getPaintProperties} from './background_style_layer_properties';\nimport {Transitionable, Transitioning, PossiblyEvaluated} from '../properties';\n\nimport type {PaintProps} from './background_style_layer_properties';\nimport type {LayerSpecification} from '../../style-spec/types';\nimport type {CreateProgramParams} from '../../render/painter';\nimport type {ConfigOptions} from '../properties';\nimport type {LUT} from \"../../util/lut\";\n\nclass BackgroundStyleLayer extends StyleLayer {\n    _transitionablePaint: Transitionable<PaintProps>;\n    _transitioningPaint: Transitioning<PaintProps>;\n    paint: PossiblyEvaluated<PaintProps>;\n\n    constructor(layer: LayerSpecification, scope: string, lut: LUT | null, options?: ConfigOptions | null) {\n        const properties = {\n            layout: getLayoutProperties(),\n            paint: getPaintProperties()\n        };\n        super(layer, properties, scope, lut, options);\n    }\n\n    getProgramIds(): Array<string> {\n        const image = this.paint.get('background-pattern');\n        return [image ? 'backgroundPattern' : 'background'];\n    }\n\n    // eslint-disable-next-line no-unused-vars\n    getDefaultProgramParams(name: string, zoom: number, lut: LUT | null): CreateProgramParams | null {\n        return {\n            overrideFog: false\n        };\n    }\n}\n\nexport default BackgroundStyleLayer;\n","import StyleLayer from '../style_layer';\n\nimport {getPaintProperties} from './slot_style_layer_properties';\n\nimport type {LayerSpecification} from '../../style-spec/types';\nimport type {LUT} from \"../../util/lut\";\n\nclass SlotStyleLayer extends StyleLayer {\n    constructor(layer: LayerSpecification, scope: string, _lut: LUT | null, _: unknown) {\n        const properties = {\n            paint: getPaintProperties()\n        };\n        super(layer, properties, scope, null);\n    }\n}\n\nexport default SlotStyleLayer;\n","import StyleLayer from '../style_layer';\n\nimport ClipBucket from '../../data/bucket/clip_bucket';\nimport {getLayoutProperties, getPaintProperties} from './clip_style_layer_properties';\nimport {Layout, PossiblyEvaluated} from '../properties';\n\nimport type {BucketParameters} from '../../data/bucket';\nimport type {LayoutProps, PaintProps} from './clip_style_layer_properties';\nimport type EvaluationParameters from '../evaluation_parameters';\nimport type {LayerSpecification} from '../../style-spec/types';\nimport type {ConfigOptions} from '../properties';\nimport type {LUT} from \"../../util/lut\";\n\nclass ClipStyleLayer extends StyleLayer {\n    _unevaluatedLayout: Layout<LayoutProps>;\n    layout: PossiblyEvaluated<LayoutProps>;\n    paint: PossiblyEvaluated<PaintProps>;\n\n    constructor(layer: LayerSpecification, scope: string, lut: LUT | null, options?: ConfigOptions | null) {\n        const properties = {\n            layout: getLayoutProperties(),\n            paint: getPaintProperties()\n        };\n        super(layer, properties, scope, lut, options);\n    }\n\n    recalculate(parameters: EvaluationParameters, availableImages: Array<string>) {\n        super.recalculate(parameters, availableImages);\n    }\n\n    createBucket(parameters: BucketParameters<ClipStyleLayer>): ClipBucket {\n        return new ClipBucket(parameters);\n    }\n\n    isTileClipped(): boolean {\n        return true;\n    }\n\n    is3D(): boolean {\n        return true;\n    }\n}\n\nexport default ClipStyleLayer;\n","import {register} from '../util/web_worker_transfer';\nimport {MRTDecodingBatch} from './mrt/mrt.esm.js';\n\nregister(MRTDecodingBatch, 'MRTDecodingBatch', {omit: ['_onCancel', '_onComplete']});\n","\nconst ARRAY_TYPES = [\n    Int8Array, Uint8Array, Uint8ClampedArray, Int16Array, Uint16Array,\n    Int32Array, Uint32Array, Float32Array, Float64Array\n];\n\n/** @typedef {Int8ArrayConstructor | Uint8ArrayConstructor | Uint8ClampedArrayConstructor | Int16ArrayConstructor | Uint16ArrayConstructor | Int32ArrayConstructor | Uint32ArrayConstructor | Float32ArrayConstructor | Float64ArrayConstructor} TypedArrayConstructor */\n\nconst VERSION = 1; // serialized format version\nconst HEADER_SIZE = 8;\n\nexport default class KDBush {\n\n    /**\n     * Creates an index from raw `ArrayBuffer` data.\n     * @param {ArrayBuffer} data\n     */\n    static from(data) {\n        if (!(data instanceof ArrayBuffer)) {\n            throw new Error('Data must be an instance of ArrayBuffer.');\n        }\n        const [magic, versionAndType] = new Uint8Array(data, 0, 2);\n        if (magic !== 0xdb) {\n            throw new Error('Data does not appear to be in a KDBush format.');\n        }\n        const version = versionAndType >> 4;\n        if (version !== VERSION) {\n            throw new Error(`Got v${version} data when expected v${VERSION}.`);\n        }\n        const ArrayType = ARRAY_TYPES[versionAndType & 0x0f];\n        if (!ArrayType) {\n            throw new Error('Unrecognized array type.');\n        }\n        const [nodeSize] = new Uint16Array(data, 2, 1);\n        const [numItems] = new Uint32Array(data, 4, 1);\n\n        return new KDBush(numItems, nodeSize, ArrayType, data);\n    }\n\n    /**\n     * Creates an index that will hold a given number of items.\n     * @param {number} numItems\n     * @param {number} [nodeSize=64] Size of the KD-tree node (64 by default).\n     * @param {TypedArrayConstructor} [ArrayType=Float64Array] The array type used for coordinates storage (`Float64Array` by default).\n     * @param {ArrayBuffer} [data] (For internal use only)\n     */\n    constructor(numItems, nodeSize = 64, ArrayType = Float64Array, data) {\n        if (isNaN(numItems) || numItems < 0) throw new Error(`Unpexpected numItems value: ${numItems}.`);\n\n        this.numItems = +numItems;\n        this.nodeSize = Math.min(Math.max(+nodeSize, 2), 65535);\n        this.ArrayType = ArrayType;\n        this.IndexArrayType = numItems < 65536 ? Uint16Array : Uint32Array;\n\n        const arrayTypeIndex = ARRAY_TYPES.indexOf(this.ArrayType);\n        const coordsByteSize = numItems * 2 * this.ArrayType.BYTES_PER_ELEMENT;\n        const idsByteSize = numItems * this.IndexArrayType.BYTES_PER_ELEMENT;\n        const padCoords = (8 - idsByteSize % 8) % 8;\n\n        if (arrayTypeIndex < 0) {\n            throw new Error(`Unexpected typed array class: ${ArrayType}.`);\n        }\n\n        if (data && (data instanceof ArrayBuffer)) { // reconstruct an index from a buffer\n            this.data = data;\n            this.ids = new this.IndexArrayType(this.data, HEADER_SIZE, numItems);\n            this.coords = new this.ArrayType(this.data, HEADER_SIZE + idsByteSize + padCoords, numItems * 2);\n            this._pos = numItems * 2;\n            this._finished = true;\n        } else { // initialize a new index\n            this.data = new ArrayBuffer(HEADER_SIZE + coordsByteSize + idsByteSize + padCoords);\n            this.ids = new this.IndexArrayType(this.data, HEADER_SIZE, numItems);\n            this.coords = new this.ArrayType(this.data, HEADER_SIZE + idsByteSize + padCoords, numItems * 2);\n            this._pos = 0;\n            this._finished = false;\n\n            // set header\n            new Uint8Array(this.data, 0, 2).set([0xdb, (VERSION << 4) + arrayTypeIndex]);\n            new Uint16Array(this.data, 2, 1)[0] = nodeSize;\n            new Uint32Array(this.data, 4, 1)[0] = numItems;\n        }\n    }\n\n    /**\n     * Add a point to the index.\n     * @param {number} x\n     * @param {number} y\n     * @returns {number} An incremental index associated with the added item (starting from `0`).\n     */\n    add(x, y) {\n        const index = this._pos >> 1;\n        this.ids[index] = index;\n        this.coords[this._pos++] = x;\n        this.coords[this._pos++] = y;\n        return index;\n    }\n\n    /**\n     * Perform indexing of the added points.\n     */\n    finish() {\n        const numAdded = this._pos >> 1;\n        if (numAdded !== this.numItems) {\n            throw new Error(`Added ${numAdded} items when expected ${this.numItems}.`);\n        }\n        // kd-sort both arrays for efficient search\n        sort(this.ids, this.coords, this.nodeSize, 0, this.numItems - 1, 0);\n\n        this._finished = true;\n        return this;\n    }\n\n    /**\n     * Search the index for items within a given bounding box.\n     * @param {number} minX\n     * @param {number} minY\n     * @param {number} maxX\n     * @param {number} maxY\n     * @returns {number[]} An array of indices correponding to the found items.\n     */\n    range(minX, minY, maxX, maxY) {\n        if (!this._finished) throw new Error('Data not yet indexed - call index.finish().');\n\n        const {ids, coords, nodeSize} = this;\n        const stack = [0, ids.length - 1, 0];\n        const result = [];\n\n        // recursively search for items in range in the kd-sorted arrays\n        while (stack.length) {\n            const axis = stack.pop() || 0;\n            const right = stack.pop() || 0;\n            const left = stack.pop() || 0;\n\n            // if we reached \"tree node\", search linearly\n            if (right - left <= nodeSize) {\n                for (let i = left; i <= right; i++) {\n                    const x = coords[2 * i];\n                    const y = coords[2 * i + 1];\n                    if (x >= minX && x <= maxX && y >= minY && y <= maxY) result.push(ids[i]);\n                }\n                continue;\n            }\n\n            // otherwise find the middle index\n            const m = (left + right) >> 1;\n\n            // include the middle item if it's in range\n            const x = coords[2 * m];\n            const y = coords[2 * m + 1];\n            if (x >= minX && x <= maxX && y >= minY && y <= maxY) result.push(ids[m]);\n\n            // queue search in halves that intersect the query\n            if (axis === 0 ? minX <= x : minY <= y) {\n                stack.push(left);\n                stack.push(m - 1);\n                stack.push(1 - axis);\n            }\n            if (axis === 0 ? maxX >= x : maxY >= y) {\n                stack.push(m + 1);\n                stack.push(right);\n                stack.push(1 - axis);\n            }\n        }\n\n        return result;\n    }\n\n    /**\n     * Search the index for items within a given radius.\n     * @param {number} qx\n     * @param {number} qy\n     * @param {number} r Query radius.\n     * @returns {number[]} An array of indices correponding to the found items.\n     */\n    within(qx, qy, r) {\n        if (!this._finished) throw new Error('Data not yet indexed - call index.finish().');\n\n        const {ids, coords, nodeSize} = this;\n        const stack = [0, ids.length - 1, 0];\n        const result = [];\n        const r2 = r * r;\n\n        // recursively search for items within radius in the kd-sorted arrays\n        while (stack.length) {\n            const axis = stack.pop() || 0;\n            const right = stack.pop() || 0;\n            const left = stack.pop() || 0;\n\n            // if we reached \"tree node\", search linearly\n            if (right - left <= nodeSize) {\n                for (let i = left; i <= right; i++) {\n                    if (sqDist(coords[2 * i], coords[2 * i + 1], qx, qy) <= r2) result.push(ids[i]);\n                }\n                continue;\n            }\n\n            // otherwise find the middle index\n            const m = (left + right) >> 1;\n\n            // include the middle item if it's in range\n            const x = coords[2 * m];\n            const y = coords[2 * m + 1];\n            if (sqDist(x, y, qx, qy) <= r2) result.push(ids[m]);\n\n            // queue search in halves that intersect the query\n            if (axis === 0 ? qx - r <= x : qy - r <= y) {\n                stack.push(left);\n                stack.push(m - 1);\n                stack.push(1 - axis);\n            }\n            if (axis === 0 ? qx + r >= x : qy + r >= y) {\n                stack.push(m + 1);\n                stack.push(right);\n                stack.push(1 - axis);\n            }\n        }\n\n        return result;\n    }\n}\n\n/**\n * @param {Uint16Array | Uint32Array} ids\n * @param {InstanceType<TypedArrayConstructor>} coords\n * @param {number} nodeSize\n * @param {number} left\n * @param {number} right\n * @param {number} axis\n */\nfunction sort(ids, coords, nodeSize, left, right, axis) {\n    if (right - left <= nodeSize) return;\n\n    const m = (left + right) >> 1; // middle index\n\n    // sort ids and coords around the middle index so that the halves lie\n    // either left/right or top/bottom correspondingly (taking turns)\n    select(ids, coords, m, left, right, axis);\n\n    // recursively kd-sort first half and second half on the opposite axis\n    sort(ids, coords, nodeSize, left, m - 1, 1 - axis);\n    sort(ids, coords, nodeSize, m + 1, right, 1 - axis);\n}\n\n/**\n * Custom Floyd-Rivest selection algorithm: sort ids and coords so that\n * [left..k-1] items are smaller than k-th item (on either x or y axis)\n * @param {Uint16Array | Uint32Array} ids\n * @param {InstanceType<TypedArrayConstructor>} coords\n * @param {number} k\n * @param {number} left\n * @param {number} right\n * @param {number} axis\n */\nfunction select(ids, coords, k, left, right, axis) {\n\n    while (right > left) {\n        if (right - left > 600) {\n            const n = right - left + 1;\n            const m = k - left + 1;\n            const z = Math.log(n);\n            const s = 0.5 * Math.exp(2 * z / 3);\n            const sd = 0.5 * Math.sqrt(z * s * (n - s) / n) * (m - n / 2 < 0 ? -1 : 1);\n            const newLeft = Math.max(left, Math.floor(k - m * s / n + sd));\n            const newRight = Math.min(right, Math.floor(k + (n - m) * s / n + sd));\n            select(ids, coords, k, newLeft, newRight, axis);\n        }\n\n        const t = coords[2 * k + axis];\n        let i = left;\n        let j = right;\n\n        swapItem(ids, coords, left, k);\n        if (coords[2 * right + axis] > t) swapItem(ids, coords, left, right);\n\n        while (i < j) {\n            swapItem(ids, coords, i, j);\n            i++;\n            j--;\n            while (coords[2 * i + axis] < t) i++;\n            while (coords[2 * j + axis] > t) j--;\n        }\n\n        if (coords[2 * left + axis] === t) swapItem(ids, coords, left, j);\n        else {\n            j++;\n            swapItem(ids, coords, j, right);\n        }\n\n        if (j <= k) left = j + 1;\n        if (k <= j) right = j - 1;\n    }\n}\n\n/**\n * @param {Uint16Array | Uint32Array} ids\n * @param {InstanceType<TypedArrayConstructor>} coords\n * @param {number} i\n * @param {number} j\n */\nfunction swapItem(ids, coords, i, j) {\n    swap(ids, i, j);\n    swap(coords, 2 * i, 2 * j);\n    swap(coords, 2 * i + 1, 2 * j + 1);\n}\n\n/**\n * @param {InstanceType<TypedArrayConstructor>} arr\n * @param {number} i\n * @param {number} j\n */\nfunction swap(arr, i, j) {\n    const tmp = arr[i];\n    arr[i] = arr[j];\n    arr[j] = tmp;\n}\n\n/**\n * @param {number} ax\n * @param {number} ay\n * @param {number} bx\n * @param {number} by\n */\nfunction sqDist(ax, ay, bx, by) {\n    const dx = ax - bx;\n    const dy = ay - by;\n    return dx * dx + dy * dy;\n}\n","import {VectorTile} from '@mapbox/vector-tile';\nimport Protobuf from 'pbf';\nimport {getArrayBuffer} from '../util/ajax';\n\nimport type {Callback} from '../types/callback';\nimport type {RequestedTileParameters} from './worker_source';\nimport type Scheduler from '../util/scheduler';\n\nexport type LoadVectorTileResult = {\n    rawData: ArrayBuffer;\n    vectorTile?: VectorTile;\n    expires?: any;\n    cacheControl?: any;\n    resourceTiming?: Array<PerformanceResourceTiming>;\n};\n\n/**\n * @callback LoadVectorDataCallback\n * @param error\n * @param vectorTile\n * @private\n */\nexport type LoadVectorDataCallback = Callback<LoadVectorTileResult | null | undefined>;\n\nexport type AbortVectorData = () => void;\nexport type LoadVectorData = (params: RequestedTileParameters, callback: LoadVectorDataCallback) => AbortVectorData | null | undefined;\nexport class DedupedRequest {\n    entries: {\n        [key: string]: any;\n    };\n    scheduler: Scheduler | null | undefined;\n\n    constructor(scheduler?: Scheduler) {\n        this.entries = {};\n        this.scheduler = scheduler;\n    }\n\n    request(key: string, metadata: any, request: any, callback: LoadVectorDataCallback): () => void {\n        const entry = this.entries[key] = this.entries[key] || {callbacks: []};\n\n        if (entry.result) {\n            const [err, result] = entry.result;\n            if (this.scheduler) {\n                this.scheduler.add(() => {\n                    callback(err, result);\n                }, metadata);\n            } else {\n                callback(err, result);\n            }\n            return () => {};\n        }\n\n        entry.callbacks.push(callback);\n\n        if (!entry.cancel) {\n            entry.cancel = request((err, result) => {\n                entry.result = [err, result];\n                for (const cb of entry.callbacks) {\n                    if (this.scheduler) {\n                        this.scheduler.add(() => {\n                            cb(err, result);\n                        }, metadata);\n                    } else {\n                        cb(err, result);\n                    }\n                }\n                setTimeout(() => delete this.entries[key], 1000 * 3);\n            });\n        }\n\n        return () => {\n            if (entry.result) return;\n            entry.callbacks = entry.callbacks.filter(cb => cb !== callback);\n            if (!entry.callbacks.length) {\n                entry.cancel();\n                delete this.entries[key];\n            }\n        };\n    }\n}\n\n/**\n * @private\n */\nexport function loadVectorTile(\n    params: RequestedTileParameters,\n    callback: LoadVectorDataCallback,\n    skipParse?: boolean,\n): () => void {\n    const key = JSON.stringify(params.request);\n\n    const makeRequest = (callback: LoadVectorDataCallback) => {\n        const request = getArrayBuffer(params.request, (err?: Error | null, data?: ArrayBuffer | null, cacheControl?: string | null, expires?: string | null) => {\n            if (err) {\n                callback(err);\n            } else if (data) {\n                callback(null, {\n                    vectorTile: skipParse ? undefined : new VectorTile(new Protobuf(data)),\n                    rawData: data,\n                    cacheControl,\n                    expires\n                });\n            }\n        });\n        return () => {\n            request.cancel();\n            callback();\n        };\n    };\n\n    if (params.data) {\n        // if we already got the result earlier (on the main thread), return it directly\n        (this.deduped as DedupedRequest).entries[key] = {result: [null, params.data]};\n    }\n\n    const callbackMetadata = {type: 'parseTile', isSymbolTile: params.isSymbolTile, zoom: params.tileZoom};\n    return (this.deduped as DedupedRequest).request(key, callbackMetadata, makeRequest, callback);\n}\n","export default ['type', 'source', 'source-layer', 'minzoom', 'maxzoom', 'filter', 'layout'];\n","import {LivePerformanceMarkers} from '../util/live_performance';\n\nexport const PerformanceMarkers = {\n    libraryEvaluate: 'library-evaluate',\n    frameGPU: 'frame-gpu',\n    frame: 'frame'\n} as const;\n\nimport {isWorker} from '../util/util';\nimport type {RequestParameters} from '../util/ajax';\n\nexport type PerformanceMetrics = {\n    loadTime: number;\n    fullLoadTime: number;\n    percentDroppedFrames: number;\n    parseTile: number;\n    parseTile1: number;\n    parseTile2: number;\n    workerTask: number;\n    workerInitialization: number;\n    workerEvaluateScript: number;\n    workerIdle: number;\n    workerIdlePercent: number;\n    placementTime: number;\n    timelines: Array<any>;\n};\n\nexport type PerformanceMark = {\n    mark: string;\n    name: string;\n};\n\ntype PerformanceMarkOptions = {\n    detail?: unknown;\n    startTime?: number;\n};\n\nlet fullLoadFinished = false;\nlet placementTime = 0;\n\nexport const PerformanceUtils = {\n    mark(marker: typeof PerformanceMarkers[keyof typeof PerformanceMarkers], markOptions?: PerformanceMarkOptions) {\n        performance.mark(marker, markOptions);\n\n        // @ts-expect-error - TS2367 - This comparison appears to be unintentional because the types '\"frame\" | \"library-evaluate\" | \"frame-gpu\"' and '\"fullLoad\"' have no overlap.\n        if (marker === LivePerformanceMarkers.fullLoad) {\n            fullLoadFinished = true;\n        }\n    },\n    measure(name: string, begin?: string, end?: string) {\n        performance.measure(name, begin, end);\n    },\n    beginMeasure(name: string): PerformanceMark {\n        const mark = name;\n        performance.mark(mark);\n        return {\n            mark,\n            name\n        };\n    },\n    endMeasure(m: PerformanceMark) {\n        performance.measure(m.name, m.mark);\n    },\n    recordPlacementTime(time: number) {\n        // Ignore placementTimes during loading\n        if (!fullLoadFinished) {\n            return;\n        }\n\n        placementTime += time;\n    },\n    frame(timestamp: number, isRenderFrame: boolean) {\n        performance.mark(PerformanceMarkers.frame, {\n            detail: {\n                timestamp,\n                isRenderFrame\n            }\n        });\n    },\n    clearMetrics() {\n        placementTime = 0;\n        fullLoadFinished = false;\n\n        performance.clearMeasures('loadTime');\n        performance.clearMeasures('fullLoadTime');\n\n        for (const marker in LivePerformanceMarkers) {\n            performance.clearMarks(LivePerformanceMarkers[marker]);\n        }\n    },\n\n    getPerformanceMetrics(): PerformanceMetrics {\n        const metrics: Record<string, any> = {};\n\n        performance.measure('loadTime', LivePerformanceMarkers.create, LivePerformanceMarkers.load);\n        performance.measure('fullLoadTime', LivePerformanceMarkers.create, LivePerformanceMarkers.fullLoad);\n\n        const measures = performance.getEntriesByType('measure');\n        for (const measure of measures) {\n            metrics[measure.name] = (metrics[measure.name] || 0) + measure.duration;\n        }\n\n        metrics.placementTime = placementTime;\n\n        // @ts-expect-error - TS2740 - Type 'Record<string, any>' is missing the following properties from type 'PerformanceMetrics': loadTime, fullLoadTime, percentDroppedFrames, parseTile, and 9 more.\n        return metrics;\n    },\n\n    getWorkerPerformanceMetrics(): {\n        timeOrigin: string;\n        entries: Array<any>;\n        scope: string;\n        } {\n        const entries = performance.getEntries().map(entry => {\n            const result = entry.toJSON();\n            // @ts-expect-error - TS2339 - Property 'detail' does not exist on type 'PerformanceEntry'.\n            if (entry.detail) {\n                Object.assign(result, {\n                    // @ts-expect-error - TS2339 - Property 'detail' does not exist on type 'PerformanceEntry'.\n                    detail: entry.detail\n                });\n            }\n            return result;\n        });\n        return {\n            scope: isWorker() ? 'Worker' : 'Window',\n            // @ts-expect-error - TS2322 - Type 'number' is not assignable to type 'string'.\n            timeOrigin: performance.timeOrigin,\n            entries\n        };\n    }\n} as const;\n\nPerformanceUtils.mark(PerformanceMarkers.libraryEvaluate);\n\nexport function getPerformanceMeasurement(request?: RequestParameters | null): Array<PerformanceEntry> {\n    const url = request ? request.url.toString() : undefined;\n    if (!url) {\n        return [];\n    }\n    return performance.getEntriesByName(url);\n}\n\nexport default performance;\n","import type {LayerSpecification} from './types';\n\nimport refProperties from './util/ref_properties';\n\nfunction stringify(obj: any) {\n    if (typeof obj === 'number' || typeof obj === 'boolean' || typeof obj === 'string' || obj === undefined || obj === null)\n        return JSON.stringify(obj);\n\n    if (Array.isArray(obj)) {\n        let str = '[';\n        for (const val of obj) {\n            str += `${stringify(val)},`;\n        }\n        return `${str}]`;\n    }\n\n    let str = '{';\n    for (const key of Object.keys(obj).sort()) {\n        str += `${key}:${stringify((obj)[key])},`;\n    }\n    return `${str}}`;\n}\n\nfunction getKey(layer: LayerSpecification) {\n    let key = '';\n    for (const k of refProperties) {\n        key += `/${stringify((layer as any)[k])}`;\n    }\n    return key;\n}\n\n/**\n * Given an array of layers, return an array of arrays of layers where all\n * layers in each group have identical layout-affecting properties. These\n * are the properties that were formerly used by explicit `ref` mechanism\n * for layers: 'type', 'source', 'source-layer', 'minzoom', 'maxzoom',\n * 'filter', and 'layout'.\n *\n * The input is not modified. The output layers are references to the\n * input layers.\n *\n * @private\n * @param {Array<Layer>} layers\n * @param {Object} [cachedKeys] - an object to keep already calculated keys.\n * @returns {Array<Array<Layer>>}\n */\nexport default function groupByLayout(\n    layers: Array<LayerSpecification>,\n    cachedKeys: {\n        [id: string]: string;\n    },\n): Array<Array<LayerSpecification>> {\n    const groups: Record<string, any> = {};\n\n    for (let i = 0; i < layers.length; i++) {\n\n        const k = (cachedKeys && cachedKeys[layers[i].id]) || getKey(layers[i]);\n        // update the cache if there is one\n        if (cachedKeys)\n            cachedKeys[layers[i].id] = k;\n\n        let group = groups[k];\n        if (!group) {\n            group = groups[k] = [];\n        }\n        group.push(layers[i]);\n    }\n\n    const result = [];\n\n    for (const k in groups) {\n        result.push(groups[k]);\n    }\n\n    return result;\n}\n","import createStyleLayer from './create_style_layer';\n\nimport {values} from '../util/util';\nimport groupByLayout from '../style-spec/group_by_layout';\n\nimport type {TypedStyleLayer} from './style_layer/typed_style_layer';\nimport type {LayerSpecification} from '../style-spec/types';\nimport type {ConfigOptions} from './properties';\n\nexport type LayerConfigs = {\n    [_: string]: LayerSpecification;\n};\nexport type Family<Layer extends TypedStyleLayer> = Array<Layer>;\n\nclass StyleLayerIndex {\n    scope: string;\n    familiesBySource: {\n        [source: string]: {\n            [sourceLayer: string]: Array<Family<TypedStyleLayer>>;\n        };\n    };\n    keyCache: {\n        [source: string]: string;\n    };\n\n    _layerConfigs: LayerConfigs;\n    _layers: {\n        [_: string]: TypedStyleLayer;\n    };\n    _options: ConfigOptions | null | undefined;\n\n    constructor(layerConfigs?: Array<LayerSpecification> | null) {\n        this.keyCache = {};\n        this._layers = {};\n        this._layerConfigs = {};\n        if (layerConfigs) {\n            this.replace(layerConfigs);\n        }\n    }\n\n    replace(layerConfigs: Array<LayerSpecification>, options?: ConfigOptions | null) {\n        this._layerConfigs = {};\n        this._layers = {};\n        this.update(layerConfigs, [], options);\n    }\n\n    update(layerConfigs: Array<LayerSpecification>, removedIds: Array<string>, options?: ConfigOptions | null) {\n        this._options = options;\n\n        for (const layerConfig of layerConfigs) {\n            this._layerConfigs[layerConfig.id] = layerConfig;\n\n            const layer = this._layers[layerConfig.id] = (createStyleLayer(layerConfig, this.scope, null, this._options) as TypedStyleLayer);\n            layer.compileFilter();\n            if (this.keyCache[layerConfig.id])\n                delete this.keyCache[layerConfig.id];\n        }\n        for (const id of removedIds) {\n            delete this.keyCache[id];\n            delete this._layerConfigs[id];\n            delete this._layers[id];\n        }\n\n        this.familiesBySource = {};\n\n        const groups = groupByLayout(values(this._layerConfigs), this.keyCache);\n\n        for (const layerConfigs of groups) {\n            const layers = layerConfigs.map((layerConfig) => this._layers[layerConfig.id]);\n\n            const layer = layers[0];\n            if (layer.visibility === 'none') {\n                continue;\n            }\n\n            const sourceId = layer.source || '';\n            let sourceGroup = this.familiesBySource[sourceId];\n            if (!sourceGroup) {\n                sourceGroup = this.familiesBySource[sourceId] = {};\n            }\n\n            const sourceLayerId = layer.sourceLayer || '_geojsonTileLayer';\n            let sourceLayerFamilies = sourceGroup[sourceLayerId];\n            if (!sourceLayerFamilies) {\n                sourceLayerFamilies = sourceGroup[sourceLayerId] = [];\n            }\n\n            sourceLayerFamilies.push(layers);\n        }\n    }\n}\n\nexport default StyleLayerIndex;\n","import {SDF_SCALE} from '../render/glyph_manager';\nimport {AlphaImage} from '../util/image';\nimport {register} from '../util/web_worker_transfer';\nimport potpack from 'potpack';\n\nimport type {StyleGlyph} from '../style/style_glyph';\n\nconst glyphPadding = 1;\n/*\n    The glyph padding is just to prevent sampling errors at the boundaries between\n    glyphs in the atlas texture, and for that purpose there's no need to make it\n    bigger with high-res SDFs. However, layout is done based on the glyph size\n    including this padding, so scaling this padding is the easiest way to keep\n    layout exactly the same as the SDF_SCALE changes.\n*/\nconst localGlyphPadding = glyphPadding * SDF_SCALE;\n\nexport type GlyphRect = {\n    x: number;\n    y: number;\n    w: number;\n    h: number;\n};\n// {glyphID: glyphRect}\nexport type GlyphPositionMap = {\n    [_: number]: GlyphRect;\n};\n\n// {fontStack: glyphPoistionMap}\nexport type GlyphPositions = {\n    [_: string]: GlyphPositionMap;\n};\n\nexport default class GlyphAtlas {\n    image: AlphaImage;\n    positions: GlyphPositions;\n    constructor(stacks: {\n        [_: string]: {\n            glyphs: {\n                [_: number]: StyleGlyph | null | undefined;\n            };\n            ascender?: number;\n            descender?: number;\n        };\n    }) {\n        const positions: Record<string, any> = {};\n        const bins = [];\n\n        for (const stack in stacks) {\n            const glyphData = stacks[stack];\n            const glyphPositionMap = positions[stack] = {};\n\n            for (const id in glyphData.glyphs) {\n                const src = glyphData.glyphs[+id];\n                if (!src || src.bitmap.width === 0 || src.bitmap.height === 0) continue;\n\n                const padding = src.metrics.localGlyph ? localGlyphPadding : glyphPadding;\n                const bin = {\n                    x: 0,\n                    y: 0,\n                    w: src.bitmap.width + 2 * padding,\n                    h: src.bitmap.height + 2 * padding\n                };\n                bins.push(bin);\n                glyphPositionMap[id] = bin;\n            }\n        }\n\n        const {w, h} = potpack(bins);\n        const image = new AlphaImage({width: w || 1, height: h || 1});\n\n        for (const stack in stacks) {\n            const glyphData = stacks[stack];\n\n            for (const id in glyphData.glyphs) {\n                const src = glyphData.glyphs[+id];\n                if (!src || src.bitmap.width === 0 || src.bitmap.height === 0) continue;\n                const bin = positions[stack][id];\n                const padding = src.metrics.localGlyph ? localGlyphPadding : glyphPadding;\n                AlphaImage.copy(src.bitmap, image, {x: 0, y: 0}, {x: bin.x + padding, y: bin.y + padding}, src.bitmap);\n            }\n        }\n\n        this.image = image;\n        this.positions = positions;\n    }\n}\n\nregister(GlyphAtlas, 'GlyphAtlas');\n","import FeatureIndex from '../data/feature_index';\n\nimport {performSymbolLayout} from '../symbol/symbol_layout';\nimport {CollisionBoxArray} from '../data/array_types';\nimport DictionaryCoder from '../util/dictionary_coder';\nimport SymbolBucket from '../data/bucket/symbol_bucket';\nimport LineBucket from '../data/bucket/line_bucket';\nimport FillBucket from '../data/bucket/fill_bucket';\nimport FillExtrusionBucket from '../data/bucket/fill_extrusion_bucket';\nimport {warnOnce, mapObject, values} from '../util/util';\nimport assert from 'assert';\nimport LineAtlas from '../render/line_atlas';\nimport ImageAtlas from '../render/image_atlas';\nimport GlyphAtlas from '../render/glyph_atlas';\nimport EvaluationParameters from '../style/evaluation_parameters';\nimport {CanonicalTileID, OverscaledTileID} from './tile_id';\nimport {PerformanceUtils} from '../util/performance';\nimport tileTransform from '../geo/projection/tile_transform';\nimport type Projection from '../geo/projection/projection';\nimport type {Bucket} from '../data/bucket';\nimport type Actor from '../util/actor';\nimport type StyleLayer from '../style/style_layer';\nimport type StyleLayerIndex from '../style/style_layer_index';\nimport type {StyleImage} from '../style/style_image';\nimport type {StyleGlyph} from '../style/style_glyph';\nimport type {SpritePositions} from '../util/image';\nimport type {\n    WorkerTileParameters,\n    WorkerTileCallback,\n} from '../source/worker_source';\nimport type {PromoteIdSpecification} from '../style-spec/types';\nimport type {TileTransform} from '../geo/projection/tile_transform';\nimport type {VectorTile} from '@mapbox/vector-tile';\nimport type {LUT} from \"../util/lut\";\n\nclass WorkerTile {\n    tileID: OverscaledTileID;\n    uid: number;\n    zoom: number;\n    lut: LUT | null;\n    tileZoom: number;\n    canonical: CanonicalTileID;\n    pixelRatio: number;\n    tileSize: number;\n    source: string;\n    scope: string;\n    promoteId: PromoteIdSpecification | null | undefined;\n    overscaling: number;\n    showCollisionBoxes: boolean;\n    collectResourceTiming: boolean;\n    isSymbolTile: boolean | null | undefined;\n    extraShadowCaster: boolean | null | undefined;\n    tessellationStep: number | null | undefined;\n    projection: Projection;\n    tileTransform: TileTransform;\n    brightness: number;\n\n    status: 'parsing' | 'done';\n    data: VectorTile;\n    collisionBoxArray: CollisionBoxArray;\n\n    abort: () => void | null | undefined;\n    reloadCallback: WorkerTileCallback | null | undefined;\n    vectorTile: VectorTile;\n\n    constructor(params: WorkerTileParameters) {\n        this.tileID = new OverscaledTileID(params.tileID.overscaledZ, params.tileID.wrap, params.tileID.canonical.z, params.tileID.canonical.x, params.tileID.canonical.y);\n        this.tileZoom = params.tileZoom;\n        this.uid = params.uid;\n        this.zoom = params.zoom;\n        this.lut = params.lut;\n        this.canonical = params.tileID.canonical;\n        this.pixelRatio = params.pixelRatio;\n        this.tileSize = params.tileSize;\n        this.source = params.source;\n        this.scope = params.scope;\n        this.overscaling = this.tileID.overscaleFactor();\n        this.showCollisionBoxes = params.showCollisionBoxes;\n        this.collectResourceTiming = !!params.collectResourceTiming;\n        this.promoteId = params.promoteId;\n        this.isSymbolTile = params.isSymbolTile;\n        this.tileTransform = tileTransform(params.tileID.canonical, params.projection);\n        this.projection = params.projection;\n        this.brightness = params.brightness;\n        this.extraShadowCaster = !!params.extraShadowCaster;\n        this.tessellationStep = params.tessellationStep;\n    }\n\n    parse(data: VectorTile, layerIndex: StyleLayerIndex, availableImages: Array<string>, actor: Actor, callback: WorkerTileCallback) {\n        const m = PerformanceUtils.beginMeasure('parseTile1');\n        this.status = 'parsing';\n        this.data = data;\n\n        this.collisionBoxArray = new CollisionBoxArray();\n        const sourceLayerCoder = new DictionaryCoder(Object.keys(data.layers).sort());\n\n        const featureIndex = new FeatureIndex(this.tileID, this.promoteId);\n        featureIndex.bucketLayerIDs = [];\n\n        const buckets: {\n            [_: string]: Bucket;\n        } = {};\n\n        // we initially reserve space for a 256x256 atlas, but trim it after processing all line features\n        const lineAtlas = new LineAtlas(256, 256);\n\n        const options = {\n            featureIndex,\n            iconDependencies: {},\n            patternDependencies: {},\n            glyphDependencies: {},\n            lineAtlas,\n            availableImages,\n            brightness: this.brightness\n        };\n\n        const layerFamilies = layerIndex.familiesBySource[this.source];\n        for (const sourceLayerId in layerFamilies) {\n            const sourceLayer = data.layers[sourceLayerId];\n            if (!sourceLayer) {\n                continue;\n            }\n\n            let anySymbolLayers = false;\n            let anyOtherLayers = false;\n            let any3DLayer = false;\n\n            for (const family of layerFamilies[sourceLayerId]) {\n                if (family[0].type === 'symbol') {\n                    anySymbolLayers = true;\n                } else {\n                    anyOtherLayers = true;\n                }\n                if (family[0].is3D() && family[0].type !== 'model') {\n                    any3DLayer = true;\n                }\n            }\n\n            if (this.extraShadowCaster && !any3DLayer) {\n                continue;\n            }\n\n            if (this.isSymbolTile === true && !anySymbolLayers) {\n                continue;\n            } else if (this.isSymbolTile === false && !anyOtherLayers) {\n                continue;\n            }\n\n            if (sourceLayer.version === 1) {\n                warnOnce(`Vector tile source \"${this.source}\" layer \"${sourceLayerId}\" ` +\n                    `does not use vector tile spec v2 and therefore may have some rendering errors.`);\n            }\n\n            const sourceLayerIndex = sourceLayerCoder.encode(sourceLayerId);\n            const features = [];\n            for (let index = 0; index < sourceLayer.length; index++) {\n                const feature = sourceLayer.feature(index);\n                const id = featureIndex.getId(feature, sourceLayerId);\n                features.push({feature, id, index, sourceLayerIndex});\n            }\n\n            for (const family of layerFamilies[sourceLayerId]) {\n                const layer = family[0];\n\n                if (this.extraShadowCaster && (!layer.is3D() || layer.type === 'model')) {\n                    // avoid to spend resources in 2D layers or 3D model layers (trees) for extra shadow casters\n                    continue;\n                }\n                if (this.isSymbolTile !== undefined && (layer.type === 'symbol') !== this.isSymbolTile) continue;\n                assert(layer.source === this.source);\n                if (layer.minzoom && this.zoom < Math.floor(layer.minzoom)) continue;\n                if (layer.maxzoom && this.zoom >= layer.maxzoom) continue;\n                if (layer.visibility === 'none') continue;\n\n                recalculateLayers(family, this.zoom, options.brightness, availableImages);\n\n                const bucket = buckets[layer.id] = layer.createBucket({\n                    index: featureIndex.bucketLayerIDs.length,\n                    // @ts-expect-error - TS2322 - Type 'Family<TypedStyleLayer>' is not assignable to type 'ClipStyleLayer[] & ModelStyleLayer[] & SymbolStyleLayer[] & LineStyleLayer[] & HeatmapStyleLayer[] & FillExtrusionStyleLayer[] & FillStyleLayer[] & CircleStyleLayer[]'.\n                    layers: family,\n                    zoom: this.zoom,\n                    lut: this.lut,\n                    canonical: this.canonical,\n                    pixelRatio: this.pixelRatio,\n                    overscaling: this.overscaling,\n                    collisionBoxArray: this.collisionBoxArray,\n                    sourceLayerIndex,\n                    sourceID: this.source,\n                    projection: this.projection.spec,\n                    tessellationStep: this.tessellationStep\n                });\n\n                assert(this.tileTransform.projection.name === this.projection.name);\n                bucket.populate(features, options, this.tileID.canonical, this.tileTransform);\n                featureIndex.bucketLayerIDs.push(family.map((l) => l.id));\n            }\n        }\n\n        lineAtlas.trim();\n\n        let error: Error | null | undefined;\n        let glyphMap: {\n            [_: string]: {\n                glyphs: {\n                    [_: number]: StyleGlyph | null | undefined;\n                };\n                ascender?: number;\n                descender?: number;\n            };\n        };\n        let iconMap: {\n            [_: string]: StyleImage;\n        };\n        let patternMap: {\n            [_: string]: StyleImage;\n        };\n        const taskMetadata = {type: 'maybePrepare', isSymbolTile: this.isSymbolTile, zoom: this.zoom};\n\n        const maybePrepare = () => {\n            if (error) {\n                this.status = 'done';\n                return callback(error);\n            } else if (this.extraShadowCaster) {\n                const m = PerformanceUtils.beginMeasure('parseTile2');\n                this.status = 'done';\n                callback(null, {\n                    buckets: values(buckets).filter(b => !b.isEmpty()),\n                    featureIndex,\n                    collisionBoxArray: null,\n                    glyphAtlasImage: null,\n                    lineAtlas: null,\n                    imageAtlas: null,\n                    brightness: options.brightness,\n                    // Only used for benchmarking:\n                    glyphMap: null,\n                    iconMap: null,\n                    glyphPositions: null\n                });\n                PerformanceUtils.endMeasure(m);\n            } else if (glyphMap && iconMap && patternMap) {\n                const m = PerformanceUtils.beginMeasure('parseTile2');\n                const glyphAtlas = new GlyphAtlas(glyphMap);\n                const imageAtlas = new ImageAtlas(iconMap, patternMap, this.lut);\n\n                for (const key in buckets) {\n                    const bucket = buckets[key];\n                    if (bucket instanceof SymbolBucket) {\n                        recalculateLayers(bucket.layers, this.zoom, options.brightness, availableImages);\n                        performSymbolLayout(bucket,\n                                glyphMap,\n                                glyphAtlas.positions,\n                                iconMap,\n                                imageAtlas.iconPositions,\n                                this.showCollisionBoxes,\n                                availableImages,\n                                this.tileID.canonical,\n                                this.tileZoom,\n                                this.projection,\n                                this.brightness);\n                    } else if (bucket.hasPattern &&\n                            (bucket instanceof LineBucket ||\n                             bucket instanceof FillBucket ||\n                             bucket instanceof FillExtrusionBucket)) {\n                        recalculateLayers(bucket.layers, this.zoom, options.brightness, availableImages);\n                        const imagePositions: SpritePositions = imageAtlas.patternPositions;\n                        bucket.addFeatures(options, this.tileID.canonical, imagePositions, availableImages, this.tileTransform, this.brightness);\n                    }\n                }\n                this.status = 'done';\n                callback(null, {\n                    buckets: values(buckets).filter(b => !b.isEmpty()),\n                    featureIndex,\n                    collisionBoxArray: this.collisionBoxArray,\n                    glyphAtlasImage: glyphAtlas.image,\n                    lineAtlas,\n                    imageAtlas,\n                    brightness: options.brightness\n                });\n                PerformanceUtils.endMeasure(m);\n            }\n        };\n\n        if (!this.extraShadowCaster) {\n            const stacks = mapObject(options.glyphDependencies, (glyphs) => Object.keys(glyphs).map(Number));\n            if (Object.keys(stacks).length) {\n                actor.send('getGlyphs', {uid: this.uid, stacks, scope: this.scope}, (err, result) => {\n                    if (!error) {\n                        error = err;\n                        glyphMap = result;\n                        maybePrepare();\n                    }\n                }, undefined, false, taskMetadata);\n            } else {\n                glyphMap = {};\n            }\n\n            const icons = Object.keys(options.iconDependencies);\n            if (icons.length) {\n                actor.send('getImages', {icons, source: this.source, scope: this.scope, tileID: this.tileID, type: 'icons'}, (err, result) => {\n                    if (!error) {\n                        error = err;\n                        iconMap = result;\n                        maybePrepare();\n                    }\n                }, undefined, false, taskMetadata);\n            } else {\n                iconMap = {};\n            }\n\n            const patterns = Object.keys(options.patternDependencies);\n            if (patterns.length) {\n                actor.send('getImages', {icons: patterns, source: this.source, scope: this.scope, tileID: this.tileID, type: 'patterns'}, (err, result) => {\n                    if (!error) {\n                        error = err;\n                        patternMap = result;\n                        maybePrepare();\n                    }\n                }, undefined, false, taskMetadata);\n            } else {\n                patternMap = {};\n            }\n        }\n\n        PerformanceUtils.endMeasure(m);\n\n        maybePrepare();\n\n    }\n}\n\nfunction recalculateLayers(layers: ReadonlyArray<StyleLayer>, zoom: number, brightness: number, availableImages: Array<string>) {\n    // Layers are shared and may have been used by a WorkerTile with a different zoom.\n    const parameters = new EvaluationParameters(zoom, {brightness});\n    for (const layer of layers) {\n        layer.recalculate(parameters, availableImages);\n    }\n}\n\nexport default WorkerTile;\n","import {VectorTile} from '@mapbox/vector-tile';\nimport Protobuf from 'pbf';\nimport WorkerTile from './worker_tile';\nimport {extend} from '../util/util';\nimport {getPerformanceMeasurement} from '../util/performance';\nimport {Evented} from '../util/evented';\nimport tileTransform from '../geo/projection/tile_transform';\nimport {loadVectorTile, DedupedRequest} from './load_vector_tile';\n\nimport type {\n    WorkerSource,\n    WorkerTileResult,\n    WorkerTileParameters,\n    WorkerTileCallback,\n    TileParameters\n} from './worker_source';\n\nimport type Actor from '../util/actor';\nimport type StyleLayerIndex from '../style/style_layer_index';\nimport type Scheduler from '../util/scheduler';\nimport type {LoadVectorData} from './load_vector_tile';\n\n/**\n * The {@link WorkerSource} implementation that supports {@link VectorTileSource}.\n * This class is designed to be easily reused to support custom source types\n * for data formats that can be parsed/converted into an in-memory VectorTile\n * representation.  To do so, create it with\n * `new VectorTileWorkerSource(actor, styleLayers, customLoadVectorDataFunction)`.\n *\n * @private\n */\nclass VectorTileWorkerSource extends Evented implements WorkerSource {\n    actor: Actor;\n    layerIndex: StyleLayerIndex;\n    availableImages: Array<string>;\n    loadVectorData: LoadVectorData;\n    loading: {\n        [_: number]: WorkerTile;\n    };\n    loaded: {\n        [_: number]: WorkerTile;\n    };\n    deduped: DedupedRequest;\n    isSpriteLoaded: boolean;\n    scheduler: Scheduler | null | undefined;\n    brightness: number | null | undefined;\n\n    /**\n     * @param [loadVectorData] Optional method for custom loading of a VectorTile\n     * object based on parameters passed from the main-thread Source. See\n     * {@link VectorTileWorkerSource#loadTile}. The default implementation simply\n     * loads the pbf at `params.url`.\n     * @private\n     */\n    constructor(actor: Actor, layerIndex: StyleLayerIndex, availableImages: Array<string>, isSpriteLoaded: boolean, loadVectorData?: LoadVectorData | null, brightness?: number | null) {\n        super();\n        this.actor = actor;\n        this.layerIndex = layerIndex;\n        this.availableImages = availableImages;\n        this.loadVectorData = loadVectorData || loadVectorTile;\n        this.loading = {};\n        this.loaded = {};\n        this.deduped = new DedupedRequest(actor.scheduler);\n        this.isSpriteLoaded = isSpriteLoaded;\n        this.scheduler = actor.scheduler;\n        this.brightness = brightness;\n    }\n\n    /**\n     * Implements {@link WorkerSource#loadTile}. Delegates to\n     * {@link VectorTileWorkerSource#loadVectorData} (which by default expects\n     * a `params.url` property) for fetching and producing a VectorTile object.\n     * @private\n     */\n    loadTile(params: WorkerTileParameters, callback: WorkerTileCallback) {\n        const uid = params.uid;\n\n        const requestParam = params && params.request;\n        const perf = requestParam && requestParam.collectResourceTiming;\n\n        const workerTile = this.loading[uid] = new WorkerTile(params);\n        workerTile.abort = this.loadVectorData(params, (err, response) => {\n\n            const aborted = !this.loading[uid];\n\n            delete this.loading[uid];\n\n            if (aborted || err || !response) {\n                workerTile.status = 'done';\n                if (!aborted) this.loaded[uid] = workerTile;\n                return callback(err);\n            }\n\n            const rawTileData = response.rawData;\n            const cacheControl: Record<string, any> = {};\n            if (response.expires) cacheControl.expires = response.expires;\n            if (response.cacheControl) cacheControl.cacheControl = response.cacheControl;\n\n            // response.vectorTile will be present in the GeoJSON worker case (which inherits from this class)\n            // because we stub the vector tile interface around JSON data instead of parsing it directly\n            workerTile.vectorTile = response.vectorTile || new VectorTile(new Protobuf(rawTileData));\n            const parseTile = () => {\n                const workerTileCallback = (err?: Error | null, result?: WorkerTileResult | null) => {\n                    if (err || !result) return callback(err);\n\n                    const resourceTiming: Record<string, any> = {};\n                    if (perf) {\n                        // Transferring a copy of rawTileData because the worker needs to retain its copy.\n                        const resourceTimingData = getPerformanceMeasurement(requestParam);\n                        // it's necessary to eval the result of getEntriesByName() here via parse/stringify\n                        // late evaluation in the main thread causes TypeError: illegal invocation\n                        if (resourceTimingData.length > 0) {\n                            resourceTiming.resourceTiming = JSON.parse(JSON.stringify(resourceTimingData));\n                        }\n                    }\n                    callback(null, extend({rawTileData: rawTileData.slice(0)}, result, cacheControl, resourceTiming));\n                };\n                workerTile.parse(workerTile.vectorTile, this.layerIndex, this.availableImages, this.actor, workerTileCallback);\n            };\n\n            if (this.isSpriteLoaded) {\n                parseTile();\n            } else {\n                this.once('isSpriteLoaded', () => {\n                    if (this.scheduler) {\n                        const metadata = {type: 'parseTile', isSymbolTile: params.isSymbolTile, zoom: params.tileZoom};\n                        // @ts-expect-error - TS2345 - Argument of type '{ type: string; isSymbolTile: boolean; zoom: number; }' is not assignable to parameter of type 'TaskMetadata'.\n                        this.scheduler.add(parseTile, metadata);\n                    } else {\n                        parseTile();\n                    }\n                });\n            }\n\n            this.loaded = this.loaded || {};\n            this.loaded[uid] = workerTile;\n        });\n    }\n\n    /**\n     * Implements {@link WorkerSource#reloadTile}.\n     * @private\n     */\n    reloadTile(params: WorkerTileParameters, callback: WorkerTileCallback) {\n        const loaded = this.loaded,\n            uid = params.uid;\n\n        if (loaded && loaded[uid]) {\n            const workerTile = loaded[uid];\n            workerTile.showCollisionBoxes = params.showCollisionBoxes;\n            workerTile.projection = params.projection;\n            workerTile.brightness = params.brightness;\n            workerTile.tileTransform = tileTransform(params.tileID.canonical, params.projection);\n            workerTile.extraShadowCaster = params.extraShadowCaster;\n            workerTile.lut = params.lut;\n            const done = (err?: Error | null, data?: WorkerTileResult | null) => {\n                const reloadCallback = workerTile.reloadCallback;\n                if (reloadCallback) {\n                    delete workerTile.reloadCallback;\n                    workerTile.parse(workerTile.vectorTile, this.layerIndex, this.availableImages, this.actor, reloadCallback);\n                }\n                callback(err, data);\n            };\n\n            if (workerTile.status === 'parsing') {\n                workerTile.reloadCallback = done;\n            } else if (workerTile.status === 'done') {\n                // if there was no vector tile data on the initial load, don't try and re-parse tile\n                if (workerTile.vectorTile) {\n                    workerTile.parse(workerTile.vectorTile, this.layerIndex, this.availableImages, this.actor, done);\n                } else {\n                    done();\n                }\n            }\n        } else {\n            callback(null, undefined);\n        }\n    }\n\n    /**\n     * Implements {@link WorkerSource#abortTile}.\n     *\n     * @param params\n     * @param params.uid The UID for this tile.\n     * @private\n     */\n    abortTile(params: TileParameters, callback: WorkerTileCallback) {\n        const uid = params.uid;\n        const tile = this.loading[uid];\n        if (tile) {\n            if (tile.abort) tile.abort();\n            delete this.loading[uid];\n        }\n        callback();\n    }\n\n    /**\n     * Implements {@link WorkerSource#removeTile}.\n     *\n     * @param params\n     * @param params.uid The UID for this tile.\n     * @private\n     */\n    removeTile(params: TileParameters, callback: WorkerTileCallback) {\n        const loaded = this.loaded,\n            uid = params.uid;\n        if (loaded && loaded[uid]) {\n            delete loaded[uid];\n        }\n        callback();\n    }\n}\n\nexport default VectorTileWorkerSource;\n","import DEMData from '../data/dem_data';\n\nimport type Actor from '../util/actor';\nimport type {WorkerDEMTileParameters, WorkerDEMTileCallback} from './worker_source';\n\nclass RasterDEMTileWorkerSource {\n    actor: Actor;\n    offscreenCanvas: OffscreenCanvas;\n    offscreenCanvasContext: CanvasRenderingContext2D;\n\n    loadTile(params: WorkerDEMTileParameters, callback: WorkerDEMTileCallback) {\n        const {uid, encoding, rawImageData, padding} = params;\n        // Main thread will transfer ImageBitmap if offscreen decode with OffscreenCanvas is supported, else it will transfer an already decoded image.\n        // Flow struggles to refine ImageBitmap type\n        const imagePixels = ImageBitmap && rawImageData instanceof ImageBitmap ? this.getImageData(rawImageData, padding) : (rawImageData as ImageData);\n        const dem = new DEMData(uid, imagePixels, encoding, padding < 1);\n        callback(null, dem);\n    }\n\n    getImageData(imgBitmap: ImageBitmap, padding: number): ImageData {\n        // Lazily initialize OffscreenCanvas\n        if (!this.offscreenCanvas || !this.offscreenCanvasContext) {\n            // Dem tiles are typically 256x256\n            this.offscreenCanvas = new OffscreenCanvas(imgBitmap.width, imgBitmap.height);\n            // @ts-expect-error - TS2739 - Type 'OffscreenCanvasRenderingContext2D' is missing the following properties from type 'CanvasRenderingContext2D': getContextAttributes, drawFocusIfNeeded\n            this.offscreenCanvasContext = this.offscreenCanvas.getContext('2d', {willReadFrequently: true});\n        }\n\n        this.offscreenCanvas.width = imgBitmap.width;\n        this.offscreenCanvas.height = imgBitmap.height;\n\n        this.offscreenCanvasContext.drawImage(imgBitmap, 0, 0, imgBitmap.width, imgBitmap.height);\n        // Insert or remove defined padding around the image to allow backfilling for neighboring data.\n        const imgData = this.offscreenCanvasContext.getImageData(-padding, -padding, imgBitmap.width + 2 * padding, imgBitmap.height + 2 * padding);\n        this.offscreenCanvasContext.clearRect(0, 0, this.offscreenCanvas.width, this.offscreenCanvas.height);\n        return imgData;\n    }\n}\n\nexport default RasterDEMTileWorkerSource;\n","import '../data/mrt_data';\nimport {MapboxRasterTile} from '../data/mrt/mrt.esm.js';\nimport Pbf from 'pbf';\n\nMapboxRasterTile.setPbf(Pbf);\n\nimport type Actor from '../util/actor';\nimport type {WorkerRasterArrayTileParameters, WorkerRasterArrayTileCallback} from './worker_source';\n\nclass RasterArrayTileWorkerSource {\n    actor: Actor;\n\n    decodeRasterArray({\n        task,\n        buffer,\n    }: WorkerRasterArrayTileParameters, callback: WorkerRasterArrayTileCallback) {\n        MapboxRasterTile.performDecoding(buffer, task)\n            .then(result => {\n                callback(null, result);\n            }, error => {\n                callback(error);\n            });\n    }\n}\n\nexport default RasterArrayTileWorkerSource;\n","import Point from '@mapbox/point-geometry';\n\nimport {VectorTileFeature} from '@mapbox/vector-tile';\nconst toGeoJSON = VectorTileFeature.prototype.toGeoJSON;\nimport EXTENT from '../style-spec/data/extent';\n\nimport type {VectorTile, VectorTileLayer} from '@mapbox/vector-tile';\n\n// The feature type used by geojson-vt and supercluster. Should be extracted to\n// global type and used in module definitions for those two modules.\nexport type Feature = {\n    type: 1;\n    id: unknown;\n    tags: {\n        [_: string]: string | number | boolean;\n    };\n    geometry: Array<[number, number]>;\n} | {\n    type: 2 | 3;\n    id: unknown;\n    tags: {\n        [_: string]: string | number | boolean;\n    };\n    geometry: Array<Array<[number, number]>>;\n};\n\nclass FeatureWrapper implements VectorTileFeature {\n    _feature: Feature;\n\n    extent: number;\n    type: 1 | 2 | 3;\n    id: number;\n    properties: {\n        [_: string]: string | number | boolean;\n    };\n\n    constructor(feature: Feature) {\n        this._feature = feature;\n\n        this.extent = EXTENT;\n        this.type = feature.type;\n        this.properties = feature.tags;\n\n        // If the feature has a top-level `id` property, copy it over, but only\n        // if it can be coerced to an integer, because this wrapper is used for\n        // serializing geojson feature data into vector tile PBF data, and the\n        // vector tile spec only supports integer values for feature ids --\n        // allowing non-integer values here results in a non-compliant PBF\n        // that causes an exception when it is parsed with vector-tile-js\n        // @ts-expect-error - TS2345 - Argument of type 'unknown' is not assignable to parameter of type 'number'.\n        if ('id' in feature && !isNaN(feature.id)) {\n            // @ts-expect-error - TS2345 - Argument of type 'unknown' is not assignable to parameter of type 'string'.\n            this.id = parseInt(feature.id, 10);\n        }\n    }\n\n    loadGeometry(): Array<Array<Point>> {\n        if (this._feature.type === 1) {\n            const geometry = [];\n            for (const point of this._feature.geometry) {\n                geometry.push([new Point(point[0], point[1])]);\n            }\n            return geometry;\n        } else {\n            const geometry = [];\n            for (const ring of this._feature.geometry) {\n                const newRing = [];\n                for (const point of ring) {\n                    newRing.push(new Point(point[0], point[1]));\n                }\n                geometry.push(newRing);\n            }\n            return geometry;\n        }\n    }\n\n    toGeoJSON(x: number, y: number, z: number): GeoJSON.Feature {\n        return toGeoJSON.call(this, x, y, z);\n    }\n}\n\nclass GeoJSONWrapper implements VectorTile, VectorTileLayer {\n    layers: {\n        [_: string]: VectorTileLayer;\n    };\n    name: string;\n    extent: number;\n    length: number;\n    _features: Array<Feature>;\n\n    constructor(features: Array<Feature>) {\n        this.layers = {'_geojsonTileLayer': this};\n        this.name = '_geojsonTileLayer';\n        this.extent = EXTENT;\n        this.length = features.length;\n        this._features = features;\n    }\n\n    feature(i: number): VectorTileFeature {\n        return new FeatureWrapper(this._features[i]);\n    }\n}\n\nexport default GeoJSONWrapper;\n","\nimport EXTENT from '../style-spec/data/extent';\nimport {mercatorXfromLng, mercatorYfromLat} from '../geo/mercator_coordinate';\n\nimport type WorkerTile from './worker_tile';\nimport type {Feature} from './geojson_wrapper';\n\ntype BBox = {\n    minX: number,\n    minY: number,\n    maxX: number,\n    maxY: number\n}\n\ntype InternalFeature = BBox & {\n    id: string | number,\n    tags: {[_: string]: string | number | boolean},\n    type: 1 | 2 | 3,\n    geometry: number[] | number[][]\n};\n\nconst PAD = 64 / 4096; // geojson-vt default tile buffer\nconst PAD_PX = 128; // the same buffer relative to EXTENT\n\n/*\n * A GeoJSON index tailored to \"small data, updated frequently\" use cases\n * which gets used with GeoJSON sources in `dynamic` mode\n */\nexport default class GeoJSONRT {\n    features: Map<number | string, InternalFeature>;\n\n    constructor() {\n        this.features = new Map();\n    }\n\n    clear() {\n        this.features.clear();\n    }\n\n    load(features: GeoJSON.Feature[] = [], cache: {[_: number]: WorkerTile}) {\n        for (const feature of features) {\n            const id = feature.id;\n            if (id == null) continue;\n\n            let updated = this.features.get(id);\n\n            // update tile cache for the old position\n            if (updated) this.updateCache(updated, cache);\n\n            if (!feature.geometry) {\n                this.features.delete(id);\n            } else {\n                updated = convertFeature(feature);\n                // update tile cache for the new position\n                this.updateCache(updated, cache);\n                this.features.set(id, updated);\n            }\n\n            this.updateCache(updated, cache);\n        }\n    }\n\n    // clear all tiles that contain a given feature from the tile cache\n    updateCache(feature: InternalFeature, cache: {[_: number]: WorkerTile}) {\n        for (const {canonical, uid} of Object.values(cache)) {\n            const {z, x, y} = canonical;\n            const z2 = Math.pow(2, z);\n\n            if (intersectsTile(feature, z2, x, y)) {\n              