1, bottom),\n                tree.data, z2, y, z2, tile);\n        }\n        if (x === z2 - 1) {\n            this._addTileFeatures(\n                tree.range(0, top, p / z2, bottom),\n                tree.data, -1, y, z2, tile);\n        }\n\n        return tile.features.length ? tile : null;\n    }\n\n    getClusterExpansionZoom(clusterId) {\n        let expansionZoom = this._getOriginZoom(clusterId) - 1;\n        while (expansionZoom <= this.options.maxZoom) {\n            const children = this.getChildren(clusterId);\n            expansionZoom++;\n            if (children.length !== 1) break;\n            clusterId = children[0].properties.cluster_id;\n        }\n        return expansionZoom;\n    }\n\n    _appendLeaves(result, clusterId, limit, offset, skipped) {\n        const children = this.getChildren(clusterId);\n\n        for (const child of children) {\n            const props = child.properties;\n\n            if (props && props.cluster) {\n                if (skipped + props.point_count <= offset) {\n                    // skip the whole cluster\n                    skipped += props.point_count;\n                } else {\n                    // enter the cluster\n                    skipped = this._appendLeaves(result, props.cluster_id, limit, offset, skipped);\n                    // exit the cluster\n                }\n            } else if (skipped < offset) {\n                // skip a single point\n                skipped++;\n            } else {\n                // add a single point\n                result.push(child);\n            }\n            if (result.length === limit) break;\n        }\n\n        return skipped;\n    }\n\n    _createTree(data) {\n        const tree = new KDBush(data.length / this.stride | 0, this.options.nodeSize, Float32Array);\n        for (let i = 0; i < data.length; i += this.stride) tree.add(data[i], data[i + 1]);\n        tree.finish();\n        tree.data = data;\n        return tree;\n    }\n\n    _addTileFeatures(ids, data, x, y, z2, tile) {\n        for (const i of ids) {\n            const k = i * this.stride;\n            const isCluster = data[k + OFFSET_NUM] > 1;\n\n            let tags, px, py;\n            if (isCluster) {\n                tags = getClusterProperties(data, k, this.clusterProps);\n                px = data[k];\n                py = data[k + 1];\n            } else {\n                const p = this.points[data[k + OFFSET_ID]];\n                tags = p.properties;\n                const [lng, lat] = p.geometry.coordinates;\n                px = lngX(lng);\n                py = latY(lat);\n            }\n\n            const f = {\n                type: 1,\n                geometry: [[\n                    Math.round(this.options.extent * (px * z2 - x)),\n                    Math.round(this.options.extent * (py * z2 - y))\n                ]],\n                tags\n            };\n\n            // assign id\n            let id;\n            if (isCluster || this.options.generateId) {\n                // optionally generate id for points\n                id = data[k + OFFSET_ID];\n            } else {\n                // keep id if already assigned\n                id = this.points[data[k + OFFSET_ID]].id;\n            }\n\n            if (id !== undefined) f.id = id;\n\n            tile.features.push(f);\n        }\n    }\n\n    _limitZoom(z) {\n        return Math.max(this.options.minZoom, Math.min(Math.floor(+z), this.options.maxZoom + 1));\n    }\n\n    _cluster(tree, zoom) {\n        const {radius, extent, reduce, minPoints} = this.options;\n        const r = radius / (extent * Math.pow(2, zoom));\n        const data = tree.data;\n        const nextData = [];\n        const stride = this.stride;\n\n        // loop through each point\n        for (let i = 0; i < data.length; i += stride) {\n            // if we've already visited the point at this zoom level, skip it\n            if (data[i + OFFSET_ZOOM] <= zoom) continue;\n            data[i + OFFSET_ZOOM] = zoom;\n\n            // find all nearby points\n            const x = data[i];\n            const y = data[i + 1];\n            const neighborIds = tree.within(data[i], data[i + 1], r);\n\n            const numPointsOrigin = data[i + OFFSET_NUM];\n            let numPoints = numPointsOrigin;\n\n            // count the number of points in a potential cluster\n            for (const neighborId of neighborIds) {\n                const k = neighborId * stride;\n                // filter out neighbors that are already processed\n                if (data[k + OFFSET_ZOOM] > zoom) numPoints += data[k + OFFSET_NUM];\n            }\n\n            // if there were neighbors to merge, and there are enough points to form a cluster\n            if (numPoints > numPointsOrigin && numPoints >= minPoints) {\n                let wx = x * numPointsOrigin;\n                let wy = y * numPointsOrigin;\n\n                let clusterProperties;\n                let clusterPropIndex = -1;\n\n                // encode both zoom and point index on which the cluster originated -- offset by total length of features\n                const id = ((i / stride | 0) << 5) + (zoom + 1) + this.points.length;\n\n                for (const neighborId of neighborIds) {\n                    const k = neighborId * stride;\n\n                    if (data[k + OFFSET_ZOOM] <= zoom) continue;\n                    data[k + OFFSET_ZOOM] = zoom; // save the zoom (so it doesn't get processed twice)\n\n                    const numPoints2 = data[k + OFFSET_NUM];\n                    wx += data[k] * numPoints2; // accumulate coordinates for calculating weighted center\n                    wy += data[k + 1] * numPoints2;\n\n                    data[k + OFFSET_PARENT] = id;\n\n                    if (reduce) {\n                        if (!clusterProperties) {\n                            clusterProperties = this._map(data, i, true);\n                            clusterPropIndex = this.clusterProps.length;\n                            this.clusterProps.push(clusterProperties);\n                        }\n                        reduce(clusterProperties, this._map(data, k));\n                    }\n                }\n\n                data[i + OFFSET_PARENT] = id;\n                nextData.push(wx / numPoints, wy / numPoints, Infinity, id, -1, numPoints);\n                if (reduce) nextData.push(clusterPropIndex);\n\n            } else { // left points as unclustered\n                for (let j = 0; j < stride; j++) nextData.push(data[i + j]);\n\n                if (numPoints > 1) {\n                    for (const neighborId of neighborIds) {\n                        const k = neighborId * stride;\n                        if (data[k + OFFSET_ZOOM] <= zoom) continue;\n                        data[k + OFFSET_ZOOM] = zoom;\n                        for (let j = 0; j < stride; j++) nextData.push(data[k + j]);\n                    }\n                }\n            }\n        }\n\n        return nextData;\n    }\n\n    // get index of the point from which the cluster originated\n    _getOriginId(clusterId) {\n        return (clusterId - this.points.length) >> 5;\n    }\n\n    // get zoom of the point from which the cluster originated\n    _getOriginZoom(clusterId) {\n        return (clusterId - this.points.length) % 32;\n    }\n\n    _map(data, i, clone) {\n        if (data[i + OFFSET_NUM] > 1) {\n            const props = this.clusterProps[data[i + OFFSET_PROP]];\n            return clone ? Object.assign({}, props) : props;\n        }\n        const original = this.points[data[i + OFFSET_ID]].properties;\n        const result = this.options.map(original);\n        return clone && result === original ? Object.assign({}, result) : result;\n    }\n}\n\nfunction getClusterJSON(data, i, clusterProps) {\n    return {\n        type: 'Feature',\n        id: data[i + OFFSET_ID],\n        properties: getClusterProperties(data, i, clusterProps),\n        geometry: {\n            type: 'Point',\n            coordinates: [xLng(data[i]), yLat(data[i + 1])]\n        }\n    };\n}\n\nfunction getClusterProperties(data, i, clusterProps) {\n    const count = data[i + OFFSET_NUM];\n    const abbrev =\n        count >= 10000 ? `${Math.round(count / 1000)  }k` :\n        count >= 1000 ? `${Math.round(count / 100) / 10  }k` : count;\n    const propIndex = data[i + OFFSET_PROP];\n    const properties = propIndex === -1 ? {} : Object.assign({}, clusterProps[propIndex]);\n    return Object.assign(properties, {\n        cluster: true,\n        cluster_id: data[i + OFFSET_ID],\n        point_count: count,\n        point_count_abbreviated: abbrev\n    });\n}\n\n// longitude/latitude to spherical mercator in [0..1] range\nfunction lngX(lng) {\n    return lng / 360 + 0.5;\n}\nfunction latY(lat) {\n    const sin = Math.sin(lat * Math.PI / 180);\n    const y = (0.5 - 0.25 * Math.log((1 + sin) / (1 - sin)) / Math.PI);\n    return y < 0 ? 0 : y > 1 ? 1 : y;\n}\n\n// spherical mercator to longitude/latitude\nfunction xLng(x) {\n    return (x - 0.5) * 360;\n}\nfunction yLat(y) {\n    const y2 = (180 - y * 360) * Math.PI / 180;\n    return 360 * Math.atan(Math.exp(y2)) / Math.PI - 90;\n}\n","\n// calculate simplification data using optimized Douglas-Peucker algorithm\n\nexport default function simplify(coords, first, last, sqTolerance) {\n    let maxSqDist = sqTolerance;\n    const mid = first + ((last - first) >> 1);\n    let minPosToMid = last - first;\n    let index;\n\n    const ax = coords[first];\n    const ay = coords[first + 1];\n    const bx = coords[last];\n    const by = coords[last + 1];\n\n    for (let i = first + 3; i < last; i += 3) {\n        const d = getSqSegDist(coords[i], coords[i + 1], ax, ay, bx, by);\n\n        if (d > maxSqDist) {\n            index = i;\n            maxSqDist = d;\n\n        } else if (d === maxSqDist) {\n            // a workaround to ensure we choose a pivot close to the middle of the list,\n            // reducing recursion depth, for certain degenerate inputs\n            // https://github.com/mapbox/geojson-vt/issues/104\n            const posToMid = Math.abs(i - mid);\n            if (posToMid < minPosToMid) {\n                index = i;\n                minPosToMid = posToMid;\n            }\n        }\n    }\n\n    if (maxSqDist > sqTolerance) {\n        if (index - first > 3) simplify(coords, first, index, sqTolerance);\n        coords[index + 2] = maxSqDist;\n        if (last - index > 3) simplify(coords, index, last, sqTolerance);\n    }\n}\n\n// square distance from a point to a segment\nfunction getSqSegDist(px, py, x, y, bx, by) {\n\n    let dx = bx - x;\n    let dy = by - y;\n\n    if (dx !== 0 || dy !== 0) {\n\n        const t = ((px - x) * dx + (py - y) * dy) / (dx * dx + dy * dy);\n\n        if (t > 1) {\n            x = bx;\n            y = by;\n\n        } else if (t > 0) {\n            x += dx * t;\n            y += dy * t;\n        }\n    }\n\n    dx = px - x;\n    dy = py - y;\n\n    return dx * dx + dy * dy;\n}\n","\nexport default function createFeature(id, type, geom, tags) {\n    const feature = {\n        id: id == null ? null : id,\n        type,\n        geometry: geom,\n        tags,\n        minX: Infinity,\n        minY: Infinity,\n        maxX: -Infinity,\n        maxY: -Infinity\n    };\n\n    if (type === 'Point' || type === 'MultiPoint' || type === 'LineString') {\n        calcLineBBox(feature, geom);\n\n    } else if (type === 'Polygon') {\n        // the outer ring (ie [0]) contains all inner rings\n        calcLineBBox(feature, geom[0]);\n\n    } else if (type === 'MultiLineString') {\n        for (const line of geom) {\n            calcLineBBox(feature, line);\n        }\n\n    } else if (type === 'MultiPolygon') {\n        for (const polygon of geom) {\n            // the outer ring (ie [0]) contains all inner rings\n            calcLineBBox(feature, polygon[0]);\n        }\n    }\n\n    return feature;\n}\n\nfunction calcLineBBox(feature, geom) {\n    for (let i = 0; i < geom.length; i += 3) {\n        feature.minX = Math.min(feature.minX, geom[i]);\n        feature.minY = Math.min(feature.minY, geom[i + 1]);\n        feature.maxX = Math.max(feature.maxX, geom[i]);\n        feature.maxY = Math.max(feature.maxY, geom[i + 1]);\n    }\n}\n","\nimport simplify from './simplify.js';\nimport createFeature from './feature.js';\n\n// converts GeoJSON feature into an intermediate projected JSON vector format with simplification data\n\nexport default function convert(data, options) {\n    const features = [];\n    if (data.type === 'FeatureCollection') {\n        for (let i = 0; i < data.features.length; i++) {\n            convertFeature(features, data.features[i], options, i);\n        }\n\n    } else if (data.type === 'Feature') {\n        convertFeature(features, data, options);\n\n    } else {\n        // single geometry or a geometry collection\n        convertFeature(features, {geometry: data}, options);\n    }\n\n    return features;\n}\n\nfunction convertFeature(features, geojson, options, index) {\n    if (!geojson.geometry) return;\n\n    const coords = geojson.geometry.coordinates;\n    if (coords && coords.length === 0) return;\n\n    const type = geojson.geometry.type;\n    const tolerance = Math.pow(options.tolerance / ((1 << options.maxZoom) * options.extent), 2);\n    let geometry = [];\n    let id = geojson.id;\n    if (options.promoteId) {\n        id = geojson.properties[options.promoteId];\n    } else if (options.generateId) {\n        id = index || 0;\n    }\n    if (type === 'Point') {\n        convertPoint(coords, geometry);\n\n    } else if (type === 'MultiPoint') {\n        for (const p of coords) {\n            convertPoint(p, geometry);\n        }\n\n    } else if (type === 'LineString') {\n        convertLine(coords, geometry, tolerance, false);\n\n    } else if (type === 'MultiLineString') {\n        if (options.lineMetrics) {\n            // explode into linestrings to be able to track metrics\n            for (const line of coords) {\n                geometry = [];\n                convertLine(line, geometry, tolerance, false);\n                features.push(createFeature(id, 'LineString', geometry, geojson.properties));\n            }\n            return;\n        } else {\n            convertLines(coords, geometry, tolerance, false);\n        }\n\n    } else if (type === 'Polygon') {\n        convertLines(coords, geometry, tolerance, true);\n\n    } else if (type === 'MultiPolygon') {\n        for (const polygon of coords) {\n            const newPolygon = [];\n            convertLines(polygon, newPolygon, tolerance, true);\n            geometry.push(newPolygon);\n        }\n    } else if (type === 'GeometryCollection') {\n        for (const singleGeometry of geojson.geometry.geometries) {\n            convertFeature(features, {\n                id,\n                geometry: singleGeometry,\n                properties: geojson.properties\n            }, options, index);\n        }\n        return;\n    } else {\n        throw new Error('Input data is not a valid GeoJSON object.');\n    }\n\n    features.push(createFeature(id, type, geometry, geojson.properties));\n}\n\nfunction convertPoint(coords, out) {\n    out.push(projectX(coords[0]), projectY(coords[1]), 0);\n}\n\nfunction convertLine(ring, out, tolerance, isPolygon) {\n    let x0, y0;\n    let size = 0;\n\n    for (let j = 0; j < ring.length; j++) {\n        const x = projectX(ring[j][0]);\n        const y = projectY(ring[j][1]);\n\n        out.push(x, y, 0);\n\n        if (j > 0) {\n            if (isPolygon) {\n                size += (x0 * y - x * y0) / 2; // area\n            } else {\n                size += Math.sqrt(Math.pow(x - x0, 2) + Math.pow(y - y0, 2)); // length\n            }\n        }\n        x0 = x;\n        y0 = y;\n    }\n\n    const last = out.length - 3;\n    out[2] = 1;\n    simplify(out, 0, last, tolerance);\n    out[last + 2] = 1;\n\n    out.size = Math.abs(size);\n    out.start = 0;\n    out.end = out.size;\n}\n\nfunction convertLines(rings, out, tolerance, isPolygon) {\n    for (let i = 0; i < rings.length; i++) {\n        const geom = [];\n        convertLine(rings[i], geom, tolerance, isPolygon);\n        out.push(geom);\n    }\n}\n\nfunction projectX(x) {\n    return x / 360 + 0.5;\n}\n\nfunction projectY(y) {\n    const sin = Math.sin(y * Math.PI / 180);\n    const y2 = 0.5 - 0.25 * Math.log((1 + sin) / (1 - sin)) / Math.PI;\n    return y2 < 0 ? 0 : y2 > 1 ? 1 : y2;\n}\n","\nimport createFeature from './feature.js';\n\n/* clip features between two vertical or horizontal axis-parallel lines:\n *     |        |\n *  ___|___     |     /\n * /   |   \\____|____/\n *     |        |\n *\n * k1 and k2 are the line coordinates\n * axis: 0 for x, 1 for y\n * minAll and maxAll: minimum and maximum coordinate value for all features\n */\nexport default function clip(features, scale, k1, k2, axis, minAll, maxAll, options) {\n    k1 /= scale;\n    k2 /= scale;\n\n    if (minAll >= k1 && maxAll < k2) return features; // trivial accept\n    else if (maxAll < k1 || minAll >= k2) return null; // trivial reject\n\n    const clipped = [];\n\n    for (const feature of features) {\n        const geometry = feature.geometry;\n        let type = feature.type;\n\n        const min = axis === 0 ? feature.minX : feature.minY;\n        const max = axis === 0 ? feature.maxX : feature.maxY;\n\n        if (min >= k1 && max < k2) { // trivial accept\n            clipped.push(feature);\n            continue;\n        } else if (max < k1 || min >= k2) { // trivial reject\n            continue;\n        }\n\n        let newGeometry = [];\n\n        if (type === 'Point' || type === 'MultiPoint') {\n            clipPoints(geometry, newGeometry, k1, k2, axis);\n\n        } else if (type === 'LineString') {\n            clipLine(geometry, newGeometry, k1, k2, axis, false, options.lineMetrics);\n\n        } else if (type === 'MultiLineString') {\n            clipLines(geometry, newGeometry, k1, k2, axis, false);\n\n        } else if (type === 'Polygon') {\n            clipLines(geometry, newGeometry, k1, k2, axis, true);\n\n        } else if (type === 'MultiPolygon') {\n            for (const polygon of geometry) {\n                const newPolygon = [];\n                clipLines(polygon, newPolygon, k1, k2, axis, true);\n                if (newPolygon.length) {\n                    newGeometry.push(newPolygon);\n                }\n            }\n        }\n\n        if (newGeometry.length) {\n            if (options.lineMetrics && type === 'LineString') {\n                for (const line of newGeometry) {\n                    clipped.push(createFeature(feature.id, type, line, feature.tags));\n                }\n                continue;\n            }\n\n            if (type === 'LineString' || type === 'MultiLineString') {\n                if (newGeometry.length === 1) {\n                    type = 'LineString';\n                    newGeometry = newGeometry[0];\n                } else {\n                    type = 'MultiLineString';\n                }\n            }\n            if (type === 'Point' || type === 'MultiPoint') {\n                type = newGeometry.length === 3 ? 'Point' : 'MultiPoint';\n            }\n\n            clipped.push(createFeature(feature.id, type, newGeometry, feature.tags));\n        }\n    }\n\n    return clipped.length ? clipped : null;\n}\n\nfunction clipPoints(geom, newGeom, k1, k2, axis) {\n    for (let i = 0; i < geom.length; i += 3) {\n        const a = geom[i + axis];\n\n        if (a >= k1 && a <= k2) {\n            addPoint(newGeom, geom[i], geom[i + 1], geom[i + 2]);\n        }\n    }\n}\n\nfunction clipLine(geom, newGeom, k1, k2, axis, isPolygon, trackMetrics) {\n\n    let slice = newSlice(geom);\n    const intersect = axis === 0 ? intersectX : intersectY;\n    let len = geom.start;\n    let segLen, t;\n\n    for (let i = 0; i < geom.length - 3; i += 3) {\n        const ax = geom[i];\n        const ay = geom[i + 1];\n        const az = geom[i + 2];\n        const bx = geom[i + 3];\n        const by = geom[i + 4];\n        const a = axis === 0 ? ax : ay;\n        const b = axis === 0 ? bx : by;\n        let exited = false;\n\n        if (trackMetrics) segLen = Math.sqrt(Math.pow(ax - bx, 2) + Math.pow(ay - by, 2));\n\n        if (a < k1) {\n            // ---|-->  | (line enters the clip region from the left)\n            if (b > k1) {\n                t = intersect(slice, ax, ay, bx, by, k1);\n                if (trackMetrics) slice.start = len + segLen * t;\n            }\n        } else if (a > k2) {\n            // |  <--|--- (line enters the clip region from the right)\n            if (b < k2) {\n                t = intersect(slice, ax, ay, bx, by, k2);\n                if (trackMetrics) slice.start = len + segLen * t;\n            }\n        } else {\n            addPoint(slice, ax, ay, az);\n        }\n        if (b < k1 && a >= k1) {\n            // <--|---  | or <--|-----|--- (line exits the clip region on the left)\n            t = intersect(slice, ax, ay, bx, by, k1);\n            exited = true;\n        }\n        if (b > k2 && a <= k2) {\n            // |  ---|--> or ---|-----|--> (line exits the clip region on the right)\n            t = intersect(slice, ax, ay, bx, by, k2);\n            exited = true;\n        }\n\n        if (!isPolygon && exited) {\n            if (trackMetrics) slice.end = len + segLen * t;\n            newGeom.push(slice);\n            slice = newSlice(geom);\n        }\n\n        if (trackMetrics) len += segLen;\n    }\n\n    // add the last point\n    let last = geom.length - 3;\n    const ax = geom[last];\n    const ay = geom[last + 1];\n    const az = geom[last + 2];\n    const a = axis === 0 ? ax : ay;\n    if (a >= k1 && a <= k2) addPoint(slice, ax, ay, az);\n\n    // close the polygon if its endpoints are not the same after clipping\n    last = slice.length - 3;\n    if (isPolygon && last >= 3 && (slice[last] !== slice[0] || slice[last + 1] !== slice[1])) {\n        addPoint(slice, slice[0], slice[1], slice[2]);\n    }\n\n    // add the final slice\n    if (slice.length) {\n        newGeom.push(slice);\n    }\n}\n\nfunction newSlice(line) {\n    const slice = [];\n    slice.size = line.size;\n    slice.start = line.start;\n    slice.end = line.end;\n    return slice;\n}\n\nfunction clipLines(geom, newGeom, k1, k2, axis, isPolygon) {\n    for (const line of geom) {\n        clipLine(line, newGeom, k1, k2, axis, isPolygon, false);\n    }\n}\n\nfunction addPoint(out, x, y, z) {\n    out.push(x, y, z);\n}\n\nfunction intersectX(out, ax, ay, bx, by, x) {\n    const t = (x - ax) / (bx - ax);\n    addPoint(out, x, ay + (by - ay) * t, 1);\n    return t;\n}\n\nfunction intersectY(out, ax, ay, bx, by, y) {\n    const t = (y - ay) / (by - ay);\n    addPoint(out, ax + (bx - ax) * t, y, 1);\n    return t;\n}\n","\nimport clip from './clip.js';\nimport createFeature from './feature.js';\n\nexport default function wrap(features, options) {\n    const buffer = options.buffer / options.extent;\n    let merged = features;\n    const left  = clip(features, 1, -1 - buffer, buffer,     0, -1, 2, options); // left world copy\n    const right = clip(features, 1,  1 - buffer, 2 + buffer, 0, -1, 2, options); // right world copy\n\n    if (left || right) {\n        merged = clip(features, 1, -buffer, 1 + buffer, 0, -1, 2, options) || []; // center world copy\n\n        if (left) merged = shiftFeatureCoords(left, 1).concat(merged); // merge left into center\n        if (right) merged = merged.concat(shiftFeatureCoords(right, -1)); // merge right into center\n    }\n\n    return merged;\n}\n\nfunction shiftFeatureCoords(features, offset) {\n    const newFeatures = [];\n\n    for (let i = 0; i < features.length; i++) {\n        const feature = features[i];\n        const type = feature.type;\n\n        let newGeometry;\n\n        if (type === 'Point' || type === 'MultiPoint' || type === 'LineString') {\n            newGeometry = shiftCoords(feature.geometry, offset);\n\n        } else if (type === 'MultiLineString' || type === 'Polygon') {\n            newGeometry = [];\n            for (const line of feature.geometry) {\n                newGeometry.push(shiftCoords(line, offset));\n            }\n        } else if (type === 'MultiPolygon') {\n            newGeometry = [];\n            for (const polygon of feature.geometry) {\n                const newPolygon = [];\n                for (const line of polygon) {\n                    newPolygon.push(shiftCoords(line, offset));\n                }\n                newGeometry.push(newPolygon);\n            }\n        }\n\n        newFeatures.push(createFeature(feature.id, type, newGeometry, feature.tags));\n    }\n\n    return newFeatures;\n}\n\nfunction shiftCoords(points, offset) {\n    const newPoints = [];\n    newPoints.size = points.size;\n\n    if (points.start !== undefined) {\n        newPoints.start = points.start;\n        newPoints.end = points.end;\n    }\n\n    for (let i = 0; i < points.length; i += 3) {\n        newPoints.push(points[i] + offset, points[i + 1], points[i + 2]);\n    }\n    return newPoints;\n}\n","\n// Transforms the coordinates of each feature in the given tile from\n// mercator-projected space into (extent x extent) tile space.\nexport default function transformTile(tile, extent) {\n    if (tile.transformed) return tile;\n\n    const z2 = 1 << tile.z;\n    const tx = tile.x;\n    const ty = tile.y;\n\n    for (const feature of tile.features) {\n        const geom = feature.geometry;\n        const type = feature.type;\n\n        feature.geometry = [];\n\n        if (type === 1) {\n            for (let j = 0; j < geom.length; j += 2) {\n                feature.geometry.push(transformPoint(geom[j], geom[j + 1], extent, z2, tx, ty));\n            }\n        } else {\n            for (let j = 0; j < geom.length; j++) {\n                const ring = [];\n                for (let k = 0; k < geom[j].length; k += 2) {\n                    ring.push(transformPoint(geom[j][k], geom[j][k + 1], extent, z2, tx, ty));\n                }\n                feature.geometry.push(ring);\n            }\n        }\n    }\n\n    tile.transformed = true;\n\n    return tile;\n}\n\nfunction transformPoint(x, y, extent, z2, tx, ty) {\n    return [\n        Math.round(extent * (x * z2 - tx)),\n        Math.round(extent * (y * z2 - ty))];\n}\n","\nexport default function createTile(features, z, tx, ty, options) {\n    const tolerance = z === options.maxZoom ? 0 : options.tolerance / ((1 << z) * options.extent);\n    const tile = {\n        features: [],\n        numPoints: 0,\n        numSimplified: 0,\n        numFeatures: features.length,\n        source: null,\n        x: tx,\n        y: ty,\n        z,\n        transformed: false,\n        minX: 2,\n        minY: 1,\n        maxX: -1,\n        maxY: 0\n    };\n    for (const feature of features) {\n        addFeature(tile, feature, tolerance, options);\n    }\n    return tile;\n}\n\nfunction addFeature(tile, feature, tolerance, options) {\n    const geom = feature.geometry;\n    const type = feature.type;\n    const simplified = [];\n\n    tile.minX = Math.min(tile.minX, feature.minX);\n    tile.minY = Math.min(tile.minY, feature.minY);\n    tile.maxX = Math.max(tile.maxX, feature.maxX);\n    tile.maxY = Math.max(tile.maxY, feature.maxY);\n\n    if (type === 'Point' || type === 'MultiPoint') {\n        for (let i = 0; i < geom.length; i += 3) {\n            simplified.push(geom[i], geom[i + 1]);\n            tile.numPoints++;\n            tile.numSimplified++;\n        }\n\n    } else if (type === 'LineString') {\n        addLine(simplified, geom, tile, tolerance, false, false);\n\n    } else if (type === 'MultiLineString' || type === 'Polygon') {\n        for (let i = 0; i < geom.length; i++) {\n            addLine(simplified, geom[i], tile, tolerance, type === 'Polygon', i === 0);\n        }\n\n    } else if (type === 'MultiPolygon') {\n\n        for (let k = 0; k < geom.length; k++) {\n            const polygon = geom[k];\n            for (let i = 0; i < polygon.length; i++) {\n                addLine(simplified, polygon[i], tile, tolerance, true, i === 0);\n            }\n        }\n    }\n\n    if (simplified.length) {\n        let tags = feature.tags || null;\n\n        if (type === 'LineString' && options.lineMetrics) {\n            tags = {};\n            for (const key in feature.tags) tags[key] = feature.tags[key];\n            tags['mapbox_clip_start'] = geom.start / geom.size;\n            tags['mapbox_clip_end'] = geom.end / geom.size;\n        }\n\n        const tileFeature = {\n            geometry: simplified,\n            type: type === 'Polygon' || type === 'MultiPolygon' ? 3 :\n            (type === 'LineString' || type === 'MultiLineString' ? 2 : 1),\n            tags\n        };\n        if (feature.id !== null) {\n            tileFeature.id = feature.id;\n        }\n        tile.features.push(tileFeature);\n    }\n}\n\nfunction addLine(result, geom, tile, tolerance, isPolygon, isOuter) {\n    const sqTolerance = tolerance * tolerance;\n\n    if (tolerance > 0 && (geom.size < (isPolygon ? sqTolerance : tolerance))) {\n        tile.numPoints += geom.length / 3;\n        return;\n    }\n\n    const ring = [];\n\n    for (let i = 0; i < geom.length; i += 3) {\n        if (tolerance === 0 || geom[i + 2] > sqTolerance) {\n            tile.numSimplified++;\n            ring.push(geom[i], geom[i + 1]);\n        }\n        tile.numPoints++;\n    }\n\n    if (isPolygon) rewind(ring, isOuter);\n\n    result.push(ring);\n}\n\nfunction rewind(ring, clockwise) {\n    let area = 0;\n    for (let i = 0, len = ring.length, j = len - 2; i < len; j = i, i += 2) {\n        area += (ring[i] - ring[j]) * (ring[i + 1] + ring[j + 1]);\n    }\n    if (area > 0 === clockwise) {\n        for (let i = 0, len = ring.length; i < len / 2; i += 2) {\n            const x = ring[i];\n            const y = ring[i + 1];\n            ring[i] = ring[len - 2 - i];\n            ring[i + 1] = ring[len - 1 - i];\n            ring[len - 2 - i] = x;\n            ring[len - 1 - i] = y;\n        }\n    }\n}\n","\nimport convert from './convert.js';     // GeoJSON conversion and preprocessing\nimport clip from './clip.js';           // stripe clipping algorithm\nimport wrap from './wrap.js';           // date line processing\nimport transform from './transform.js'; // coordinate transformation\nimport createTile from './tile.js';     // final simplified tile generation\n\nconst defaultOptions = {\n    maxZoom: 14,            // max zoom to preserve detail on\n    indexMaxZoom: 5,        // max zoom in the tile index\n    indexMaxPoints: 100000, // max number of points per tile in the tile index\n    tolerance: 3,           // simplification tolerance (higher means simpler)\n    extent: 4096,           // tile extent\n    buffer: 64,             // tile buffer on each side\n    lineMetrics: false,     // whether to calculate line metrics\n    promoteId: null,        // name of a feature property to be promoted to feature.id\n    generateId: false,      // whether to generate feature ids. Cannot be used with promoteId\n    debug: 0                // logging level (0, 1 or 2)\n};\n\nclass GeoJSONVT {\n    constructor(data, options) {\n        options = this.options = extend(Object.create(defaultOptions), options);\n\n        const debug = options.debug;\n\n        if (debug) console.time('preprocess data');\n\n        if (options.maxZoom < 0 || options.maxZoom > 24) throw new Error('maxZoom should be in the 0-24 range');\n        if (options.promoteId && options.generateId) throw new Error('promoteId and generateId cannot be used together.');\n\n        // projects and adds simplification info\n        let features = convert(data, options);\n\n        // tiles and tileCoords are part of the public API\n        this.tiles = {};\n        this.tileCoords = [];\n\n        if (debug) {\n            console.timeEnd('preprocess data');\n            console.log('index: maxZoom: %d, maxPoints: %d', options.indexMaxZoom, options.indexMaxPoints);\n            console.time('generate tiles');\n            this.stats = {};\n            this.total = 0;\n        }\n\n        // wraps features (ie extreme west and extreme east)\n        features = wrap(features, options);\n\n        // start slicing from the top tile down\n        if (features.length) this.splitTile(features, 0, 0, 0);\n\n        if (debug) {\n            if (features.length) console.log('features: %d, points: %d', this.tiles[0].numFeatures, this.tiles[0].numPoints);\n            console.timeEnd('generate tiles');\n            console.log('tiles generated:', this.total, JSON.stringify(this.stats));\n        }\n    }\n\n    // splits features from a parent tile to sub-tiles.\n    // z, x, and y are the coordinates of the parent tile\n    // cz, cx, and cy are the coordinates of the target tile\n    //\n    // If no target tile is specified, splitting stops when we reach the maximum\n    // zoom or the number of points is low as specified in the options.\n    splitTile(features, z, x, y, cz, cx, cy) {\n\n        const stack = [features, z, x, y];\n        const options = this.options;\n        const debug = options.debug;\n\n        // avoid recursion by using a processing queue\n        while (stack.length) {\n            y = stack.pop();\n            x = stack.pop();\n            z = stack.pop();\n            features = stack.pop();\n\n            const z2 = 1 << z;\n            const id = toID(z, x, y);\n            let tile = this.tiles[id];\n\n            if (!tile) {\n                if (debug > 1) console.time('creation');\n\n                tile = this.tiles[id] = createTile(features, z, x, y, options);\n                this.tileCoords.push({z, x, y});\n\n                if (debug) {\n                    if (debug > 1) {\n                        console.log('tile z%d-%d-%d (features: %d, points: %d, simplified: %d)',\n                            z, x, y, tile.numFeatures, tile.numPoints, tile.numSimplified);\n                        console.timeEnd('creation');\n                    }\n                    const key = `z${  z}`;\n                    this.stats[key] = (this.stats[key] || 0) + 1;\n                    this.total++;\n                }\n            }\n\n            // save reference to original geometry in tile so that we can drill down later if we stop now\n            tile.source = features;\n\n            // if it's the first-pass tiling\n            if (cz == null) {\n                // stop tiling if we reached max zoom, or if the tile is too simple\n                if (z === options.indexMaxZoom || tile.numPoints <= options.indexMaxPoints) continue;\n            // if a drilldown to a specific tile\n            } else if (z === options.maxZoom || z === cz) {\n                // stop tiling if we reached base zoom or our target tile zoom\n                continue;\n            } else if (cz != null) {\n                // stop tiling if it's not an ancestor of the target tile\n                const zoomSteps = cz - z;\n                if (x !== cx >> zoomSteps || y !== cy >> zoomSteps) continue;\n            }\n\n            // if we slice further down, no need to keep source geometry\n            tile.source = null;\n\n            if (features.length === 0) continue;\n\n            if (debug > 1) console.time('clipping');\n\n            // values we'll use for clipping\n            const k1 = 0.5 * options.buffer / options.extent;\n            const k2 = 0.5 - k1;\n            const k3 = 0.5 + k1;\n            const k4 = 1 + k1;\n\n            let tl = null;\n            let bl = null;\n            let tr = null;\n            let br = null;\n\n            let left  = clip(features, z2, x - k1, x + k3, 0, tile.minX, tile.maxX, options);\n            let right = clip(features, z2, x + k2, x + k4, 0, tile.minX, tile.maxX, options);\n            features = null;\n\n            if (left) {\n                tl = clip(left, z2, y - k1, y + k3, 1, tile.minY, tile.maxY, options);\n                bl = clip(left, z2, y + k2, y + k4, 1, tile.minY, tile.maxY, options);\n                left = null;\n            }\n\n            if (right) {\n                tr = clip(right, z2, y - k1, y + k3, 1, tile.minY, tile.maxY, options);\n                br = clip(right, z2, y + k2, y + k4, 1, tile.minY, tile.maxY, options);\n                right = null;\n            }\n\n            if (debug > 1) console.timeEnd('clipping');\n\n            stack.push(tl || [], z + 1, x * 2,     y * 2);\n            stack.push(bl || [], z + 1, x * 2,     y * 2 + 1);\n            stack.push(tr || [], z + 1, x * 2 + 1, y * 2);\n            stack.push(br || [], z + 1, x * 2 + 1, y * 2 + 1);\n        }\n    }\n\n    getTile(z, x, y) {\n        z = +z;\n        x = +x;\n        y = +y;\n\n        const options = this.options;\n        const {extent, debug} = options;\n\n        if (z < 0 || z > 24) return null;\n\n        const z2 = 1 << z;\n        x = (x + z2) & (z2 - 1); // wrap tile x coordinate\n\n        const id = toID(z, x, y);\n        if (this.tiles[id]) return transform(this.tiles[id], extent);\n\n        if (debug > 1) console.log('drilling down to z%d-%d-%d', z, x, y);\n\n        let z0 = z;\n        let x0 = x;\n        let y0 = y;\n        let parent;\n\n        while (!parent && z0 > 0) {\n            z0--;\n            x0 = x0 >> 1;\n            y0 = y0 >> 1;\n            parent = this.tiles[toID(z0, x0, y0)];\n        }\n\n        if (!parent || !parent.source) return null;\n\n        // if we found a parent tile containing the original geometry, we can drill down from it\n        if (debug > 1) {\n            console.log('found parent tile z%d-%d-%d', z0, x0, y0);\n            console.time('drilling down');\n        }\n        this.splitTile(parent.source, z0, x0, y0, z, x, y);\n        if (debug > 1) console.timeEnd('drilling down');\n\n        return this.tiles[id] ? transform(this.tiles[id], extent) : null;\n    }\n}\n\nfunction toID(z, x, y) {\n    return (((1 << z) * y + x) * 32) + z;\n}\n\nfunction extend(dest, src) {\n    for (const i in src) dest[i] = src[i];\n    return dest;\n}\n\nexport default function geojsonvt(data, options) {\n    return new GeoJSONVT(data, options);\n}\n","import {getJSON} from '../util/ajax';\n\nimport {getPerformanceMeasurement} from '../util/performance';\nimport GeoJSONWrapper from './geojson_wrapper';\nimport GeoJSONRT from './geojson_rt';\nimport vtpbf from 'vt-pbf';\nimport Supercluster from 'supercluster';\nimport geojsonvt from 'geojson-vt';\nimport assert from 'assert';\nimport VectorTileWorkerSource from './vector_tile_worker_source';\nimport {createExpression} from '../style-spec/expression/index';\n\nimport type {\n    RequestedTileParameters,\n    WorkerTileParameters,\n    WorkerTileCallback,\n} from '../source/worker_source';\n\nimport type Actor from '../util/actor';\nimport type StyleLayerIndex from '../style/style_layer_index';\n\nimport type {LoadVectorDataCallback} from './load_vector_tile';\nimport type {RequestParameters, ResponseCallback} from '../util/ajax';\nimport type {Callback} from '../types/callback';\n\nexport type GeoJSONWorkerOptions = {\n    source: string;\n    cluster: boolean;\n    superclusterOptions?: any;\n    geojsonVtOptions?: any;\n    clusterProperties?: any;\n    filter?: Array<unknown>;\n    dynamic?: boolean;\n};\n\nexport type LoadGeoJSONParameters = GeoJSONWorkerOptions & {\n    request?: RequestParameters;\n    data?: string;\n    append?: boolean;\n};\n\nexport type LoadGeoJSON = (params: LoadGeoJSONParameters, callback: ResponseCallback<any>) => void;\n\nexport interface GeoJSONIndex {\n    getTile(z: number, x: number, y: number): any;\n    // supercluster methods\n    getClusterExpansionZoom?(clusterId: number): number;\n    getChildren?(clusterId: number): Array<GeoJSON.Feature>;\n    getLeaves?(clusterId: number, limit: number, offset: number): Array<GeoJSON.Feature>;\n}\n\nfunction loadGeoJSONTile(params: RequestedTileParameters, callback: LoadVectorDataCallback) {\n    const canonical = params.tileID.canonical;\n\n    if (!this._geoJSONIndex) {\n        return callback(null, null);  // we couldn't load the file\n    }\n\n    const geoJSONTile = this._geoJSONIndex.getTile(canonical.z, canonical.x, canonical.y);\n    if (!geoJSONTile) {\n        return callback(null, null); // nothing in the given tile\n    }\n\n    const geojsonWrapper = new GeoJSONWrapper(geoJSONTile.features);\n\n    // Encode the geojson-vt tile into binary vector tile form.  This\n    // is a convenience that allows `FeatureIndex` to operate the same way\n    // across `VectorTileSource` and `GeoJSONSource` data.\n    let pbf = vtpbf(geojsonWrapper);\n    if (pbf.byteOffset !== 0 || pbf.byteLength !== pbf.buffer.byteLength) {\n        // Compatibility with node Buffer (https://github.com/mapbox/pbf/issues/35)\n        pbf = new Uint8Array(pbf);\n    }\n\n    callback(null, {\n        vectorTile: geojsonWrapper,\n        rawData: pbf.buffer\n    });\n}\n\n/**\n * The {@link WorkerSource} implementation that supports {@link GeoJSONSource}.\n * This class is designed to be easily reused to support custom source types\n * for data formats that can be parsed/converted into an in-memory GeoJSON\n * representation.  To do so, create it with\n * `new GeoJSONWorkerSource(actor, layerIndex, customLoadGeoJSONFunction)`.\n * For a full example, see [mapbox-gl-topojson](https://github.com/developmentseed/mapbox-gl-topojson).\n *\n * @private\n */\nclass GeoJSONWorkerSource extends VectorTileWorkerSource {\n    _geoJSONIndex: GeoJSONIndex;\n    _dynamicIndex: GeoJSONRT;\n\n    /**\n     * @param [loadGeoJSON] Optional method for custom loading/parsing of\n     * GeoJSON based on parameters passed from the main-thread Source.\n     * See {@link GeoJSONWorkerSource#loadGeoJSON}.\n     * @private\n     */\n    constructor(actor: Actor, layerIndex: StyleLayerIndex, availableImages: Array<string>, isSpriteLoaded: boolean, loadGeoJSON?: LoadGeoJSON | null, brightness?: number | null) {\n        // @ts-expect-error - TS2345 - Argument of type '(params: RequestedTileParameters, callback: LoadVectorDataCallback) => void' is not assignable to parameter of type 'LoadVectorData'.\n        super(actor, layerIndex, availableImages, isSpriteLoaded, loadGeoJSONTile, brightness);\n        if (loadGeoJSON) {\n            this.loadGeoJSON = loadGeoJSON;\n        }\n        this._dynamicIndex = new GeoJSONRT();\n    }\n\n    /**\n     * Fetches (if appropriate), parses, and index geojson data into tiles. This\n     * preparatory method must be called before {@link GeoJSONWorkerSource#loadTile}\n     * can correctly serve up tiles.\n     *\n     * Defers to {@link GeoJSONWorkerSource#loadGeoJSON} for the fetching/parsing,\n     * expecting `callback(error, data)` to be called with either an error or a\n     * parsed GeoJSON object.\n     *\n     * When `loadData` requests come in faster than they can be processed,\n     * they are coalesced into a single request using the latest data.\n     * See {@link GeoJSONWorkerSource#coalesce}\n     *\n     * @param params\n     * @param callback\n     * @private\n     */\n    loadData(params: LoadGeoJSONParameters, callback: Callback<{\n        resourceTiming?: {\n            [_: string]: Array<PerformanceResourceTiming>;\n        };\n    }>) {\n        const requestParam = params && params.request;\n        const perf = requestParam && requestParam.collectResourceTiming;\n\n        this.loadGeoJSON(params, (err?: Error | null, data?: any | null) => {\n            if (err || !data) {\n                return callback(err);\n\n            } else if (typeof data !== 'object') {\n                return callback(new Error(`Input data given to '${params.source}' is not a valid GeoJSON object.`));\n\n            } else {\n                try {\n                    if (params.filter) {\n                        // @ts-expect-error - TS2353 - Object literal may only specify known properties, and 'overridable' does not exist in type '{ type: \"boolean\"; 'property-type': ExpressionType; expression?: ExpressionSpecification; transition?: boolean; default?: boolean; }'.\n                        const compiled = createExpression(params.filter, {type: 'boolean', 'property-type': 'data-driven', overridable: false, transition: false});\n                        if (compiled.result === 'error')\n                            throw new Error(compiled.value.map(err => `${err.key}: ${err.message}`).join(', '));\n\n                        data.features = data.features.filter(feature => compiled.value.evaluate({zoom: 0}, feature));\n                    }\n\n                    // for GeoJSON sources that are marked as dynamic, we retain the GeoJSON data\n                    // as a id-to-feature map so that we can later update features by id individually\n                    if (params.dynamic) {\n                        if (data.type === 'Feature') data = {type: 'FeatureCollection', features: [data]};\n\n                        if (!params.append) {\n                            this._dynamicIndex.clear();\n                            this.loaded = {};\n                        }\n\n                        this._dynamicIndex.load(data.features, this.loaded);\n\n                        if (params.cluster) data.features = this._dynamicIndex.getFeatures();\n\n                    } else {\n                        this.loaded = {};\n                    }\n\n                    this._geoJSONIndex =\n                        params.cluster ? new Supercluster(getSuperclusterOptions(params)).load(data.features) :\n                        params.dynamic ? this._dynamicIndex :\n                        geojsonvt(data, params.geojsonVtOptions);\n\n                } catch (err: any) {\n                    return callback(err);\n                }\n\n                const result: Record<string, any> = {};\n                if (perf) {\n                    const resourceTimingData = getPerformanceMeasurement(requestParam);\n                    // it's necessary to eval the result of getEntriesByName() here via parse/stringify\n                    // late evaluation in the main thread causes TypeError: illegal invocation\n                    if (resourceTimingData) {\n                        result.resourceTiming = {};\n                        result.resourceTiming[params.source] = JSON.parse(JSON.stringify(resourceTimingData));\n                    }\n                }\n                callback(null, result);\n            }\n        });\n    }\n\n    /**\n    * Implements {@link WorkerSource#reloadTile}.\n    *\n    * If the tile is loaded, uses the implementation in VectorTileWorkerSource.\n    * Otherwise, such as after a setData() call, we load the tile fresh.\n    *\n    * @param params\n    * @param params.uid The UID for this tile.\n    * @private\n    */\n    reloadTile(params: WorkerTileParameters, callback: WorkerTileCallback): void {\n        const loaded = this.loaded,\n            uid = params.uid;\n\n        if (loaded && loaded[uid]) {\n            if (params.partial) {\n                return callback(null, undefined);\n            }\n            return super.reloadTile(params, callback);\n        } else {\n            return this.loadTile(params, callback);\n        }\n    }\n\n    /**\n     * Fetch and parse GeoJSON according to the given params.  Calls `callback`\n     * with `(err, data)`, where `data` is a parsed GeoJSON object.\n     *\n     * GeoJSON is loaded and parsed from `params.url` if it exists, or else\n     * expected as a literal (string or object) `params.data`.\n     *\n     * @param params\n     * @param [params.url] A URL to the remote GeoJSON data.\n     * @param [params.data] Literal GeoJSON data. Must be provided if `params.url` is not.\n     * @private\n     */\n    loadGeoJSON(params: LoadGeoJSONParameters, callback: ResponseCallback<any>): void {\n        // Because of same origin issues, urls must either include an explicit\n        // origin or absolute path.\n        // ie: /foo/bar.json or http://example.com/bar.json\n        // but not ../foo/bar.json\n        if (params.request) {\n            getJSON(params.request, callback);\n        } else if (typeof params.data === 'string') {\n            try {\n                return callback(null, JSON.parse(params.data));\n            } catch (e: any) {\n                return callback(new Error(`Input data given to '${params.source}' is not a valid GeoJSON object.`));\n            }\n        } else {\n            return callback(new Error(`Input data given to '${params.source}' is not a valid GeoJSON object.`));\n        }\n    }\n\n    getClusterExpansionZoom(params: {\n        clusterId: number;\n    }, callback: Callback<number>) {\n        try {\n            callback(null, this._geoJSONIndex.getClusterExpansionZoom(params.clusterId));\n        } catch (e: any) {\n            callback(e);\n        }\n    }\n\n    getClusterChildren(params: {\n        clusterId: number;\n    }, callback: Callback<Array<GeoJSON.Feature>>) {\n        try {\n            callback(null, this._geoJSONIndex.getChildren(params.clusterId));\n        } catch (e: any) {\n            callback(e);\n        }\n    }\n\n    getClusterLeaves(params: {\n        clusterId: number;\n        limit: number;\n        offset: number;\n    }, callback: Callback<Array<GeoJSON.Feature>>) {\n        try {\n            callback(null, this._geoJSONIndex.getLeaves(params.clusterId, params.limit, params.offset));\n        } catch (e: any) {\n            callback(e);\n        }\n    }\n}\n\nfunction getSuperclusterOptions({\n    superclusterOptions,\n    clusterProperties,\n}: LoadGeoJSONParameters) {\n    if (!clusterProperties || !superclusterOptions) return superclusterOptions;\n\n    const mapExpressions: Record<string, any> = {};\n    const reduceExpressions: Record<string, any> = {};\n    const globals = {accumulated: null, zoom: 0};\n    const feature = {properties: null};\n    const propertyNames = Object.keys(clusterProperties);\n\n    for (const key of propertyNames) {\n        const [operator, mapExpression] = clusterProperties[key];\n\n        const mapExpressionParsed = createExpression(mapExpression);\n        const reduceExpressionParsed = createExpression(\n            typeof operator === 'string' ? [operator, ['accumulated'], ['get', key]] : operator);\n\n        assert(mapExpressionParsed.result === 'success');\n        assert(reduceExpressionParsed.result === 'success');\n\n        mapExpressions[key] = mapExpressionParsed.value;\n        reduceExpressions[key] = reduceExpressionParsed.value;\n    }\n\n    superclusterOptions.map = (pointProperties) => {\n        feature.properties = pointProperties;\n        const properties: Record<string, any> = {};\n        for (const key of propertyNames) {\n            properties[key] = mapExpressions[key].evaluate(globals, feature);\n        }\n        return properties;\n    };\n    superclusterOptions.reduce = (accumulated, clusterProperties) => {\n        feature.properties = clusterProperties;\n        for (const key of propertyNames) {\n            globals.accumulated = accumulated[key];\n            accumulated[key] = reduceExpressions[key].evaluate(globals, feature);\n        }\n    };\n\n    return superclusterOptions;\n}\n\nexport default GeoJSONWorkerSource;\n","import {getArrayBuffer} from '../../src/util/ajax';\nimport FeatureIndex from '../../src/data/feature_index';\nimport {process3DTile} from './model_loader';\nimport {tileToMeter} from '../../src/geo/mercator_coordinate';\nimport Tiled3dModelBucket from '../data/bucket/tiled_3d_model_bucket';\nimport {CanonicalTileID, OverscaledTileID} from '../../src/source/tile_id';\nimport {load3DTile} from '../util/loaders';\nimport EvaluationParameters from '../../src/style/evaluation_parameters';\n\nimport type Actor from '../../src/util/actor';\nimport type StyleLayerIndex from '../../src/style/style_layer_index';\nimport type {\n    WorkerSource,\n    WorkerTileParameters,\n    WorkerTileCallback,\n    TileParameters,\n    WorkerTileResult\n} from '../../src/source/worker_source';\nimport type {Bucket} from '../../src/data/bucket';\nimport type Projection from '../../src/geo/projection/projection';\n\nclass Tiled3dWorkerTile {\n    tileID: OverscaledTileID;\n    uid: number;\n    zoom: number;\n    tileZoom: number;\n    canonical: CanonicalTileID;\n    pixelRatio: number;\n    tileSize: number;\n    source: string;\n    overscaling: number;\n    projection: Projection;\n    status: 'parsing' | 'done';\n    reloadCallback: WorkerTileCallback | null | undefined;\n    brightness: number | null | undefined;\n\n    constructor(params: WorkerTileParameters, brightness?: number | null) {\n        this.tileID = new OverscaledTileID(params.tileID.overscaledZ, params.tileID.wrap, params.tileID.canonical.z, params.tileID.canonical.x, params.tileID.canonical.y);\n        this.tileZoom = params.tileZoom;\n        this.uid = params.uid;\n        this.zoom = params.zoom;\n        this.canonical = params.tileID.canonical;\n        this.pixelRatio = params.pixelRatio;\n        this.tileSize = params.tileSize;\n        this.source = params.source;\n        this.overscaling = this.tileID.overscaleFactor();\n        this.projection = params.projection;\n        this.brightness = brightness;\n    }\n\n    parse(\n        data: ArrayBuffer,\n        layerIndex: StyleLayerIndex,\n        params: WorkerTileParameters,\n        callback: WorkerTileCallback,\n    ): Promise<void> {\n        this.status = 'parsing';\n        const tileID = new OverscaledTileID(params.tileID.overscaledZ, params.tileID.wrap, params.tileID.canonical.z, params.tileID.canonical.x, params.tileID.canonical.y);\n        const buckets: {\n            [_: string]: Bucket;\n        } = {};\n        const layerFamilies = layerIndex.familiesBySource[params.source];\n        const featureIndex = new FeatureIndex(tileID, params.promoteId);\n        featureIndex.bucketLayerIDs = [];\n        featureIndex.is3DTile = true;\n\n        return load3DTile(data)\n            .then(gltf => {\n                if (!gltf) return callback(new Error('Could not parse tile'));\n                const nodes = process3DTile(gltf, 1.0 / tileToMeter(params.tileID.canonical));\n                const hasMapboxMeshFeatures = (gltf.json.extensionsUsed && gltf.json.extensionsUsed.includes('MAPBOX_mesh_features')) ||\n                                            (gltf.json.asset.extras && gltf.json.asset.extras['MAPBOX_mesh_features']);\n                const hasMeshoptCompression = gltf.json.extensionsUsed && gltf.json.extensionsUsed.includes('EXT_meshopt_compression');\n\n                const parameters = new EvaluationParameters(this.zoom, {brightness: this.brightness});\n                for (const sourceLayerId in layerFamilies) {\n                    for (const family of layerFamilies[sourceLayerId]) {\n                        const layer = family[0];\n                        featureIndex.bucketLayerIDs.push(family.map((l) => l.id));\n                        layer.recalculate(parameters, []);\n                        const bucket = new Tiled3dModelBucket(nodes, tileID, hasMapboxMeshFeatures, hasMeshoptCompression, this.brightness, featureIndex);\n                        // Upload to GPU without waiting for evaluation if we are in diffuse path\n                        if (!hasMapboxMeshFeatures) bucket.needsUpload = true;\n                        buckets[layer.fqid] = bucket;\n                        // do the first evaluation in the worker to avoid stuttering\n                        // @ts-expect-error - TS2345 - Argument of type 'TypedStyleLayer' is not assignable to parameter of type 'ModelStyleLayer'.\n                        bucket.evaluate(layer);\n                    }\n                }\n                this.status = 'done';\n                // @ts-expect-error - TS2740 - Type '{ [_: string]: Bucket; }' is missing the following properties from type 'Bucket[]': length, pop, push, concat, and 35 more.\n                callback(null, {buckets, featureIndex});\n            })\n            .catch((err) => callback(new Error(err.message)));\n    }\n}\n\n// @ts-expect-error - TS2420 - Class 'Tiled3dModelWorkerSource' incorrectly implements interface 'WorkerSource'.\nclass Tiled3dModelWorkerSource implements WorkerSource {\n    actor: Actor;\n    layerIndex: StyleLayerIndex;\n\n    loading: {\n        [_: number]: Tiled3dWorkerTile;\n    };\n    loaded: {\n        [_: number]: Tiled3dWorkerTile;\n    };\n    brightness: number | null | undefined;\n    constructor(actor: Actor, layerIndex: StyleLayerIndex, availableImages: Array<string>, isSpriteLoaded: boolean, loadVectorData?: any | null, brightness?: number | null) {\n        this.actor = actor;\n        this.layerIndex = layerIndex;\n        this.brightness = brightness;\n        this.loading = {};\n        this.loaded = {};\n    }\n\n    loadTile(params: WorkerTileParameters, callback: WorkerTileCallback) {\n        const uid = params.uid;\n        const workerTile = this.loading[uid] = new Tiled3dWorkerTile(params, this.brightness);\n        getArrayBuffer(params.request, (err?: Error | null, data?: ArrayBuffer | null) => {\n            const aborted = !this.loading[uid];\n            delete this.loading[uid];\n\n            if (aborted || err) {\n                workerTile.status = 'done';\n                if (!aborted) this.loaded[uid] = workerTile;\n                return callback(err);\n            }\n\n            if (!data || data.byteLength === 0) {\n                workerTile.status = 'done';\n                this.loaded[uid] = workerTile;\n                return callback();\n            }\n\n            const workerTileCallback = (err?: Error | null, result?: WorkerTileResult | null) => {\n                workerTile.status = 'done';\n                this.loaded = this.loaded || {};\n                this.loaded[uid] = workerTile;\n\n                if (err || !result) callback(err);\n                else callback(null, result);\n            };\n\n            workerTile.parse(data, this.layerIndex, params, workerTileCallback);\n        });\n    }\n\n    /**\n     * Re-parses a tile that has already been loaded.  Yields the same data as\n     * {@link WorkerSource#loadTile}.\n     */\n    // eslint-disable-next-line no-unused-vars\n    reloadTile(params: WorkerTileParameters, callback: WorkerTileCallback) {\n        const loaded = this.loaded;\n        const uid = params.uid;\n        if (loaded && loaded[uid]) {\n            const workerTile = loaded[uid];\n            workerTile.projection = params.projection;\n            workerTile.brightness = params.brightness;\n\n            const done = (err?: Error | null, data?: WorkerTileResult | null) => {\n                const reloadCallback = workerTile.reloadCallback;\n                if (reloadCallback) {\n                    delete workerTile.reloadCallback;\n                    this.loadTile(params, callback);\n                }\n                callback(err, data);\n            };\n\n            if (workerTile.status === 'parsing') {\n                workerTile.reloadCallback = done;\n            } else if (workerTile.status === 'done') {\n                // do the request again\n                this.loadTile(params, callback);\n            }\n        }\n    }\n\n    /**\n     * Aborts loading a tile that is in progress.\n     */\n    // eslint-disable-next-line no-unused-vars\n    abortTile(params: TileParameters, callback: WorkerTileCallback) {\n        const uid = params.uid;\n        const tile = this.loading[uid];\n        if (tile) {\n            delete this.loading[uid];\n        }\n        callback();\n    }\n\n    /**\n     * Removes this tile from any local caches.\n     */\n    // eslint-disable-next-line no-unused-vars\n    removeTile(params: TileParameters, callback: WorkerTileCallback) {\n        const loaded = this.loaded,\n            uid = params.uid;\n        if (loaded && loaded[uid]) {\n            delete loaded[uid];\n        }\n        callback();\n    }\n\n}\n\nexport default Tiled3dModelWorkerSource;\n","import Actor from '../util/actor';\n\nimport StyleLayerIndex from '../style/style_layer_index';\nimport VectorTileWorkerSource from './vector_tile_worker_source';\nimport RasterDEMTileWorkerSource from './raster_dem_tile_worker_source';\nimport RasterArrayTileWorkerSource from './raster_array_tile_worker_source';\nimport GeoJSONWorkerSource from './geojson_worker_source';\nimport Tiled3dModelWorkerSource from '../../3d-style/source/tiled_3d_model_worker_source';\nimport assert from 'assert';\nimport {plugin as globalRTLTextPlugin} from './rtl_text_plugin';\nimport {enforceCacheSizeLimit} from '../util/tile_request_cache';\nimport {PerformanceUtils} from '../util/performance';\nimport {Event} from '../util/evented';\nimport {getProjection} from '../geo/projection/index';\n\nimport type {Class} from '../types/class';\n\nimport type {\n    WorkerSource,\n    WorkerTileParameters,\n    WorkerDEMTileParameters,\n    WorkerTileCallback,\n    WorkerDEMTileCallback,\n    TileParameters,\n    WorkerRasterArrayTileParameters,\n    WorkerRasterArrayTileCallback\n} from '../source/worker_source';\n\nimport type {WorkerGlobalScopeInterface} from '../util/web_worker';\nimport type {Callback} from '../types/callback';\nimport type {LayerSpecification, ProjectionSpecification} from '../style-spec/types';\nimport type {ConfigOptions} from '../style/properties';\nimport type {PluginState} from './rtl_text_plugin';\nimport type Projection from '../geo/projection/projection';\n\n/**\n * @private\n */\nexport default class Worker {\n    self: WorkerGlobalScopeInterface;\n    actor: Actor;\n    layerIndexes: {\n        [mapId: string]: {\n            [scope: string]: StyleLayerIndex;\n        };\n    };\n    availableImages: {\n        [mapId: string]: {\n            [scope: string]: Array<string>;\n        };\n    };\n    workerSourceTypes: {\n        [_: string]: Class<WorkerSource>;\n    };\n    workerSources: {\n        [mapId: string]: {\n            [scope: string]: {\n                [sourceType: string]: {\n                    [sourceId: string]: WorkerSource;\n                };\n            };\n        };\n    };\n    demWorkerSources: {\n        [mapId: string]: {\n            [scope: string]: {\n                [sourceId: string]: RasterDEMTileWorkerSource;\n            };\n        };\n    };\n    rasterArrayWorkerSource: RasterArrayTileWorkerSource | null | undefined;\n    projections: {\n        [_: string]: Projection;\n    };\n    defaultProjection: Projection;\n    isSpriteLoaded: {\n        [mapId: string]: {\n            [scope: string]: boolean;\n        };\n    };\n    referrer: string | null | undefined;\n    dracoUrl: string | null | undefined;\n    brightness: number | null | undefined;\n\n    constructor(self: WorkerGlobalScopeInterface) {\n        PerformanceUtils.measure('workerEvaluateScript');\n        this.self = self;\n        this.actor = new Actor(self, this);\n\n        this.layerIndexes = {};\n        this.availableImages = {};\n        this.isSpriteLoaded = {};\n\n        this.projections = {};\n        this.defaultProjection = getProjection({name: 'mercator'});\n\n        this.workerSourceTypes = {\n            vector: VectorTileWorkerSource,\n            geojson: GeoJSONWorkerSource,\n            // @ts-expect-error - TS2419 - Types of construct signatures are incompatible.\n            'batched-model': Tiled3dModelWorkerSource\n        };\n\n        // [mapId][scope][sourceType][sourceName] => worker source instance\n        this.workerSources = {};\n        this.demWorkerSources = {};\n\n        this.self.registerWorkerSource = (name: string, WorkerSource: Class<WorkerSource>) => {\n            if (this.workerSourceTypes[name]) {\n                throw new Error(`Worker source with name \"${name}\" already registered.`);\n            }\n            this.workerSourceTypes[name] = WorkerSource;\n        };\n\n        // This is invoked by the RTL text plugin when the download via the `importScripts` call has finished, and the code has been parsed.\n        this.self.registerRTLTextPlugin = (rtlTextPlugin: {\n            applyArabicShaping: any;\n            processBidirectionalText: any;\n            processStyledBidirectionalText?: any;\n        }) => {\n            if (globalRTLTextPlugin.isParsed()) {\n                throw new Error('RTL text plugin already registered.');\n            }\n            globalRTLTextPlugin['applyArabicShaping'] = rtlTextPlugin.applyArabicShaping;\n            globalRTLTextPlugin['processBidirectionalText'] = rtlTextPlugin.processBidirectionalText;\n            globalRTLTextPlugin['processStyledBidirectionalText'] = rtlTextPlugin.processStyledBidirectionalText;\n        };\n    }\n\n    clearCaches(mapId: string, unused: unknown, callback: WorkerTileCallback) {\n        delete this.layerIndexes[mapId];\n        delete this.availableImages[mapId];\n        delete this.workerSources[mapId];\n        delete this.demWorkerSources[mapId];\n        delete this.rasterArrayWorkerSource;\n        callback();\n    }\n\n    checkIfReady(mapID: string, unused: unknown, callback: WorkerTileCallback) {\n        // noop, used to check if a worker is fully set up and ready to receive messages\n        callback();\n    }\n\n    setReferrer(mapID: string, referrer: string) {\n        this.referrer = referrer;\n    }\n\n    spriteLoaded(mapId: string, {\n        scope,\n        isLoaded,\n    }: {\n        scope: string;\n        isLoaded: boolean;\n    }) {\n        if (!this.isSpriteLoaded[mapId])\n            this.isSpriteLoaded[mapId] = {};\n\n        this.isSpriteLoaded[mapId][scope] = isLoaded;\n\n        if (!this.workerSources[mapId] || !this.workerSources[mapId][scope]) {\n            return;\n        }\n\n        for (const workerSource in this.workerSources[mapId][scope]) {\n            const ws = this.workerSources[mapId][scope][workerSource];\n            for (const source in ws) {\n                const workerSource = ws[source];\n                if (workerSource instanceof VectorTileWorkerSource) {\n                    workerSource.isSpriteLoaded = isLoaded;\n                    workerSource.fire(new Event('isSpriteLoaded'));\n                }\n            }\n        }\n    }\n\n    setImages(mapId: string, {\n        scope,\n        images,\n    }: {\n        scope: string;\n        images: Array<string>;\n    }, callback: WorkerTileCallback) {\n        if (!this.availableImages[mapId]) {\n            this.availableImages[mapId] = {};\n        }\n\n        this.availableImages[mapId][scope] = images;\n\n        if (!this.workerSources[mapId] || !this.workerSources[mapId][scope]) {\n            callback();\n            return;\n        }\n\n        for (const workerSource in this.workerSources[mapId][scope]) {\n            const ws = this.workerSources[mapId][scope][workerSource];\n            for (const source in ws) {\n                ws[source].availableImages = images;\n            }\n        }\n\n        callback();\n    }\n\n    setProjection(mapId: string, config: ProjectionSpecification) {\n        this.projections[mapId] = getProjection(config);\n    }\n\n    setBrightness(mapId: string, brightness: number | null | undefined, callback: WorkerTileCallback) {\n        this.brightness = brightness;\n        callback();\n    }\n\n    setLayers(mapId: string, params: {\n        layers: Array<LayerSpecification>;\n        scope: string;\n        options: ConfigOptions;\n    }, callback: WorkerTileCallback) {\n        this.getLayerIndex(mapId, params.scope).replace(params.layers, params.options);\n        callback();\n    }\n\n    updateLayers(mapId: string, params: {\n        layers: Array<LayerSpecification>;\n        scope: string;\n        removedIds: Array<string>;\n        options: ConfigOptions;\n    }, callback: WorkerTileCallback) {\n        this.getLayerIndex(mapId, params.scope).update(params.layers, params.removedIds, params.options);\n        callback();\n    }\n\n    loadTile(mapId: string, params: WorkerTileParameters & {\n        type: string;\n    }, callback: WorkerTileCallback) {\n        assert(params.type);\n        params.projection = this.projections[mapId] || this.defaultProjection;\n        this.getWorkerSource(mapId, params.type, params.source, params.scope).loadTile(params, callback);\n    }\n\n    loadDEMTile(mapId: string, params: WorkerDEMTileParameters, callback: WorkerDEMTileCallback) {\n        this.getDEMWorkerSource(mapId, params.source, params.scope).loadTile(params, callback);\n    }\n\n    decodeRasterArray(mapId: string, params: WorkerRasterArrayTileParameters, callback: WorkerRasterArrayTileCallback) {\n        this.getRasterArrayWorkerSource().decodeRasterArray(params, callback);\n    }\n\n    reloadTile(mapId: string, params: WorkerTileParameters & {\n        type: string;\n    }, callback: WorkerTileCallback) {\n        assert(params.type);\n        params.projection = this.projections[mapId] || this.defaultProjection;\n        this.getWorkerSource(mapId, params.type, params.source, params.scope).reloadTile(params, callback);\n    }\n\n    abortTile(mapId: string, params: TileParameters & {\n        type: string;\n    }, callback: WorkerTileCallback) {\n        assert(params.type);\n        this.getWorkerSource(mapId, params.type, params.source, params.scope).abortTile(params, callback);\n    }\n\n    removeTile(mapId: string, params: TileParameters & {\n        type: string;\n    }, callback: WorkerTileCallback) {\n        assert(params.type);\n        this.getWorkerSource(mapId, params.type, params.source, params.sco