n    depthMask: DepthMask;\n    stencilMask: StencilMask;\n    stencilFunc: StencilFunc;\n    stencilOp: StencilOp;\n    stencilTest: StencilTest;\n    depthRange: DepthRange;\n    depthTest: DepthTest;\n    depthFunc: DepthFunc;\n    blend: Blend;\n    blendFunc: BlendFunc;\n    blendColor: BlendColor;\n    blendEquation: BlendEquation;\n    cullFace: CullFace;\n    cullFaceSide: CullFaceSide;\n    frontFace: FrontFace;\n    program: Program;\n    activeTexture: ActiveTextureUnit;\n    viewport: Viewport;\n    bindFramebuffer: BindFramebuffer;\n    bindRenderbuffer: BindRenderbuffer;\n    bindTexture: BindTexture;\n    bindVertexBuffer: BindVertexBuffer;\n    bindElementBuffer: BindElementBuffer;\n    bindVertexArrayOES: BindVertexArrayOES;\n    pixelStoreUnpack: PixelStoreUnpack;\n    pixelStoreUnpackPremultiplyAlpha: PixelStoreUnpackPremultiplyAlpha;\n    pixelStoreUnpackFlipY: PixelStoreUnpackFlipY;\n    renderer: string | null | undefined;\n    vendor: string | null | undefined;\n\n    extTextureFilterAnisotropic: any;\n    extTextureFilterAnisotropicMax: any;\n    extTextureHalfFloat: any;\n    extRenderToTextureHalfFloat: any;\n    extDebugRendererInfo: any;\n    extTimerQuery: any;\n    extTextureFloatLinear: any;\n    options: ContextOptions;\n    maxPointSize: number;\n\n    constructor(gl: WebGL2RenderingContext, options?: ContextOptions) {\n        this.gl = gl;\n\n        this.clearColor = new ClearColor(this);\n        this.clearDepth = new ClearDepth(this);\n        this.clearStencil = new ClearStencil(this);\n        this.colorMask = new ColorMask(this);\n        this.depthMask = new DepthMask(this);\n        this.stencilMask = new StencilMask(this);\n        this.stencilFunc = new StencilFunc(this);\n        this.stencilOp = new StencilOp(this);\n        this.stencilTest = new StencilTest(this);\n        this.depthRange = new DepthRange(this);\n        this.depthTest = new DepthTest(this);\n        this.depthFunc = new DepthFunc(this);\n        this.blend = new Blend(this);\n        this.blendFunc = new BlendFunc(this);\n        this.blendColor = new BlendColor(this);\n        this.blendEquation = new BlendEquation(this);\n        this.cullFace = new CullFace(this);\n        this.cullFaceSide = new CullFaceSide(this);\n        this.frontFace = new FrontFace(this);\n        this.program = new Program(this);\n        this.activeTexture = new ActiveTextureUnit(this);\n        this.viewport = new Viewport(this);\n        this.bindFramebuffer = new BindFramebuffer(this);\n        this.bindRenderbuffer = new BindRenderbuffer(this);\n        this.bindTexture = new BindTexture(this);\n        this.bindVertexBuffer = new BindVertexBuffer(this);\n        this.bindElementBuffer = new BindElementBuffer(this);\n        this.bindVertexArrayOES = new BindVertexArrayOES(this);\n        this.pixelStoreUnpack = new PixelStoreUnpack(this);\n        this.pixelStoreUnpackPremultiplyAlpha = new PixelStoreUnpackPremultiplyAlpha(this);\n        this.pixelStoreUnpackFlipY = new PixelStoreUnpackFlipY(this);\n        this.options = options ? {...options} : {};\n\n        if (!this.options.extTextureFilterAnisotropicForceOff) {\n            this.extTextureFilterAnisotropic = (\n                gl.getExtension('EXT_texture_filter_anisotropic') ||\n            gl.getExtension('MOZ_EXT_texture_filter_anisotropic') ||\n            gl.getExtension('WEBKIT_EXT_texture_filter_anisotropic')\n            );\n            if (this.extTextureFilterAnisotropic) {\n                this.extTextureFilterAnisotropicMax = gl.getParameter(this.extTextureFilterAnisotropic.MAX_TEXTURE_MAX_ANISOTROPY_EXT);\n            }\n        }\n\n        this.extDebugRendererInfo = gl.getExtension('WEBGL_debug_renderer_info');\n        if (this.extDebugRendererInfo) {\n            this.renderer = gl.getParameter(this.extDebugRendererInfo.UNMASKED_RENDERER_WEBGL);\n            this.vendor = gl.getParameter(this.extDebugRendererInfo.UNMASKED_VENDOR_WEBGL);\n        }\n\n        if (!this.options.extTextureFloatLinearForceOff) {\n            this.extTextureFloatLinear = gl.getExtension('OES_texture_float_linear');\n        }\n        this.extRenderToTextureHalfFloat = gl.getExtension('EXT_color_buffer_half_float');\n\n        this.extTimerQuery = gl.getExtension('EXT_disjoint_timer_query_webgl2');\n        this.maxTextureSize = gl.getParameter(gl.MAX_TEXTURE_SIZE);\n        this.maxPointSize = gl.getParameter(gl.ALIASED_POINT_SIZE_RANGE)[1];\n    }\n\n    setDefault() {\n        this.unbindVAO();\n\n        this.clearColor.setDefault();\n        this.clearDepth.setDefault();\n        this.clearStencil.setDefault();\n        this.colorMask.setDefault();\n        this.depthMask.setDefault();\n        this.stencilMask.setDefault();\n        this.stencilFunc.setDefault();\n        this.stencilOp.setDefault();\n        this.stencilTest.setDefault();\n        this.depthRange.setDefault();\n        this.depthTest.setDefault();\n        this.depthFunc.setDefault();\n        this.blend.setDefault();\n        this.blendFunc.setDefault();\n        this.blendColor.setDefault();\n        this.blendEquation.setDefault();\n        this.cullFace.setDefault();\n        this.cullFaceSide.setDefault();\n        this.frontFace.setDefault();\n        this.program.setDefault();\n        this.activeTexture.setDefault();\n        this.bindFramebuffer.setDefault();\n        this.pixelStoreUnpack.setDefault();\n        this.pixelStoreUnpackPremultiplyAlpha.setDefault();\n        this.pixelStoreUnpackFlipY.setDefault();\n    }\n\n    setDirty() {\n        this.clearColor.dirty = true;\n        this.clearDepth.dirty = true;\n        this.clearStencil.dirty = true;\n        this.colorMask.dirty = true;\n        this.depthMask.dirty = true;\n        this.stencilMask.dirty = true;\n        this.stencilFunc.dirty = true;\n        this.stencilOp.dirty = true;\n        this.stencilTest.dirty = true;\n        this.depthRange.dirty = true;\n        this.depthTest.dirty = true;\n        this.depthFunc.dirty = true;\n        this.blend.dirty = true;\n        this.blendFunc.dirty = true;\n        this.blendColor.dirty = true;\n        this.blendEquation.dirty = true;\n        this.cullFace.dirty = true;\n        this.cullFaceSide.dirty = true;\n        this.frontFace.dirty = true;\n        this.program.dirty = true;\n        this.activeTexture.dirty = true;\n        this.viewport.dirty = true;\n        this.bindFramebuffer.dirty = true;\n        this.bindRenderbuffer.dirty = true;\n        this.bindTexture.dirty = true;\n        this.bindVertexBuffer.dirty = true;\n        this.bindElementBuffer.dirty = true;\n        this.bindVertexArrayOES.dirty = true;\n        this.pixelStoreUnpack.dirty = true;\n        this.pixelStoreUnpackPremultiplyAlpha.dirty = true;\n        this.pixelStoreUnpackFlipY.dirty = true;\n    }\n\n    createIndexBuffer(\n        array: TriangleIndexArray | LineIndexArray | LineStripIndexArray,\n        dynamicDraw?: boolean,\n        noDestroy?: boolean,\n    ): IndexBuffer {\n        return new IndexBuffer(this, array, dynamicDraw, noDestroy);\n    }\n\n    createVertexBuffer(\n        array: StructArray,\n        attributes: ReadonlyArray<StructArrayMember>,\n        dynamicDraw?: boolean,\n        noDestroy?: boolean,\n        instanceCount?: number,\n    ): VertexBuffer {\n        return new VertexBuffer(this, array, attributes, dynamicDraw, noDestroy, instanceCount);\n    }\n\n    createRenderbuffer(storageFormat: number, width: number, height: number): WebGLRenderbuffer | null | undefined {\n        const gl = this.gl;\n\n        const rbo = gl.createRenderbuffer();\n        this.bindRenderbuffer.set(rbo);\n        gl.renderbufferStorage(gl.RENDERBUFFER, storageFormat, width, height);\n        this.bindRenderbuffer.set(null);\n\n        return rbo;\n    }\n\n    createFramebuffer(\n        width: number,\n        height: number,\n        hasColor: boolean,\n        depthType?: DepthBufferType | null,\n    ): Framebuffer {\n        return new Framebuffer(this, width, height, hasColor, depthType);\n    }\n\n    clear({\n        color,\n        depth,\n        stencil,\n        colorMask,\n    }: ClearArgs) {\n        const gl = this.gl;\n        let mask = 0;\n\n        if (color) {\n            mask |= gl.COLOR_BUFFER_BIT;\n            this.clearColor.set(color);\n            if (colorMask) {\n                this.colorMask.set(colorMask);\n            } else {\n                this.colorMask.set([true, true, true, true]);\n            }\n        }\n\n        if (typeof depth !== 'undefined') {\n            mask |= gl.DEPTH_BUFFER_BIT;\n\n            // Workaround for platforms where clearDepth doesn't seem to work\n            // without reseting the depthRange. See https://github.com/mapbox/mapbox-gl-js/issues/3437\n            this.depthRange.set([0, 1]);\n\n            this.clearDepth.set(depth);\n            this.depthMask.set(true);\n        }\n\n        if (typeof stencil !== 'undefined') {\n            mask |= gl.STENCIL_BUFFER_BIT;\n            this.clearStencil.set(stencil);\n            this.stencilMask.set(0xFF);\n        }\n\n        gl.clear(mask);\n    }\n\n    setCullFace(cullFaceMode: Readonly<CullFaceMode>) {\n        if (cullFaceMode.enable === false) {\n            this.cullFace.set(false);\n        } else {\n            this.cullFace.set(true);\n            this.cullFaceSide.set(cullFaceMode.mode);\n            this.frontFace.set(cullFaceMode.frontFace);\n        }\n    }\n\n    setDepthMode(depthMode: Readonly<DepthMode>) {\n        if (depthMode.func === this.gl.ALWAYS && !depthMode.mask) {\n            this.depthTest.set(false);\n        } else {\n            this.depthTest.set(true);\n            this.depthFunc.set(depthMode.func);\n            this.depthMask.set(depthMode.mask);\n            this.depthRange.set(depthMode.range);\n        }\n    }\n\n    setStencilMode(stencilMode: Readonly<StencilMode>) {\n        if (stencilMode.test.func === this.gl.ALWAYS && !stencilMode.mask) {\n            this.stencilTest.set(false);\n        } else {\n            this.stencilTest.set(true);\n            this.stencilMask.set(stencilMode.mask);\n            this.stencilOp.set([stencilMode.fail, stencilMode.depthFail, stencilMode.pass]);\n            this.stencilFunc.set({\n                func: stencilMode.test.func,\n                ref: stencilMode.ref,\n                mask: stencilMode.test.mask\n            });\n        }\n    }\n\n    setColorMode(colorMode: Readonly<ColorMode>) {\n        if (deepEqual(colorMode.blendFunction, ColorMode.Replace)) {\n            this.blend.set(false);\n        } else {\n            this.blend.set(true);\n            this.blendFunc.set(colorMode.blendFunction);\n            this.blendColor.set(colorMode.blendColor);\n            if (colorMode.blendEquation) {\n                this.blendEquation.set(colorMode.blendEquation);\n            } else {\n                this.blendEquation.setDefault();\n            }\n        }\n\n        this.colorMask.set(colorMode.mask);\n    }\n\n    unbindVAO() {\n        // Unbinding the VAO prevents other things (custom layers, new buffer creation) from\n        // unintentionally changing the state of the last VAO used.\n        this.bindVertexArrayOES.set(null);\n    }\n}\n\nexport default Context;\n","import browser from '../util/browser';\nimport Context from '../gl/context';\nimport {ParticleIndexLayoutArray} from '../data/array_types';\nimport particleAttributes from '../data/particle_attributes';\nimport SegmentVector from '../data/segment';\nimport Texture from './texture';\nimport assert from 'assert';\n\nimport type {OverscaledTileID} from \"../source/tile_id\";\nimport type {TextureImage} from './texture';\nimport type VertexBuffer from '../gl/vertex_buffer';\nimport type {RGBAImage} from \"../util/image\";\n\nclass RasterParticleState {\n    context: Context;\n    particleTexture0: Texture;\n    particleTexture1: Texture;\n    particleIndexBuffer: VertexBuffer;\n    particleSegment: SegmentVector;\n    targetColorTexture: Texture;\n    backgroundColorTexture: Texture;\n    particleTextureDimension: number;\n    lastInvalidatedAt: number;\n\n    constructor(\n        context: Context,\n        id: OverscaledTileID,\n        textureSize: [number, number],\n        RGBAPositions: RGBAImage,\n    ) {\n        const emptyImage: TextureImage = {\n            width: textureSize[0],\n            height: textureSize[1],\n            data: null\n        };\n        const gl = context.gl;\n        this.targetColorTexture = new Texture(context, emptyImage, gl.RGBA, {useMipmap: false});\n        this.backgroundColorTexture = new Texture(context, emptyImage, gl.RGBA, {useMipmap: false});\n        this.context = context;\n\n        this.updateParticleTexture(id, RGBAPositions);\n        this.lastInvalidatedAt = 0;\n    }\n\n    updateParticleTexture(id: OverscaledTileID, RGBAPositions: RGBAImage) {\n        assert(RGBAPositions.width === RGBAPositions.height);\n        if (this.particleTextureDimension === RGBAPositions.width) {\n            return;\n        }\n\n        if (this.particleTexture0 || this.particleTexture1 || this.particleIndexBuffer || this.particleSegment) {\n            assert(this.particleTexture0 && this.particleTexture1 && this.particleIndexBuffer && this.particleSegment);\n            this.particleTexture0.destroy();\n            this.particleTexture1.destroy();\n            this.particleIndexBuffer.destroy();\n            this.particleSegment.destroy();\n        }\n\n        const gl = this.context.gl;\n\n        const numParticles = RGBAPositions.width * RGBAPositions.height;\n\n        this.particleTexture0 = new Texture(this.context, RGBAPositions, gl.RGBA, {premultiply: false, useMipmap: false});\n        this.particleTexture1 = new Texture(this.context, RGBAPositions, gl.RGBA, {premultiply: false, useMipmap: false});\n\n        const particleIndices = new ParticleIndexLayoutArray();\n        particleIndices.reserve(numParticles);\n        for (let i = 0; i < numParticles; i++) {\n            particleIndices.emplaceBack(i);\n        }\n        this.particleIndexBuffer = this.context.createVertexBuffer(particleIndices, particleAttributes.members, true);\n\n        this.particleSegment = SegmentVector.simpleSegment(0, 0, this.particleIndexBuffer.length, 0);\n        this.particleTextureDimension = RGBAPositions.width;\n    }\n\n    update(layerLastInvalidatedAt: number): boolean {\n        if (this.lastInvalidatedAt < layerLastInvalidatedAt) {\n            this.lastInvalidatedAt = browser.now();\n            return false;\n        }\n\n        return true;\n    }\n\n    destroy() {\n        this.targetColorTexture.destroy();\n        this.backgroundColorTexture.destroy();\n        this.particleIndexBuffer.destroy();\n        this.particleTexture0.destroy();\n        this.particleTexture1.destroy();\n        this.particleSegment.destroy();\n    }\n}\n\nexport default RasterParticleState;\n","import {Event, ErrorEvent, Evented} from '../../src/util/evented';\n\nimport Model from '../data/model';\nimport convertModel from '../source/model_loader';\n\nimport {RequestManager} from '../../src/util/mapbox';\nimport {ResourceType} from '../../src/util/ajax';\n\nimport {loadGLTF} from '../util/loaders';\n\nimport type Painter from '../../src/render/painter';\nimport type {ModelsSpecification} from '../../src/style-spec/types';\n\n// Keep the number of references to each model\n// to avoid deleting models in use\ntype ReferencedModel = {\n    model: Model;\n    numReferences: number;\n};\n\nclass ModelManager extends Evented {\n    models: {\n        [scope: string]: {\n            [id: string]: ReferencedModel;\n        };\n    };\n    numModelsLoading: {\n        [scope: string]: number;\n    };\n    requestManager: RequestManager;\n\n    constructor(requestManager: RequestManager) {\n        super();\n        this.requestManager = requestManager;\n        this.models = {'': {}};\n        this.numModelsLoading = {};\n    }\n\n    loadModel(id: string, url: string): Promise<Model | null | undefined> {\n        // @ts-expect-error - TS2345 - Argument of type 'string' is not assignable to parameter of type '\"Unknown\" | \"Style\" | \"Source\" | \"Tile\" | \"Glyphs\" | \"SpriteImage\" | \"SpriteJSON\" | \"Image\" | \"Model\"'.\n        return loadGLTF(this.requestManager.transformRequest(url, ResourceType.Model).url)\n            .then(gltf => {\n                if (!gltf) return;\n\n                const nodes = convertModel(gltf);\n                const model = new Model(id, undefined, undefined, nodes);\n                model.computeBoundsAndApplyParent();\n                return model;\n            })\n            .catch((err) => {\n                if (err && err.status === 404) {\n                    return null;\n                }\n                this.fire(new ErrorEvent(new Error(`Could not load model ${id} from ${url}: ${err.message}`)));\n            });\n    }\n\n    load(modelUris: {\n        [key: string]: string;\n    }, scope: string) {\n        if (!this.models[scope]) this.models[scope] = {};\n\n        const modelIds = Object.keys(modelUris);\n        this.numModelsLoading[scope] = (this.numModelsLoading[scope] || 0) + modelIds.length;\n\n        const modelLoads = [];\n        for (const modelId of modelIds) {\n            modelLoads.push(this.loadModel(modelId, modelUris[modelId]));\n        }\n\n        Promise.allSettled(modelLoads)\n            .then(results => {\n                for (let i = 0; i < results.length; i++) {\n                    // @ts-expect-error - TS2339 - Property 'value' does not exist on type 'PromiseSettledResult<any>'.\n                    const {status, value} = results[i];\n                    if (status === 'fulfilled' && value) {\n                        this.models[scope][modelIds[i]] = {model: value, numReferences : 1};\n                    }\n                }\n                this.numModelsLoading[scope] -= modelIds.length;\n                this.fire(new Event('data', {dataType: 'style'}));\n            })\n            .catch((err) => {\n                this.fire(new ErrorEvent(new Error(`Could not load models: ${err.message}`)));\n            });\n    }\n\n    isLoaded(): boolean {\n        for (const scope in this.numModelsLoading) {\n            if (this.numModelsLoading[scope] > 0) return false;\n        }\n        return true;\n    }\n\n    hasModel(id: string, scope: string): boolean {\n        return !!this.getModel(id, scope);\n    }\n\n    getModel(id: string, scope: string): Model | null | undefined {\n        if (!this.models[scope]) this.models[scope] = {};\n        return this.models[scope][id] ? this.models[scope][id].model : undefined;\n    }\n\n    addModel(id: string, url: string, scope: string) {\n        if (!this.models[scope]) this.models[scope] = {};\n        // update num references if the model exists\n        if (this.hasModel(id, scope)) {\n            this.models[scope][id].numReferences++;\n        }\n        this.load({[id]: this.requestManager.normalizeModelURL(url)}, scope);\n    }\n\n    addModels(models: ModelsSpecification, scope: string) {\n        if (!this.models[scope]) this.models[scope] = {};\n\n        const modelUris: Record<string, any> = {};\n        for (const modelId in models) {\n            // Add a void object so we mark this model as requested\n            // @ts-expect-error - TS2739 - Type '{}' is missing the following properties from type 'ReferencedModel': model, numReferences\n            this.models[scope][modelId] = {};\n            modelUris[modelId] = this.requestManager.normalizeModelURL(models[modelId]);\n        }\n        this.load(modelUris, scope);\n    }\n\n    addModelsFromBucket(modelUris: Array<string>, scope: string) {\n        if (!this.models[scope]) this.models[scope] = {};\n\n        const modelsRequests: Record<string, any> = {};\n        for (const modelUri of modelUris) {\n            if (this.hasModel(modelUri, scope)) {\n                this.models[scope][modelUri].numReferences++;\n            } else {\n                modelsRequests[modelUri] = this.requestManager.normalizeModelURL(modelUri);\n            }\n        }\n        this.load(modelsRequests, scope);\n    }\n\n    removeModel(id: string, scope: string) {\n        if (!this.models[scope] || !this.models[scope][id]) return;\n        this.models[scope][id].numReferences--;\n        if (this.models[scope][id].numReferences === 0) {\n            const model = this.models[scope][id].model;\n            delete this.models[scope][id];\n            model.destroy();\n        }\n    }\n\n    listModels(scope: string): Array<string> {\n        if (!this.models[scope]) this.models[scope] = {};\n        return Object.keys(this.models[scope]);\n    }\n\n    upload(painter: Painter, scope: string) {\n        if (!this.models[scope]) this.models[scope] = {};\n        for (const modelId in this.models[scope]) {\n            if (this.models[scope][modelId].model) {\n                this.models[scope][modelId].model.upload(painter.context);\n            }\n        }\n    }\n}\n\nexport default ModelManager;\n","import {RGBAImage} from '../util/image';\n\nimport type {Map} from '../ui/map';\n\nexport type StyleImageData = {\n    data: RGBAImage;\n    version: number;\n    hasRenderCallback?: boolean;\n    userImage?: StyleImageInterface;\n};\n\nexport type StyleImageMetadata = {\n    pixelRatio: number;\n    sdf: boolean;\n    stretchX?: Array<[number, number]>;\n    stretchY?: Array<[number, number]>;\n    content?: [number, number, number, number];\n};\n\nexport type StyleImage = StyleImageData & StyleImageMetadata;\n\nexport type StyleImageInterface = {\n    width: number;\n    height: number;\n    data: Uint8Array | Uint8ClampedArray;\n    render?: () => boolean;\n    onAdd?: (map: Map, id: string) => void;\n    onRemove?: () => void;\n};\n\nexport function renderStyleImage(image: StyleImage): boolean {\n    const {userImage} = image;\n    if (userImage && userImage.render) {\n        const updated = userImage.render();\n        if (updated) {\n            image.data.replace(new Uint8Array(userImage.data.buffer));\n            return true;\n        }\n    }\n    return false;\n}\n\n/**\n * Interface for dynamically generated style images. This is a specification for\n * implementers to model: it is not an exported method or class.\n *\n * Images implementing this interface can be redrawn for every frame. They can be used to animate\n * icons and patterns or make them respond to user input. Style images can implement a\n * {@link StyleImageInterface#render} method. The method is called every frame and\n * can be used to update the image.\n *\n * @interface StyleImageInterface\n * @property {number} width Width in pixels.\n * @property {number} height Height in pixels.\n * @property {Uint8Array | Uint8ClampedArray} data Byte array representing the image. To ensure space for all four channels in an RGBA color, size must be width × height × 4.\n *\n * @see [Example: Add an animated icon to the map.](https://docs.mapbox.com/mapbox-gl-js/example/add-image-animated/)\n *\n * @example\n * const flashingSquare = {\n *     width: 64,\n *     height: 64,\n *     data: new Uint8Array(64 * 64 * 4),\n *\n *     onAdd(map) {\n *         this.map = map;\n *     },\n *\n *     render() {\n *         // keep repainting while the icon is on the map\n *         this.map.triggerRepaint();\n *\n *         // alternate between black and white based on the time\n *         const value = Math.round(Date.now() / 1000) % 2 === 0  ? 255 : 0;\n *\n *         // check if image needs to be changed\n *         if (value !== this.previousValue) {\n *             this.previousValue = value;\n *\n *             const bytesPerPixel = 4;\n *             for (let x = 0; x < this.width; x++) {\n *                 for (let y = 0; y < this.height; y++) {\n *                     const offset = (y * this.width + x) * bytesPerPixel;\n *                     this.data[offset + 0] = value;\n *                     this.data[offset + 1] = value;\n *                     this.data[offset + 2] = value;\n *                     this.data[offset + 3] = 255;\n *                 }\n *             }\n *\n *             // return true to indicate that the image changed\n *             return true;\n *         }\n *     }\n * };\n *\n * map.addImage('flashing_square', flashingSquare);\n */\n\n/**\n * This method is called once before every frame where the icon will be used.\n * The method can optionally update the image's `data` member with a new image.\n *\n * If the method updates the image it must return `true` to commit the change.\n * If the method returns `false` or nothing the image is assumed to not have changed.\n *\n * If updates are infrequent it maybe easier to use {@link Map#updateImage} to update\n * the image instead of implementing this method.\n *\n * @function\n * @memberof StyleImageInterface\n * @instance\n * @name render\n * @return {boolean} `true` if this method updated the image. `false` if the image was not changed.\n */\n\n/**\n * Optional method called when the layer has been added to the Map with {@link Map#addImage}.\n *\n * @function\n * @memberof StyleImageInterface\n * @instance\n * @name onAdd\n * @param {Map} map The Map this custom layer was just added to.\n */\n\n/**\n * Optional method called when the icon is removed from the map with {@link Map#removeImage}.\n * This gives the image a chance to clean up resources and event listeners.\n *\n * @function\n * @memberof StyleImageInterface\n * @instance\n * @name onRemove\n */\n","import potpack from 'potpack';\n\nimport {Event, ErrorEvent, Evented} from '../util/evented';\nimport {RGBAImage} from '../util/image';\nimport {ImagePosition} from './image_atlas';\nimport Texture from './texture';\nimport assert from 'assert';\nimport {renderStyleImage} from '../style/style_image';\nimport {warnOnce} from '../util/util';\n\nimport type {StyleImage} from '../style/style_image';\nimport type Context from '../gl/context';\nimport type {PotpackBox} from 'potpack';\nimport type {Callback} from '../types/callback';\nimport type {Size} from '../util/image';\nimport type {LUT} from '../util/lut';\n\ntype Pattern = {\n    bin: PotpackBox;\n    position: ImagePosition;\n};\n\n// When copied into the atlas texture, image data is padded by one pixel on each side. Icon\n// images are padded with fully transparent pixels, while pattern images are padded with a\n// copy of the image data wrapped from the opposite side. In both cases, this ensures the\n// correct behavior of GL_LINEAR texture sampling mode.\nconst padding = 1;\n\n/*\n    ImageManager does three things:\n\n        1. Tracks requests for icon images from tile workers and sends responses when the requests are fulfilled.\n        2. Builds a texture atlas for pattern images.\n        3. Rerenders renderable images once per frame\n\n    These are disparate responsibilities and should eventually be handled by different classes. When we implement\n    data-driven support for `*-pattern`, we'll likely use per-bucket pattern atlases, and that would be a good time\n    to refactor this.\n*/\nclass ImageManager extends Evented {\n    images: {\n        [scope: string]: {\n            [id: string]: StyleImage;\n        };\n    };\n    updatedImages: {\n        [scope: string]: {\n            [id: string]: boolean;\n        };\n    };\n    callbackDispatchedThisFrame: {\n        [scope: string]: {\n            [id: string]: boolean;\n        };\n    };\n    loaded: {\n        [scope: string]: boolean;\n    };\n    requestors: Array<{\n        ids: Array<string>;\n        scope: string;\n        callback: Callback<{\n            [id: string]: StyleImage;\n        }>;\n    }>;\n\n    patterns: {\n        [scope: string]: {\n            [id: string]: Pattern;\n        };\n    };\n    atlasImage: {\n        [scope: string]: RGBAImage;\n    };\n    atlasTexture: {\n        [scope: string]: Texture | null | undefined;\n    };\n    dirty: boolean;\n\n    constructor() {\n        super();\n        this.images = {};\n        this.updatedImages = {};\n        this.callbackDispatchedThisFrame = {};\n        this.loaded = {};\n        this.requestors = [];\n\n        this.patterns = {};\n        this.atlasImage = {};\n        this.atlasTexture = {};\n        this.dirty = true;\n    }\n\n    createScope(scope: string) {\n        this.images[scope] = {};\n        this.loaded[scope] = false;\n        this.updatedImages[scope] = {};\n        this.patterns[scope] = {};\n        this.callbackDispatchedThisFrame[scope] = {};\n        this.atlasImage[scope] = new RGBAImage({width: 1, height: 1});\n    }\n\n    isLoaded(): boolean {\n        for (const scope in this.loaded) {\n            if (!this.loaded[scope]) return false;\n        }\n        return true;\n    }\n\n    setLoaded(loaded: boolean, scope: string) {\n        if (this.loaded[scope] === loaded) {\n            return;\n        }\n\n        this.loaded[scope] = loaded;\n\n        if (loaded) {\n            for (const {ids, callback} of this.requestors) {\n                this._notify(ids, scope, callback);\n            }\n            this.requestors = [];\n        }\n    }\n\n    hasImage(id: string, scope: string): boolean {\n        return !!this.getImage(id, scope);\n    }\n\n    getImage(id: string, scope: string): StyleImage | null | undefined {\n        return this.images[scope][id];\n    }\n\n    addImage(id: string, scope: string, image: StyleImage) {\n        assert(!this.images[scope][id]);\n        if (this._validate(id, image)) {\n            this.images[scope][id] = image;\n        }\n    }\n\n    _validate(id: string, image: StyleImage): boolean {\n        let valid = true;\n        if (!this._validateStretch(image.stretchX, image.data && image.data.width)) {\n            this.fire(new ErrorEvent(new Error(`Image \"${id}\" has invalid \"stretchX\" value`)));\n            valid = false;\n        }\n        if (!this._validateStretch(image.stretchY, image.data && image.data.height)) {\n            this.fire(new ErrorEvent(new Error(`Image \"${id}\" has invalid \"stretchY\" value`)));\n            valid = false;\n        }\n        if (!this._validateContent(image.content, image)) {\n            this.fire(new ErrorEvent(new Error(`Image \"${id}\" has invalid \"content\" value`)));\n            valid = false;\n        }\n        return valid;\n    }\n\n    _validateStretch(\n        stretch: Array<[number, number]> | null | undefined,\n        size: number,\n    ): boolean {\n        if (!stretch) return true;\n        let last = 0;\n        for (const part of stretch) {\n            if (part[0] < last || part[1] < part[0] || size < part[1]) return false;\n            last = part[1];\n        }\n        return true;\n    }\n\n    _validateContent(\n        content: [number, number, number, number] | null | undefined,\n        image: StyleImage,\n    ): boolean {\n        if (!content) return true;\n        if (content.length !== 4) return false;\n        if (content[0] < 0 || image.data.width < content[0]) return false;\n        if (content[1] < 0 || image.data.height < content[1]) return false;\n        if (content[2] < 0 || image.data.width < content[2]) return false;\n        if (content[3] < 0 || image.data.height < content[3]) return false;\n        if (content[2] < content[0]) return false;\n        if (content[3] < content[1]) return false;\n        return true;\n    }\n\n    updateImage(id: string, scope: string, image: StyleImage) {\n        const oldImage = this.images[scope][id];\n        assert(oldImage);\n        assert(oldImage.data.width === image.data.width);\n        assert(oldImage.data.height === image.data.height);\n        image.version = oldImage.version + 1;\n        this.images[scope][id] = image;\n        this.updatedImages[scope][id] = true;\n    }\n\n    removeImage(id: string, scope: string) {\n        assert(this.images[scope][id]);\n        const image = this.images[scope][id];\n        delete this.images[scope][id];\n        delete this.patterns[scope][id];\n\n        if (image.userImage && image.userImage.onRemove) {\n            image.userImage.onRemove();\n        }\n    }\n\n    listImages(scope: string): Array<string> {\n        return Object.keys(this.images[scope]);\n    }\n\n    getImages(ids: Array<string>, scope: string, callback: Callback<{\n        [_: string]: StyleImage;\n    }>) {\n        // If the sprite has been loaded, or if all the icon dependencies are already present\n        // (i.e. if they've been added via runtime styling), then notify the requestor immediately.\n        // Otherwise, delay notification until the sprite is loaded. At that point, if any of the\n        // dependencies are still unavailable, we'll just assume they are permanently missing.\n        let hasAllDependencies = true;\n        const isLoaded = !!this.loaded[scope];\n        if (!isLoaded) {\n            for (const id of ids) {\n                if (!this.images[scope][id]) {\n                    hasAllDependencies = false;\n                }\n            }\n        }\n        if (isLoaded || hasAllDependencies) {\n            this._notify(ids, scope, callback);\n        } else {\n            this.requestors.push({ids, scope, callback});\n        }\n    }\n\n    getUpdatedImages(scope: string): {\n        [_: string]: boolean;\n    } {\n        return this.updatedImages[scope];\n    }\n\n    _notify(ids: Array<string>, scope: string, callback: Callback<{\n        [_: string]: StyleImage;\n    }>) {\n        const response: Record<string, any> = {};\n\n        for (const id of ids) {\n            if (!this.images[scope][id]) {\n                this.fire(new Event('styleimagemissing', {id}));\n            }\n            const image = this.images[scope][id];\n            if (image) {\n                // Clone the image so that our own copy of its ArrayBuffer doesn't get transferred.\n                response[id] = {\n                    data: image.data.clone(),\n                    pixelRatio: image.pixelRatio,\n                    sdf: image.sdf,\n                    version: image.version,\n                    stretchX: image.stretchX,\n                    stretchY: image.stretchY,\n                    content: image.content,\n                    hasRenderCallback: Boolean(image.userImage && image.userImage.render)\n                };\n            } else {\n                warnOnce(`Image \"${id}\" could not be loaded. Please make sure you have added the image with map.addImage() or a \"sprite\" property in your style. You can provide missing images by listening for the \"styleimagemissing\" map event.`);\n            }\n        }\n\n        callback(null, response);\n    }\n\n    // Pattern stuff\n\n    getPixelSize(scope: string): Size {\n        const {width, height} = this.atlasImage[scope];\n        return {width, height};\n    }\n\n    getPattern(id: string, scope: string, lut: LUT | null): ImagePosition | null | undefined {\n        const pattern = this.patterns[scope][id];\n\n        const image = this.getImage(id, scope);\n        if (!image) {\n            return null;\n        }\n\n        if (pattern && pattern.position.version === image.version) {\n            return pattern.position;\n        }\n\n        if (!pattern) {\n            const w = image.data.width + padding * 2;\n            const h = image.data.height + padding * 2;\n            const bin = {w, h, x: 0, y: 0};\n            const position = new ImagePosition(bin, image);\n            this.patterns[scope][id] = {bin, position};\n        } else {\n            pattern.position.version = image.version;\n        }\n\n        this._updatePatternAtlas(scope, lut);\n\n        return this.patterns[scope][id].position;\n    }\n\n    bind(context: Context, scope: string) {\n        const gl = context.gl;\n        let atlasTexture = this.atlasTexture[scope];\n\n        if (!atlasTexture) {\n            atlasTexture = new Texture(context, this.atlasImage[scope], gl.RGBA);\n            this.atlasTexture[scope] = atlasTexture;\n        } else if (this.dirty) {\n            atlasTexture.update(this.atlasImage[scope]);\n            this.dirty = false;\n        }\n\n        atlasTexture.bind(gl.LINEAR, gl.CLAMP_TO_EDGE);\n    }\n\n    _updatePatternAtlas(scope: string, lut: LUT | null) {\n        const bins = [];\n        for (const id in this.patterns[scope]) {\n            bins.push(this.patterns[scope][id].bin);\n        }\n\n        const {w, h} = potpack(bins);\n\n        const dst = this.atlasImage[scope];\n        dst.resize({width: w || 1, height: h || 1});\n\n        for (const id in this.patterns[scope]) {\n            const {bin} = this.patterns[scope][id];\n            const x = bin.x + padding;\n            const y = bin.y + padding;\n            const src = this.images[scope][id].data;\n            const w = src.width;\n            const h = src.height;\n\n            RGBAImage.copy(src, dst, {x: 0, y: 0}, {x, y}, {width: w, height: h}, lut);\n\n            // Add 1 pixel wrapped padding on each side of the image.\n            RGBAImage.copy(src, dst, {x: 0, y: h - 1}, {x, y: y - 1}, {width: w, height: 1}, lut); // T\n            RGBAImage.copy(src, dst, {x: 0, y:     0}, {x, y: y + h}, {width: w, height: 1}, lut); // B\n            RGBAImage.copy(src, dst, {x: w - 1, y: 0}, {x: x - 1, y}, {width: 1, height: h}, lut); // L\n            RGBAImage.copy(src, dst, {x: 0,     y: 0}, {x: x + w, y}, {width: 1, height: h}, lut); // R\n        }\n\n        this.dirty = true;\n    }\n\n    beginFrame() {\n        for (const scope in this.images) {\n            this.callbackDispatchedThisFrame[scope] = {};\n        }\n    }\n\n    dispatchRenderCallbacks(ids: Array<string>, scope: string) {\n        for (const id of ids) {\n            // the callback for the image was already dispatched for a different frame\n            if (this.callbackDispatchedThisFrame[scope][id]) continue;\n            this.callbackDispatchedThisFrame[scope][id] = true;\n\n            const image = this.images[scope][id];\n            assert(image);\n\n            const updated = renderStyleImage(image);\n            if (updated) {\n                this.updateImage(id, scope, image);\n            }\n        }\n    }\n}\n\nexport default ImageManager;\n","import {default as ValidationError, ValidationWarning} from '../error/validation_error';\nimport getType from '../util/get_type';\nimport validateSpec from './validate';\n\nimport type {ValidationOptions} from './validate';\n\ntype Options = ValidationOptions & {\n    objectElementValidators?: any;\n};\n\nexport default function validateObject(options: Options): Array<ValidationError> {\n    const key = options.key;\n    const object = options.value;\n    const elementSpecs = options.valueSpec || {};\n    const elementValidators = options.objectElementValidators || {};\n    const style = options.style;\n    const styleSpec = options.styleSpec;\n    let errors = [];\n\n    const type = getType(object);\n    if (type !== 'object') {\n        return [new ValidationError(key, object, `object expected, ${type} found`)];\n    }\n\n    for (const objectKey in object) {\n        const elementSpecKey = objectKey.split('.')[0]; // treat 'paint.*' as 'paint'\n        const elementSpec = elementSpecs[elementSpecKey] || elementSpecs['*'];\n\n        let validateElement;\n        if (elementValidators[elementSpecKey]) {\n            validateElement = elementValidators[elementSpecKey];\n        } else if (elementSpecs[elementSpecKey]) {\n            validateElement = validateSpec;\n        } else if (elementValidators['*']) {\n            validateElement = elementValidators['*'];\n        } else if (elementSpecs['*']) {\n            validateElement = validateSpec;\n        }\n\n        if (!validateElement) {\n            errors.push(new ValidationWarning(key, object[objectKey], `unknown property \"${objectKey}\"`));\n            continue;\n        }\n\n        errors = errors.concat(validateElement({\n            key: (key ? `${key}.` : key) + objectKey,\n            value: object[objectKey],\n            valueSpec: elementSpec,\n            style,\n            styleSpec,\n            object,\n            objectKey\n        }, object));\n    }\n\n    for (const elementSpecKey in elementSpecs) {\n        // Don't check `required` when there's a custom validator for that property.\n        if (elementValidators[elementSpecKey]) {\n            continue;\n        }\n\n        if (elementSpecs[elementSpecKey].required && elementSpecs[elementSpecKey]['default'] === undefined && object[elementSpecKey] === undefined) {\n            errors.push(new ValidationError(key, object, `missing required property \"${elementSpecKey}\"`));\n        }\n    }\n\n    return errors;\n}\n","import getType from '../util/get_type';\nimport validate from './validate';\nimport ValidationError from '../error/validation_error';\n\nimport type {ValidationOptions} from './validate';\n\ntype Options = ValidationOptions & {\n    arrayElementValidator: any;\n};\n\nexport default function validateArray(options: Options): Array<ValidationError> {\n    const array = options.value;\n    const arraySpec = options.valueSpec;\n    const style = options.style;\n    const styleSpec = options.styleSpec;\n    const key = options.key;\n    const validateArrayElement = options.arrayElementValidator || validate;\n\n    if (getType(array) !== 'array') {\n        return [new ValidationError(key, array, `array expected, ${getType(array)} found`)];\n    }\n\n    if (arraySpec.length && array.length !== arraySpec.length) {\n        return [new ValidationError(key, array, `array length ${arraySpec.length} expected, length ${array.length} found`)];\n    }\n\n    if (arraySpec['min-length'] && array.length < arraySpec['min-length']) {\n        return [new ValidationError(key, array, `array length at least ${arraySpec['min-length']} expected, length ${array.length} found`)];\n    }\n\n    let arrayElementSpec = {\n        \"type\": arraySpec.value,\n        \"values\": arraySpec.values,\n        \"minimum\": arraySpec.minimum,\n        \"maximum\": arraySpec.maximum,\n        function: undefined\n    };\n\n    if (styleSpec.$version < 7) {\n        arrayElementSpec.function = arraySpec.function;\n    }\n\n    if (getType(arraySpec.value) === 'object') {\n        arrayElementSpec = arraySpec.value;\n    }\n\n    let errors = [];\n    for (let i = 0; i < array.length; i++) {\n        errors = errors.concat(validateArrayElement({\n            array,\n            arrayIndex: i,\n            value: array[i],\n            valueSpec: arrayElementSpec,\n            style,\n            styleSpec,\n            key: `${key}[${i}]`\n        }, true));\n    }\n    return errors;\n}\n","import getType from '../util/get_type';\nimport ValidationError from '../error/validation_error';\n\nimport type {ValidationOptions} from './validate';\n\ntype Options = ValidationOptions & {\n    arrayIndex: number;\n};\n\nexport default function validateNumber(options: Options): Array<ValidationError> {\n    const key = options.key;\n    const value = options.value;\n    const valueSpec = options.valueSpec;\n    let type = getType(value);\n\n    // eslint-disable-next-line no-self-compare\n    if (type === 'number' && value !== value) {\n        type = 'NaN';\n    }\n\n    if (type !== 'number') {\n        return [new ValidationError(key, value, `number expected, ${type} found`)];\n    }\n\n    if ('minimum' in valueSpec) {\n        let specMin = valueSpec.minimum;\n        if (getType(valueSpec.minimum) === 'array') {\n            const i = options.arrayIndex;\n            specMin = valueSpec.minimum[i];\n        }\n        if (value < specMin) {\n            return [new ValidationError(key, value, `${value} is less than the minimum value ${specMin}`)];\n        }\n    }\n\n    if ('maximum' in valueSpec) {\n        let specMax = valueSpec.maximum;\n        if (getType(valueSpec.maximum) === 'array') {\n            const i = options.arrayIndex;\n            specMax = valueSpec.maximum[i];\n        }\n        if (value > specMax) {\n            return [new ValidationError(key, value, `${value} is greater than the maximum value ${specMax}`)];\n        }\n    }\n\n    return [];\n}\n","import ValidationError from '../error/validation_error';\nimport getType from '../util/get_type';\nimport validate from './validate';\nimport validateObject from './validate_object';\nimport validateArray from './validate_array';\nimport validateNumber from './validate_number';\nimport {isExpression} from '../expression/index';\nimport {unbundle, deepUnbundle} from '../util/unbundle_jsonlint';\nimport {\n    supportsPropertyExpression,\n    supportsZoomExpression,\n    supportsInterpolation\n} from '../util/properties';\n\nimport type {ValidationOptions} from './validate';\n\nexport default function validateFunction(options: ValidationOptions): any {\n    const functionValueSpec = options.valueSpec;\n    const functionType = unbundle(options.value.type);\n    let stopKeyType;\n    let stopDomainValues: Partial<Record<string | number, boolean>> = {};\n    let previousStopDomainValue: unknown | null | undefined;\n    let previousStopDomainZoom;\n\n    const isZoomFunction = functionType !== 'categorical' && options.value.property === undefined;\n    const isPropertyFunction = !isZoomFunction;\n    const isZoomAndPropertyFunction =\n        getType(options.value.stops) === 'array' &&\n        getType(options.value.stops[0]) === 'array' &&\n        getType(options.value.stops[0][0]) === 'object';\n\n    const errors = validateObject({\n        key: options.key,\n        value: options.value,\n        valueSpec: options.styleSpec.function,\n        style: options.style,\n        styleSpec: options.styleSpec,\n        objectElementValidators: {\n            stops: validateFunctionStops,\n            default: validateFunctionDefault\n        }\n    });\n\n    if (functionType === 'identity' && isZoomFunction) {\n        errors.push(new ValidationError(options.key, options.value, 'missing required property \"property\"'));\n    }\n\n    if (functionType !== 'identity' && !options.value.stops) {\n        errors.push(new ValidationError(options.key, options.value, 'missing required property \"stops\"'));\n    }\n\n    if (functionType === 'exponential' && options.valueSpec.expression && !supportsInterpolation(options.valueSpec)) {\n        errors.push(new ValidationError(options.key, options.value, 'exponential functions not supported'));\n    }\n\n    if (options.styleSpec.$version >= 8) {\n        if (isPropertyFunction && !supportsPropertyExpression(options.valueSpec)) {\n            errors.push(new ValidationError(options.key, options.value, 'property functions not supported'));\n        } else if (isZoomFunction && !supportsZoomExpression(options.valueSpec)) {\n            errors.push(new ValidationError(options.key, options.value, 'zoom functions not supported'));\n        }\n    }\n\n    if ((functionType === 'categorical' || isZoomAndPropertyFunction) && options.value.property === undefined) {\n        errors.push(new ValidationError(options.key, options.value, '\"property\" property is required'));\n    }\n\n    return errors;\n\n    function validateFunctionStops(options: ValidationOptions) {\n        if (functionType === 'identity') {\n            return [new ValidationError(options.key, options.value, 'identity function may not have a \"stops\" property')];\n        }\n\n        let errors = [];\n        const value = options.value;\n\n        errors = errors.concat(validateArray({\n            key: options.key,\n            value,\n            valueSpec: options.valueSpec,\n            style: options.style,\n            styleSpec: options.styleSpec,\