n        if (this.vao) {\n            this.context.gl.deleteVertexArray(this.vao);\n            this.vao = null;\n        }\n    }\n}\n\nexport default VertexArrayObject;\n","import {mat4} from 'gl-matrix';\n\nimport {\n    Uniform1i,\n    Uniform1f,\n    Uniform2f,\n    UniformColor,\n    UniformMatrix4f\n} from '../uniform_binding';\nimport EXTENT from '../../style-spec/data/extent';\nimport MercatorCoordinate from '../../geo/mercator_coordinate';\nimport {cartesianPositionToSpherical, degToRad} from '../../../src/util/util';\n\nimport type Context from '../../gl/context';\nimport type {UniformValues} from '../uniform_binding';\nimport type Tile from '../../source/tile';\nimport type Painter from '../painter';\nimport type HillshadeStyleLayer from '../../style/style_layer/hillshade_style_layer';\nimport type DEMData from '../../data/dem_data';\nimport type {OverscaledTileID} from '../../source/tile_id';\n\nexport type HillshadeUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n    ['u_image']: Uniform1i;\n    ['u_latrange']: Uniform2f;\n    ['u_light']: Uniform2f;\n    ['u_shadow']: UniformColor;\n    ['u_highlight']: UniformColor;\n    ['u_emissive_strength']: Uniform1f;\n    ['u_accent']: UniformColor;\n};\n\nexport type HillshadePrepareUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n    ['u_image']: Uniform1i;\n    ['u_dimension']: Uniform2f;\n    ['u_zoom']: Uniform1f;\n};\n\nexport type HillshadeDefinesType = 'TERRAIN_DEM_FLOAT_FORMAT';\n\nconst hillshadeUniforms = (context: Context): HillshadeUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context),\n    'u_image': new Uniform1i(context),\n    'u_latrange': new Uniform2f(context),\n    'u_light': new Uniform2f(context),\n    'u_shadow': new UniformColor(context),\n    'u_highlight': new UniformColor(context),\n    'u_emissive_strength': new Uniform1f(context),\n    'u_accent': new UniformColor(context)\n});\n\nconst hillshadePrepareUniforms = (context: Context): HillshadePrepareUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context),\n    'u_image': new Uniform1i(context),\n    'u_dimension': new Uniform2f(context),\n    'u_zoom': new Uniform1f(context)\n});\n\nconst hillshadeUniformValues = (\n    painter: Painter,\n    tile: Tile,\n    layer: HillshadeStyleLayer,\n    matrix?: Float32Array | null,\n): UniformValues<HillshadeUniformsType> => {\n    const shadow = layer.paint.get(\"hillshade-shadow-color\");\n    const highlight = layer.paint.get(\"hillshade-highlight-color\");\n    const accent = layer.paint.get(\"hillshade-accent-color\");\n    const emissiveStrength = layer.paint.get(\"hillshade-emissive-strength\");\n\n    let azimuthal = degToRad(layer.paint.get('hillshade-illumination-direction'));\n    // modify azimuthal angle by map rotation if light is anchored at the viewport\n    if (layer.paint.get('hillshade-illumination-anchor') === 'viewport') {\n        azimuthal -= painter.transform.angle;\n    } else if (painter.style && painter.style.enable3dLights()) {\n        // hillshade-illumination-anchor = map & 3d lights enabled\n        if (painter.style.directionalLight) {\n            const direction = painter.style.directionalLight.properties.get('direction');\n\n            const spherical = cartesianPositionToSpherical(direction.x, direction.y, direction.z);\n            azimuthal = degToRad(spherical[1]);\n        }\n    }\n    const align = !painter.options.moving;\n    return {\n        'u_matrix': matrix ? matrix : painter.transform.calculateProjMatrix(tile.tileID.toUnwrapped(), align),\n        'u_image': 0,\n        'u_latrange': getTileLatRange(painter, tile.tileID),\n        'u_light': [layer.paint.get('hillshade-exaggeration'), azimuthal],\n\n        'u_shadow': shadow.toRenderColor(layer.lut),\n\n        'u_highlight': highlight.toRenderColor(layer.lut),\n        'u_emissive_strength': emissiveStrength,\n\n        'u_accent': accent.toRenderColor(layer.lut)\n    };\n};\n\nconst hillshadeUniformPrepareValues = (tileID: OverscaledTileID, dem: DEMData): UniformValues<HillshadePrepareUniformsType> => {\n\n    const stride = dem.stride;\n    const matrix = mat4.create() as Float32Array;\n    // Flip rendering at y axis.\n    mat4.ortho(matrix, 0, EXTENT, -EXTENT, 0, 0, 1);\n    mat4.translate(matrix, matrix, [0, -EXTENT, 0]);\n\n    return {\n        'u_matrix': matrix,\n        'u_image': 1,\n        'u_dimension': [stride, stride],\n        'u_zoom': tileID.overscaledZ\n    };\n};\n\nfunction getTileLatRange(painter: Painter, tileID: OverscaledTileID): [number, number] {\n    // for scaling the magnitude of a points slope by its latitude\n    const tilesAtZoom = Math.pow(2, tileID.canonical.z);\n    const y = tileID.canonical.y;\n    return [\n        new MercatorCoordinate(0, y / tilesAtZoom).toLngLat().lat,\n        new MercatorCoordinate(0, (y + 1) / tilesAtZoom).toLngLat().lat];\n}\n\nexport {\n    hillshadeUniforms,\n    hillshadePrepareUniforms,\n    hillshadeUniformValues,\n    hillshadeUniformPrepareValues\n};\n","import Texture from './texture';\nimport StencilMode from '../gl/stencil_mode';\nimport DepthMode from '../gl/depth_mode';\nimport CullFaceMode from '../gl/cull_face_mode';\nimport {\n    hillshadeUniformValues,\n    hillshadeUniformPrepareValues\n} from './program/hillshade_program';\n\nimport type Painter from './painter';\nimport type SourceCache from '../source/source_cache';\nimport type Tile from '../source/tile';\nimport type HillshadeStyleLayer from '../style/style_layer/hillshade_style_layer';\nimport ColorMode from '../gl/color_mode';\nimport type {OverscaledTileID} from '../source/tile_id';\nimport assert from 'assert';\nimport DEMData from '../data/dem_data';\nimport type {DynamicDefinesType} from './program/program_uniforms';\n\nexport default drawHillshade;\n\nfunction drawHillshade(painter: Painter, sourceCache: SourceCache, layer: HillshadeStyleLayer, tileIDs: Array<OverscaledTileID>) {\n    if (painter.renderPass !== 'offscreen' && painter.renderPass !== 'translucent') return;\n    if (painter.style.disableElevatedTerrain) return;\n\n    const context = painter.context;\n\n    // When rendering to texture, coordinates are already sorted: primary by\n    // proxy id and secondary sort is by Z.\n    const renderingToTexture = painter.terrain && painter.terrain.renderingToTexture;\n    const [stencilModes, coords] = painter.renderPass === 'translucent' && !renderingToTexture ?\n        painter.stencilConfigForOverlap(tileIDs) : [{}, tileIDs];\n\n    for (const coord of coords) {\n        const tile = sourceCache.getTile(coord);\n        if (tile.needsHillshadePrepare && painter.renderPass === 'offscreen') {\n            prepareHillshade(painter, tile, layer);\n        } else if (painter.renderPass === 'translucent') {\n            const depthMode = painter.depthModeForSublayer(0, DepthMode.ReadOnly);\n            const emissiveStrength = layer.paint.get('hillshade-emissive-strength');\n\n            const colorMode = painter.colorModeForDrapableLayerRenderPass(emissiveStrength);\n            const stencilMode = renderingToTexture && painter.terrain ?\n                painter.terrain.stencilModeForRTTOverlap(coord) : stencilModes[coord.overscaledZ];\n            renderHillshade(painter, coord, tile, layer, depthMode, stencilMode, colorMode);\n        }\n    }\n\n    context.viewport.set([0, 0, painter.width, painter.height]);\n\n    painter.resetStencilClippingMasks();\n}\n\nfunction renderHillshade(painter: Painter, coord: OverscaledTileID, tile: Tile, layer: HillshadeStyleLayer, depthMode: DepthMode, stencilMode: StencilMode, colorMode: ColorMode) {\n    const context = painter.context;\n    const gl = context.gl;\n    const fbo = tile.hillshadeFBO;\n    if (!fbo) return;\n    painter.prepareDrawTile();\n\n    const affectedByFog = painter.isTileAffectedByFog(coord);\n    const program = painter.getOrCreateProgram('hillshade', {overrideFog: affectedByFog});\n\n    context.activeTexture.set(gl.TEXTURE0);\n    gl.bindTexture(gl.TEXTURE_2D, fbo.colorAttachment.get());\n\n    const uniformValues = hillshadeUniformValues(painter, tile, layer, painter.terrain ? coord.projMatrix : null);\n\n    painter.uploadCommonUniforms(context, program, coord.toUnwrapped());\n\n    const {tileBoundsBuffer, tileBoundsIndexBuffer, tileBoundsSegments} = painter.getTileBoundsBuffers(tile);\n\n    // @ts-expect-error - TS2554 - Expected 12-16 arguments, but got 11.\n    program.draw(painter, gl.TRIANGLES, depthMode, stencilMode, colorMode, CullFaceMode.disabled,\n        uniformValues, layer.id, tileBoundsBuffer,\n        tileBoundsIndexBuffer, tileBoundsSegments);\n}\n\nexport function prepareDEMTexture(painter: Painter, tile: Tile, dem: DEMData) {\n    if (!tile.needsDEMTextureUpload) return;\n\n    const context = painter.context;\n    const gl = context.gl;\n\n    context.pixelStoreUnpackPremultiplyAlpha.set(false);\n    const textureStride = dem.stride;\n    tile.demTexture = tile.demTexture || painter.getTileTexture(textureStride);\n    const demImage = dem.getPixels();\n\n    // Dem encoding should match painters expectations about floating point DEM usage\n    if (tile.demTexture) {\n        tile.demTexture.update(demImage, {premultiply: false});\n    } else {\n        tile.demTexture = new Texture(context, demImage, gl.R32F, {premultiply: false});\n    }\n    tile.needsDEMTextureUpload = false;\n}\n\n// hillshade rendering is done in two steps. the prepare step first calculates the slope of the terrain in the x and y\n// directions for each pixel, and saves those values to a framebuffer texture in the r and g channels.\nfunction prepareHillshade(painter: Painter, tile: Tile, layer: HillshadeStyleLayer) {\n    const context = painter.context;\n    const gl = context.gl;\n    if (!tile.dem) return;\n    const dem: DEMData = tile.dem;\n\n    context.activeTexture.set(gl.TEXTURE1);\n    prepareDEMTexture(painter, tile, dem);\n    assert(tile.demTexture);\n    if (!tile.demTexture) return; // Silence flow.\n    tile.demTexture.bind(gl.NEAREST, gl.CLAMP_TO_EDGE);\n    const tileSize = dem.dim;\n\n    context.activeTexture.set(gl.TEXTURE0);\n    let fbo = tile.hillshadeFBO;\n    if (!fbo) {\n        const renderTexture = new Texture(context, {width: tileSize, height: tileSize, data: null}, gl.RGBA);\n        renderTexture.bind(gl.LINEAR, gl.CLAMP_TO_EDGE);\n\n        fbo = tile.hillshadeFBO = context.createFramebuffer(tileSize, tileSize, true, 'renderbuffer');\n        fbo.colorAttachment.set(renderTexture.texture);\n    }\n\n    context.bindFramebuffer.set(fbo.framebuffer);\n    context.viewport.set([0, 0, tileSize, tileSize]);\n\n    const {tileBoundsBuffer, tileBoundsIndexBuffer, tileBoundsSegments} = painter.getMercatorTileBoundsBuffers();\n\n    const definesValues: DynamicDefinesType[] = [];\n    if (painter.linearFloatFilteringSupported()) definesValues.push('TERRAIN_DEM_FLOAT_FORMAT');\n\n    // @ts-expect-error - TS2554 - Expected 12-16 arguments, but got 11.\n    painter.getOrCreateProgram('hillshadePrepare', {defines: definesValues}).draw(painter, gl.TRIANGLES,\n        DepthMode.disabled, StencilMode.disabled, ColorMode.unblended, CullFaceMode.disabled,\n        hillshadeUniformPrepareValues(tile.tileID, dem),\n        layer.id, tileBoundsBuffer,\n        tileBoundsIndexBuffer, tileBoundsSegments);\n\n    tile.needsHillshadePrepare = false;\n}\n","import {pick, extend} from '../util/util';\n\nimport {getJSON, ResourceType} from '../util/ajax';\nimport browser from '../util/browser';\n\nimport type {RequestManager} from '../util/mapbox';\nimport type {Callback} from '../types/callback';\nimport type {TileJSON} from '../types/tilejson';\nimport type {Cancelable} from '../types/cancelable';\nimport type {SourceSpecification} from '../style-spec/types';\nimport type {SourceVectorLayer, SourceRasterLayer} from './source';\n\ntype ExtendedTileJSON = TileJSON & {\n    vectorLayers?: Array<SourceVectorLayer>;\n    vectorLayerIds?: Array<string>;\n    rasterLayers?: Array<SourceRasterLayer>;\n    rasterLayerIds?: Array<string>;\n};\n\ntype TileJSONLike = {url?: string, tiles?: Array<string>};\ntype Options = Extract<SourceSpecification, TileJSONLike> & TileJSONLike & {\n    data?: TileJSON\n};\n\nfunction getInlinedTileJSON(data?: TileJSON, language?: string, worldview?: string): TileJSON | undefined | null {\n    if (!data) {\n        return null;\n    }\n\n    if (!language && !worldview) {\n        return data;\n    }\n\n    worldview = worldview || data.worldview_default;\n\n    const tileJSONLanguages = Object.values(data.language || {});\n\n    if (tileJSONLanguages.length === 0) {\n        return null;\n    }\n\n    const tileJSONWorldviews = Object.values(data.worldview || {});\n\n    if (tileJSONWorldviews.length === 0) {\n        return null;\n    }\n\n    const isLanguageMatched = tileJSONLanguages.every(lang => lang === language);\n    const isWorldviewMatched = tileJSONWorldviews.every(vw => vw === worldview);\n\n    if (isLanguageMatched && isWorldviewMatched) {\n        return data;\n    }\n\n    // If we don't support this language and worldview in TileJSON\n    // or in the same time some of them is not defined\n    // we can safely use inlined default\n    if (!(language in (data.language_options || {})) && !(worldview in (data.worldview_options || {}))) {\n        // There is exception for empty language or worldview options:\n        // If we don't have any language or worldview options\n        // we should always request TileJSON\n        if (!data.language_options || !data.worldview_options) {\n            return null;\n        }\n\n        return data;\n    }\n\n    return null;\n}\n\nexport default function(\n    options: Options,\n    requestManager: RequestManager,\n    language: string | null | undefined,\n    worldview: string | null | undefined,\n    callback: Callback<ExtendedTileJSON>,\n): Cancelable {\n    const loaded = function(err?: Error | null, tileJSON?: Partial<TileJSON>) {\n        if (err) {\n            return callback(err);\n        } else if (tileJSON) {\n            // Prefer TileJSON tiles, if both URL and tiles options are set\n            if (options.url && tileJSON.tiles && options.tiles) delete options.tiles;\n            // check if we have variants and merge with the original TileJson\n            if (tileJSON.variants) {\n                if (!Array.isArray(tileJSON.variants)) {\n                    return callback(new Error(\"variants must be an array\"));\n                }\n                for (const variant of tileJSON.variants) {\n                    if (variant == null || typeof variant !== 'object' || variant.constructor !== Object) {\n                        return callback(new Error(\"variant must be an object\"));\n                    }\n                    if (!Array.isArray(variant.capabilities)) {\n                        return callback(new Error(\"capabilities must be an array\"));\n                    }\n                    // in this version we only support meshopt, we check there is no more different capabilities\n                    // so future tileJsons with more capabilities won't break existing sdk's\n                    if (variant.capabilities.length === 1 && variant.capabilities[0] === \"meshopt\") {\n                        tileJSON = extend(tileJSON, variant);\n                        break;\n                    }\n                }\n            }\n\n            const result = pick(\n                // explicit source options take precedence over TileJSON\n                extend(tileJSON, options),\n                ['tilejson', 'tiles', 'minzoom', 'maxzoom', 'attribution', 'mapbox_logo', 'bounds', 'scheme', 'tileSize', 'encoding']\n            ) as ExtendedTileJSON;\n\n            if (tileJSON.vector_layers) {\n                result.vectorLayers = tileJSON.vector_layers;\n                result.vectorLayerIds = result.vectorLayers.map((layer) => { return layer.id; });\n            }\n\n            if (tileJSON.raster_layers) {\n                result.rasterLayers = tileJSON.raster_layers;\n                result.rasterLayerIds = result.rasterLayers.map((layer) => { return layer.id; });\n            }\n\n            result.tiles = requestManager.canonicalizeTileset(result, options.url);\n            callback(null, result);\n        }\n    };\n\n    const inlinedTileJSON = getInlinedTileJSON(options.data, language, worldview);\n\n    if (inlinedTileJSON) {\n        return browser.frame(() => loaded(null, inlinedTileJSON));\n    }\n\n    if (options.url) {\n        // @ts-expect-error - TS2345 - Argument of type 'string' is not assignable to parameter of type '\"Unknown\" | \"Style\" | \"Source\" | \"Tile\" | \"Glyphs\" | \"SpriteImage\" | \"SpriteJSON\" | \"Image\" | \"Model\"'.\n        return getJSON(requestManager.transformRequest(requestManager.normalizeSourceURL(options.url, null, language, worldview), ResourceType.Source), loaded);\n    } else {\n        return browser.frame(() => {\n            const {data, ...tileJSON} = options;\n            loaded(null, tileJSON);\n        });\n    }\n}\n","import {LngLatBounds} from '../geo/lng_lat';\nimport {mercatorXfromLng, mercatorYfromLat} from '../geo/mercator_coordinate';\n\nimport type {CanonicalTileID} from './tile_id';\n\nclass TileBounds {\n    bounds: LngLatBounds;\n    minzoom: number;\n    maxzoom: number;\n\n    constructor(bounds: [number, number, number, number], minzoom?: number | null, maxzoom?: number | null) {\n        this.bounds = LngLatBounds.convert(this.validateBounds(bounds));\n        this.minzoom = minzoom || 0;\n        this.maxzoom = maxzoom || 24;\n    }\n\n    validateBounds(bounds: [number, number, number, number]): [number, number, number, number] {\n        // make sure the bounds property contains valid longitude and latitudes\n        if (!Array.isArray(bounds) || bounds.length !== 4) return [-180, -90, 180, 90];\n        return [Math.max(-180, bounds[0]), Math.max(-90, bounds[1]), Math.min(180, bounds[2]), Math.min(90, bounds[3])];\n    }\n\n    contains(tileID: CanonicalTileID): boolean {\n        const worldSize = Math.pow(2, tileID.z);\n        const level = {\n            minX: Math.floor(mercatorXfromLng(this.bounds.getWest()) * worldSize),\n            minY: Math.floor(mercatorYfromLat(this.bounds.getNorth()) * worldSize),\n            maxX: Math.ceil(mercatorXfromLng(this.bounds.getEast()) * worldSize),\n            maxY: Math.ceil(mercatorYfromLat(this.bounds.getSouth()) * worldSize)\n        };\n        const hit = tileID.x >= level.minX && tileID.x < level.maxX && tileID.y >= level.minY && tileID.y < level.maxY;\n        return hit;\n    }\n}\n\nexport default TileBounds;\n","import {extend, pick} from '../util/util';\n\nimport {getImage, ResourceType} from '../util/ajax';\nimport {Event, ErrorEvent, Evented} from '../util/evented';\nimport loadTileJSON from './load_tilejson';\nimport {postTurnstileEvent} from '../util/mapbox';\nimport TileBounds from './tile_bounds';\nimport browser from '../util/browser';\nimport {cacheEntryPossiblyAdded} from '../util/tile_request_cache';\nimport {makeFQID} from '../util/fqid';\n\nimport type {ISource, SourceEvents} from './source';\nimport type {OverscaledTileID} from './tile_id';\nimport type {Map} from '../ui/map';\nimport type Dispatcher from '../util/dispatcher';\nimport type Tile from './tile';\nimport type {Callback} from '../types/callback';\nimport type {Cancelable} from '../types/cancelable';\nimport type {\n    RasterSourceSpecification,\n    RasterDEMSourceSpecification,\n    RasterArraySourceSpecification\n} from '../style-spec/types';\nimport Texture from '../render/texture';\n\n/**\n * A source containing raster tiles.\n * See the [Style Specification](https://docs.mapbox.com/mapbox-gl-js/style-spec/sources/#raster) for detailed documentation of options.\n *\n * @example\n * map.addSource('some id', {\n *     type: 'raster',\n *     url: 'mapbox://mapbox.satellite',\n *     tileSize: 256\n * });\n *\n * @example\n * map.addSource('some id', {\n *     type: 'raster',\n *     tiles: ['https://img.nj.gov/imagerywms/Natural2015?bbox={bbox-epsg-3857}&format=image/png&service=WMS&version=1.1.1&request=GetMap&srs=EPSG:3857&transparent=true&width=256&height=256&layers=Natural2015'],\n *     tileSize: 256\n * });\n *\n * @see [Example: Add a raster tile source](https://docs.mapbox.com/mapbox-gl-js/example/map-tiles/)\n * @see [Example: Add a WMS source](https://docs.mapbox.com/mapbox-gl-js/example/wms/)\n */\nclass RasterTileSource<T extends 'raster' | 'raster-dem' | 'raster-array' = 'raster'> extends Evented<SourceEvents> implements ISource {\n    type: T;\n    id: string;\n    scope: string;\n    minzoom: number;\n    maxzoom: number;\n    url: string;\n    scheme: string;\n    attribution: string | undefined;\n    // eslint-disable-next-line camelcase\n    mapbox_logo: boolean | undefined;\n    tileSize: number;\n    minTileCacheSize: number | null | undefined;\n    maxTileCacheSize: number | null | undefined;\n\n    bounds: [number, number, number, number] | null | undefined;\n    tileBounds: TileBounds;\n    roundZoom: boolean | undefined;\n    reparseOverscaled: boolean | undefined;\n    dispatcher: Dispatcher;\n    map: Map;\n    tiles: Array<string>;\n\n    _loaded: boolean;\n    _options: RasterSourceSpecification | RasterDEMSourceSpecification | RasterArraySourceSpecification;\n    _tileJSONRequest: Cancelable | null | undefined;\n\n    prepare: undefined;\n    afterUpdate: undefined;\n    _clear: undefined;\n\n    constructor(id: string, options: RasterSourceSpecification | RasterDEMSourceSpecification | RasterArraySourceSpecification, dispatcher: Dispatcher, eventedParent: Evented) {\n        super();\n        this.id = id;\n        this.dispatcher = dispatcher;\n        this.setEventedParent(eventedParent);\n\n        this.type = 'raster' as T;\n        this.minzoom = 0;\n        this.maxzoom = 22;\n        this.roundZoom = true;\n        this.scheme = 'xyz';\n        this.tileSize = 512;\n        this._loaded = false;\n\n        this._options = extend({type: 'raster'}, options);\n        extend(this, pick(options, ['url', 'scheme', 'tileSize']));\n    }\n\n    load(callback?: Callback<undefined>) {\n        this._loaded = false;\n        this.fire(new Event('dataloading', {dataType: 'source'}));\n        this._tileJSONRequest = loadTileJSON(this._options, this.map._requestManager, null, null, (err, tileJSON) => {\n            this._tileJSONRequest = null;\n            this._loaded = true;\n            if (err) {\n                this.fire(new ErrorEvent(err));\n            } else if (tileJSON) {\n                extend(this, tileJSON);\n                if (tileJSON.bounds) this.tileBounds = new TileBounds(tileJSON.bounds, this.minzoom, this.maxzoom);\n\n                postTurnstileEvent(tileJSON.tiles);\n\n                // `content` is included here to prevent a race condition where `Style#updateSources` is called\n                // before the TileJSON arrives. this makes sure the tiles needed are loaded once TileJSON arrives\n                // ref: https://github.com/mapbox/mapbox-gl-js/pull/4347#discussion_r104418088\n                this.fire(new Event('data', {dataType: 'source', sourceDataType: 'metadata'}));\n                this.fire(new Event('data', {dataType: 'source', sourceDataType: 'content'}));\n            }\n\n            if (callback) callback(err);\n        });\n    }\n\n    loaded(): boolean {\n        return this._loaded;\n    }\n\n    onAdd(map: Map) {\n        this.map = map;\n        this.load();\n    }\n\n    /**\n     * Reloads the source data and re-renders the map.\n     *\n     * @example\n     * map.getSource('source-id').reload();\n     */\n    reload() {\n        this.cancelTileJSONRequest();\n        const fqid = makeFQID(this.id, this.scope);\n        this.load(() => this.map.style.clearSource(fqid));\n    }\n\n    /**\n     * Sets the source `tiles` property and re-renders the map.\n     *\n     * @param {string[]} tiles An array of one or more tile source URLs, as in the TileJSON spec.\n     * @returns {RasterTileSource} Returns itself to allow for method chaining.\n     * @example\n     * map.addSource('source-id', {\n     *     type: 'raster',\n     *     tiles: ['https://some_end_point.net/{z}/{x}/{y}.png'],\n     *     tileSize: 256\n     * });\n     *\n     * // Set the endpoint associated with a raster tile source.\n     * map.getSource('source-id').setTiles(['https://another_end_point.net/{z}/{x}/{y}.png']);\n     */\n    setTiles(tiles: Array<string>): this {\n        this._options.tiles = tiles;\n        this.reload();\n\n        return this;\n    }\n\n    /**\n     * Sets the source `url` property and re-renders the map.\n     *\n     * @param {string} url A URL to a TileJSON resource. Supported protocols are `http:`, `https:`, and `mapbox://<Tileset ID>`.\n     * @returns {RasterTileSource} Returns itself to allow for method chaining.\n     * @example\n     * map.addSource('source-id', {\n     *     type: 'raster',\n     *     url: 'mapbox://mapbox.satellite'\n     * });\n     *\n     * // Update raster tile source to a new URL endpoint\n     * map.getSource('source-id').setUrl('mapbox://mapbox.satellite');\n     */\n    setUrl(url: string): this {\n        this.url = url;\n        this._options.url = url;\n        this.reload();\n\n        return this;\n    }\n\n    onRemove(_: Map) {\n        this.cancelTileJSONRequest();\n    }\n\n    serialize(): RasterSourceSpecification | RasterDEMSourceSpecification {\n        return extend({}, this._options);\n    }\n\n    hasTile(tileID: OverscaledTileID): boolean {\n        return !this.tileBounds || this.tileBounds.contains(tileID.canonical);\n    }\n\n    loadTile(tile: Tile, callback: Callback<undefined>) {\n        const use2x = browser.devicePixelRatio >= 2;\n        const url = this.map._requestManager.normalizeTileURL(tile.tileID.canonical.url(this.tiles, this.scheme), use2x, this.tileSize);\n        // @ts-expect-error - TS2345 - Argument of type 'string' is not assignable to parameter of type '\"Unknown\" | \"Style\" | \"Source\" | \"Tile\" | \"Glyphs\" | \"SpriteImage\" | \"SpriteJSON\" | \"Image\" | \"Model\"'.\n        tile.request = getImage(this.map._requestManager.transformRequest(url, ResourceType.Tile), (error, data, cacheControl, expires) => {\n            delete tile.request;\n\n            if (tile.aborted) {\n                tile.state = 'unloaded';\n                return callback(null);\n            }\n\n            if (error) {\n                tile.state = 'errored';\n                return callback(error);\n            }\n\n            if (!data) return callback(null);\n\n            if (this.map._refreshExpiredTiles) tile.setExpiryData({cacheControl, expires});\n            tile.setTexture(data, this.map.painter);\n            tile.state = 'loaded';\n\n            cacheEntryPossiblyAdded(this.dispatcher);\n            callback(null);\n        });\n    }\n\n    abortTile(tile: Tile, callback?: Callback<undefined>) {\n        if (tile.request) {\n            tile.request.cancel();\n            delete tile.request;\n        }\n        if (callback) callback();\n    }\n\n    unloadTile(tile: Tile, callback?: Callback<undefined>) {\n        // Cache the tile texture to avoid re-allocating Textures if they'll just be reloaded\n        if (tile.texture && tile.texture instanceof Texture) {\n            // Clean everything else up owned by the tile, but preserve the texture.\n            // Destroy first to prevent racing with the texture cache being popped.\n            tile.destroy(true);\n\n            // Save the texture to the cache\n            if (tile.texture && tile.texture instanceof Texture) {\n                this.map.painter.saveTileTexture(tile.texture);\n            }\n        } else {\n            tile.destroy();\n        }\n\n        if (callback) callback();\n    }\n\n    hasTransition(): boolean {\n        return false;\n    }\n\n    cancelTileJSONRequest() {\n        if (!this._tileJSONRequest) return;\n        this._tileJSONRequest.cancel();\n        this._tileJSONRequest = null;\n    }\n}\n\nexport default RasterTileSource;\n","import {Event, ErrorEvent, Evented} from '../util/evented';\n\nimport {extend, pick} from '../util/util';\nimport loadTileJSON from './load_tilejson';\nimport {postTurnstileEvent} from '../util/mapbox';\nimport TileBounds from './tile_bounds';\nimport {ResourceType} from '../util/ajax';\nimport browser from '../util/browser';\nimport {cacheEntryPossiblyAdded} from '../util/tile_request_cache';\nimport {DedupedRequest, loadVectorTile} from './load_vector_tile';\nimport {makeFQID} from '../util/fqid';\n\nimport type {ISource, SourceEvents} from './source';\nimport type {OverscaledTileID} from './tile_id';\nimport type {Map} from '../ui/map';\nimport type Dispatcher from '../util/dispatcher';\nimport type Tile from './tile';\nimport type {Callback} from '../types/callback';\nimport type {Cancelable} from '../types/cancelable';\nimport type {VectorSourceSpecification, PromoteIdSpecification} from '../style-spec/types';\nimport type Actor from '../util/actor';\nimport type {LoadVectorTileResult} from './load_vector_tile';\nimport type {WorkerTileResult} from './worker_source';\n\n/**\n * A source containing vector tiles in [Mapbox Vector Tile format](https://docs.mapbox.com/vector-tiles/reference/).\n * See the [Style Specification](https://docs.mapbox.com/mapbox-gl-js/style-spec/sources/#vector) for detailed documentation of options.\n *\n * @example\n * map.addSource('some id', {\n *     type: 'vector',\n *     url: 'mapbox://mapbox.mapbox-streets-v8'\n * });\n *\n * @example\n * map.addSource('some id', {\n *     type: 'vector',\n *     tiles: ['https://d25uarhxywzl1j.cloudfront.net/v0.1/{z}/{x}/{y}.mvt'],\n *     minzoom: 6,\n *     maxzoom: 14\n * });\n *\n * @example\n * map.getSource('some id').setUrl(\"mapbox://mapbox.mapbox-streets-v8\");\n *\n * @example\n * map.getSource('some id').setTiles(['https://d25uarhxywzl1j.cloudfront.net/v0.1/{z}/{x}/{y}.mvt']);\n * @see [Example: Add a vector tile source](https://docs.mapbox.com/mapbox-gl-js/example/vector-source/)\n * @see [Example: Add a third party vector tile source](https://docs.mapbox.com/mapbox-gl-js/example/third-party/)\n */\nclass VectorTileSource extends Evented<SourceEvents> implements ISource {\n    type: 'vector';\n    id: string;\n    scope: string;\n    minzoom: number;\n    maxzoom: number;\n    url: string;\n    scheme: string;\n    tileSize: number;\n    minTileCacheSize: number | null | undefined;\n    maxTileCacheSize: number | null | undefined;\n    roundZoom: boolean | undefined;\n    attribution: string | undefined;\n    // eslint-disable-next-line camelcase\n    mapbox_logo: boolean | undefined;\n    promoteId: PromoteIdSpecification | null | undefined;\n\n    _options: VectorSourceSpecification;\n    _collectResourceTiming: boolean;\n    dispatcher: Dispatcher;\n    map: Map;\n    bounds: [number, number, number, number] | null | undefined;\n    tiles: Array<string>;\n    tileBounds: TileBounds;\n    reparseOverscaled: boolean | undefined;\n    isTileClipped: boolean | undefined;\n    _tileJSONRequest: Cancelable | null | undefined;\n    _loaded: boolean;\n    _tileWorkers: {\n        [key: string]: Actor;\n    };\n    _deduped: DedupedRequest;\n    vectorLayerIds: Array<string> | undefined;\n\n    prepare: undefined;\n    _clear: undefined;\n\n    constructor(id: string, options: VectorSourceSpecification & {\n        collectResourceTiming: boolean;\n    }, dispatcher: Dispatcher, eventedParent: Evented) {\n        super();\n        this.id = id;\n        this.dispatcher = dispatcher;\n\n        this.type = 'vector';\n        this.minzoom = 0;\n        this.maxzoom = 22;\n        this.scheme = 'xyz';\n        this.tileSize = 512;\n        this.reparseOverscaled = true;\n        this.isTileClipped = true;\n        this._loaded = false;\n\n        extend(this, pick(options, ['url', 'scheme', 'tileSize', 'promoteId']));\n        this._options = extend({type: 'vector'}, options);\n\n        this._collectResourceTiming = !!options.collectResourceTiming;\n\n        if (this.tileSize !== 512) {\n            throw new Error('vector tile sources must have a tileSize of 512');\n        }\n\n        this.setEventedParent(eventedParent);\n\n        this._tileWorkers = {};\n        this._deduped = new DedupedRequest();\n    }\n\n    load(callback?: Callback<undefined>) {\n        this._loaded = false;\n        this.fire(new Event('dataloading', {dataType: 'source'}));\n        const language = Array.isArray(this.map._language) ? this.map._language.join() : this.map._language;\n        const worldview = this.map._worldview;\n        this._tileJSONRequest = loadTileJSON(this._options, this.map._requestManager, language, worldview, (err, tileJSON) => {\n            this._tileJSONRequest = null;\n            this._loaded = true;\n            if (err) {\n                if (language) console.warn(`Ensure that your requested language string is a valid BCP-47 code or list of codes. Found: ${language}`);\n                if (worldview && worldview.length !== 2) console.warn(`Requested worldview strings must be a valid ISO alpha-2 code. Found: ${worldview}`);\n\n                this.fire(new ErrorEvent(err));\n            } else if (tileJSON) {\n                extend(this, tileJSON);\n                if (tileJSON.bounds) this.tileBounds = new TileBounds(tileJSON.bounds, this.minzoom, this.maxzoom);\n                postTurnstileEvent(tileJSON.tiles, this.map._requestManager._customAccessToken);\n\n                // `content` is included here to prevent a race condition where `Style#updateSources` is called\n                // before the TileJSON arrives. this makes sure the tiles needed are loaded once TileJSON arrives\n                // ref: https://github.com/mapbox/mapbox-gl-js/pull/4347#discussion_r104418088\n                this.fire(new Event('data', {dataType: 'source', sourceDataType: 'metadata'}));\n                this.fire(new Event('data', {dataType: 'source', sourceDataType: 'content'}));\n            }\n\n            if (callback) callback(err);\n        });\n    }\n\n    loaded(): boolean {\n        return this._loaded;\n    }\n\n    hasTile(tileID: OverscaledTileID): boolean {\n        return !this.tileBounds || this.tileBounds.contains(tileID.canonical);\n    }\n\n    onAdd(map: Map) {\n        this.map = map;\n        this.load();\n    }\n\n    /**\n     * Reloads the source data and re-renders the map.\n     *\n     * @example\n     * map.getSource('source-id').reload();\n     */\n    reload() {\n        this.cancelTileJSONRequest();\n        const fqid = makeFQID(this.id, this.scope);\n        this.load(() => this.map.style.clearSource(fqid));\n    }\n\n    /**\n     * Sets the source `tiles` property and re-renders the map.\n     *\n     * @param {string[]} tiles An array of one or more tile source URLs, as in the TileJSON spec.\n     * @returns {VectorTileSource} Returns itself to allow for method chaining.\n     * @example\n     * map.addSource('source-id', {\n     *     type: 'vector',\n     *     tiles: ['https://some_end_point.net/{z}/{x}/{y}.mvt'],\n     *     minzoom: 6,\n     *     maxzoom: 14\n     * });\n     *\n     * // Set the endpoint associated with a vector tile source.\n     * map.getSource('source-id').setTiles(['https://another_end_point.net/{z}/{x}/{y}.mvt']);\n     */\n    setTiles(tiles: Array<string>): this {\n        this._options.tiles = tiles;\n        this.reload();\n\n        return this;\n    }\n\n    /**\n     * Sets the source `url` property and re-renders the map.\n     *\n     * @param {string} url A URL to a TileJSON resource. Supported protocols are `http:`, `https:`, and `mapbox://<Tileset ID>`.\n     * @returns {VectorTileSource} Returns itself to allow for method chaining.\n     * @example\n     * map.addSource('source-id', {\n     *     type: 'vector',\n     *     url: 'mapbox://mapbox.mapbox-streets-v7'\n     * });\n     *\n     * // Update vector tile source to a new URL endpoint\n     * map.getSource('source-id').setUrl(\"mapbox://mapbox.mapbox-streets-v8\");\n     */\n    setUrl(url: string): this {\n        this.url = url;\n        this._options.url = url;\n        this.reload();\n\n        return this;\n    }\n\n    onRemove(_: Map) {\n        this.cancelTileJSONRequest();\n    }\n\n    serialize(): VectorSourceSpecification {\n        return extend({}, this._options);\n    }\n\n    loadTile(tile: Tile, callback: Callback<undefined>) {\n        const url = this.map._requestManager.normalizeTileURL(tile.tileID.canonical.url(this.tiles, this.scheme));\n        // @ts-expect-error - TS2345 - Argument of type 'string' is not assignable to parameter of type '\"Unknown\" | \"Style\" | \"Source\" | \"Tile\" | \"Glyphs\" | \"SpriteImage\" | \"SpriteJSON\" | \"Image\" | \"Model\"'.\n        const request = this.map._requestManager.transformRequest(url, ResourceType.Tile);\n        const lutForScope = this.map.style ? this.map.style.getLut(this.scope) : null;\n        const params = {\n            request,\n            data: undefined,\n            uid: tile.uid,\n            tileID: tile.tileID,\n            tileZoom: tile.tileZoom,\n            zoom: tile.tileID.overscaledZ,\n            lut: lutForScope ? {\n                image: lutForScope.image.clone()\n            } : null,\n            tileSize: this.tileSize * tile.tileID.overscaleFactor(),\n            type: this.type,\n            source: this.id,\n            scope: this.scope,\n            pixelRatio: browser.devicePixelRatio,\n            showCollisionBoxes: this.map.showCollisionBoxes,\n            promoteId: this.promoteId,\n            isSymbolTile: tile.isSymbolTile,\n            brightness: this.map.style ? (this.map.style.getBrightness() || 0.0) : 0.0,\n            extraShadowCaster: tile.isExtraShadowCaster,\n            tessellationStep: this.map._tessellationStep\n        };\n        params.request.collectResourceTiming = this._collectResourceTiming;\n\n        if (!tile.actor || tile.state === 'expired') {\n            tile.actor = this._tileWorkers[url] = this._tileWorkers[url] || this.dispatcher.getActor();\n\n            // if workers are not ready to receive messages yet, use the idle time to preemptively\n            // load tiles on the main thread and pass the result instead of requesting a worker to do so\n            if (!this.dispatcher.ready) {\n                const cancel = loadVectorTile.call({deduped: this._deduped}, params, (err?: Error | null, data?: LoadVectorTileResult | null) => {\n                    if (err || !data) {\n                        done.call(this, err);\n                    } else {\n                        // the worker will skip the network request if the data is already there\n                        params.data = {\n                            cacheControl: data.cacheControl,\n                            expires: data.expires,\n                            rawData: data.rawData.slice(0)\n                        };\n                        if (tile.actor) tile.actor.send('loadTile', params, done.bind(this), undefined, true);\n                    }\n                }, true);\n                tile.request = {cancel};\n\n            } else {\n                tile.request = tile.actor.send('loadTile', params, done.bind(this), undefined, true);\n            }\n\n        } else if (tile.state === 'loading') {\n            // schedule tile reloading after it has been loaded\n            tile.reloadCallback = callback;\n\n        } else {\n            tile.request = tile.actor.send('reloadTile', params, done.bind(this));\n        }\n\n        function done(err?: Error | null, data?: WorkerTileResult | null) {\n            delete tile.request;\n\n            if (tile.aborted)\n                return callback(null);\n\n            // @ts-expect-error - TS2339 - Property 'status' does not exist on type 'Error'.\n            if (err && err.status !== 404) {\n                return callback(err);\n            }\n\n            if (data && data.resourceTiming)\n                tile.resourceTiming = data.resourceTiming;\n\n            if (this.map._refreshExpiredTiles && data) tile.setExpiryData(data);\n            tile.loadVectorData(data, this.map.painter);\n\n            cacheEntryPossiblyAdded(this.dispatcher);\n\n            callback(null);\n\n            if (tile.reloadCallback) {\n                this.loadTile(tile, tile.reloadCallback);\n                tile.reloadCallback = null;\n            }\n        }\n    }\n\n    abortTile(tile: Tile) {\n        if (tile.request) {\n            tile.request.cancel();\n            delete tile.request;\n        }\n        if (tile.actor) {\n            tile.actor.send('abortTile', {uid: tile.uid, type: this.type, source: this.id, scope: this.scope});\n        }\n    }\n\n    unloadTile(tile: Tile, _?: Callback<undefined> | null) {\n        if (tile.actor) {\n            tile.actor.send('removeTile', {uid: tile.uid, type: this.type, source: this.id, scope: this.scope});\n        }\n        tile.destroy();\n    }\n\n    hasTransition(): boolean {\n        return false;\n    }\n\n    afterUpdate() {\n        this._tileWorkers = {};\n    }\n\n    cancelTileJSONRequest() {\n        if (!this._tileJSONRequest) return;\n        this._tileJSONRequest.cancel();\n        this._tileJSONRequest = null;\n    }\n}\n\nexport default VectorTileSource;\n","import {Uniform1i, Uniform1f, Uniform3f, UniformMatrix4f} from '../render/uniform_binding';\n\nimport type Context from '../gl/context';\nimport type {UniformValues} from '../render/uniform_binding';\n\nexport type TerrainRasterUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n    ['u_image0']: Uniform1i;\n    ['u_skirt_height']: Uniform1f;\n    ['u_ground_shadow_factor']: Uniform3f;\n};\n\nconst terrainRasterUniforms = (context: Context): TerrainRasterUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context),\n    'u_image0': new Uniform1i(context),\n    'u_skirt_height': new Uniform1f(context),\n    'u_ground_shadow_factor': new Uniform3f(context)\n});\n\nconst terrainRasterUniformValues = (\n    matrix: Float32Array,\n    skirtHeight: number,\n    groundShadowFactor: [number, number, number],\n): UniformValues<TerrainRasterUniformsType> => ({\n    'u_matrix': matrix,\n    'u_image0': 0,\n    'u_skirt_height': skirtHeight,\n    'u_ground_shadow_factor': groundShadowFactor\n});\n\nexport {terrainRasterUniforms, terrainRasterUniformValues};\n","import {\n    Uniform1i,\n    Uniform2f,\n    Uniform3f,\n    Uniform4f,\n    UniformMatrix4f,\n    Uniform1f,\n    UniformMatrix3f,\n} from '../render/uniform_binding';\n\nimport type Context from '../gl/context';\nimport type {UniformValues} from '../render/uniform_binding';\nimport type {mat4} from 'gl-matrix';\n\nexport type GlobeRasterUniformsType = {\n    ['u_proj_matrix']: UniformMatrix4f;\n    ['u_globe_matrix']: UniformMatrix4f;\n    ['u_normalize_matrix']: UniformMatrix4f;\n    ['u_merc_matrix']: UniformMatrix4f;\n    ['u_zoom_transition']: Uniform1f;\n    ['u_merc_center']: Uniform2f;\n    ['u_image0']: Uniform1i;\n    ['u_grid_matrix']: UniformMatrix3f;\n    ['u_skirt_height']: Uniform1f;\n    ['u_far_z_cutoff']: Uniform1f;\n    ['u_frustum_tl']: Uniform3f;\n    ['u_frustum_tr']: Uniform3f;\n    ['u_frustum_br']: Uniform3f;\n    ['u_frustum_bl']: Uniform3f;\n    ['u_globe_pos']: Uniform3f;\n    ['u_globe_radius']: Uniform1f;\n    ['u_viewport']: Uniform2f;\n};\n\nexport type AtmosphereUniformsType = {\n    ['u_frustum_tl']: Uniform3f;\n    ['u_frustum_tr']: Uniform3f;\n    ['u_frustum_br']: Uniform3f;\n    ['u_frustum_bl']: Uniform3f;\n    ['u_horizon']: Uniform1f;\n    ['u_transition']: Uniform1f;\n    ['u_fadeout_range']: Uniform1f;\n    ['u_color']: Uniform4f;\n    ['u_high_color']: Uniform4f;\n    ['u_space_color']: Uniform4f;\n    ['u_temporal_offset']: Uniform1f;\n    ['u_horizon_angle']: Uniform1f;\n};\n\nconst globeRasterUniforms = (context: Context): GlobeRasterUniformsType => ({\n    'u_proj_matrix': new UniformMatrix4f(context),\n    'u_globe_matrix': new UniformMatrix4f(context),\n    'u_normalize_matrix': new UniformMatrix4f(context),\n    'u_merc_matrix': new UniformMatrix4f(context),\n    'u_zoom_transition': new Uniform1f(context),\n    'u_merc_center': new Uniform2f(context),\n    'u_image0': new Uniform1i(context),\n    'u_grid_matrix': new UniformMatrix3f(context),\n    'u_skirt_height': new Uniform1f(context),\n    'u_far_z_cutoff': new Uniform1f(context),\n    'u_frustum_tl': new Uniform3f(context),\n    'u_frustum_tr': new Uniform3f(context),\n    'u_frustum_br': new Uniform3f(context),\n    'u_frustum_bl': new Uniform3f(context),\n    'u_globe_pos': new Uniform3f(context),\n    'u_globe_radius': new Uniform1f(context),\n    'u_viewport': new Uniform2f(context)\n});\n\nconst atmosphereUniforms = (context: Context): AtmosphereUniformsType => ({\n    'u_frustum_tl': new Uniform3f(context),\n    'u_frustum_tr': new Uniform3f(context),\n    'u_frustum_br': new Uniform3f(context),\n    'u_frustum_bl': new Uniform3f(context),\n    'u_horizon': new Uniform1f(context),\n    'u_transition': new Uniform1f(context),\n    'u_fadeout_range': new Uniform1f(context),\n    'u_color': new Uniform4f(context),\n    'u_high_color': new Uniform4f(context),\n    'u_space_color': new Uniform4f(context),\n    'u_temporal_offset': new Uniform1f(context),\n    'u_horizon_angle': new Uniform1f(context),\n});\n\nconst globeRasterUniformValues = (\n    projMatrix: mat4,\n    globeMatrix: Float32Array,\n    globeMercatorMatrix: Float32Array,\n    normalizeMatrix: Float64Array,\n    zoomTransition: number,\n    mercCenter: [number, number],\n    frustumDirTl: [number, number, number],\n    frustumDirTr: [number, number, number],\n    frustumDirBr: [number, number, number],\n    frustumDirBl: [number, number, number],\n    globePosition: [number, number, number],\n    globeRadius: number,\n    viewport: [number, number],\n    skirtHeight: number,\n    farZCutoff: number,\n    gridMatrix?: mat4 | null,\n): UniformValues<GlobeRasterUniformsType> => ({\n    'u_proj_matrix': Float32Array.from(projMatrix),\n    'u_globe_matrix': globeMatrix,\n    'u_normalize_matrix': Float32Array.from(normalizeMatrix),\n    'u_merc_matrix': globeMercatorMatrix,\n    'u_zoom_transition': zoomTransition,\n    'u_merc_center': mercCenter,\n    'u_image0': 0,\n    'u_frustum_tl': frustumDirTl,\n    'u_frustum_tr': frustumDirTr,\n    'u_frustum_br': frustumDirBr,\n    'u_frustum_bl': frustumDirBl,\n    'u_globe_pos': globePosition,\n    'u_globe_radius': globeRadius,\n    'u_viewport': viewport,\n    'u_grid_matrix': gridMatrix ? Float32Array.from(gridMatrix) : new Float32Array(9),\n    'u_skirt_height': skirtHeight,\n    'u_far_z_cutoff': farZCutoff\n});\n\nconst atmosphereUniformValues = (\n    frustumDirTl: [number, number, number],\n    frustumDirTr: [number, number, number],\n    frustumDirBr: [number, number, number],\n    frustumDirBl: [number, number, number],\n    horizon: number,\n    transitionT: number,\n    fadeoutRange: number,\n    color: [number, number, number, number],\n    highColor: [number, number, number, number],\n    spaceColor: [number, number, number, number],\n    temporalOffset: number,\n    horizonAngle: number,\n): UniformValues<AtmosphereUniformsType> => ({\n    'u_frustum_tl': frustumDirTl,\n    'u_frustum_tr': frustumDirTr,\n    'u_frustum_br': frustumDirBr,\n    'u_frustum_bl': frustumDirBl,\n    'u_horizon': horizon,\n    'u_transition': transitionT,\n    'u_fadeout_range': fadeoutRange,\n    'u_color': color,\n    'u_high_color': highColor,\n    'u_space_color': spaceColor,\n    'u_temporal_offset': temporalOffset,\n    'u_horizon_angle': horizonAngle\n});\n\nexport {globeRasterUniforms, globeRasterUniformValues, atmosphereUniforms, atmosphereUniformValues};\n\nexport type GlobeDefinesType = 'PROJECTION_GLOBE_VIEW' | 'GLOBE_POLES' | 'CUSTOM_ANTIALIASING' | 'ALPHA_PASS';\n","import Point from \"@mapbox/point-geometry\";\n\nimport {clamp} from '../util/util';\nimport {number} from '../style-spec/util/interpolate';\n\n/**\n * @private\n * An `EdgeInset` object represents screen space padding applied to the edges of the viewport.\n * This shifts the apparent center or the vanishing point of the map. This is useful for adding floating UI elements\n * on top of the map and having the vanishing point shift as UI elements resize.\n *\n * @param {number} [top=0]\n * @param {number} [bottom=0]\n * @param {number} [left=0]\n * @param {number} [right=0]\n */\nclass EdgeInsets {\n    top: number;\n    bottom: number;\n    left: number;\n    right: number;\n\n    constructor(top: number = 0, bottom: number = 0, left: number = 0, right: number = 0) {\n        if (isNaN(top) || top < 0 ||\n            isNaN(bottom) || bottom < 0 ||\n            isNaN(left) || left < 0 ||\n            isNaN(right) || right < 0\n        ) {\n            throw new Error('Invalid value for edge-insets, top, bottom, left and right must all be numbers');\n        }\n\n        this.top = top;\n        this.bottom = bottom;\n        this.left = left;\n        this.right = right;\n    }\n\n    /**\n     * Interpolates the inset in-place.\n     * This maintains the current inset value for any inset not present in `target`.\n     *\n     * @private\n     * @param {PaddingOptions | EdgeInsets} start The initial padding options.\n     * @param {PaddingOptions} target The target padding options.\n     * @param {number} t The interpolation variable.\n     * @returns {EdgeInsets} The interpolated edge insets.\n     * @memberof EdgeInsets\n     */\n    interpolate(start: PaddingOptions | EdgeInsets, target: PaddingOptions, t: number): EdgeInsets {\n        if (target.top != null && start.top != null) this.top = number(start.top, target.top, t);\n        if (target.bottom != null && start.bottom != null) this.bottom = number(start.bottom, target.bottom, t);\n        if (target.left != null && start.left != null) this.left = number(start.left, target.left, t);\n        if (target.right != null && start.right != null) this.right = number(start.right, target.right, t);\n\n        return this;\n    }\n\n    /**\n     * Utility method that computes the new apprent center or vanishing point after applying insets.\n     * This is in pixels and with the top left being (0.0) and +y being downwards.\n     *\n     * @private\n     * @param {number} width The width of the map in pixels.\n     * @param {number} height The height of the map in pixels.\n     * @returns {Point} The apparent center or vanishing point of the map.\n     * @memberof EdgeInsets\n     */\n    getCenter(width: number, height: number): Point {\n        // Clamp insets so they never overflow width/height and always calculate a valid center\n        const x = clamp((this.left + width - this.right) / 2, 0, width);\n        const y = clamp((this.top + height - this.bottom) / 2, 0, height);\n\n        return new Point(x, y);\n    }\n\n    equals(other: PaddingOptions): boolean {\n        return this.top === other.top &&\n            this.bottom === other.bottom &&\n            this.left === other.left &&\n            this.right === other.right;\n    }\n\n    clone(): EdgeInsets {\n        return new EdgeInsets(this.top, this.bottom, this.left, this.right);\n    }\n\n    /**\n     * Returns the current state as json, useful when you want to have a\n     * read-only representation of the inset.\n     *\n     * @private\n     * @returns {PaddingOptions} The current padding options.\n     * @memberof EdgeInsets\n     */\n    toJSON(): PaddingOptions {\n        return {\n            top: this.top,\n            bottom: this.bottom,\n            left: this.left,\n            right: this.right\n        };\n    }\n}\n\nexport type PaddingOptions = {\n    readonly top?: number;\n    readonly bottom?: number;\n    readonly right?: number;\n    readonly left?: number;\n};\n\nexport default EdgeInsets;\n","import MercatorCoordinate, {mercatorZfromAltitude, latFromMercatorY} from '../geo/mercator_coordinate';\nimport {degToRad, wrap, getColumn, setColumn} from '../util/util';\nimport {vec3, quat, mat4} from 'gl-matrix';\n\nimport type {Elevation} from '../terrain/elevation';\nimport type {LngLatLike} from '../geo/lng_lat';\nimport type {vec4} from 'gl-matrix';\n\nfunction updateTransformOrientation(matrix: mat4, orientation: quat) {\n    // Take temporary copy of position to prevent it from being overwritten\n    const position: vec4 = getColumn(matrix, 3);\n\n    // Convert quaternion to rotation matrix\n    mat4.fromQuat(matrix, orientation);\n    setColumn(matrix, 3, position);\n}\n\nfunction updateTransformPosition(matrix: mat4, position: vec3) {\n    setColumn(matrix, 3, [position[0], position[1], position[2], 1.0]);\n}\n\nfunction orientationFromPitchBearing(pitch: number, bearing: number): quat {\n    // Both angles are considered to define CW rotation around their respective axes.\n    // Values have to be negated to achieve the proper quaternion in left handed coordinate space\n    const orientation = quat.identity([] as any);\n    quat.rotateZ(orientation, orientation, -bearing);\n    quat.rotateX(orientation, orientation, -pitch);\n    return orientation;\n}\n\nexport function orientationFromFrame(forward: vec3, up: vec3): quat | null | undefined {\n    // Find right-vector of the resulting coordinate frame. Up-vector has to be\n    // sanitized first in order to remove the roll component from the orientation\n    const xyForward = [forward[0], forward[1], 0];\n    const xyUp = [up[0], up[1], 0];\n\n    const epsilon = 1e-15;\n\n    if (vec3.length(xyForward as [number, number, number]) >= epsilon) {\n        // Roll rotation can be seen as the right vector not being on the xy-plane, ie. right[2] != 0.0.\n        // It can be negated by projecting the up vector on top of the forward vector.\n        const xyDir = vec3.normalize([] as any, xyForward as [number, number, number]);\n        vec3.scale(xyUp as [number, number, number], xyDir, vec3.dot(xyUp as [number, number, number], xyDir));\n\n        up[0] = xyUp[0];\n        up[1] = xyUp[1];\n    }\n\n    const right = vec3.cross([] as any, up, forward);\n    if (vec3.len(right) < epsilon) {\n        return null;\n    }\n\n    const bearing = Math.atan2(-right[1], right[0]);\n    const pitch = Math.atan2(Math.sqrt(forward[0] * forward[0] + forward[1] * forward[1]), -forward[2]);\n\n    return orientationFromPitchBearing(pitch, bearing);\n}\n\n/**\n * Options for accessing physical properties of the underlying camera entity.\n * Direct access to these properties allows more flexible and precise controlling of the camera.\n * These options are also fully compatible and interchangeable with CameraOptions. All fields are optional.\n * See {@link Map#setFreeCameraOptions} and {@link Map#getFreeCameraOptions}.\n *\n * @param {MercatorCoordinate} position Position of the camera in slightly modified web mercator coordinates.\n        - The size of 1 unit is the width of the projected world instead of the \"mercator meter\".\n          Coordinate [0, 0, 0] is the north-west corner and [1, 1, 0] is the south-east corner.\n        - Z coordinate is conformal and must respect minimum and maximum zoom values.\n        - Zoom is automatically computed from the altitude (z).\n * @param {quat} orientation Orientation of the camera represented as a unit quaternion [x, y, z, w] in a left-handed coordinate space.\n        Direction of the rotation is clockwise around the respective axis.\n        The default pose of the camera is such that the forward vector is looking up the -Z axis.\n        The up vector is aligned with north orientation of the map:\n          forward: [0, 0, -1]\n          up:      [0, -1, 0]\n          right    [1, 0, 0]\n        Orientation can be set freely but certain constraints still apply:\n         - Orientation must be representable with only pitch and bearing.\n         - Pitch has an upper limit\n * @example\n * const camera = map.getFreeCameraOptions();\n *\n * const position = [138.72649, 35.33974];\n * const altitude = 3000;\n *\n * camera.position = mapboxgl.MercatorCoordinate.fromLngLat(position, altitude);\n * camera.lookAtPoint([138.73036, 35.36197]);\n *\n * map.setFreeCameraOptions(camera);\n * @see [Example: Animate the camera around a point in 3D terrain](https://docs.mapbox.com/mapbox-gl-js/example/free-camera-point/)\n * @see [Example: Animate the camera along a path](https://docs.mapbox.com/mapbox-gl-js/example/free-camera-path/)\n*/\nclass FreeCameraOptions {\n    orientation: quat | null | undefined;\n    _position: MercatorCoordinate | null | undefined;\n    _elevation: Elevation | null | undefined;\n    _renderWorldCopies: boolean;\n\n    constructor(position?: MercatorCoordinate | null, orientation?: quat | null) {\n        this.position = position;\n        this.orientation = orientation;\n    }\n\n    get position(): MercatorCoordinate | null | undefined {\n        return this._position;\n    }\n\n    set position(position: MercatorCoordinate | null | undefined | vec3) {\n        if (!position) {\n            this._position = null;\n        } else {\n            const mercatorCoordinate = position instanceof MercatorCoordinate ? position : new MercatorCoordinate(position[0], position[1], position[2]);\n            if (this._renderWorldCopies) {\n                mercatorCoordinate.x = wrap(mercatorCoordinate.x, 0, 1);\n            }\n            this._position = mercatorCoordinate;\n        }\n    }\n\n    /**\n     * Helper function for setting orientation of the camera by defining a focus point\n     * on the map.\n     *\n     * @param {LngLatLike} location Location of the focus point on the map.\n     * @param {vec3?} up Up vector of the camera is necessary in certain scenarios where bearing can't be deduced\n     *      from the viewing direction.\n     * @example\n     * const camera = map.getFreeCameraOptions();\n     *\n     * const position = [138.72649, 35.33974];\n     * const altitude = 3000;\n     *\n     * camera.position = mapboxgl.MercatorCoordinate.fromLngLat(position, altitude);\n     * camera.lookAtPoint([138.73036, 35.36197]);\n     * // Apply camera changes\n     * map.setFreeCameraOptions(camera);\n     */\n    lookAtPoint(location: LngLatLike, up?: vec3) {\n        this.orientation = null;\n        if (!this.position) {\n            return;\n        }\n\n        const pos: MercatorCoordinate = this.position;\n        const altitude = this._elevation ? this._elevation.getAtPointOrZero(MercatorCoordinate.fromLngLat(location)) : 0;\n        const target = MercatorCoordinate.fromLngLat(location, altitude);\n        const forward = [target.x - pos.x, target.y - pos.y, target.z - pos.z];\n        if (!up)\n            up = [0, 0, 1];\n\n        // flip z-component if the up vector is pointing downwards\n        up[2] = Math.abs(up[2]);\n\n        // @ts-expect-error - TS2345 - Argument of type 'number[]' is not assignable to parameter of type 'vec3'.\n        this.orientation = orientationFromFrame(forward, up);\n    }\n\n    /**\n     * Helper function for setting the orientation of the camera as a pitch and a bearing.\n     *\n     * @param {number} pitch Pitch angle in degrees.\n     * @param {number} bearing Bearing angle in degrees.\n     * @example\n     * const camera = map.getFreeCameraOptions();\n     *\n     * // Update camera pitch and bearing\n     * camera.setPitchBearing(80, 90);\n     * // Apply changes\n     * map.setFreeCameraOptions(camera);\n     */\n    setPitchBearing(pitch: number, bearing: number) {\n        this.orientation = orientationFromPitchBearing(degToRad(pitch), degToRad(-bearing));\n    }\n}\n\n/**\n * While using the free camera API the outcome value of isZooming, isMoving and isRotating\n * is not a result of the free camera API.\n * If the user sets the map.interactive to true, there will be conflicting behaviors while\n * interacting with map via zooming or moving using mouse or/and keyboard which will result\n * in isZooming, isMoving and isRotating to return true while using free camera API. In order\n * to prevent the confilicting behavior please set map.interactive to false which will result\n * in muting the following events: zoom, zoomend, zoomstart, rotate, rotateend, rotatestart,\n * move, moveend, movestart, pitch, pitchend, pitchstart.\n */\n\nclass FreeCamera {\n    _transform: mat4;\n    _orientation: quat;\n\n    constructor(position?: vec3 | null, orientation?: quat | null) {\n        this._transform = mat4.identity([] as any);\n        this.orientation = orientation;\n        this.position = position;\n    }\n\n    get mercatorPosition(): MercatorCoordinate {\n        const pos = this.position;\n        return new MercatorCoordinate(pos[0], pos[1], pos[2]);\n    }\n\n    get position(): vec3 {\n        const col: vec4 = getColumn(this._transform, 3);\n        return [col[0], col[1], col[2]];\n    }\n\n    set position(value: vec3 | null | undefined) {\n        if (value) {\n            updateTransformPosition(this._transform, value);\n        }\n    }\n\n    get orientation(): quat {\n        return this._orientation;\n    }\n\n    set orientation(value: quat | null | undefined) {\n        this._orientation = value || quat.identity([] as any);\n        if (value) {\n            updateTransformOrientation(this._transform, this._orientation);\n        }\n    }\n\n    getPitchBearing(): {\n        pitch: number;\n        bearing: number;\n        } {\n        const f = this.forward();\n        const r = this.right();\n\n        return {\n            bearing: Math.atan2(-r[1], r[0]),\n            pitch: Math.atan2(Math.sqrt(f[0] * f[0] + f[1] * f[1]), -f[2])\n        };\n    }\n\n    setP