mValues(\n                // @ts-expect-error - TS2345 - Argument of type 'number[] | Float32Array | Float64Array' is not assignable to parameter of type 'mat4'.\n                tr.expandedFarZProjMatrix, globeMatrix, globeMercatorMatrix, normalizeMatrix, globeToMercatorTransition(tr.zoom),\n                mercatorCenter, tr.frustumCorners.TL, tr.frustumCorners.TR, tr.frustumCorners.BR,\n                tr.frustumCorners.BL, tr.globeCenterInViewSpace, tr.globeRadius, viewport, skirtHeightValue, tr._farZ, gridMatrix);\n\n            setShaderMode(coord, shaderMode);\n            if (!program) {\n                continue;\n            }\n\n            terrain.setupElevationDraw(tile, program, elevationOptions);\n\n            painter.uploadCommonUniforms(context, program, coord.toUnwrapped());\n\n            if (sharedBuffers) {\n                const [buffer, indexBuffer, segments] = sharedBuffers.getGridBuffers(latitudinalLod, skirtHeightValue !== 0);\n\n                program.draw(painter, primitive, depthMode, stencilMode, colorMode, CullFaceMode.backCCW,\n                    uniformValues, \"globe_raster\", buffer, indexBuffer, segments);\n            }\n        }\n    }\n\n    // Render the poles.\n    if (sharedBuffers && (painter.renderDefaultNorthPole || painter.renderDefaultSouthPole)) {\n        const defines = ['GLOBE_POLES', 'PROJECTION_GLOBE_VIEW'];\n        if (useCustomAntialiasing) defines.push('CUSTOM_ANTIALIASING');\n\n        // @ts-expect-error - TS2322 - Type 'string[]' is not assignable to type 'DynamicDefinesType[]'.\n        program = painter.getOrCreateProgram('globeRaster', {defines});\n        for (const coord of tileIDs) {\n            // Fill poles by extrapolating adjacent border tiles\n            const {x, y, z} = coord.canonical;\n            const topCap = y === 0;\n            const bottomCap = y === (1 << z) - 1;\n\n            const [northPoleBuffer, southPoleBuffer, indexBuffer, segment] = sharedBuffers.getPoleBuffers(z, false);\n\n            if (segment && (topCap || bottomCap)) {\n                const tile = sourceCache.getTile(coord);\n\n                // Bind the main draped texture\n                context.activeTexture.set(gl.TEXTURE0);\n                if (tile.texture) {\n                    tile.texture.bind(gl.LINEAR, gl.CLAMP_TO_EDGE);\n                }\n\n                let poleMatrix = globePoleMatrixForTile(z, x, tr);\n                const normalizeMatrix = globeNormalizeECEF(globeTileBounds(coord.canonical));\n\n                // @ts-expect-error - TS2554 - Expected 12-16 arguments, but got 11.\n                const drawPole = (program: Program<any>, vertexBuffer: VertexBuffer) => program.draw(\n                    painter, gl.TRIANGLES, depthMode, StencilMode.disabled, colorMode, CullFaceMode.disabled,\n                    // @ts-expect-error - TS2345 - Argument of type 'number[] | Float32Array | Float64Array' is not assignable to parameter of type 'mat4'.\n                    globeRasterUniformValues(tr.expandedFarZProjMatrix, poleMatrix, poleMatrix, normalizeMatrix, 0.0, mercatorCenter,\n                    tr.frustumCorners.TL, tr.frustumCorners.TR, tr.frustumCorners.BR, tr.frustumCorners.BL,\n                    tr.globeCenterInViewSpace, tr.globeRadius, viewport, 0, tr._farZ), \"globe_pole_raster\", vertexBuffer,\n                    indexBuffer, segment);\n\n                terrain.setupElevationDraw(tile, program, elevationOptions);\n\n                painter.uploadCommonUniforms(context, program, coord.toUnwrapped());\n\n                if (topCap && painter.renderDefaultNorthPole) {\n                    drawPole(program, northPoleBuffer);\n                }\n                if (bottomCap && painter.renderDefaultSouthPole) {\n                    // @ts-expect-error - TS2322 - Type 'mat4' is not assignable to type 'Float32Array'.\n                    poleMatrix = mat4.scale(mat4.create(), poleMatrix, [1, -1, 1]);\n                    drawPole(program, southPoleBuffer);\n                }\n            }\n        }\n    }\n}\n\nfunction drawTerrainRaster(painter: Painter, terrain: Terrain, sourceCache: SourceCache, tileIDs: Array<OverscaledTileID>, now: number) {\n    if (painter.transform.projection.name === 'globe') {\n        drawTerrainForGlobe(painter, terrain, sourceCache, tileIDs, now);\n    } else {\n        const context = painter.context;\n        const gl = context.gl;\n\n        let program, programMode;\n        const shadowRenderer = painter.shadowRenderer;\n        const cutoffParams = getCutoffParams(painter, painter.longestCutoffRange);\n\n        const setShaderMode = (mode: number) => {\n            if (programMode === mode)\n                return;\n            const modes = ([] as any);\n            modes.push(shaderDefines[mode]);\n            if (cutoffParams.shouldRenderCutoff) {\n                modes.push('RENDER_CUTOFF');\n            }\n            program = painter.getOrCreateProgram('terrainRaster', {defines: modes});\n            programMode = mode;\n        };\n\n        const colorMode = painter.colorModeForRenderPass();\n        const depthMode = new DepthMode(gl.LEQUAL, DepthMode.ReadWrite, painter.depthRangeFor3D);\n        vertexMorphing.update(now);\n        const tr = painter.transform;\n        const skirt = skirtHeight(tr.zoom, terrain.exaggeration(), terrain.sourceCache._source.tileSize);\n\n        let groundShadowFactor: [number, number, number] = [0, 0, 0];\n        if (shadowRenderer) {\n            const directionalLight = painter.style.directionalLight;\n            const ambientLight = painter.style.ambientLight;\n            if (directionalLight && ambientLight) {\n                groundShadowFactor = calculateGroundShadowFactor(painter.style, directionalLight, ambientLight);\n            }\n        }\n\n        {\n            programMode = -1;\n\n            const primitive = gl.TRIANGLES;\n            const [buffer, segments] = [terrain.gridIndexBuffer, terrain.gridSegments];\n\n            for (const coord of tileIDs) {\n                const tile = sourceCache.getTile(coord);\n                const stencilMode = StencilMode.disabled;\n\n                const prevDemTile = terrain.prevTerrainTileForTile[coord.key];\n                const nextDemTile = terrain.terrainTileForTile[coord.key];\n\n                if (demTileChanged(prevDemTile, nextDemTile)) {\n                    vertexMorphing.newMorphing(coord.key, prevDemTile, nextDemTile, now, defaultDuration);\n                }\n\n                // Bind the main draped texture\n                context.activeTexture.set(gl.TEXTURE0);\n                if (tile.texture) {\n                    tile.texture.bind(gl.LINEAR, gl.CLAMP_TO_EDGE);\n                }\n\n                const morph = vertexMorphing.getMorphValuesForProxy(coord.key);\n                const shaderMode = morph ? SHADER_MORPHING : SHADER_DEFAULT;\n                let elevationOptions;\n\n                if (morph) {\n                    elevationOptions = {morphing: {srcDemTile: morph.from, dstDemTile: morph.to, phase: easeCubicInOut(morph.phase)}};\n                }\n\n                const uniformValues = terrainRasterUniformValues(coord.projMatrix, isEdgeTile(coord.canonical, tr.renderWorldCopies) ? skirt / 10 : skirt, groundShadowFactor);\n                setShaderMode(shaderMode);\n                if (!program) {\n                    continue;\n                }\n\n                terrain.setupElevationDraw(tile, program, elevationOptions);\n\n                const unwrappedId = coord.toUnwrapped();\n\n                if (shadowRenderer) {\n                    shadowRenderer.setupShadows(unwrappedId, program);\n                }\n\n                painter.uploadCommonUniforms(context, program, unwrappedId, null, cutoffParams);\n\n                program.draw(painter, primitive, depthMode, stencilMode, colorMode, CullFaceMode.backCCW,\n                    uniformValues, \"terrain_raster\", terrain.gridBuffer, buffer, segments);\n            }\n        }\n    }\n}\n\nfunction skirtHeight(zoom: number, terrainExaggeration: number, tileSize: number) {\n    // Skirt height calculation is heuristic: provided value hides\n    // seams between tiles and it is not too large: 9 at zoom 22, ~20000m at zoom 0.\n    if (terrainExaggeration === 0) return 0;\n    const exaggerationFactor = (terrainExaggeration < 1.0 && tileSize === 514) ? 0.25 / terrainExaggeration : 1.0;\n    return 6 * Math.pow(1.5, 22 - zoom) * Math.max(terrainExaggeration, 1.0) * exaggerationFactor;\n}\n\nfunction isEdgeTile(cid: CanonicalTileID, renderWorldCopies: boolean): boolean {\n    const numTiles = 1 << cid.z;\n    return (!renderWorldCopies && (cid.x === 0 || cid.x === numTiles - 1)) || cid.y === 0 || cid.y === numTiles - 1;\n}\n\nexport {\n    VertexMorphing\n};\n","import {UniformMatrix4f} from '../uniform_binding';\n\nimport type Context from '../../gl/context';\nimport type {UniformValues} from '../uniform_binding';\n\nexport type ClippingMaskUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n};\n\nconst clippingMaskUniforms = (context: Context): ClippingMaskUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context)\n});\n\nconst clippingMaskUniformValues = (matrix: Float32Array): UniformValues<ClippingMaskUniformsType> => ({\n    'u_matrix': matrix\n});\n\nexport {clippingMaskUniforms, clippingMaskUniformValues};\n","import type SourceCache from '../source/source_cache';\nimport {clamp} from '../util/util';\nimport browser from '../util/browser';\nimport Tile from '../source/tile';\nimport type Transform from '../geo/transform';\n\nexport type RasterFade = {\n    opacity: number;\n    mix: number;\n};\n\nfunction rasterFade(\n    tile: Tile,\n    parentTile: Tile | null | undefined,\n    sourceCache: SourceCache,\n    transform: Transform,\n    fadeDuration: number,\n): RasterFade {\n    if (fadeDuration > 0) {\n        const now = browser.now();\n        const sinceTile = (now - tile.timeAdded) / fadeDuration;\n        const sinceParent = parentTile ? (now - parentTile.timeAdded) / fadeDuration : -1;\n\n        const source = sourceCache.getSource();\n        const idealZ = transform.coveringZoomLevel({\n            tileSize: source.tileSize,\n            roundZoom: source.roundZoom\n        });\n\n        // if no parent or parent is older, fade in; if parent is younger, fade out\n        const fadeIn = !parentTile || Math.abs(parentTile.tileID.overscaledZ - idealZ) > Math.abs(tile.tileID.overscaledZ - idealZ);\n\n        const childOpacity = (fadeIn && tile.refreshedUponExpiration) ? 1 : clamp(fadeIn ? sinceTile : 1 - sinceParent, 0, 1);\n\n        // we don't crossfade tiles that were just refreshed upon expiring:\n        // once they're old enough to pass the crossfading threshold\n        // (fadeDuration), unset the `refreshedUponExpiration` flag so we don't\n        // incorrectly fail to crossfade them when zooming\n        if (tile.refreshedUponExpiration && sinceTile >= 1) tile.refreshedUponExpiration = false;\n\n        if (parentTile) {\n            return {\n                opacity: 1,\n                mix: 1 - childOpacity\n            };\n        } else {\n            return {\n                opacity: childOpacity,\n                mix: 0\n            };\n        }\n    } else {\n        return {\n            opacity: 1,\n            mix: 0\n        };\n    }\n}\n\nexport default rasterFade;\n","import Texture from '../render/texture';\nimport RasterTileSource from './raster_tile_source';\nimport {extend} from '../util/util';\nimport {ResourceType} from '../util/ajax';\nimport {Evented, ErrorEvent} from '../util/evented';\nimport RasterStyleLayer from '../style/style_layer/raster_style_layer';\nimport RasterParticleStyleLayer from '../style/style_layer/raster_particle_style_layer';\n\n// Import MRTData as a module with side effects to ensure\n// it's registered as a serializable class on the main thread\nimport '../data/mrt_data';\n\nimport type Tile from './tile';\nimport type {Map} from '../ui/map';\nimport type Dispatcher from '../util/dispatcher';\nimport type RasterArrayTile from './raster_array_tile';\nimport type {Callback} from '../types/callback';\nimport type {TextureDescriptor} from './raster_array_tile';\nimport type {ISource, SourceRasterLayer} from './source';\nimport type {RasterArraySourceSpecification} from '../style-spec/types';\n\n/**\n * A data source containing raster-array tiles created with [Mapbox Tiling Service](https://docs.mapbox.com/mapbox-tiling-service/guides/).\n * See the [Style Specification](https://docs.mapbox.com/style-spec/reference/sources/#raster-array) for detailed documentation of options.\n *\n * @example\n * // add to map\n * map.addSource('some id', {\n *     type: 'raster-array',\n *     url: 'mapbox://rasterarrayexamples.gfs-winds',\n *     tileSize: 512\n * });\n *\n * @see [Example: Create a wind particle animation](https://docs.mapbox.com/mapbox-gl-js/example/raster-particle-layer/)\n */\nclass RasterArrayTileSource extends RasterTileSource<'raster-array'> implements ISource {\n    type: 'raster-array';\n    map: Map;\n    rasterLayers: Array<SourceRasterLayer> | undefined;\n    rasterLayerIds: Array<string> | undefined;\n\n    constructor(id: string, options: RasterArraySourceSpecification, dispatcher: Dispatcher, eventedParent: Evented) {\n        super(id, options, dispatcher, eventedParent);\n        this.type = 'raster-array';\n        this.maxzoom = 22;\n        this._options = extend({type: 'raster-array'}, options);\n    }\n\n    triggerRepaint(tile: RasterArrayTile) {\n        const terrain = this.map.painter._terrain;\n        const sourceCache = this.map.style.getSourceCache(this.id);\n        if (terrain && terrain.enabled && sourceCache) {\n            terrain._clearRenderCacheForTile(sourceCache.id, tile.tileID);\n        }\n\n        // eslint-disable-next-line no-warning-comments\n        // TODO: trigger repaint only if all tiles have the requested band\n        this.map.triggerRepaint();\n    }\n\n    loadTile(tile: Tile, callback: Callback<undefined>) {\n        tile = (tile as RasterArrayTile);\n\n        const url = this.map._requestManager.normalizeTileURL(tile.tileID.canonical.url(this.tiles, this.scheme), false, this.tileSize);\n        // @ts-expect-error - TS2345 - Argument of type 'string' is not assignable to parameter of type '\"Unknown\" | \"Style\" | \"Source\" | \"Tile\" | \"Glyphs\" | \"SpriteImage\" | \"SpriteJSON\" | \"Image\" | \"Model\"'.\n        const requestParams = this.map._requestManager.transformRequest(url, ResourceType.Tile);\n\n        // @ts-expect-error - TS2339 - Property 'requestParams' does not exist on type 'Tile'.\n        tile.requestParams = requestParams;\n        if (!tile.actor) tile.actor = this.dispatcher.getActor();\n\n        // @ts-expect-error - TS2339 - Property 'fetchHeader' does not exist on type 'Tile'.\n        tile.request = tile.fetchHeader(undefined, (error?: Error | null, dataBuffer?: ArrayBuffer | null, cacheControl?: string | null, expires?: string | null) => {\n            delete tile.request;\n\n            if (tile.aborted) {\n                tile.state = 'unloaded';\n                return callback(null);\n            }\n\n            if (error) {\n                // silence AbortError\n                // @ts-expect-error - TS2339 - Property 'code' does not exist on type 'Error'.\n                if (error.code === 20)\n                    return;\n                tile.state = 'errored';\n                return callback(error);\n            }\n\n            if (this.map._refreshExpiredTiles) tile.setExpiryData({cacheControl, expires});\n\n            tile.state = 'empty';\n            callback(null);\n        });\n    }\n\n    unloadTile(tile: Tile, _?: Callback<undefined> | null) {\n        tile = (tile as RasterArrayTile);\n\n        const texture = tile.texture;\n        if (texture && texture instanceof Texture) {\n            // Clean everything else up owned by the tile, but preserve the texture.\n            // Destroy first to prevent racing with the texture cache being popped.\n            tile.destroy(true);\n\n            // Save the texture to the cache\n            this.map.painter.saveTileTexture(texture);\n        } else {\n            tile.destroy();\n\n            // @ts-expect-error - TS2339 - Property 'flushQueues' does not exist on type 'Tile'.\n            tile.flushQueues();\n            // @ts-expect-error - TS2339 - Property '_isHeaderLoaded' does not exist on type 'Tile'.\n            tile._isHeaderLoaded = false;\n\n            // @ts-expect-error - TS2339 - Property '_mrt' does not exist on type 'Tile'.\n            delete tile._mrt;\n            // @ts-expect-error - TS2339 - Property 'textureDescriptor' does not exist on type 'Tile'.\n            delete tile.textureDescriptor;\n        }\n\n        // @ts-expect-error - TS2339 - Property 'fbo' does not exist on type 'Tile'.\n        if (tile.fbo) {\n            // @ts-expect-error - TS2339 - Property 'fbo' does not exist on type 'Tile'.\n            tile.fbo.destroy();\n            // @ts-expect-error - TS2339 - Property 'fbo' does not exist on type 'Tile'.\n            delete tile.fbo;\n        }\n\n        delete tile.request;\n        // @ts-expect-error - TS2339 - Property 'requestParams' does not exist on type 'Tile'.\n        delete tile.requestParams;\n\n        delete tile.neighboringTiles;\n        tile.state = 'unloaded';\n    }\n\n    /**\n     * Prepare RasterArrayTile for the rendering. If tile doesn't have data\n     * for the requested band, fetch and repaint once it's acquired.\n     * @private\n     */\n    prepareTile(tile: RasterArrayTile, sourceLayer: string, band: string | number) {\n        // Skip if tile is not yet loaded or if no update is needed\n        if (!tile._isHeaderLoaded) return;\n\n        // Don't mark tile as reloading if it was empty.\n        if (tile.state !== 'empt