er) {\n            layerBand = layer.paint.get('raster-particle-array-band');\n        }\n        const band = layerBand || this.getInitialBand(sourceLayer);\n        if (band == null) return;\n\n        if (!tile.textureDescriptor) {\n            this.prepareTile(tile, sourceLayer, band);\n            return;\n        }\n\n        // Fallback to previous texture even if update is needed\n        if (tile.updateNeeded(sourceLayer, band) && !fallbackToPrevious) return;\n\n        return Object.assign({}, tile.textureDescriptor, {texture: tile.texture});\n    }\n}\n\nexport default RasterArrayTileSource;\n","import {bindAll} from '../util/util';\nimport {CanonicalTileID} from './tile_id';\n\nimport vector from '../source/vector_tile_source';\nimport raster from '../source/raster_tile_source';\nimport rasterDem from '../source/raster_dem_tile_source';\nimport rasterArray from '../source/raster_array_tile_source';\nimport geojson from '../source/geojson_source';\nimport video from '../source/video_source';\nimport image from '../source/image_source';\nimport canvas from '../source/canvas_source';\nimport custom from '../source/custom_source';\nimport model from '../../3d-style/source/model_source';\nimport tiled3DModel from '../../3d-style/source/tiled_3d_model_source';\n\nimport type Tile from './tile';\nimport type Dispatcher from '../util/dispatcher';\nimport type {Map} from '../ui/map';\nimport type {Class} from '../types/class';\nimport type {Source} from './source_types';\nimport type {Evented} from '../util/evented';\nimport type {Callback} from '../types/callback';\nimport type {MapEvents} from '../ui/events';\nimport type {OverscaledTileID} from './tile_id';\nimport type {SourceSpecification} from '../style-spec/types';\n\nexport type {Source};\n\nexport type SourceEvents = Pick<MapEvents, 'data' | 'dataloading' | 'error'>;\n\nexport type SourceRasterLayer = {\n    id: string;\n    maxzoom?: number;\n    minzoom?: number;\n    fields?: {\n        bands?: Array<string | number>;\n        range?: [number, number];\n    };\n};\n\nexport type SourceVectorLayer = {\n    id: string;\n    maxzoom?: number;\n    minzoom?: number;\n};\n\n/**\n * The `Source` interface must be implemented by each source type, including \"core\" types like `vector`, `raster`,\n * or `video`) and all custom, third-party types.\n *\n * @private\n *\n * @param {string} id The id for the source. Must not be used by any existing source.\n * @param {Object} options Source options, specific to the source type (except for `options.type`, which is always\n * required).\n * @param {string} options.type The source type, matching the value of `name` used in {@link Style#addSourceType}.\n * @param {Dispatcher} dispatcher A {@link Dispatcher} instance, which can be used to send messages to the workers.\n *\n * @fires Map.event:data Fires `data` with `{dataType: 'source', sourceDataType: 'metadata'}`\n * to indicate that any necessary metadata has been loaded so that it's okay to call `loadTile`;\n * fires `data` with `{dataType: 'source', sourceDataType: 'content'}`\n * to indicate that the source data has changed, so that any current caches should be flushed.\n * @property {string} id The id for the source.  Must match the id passed to the constructor.\n * @property {number} minzoom\n * @property {number} maxzoom\n * @property {boolean} isTileClipped `false` if tiles can be drawn outside their boundaries, `true` if they cannot.\n * @property {boolean} reparseOverscaled `true` if tiles should be sent back to the worker for each overzoomed zoom\n * level, `false` if not.\n * @property {boolean} roundZoom `true` if zoom levels are rounded to the nearest integer in the source data, `false`\n * if they are floor-ed to the nearest integer.\n */\nexport interface ISource extends Evented<SourceEvents> {\n    readonly type: string;\n    id: string;\n    scope: string;\n    minzoom: number;\n    maxzoom: number;\n    tileSize: number;\n    attribution?: string;\n    roundZoom?: boolean;\n    isTileClipped?: boolean;\n    mapbox_logo?: boolean;\n    tileID?: CanonicalTileID;\n    reparseOverscaled?: boolean;\n    minTileCacheSize?: number | null | undefined;\n    maxTileCacheSize?: number | null | undefined;\n    language?: string | null | undefined;\n    worldview?: string | null | undefined;\n    readonly usedInConflation?: boolean;\n    vectorLayers?: Array<SourceVectorLayer>;\n    vectorLayerIds?: Array<string>;\n    rasterLayers?: Array<SourceRasterLayer>;\n    rasterLayerIds?: Array<string>;\n    hasTransition(): boolean;\n    loaded(): boolean;\n    readonly onAdd?: (map: Map) => void;\n    readonly onRemove?: (map: Map) => void;\n    loadTile(\n        tile: Tile,\n        callback: Callback<undefined>,\n        tileWorkers?: {\n            [key: string]: Actor;\n        },\n    ): void;\n    readonly hasTile?: (tileID: OverscaledTileID) => boolean;\n    readonly abortTile?: (tile: Tile, callback?: Callback<undefined>) => void;\n    readonly unloadTile?: (tile: Tile, callback?: Callback<undefined>) => void;\n    readonly reload?: () => void;\n    /**\n     * @returns A plain (stringifiable) JS object representing the current state of the source.\n     * Creating a source using the returned object as the `options` should result in a Source that is\n     * equivalent to this one.\n     * @private\n     */\n    serialize(): SourceSpecification | {type: 'custom', [key: string]: unknown};\n    readonly prepare?: () => void;\n    readonly afterUpdate?: () => void;\n    readonly _clear?: () => void;\n}\n\ntype SourceStatics = {\n    /*\n     * An optional URL to a script which, when run by a Worker, registers a {@link WorkerSource}\n     * implementation for this Source type by calling `self.registerWorkerSource(workerSource: WorkerSource)`.\n     */\n    workerSourceURL?: URL;\n};\n\nexport type SourceClass = Class<ISource> & SourceStatics;\n\nconst sourceTypes: Record<Source['type'], Class<ISource>> = {\n    vector,\n    raster,\n    'raster-dem': rasterDem,\n    'raster-array': rasterArray,\n    geojson,\n    video,\n    image,\n    model,\n    'batched-model': tiled3DModel,\n    canvas,\n    custom\n};\n\n/*\n * Creates a tiled data source instance given an options object.\n *\n * @param id\n * @param {Object} source A source definition object compliant with\n * [`mapbox-gl-style-spec`](https://www.mapbox.com/mapbox-gl-style-spec/#sources) or, for a third-party source type,\n  * with that type's requirements.\n * @param {Dispatcher} dispatcher\n * @returns {Source}\n */\nexport const create = function(\n    id: string,\n    specification: SourceSpecification,\n    dispatcher: Dispatcher,\n    eventedParent: Evented,\n): Source {\n    const source = new sourceTypes[specification.type](id, specification, dispatcher, eventedParent) as Source;\n\n    if (source.id !== id) {\n        throw new Error(`Expected Source id to be ${id} instead of ${source.id}`);\n    }\n\n    bindAll(['load', 'abort', 'unload', 'serialize', 'prepare'], source);\n    return source;\n};\n\nexport const getType = function(name: string): Class<ISource> {\n    return sourceTypes[name];\n};\n\nexport const setType = function (name: string, type: Class<ISource>) {\n    sourceTypes[name] = type;\n};\n\nexport interface Actor {\n    send(type: string, data: unknown, callback: Callback<unknown>): void;\n}\n","import {getImage, ResourceType} from '../util/ajax';\nimport {extend, prevPowerOfTwo} from '../util/util';\nimport {Evented} from '../util/evented';\nimport browser from '../util/browser';\nimport offscreenCanvasSupported from '../util/offscreen_canvas_supported';\nimport {OverscaledTileID} from './tile_id';\nimport RasterTileSource from './raster_tile_source';\n\n// Import DEMData as a module with side effects to ensure\n// it's registered as a serializable class on the main thread\nimport '../data/dem_data';\n\nimport type DEMData from '../data/dem_data';\nimport type {ISource} from './source';\nimport type Dispatcher from '../util/dispatcher';\nimport type Tile from './tile';\nimport type {Callback} from '../types/callback';\nimport type {TextureImage} from '../render/texture';\nimport type {RasterDEMSourceSpecification} from '../style-spec/types';\n\nclass RasterDEMTileSource extends RasterTileSource<'raster-dem'> implements ISource {\n    type: 'raster-dem';\n    encoding: 'mapbox' | 'terrarium';\n\n    constructor(id: string, options: RasterDEMSourceSpecification, dispatcher: Dispatcher, eventedParent: Evented) {\n        super(id, options, dispatcher, eventedParent);\n        this.type = 'raster-dem';\n        this.maxzoom = 22;\n        this._options = extend({type: 'raster-dem'}, options);\n        this.encoding = options.encoding || \"mapbox\";\n    }\n\n    loadTile(tile: Tile, callback: Callback<undefined>) {\n        const url = this.map._requestManager.normalizeTileURL(tile.tileID.canonical.url(this.tiles, this.scheme), false, this.tileSize);\n        // @ts-expect-error - TS2345 - Argument of type 'string' is not assignable to parameter of type '\"Unknown\" | \"Style\" | \"Source\" | \"Tile\" | \"Glyphs\" | \"SpriteImage\" | \"SpriteJSON\" | \"Image\" | \"Model\"'.\n        tile.request = getImage(this.map._requestManager.transformRequest(url, ResourceType.Tile), imageLoaded.bind(this));\n\n        function imageLoaded(\n            err?: Error | null,\n            img?: TextureImage | null,\n            cacheControl?: string | null,\n            expires?: string | null,\n        ) {\n            delete tile.request;\n            if (tile.aborted) {\n                tile.state = 'unloaded';\n                callback(null);\n            } else if (err) {\n                tile.state = 'errored';\n                callback(err);\n            } else if (img) {\n                if (this.map._refreshExpiredTiles) tile.setExpiryData({cacheControl, expires});\n                const transfer = ImageBitmap && img instanceof ImageBitmap && offscreenCanvasSupported();\n                // DEMData uses 1px padding. Handle cases with image buffer of 1 and 2 pxs, the rest assume default buffer 0\n                // in order to keep the previous implementation working (no validation against tileSize).\n                const buffer = (img.width - prevPowerOfTwo(img.width)) / 2;\n                // padding is used in getImageData. As DEMData has 1px padding, if DEM tile buffer is 2px, discard outermost pixels.\n                const padding = 1 - buffer;\n                const borderReady = padding < 1;\n                if (!borderReady && !tile.neighboringTiles) {\n                    tile.neighboringTiles = this._getNeighboringTiles(tile.tileID);\n                }\n\n                // @ts-expect-error - TS2345 - Argument of type 'TextureImage' is not assignable to parameter of type 'CanvasImageSource'.\n                const rawImageData = transfer ? img : browser.getImageData(img, padding);\n                const params = {\n                    uid: tile.uid,\n                    coord: tile.tileID,\n                    source: this.id,\n                    scope: this.scope,\n                    rawImageData,\n                    encoding: this.encoding,\n                    padding\n                };\n\n                if (!tile.actor || tile.state === 'expired') {\n                    tile.actor = this.dispatcher.getActor();\n                    tile.actor.send('loadDEMTile', params, done.bind(this), undefined, true);\n                }\n            }\n        }\n\n        function done(err?: Error | null, dem?: DEMData | null) {\n            if (err) {\n                tile.state = 'errored';\n                callback(err);\n            }\n\n            if (dem) {\n                tile.dem = dem;\n                tile.dem.onDeserialize();\n                tile.needsHillshadePrepare = true;\n                tile.needsDEMTextureUpload = true;\n                tile.state = 'loaded';\n                callback(null);\n            }\n        }\n    }\n\n    _getNeighboringTiles(tileID: OverscaledTileID): {\n        [key: number]: {\n            backfilled: boolean;\n        };\n    } {\n        const canonical = tileID.canonical;\n        const dim = Math.pow(2, canonical.z);\n\n        const px = (canonical.x - 1 + dim) % dim;\n        const pxw = canonical.x === 0 ? tileID.wrap - 1 : tileID.wrap;\n        const nx = (canonical.x + 1 + dim) % dim;\n        const nxw = canonical.x + 1 === dim ? tileID.wrap + 1 : tileID.wrap;\n\n        const neighboringTiles: Record<string, any> = {};\n        // add adjacent tiles\n        neighboringTiles[new OverscaledTileID(tileID.overscaledZ, pxw, canonical.z, px, canonical.y).key] = {backfilled: false};\n        neighboringTiles[new OverscaledTileID(tileID.overscaledZ, nxw, canonical.z, nx, canonical.y).key] = {backfilled: false};\n\n        // Add upper neighboringTiles\n        if (canonical.y > 0) {\n            neighboringTiles[new OverscaledTileID(tileID.overscaledZ, pxw, canonical.z, px, canonical.y - 1).key] = {backfilled: false};\n            neighboringTiles[new OverscaledTileID(tileID.overscaledZ, tileID.wrap, canonical.z, canonical.x, canonical.y - 1).key] = {backfilled: false};\n            neighboringTiles[new OverscaledTileID(tileID.overscaledZ, nxw, canonical.z, nx, canonical.y - 1).key] = {backfilled: false};\n        }\n        // Add lower neighboringTiles\n        if (canonical.y + 1 < dim) {\n            neighboringTiles[new OverscaledTileID(tileID.overscaledZ, pxw, canonical.z, px, canonical.y + 1).key] = {backfilled: false};\n            neighboringTiles[new OverscaledTileID(tileID.overscaledZ, tileID.wrap, canonical.z, canonical.x, canonical.y + 1).key] = {backfilled: false};\n            neighboringTiles[new OverscaledTileID(tileID.overscaledZ, nxw, canonical.z, nx, canonical.y + 1).key] = {backfilled: false};\n        }\n\n        return neighboringTiles;\n    }\n}\n\nexport default RasterDEMTileSource;\n","import {Event, ErrorEvent, Evented} from '../util/evented';\n\nimport {extend} from '../util/util';\nimport EXTENT from '../style-spec/data/extent';\nimport {ResourceType} from '../util/ajax';\nimport browser from '../util/browser';\n\nimport type {ISource, SourceEvents} from './source';\nimport type {Map as MapboxMap} from '../ui/map';\nimport type Dispatcher from '../util/dispatcher';\nimport type Tile from './tile';\nimport type Actor from '../util/actor';\nimport type {Callback} from '../types/callback';\nimport type {GeoJSONWorkerOptions} from './geojson_worker_source';\nimport type {GeoJSONSourceSpecification, PromoteIdSpecification} from '../style-spec/types';\nimport type {Cancelable} from '../types/cancelable';\n\n/**\n * A source containing GeoJSON.\n * See the [Style Specification](https://www.mapbox.com/mapbox-gl-style-spec/#sources-geojson) for detailed documentation of options.\n *\n * @example\n * map.addSource('some id', {\n *     type: 'geojson',\n *     data: 'https://d2ad6b4ur7yvpq.cloudfront.net/naturalearth-3.3.0/ne_10m_ports.geojson'\n * });\n *\n * @example\n * map.addSource('some id', {\n *     type: 'geojson',\n *     data: {\n *         \"type\": \"FeatureCollection\",\n *         \"features\": [{\n *             \"type\": \"Feature\",\n *             \"properties\": {},\n *             \"geometry\": {\n *                 \"type\": \"Point\",\n *                 \"coordinates\": [\n *                     -76.53063297271729,\n *                     39.18174077994108\n *                 ]\n *             }\n *         }]\n *     }\n * });\n *\n * @example\n * map.getSource('some id').setData({\n *     \"type\": \"FeatureCollection\",\n *     \"features\": [{\n *         \"type\": \"Feature\",\n *         \"properties\": {\"name\": \"Null Island\"},\n *         \"geometry\": {\n *             \"type\": \"Point\",\n *             \"coordinates\": [ 0, 0 ]\n *         }\n *     }]\n * });\n * @see [Example: Draw GeoJSON points](https://www.mapbox.com/mapbox-gl-js/example/geojson-markers/)\n * @see [Example: Add a GeoJSON line](https://www.mapbox.com/mapbox-gl-js/example/geojson-line/)\n * @see [Example: Create a heatmap from points](https://www.mapbox.com/mapbox-gl-js/example/heatmap/)\n * @see [Example: Create and style clusters](https://www.mapbox.com/mapbox-gl-js/example/cluster/)\n */\nclass GeoJSONSource extends Evented<SourceEvents> implements ISource {\n    type: 'geojson';\n    id: string;\n    scope: string;\n    minzoom: number;\n    maxzoom: number;\n    tileSize: number;\n    minTileCacheSize: number | null | undefined;\n    maxTileCacheSize: number | null | undefined;\n    attribution: string | undefined;\n    promoteId: PromoteIdSpecification | null | undefined;\n    // eslint-disable-next-line camelcase\n    mapbox_logo: boolean | undefined;\n\n    roundZoom: boolean | undefined;\n    isTileClipped: boolean | undefined;\n    reparseOverscaled: boolean | undefined;\n    _data: GeoJSON.GeoJSON | string;\n    _options: GeoJSONSourceSpecification;\n    workerOptions: GeoJSONWorkerOptions;\n    map: MapboxMap;\n    actor: Actor;\n    _loaded: boolean;\n    _coalesce: boolean | null | undefined;\n    _metadataFired: boolean | null | undefined;\n    _collectResourceTiming: boolean;\n    _pendingLoad: Cancelable | null | undefined;\n    _partialReload: boolean;\n\n    reload: undefined;\n    hasTile: undefined;\n    prepare: undefined;\n    afterUpdate: undefined;\n    _clear: undefined;\n\n    /**\n     * @private\n     */\n    constructor(id: string, options: GeoJSONSourceSpecification & {\n        workerOptions?: GeoJSONWorkerOptions;\n        collectResourceTiming: boolean;\n    }, dispatcher: Dispatcher, eventedParent: Evented) {\n        super();\n\n        this.id = id;\n\n        // `type` is a property rather than a constant to make it easy for 3rd\n        // parties to use GeoJSONSource to build their own source types.\n        this.type = 'geojson';\n\n        this.minzoom = 0;\n        this.maxzoom = 18;\n        this.tileSize = 512;\n        this.isTileClipped = true;\n        this.reparseOverscaled = true;\n        this._loaded = false;\n\n        this.actor = dispatcher.getActor();\n        this.setEventedParent(eventedParent);\n\n        this._data = (options.data as any);\n        this._options = extend({}, options);\n\n        this._collectResourceTiming = options.collectResourceTiming;\n\n        if (options.maxzoom !== undefined) this.maxzoom = options.maxzoom;\n        if (options.minzoom !== undefined) this.minzoom = options.minzoom;\n        if (options.type) this.type = options.type;\n        if (options.attribution) this.attribution = options.attribution;\n        this.promoteId = options.promoteId;\n\n        const scale = EXTENT / this.tileSize;\n\n        // sent to the worker, along with `url: ...` or `data: literal geojson`,\n        // so that it can load/parse/index the geojson data\n        // extending with `options.workerOptions` helps to make it easy for\n        // third-party sources to hack/reuse GeoJSONSource.\n        this.workerOptions = extend({\n            source: this.id,\n            scope: this.scope,\n            cluster: options.cluster || false,\n            geojsonVtOptions: {\n                buffer: (options.buffer !== undefined ? options.buffer : 128) * scale,\n                tolerance: (options.tolerance !== undefined ? options.tolerance : 0.375) * scale,\n                extent: EXTENT,\n                maxZoom: this.maxzoom,\n                lineMetrics: options.lineMetrics || false,\n                generateId: options.generateId || false\n            },\n            superclusterOptions: {\n                maxZoom: options.clusterMaxZoom !== undefined ? options.clusterMaxZoom : this.maxzoom - 1,\n                minPoints: Math.max(2, options.clusterMinPoints || 2),\n                extent: EXTENT,\n                radius: (options.clusterRadius !== undefined ? options.clusterRadius : 50) * scale,\n                log: false,\n                generateId: options.generateId || false\n            },\n            clusterProperties: options.clusterProperties,\n            filter: options.filter,\n            dynamic: options.dynamic\n        }, options.workerOptions);\n    }\n\n    onAdd(map: MapboxMap) {\n        this.map = map;\n        this.setData(this._data);\n    }\n\n    /**\n     * Sets the GeoJSON data and re-renders the map.\n     *\n     * @param {Object | string} data A GeoJSON data object or a URL to one. The latter is preferable in the case of large GeoJSON files.\n     * @returns {GeoJSONSource} Returns itself to allow for method chaining.\n     * @example\n     * map.addSource('source_id', {\n     *     type: 'geojson',\n     *     data: {\n     *         type: 'FeatureCollection',\n     *         features: []\n     *     }\n     * });\n     * const geojsonSource = map.getSource('source_id');\n     * // Update the data after the GeoJSON source was created\n     * geojsonSource.setData({\n     *     \"type\": \"FeatureCollection\",\n     *     \"features\": [{\n     *         \"type\": \"Feature\",\n     *         \"properties\": {\"name\": \"Null Island\"},\n     *         \"geometry\": {\n     *             \"type\": \"Point\",\n     *             \"coordinates\": [ 0, 0 ]\n     *         }\n     *     }]\n     * });\n     */\n    setData(data: GeoJSON.GeoJSON | string): this {\n        this._data = data;\n        this._updateWorkerData();\n        return this;\n    }\n\n    /**\n     * Updates the existing GeoJSON data with new features and re-renders the map.\n     * Can only be used on sources with `dynamic: true` in options.\n     * Updates features by their IDs:\n     *\n     * - If there's a feature with the same ID, overwrite it.\n     * - If there's a feature with the same ID but the new one's geometry is `null`, remove it\n     * - If there's no such ID in existing data, add it as a new feature.\n     *\n     * @param {Object | string} data A GeoJSON data object or a URL to one.\n     * @returns {GeoJSONSource} Returns itself to allow for method chaining.\n     * @example\n     * // Update the feature with ID=123 in the existing GeoJSON source\n     * map.getSource('source_id').updateData({\n     *     \"type\": \"FeatureCollection\",\n     *     \"features\": [{\n     *         \"id\": 123,\n     *         \"type\": \"Feature\",\n     *         \"properties\": {\"name\": \"Null Island\"},\n     *         \"geometry\": {\n     *             \"type\": \"Point\",\n     *             \"coordinates\": [ 0, 0 ]\n     *         }\n     *     }]\n     * });\n     */\n    updateData(data: GeoJSON.GeoJSON | string): this {\n        if (!this._options.dynamic) {\n            return this.fire(new ErrorEvent(new Error(\"Can't call updateData on a GeoJSON source with dynamic set to false.\")));\n        }\n        if (typeof data !== 'string') {\n            if (data.type === 'Feature') {\n                data = {type: 'FeatureCollection', features: [data]};\n            }\n            if (data.type !== 'FeatureCollection') {\n                return this.fire(new ErrorEvent(new Error(\"Data to update should be a feature or a feature collection.\")));\n            }\n        }\n        // if there's a pending load, accummulate feature updates\n        if (this._coalesce && typeof data !== 'string' && typeof this._data !== 'string' && this._data.type === 'FeatureCollection') {\n            // merge features by ID to avoid accummulating duplicate features to update\n            const featuresById = new Map();\n            for (const feature of this._data.features) featuresById.set(feature.id, feature);\n            for (const feature of data.features) featuresById.set(feature.id, feature);\n            this._data.features = [...featuresById.values()];\n        } else {\n            this._data = data;\n        }\n        this._updateWorkerData(true);\n        return this;\n    }\n\n    /**\n     * For clustered sources, fetches the zoom at which the given cluster expands.\n     *\n     * @param {number} clusterId The value of the cluster's `cluster_id` property.\n     * @param {Function} callback A callback to be called when the zoom value is retrieved (`(error, zoom) => { ... }`).\n     * @returns {GeoJSONSource} Returns itself to allow for method chaining.\n     * @example\n     * // Assuming the map has a layer named 'clusters' and a source 'earthquakes'\n     * // The following creates a camera animation on cluster feature click\n     * // the clicked layer should be filtered to only include clusters, e.g. `filter: ['has', 'point_count']`\n     * map.on('click', 'clusters', (e) => {\n     *     const features = map.queryRenderedFeatures(e.point, {\n     *         layers: ['clusters']\n     *     });\n     *\n     *     const clusterId = features[0].properties.cluster_id;\n     *\n     *     // Ease the camera to the next cluster expansion\n     *     map.getSource('earthquakes').getClusterExpansionZoom(\n     *         clusterId,\n     *         (err, zoom) => {\n     *             if (!err) {\n     *                 map.easeTo({\n     *                     center: features[0].geometry.coordinates,\n     *                     zoom\n     *                 });\n     *             }\n     *         }\n     *     );\n     * });\n     */\n    getClusterExpansionZoom(clusterId: number, callback: Callback<number>): this {\n        this.actor.send('geojson.getClusterExpansionZoom', {clusterId, source: this.id, scope: this.scope}, callback);\n        return this;\n    }\n\n    /**\n     * For clustered sources, fetches the children of the given cluster on the next zoom level (as an array of GeoJSON features).\n     *\n     * @param {number} clusterId The value of the cluster's `cluster_id` property.\n     * @param {Function} callback A callback to be called when the features are retrieved (`(error, features) => { ... }`).\n     * @returns {GeoJSONSource} Returns itself to allow for method chaining.\n     * @example\n     * // Retrieve cluster children on click\n     * // the clicked layer should be filtered to only include clusters, e.g. `filter: ['has', 'point_count']`\n     * map.on('click', 'clusters', (e) => {\n     *     const features = map.queryRenderedFeatures(e.point, {\n     *         layers: ['clusters']\n     *     });\n     *\n     *     const clusterId = features[0].properties.cluster_id;\n     *\n     *     clusterSource.getClusterChildren(clusterId, (error, features) => {\n     *         if (!error) {\n     *             console.log('Cluster children:', features);\n     *         }\n     *     });\n     * });\n     */\n    getClusterChildren(clusterId: number, callback: Callback<Array<GeoJSON.Feature>>): this {\n        this.actor.send('geojson.getClusterChildren', {clusterId, source: this.id, scope: this.scope}, callback);\n        return this;\n    }\n\n    /**\n     * For clustered sources, fetches the original points that belong to the cluster (as an array of GeoJSON features).\n     *\n     * @param {number} clusterId The value of the cluster's `cluster_id` property.\n     * @param {number} limit The maximum number of features to return. Defaults to `10` if a falsy value is given.\n     * @param {number} offset The number of features to skip (for example, for pagination). Defaults to `0` if a falsy value is given.\n     * @param {Function} callback A callback to be called when the features are retrieved (`(error, features) => { ... }`).\n     * @returns {GeoJSONSource} Returns itself to allow for method chaining.\n     * @example\n     * // Retrieve cluster leaves on click\n     * // the clicked layer should be filtered to only include clusters, e.g. `filter: ['has', 'point_count']`\n     * map.on('click', 'clusters', (e) => {\n     *     const features = map.queryRenderedFeatures(e.point, {\n     *         layers: ['clusters']\n     *     });\n     *\n     *     const clusterId = features[0].properties.cluster_id;\n     *     const pointCount = features[0].properties.point_count;\n     *     const clusterSource = map.getSource('clusters');\n     *\n     *     clusterSource.getClusterLeaves(clusterId, pointCount, 0, (error, features) => {\n     *     // Print cluster leaves in the console\n     *         console.log('Cluster leaves:', error, features);\n     *     });\n     * });\n     */\n    getClusterLeaves(\n        clusterId: number,\n        limit: number,\n        offset: number,\n        callback: Callback<Array<GeoJSON.Feature>>,\n    ): this {\n        this.actor.send('geojson.getClusterLeaves', {\n            source: this.id,\n            scope: this.scope,\n            clusterId,\n            limit,\n            offset\n        }, callback);\n        return this;\n    }\n\n    /*\n     * Responsible for invoking WorkerSource's geojson.loadData target, which\n     * handles loading the geojson data and preparing to serve it up as tiles,\n     * using geojson-vt or supercluster as appropriate.\n     */\n    _updateWorkerData(append: boolean = false) {\n        // if there's an earlier loadData to finish, wait until it finishes and then do another update\n        if (this._pendingLoad) {\n            this._coalesce = true;\n            return;\n        }\n\n        this.fire(new Event('dataloading', {dataType: 'source'}));\n\n        this._loaded = false;\n        const options = extend({append}, this.workerOptions) as GeoJSONWorkerOptions & {\n            data?: string\n            scope?: string;\n            append?: boolean;\n            request?: ReturnType<typeof this.map._requestManager.transformRequest>;\n        };\n\n        options.scope = this.scope;\n        const data = this._data;\n        if (typeof data === 'string') {\n            // @ts-expect-error - TS2345 - Argument of type 'string' is not assignable to parameter of type '\"Unknown\" | \"Style\" | \"Source\" | \"Tile\" | \"Glyphs\" | \"SpriteImage\" | \"SpriteJSON\" | \"Image\" | \"Model\"'.\n            options.request = this.map._requestManager.transformRequest(browser.resolveURL(data), ResourceType.Source);\n            options.request.collectResourceTiming = this._collectResourceTiming;\n        } else {\n            options.data = JSON.stringify(data);\n        }\n\n        // target {this.type}.loadData rather than literally geojson.loadData,\n        // so that other geojson-like source types can easily reuse this\n        // implementation\n        this._pendingLoad = this.actor.send(`${this.type}.loadData`, options, (err, result) => {\n            this._loaded = true;\n            this._pendingLoad = null;\n\n            if (err) {\n                this.fire(new ErrorEvent(err));\n\n            } else {\n                // although GeoJSON sources contain no metadata, we fire this event at first\n                // to let the SourceCache know its ok to start requesting tiles.\n                const data: any = {dataType: 'source', sourceDataType: this._metadataFired ? 'content' : 'metadata'};\n                if (this._collectResourceTiming && result && result.resourceTiming && result.resourceTiming[this.id]) {\n                    data.resourceTiming = result.resourceTiming[this.id];\n                }\n                if (append) this._partialReload = true;\n                this.fire(new Event('data', data));\n                this._partialReload = false;\n                this._metadataFired = true;\n            }\n\n            if (this._coalesce) {\n                this._updateWorkerData(append);\n                this._coalesce = false;\n            }\n        });\n    }\n\n    loaded(): boolean {\n        return this._loaded;\n    }\n\n    loadTile(tile: Tile, callback: Callback<undefined>) {\n        const message = !tile.actor ? 'loadTile' : 'reloadTile';\n        tile.actor = this.actor;\n        const lutForScope = this.map.style ? this.map.style.getLut(this.scope) : null;\n        const partial = this._partialReload;\n        const params = {\n            type: this.type,\n            uid: tile.uid,\n            tileID: tile.tileID,\n            tileZoom: tile.tileZoom,\n            zoom: tile.tileID.overscaledZ,\n            maxZoom: this.maxzoom,\n            tileSize: this.tileSize,\n            source: this.id,\n            lut: lutForScope ? {\n                image: lutForScope.image.clone()\n            } : null,\n            scope: this.scope,\n            pixelRatio: browser.devicePixelRatio,\n            showCollisionBoxes: this.map.showCollisionBoxes,\n            promoteId: this.promoteId,\n            brightness: this.map.style ? (this.map.style.getBrightness() || 0.0) : 0.0,\n            partial\n        };\n\n        tile.request = this.actor.send(message, params, (err, data) => {\n            if (partial && !data) {\n                // if we did a partial reload and the tile didn't change, do nothing and treat the tile as loaded\n                tile.state = 'loaded';\n                return callback(null);\n            }\n\n            delete tile.request;\n            tile.destroy();\n\n            if (tile.aborted) {\n                return callback(null);\n            }\n\n            if (err) {\n                return callback(err);\n            }\n\n            tile.loadVectorData(data, this.map.painter, message === 'reloadTile');\n\n            return callback(null);\n        }, undefined, message === 'loadTile');\n    }\n\n    abortTile(tile: Tile) {\n        if (tile.request) {\n            tile.request.cancel();\n            delete tile.request;\n        }\n        tile.aborted = true;\n    }\n\n    unloadTile(tile: Tile, _?: Callback<undefined> | null) {\n        this.actor.send('removeTile', {uid: tile.uid, type: this.type, source: this.id, scope: this.scope});\n        tile.destroy();\n    }\n\n    onRemove(_: MapboxMap) {\n        if (this._pendingLoad) {\n            this._pendingLoad.cancel();\n        }\n    }\n\n    serialize(): GeoJSONSourceSpecification {\n        return extend({}, this._options, {\n            type: this.type,\n            data: this._data\n        });\n    }\n\n    hasTransition(): boolean {\n        return false;\n    }\n}\n\nexport default GeoJSONSource;\n","import {getVideo, ResourceType} from '../util/ajax';\n\nimport ImageSource from './image_source';\nimport Texture from '../render/texture';\nimport {ErrorEvent} from '../util/evented';\nimport ValidationError from '../style-spec/error/validation_error';\n\nimport type {Map} from '../ui/map';\nimport type Dispatcher from '../util/dispatcher';\nimport type {Evented} from '../util/evented';\nimport type {VideoSourceSpecification} from '../style-spec/types';\n\n/**\n * A data source containing video.\n * See the [Style Specification](https://www.mapbox.com/mapbox-gl-style-spec/#sources-video) for detailed documentation of options.\n *\n * @example\n * // add to map\n * map.addSource('some id', {\n *     type: 'video',\n *     url: [\n *         'https://www.mapbox.com/blog/assets/baltimore-smoke.mp4',\n *         'https://www.mapbox.com/blog/assets/baltimore-smoke.webm'\n *     ],\n *     coordinates: [\n *         [-76.54, 39.18],\n *         [-76.52, 39.18],\n *         [-76.52, 39.17],\n *         [-76.54, 39.17]\n *     ]\n * });\n *\n * // update\n * const mySource = map.getSource('some id');\n * mySource.setCoordinates([\n *     [-76.54335737228394, 39.18579907229748],\n *     [-76.52803659439087, 39.1838364847587],\n *     [-76.5295386314392, 39.17683392507606],\n *     [-76.54520273208618, 39.17876344106642]\n * ]);\n *\n * map.removeSource('some id');  // remove\n * @see [Example: Add a video](https://www.mapbox.com/mapbox-gl-js/example/video-on-a-map/)\n */\nclass VideoSource extends ImageSource<'video'> {\n    type: 'video';\n    options: VideoSourceSpecification;\n    urls: Array<string>;\n    video: HTMLVideoElement;\n\n    /**\n     * @private\n     */\n    constructor(id: string, options: VideoSourceSpecification, dispatcher: Dispatcher, eventedParent: Evented) {\n        super(id, options, dispatcher, eventedParent);\n        this.roundZoom = true;\n        this.type = 'video';\n        this.options = options;\n    }\n\n    load() {\n        this._loaded = false;\n        const options = this.options;\n\n        this.urls = [];\n        for (const url of options.urls) {\n            // @ts-expect-error - TS2345 - Argument of type 'string' is not assignable to parameter of type '\"Unknown\" | \"Style\" | \"Source\" | \"Tile\" | \"Glyphs\" | \"SpriteImage\" | \"SpriteJSON\" | \"Image\" | \"Model\"'.\n            this.urls.push(this.map._requestManager.transformRequest(url, ResourceType.Source).url);\n        }\n\n        getVideo(this.urls, (err, video) => {\n            this._loaded = true;\n            if (err) {\n                this.fire(new ErrorEvent(err));\n            } else if (video) {\n                this.video = video;\n                this.video.loop = true;\n\n                // Prevent the video from taking over the screen in iOS\n                this.video.setAttribute('playsinline', '');\n\n                // Start repainting when video starts playing. hasTransition() will then return\n                // true to trigger additional frames as long as the videos continues playing.\n                this.video.addEventListener('playing', () => {\n                    this.map.triggerRepaint();\n                });\n\n                if (this.map) {\n                    this.video.play();\n                }\n\n                this._finishLoading();\n            }\n        });\n    }\n\n    /**\n     * Pauses the video.\n     *\n     * @example\n     * // Assuming a video source identified by video_source_id was added to the map\n     * const videoSource = map.getSource('video_source_id');\n     *\n     * // Pauses the video\n     * videoSource.pause();\n     */\n    pause() {\n        if (this.video) {\n            this.video.pause();\n        }\n    }\n\n    /**\n     * Plays the video.\n     *\n     * @example\n     * // Assuming a video source identified by video_source_id was added to the map\n     * const videoSource = map.getSource('video_source_id');\n     *\n     * // Starts the video\n     * videoSource.play();\n     */\n    play() {\n        if (this.video) {\n            this.video.play();\n        }\n    }\n\n    /**\n     * Sets playback to a timestamp, in seconds.\n     * @private\n     */\n    seek(seconds: number) {\n        if (this.video) {\n            const seekableRange = this.video.seekable;\n            if (seconds < seekableRange.start(0) || seconds > seekableRange.end(0)) {\n                this.fire(new ErrorEvent(new ValidationError(`sources.${this.id}`, null, `Playback for this video can be set only between the ${seekableRange.start(0)} and ${seekableRange.end(0)}-second mark.`)));\n            } else this.video.currentTime = seconds;\n        }\n    }\n\n    /**\n     * Returns the HTML `video` element.\n     *\n     * @returns {HTMLVideoElement} The HTML `video` element.\n     * @example\n     * // Assuming a video source identified by video_source_id was added to the map\n     * const videoSource = map.getSource('video_source_id');\n     *\n     * videoSource.getVideo(); // <video crossorigin=\"Anonymous\" loop=\"\">...</video>\n     */\n    getVideo(): HTMLVideoElement {\n        return this.video;\n    }\n\n    onAdd(map: Map) {\n        if (this.map) return;\n        this.map = map;\n        this.load();\n        if (this.video) {\n            this.video.play();\n            this.setCoordinates(this.coordinates);\n        }\n    }\n\n    /**\n     * Sets the video's coordinates and re-renders the map.\n     *\n     * @method setCoordinates\n     * @instance\n     * @memberof VideoSource\n     * @returns {VideoSource} Returns itself to allow for method chaining.\n     * @example\n     * // Add a video source to the map to map\n     * map.addSource('video_source_id', {\n     *     type: 'video',\n     *     urls: [\n     *         'https://www.mapbox.com/blog/assets/baltimore-smoke.mp4',\n     *         'https://www.mapbox.com/blog/assets/baltimore-smoke.webm'\n     *     ],\n     *     coordinates: [\n     *         [-76.54, 39.18],\n     *         [-76.52, 39.18],\n     *         [-76.52, 39.17],\n     *         [-76.54, 39.17]\n     *     ]\n     * });\n     *\n     * // Then update the video source coordinates by new coordinates\n     * const videoSource = map.getSource('video_source_id');\n     * videoSource.setCoordinates([\n     *     [-76.5433, 39.1857],\n     *     [-76.5280, 39.1838],\n     *     [-76.5295, 39.1768],\n     *     [-76.5452, 39.1787]\n     * ]);\n     */\n    // setCoordinates inherited from ImageSource\n\n    prepare() {\n        if (Object.keys(this.tiles).length === 0 || this.video.readyState < 2) {\n            return; // not enough data for current position\n        }\n\n        const context = this.map.painter.context;\n        const gl = context.gl;\n\n        if (!this.texture) {\n            this.texture = new Texture(context, this.video, gl.RGBA);\n            this.texture.bind(gl.LINEAR, gl.CLAMP_TO_EDGE);\n            this.width = this.video.videoWidth;\n            this.height = this.video.videoHeight;\n\n        } else if (!this.video.paused) {\n            this.texture.bind(gl.LINEAR, gl.CLAMP_TO_EDGE);\n            gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, gl.RGBA, gl.UNSIGNED_BYTE, this.video);\n        }\n\n        this._prepareData(context);\n    }\n\n    serialize(): VideoSourceSpecification {\n        return {\n            type: 'video',\n            urls: this.urls,\n            coordinates: this.coordinates\n        };\n    }\n\n    hasTransition(): boolean {\n        return this.video && !this.video.paused;\n    }\n}\n\nexport default VideoSource;\n","import {Evented, ErrorEvent, Event} from '../../src/util/evented';\nimport {ResourceType} from '../../src/util/ajax';\n\nimport Model from '../data/model';\nimport convertModel from './model_loader';\nimport {loadGLTF} from '../util/loaders';\n\nimport type Tile from '../../src/source/tile';\nimport type Dispatcher from '../../src/util/dispatcher';\nimport type {Map} from '../../src/ui/map';\nimport type {Callback} from '../../src/types/callback';\nimport type {ISource, SourceEvents} from '../../src/source/source';\nimport type {ModelSourceSpecification} from '../../src/style-spec/types';\n\n/**\n * A source containing single models.\n */\n// Important Note: ModelSource is legacy and should not be offered in the API, as the only valid official sources to add models\n// are batched-models and via GeoJson/vector sources. We keep this one (for now) just for ease development and get the render-tests\n// passing.\nclass ModelSource extends Evented<SourceEvents> implements ISource {\n    type: 'model';\n    id: string;\n    scope: string;\n    minzoom: number;\n    maxzoom: number;\n    tileSize: number;\n    minTileCacheSize: number | null | undefined;\n    maxTileCacheSize: number | null | undefined;\n    roundZoom: boolean | undefined;\n    reparseOverscaled: boolean | undefined;\n    attribution: string | undefined;\n    // eslint-disable-next-line camelcase\n    mapbox_logo: boolean | undefined;\n    map: Map;\n    uri: string;\n    models: Array<Model>;\n    _options: ModelSourceSpecification;\n    _loaded: boolean;\n\n    onRemove: undefined;\n    reload: undefined;\n    abortTile: undefined;\n    unloadTile: undefined;\n    hasTile: undefined;\n    prepare: undefined;\n    afterUpdate: undefined;\n    _clear: undefined;\n\n    /**\n     * @private\n     */\n    // eslint-disable-next-line no-unused-vars\n    constructor(id: string, options: ModelSourceSpecification, dispatcher: Dispatcher, eventedParent: Evented) {\n        super();\n        this.id = id;\n        this.type = 'model';\n        this.models = [];\n        this._loaded = false;\n        this._options = options;\n    }\n\n    load(): Promise<void> {\n        const modelPromises = [];\n\n        // @ts-expect-error - TS2339 - Property 'models' does not exist on type 'ModelSourceSpecification'.\n        for (const modelId in this._options.models) {\n            // @ts-expect-error - TS2339 - Property 'models' does not exist on type 'ModelSourceSpecification'.\n            const modelSpec = this._options.models[modelId];\n\n            // @ts-expect-error - TS2345 - Argument of type 'string' is not assignable to parameter of type '\"Unknown\" | \"Style\" | \"Source\" | \"Tile\" | \"Glyphs\" | \"SpriteImage\" | \"SpriteJSON\" | \"Image\" | \"Model\"'.\n            const modelPromise = loadGLTF(this.map._requestManager.transformRequest(modelSpec.uri, ResourceType.Model).url).then(gltf => {\n                if (!gltf) return;\n                const nodes = convertModel(gltf);\n                const model = new Model(modelId, modelSpec.position, modelSpec.orientation, nodes);\n                model.computeBoundsAndApplyParent();\n                this.models.push(model);\n            }).catch((err) => {\n                this.fire(new ErrorEvent(new Error(`Could not load model ${modelId} from ${modelSpec.uri}: ${err.message}`)));\n            });\n\n            modelPromises.push(modelPromise);\n        }\n\n        return Promise.allSettled(modelPromises).then(() => {\n            this._loaded = true;\n            this.fire(new Event('data', {dataType: 'source', sourceDataType: 'metadata'}));\n        }).catch((err) => {\n            this.fire(new ErrorEvent(new Error(`Could not load models: ${err.message}`)));\n        });\n    }\n\n    onAdd(map: Map) {\n        this.map = map;\n        this.load();\n    }\n\n    hasTransition(): boolean {\n        return false;\n    }\n\n    loaded(): boolean {\n        return this._loaded;\n    }\n\n    getModels(): Array<Model> {\n        return this.models;\n    }\n    // eslint-disable-next-line no-unused-vars\n    loadTile(tile: Tile, callback: Callback<undefined>) {}\n\n    serialize(): any {\n        return {\n            type: 'model'\n        };\n    }\n}\n\nexport default ModelSource;\n","import {Evented, ErrorEvent, Event} from '../../src/util/evented';\nimport {ResourceType} from '../../src/util/ajax';\nimport loadTileJSON from '../../src/source/load_tilejson';\nimport TileBounds from '../../src/source/tile_bounds';\nimport {extend} from '../../src/util/util';\nimport {postTurnstileEvent} from '../../src/util/mapbox';\n\n// Import Tiled3dModelBucket as a module with side effects to ensure\n// it's registered as a serializable class on the main thread\nimport '../data/bucket/tiled_3d_model_bucket';\n\nimport type Tile from '../../src/source/tile';\nimport type Dispatcher from '../../src/util/dispatcher';\nimport type Tiled3dModelBucket from '../data/bucket/tiled_3d_model_bucket';\nimport type {Map} from '../../src/ui/map';\nimport type {Callback} from '../../src/types/callback';\nimport type {Cancelable} from '../../src/types/cancelable';\nimport type {OverscaledTileID} from '../../src/source/tile_id';\nimport type {ISource, SourceEvents} from '../../src/source/source';\nimport type {ModelSourceSpecification} from '../../src/style-spec/types';\n\nclass Tiled3DModelSource extends Evented<SourceEvents> implements ISource {\n    type: 'batched-model';\n    id: string;\n    scope: string;\n    minzoom: number;\n    maxzoom: number;\n    tileBounds: TileBounds;\n    roundZoom: boolean | undefined;\n    reparseOverscaled: boolean | undefined;\n    usedInConflation: boolean;\n    tileSize: number;\n    minTileCacheSize: number | null | undefined;\n    maxTileCacheSize: number | null | undefined;\n    attribution: string | undefined;\n    // eslint-disable-next-line camelcase\n    mapbox_logo: boolean | undefined;\n    tiles: Array<string>;\n    dispatcher: Dispatcher;\n    scheme: string;\n    _loaded: boolean;\n    _options: ModelSourceSpecification;\n    _tileJSONRequest: Cancelable | null | undefined;\n    map: Map;\n\n    onRemove: undefined;\n    reload: undefined;\n    abortTile: undefined;\n    unloadTile: undefined;\n    prepare: undefined;\n    afterUpdate: undefined;\n    _clear: undefined;\n\n    /**\n     * @private\n     */\n    constructor(id: string, options: ModelSourceSpecification, dispatcher: Dispatcher, eventedParent: Evented) {\n        super();\n        this.type = 'batched-model';\n        this.id = id;\n        this.tileSize = 512;\n\n        this._options = options;\n        this.tiles = (this._options.tiles as any);\n        this.maxzoom = options.maxzoom || 19;\n        this.minzoom = options.minzoom || 0;\n        this.roundZoom = true;\n        this.usedInConflation = true;\n        this.dispatcher = dispatcher;\n        this.reparseOverscaled = false;\n        this.scheme = 'xyz';\n        this._loaded = false;\n        this.setEventedParent(eventedParent);\n    }\n    onAdd(map: Map) {\n        this.map = map;\n        this.load();\n    }\n\n    load(callback?: Callback<undefined>) {\n        this._loaded = false;\n        this.fire(new Event('dataloading', {dataType: 'source'}));\n        const language = Array.isArray(this.map._language) ? this.map._language.join() : this.map._language;\n        const worldview = this.map._worldview;\n        this._tileJSONRequest = loadTileJSON(this._options, this.map._requestManager, language, worldview, (err, tileJSON) => {\n            this._tileJSONRequest = null;\n            this._loaded = true;\n            if (err) {\n                if (language) console.warn(`Ensure that your requested language string is a valid BCP-47 code or list of codes. Found: ${language}`);\n                if (worldview && worldview.length !== 2) console.warn(`Requested worldview strings must be a valid ISO alpha-2 code. Found: ${worldview}`);\n\n                this.fire(new ErrorEvent(err));\n            } else if (tileJSON) {\n                extend(this, tileJSON);\n                if (tileJSON.bounds) this.tileBounds = new TileBounds(tileJSON.bounds, this.minzoom, this.maxzoom);\n                postTurnstileEvent(tileJSON.tiles, this.map._requestManager._customAccessToken);\n\n                // `content` is included here to prevent a race condition where `Style#_updateSources` is called\n                // before the TileJSON arrives. this makes sure the tiles needed are loaded once TileJSON arrives\n                // ref: https://github.com/mapbox/mapbox-gl-js/pull/4347#discussion_r104418088\n                this.fire(new Event('data', {dataType: 'source', sourceDataType: 'metadata'}));\n                this.fire(new Event('data', {dataType: 'source', sourceDataType: 'content'}));\n            }\n\n            if (callback) callback(err);\n        });\n    }\n\n    hasTransition(): boolean {\n        return false;\n    }\n\n    hasTile(tileID: OverscaledTileID): boolean {\n        return !this.tileBounds || this.tileBounds.contains(tileID.canonical);\n    }\n\n    loaded(): boolean {\n        return this._loaded;\n    }\n\n    loadTile(tile: Tile, callback: Callback<undefined>) {\n        const url = this.map._requestManager.normalizeTileURL(tile.tileID.canonical.url((this.tiles as any), this.scheme));\n        // @ts-expect-error - TS2345 - Argument of type 'string' is not assignable to parameter of type '\"Unknown\" | \"Style\" | \"Source\" | \"Tile\" | \"Glyphs\" | \"SpriteImage\" | \"SpriteJSON\" | \"Image\" | \"Model\"'.\n        const request = this.map._requestManager.transformRequest(url, ResourceType.Tile);\n        const params = {\n            request,\n            data: undefined,\n            uid: tile.uid,\n            tileID: tile.tileID,\n            tileZoom: tile.tileZoom,\n            zoom: tile.tileID.overscaledZ,\n            tileSize: this.tileSize * tile.tileID.overscaleFactor(),\n            type: this.type,\n            source: this.id,\n            scope: this.scope,\n            showCollisionBoxes: this.map.showCollisionBoxes,\n            isSymbolTile: tile.isSymbolTile,\n            brightness: this.map.style ? (this.map.style.getBrightness() || 0.0) : 0.0\n        };\n        if (!tile.actor || tile.state === 'expired') {\n            tile.actor = this.dispatcher.getActor();\n            tile.request = tile.actor.send('loadTile', params, done.bind(this), undefined, true);\n        } else if (tile.state === 'loading') {\n            // schedule tile reloading after it has been loaded\n            tile.reloadCallback = callback;\n        } else {\n            // If the tile has already been parsed we may just need to reevaluate\n            if (tile.buckets) {\n                const buckets: Tiled3dModelBucket[] = (Object.values(tile.buckets) as any[]);\n                for (const bucket of buckets) {\n                    bucket.dirty = true;\n                }\n                tile.state = 'loaded';\n                return;\n            }\n            tile.request = tile.actor.send('reloadTile', params, done.bind(this));\n        }\n\n        function done(err: Error | null | undefined, data: any) {\n            if (tile.aborted) return callback(null);\n\n            // @ts-expect-error - TS2339 - Property 'status' does not exist on type 'Error'.\n            if (err && err.status !== 404) {\n                return callback(err);\n            }\n\n            if (data) {\n                if (data.resourceTiming) tile.resourceTiming = data.resourceTiming;\n                if (this.map._refreshExpiredTiles) tile.setExpiryData(data);\n                tile.buckets = {...tile.buckets, ...data.buckets};\n                if (data.featureIndex) {\n                    tile.latestFeatureIndex = data.featureIndex;\n                }\n            }\n\n            tile.state = 'loaded';\n            callback(null);\n        }\n    }\n\n    serialize(): ModelSourceSpecification {\n        return extend({}, this._options);\n    }\n}\n\nexport default Tiled3DModelSource;\n","import ImageSource from './image_source';\n\nimport Texture, {UserManagedTexture} from '../render/texture';\nimport {ErrorEvent} from '../util/evented