iformValues[name]);\n            }\n        }\n    }\n\n    setFogUniformValues(context: Context, fogUniformValues: UniformValues<FogUniformsType>) {\n        if (!this.fogUniforms) return;\n        const uniforms: FogUniformsType = this.fogUniforms;\n\n        if (this.failedToCreate) return;\n        context.program.set(this.program);\n\n        for (const name in fogUniformValues) {\n            uniforms[name].set(this.program, name, fogUniformValues[name]);\n        }\n    }\n\n    setCutoffUniformValues(context: Context, cutoffUniformValues: UniformValues<CutoffUniformsType>) {\n        if (!this.cutoffUniforms) return;\n        const uniforms: CutoffUniformsType = this.cutoffUniforms;\n\n        if (this.failedToCreate) return;\n        context.program.set(this.program);\n\n        for (const name in cutoffUniformValues) {\n            uniforms[name].set(this.program, name, cutoffUniformValues[name]);\n        }\n    }\n\n    setLightsUniformValues(context: Context, lightsUniformValues: UniformValues<LightsUniformsType>) {\n        if (!this.lightsUniforms) return;\n        const uniforms: LightsUniformsType = this.lightsUniforms;\n\n        if (this.failedToCreate) return;\n        context.program.set(this.program);\n\n        for (const name in lightsUniformValues) {\n            uniforms[name].set(this.program, name, lightsUniformValues[name]);\n        }\n    }\n\n    setShadowUniformValues(context: Context, shadowUniformValues: UniformValues<ShadowUniformsType>) {\n        if (this.failedToCreate || !this.shadowUniforms) return;\n\n        const uniforms: ShadowUniformsType = this.shadowUniforms;\n        context.program.set(this.program);\n\n        for (const name in shadowUniformValues) {\n            uniforms[name].set(this.program, name, shadowUniformValues[name]);\n        }\n    }\n\n    _drawDebugWireframe(painter: Painter, depthMode: Readonly<DepthMode>,\n        stencilMode: Readonly<StencilMode>,\n        colorMode: Readonly<ColorMode>,\n        indexBuffer: IndexBuffer, segment: Segment,\n        currentProperties: any, zoom?: number | null, configuration?: ProgramConfiguration | null, instanceCount?: number | null) {\n\n        const wireframe = painter.options.wireframe;\n\n        if (wireframe.terrain === false && wireframe.layers2D === false && wireframe.layers3D === false) {\n            return;\n        }\n\n        const context = painter.context;\n\n        const subjectForWireframe = (() => {\n            // Terrain\n            if (wireframe.terrain && (this.name === 'terrainRaster' || this.name === 'globeRaster')) {\n                return true;\n            }\n\n            const drapingInProgress = painter._terrain && painter._terrain.renderingToTexture;\n\n            // 2D\n            if (wireframe.layers2D && !drapingInProgress) {\n                if (debugWireframe2DLayerProgramNames.includes(this.name)) {\n                    return true;\n                }\n            }\n\n            // 3D\n            if (wireframe.layers3D) {\n                if (debugWireframe3DLayerProgramNames.includes(this.name)) {\n                    return true;\n                }\n            }\n\n            return false;\n        })();\n\n        if (!subjectForWireframe) {\n            return;\n        }\n\n        const gl = context.gl;\n        const linesIndexBuffer = painter.wireframeDebugCache.getLinesFromTrianglesBuffer(painter.frameCounter, indexBuffer, context);\n\n        if (!linesIndexBuffer) {\n            return;\n        }\n\n        const debugDefines = [...this.fixedDefines];\n        debugDefines.push(\"DEBUG_WIREFRAME\");\n        // @ts-expect-error - TS2322 - Type 'string[]' is not assignable to type 'DynamicDefinesType[]'.\n        const debugProgram = painter.getOrCreateProgram(this.name, {config: this.configuration, defines: debugDefines});\n\n        context.program.set(debugProgram.program);\n\n        const copyUniformValues = (group: string, pSrc: any, pDst: any) => {\n            if (pSrc[group] && pDst[group]) {\n                for (const name in pSrc[group]) {\n                    if (pDst[group][name]) {\n                        pDst[group][name].set(pDst.program, name, pSrc[group][name].current);\n                    }\n                }\n            }\n        };\n\n        if (configuration) {\n            configuration.setUniforms(debugProgram.program, context, debugProgram.binderUniforms, currentProperties, {zoom: (zoom as any)});\n        }\n\n        copyUniformValues(\"fixedUniforms\", this, debugProgram);\n        copyUniformValues(\"terrainUniforms\", this, debugProgram);\n        copyUniformValues(\"globeUniforms\", this, debugProgram);\n        copyUniformValues(\"fogUniforms\", this, debugProgram);\n        copyUniformValues(\"lightsUniforms\", this, debugProgram);\n        copyUniformValues(\"shadowUniforms\", this, debugProgram);\n\n        linesIndexBuffer.bind();\n\n        // Debug wireframe uses premultiplied alpha blending (alpha channel is left unchanged)\n        context.setColorMode(new ColorMode([gl.ONE, gl.ONE_MINUS_SRC_ALPHA, gl.ZERO, gl.ONE],\n            Color.transparent, [true, true, true, false]));\n        context.setDepthMode(new DepthMode(depthMode.func === gl.LESS ? gl.LEQUAL : depthMode.func, DepthMode.ReadOnly, depthMode.range));\n        context.setStencilMode(StencilMode.disabled);\n\n        const count = segment.primitiveLength * 3 * 2; // One triangle corresponds to 3 lines (each has 2 indices)\n        const offset = segment.primitiveOffset * 3 * 2 * 2; // One triangles corresponds to 3 lines (2 indices * 2 bytes per index)\n\n        if (instanceCount && instanceCount > 1) {\n            gl.drawElementsInstanced(\n                gl.LINES,\n                count,\n                gl.UNSIGNED_SHORT,\n                offset,\n                instanceCount);\n        } else {\n            gl.drawElements(\n                gl.LINES,\n                count,\n                gl.UNSIGNED_SHORT,\n                offset\n            );\n        }\n\n        // Revert to non-wireframe parameters\n        indexBuffer.bind();\n        context.program.set(this.program);\n        context.setDepthMode(depthMode);\n        context.setStencilMode(stencilMode);\n        context.setColorMode(colorMode);\n    }\n\n    draw(\n         painter: Painter,\n         drawMode: DrawMode,\n         depthMode: Readonly<DepthMode>,\n         stencilMode: Readonly<StencilMode>,\n         colorMode: Readonly<ColorMode>,\n         cullFaceMode: Readonly<CullFaceMode>,\n         uniformValues: UniformValues<Us>,\n         layerID: string,\n         layoutVertexBuffer: VertexBuffer,\n         indexBuffer: IndexBuffer | undefined,\n         segments: SegmentVector,\n         currentProperties: any,\n         zoom?: number | null,\n         configuration?: ProgramConfiguration | null,\n         dynamicLayoutBuffers?: Array<VertexBuffer | null | undefined> | null,\n         instanceCount?: number | null) {\n\n        const context = painter.context;\n        const gl = context.gl;\n\n        if (this.failedToCreate) return;\n\n        context.program.set(this.program);\n        context.setDepthMode(depthMode);\n        context.setStencilMode(stencilMode);\n        context.setColorMode(colorMode);\n        context.setCullFace(cullFaceMode);\n\n        for (const name of Object.keys(this.fixedUniforms)) {\n            this.fixedUniforms[name].set(this.program, name, uniformValues[name]);\n        }\n\n        if (configuration) {\n            configuration.setUniforms(this.program, context, this.binderUniforms, currentProperties, {zoom: (zoom as any)});\n        }\n\n        const primitiveSize = {\n            [gl.POINTS]: 1,\n            [gl.LINES]: 2,\n            [gl.TRIANGLES]: 3,\n            [gl.LINE_STRIP]: 1\n        }[drawMode];\n\n        const vertexAttribDivisorValue = instanceCount && instanceCount > 0 ? 1 : undefined;\n        for (const segment of segments.get()) {\n            const vaos = segment.vaos || (segment.vaos = {});\n            const vao: VertexArrayObject = vaos[layerID] || (vaos[layerID] = new VertexArrayObject());\n            vao.bind(\n                context,\n                this,\n                layoutVertexBuffer,\n                configuration ? configuration.getPaintVertexBuffers() : [],\n                indexBuffer,\n                segment.vertexOffset,\n                dynamicLayoutBuffers ? dynamicLayoutBuffers : [],\n                vertexAttribDivisorValue\n            );\n\n            if (instanceCount && instanceCount > 1) {\n                assert(indexBuffer);\n                gl.drawElementsInstanced(\n                    drawMode,\n                    segment.primitiveLength * primitiveSize,\n                    gl.UNSIGNED_SHORT,\n                    segment.primitiveOffset * primitiveSize * 2,\n                    instanceCount);\n            } else if (indexBuffer) {\n                gl.drawElements(\n                    drawMode,\n                    segment.primitiveLength * primitiveSize,\n                    gl.UNSIGNED_SHORT,\n                    segment.primitiveOffset * primitiveSize * 2);\n            } else {\n                gl.drawArrays(drawMode, segment.vertexOffset, segment.vertexLength);\n            }\n            if (drawMode === gl.TRIANGLES && indexBuffer) {\n                // Handle potential wireframe rendering for current draw call\n                this._drawDebugWireframe(painter, depthMode, stencilMode, colorMode, indexBuffer, segment,\n                    currentProperties, zoom, configuration, instanceCount);\n            }\n        }\n    }\n}\n\nexport default Program;\n","import Context from '../gl/context';\nimport Fog from '../style/fog';\nimport {Uniform1f, Uniform1i, Uniform2f, Uniform3f, Uniform4f, UniformMatrix4f} from './uniform_binding';\nimport {globeToMercatorTransition} from '../geo/projection/globe_util';\n\nimport type {UniformValues} from './uniform_binding';\nimport type {UnwrappedTileID} from '../source/tile_id';\nimport type Painter from './painter';\n\nexport type FogUniformsType = {\n    ['u_fog_matrix']: UniformMatrix4f;\n    ['u_fog_range']: Uniform2f;\n    ['u_fog_color']: Uniform4f;\n    ['u_fog_horizon_blend']: Uniform1f;\n    ['u_fog_vertical_limit']: Uniform2f;\n    ['u_fog_temporal_offset']: Uniform1f;\n    ['u_frustum_tl']: Uniform3f;\n    ['u_frustum_tr']: Uniform3f;\n    ['u_frustum_br']: Uniform3f;\n    ['u_frustum_bl']: Uniform3f;\n    ['u_globe_pos']: Uniform3f;\n    ['u_globe_radius']: Uniform1f;\n    ['u_globe_transition']: Uniform1f;\n    ['u_is_globe']: Uniform1i;\n    ['u_viewport']: Uniform2f;\n};\n\nexport const fogUniforms = (context: Context): FogUniformsType => ({\n    'u_fog_matrix': new UniformMatrix4f(context),\n    'u_fog_range': new Uniform2f(context),\n    'u_fog_color': new Uniform4f(context),\n    'u_fog_horizon_blend': new Uniform1f(context),\n    'u_fog_vertical_limit': new Uniform2f(context),\n    'u_fog_temporal_offset': new Uniform1f(context),\n    'u_frustum_tl': new Uniform3f(context),\n    'u_frustum_tr': new Uniform3f(context),\n    'u_frustum_br': new Uniform3f(context),\n    'u_frustum_bl': new Uniform3f(context),\n    'u_globe_pos': new Uniform3f(context),\n    'u_globe_radius': new Uniform1f(context),\n    'u_globe_transition': new Uniform1f(context),\n    'u_is_globe': new Uniform1i(context),\n    'u_viewport': new Uniform2f(context)\n});\n\nexport const fogUniformValues = (\n    painter: Painter,\n    fog: Fog,\n    tileID: UnwrappedTileID | null | undefined,\n    fogOpacity: number,\n    frustumDirTl: [number, number, number],\n    frustumDirTr: [number, number, number],\n    frustumDirBr: [number, number, number],\n    frustumDirBl: [number, number, number],\n    globePosition: [number, number, number],\n    globeRadius: number,\n    viewport: [number, number],\n    fogMatrix?: Float32Array | null,\n): UniformValues<FogUniformsType> => {\n    const tr = painter.transform;\n\n    const fogColor = fog.properties.get('color').toRenderColor(painter.style.getLut(fog.scope)).toArray01();\n    fogColor[3] = fogOpacity; // Update Alpha\n    const temporalOffset = (painter.frameCounter / 1000.0) % 1;\n\n    const [verticalRangeMin, verticalRangeMax] = fog.properties.get('vertical-range');\n    return {\n        'u_fog_matrix': tileID ? tr.calculateFogTileMatrix(tileID) : fogMatrix ? fogMatrix : painter.identityMat,\n        'u_fog_range': fog.getFovAdjustedRange(tr._fov),\n        'u_fog_color': fogColor,\n        'u_fog_horizon_blend': fog.properties.get('horizon-blend'),\n        'u_fog_vertical_limit': [Math.min(verticalRangeMin, verticalRangeMax), verticalRangeMax],\n        'u_fog_temporal_offset': temporalOffset,\n        'u_frustum_tl': frustumDirTl,\n        'u_frustum_tr': frustumDirTr,\n        'u_frustum_br': frustumDirBr,\n        'u_frustum_bl': frustumDirBl,\n        'u_globe_pos': globePosition,\n        'u_globe_radius': globeRadius,\n        'u_viewport': viewport,\n        'u_globe_transition': globeToMercatorTransition(tr.zoom),\n        'u_is_globe': +(tr.projection.name === 'globe')\n    };\n};\n","import assert from 'assert';\nimport {\n    Uniform1i,\n    Uniform1f,\n    Uniform2f\n} from '../uniform_binding';\nimport pixelsToTileUnits from '../../source/pixels_to_tile_units';\n\nimport type Painter from '../painter';\nimport type {OverscaledTileID} from '../../source/tile_id';\nimport type {UniformValues} from '../uniform_binding';\nimport type Tile from '../../source/tile';\nimport type ResolvedImage from '../../style-spec/expression/types/resolved_image';\nimport type {ImagePosition} from \"../image_atlas\";\n\ntype BackgroundPatternUniformsType = {\n    ['u_image']: Uniform1i;\n    ['u_pattern_tl']: Uniform2f;\n    ['u_pattern_br']: Uniform2f;\n    ['u_texsize']: Uniform2f;\n    ['u_pattern_size']: Uniform2f;\n    ['u_pixel_coord_upper']: Uniform2f;\n    ['u_pixel_coord_lower']: Uniform2f;\n    ['u_tile_units_to_pixels']: Uniform1f;\n};\n\nexport type PatternUniformsType = {\n    ['u_image']: Uniform1i;\n    ['u_texsize']: Uniform2f;\n    ['u_tile_units_to_pixels']: Uniform1f;\n    ['u_pixel_coord_upper']: Uniform2f;\n    ['u_pixel_coord_lower']: Uniform2f;\n};\n\nfunction patternUniformValues(painter: Painter, tile: Tile): UniformValues<PatternUniformsType> {\n\n    const numTiles = Math.pow(2, tile.tileID.overscaledZ);\n    const tileSizeAtNearestZoom = tile.tileSize * Math.pow(2, painter.transform.tileZoom) / numTiles;\n\n    const pixelX = tileSizeAtNearestZoom * (tile.tileID.canonical.x + tile.tileID.wrap * numTiles);\n    const pixelY = tileSizeAtNearestZoom * tile.tileID.canonical.y;\n\n    return {\n        'u_image': 0,\n        'u_texsize': tile.imageAtlasTexture ? tile.imageAtlasTexture.size : [0, 0],\n        'u_tile_units_to_pixels': 1 / pixelsToTileUnits(tile, 1, painter.transform.tileZoom),\n        // split the pixel coord into two pairs of 16 bit numbers. The glsl spec only guarantees 16 bits of precision.\n        'u_pixel_coord_upper': [pixelX >> 16, pixelY >> 16],\n        'u_pixel_coord_lower': [pixelX & 0xFFFF, pixelY & 0xFFFF]\n    };\n}\n\nfunction bgPatternUniformValues(\n    image: ResolvedImage,\n    scope: string,\n    patternPosition: ImagePosition | null | undefined,\n    painter: Painter,\n    tile: {\n        tileID: OverscaledTileID;\n        tileSize: number;\n    },\n): UniformValues<BackgroundPatternUniformsType> {\n    assert(patternPosition);\n    const {width, height} = painter.imageManager.getPixelSize(scope);\n\n    const numTiles = Math.pow(2, tile.tileID.overscaledZ);\n    const tileSizeAtNearestZoom = tile.tileSize * Math.pow(2, painter.transform.tileZoom) / numTiles;\n\n    const pixelX = tileSizeAtNearestZoom * (tile.tileID.canonical.x + tile.tileID.wrap * numTiles);\n    const pixelY = tileSizeAtNearestZoom * tile.tileID.canonical.y;\n\n    return {\n        'u_image': 0,\n        'u_pattern_tl': (patternPosition as any).tl,\n        'u_pattern_br': (patternPosition as any).br,\n        'u_texsize': [width, height],\n        'u_pattern_size': (patternPosition as any).displaySize,\n        'u_tile_units_to_pixels': 1 / pixelsToTileUnits(tile, 1, painter.transform.tileZoom),\n        // split the pixel coord into two pairs of 16 bit numbers. The glsl spec only guarantees 16 bits of precision.\n        'u_pixel_coord_upper': [pixelX >> 16, pixelY >> 16],\n        'u_pixel_coord_lower': [pixelX & 0xFFFF, pixelY & 0xFFFF]\n    };\n}\nexport {bgPatternUniformValues, patternUniformValues};\n","import {patternUniformValues} from './pattern';\nimport {\n    Uniform1i,\n    Uniform1f,\n    Uniform2f,\n    Uniform3f,\n    UniformMatrix4f\n} from '../uniform_binding';\nimport {mat3, mat4, vec3} from 'gl-matrix';\nimport {extend} from '../../util/util';\nimport type Context from '../../gl/context';\nimport type Painter from '../painter';\nimport type {UniformValues} from '../uniform_binding';\nimport type Tile from '../../source/tile';\nimport {CanonicalTileID, OverscaledTileID} from '../../source/tile_id';\nimport EXTENT from '../../style-spec/data/extent';\n\nexport type FillExtrusionUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n    ['u_lightpos']: Uniform3f;\n    ['u_lightintensity']: Uniform1f;\n    ['u_lightcolor']: Uniform3f;\n    ['u_vertical_gradient']: Uniform1f;\n    ['u_opacity']: Uniform1f;\n    // globe uniforms:\n    ['u_tile_id']: Uniform3f;\n    ['u_zoom_transition']: Uniform1f;\n    ['u_inv_rot_matrix']: UniformMatrix4f;\n    ['u_merc_center']: Uniform2f;\n    ['u_up_dir']: Uniform3f;\n    ['u_height_lift']: Uniform1f;\n    ['u_ao']: Uniform2f;\n    ['u_edge_radius']: Uniform1f;\n    ['u_alignment']: Uniform1f;\n    ['u_width_scale']: Uniform1f;\n    ['u_flood_light_color']: Uniform3f;\n    ['u_vertical_scale']: Uniform1f;\n    ['u_flood_light_intensity']: Uniform1f;\n    ['u_ground_shadow_factor']: Uniform3f;\n    ['u_emissive_strength']: Uniform1f;\n};\n\nexport t