'u_pixel_coord_lower': new Uniform2f(context),\n    'u_tile_units_to_pixels': new Uniform1f(context),\n    'u_opacity': new Uniform1f(context)\n});\n\nconst fillExtrusionGroundEffectUniforms = (context: Context): FillExtrusionGroundEffectUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context),\n    'u_opacity': new Uniform1f(context),\n    'u_ao_pass': new Uniform1f(context),\n    'u_meter_to_tile': new Uniform1f(context),\n    'u_ao': new Uniform2f(context),\n    'u_flood_light_intensity': new Uniform1f(context),\n    'u_flood_light_color': new Uniform3f(context),\n    'u_attenuation': new Uniform1f(context),\n    'u_edge_radius': new Uniform1f(context),\n    'u_fb': new Uniform1i(context),\n    'u_fb_size': new Uniform1f(context)\n});\n\nconst identityMatrix = mat4.create() as Float32Array;\n\nconst fillExtrusionUniformValues = (\n    matrix: Float32Array,\n    painter: Painter,\n    shouldUseVerticalGradient: boolean,\n    opacity: number,\n    aoIntensityRadius: [number, number],\n    edgeRadius: number,\n    lineAlignment: number,\n    lineWidthScale: number,\n    coord: OverscaledTileID,\n    heightLift: number,\n    zoomTransition: number,\n    mercatorCenter: [number, number],\n    invMatrix: Float32Array,\n    floodLightColor: [number, number, number],\n    verticalScale: number,\n    floodLightIntensity: number,\n    groundShadowFactor: [number, number, number],\n    emissiveStrength: number,\n): UniformValues<FillExtrusionUniformsType> => {\n    const light = painter.style.light;\n    const _lp = light.properties.get('position');\n    const lightPos: [number, number, number] = [_lp.x, _lp.y, _lp.z];\n    const lightMat = mat3.create();\n    const anchor = light.properties.get('anchor');\n    if (anchor === 'viewport') {\n        mat3.fromRotation(lightMat, -painter.transform.angle);\n        vec3.transformMat3(lightPos, lightPos, lightMat);\n    }\n\n    const lightColor = light.properties.get('color');\n    const tr = painter.transform;\n\n    const uniformValues = {\n        'u_matrix': matrix,\n        'u_lightpos': lightPos,\n        'u_lightintensity': light.properties.get('intensity'),\n\n        'u_lightcolor': [lightColor.r, lightColor.g, lightColor.b] as [number, number, number],\n        'u_vertical_gradient': +shouldUseVerticalGradient,\n        'u_opacity': opacity,\n        'u_tile_id': [0, 0, 0] as [number, number, number],\n        'u_zoom_transition': 0,\n        'u_inv_rot_matrix': identityMatrix,\n        'u_merc_center': [0, 0] as [number, number],\n        'u_up_dir': [0, 0, 0] as [number, number, number],\n        'u_height_lift': 0,\n        'u_ao': aoIntensityRadius,\n        'u_edge_radius': edgeRadius,\n        'u_alignment': lineAlignment,\n        'u_width_scale': lineWidthScale,\n        'u_flood_light_color': floodLightColor,\n        'u_vertical_scale': verticalScale,\n        'u_flood_light_intensity': floodLightIntensity,\n        'u_ground_shadow_factor': groundShadowFactor,\n        'u_emissive_strength': emissiveStrength\n    };\n\n    if (tr.projection.name === 'globe') {\n        uniformValues['u_tile_id'] = [coord.canonical.x, coord.canonical.y, 1 << coord.canonical.z];\n        uniformValues['u_zoom_transition'] = zoomTransition;\n        uniformValues['u_inv_rot_matrix'] = invMatrix;\n        uniformValues['u_merc_center'] = mercatorCenter;\n        uniformValues['u_up_dir'] = (tr.projection.upVector(new CanonicalTileID(0, 0, 0), mercatorCenter[0] * EXTENT, mercatorCenter[1] * EXTENT) as any);\n        uniformValues['u_height_lift'] = heightLift;\n    }\n\n    return uniformValues;\n};\n\nconst fillExtrusionDepthUniformValues = (matrix: Float32Array, edgeRadius: number, lineAlignment: number, lineWidthScale: number, verticalScale: number): UniformValues<FillExtrusionDepthUniformsType> => {\n    return {\n        'u_matrix': matrix,\n        'u_edge_radius': edgeRadius,\n        'u_alignment': lineAlignment,\n        'u_width_scale': lineWidthScale,\n        'u_vertical_scale': verticalScale\n    };\n};\n\nconst fillExtrusionPatternUniformValues = (\n    matrix: Float32Array,\n    painter: Painter,\n    shouldUseVerticalGradient: boolean,\n    opacity: number,\n    aoIntensityRadius: [number, number],\n    edgeRadius: number,\n    lineAlignment: number,\n    lineWidthScale: number,\n    coord: OverscaledTileID,\n    tile: Tile,\n    heightLift: number,\n    zoomTransition: number,\n    mercatorCenter: [number, number],\n    invMatrix: Float32Array,\n    floodLightColor: [number, number, number],\n    verticalScale: number,\n): UniformValues<FillExtrusionPatternUniformsType> => {\n    const uniformValues = fillExtrusionUniformValues(\n        matrix, painter, shouldUseVerticalGradient, opacity, aoIntensityRadius, edgeRadius, lineAlignment, lineWidthScale, coord,\n        heightLift, zoomTransition, mercatorCenter, invMatrix, floodLightColor, verticalScale, 1.0, [0, 0, 0], 0);\n    const heightFactorUniform = {\n        'u_height_factor': -Math.pow(2, coord.overscaledZ) / tile.tileSize / 8\n    };\n    return extend(uniformValues, patternUniformValues(painter, tile), heightFactorUniform);\n};\n\nconst fillExtrusionGroundEffectUniformValues = (\n    painter: Painter,\n    matrix: Float32Array,\n    opacity: number,\n    aoPass: boolean,\n    meterToTile: number,\n    ao: [number, number],\n    floodLightIntensity: number,\n    floodLightColor: [number, number, number],\n    attenuation: number,\n    edgeRadius: number,\n    fbSize: number,\n): UniformValues<FillExtrusionGroundEffectUniformsType> => {\n    const uniformValues = {\n        'u_matrix': matrix,\n        'u_opacity': opacity,\n        'u_ao_pass': aoPass ? 1 : 0,\n        'u_meter_to_tile': meterToTile,\n        'u_ao': ao,\n        'u_flood_light_intensity': floodLightIntensity,\n        'u_flood_light_color': floodLightColor,\n        'u_attenuation': attenuation,\n        'u_edge_radius': edgeRadius,\n        'u_fb': 0,\n        'u_fb_size': fbSize\n    };\n    return uniformValues;\n};\n\nexport {\n    fillExtrusionUniforms,\n    fillExtrusionDepthUniforms,\n    fillExtrusionPatternUniforms,\n    fillExtrusionUniformValues,\n    fillExtrusionDepthUniformValues,\n    fillExtrusionPatternUniformValues,\n    fillExtrusionGroundEffectUniforms,\n    fillExtrusionGroundEffectUniformValues\n};\n","import {patternUniformValues} from './pattern';\nimport {\n    Uniform1i,\n    Uniform1f,\n    Uniform2f,\n    UniformMatrix4f\n} from '../uniform_binding';\nimport {extend} from '../../util/util';\n\nimport type Painter from '../painter';\nimport type {UniformValues} from '../uniform_binding';\nimport type Context from '../../gl/context';\nimport type Tile from '../../source/tile';\n\nexport type FillUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n    ['u_emissive_strength']: Uniform1f;\n};\n\nexport type FillOutlineUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n    ['u_emissive_strength']: Uniform1f;\n    ['u_world']: Uniform2f;\n};\n\nexport type FillPatternUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n    ['u_emissive_strength']: Uniform1f;\n    // pattern uniforms:\n    ['u_texsize']: Uniform2f;\n    ['u_image']: Uniform1i;\n    ['u_pixel_coord_upper']: Uniform2f;\n    ['u_pixel_coord_lower']: Uniform2f;\n    ['u_tile_units_to_pixels']: Uniform1f;\n};\n\nexport type FillOutlinePatternUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n    ['u_emissive_strength']: Uniform1f;\n    ['u_world']: Uniform2f;\n    // pattern uniforms:\n    ['u_texsize']: Uniform2f;\n    ['u_image']: Uniform1i;\n    ['u_pixel_coord_upper']: Uniform2f;\n    ['u_pixel_coord_lower']: Uniform2f;\n    ['u_tile_units_to_pixels']: Uniform1f;\n};\n\nconst fillUniforms = (context: Context): FillUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context),\n    'u_emissive_strength': new Uniform1f(context)\n});\n\nconst fillPatternUniforms = (context: Context): FillPatternUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context),\n    'u_emissive_strength': new Uniform1f(context),\n    'u_image': new Uniform1i(context),\n    'u_texsize': new Uniform2f(context),\n    'u_pixel_coord_upper': new Uniform2f(context),\n    'u_pixel_coord_lower': new Uniform2f(context),\n    'u_tile_units_to_pixels': new Uniform1f(context)\n});\n\nconst fillOutlineUniforms = (context: Context): FillOutlineUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context),\n    'u_emissive_strength': new Uniform1f(context),\n    'u_world': new Uniform2f(context)\n});\n\nconst fillOutlinePatternUniforms = (context: Context): FillOutlinePatternUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context),\n    'u_emissive_strength': new Uniform1f(context),\n    'u_world': new Uniform2f(context),\n    'u_image': new Uniform1i(context),\n    'u_texsize': new Uniform2f(context),\n    'u_pixel_coord_upper': new Uniform2f(context),\n    'u_pixel_coord_lower': new Uniform2f(context),\n    'u_tile_units_to_pixels': new Uniform1f(context)\n});\n\nconst fillUniformValues = (matrix: Float32Array, emissiveStrength: number): UniformValues<FillUniformsType> => ({\n    'u_matrix': matrix,\n    'u_emissive_strength': emissiveStrength\n});\n\nconst fillPatternUniformValues = (\n    matrix: Float32Array,\n    emissiveStrength: number,\n    painter: Painter,\n    tile: Tile,\n): UniformValues<FillPatternUniformsType> => extend(\n    fillUniformValues(matrix, emissiveStrength),\n    patternUniformValues(painter, tile)\n);\n\nconst fillOutlineUniformValues = (\n    matrix: Float32Array,\n    emissiveStrength: number,\n    drawingBufferSize: [number, number],\n): UniformValues<FillOutlineUniformsType> => ({\n    'u_matrix': matrix,\n    'u_world': drawingBufferSize,\n    'u_emissive_strength': emissiveStrength\n});\n\nconst fillOutlinePatternUniformValues = (\n    matrix: Float32Array,\n    emissiveStrength: number,\n    painter: Painter,\n    tile: Tile,\n    drawingBufferSize: [number, number],\n): UniformValues<FillOutlinePatternUniformsType> => extend(\n    fillPatternUniformValues(matrix, emissiveStrength, painter, tile),\n    {\n        'u_world': drawingBufferSize\n    }\n);\n\nexport {\n    fillUniforms,\n    fillPatternUniforms,\n    fillOutlineUniforms,\n    fillOutlinePatternUniforms,\n    fillUniformValues,\n    fillPatternUniformValues,\n    fillOutlineUniformValues,\n    fillOutlinePatternUniformValues\n};\n","import {Uniform1f, Uniform2f, UniformMatrix4f} from '../uniform_binding';\nimport EXTENT from '../../style-spec/data/extent';\nimport type Context from '../../gl/context';\nimport type {UniformValues} from '../uniform_binding';\nimport type Transform from '../../geo/transform';\nimport type Tile from '../../source/tile';\nimport type Projection from '../../geo/projection/projection';\n\nexport type CollisionUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n    ['u_camera_to_center_distance']: Uniform1f;\n    ['u_extrude_scale']: Uniform2f;\n};\n\nexport type CollisionCircleUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n    ['u_inv_matrix']: UniformMatrix4f;\n    ['u_camera_to_center_distance']: Uniform1f;\n    ['u_viewport_size']: Uniform2f;\n};\n\nconst collisionUniforms = (context: Context): CollisionUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context),\n    'u_camera_to_center_distance': new Uniform1f(context),\n    'u_extrude_scale': new Uniform2f(context)\n});\n\nconst collisionCircleUniforms = (context: Context): CollisionCircleUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context),\n    'u_inv_matrix': new UniformMatrix4f(context),\n    'u_camera_to_center_distance': new Uniform1f(context),\n    'u_viewport_size': new Uniform2f(context)\n});\n\nconst collisionUniformValues = (\n    matrix: Float32Array,\n    transform: Transform,\n    tile: Tile,\n    projection: Projection,\n): UniformValues<CollisionUniformsType> => {\n    const pixelRatio = EXTENT / tile.tileSize;\n\n    return {\n        'u_matrix': matrix,\n        'u_camera_to_center_distance': transform.getCameraToCenterDistance(projection),\n        'u_extrude_scale': [transform.pixelsToGLUnits[0] / pixelRatio,\n            transform.pixelsToGLUnits[1] / pixelRatio]\n    };\n};\n\nconst collisionCircleUniformValues = (\n    matrix: Float32Array,\n    invMatrix: Float32Array,\n    transform: Transform,\n    projection: Projection,\n): UniformValues<CollisionCircleUniformsType> => {\n    return {\n        'u_matrix': matrix,\n        'u_inv_matrix': invMatrix,\n        'u_camera_to_center_distance': transform.getCameraToCenterDistance(projection),\n        'u_viewport_size': [transform.width, transform.height]\n    };\n};\n\nexport {collisionUniforms, collisionUniformValues, collisionCircleUniforms, collisionCircleUniformValues};\n","import {UniformColor, UniformMatrix4f, Uniform1i, Uniform1f} from '../uniform_binding';\n\nimport type Context from '../../gl/context';\nimport type {UniformValues} from '../uniform_binding';\nimport type Color from '../../style-spec/util/color';\n\nexport type DebugUniformsType = {\n    ['u_color']: UniformColor;\n    ['u_matrix']: UniformMatrix4f;\n    ['u_overlay']: Uniform1i;\n    ['u_overlay_scale']: Uniform1f;\n};\n\nconst debugUniforms = (context: Context): DebugUniformsType => ({\n    'u_color': new UniformColor(context),\n    'u_matrix': new UniformMatrix4f(context),\n    'u_overlay': new Uniform1i(context),\n    'u_overlay_scale':  new Uniform1f(context),\n});\n\nconst debugUniformValues = (matrix: Float32Array, color: Color, scaleRatio: number = 1): UniformValues<DebugUniformsType> => ({\n    'u_matrix': matrix,\n    'u_color': color.toRenderColor(null),\n    'u_overlay': 0,\n    'u_overlay_scale': scaleRatio\n});\n\nexport {debugUniforms, debugUniformValues};\n\nexport type DebugDefinesType = 'PROJECTION_GLOBE_VIEW';\n","import {Uniform1i, Uniform1f, Uniform2f, Uniform3f, UniformMatrix4f} from '../uniform_binding';\nimport pixelsToTileUnits from '../../source/pixels_to_tile_units';\n\nimport type Context from '../../gl/context';\nimport type Tile from '../../source/tile';\nimport type {UniformValues} from '../uniform_binding';\nimport type Painter from '../painter';\nimport type HeatmapStyleLayer from '../../style/style_layer/heatmap_style_layer';\nimport {CanonicalTileID, OverscaledTileID} from '../../source/tile_id';\nimport {mat4} from 'gl-matrix';\nimport {globeToMercatorTransition, globePixelsToTileUnits} from '../../geo/projection/globe_util';\nimport EXTENT from '../../style-spec/data/extent';\n\nexport type HeatmapUniformsType = {\n    ['u_extrude_scale']: Uniform1f;\n    ['u_intensity']: Uniform1f;\n    ['u_matrix']: UniformMatrix4f;\n    ['u_inv_rot_matrix']: UniformMatrix4f;\n    ['u_merc_center']: Uniform2f;\n    ['u_tile_id']: Uniform3f;\n    ['u_zoom_transition']: Uniform1f;\n    ['u_up_dir']: Uniform3f;\n};\n\nexport type HeatmapTextureUniformsType = {\n    ['u_image']: Uniform1i;\n    ['u_color_ramp']: Uniform1i;\n    ['u_opacity']: Uniform1f;\n};\n\nconst heatmapUniforms = (context: Context): HeatmapUniformsType => ({\n    'u_extrude_scale': new Uniform1f(context),\n    'u_intensity': new Uniform1f(context),\n    'u_matrix': new UniformMatrix4f(context),\n    'u_inv_rot_matrix': new UniformMatrix4f(context),\n    'u_merc_center': new Uniform2f(context),\n    'u_tile_id': new Uniform3f(context),\n    'u_zoom_transition': new Uniform1f(context),\n    'u_up_dir': new Uniform3f(context)\n});\n\nconst heatmapTextureUniforms = (context: Context): HeatmapTextureUniformsType => ({\n    'u_image': new Uniform1i(context),\n    'u_color_ramp': new Uniform1i(context),\n    'u_opacity': new Uniform1f(context)\n});\n\nconst identityMatrix = mat4.create() as Float32Array;\n\nconst heatmapUniformValues = (\n    painter: Painter,\n    coord: OverscaledTileID,\n    tile: Tile,\n    invMatrix: Float32Array,\n    mercatorCenter: [number, number],\n    zoom: number,\n    intensity: number,\n): UniformValues<HeatmapUniformsType> => {\n    const transform = painter.transform;\n    const isGlobe = transform.projection.name === 'globe';\n    const extrudeScale = isGlobe ? globePixelsToTileUnits(transform.zoom, coord.canonical) * transform._pixelsPerMercatorPixel : pixelsToTileUnits(tile, 1, zoom);\n\n    const values = {\n        'u_matrix': coord.projMatrix,\n        'u_extrude_scale': extrudeScale,\n        'u_intensity': intensity,\n        'u_inv_rot_matrix': identityMatrix,\n        'u_merc_center': [0, 0] as [number, number],\n        'u_tile_id': [0, 0, 0] as [number, number, number],\n        'u_zoom_transition': 0,\n        'u_up_dir': [0, 0, 0] as [number, number, number]\n    };\n\n    if (isGlobe) {\n        values['u_inv_rot_matrix'] = invMatrix;\n        values['u_merc_center'] = mercatorCenter;\n        values['u_tile_id'] = [coord.canonical.x, coord.canonical.y, 1 << coord.canonical.z];\n        values['u_zoom_transition'] = globeToMercatorTransition(transform.zoom);\n        const x = mercatorCenter[0] * EXTENT;\n        const y = mercatorCenter[1] * EXTENT;\n        values['u_up_dir'] = (transform.projection.upVector(new CanonicalTileID(0, 0, 0), x, y) as any);\n    }\n\n    return values;\n};\n\nconst heatmapTextureUniformValues = (\n    painter: Painter,\n    layer: HeatmapStyleLayer,\n    textureUnit: number,\n    colorRampUnit: number,\n): UniformValues<HeatmapTextureUniformsType> => {\n    return {\n        'u_image': textureUnit,\n        'u_color_ramp': colorRampUnit,\n        'u_opacity': layer.paint.get('heatmap-opacity')\n    };\n};\n\nexport {\n    heatmapUniforms,\n    heatmapTextureUniforms,\n    heatmapUniformValues,\n    heatmapTextureUniformValues\n};\n\nexport type HeatmapDefinesType = 'PROJECTION_GLOBE_VIEW';\n","function computeRasterColorMix(\n    colorRampRes: number,\n    [mixR, mixG, mixB, mixA]: [any, any, any, any],\n    [min, max]: [any, any],\n): [number, number, number, number] {\n    if (min === max) return [0, 0, 0, 0];\n\n    // Together with the `offset`, the mix vector transforms the encoded integer\n    // input into a numeric value. To minimize work, we modify this vector to\n    // perform extra steps on the CPU, before rendering.\n    //\n    // To a first cut, we map `min` to the texture coordinate 0, and `max` to texture\n    // coordinate 1. However, this would align the samples with the *edges* of\n    // tabulated texels rather than the centers. This  makes it difficult to precisely\n    // position values relative to the tabulated colors.\n    //\n    // Therefore given color map resolution N, we actually map `min` to 1 / 2N and\n    // `max` to 1 - 1 / 2N. When you work out a few lines of algebra, the scale factor\n    // below is the result.\n    //\n    // Similarly, computerRasterColorOffset contains the counterpart of this equation\n    // by which the constant offset is adjusted.\n    const factor = 255 * (colorRampRes - 1) / (colorRampRes * (max - min));\n\n    return [\n        mixR * factor,\n        mixG * factor,\n        mixB * factor,\n        mixA * factor\n    ];\n}\n\nfunction computeRasterColorOffset(colorRampRes: number, offset: number, [min, max]: [any, any]): number {\n    if (min === max) return 0;\n\n    // See above for an explanation.\n    return 0.5 / colorRampRes + (offset - min) * (colorRampRes - 1) / (colorRampRes * (max - min));\n}\n\nexport {computeRasterColorMix, computeRasterColorOffset};\n","import {\n    Uniform1i,\n    Uniform1f,\n    Uniform2f,\n    Uniform3f,\n    Uniform4f,\n    UniformMatrix3f,\n    UniformMatrix4f,\n} from '../uniform_binding';\n\nimport {computeRasterColorMix, computeRasterColorOffset} from '../raster';\nimport {COLOR_RAMP_RES} from '../../style/style_layer/raster_style_layer';\nimport {contrastFactor, saturationFactor} from '../../util/util';\n\nimport type Context from '../../gl/context';\nimport type {UniformValues} from '../uniform_binding';\nimport type RasterStyleLayer from '../../style/style_layer/raster_style_layer';\n\nexport type RasterUniformsType = {\n    ['u_matrix']: Un