} from './hillshade_program';\nimport {lineUniforms, linePatternUniforms} from './line_program';\nimport {rasterUniforms} from './raster_program';\nimport {rasterParticleUniforms, rasterParticleTextureUniforms, rasterParticleDrawUniforms, rasterParticleUpdateUniforms} from './raster_particle_program';\nimport {symbolIconUniforms, symbolSDFUniforms, symbolTextAndIconUniforms} from './symbol_program';\nimport {backgroundUniforms, backgroundPatternUniforms} from './background_program';\nimport {terrainRasterUniforms} from '../../terrain/terrain_raster_program';\nimport {skyboxUniforms, skyboxGradientUniforms} from './skybox_program';\nimport {skyboxCaptureUniforms} from './skybox_capture_program';\nimport {globeRasterUniforms, atmosphereUniforms} from '../../terrain/globe_raster_program';\nimport type {HeatmapDefinesType} from './heatmap_program';\nimport type {DebugDefinesType} from './debug_program';\nimport type {GlobeDefinesType} from '../../terrain/globe_raster_program';\n\nimport {modelUniforms, modelDepthUniforms} from '../../../3d-style/render/program/model_program';\nimport {groundShadowUniforms} from '../../../3d-style/render/program/ground_shadow_program';\nimport {starsUniforms} from '../../terrain/stars_program';\nimport {occlusionUniforms} from './occlusion_program';\n\nexport type FogDefinesType = ['FOG', 'FOG_DITHERING'];\nexport type TerrainDepthAccessDefinesType = 'DEPTH_D24' | 'DEPTH_OCCLUSION';\nexport type DynamicDefinesType = CircleDefinesType | SymbolDefinesType | LineDefinesType | HeatmapDefinesType   | GlobeDefinesType | RasterDefinesType | RasterParticleDefinesType | FogDefinesType | HillshadeDefinesType | TerrainDepthAccessDefinesType;\n\nexport const programUniforms = {\n    fillExtrusion: fillExtrusionUniforms,\n    fillExtrusionDepth: fillExtrusionDepthUniforms,\n    fillExtrusionPattern: fillExtrusionPatternUniforms,\n    fillExtrusionGroundEffect: fillExtrusionGroundEffectUniforms,\n    fill: fillUniforms,\n    fillPattern: fillPatternUniforms,\n    fillOutline: fillOutlineUniforms,\n    fillOutlinePattern: fillOutlinePatternUniforms,\n    circle: circleUniforms,\n    collisionBox: collisionUniforms,\n    collisionCircle: collisionCircleUniforms,\n    debug: debugUniforms,\n    clippingMask: clippingMaskUniforms,\n    heatmap: heatmapUniforms,\n    heatmapTexture: heatmapTextureUniforms,\n    hillshade: hillshadeUniforms,\n    hillshadePrepare: hillshadePrepareUniforms,\n    line: lineUniforms,\n    linePattern: linePatternUniforms,\n    raster: rasterUniforms,\n    rasterParticle: rasterParticleUniforms,\n    rasterParticleTexture: rasterParticleTextureUniforms,\n    rasterParticleDraw: rasterParticleDrawUniforms,\n    rasterParticleUpdate: rasterParticleUpdateUniforms,\n    symbolIcon: symbolIconUniforms,\n    symbolSDF: symbolSDFUniforms,\n    symbolTextAndIcon: symbolTextAndIconUniforms,\n    background: backgroundUniforms,\n    backgroundPattern: backgroundPatternUniforms,\n    terrainRaster: terrainRasterUniforms,\n    skybox: skyboxUniforms,\n    skyboxGradient: skyboxGradientUniforms,\n    skyboxCapture: skyboxCaptureUniforms,\n    globeRaster: globeRasterUniforms,\n    globeAtmosphere: atmosphereUniforms,\n    model: modelUniforms,\n    modelDepth: modelDepthUniforms,\n    groundShadow: groundShadowUniforms,\n    stars: starsUniforms,\n    occlusion: occlusionUniforms\n} as const;\n","import {UniformMatrix4f, Uniform1i, Uniform3f, Uniform1f} from '../uniform_binding';\nimport {degToRad} from '../../util/util';\n\nimport type {UniformValues} from '../uniform_binding';\nimport type Context from '../../gl/context';\n\nexport type SkyboxUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n    ['u_sun_direction']: Uniform3f;\n    ['u_cubemap']: Uniform1i;\n    ['u_opacity']: Uniform1f;\n    ['u_temporal_offset']: Uniform1f;\n};\n\nexport type SkyboxGradientlUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n    ['u_color_ramp']: Uniform1i;\n    ['u_center_direction']: Uniform3f;\n    ['u_radius']: Uniform1f;\n    ['u_opacity']: Uniform1f;\n    ['u_temporal_offset']: Uniform1f;\n};\n\nconst skyboxUniforms = (context: Context): SkyboxUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context),\n    'u_sun_direction': new Uniform3f(context),\n    'u_cubemap': new Uniform1i(context),\n    'u_opacity': new Uniform1f(context),\n    'u_temporal_offset': new Uniform1f(context)\n\n});\n\nconst skyboxUniformValues = (\n    matrix: Float32Array,\n    sunDirection: [number, number, number],\n    cubemap: number,\n    opacity: number,\n    temporalOffset: number,\n): UniformValues<SkyboxUniformsType> => ({\n    'u_matrix': matrix,\n    'u_sun_direction': sunDirection,\n    'u_cubemap': cubemap,\n    'u_opacity': opacity,\n    'u_temporal_offset': temporalOffset\n});\n\nconst skyboxGradientUniforms = (context: Context): SkyboxGradientlUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context),\n    'u_color_ramp': new Uniform1i(context),\n    // radial gradient uniforms\n    'u_center_direction': new Uniform3f(context),\n    'u_radius': new Uniform1f(context),\n    'u_opacity': new Uniform1f(context),\n    'u_temporal_offset': new Uniform1f(context)\n});\n\nconst skyboxGradientUniformValues = (\n    matrix: Float32Array,\n    centerDirection: [number, number, number],\n    //degrees\n    radius: number,\n    opacity: number,\n    temporalOffset: number,\n): UniformValues<SkyboxGradientlUniformsType> => {\n    return {\n        'u_matrix': matrix,\n        'u_color_ramp': 0,\n        'u_center_direction': centerDirection,\n        'u_radius': degToRad(radius),\n        'u_opacity': opacity,\n        'u_temporal_offset': temporalOffset\n    };\n};\n\nexport {\n    skyboxUniforms,\n    skyboxUniformValues,\n    skyboxGradientUniforms,\n    skyboxGradientUniformValues\n};\n","import type Color from '../../style-spec/util/color';\n\nimport {\n    UniformMatrix3f,\n    Uniform1f,\n    Uniform3f,\n    Uniform4f,\n} from '../uniform_binding';\nimport type {UniformValues} from '../uniform_binding';\nimport type Context from '../../gl/context';\n\nexport type SkyboxCaptureUniformsType = {\n    ['u_matrix_3f']: UniformMatrix3f;\n    ['u_sun_direction']: Uniform3f;\n    ['u_sun_intensity']: Uniform1f;\n    ['u_color_tint_r']: Uniform4f;\n    ['u_color_tint_m']: Uniform4f;\n    ['u_luminance']: Uniform1f;\n};\n\nconst skyboxCaptureUniforms = (context: Context): SkyboxCaptureUniformsType => ({\n    'u_matrix_3f': new UniformMatrix3f(context),\n    'u_sun_direction': new Uniform3f(context),\n    'u_sun_intensity': new Uniform1f(context),\n    'u_color_tint_r': new Uniform4f(context),\n    'u_color_tint_m': new Uniform4f(context),\n    'u_luminance': new Uniform1f(context),\n});\n\nconst skyboxCaptureUniformValues = (\n    matrix: Float32Array,\n    sunDirection: [number, number, number],\n    sunIntensity: number,\n    atmosphereColor: Color,\n    atmosphereHaloColor: Color,\n): UniformValues<SkyboxCaptureUniformsType> => ({\n    'u_matrix_3f': matrix,\n    'u_sun_direction': sunDirection,\n    'u_sun_intensity': sunIntensity,\n    'u_color_tint_r': [\n        atmosphereColor.r,\n        atmosphereColor.g,\n        atmosphereColor.b,\n        atmosphereColor.a\n    ],\n    'u_color_tint_m': [\n        atmosphereHaloColor.r,\n        atmosphereHaloColor.g,\n        atmosphereHaloColor.b,\n        atmosphereHaloColor.a\n    ],\n    'u_luminance': 5e-5,\n});\n\nexport {\n    skyboxCaptureUniforms,\n    skyboxCaptureUniformValues,\n};\n","import {Uniform3f, UniformMatrix4f, Uniform1f} from '../render/uniform_binding';\n\nimport type Context from '../gl/context';\nimport type {UniformValues} from '../render/uniform_binding';\nimport type {mat4} from 'gl-matrix';\n\nexport type StarsUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n    ['u_up']: Uniform3f;\n    ['u_right']: Uniform3f;\n    ['u_intensity_multiplier']: Uniform1f;\n};\n\nconst starsUniforms = (context: Context): StarsUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context),\n    'u_up': new Uniform3f(context),\n    'u_right': new Uniform3f(context),\n    'u_intensity_multiplier': new Uniform1f(context),\n});\n\nconst starsUniformValues = (\n    matrix: mat4,\n    up: [number, number, number],\n    right: [number, number, number],\n    intensityMultiplier: number,\n): UniformValues<StarsUniformsType> => ({\n    'u_matrix': Float32Array.from(matrix),\n    'u_up': up,\n    'u_right': right,\n    'u_intensity_multiplier': intensityMultiplier\n});\n\nexport {starsUniforms, starsUniformValues};\n","import {Uniform2f, Uniform3f, Uniform4f, UniformMatrix4f} from '../uniform_binding';\nimport type {mat4} from 'gl-matrix';\nimport type Context from '../../gl/context';\nimport type {UniformValues} from '../uniform_binding';\n\nexport type OcclusionUniformsType = {\n    ['u_matrix']: UniformMatrix4f;\n    ['u_anchorPos']: Uniform3f;\n    ['u_screenSizePx']: Uniform2f;\n    ['u_occluderSizePx']: Uniform2f;\n    ['u_color']: Uniform4f;\n};\n\nconst occlusionUniforms = (context: Context): OcclusionUniformsType => ({\n    'u_matrix': new UniformMatrix4f(context),\n    'u_anchorPos': new Uniform3f(context),\n    'u_screenSizePx': new Uniform2f(context),\n    'u_occluderSizePx': new Uniform2f(context),\n    'u_color': new Uniform4f(context)\n});\n\nconst occlusionUniformValues = (\n    matrix: mat4,\n    anchorPos: [number, number, number],\n    screenSize: [number, number],\n    occluderSize: [number, number],\n    color: [number, number, number, number],\n): UniformValues<OcclusionUniformsType> => ({\n    'u_matrix': Float32Array.from(matrix),\n    'u_anchorPos': anchorPos,\n    'u_screenSizePx': screenSize,\n    'u_occluderSizePx': occluderSize,\n    'u_color': color,\n});\n\nexport {occlusionUniforms, occlusionUniformValues};\n","import type {OverscaledTileID} from '../../source/tile_id';\nimport type SymbolBucket from '../../data/bucket/symbol_bucket';\nimport type Transform from '../../geo/transform';\nimport type Projection from './projection';\nimport {mat4} from 'gl-matrix';\nimport assert from 'assert';\n\nfunction reconstructTileMatrix(transform: Transform, projection: Projection, coord: OverscaledTileID) {\n    // Bucket being rendered is built for different map projection\n    // than is currently being used. Reconstruct correct matrices.\n    // This code path may happen during a Globe - Mercator transition\n    const tileMatrix = projection.createTileMatrix(transform, transform.worldSize, coord.toUnwrapped());\n    // @ts-expect-error - TS2345 - Argument of type 'number[] | Float32Array | Float64Array' is not assignable to parameter of type 'ReadonlyMat4'.\n    return mat4.multiply(new Float32Array(16), transform.projMatrix, tileMatrix);\n}\n\nexport function getCollisionDebugTileProjectionMatrix(coord: OverscaledTileID, bucket: SymbolBucket, transform: Transform): Float32Array {\n    if (bucket.projection.name === transform.projection.name) {\n        assert(coord.projMatrix);\n        return coord.projMatrix;\n    }\n    const tr = transform.clone();\n    tr.setProjection(bucket.projection);\n    // @ts-expect-error - TS2322 - Type 'mat4' is not assignable to type 'Float32Array'.\n    return reconstructTileMatrix(tr, bucket.getProjection(), coord);\n}\n\nexport function getSymbolTileProjectionMatrix(\n    coord: OverscaledTileID,\n    bucketProjection: Projection,\n    transform: Transform,\n): Float32Array {\n    if (bucketProjection.name === transform.projection.name) {\n        assert(coord.projMatrix);\n        return coord.projMatrix;\n    }\n    // @ts-expect-error - TS2322 - Type 'mat4' is not assignable to type 'Float32Array'.\n    return reconstructTileMatrix(transform, bucketProjection, coord);\n}\n\nexport function getSymbolPlacementTileProjectionMatrix(\n    coord: OverscaledTileID,\n    bucketProjection: Projection,\n    transform: Transform,\n    runtimeProjection: string,\n): Float32Array {\n    if (bucketProjection.name === runtimeProjection) {\n        return transform.calculateProjMatrix(coord.toUnwrapped());\n    }\n    assert(transform.projection.name === bucketProjection.name);\n    // @ts-expect-error - TS2322 - Type 'mat4' is not assignable to type 'Float32Array'.\n    return reconstructTileMatrix(transform, bucketProjection, coord);\n}\n","import DepthMode from '../gl/depth_mode';\nimport StencilMode from '../gl/stencil_mode';\nimport CullFaceMode from '../gl/cull_face_mode';\nimport {collisionUniformValues, collisionCircleUniformValues} from './program/collision_program';\nimport {QuadTriangleArray, CollisionCircleLayoutArray} from '../data/array_types';\nimport {collisionCircleLayout} from '../data/bucket/symbol_attributes';\nimport SegmentVector from '../data/segment';\nimport {mat4} from 'gl-matrix';\nimport {getCollisionDebugTileProjectionMatrix} from '../geo/projection/projection_util';\nimport VertexBuffer from '../gl/vertex_buffer';\nimport IndexBuffer from '../gl/index_buffer';\n\nimport type Painter from './painter';\nimport type SourceCache from '../source/source_cache';\nimport type StyleLayer from '../style/style_layer';\nimport type {OverscaledTileID} from '../source/tile_id';\nimport type SymbolBucket from '../data/bucket/symbol_bucket';\nimport type Projection from '../geo/projection/projection';\n\nexport default drawCollisionDebug;\n\ntype TileBatch = {\n    circleArray: Array<number>;\n    circleOffset: number;\n    transform: Float32Array;\n    invTransform: Float32Array;\n    projection: Projection;\n};\n\nlet quadTriangles: QuadTriangleArray | null | undefined;\n\nfunction drawCollisionDebug(painter: Painter, sourceCache: SourceCache, layer: StyleLayer, coords: Array<OverscaledTileID>, translate: [number, number], translateAnchor: 'map' | 'viewport', isText: boolean) {\n    const context = painter.context;\n    const gl = context.gl;\n    const tr = painter.transform;\n    const program = painter.getOrCreateProgram('collisionBox');\n    const tileBatches: Array<TileBatch> = [];\n    let circleCount = 0;\n    let circleOffset = 0;\n\n    for (let i = 0; i < coords.length; i++) {\n        const coord = coords[i];\n        const tile = sourceCache.getTile(coord);\n        const bucket: SymbolBucket | null | undefined = (tile.getBucket(layer) as any);\n        if (!bucket) continue;\n\n        const tileMatrix = getCollisionDebugTileProjectionMatrix(coord, bucket, tr);\n\n        let posMatrix = tileMatrix;\n        if (translate[0] !== 0 || translate[1] !== 0) {\n            posMatrix = painter.translatePosMatrix(tileMatrix, tile, translate, translateAnchor);\n        }\n        const buffers = isText ? bucket.textCollisionBox : bucket.iconCollisionBox;\n        // Get collision circle data of this bucket\n        const circleArray: Array<number> = bucket.collisionCircleArray;\n        if (circleArray.length > 0) {\n            // We need to know the projection matrix that was used for projecting collision circles to the screen.\n            // This might vary between buckets as the symbol placement is a continous process. This matrix is\n            // required for transforming points from previous screen space to the current one\n            const invTransform = mat4.create();\n            const transform = posMatrix;\n\n            mat4.mul(invTransform, bucket.placementInvProjMatrix, tr.glCoordMatrix);\n            mat4.mul(invTransform, invTransform, bucket.placementViewportMatrix);\n\n            tileBatches.push({\n                circleArray,\n                circleOffset,\n                transform,\n                // @ts-expect-error - TS2322 - Type 'mat4' is not assignable to type 'Float32Array'.\n                invTransform,\n                projection: bucket.getProjection()\n            });\n\n            circleCount += circleArray.length / 4;  // 4 values per circle\n            circleOffset = circleCount;\n        }\n        if (!buffers) continue;\n        if (painter.terrain) painter.terrain.setupElevationDraw(tile, program);\n        program.draw(painter, gl.LINES,\n            DepthMode.disabled, StencilMode.disabled,\n            painter.colorModeForRenderPass(),\n            CullFaceMode.disabled,\n            collisionUniformValues(posMatrix, tr, tile, bucket.getProjection()),\n            layer.id, buffers.layoutVertexBuffer, buffers.indexBuffer,\n            buffers.segments, null, tr.zoom, null,\n            [buffers.collisionVertexBuffer, buffers.collisionVertexBufferExt]);\n    }\n\n    if (!isText || !tileBatches.length) {\n        return;\n    }\n\n    // Render collision circles\n    const circleProgram = painter.getOrCreateProgram('collisionCircle');\n\n    // Construct vertex data\n    const vertexData = new CollisionCircleLayoutArray();\n    vertexData.resize(circleCount * 4);\n    vertexData._trim();\n\n    let vertexOffset = 0;\n\n    for (const batch of tileBatches) {\n        for (let i = 0; i < batch.circleArray.length / 4; i++) {\n            const circleIdx = i * 4;\n            const x = batch.circleArray[circleIdx + 0];\n            const y = batch.circleArray[circleIdx + 1];\n            const radius = batch.circleArray[circleIdx + 2];\n            const collision = batch.circleArray[circleIdx + 3];\n\n            // 4 floats per vertex, 4 vertices per quad\n            vertexData.emplace(vertexOffset++, x, y, radius, collision, 0);\n            vertexData.emplace(vertexOffset++, x, y, radius, collision, 1);\n            vertexData.emplace(vertexOffset++, x, y, radius, collision, 2);\n            vertexData.emplace(vertexOffset++, x, y, radius, collision, 3);\n        }\n    }\n    if (!quadTriangles || quadTriangles.length < circleCount * 2) {\n        quadTriangles = createQuadTriangles(circleCount);\n    }\n\n    const indexBuffer: IndexBuffer = context.createIndexBuffer(quadTriangles, true);\n    const vertexBuffer: VertexBuffer = context.createVertexBuffer(vertexData, collisionCircleLayout.members, true);\n\n    // Render batches\n    for (const batch of tileBatches) {\n        const uniforms = collisionCircleUniformValues(batch.transform, batch.invTransform, tr, batch.projection);\n\n        circleProgram.draw(\n            painter,\n            gl.TRIANGLES,\n            DepthMode.disabled,\n            StencilMode.disabled,\n            painter.colorModeForRenderPass(),\n            CullFaceMode.disabled,\n            uniforms,\n            layer.id,\n            vertexBuffer,\n            indexBuffer,\n            SegmentVector.simpleSegment(0, batch.circleOffset * 2, batch.circleArray.length, batch.circleArray.length / 2),\n            null,\n            tr.zoom);\n    }\n\n    vertexBuffer.destroy();\n    indexBuffer.destroy();\n}\n\nfunction createQuadTriangles(quadCount: number): QuadTriangleArray {\n    const triCount = quadCount * 2;\n    const array = new QuadTriangleArray();\n\n    array.resize(triCount);\n    array._trim();\n\n    // Two triangles and 4 vertices per quad.\n    for (let i = 0; i < triCount; i++) {\n        const idx = i * 6;\n\n        array.uint16[idx + 0] = i * 4 + 0;\n        array.uint16[idx + 1] = i * 4 + 1;\n        array.uint16[idx + 2] = i * 4 + 2;\n        array.uint16[idx + 3] = i * 4 + 2;\n        array.uint16[idx + 4] = i * 4 + 3;\n        array.uint16[idx + 5] = i * 4 + 0;\n    }\n\n    return array;\n}\n","import Point from '@mapbox/point-geometry';\nimport drawCollisionDebug from './draw_collision_debug';\n\nimport SegmentVector from '../data/segment';\nimport * as symbolProjection from '../symbol/projection';\nimport * as symbolSize from '../symbol/symbol_size';\nimport {mat4, vec3, vec4} from 'gl-matrix';\nimport {OcclusionQuery} from '../gl/query';\nimport {warnOnce} from '../util/util';\nconst identityMat4 = mat4.create();\nimport StencilMode from '../gl/stencil_mode';\nimport DepthMode from '../gl/depth_mode';\nimport CullFaceMode from '../gl/cull_face_mode';\nimport {addDynamicAttributes} from '../data/bucket/symbol_bucket';\nimport {getAnchorAlignment, WritingMode} from '../symbol/sh