rror - TS2322 - Type 'number[]' is not assignable to type 'vec3'.\n                    aabb.min = [...localBounds.min];\n                    // @ts-expect-error - TS2322 - Type 'number[]' is not assignable to type 'vec3'.\n                    aabb.max = [...localBounds.max];\n                    aabb.min[2] += elevation;\n                    aabb.max[2] += elevation;\n                    // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'ReadonlyMat4'.\n                    vec3.transformMat4(aabb.min, aabb.min, tileMatrix);\n                    // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'ReadonlyMat4'.\n                    vec3.transformMat4(aabb.max, aabb.max, tileMatrix);\n                    return aabb;\n                };\n\n                const scale = nodeInfo.evaluatedScale;\n                if (scale[0] <= 1 && scale[1] <= 1 && scale[2] <= 1 && nodeAabb().intersects(frustum) === 0) {\n                    // While it is possible to use arbitrary scale for landmarks, it is highly unlikely\n                    // and frustum culling optimization could be skipped in that case.\n                    continue;\n                }\n\n                const tileModelMatrix = [...tileMatrix];\n\n                const anchorX = node.anchor ? node.anchor[0] : 0;\n                const anchorY = node.anchor ? node.anchor[1] : 0;\n\n                // @ts-expect-error - TS2345 - Argument of type '[number]' is not assignable to parameter of type 'mat4'.\n                mat4.translate(tileModelMatrix as [number], tileModelMatrix as [number], [anchorX * (scale[0] - 1),\n                    anchorY * (scale[1] - 1),\n                    elevation]);\n                if (!vec3.exactEquals(scale, DefaultModelScale)) {\n                    // @ts-expect-error - TS2345 - Argument of type '[number]' is not assignable to parameter of type 'mat4'.\n                    mat4.scale(tileModelMatrix as [number], tileModelMatrix as [number], scale);\n                }\n\n                // keep model and nodemodel matrices separate for rendering door lights\n                // @ts-expect-error - TS2345 - Argument of type '[number]' is not assignable to parameter of type 'ReadonlyMat4'.\n                const nodeModelMatrix = mat4.multiply([] as any, tileModelMatrix as [number], node.matrix);\n                // @ts-expect-error - TS2345 - Argument of type 'number[] | Float32Array | Float64Array' is not assignable to parameter of type 'ReadonlyMat4'.\n                const wvpForNode = mat4.multiply([] as any, tr.expandedFarZProjMatrix, nodeModelMatrix);\n                // Lights come in tilespace so wvp should not include node.matrix when rendering door ligths\n                // @ts-expect-error - TS2345 - Argument of type 'number[] | Float32Array | Float64Array' is not assignable to parameter of type 'ReadonlyMat4'.\n                const wvpForTile = mat4.multiply([] as any, tr.expandedFarZProjMatrix, tileModelMatrix as [number]);\n                const anchorPos = vec4.transformMat4([] as any, [anchorX, anchorY, elevation, 1.0], wvpForNode);\n                const depth = anchorPos[2];\n\n                node.hidden = false;\n                let opacity = layerOpacity;\n                if (!isShadowPass) {\n                    if (frontCutoffEnabled) {\n                        opacity *= calculateFrontCutoffOpacity(tileModelMatrix as any, tr, nodeInfo.aabb, frontCutoffParams);\n                    }\n\n                    opacity *= calculateFarCutoffOpacity(cutoffParams, depth);\n                }\n                if (opacity === 0.0) {\n                    node.hidden = true;\n                    continue;\n                }\n\n                const sortedNode: SortedNode = {\n                    nodeInfo,\n                    depth,\n\n                    opacity,\n                    wvpForNode,\n                    wvpForTile,\n                    nodeModelMatrix,\n                    // @ts-expect-error - TS2322 - Type 'number[]' is not assignable to type 'mat4'.\n                    tileModelMatrix\n                };\n\n                sortedNodes.push(sortedNode);\n            }\n\n            if (!isShadowPass) {\n                // Sort nodes. Opaque nodes first in front to back order. Then non-opaque nodes in back to front order.\n                sortedNodes.sort((a, b) => {\n                    // Front to back order for opaque nodes, and for all nodes when front cutoff is disabled\n                    if (!frontCutoffEnabled || (a.opacity === 1.0 && b.opacity === 1.0)) {\n                        return a.depth < b.depth ? -1 : 1;\n                    }\n                    if (a.opacity === 1.0) {\n                        return -1;\n                    }\n                    if (b.opacity === 1.0) {\n                        return 1;\n                    }\n\n                    // Back to front order for non-opaque nodes\n                    return a.depth > b.depth ? -1 : 1;\n                });\n            }\n\n            for (const sortedNode of sortedNodes) {\n                const nodeInfo = sortedNode.nodeInfo;\n                const node = nodeInfo.node;\n\n                let lightingMatrix = mat4.multiply([] as any, zScaleMatrix, sortedNode.tileModelMatrix);\n                mat4.multiply(lightingMatrix, negCameraPosMatrix, lightingMatrix);\n                const normalMatrix = mat4.invert([] as any, lightingMatrix);\n                mat4.transpose(normalMatrix, normalMatrix);\n                mat4.scale(normalMatrix, normalMatrix, normalScale as [number, number, number]);\n\n                // lighting matrix should take node.matrix into account\n                lightingMatrix = mat4.multiply(lightingMatrix, lightingMatrix, node.matrix);\n\n                const isLightBeamPass = painter.renderPass === 'light-beam';\n                const hasMapboxFeatures = modelTraits & ModelTraits.HasMapboxMeshFeatures;\n                const emissiveStrength = hasMapboxFeatures ? 0.0 : nodeInfo.evaluatedRMEA[0][2];\n\n                for (let i = 0; i < node.meshes.length; ++i) {\n                    const mesh = node.meshes[i];\n                    const isLight = i === node.lightMeshIndex;\n                    let worldViewProjection = sortedNode.wvpForNode;\n                    if (isLight) {\n                        if (!isLightBeamPass && !painter.terrain && painter.shadowRenderer) {\n                            if (painter.currentLayer < painter.firstLightBeamLayer) {\n                                painter.firstLightBeamLayer = painter.currentLayer;\n                            }\n                            continue;\n                        }\n                        // Lights come in tilespace\n                        worldViewProjection = sortedNode.wvpForTile;\n                    } else if (isLightBeamPass) {\n                        continue;\n                    }\n\n                    const programOptions: CreateProgramParams = {\n                        defines: []\n                    };\n                    const dynamicBuffers = [];\n                    setupMeshDraw((programOptions.defines as Array<string>), dynamicBuffers, mesh, painter, layer.lut);\n                    if (!hasMapboxFeatures) {\n                        // @ts-expect-error\n                        programOptions.defines.push('DIFFUSE_SHADED');\n                    }\n\n                    if (singleCascade) {\n                        // @ts-expect-error\n                        programOptions.defines.push('SHADOWS_SINGLE_CASCADE');\n                    }\n\n                    if (stats) {\n                        if (!isShadowPass) {\n                            stats.numRenderedVerticesInTransparentPass += mesh.vertexArray.length;\n                        } else {\n                            stats.numRenderedVerticesInShadowPass += mesh.vertexArray.length;\n                        }\n                    }\n\n                    if (isShadowPass) {\n                        drawShadowCaster(mesh, sortedNode.nodeModelMatrix, painter, layer);\n                        continue;\n                    }\n\n                    let fogMatrixArray = null;\n                    if (fog) {\n                        const fogMatrix = fogMatrixForModel(sortedNode.nodeModelMatrix, painter.transform);\n                        fogMatrixArray = new Float32Array(fogMatrix);\n\n                        if (tr.projection.name !== 'globe') {\n                            const min = mesh.aabb.min;\n                            const max = mesh.aabb.max;\n                            const [minOpacity, maxOpacity] = fog.getOpacityForBounds(fogMatrix, min[0], min[1], max[0], max[1]);\n                            programOptions.overrideFog = minOpacity >= FOG_OPACITY_THRESHOLD || maxOpacity >= FOG_OPACITY_THRESHOLD;\n                        }\n                    }\n\n                    const material = mesh.material;\n                    let occlusionTextureTransform;\n                    // Handle Texture transform\n                    if (material.occlusionTexture && material.occlusionTexture.offsetScale) {\n                        occlusionTextureTransform = material.occlusionTexture.offsetScale;\n                        // @ts-expect-error\n                        programOptions.defines.push('OCCLUSION_TEXTURE_TRANSFORM');\n                    }\n\n                    if (!isShadowPass && shadowRenderer) {\n                        // Set normal offset before program creation, as it adds/remove necessary defines under the hood\n                        shadowRenderer.useNormalOffset = !!mesh.normalBuffer;\n                    }\n\n                    const program = painter.getOrCreateProgram('model', programOptions);\n\n                    if (!isShadowPass && shadowRenderer) {\n                        // The shadow matrix does not need to include node transforms,\n                        // as shadow_pos will be performing that transform in the shader\n                        shadowRenderer.setupShadowsFromMatrix(sortedNode.tileModelMatrix, program, shadowRenderer.useNormalOffset);\n                    }\n\n                    painter.uploadCommonUniforms(context, program, null, fogMatrixArray);\n\n                    const pbr = material.pbrMetallicRoughness;\n                    // These values were taken from the tilesets used for testing\n                    pbr.metallicFactor = 0.9;\n                    pbr.roughnessFactor = 0.5;\n\n                    // Set emissive strength to zero for landmarks, as it is already used embedded in the PBR buffer.\n                    const uniformValues = modelUniformValues(\n                            new Float32Array(worldViewProjection),\n                            new Float32Array(lightingMatrix),\n                            new Float32Array(normalMatrix),\n                            new Float32Array(node.matrix),\n                            painter,\n                            sortedNode.opacity,\n                            pbr.baseColorFactor.toRenderColor(null),\n                            material.emissiveFactor,\n                            pbr.metallicFactor,\n                            pbr.roughnessFactor,\n                            material,\n                            emissiveStrength,\n                            layer,\n                            [0, 0, 0],\n                            occlusionTextureTransform\n                    );\n\n                    if (!isLight && (nodeInfo.hasTranslucentParts || sortedNode.opacity < 1.0)) {\n\n                        program.draw(painter, context.gl.TRIANGLES, depthModeRW, StencilMode.disabled, ColorMode.disabled, CullFaceMode.backCCW,\n                            uniformValues, layer.id, mesh.vertexBuffer, mesh.indexBuffer, mesh.segments, layer.paint, painter.transform.zoom,\n                            undefined, dynamicBuffers);\n                    }\n\n                    const meshNeedsBlending = isLight || sortedNode.opacity < 1.0 || nodeInfo.hasTranslucentParts;\n                    const colorMode = meshNeedsBlending ? ColorMode.alphaBlended : ColorMode.unblended;\n                    const depthMode = !isLight ? depthModeRW : depthModeRO;\n                    program.draw(painter, context.gl.TRIANGLES, depthMode, StencilMode.disabled, colorMode, CullFaceMode.backCCW,\n                        uniformValues, layer.id, mesh.vertexBuffer, mesh.indexBuffer, mesh.segments, layer.paint, painter.transform.zoom,\n                        undefined, dynamicBuffers);\n                }\n            }\n        }\n    };\n\n    // Evaluate bucket and prepare for rendering\n    prepareBatched(painter, source, layer, coords);\n\n    drawTiles();\n}\n\nfunction calculateTileShadowPassCulling(bucket: ModelBucket, renderData: RenderData, painter: Painter, scope: string) {\n    if (!painter.modelManager) return true;\n    const modelManager = painter.modelManager;\n    if (!painter.shadowRenderer) return true;\n    const shadowRenderer = painter.shadowRenderer;\n    assert(painter.renderPass === 'shadow');\n    const aabb = renderData.aabb;\n    let allModelsLoaded = true;\n    let maxHeight = bucket.maxHeight;\n    if (maxHeight === 0) {\n        let maxDim = 0;\n        for (const modelId in bucket.instancesPerModel) {\n            const model = modelManager.getModel(modelId, scope);\n            if (!model) {\n                allModelsLoaded = false;\n                continue;\n            }\n            maxDim = Math.max(maxDim, Math.max(Math.max(model.aabb.max[0], model.aabb.max[1]), model.aabb.max[2]));\n        }\n        maxHeight = bucket.maxScale * maxDim * 1.41 + bucket.maxVerticalOffset;\n        if (allModelsLoaded) bucket.maxHeight = maxHeight;\n    }\n    aabb.max[2] = maxHeight;\n\n    // Take into account bucket placement on DEM\n    aabb.min[2] += bucket.terrainElevationMin;\n    aabb.max[2] += bucket.terrainElevationMax;\n\n    // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'ReadonlyMat4'.\n    vec3.transformMat4(aabb.min, aabb.min, renderData.tileMatrix);\n    // @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'ReadonlyMat4'.\n    vec3.transformMat4(aabb.max, aabb.max, renderData.tileMatrix);\n    const intersection = aabb.intersects(shadowRenderer.getCurrentCascadeFrustum());\n    if (painter.currentShadowCascade === 0) {\n        bucket.isInsideFirstShadowMapFrustum = intersection === 2;\n    }\n    return intersection === 0;\n}\n\nfunction calculateFarCutoffOpacity(cutoffParams: CutoffParams, depth: number): number {\n    assert(cutoffParams.uniformValues.u_cutoff_params.length === 4);\n    const near = cutoffParams.uniformValues.u_cutoff_params[0];\n    const far = cutoffParams.uniformValues.u_cutoff_params[1];\n    const cutoffStart = cutoffParams.uniformValues.u_cutoff_params[2];\n    const cutoffEnd = cutoffParams.uniformValues.u_cutoff_params[3];\n\n    if (far === near || cutoffEnd === cutoffStart) {\n        return 1.0;\n    }\n\n    const linearDepth = (depth - near) / (far - near);\n    return clamp((linearDepth - cutoffStart) / (cutoffEnd - cutoffStart), 0.0, 1.0);\n}\n\nfunction calculateFrontCutoffOpacity(tileModelMatrix: mat4, tr: Transform, aabb: Aabb, cutoffParams: [number, number, number]) {\n    // The cutoff opacity is completely disabled when pitch is lower than 20.\n    const fullyOpaquePitch = 20.0;\n    const fullyTransparentPitch = 40.0;\n    // @ts-expect-error - TS2367 - This comparison appears to be unintentional because the types '20' and '40' have no overlap.\n    assert(fullyOpaquePitch !== fullyTransparentPitch);\n    if (tr.pitch < fullyOpaquePitch) {\n        return 1.0;\n    }\n\n    const worldToCamera = tr.getWorldToCameraMatrix();\n    const mat = mat4.multiply([] as any, worldToCamera, tileModelMatrix);\n\n    // The cutoff opacity is calculated based on how much below the view the AABB bottom corners are.\n    // For this, we find the AABB points with the highest and lowest y value in the view space.\n    const p = [...aabb.min, 1.0];\n    // @ts-expect-error - TS2345 - Argument of type '[number, number]' is not assignable to parameter of type 'ReadonlyVec4'.\n    let r = vec4.transformMat4([] as any, p as [number, number], mat);\n    let pMin = r;\n    let pMax = r;\n    p[1] = aabb.max[1];\n    // @ts-expect-error - TS2345 - Argument of type '[number, number]' is not assignable to parameter of type 'ReadonlyVec4'.\n    r = vec4.transformMat4([] as any, p as [number, number], mat);\n    pMin = r[1] < pMin[1] ? r : pMin;\n    pMax = r[1] > pMax[1] ? r : pMax;\n    p[0] = aabb.max[0];\n    // @ts-expect-error - TS2345 - Argument of type '[number, number]' is not assignable to parameter of type 'ReadonlyVec4'.\n    r = vec4.transformMat4([] as any, p as [number, number], mat);\n    pMin = r[1] < pMin[1] ? r : pMin;\n    pMax = r[1] > pMax[1] ? r : pMax;\n    p[1] = aabb.min[1];\n    // @ts-expect-error - TS2345 - Argument of type '[number, number]' is not assignable to parameter of type 'ReadonlyVec4'.\n    r = vec4.transformMat4([] as any, p as [number, number], mat);\n    pMin = r[1] < pMin[1] ? r : pMin;\n    pMax = r[1] > pMax[1] ? r : pMax;\n\n    const cutoffStartParam = clamp(cutoffParams[0], 0.0, 1.0);\n    // 100.0 is used here just because it provides a nice looking maximum value for the fade effect.\n    // This value could be increased to allow longer fade ranges.\n    const cutoffRangeParam = 100.0 * tr.pixelsPerMeter * clamp(cutoffParams[1], 0.0, 1.0);\n    const finalOpacity = clamp(cutoffParams[2], 0.0, 1.0);\n    // @ts-expect-error - TS2345 - Argument of type 'vec4' is not assignable to parameter of type 'ReadonlyVec3'.\n    const cutoffStart = vec3.lerp([] as any, pMin, pMax, cutoffStartParam);\n\n    const fovScale = Math.tan(tr.fovX * 0.5);\n    // Lowest y coordinate that's still visible at the depth of the cutoff start point.\n    const yMinLimit = -cutoffStart[2] * fovScale;\n    if (cutoffRangeParam === 0.0) {\n        return (cutoffStart[1] < -Math.abs(yMinLimit)) ? finalOpacity : 1.0;\n    }\n\n    const cutoffFactor = (-Math.abs(yMinLimit) - cutoffStart[1]) / cutoffRangeParam;\n    const lerp = (a: number, b: number, t: number) => { return (1 - t) * a + t * b; };\n    const opacity = clamp(lerp(1.0, finalOpacity, cutoffFactor), finalOpacity, 1.0);\n\n    return lerp(1.0, opacity, clamp((tr.pitch - fullyOpaquePitch) / (fullyTransparentPitch - fullyOpaquePitch), 0.0, 1.0));\n}\n","import IndexBuffer from '../gl/index_buffer';\nimport Context from '../gl/context';\nimport {LineIndexArray} from '../data/index_array_type';\n\nclass CacheEntry {\n    buf: IndexBuffer;\n    lastUsedFrameIdx: number;\n}\n\nconst TimeoutFrames = 30;\n\nexport class WireframeDebugCache {\n    _storage: Map<number, CacheEntry>;\n\n    constructor() {\n        this._storage = new Map();\n    }\n\n    getLinesFromTrianglesBuffer(frameIdx: number, indexBuffer: IndexBuffer, context: Context): IndexBuffer | null | undefined {\n        {\n            const entry = this._storage.get(indexBuffer.id);\n            if (entry) {\n                entry.lastUsedFrameIdx = frameIdx;\n                return entry.buf;\n            }\n        }\n\n        const gl = context.gl;\n\n        const bufSize = gl.getBufferParameter(gl.ELEMENT_ARRAY_BUFFER, gl.BUFFER_SIZE);\n        const bufTmp = new ArrayBuffer(bufSize);\n        const intView = new Int16Array(bufTmp);\n        gl.getBufferSubData(gl.ELEMENT_ARRAY_BUFFER, 0, new Int16Array(bufTmp));\n\n        const lineIndexArray = new LineIndexArray();\n\n        for (let i = 0; i < bufSize / 2; i += 3) {\n            const i0 = intView[i];\n            const i1 = intView[i + 1];\n            const i2 = intView[i + 2];\n\n            lineIndexArray.emplaceBack(i0, i1);\n            lineIndexArray.emplaceBack(i1, i2);\n            lineIndexArray.emplaceBack(i2, i0);\n        }\n\n        // Save and restore current VAO since it is reset on IndexBuffer creation\n        const previousBoundVAO = context.bindVertexArrayOES.current;\n\n        const newEntry = new CacheEntry();\n        newEntry.buf = new IndexBuffer(context, lineIndexArray);\n        newEntry.lastUsedFrameIdx = frameIdx;\n        this._storage.set(indexBuffer.id, newEntry);\n\n        context.bindVertexArrayOES.set(previousBoundVAO);\n\n        return newEntry.buf;\n    }\n\n    update(frameIdx: number) {\n        for (const [key, obj] of this._storage) {\n\n            if (frameIdx - obj.lastUsedFrameIdx > TimeoutFrames) {\n                // Delete object from cache\n                obj.buf.destroy();\n                this._storage.delete(key);\n            }\n        }\n    }\n\n    destroy() {\n        for (const [key, obj] of this._storage) {\n            obj.buf.destroy();\n            this._storage.delete(key);\n        }\n    }\n}\n","import type {ITrackedParameters} from '../tracked-parameters/tracked_parameters_base';\n\nexport class OcclusionParams {\n    // Occluder size in pixels\n    occluderSize: number;\n    // Depth offset in NDC units, to prevent coplanar symbol/geometry cases\n    depthOffset: number;\n\n    constructor(tp: ITrackedParameters) {\n        this.occluderSize = 30;\n        this.depthOffset = -0.0001;\n\n        tp.registerParameter(this, [\"Occlusion\"], \"occluderSize\", {min:1, max: 100, step: 1});\n        tp.registerParameter(this, [\"Occlusion\"], \"depthOffset\", {min:-0.05, max: 0, step: 0.00001});\n    }\n}\n","import browser from '../util/browser';\n\nimport {mat4} from 'gl-matrix';\nimport SourceCache from '../source/source_cache';\nimport EXTENT from '../style-spec/data/extent';\nimport pixelsToTileUnits from '../source/pixels_to_tile_units';\nimport SegmentVector from '../data/segment';\nimport {PosArray, TileBoundsArray, TriangleIndexArray, LineStripIndexArray} from '../data/array_types';\nimport {isMapAuthenticated} from '../util/mapbox';\nimport posAttributes from '../data/pos_attributes';\nimport boundsAttributes from '../data/bounds_attributes';\nimport ProgramConfiguration from '../data/program_configuration';\nimport shaders from '../shaders/shaders';\nimport Program from './program';\nimport {programUniforms} from './program/program_uniforms';\nimport Context from '../gl/context';\nimport {fogUniformValues} from '../render/fog';\nimport DepthMode from '../gl/depth_mode';\nimport StencilMode from '../gl/stencil_mode';\nimport ColorMode from '../gl/color_mode';\nimport CullFaceMode from '../gl/cull_face_mode';\nimport Texture from './texture';\nimport {clippingMaskUniformValues} from './program/clipping_mask_program';\nimport Color from '../style-spec/util/color';\nimport symbol from './draw_symbol';\nimport circle from './draw_circle';\nimport assert from 'assert';\nimport heatmap from './draw_heatmap';\nimport line from './draw_line';\nimport fill from './draw_fill';\nimport fillExtrusion from './draw_fill_extrusion';\nimport hillshade from './draw_hillshade';\nimport raster, {prepare as prepareRaster} from './draw_raster';\nimport rasterParticle, {prepare as prepareRasterParticle} from './draw_raster_particle';\nimport background from './draw_background';\nimport debug, {drawDebugPadding, drawDebugQueryGeometry} from './draw_debug';\nimport custom from './draw_custom';\nimport sky from './draw_sky';\nimport Atmosphere from './draw_atmosphere';\nimport {GlobeSharedBuffers, globeToMercatorTransition} from '../geo/projection/globe_util';\nimport {Terrain, defaultTerrainUniforms, type TerrainUniformsType} from '../terrain/terrain';\nimport {Debug} from '../util/debug';\nimport Tile from '../source/tile';\nimport {RGBAImage} from '../util/image';\nimport {LayerTypeMask} from '../../3d-style/util/conflation';\nimport {ReplacementSource, ReplacementOrderLandmark} from '../../3d-style/source/replacement_source';\nimport type {Source} from '../source/source';\nimport type {CutoffParams} from '../render/cutoff';\n\n// 3D-style related\nimport model, {prepare as modelPrepare} from '../../3d-style/render/draw_model';\nimport {lightsUniformValues} from '../../3d-style/render/lights';\nimport {ShadowRenderer} from '../../3d-style/render/shadow_renderer';\nimport {WireframeDebugCache} from './wireframe_cache';\n\nimport type Transform from '../geo/transform';\nimport type {OverscaledTileID, UnwrappedTileID} from '../source/tile_id';\nimport type Style from '../style/style';\nimport type StyleLayer from '../style/style_layer';\nimport type ImageManager from './image_manager';\nimport type GlyphManager from './glyph_manager';\nimport type ModelManager from '../../3d-style/render/model_manager';\nimport type VertexBuffer from '../gl/vertex_buffer';\nimport type IndexBuffer from '../gl/index_buffer';\nimport type {DepthRangeType, DepthMaskType, DepthFuncType} from '../gl/types';\nimport type {DynamicDefinesType} from './program/program_uniforms';\nimport {FOG_OPACITY_THRESHOLD} from '../style/fog_helpers';\nimport type {ContextOptions} from '../gl/context';\nimport type {ITrackedParameters} from '../tracked-parameters/tracked_parameters_base';\nimport Framebuffer from '../gl/framebuffer';\nimport SymbolStyleLayer from '../style/style_layer/symbol_style_layer';\n\nimport {OcclusionParams} from './occlusion_params';\n\nexport type RenderPass = 'offscreen' | 'opaque' | 'translucent' | 'sky' | 'shadow' | 'light-beam';\n\nexport type CanvasCopyInstances = {\n    canvasCopies: WebGLTexture[];\n    timeStamps: number[];\n};\n\nexport type CreateProgramParams = {\n    config?: ProgramConfiguration;\n    defines?: DynamicDefinesType[];\n    overrideFog?: boolean;\n    overrideRtt?: boolean;\n};\n\ntype WireframeOptions = {\n    terrain: boolean;\n    layers2D: boolean;\n    layers3D: boolean;\n};\n\ntype PainterOptions = {\n    showOverdrawInspector: boolean;\n    showTileBoundaries: boolean;\n    showParseStatus: boolean;\n    showQueryGeometry: boolean;\n    showTileAABBs: boolean;\n    showPadding: boolean;\n    rotating: boolean;\n    zooming: boolean;\n    moving: boolean;\n    gpuTiming: boolean;\n    gpuTimingDeferredRender: boolean;\n    fadeDuration: number;\n    isInitialLoad: boolean;\n    speedIndexTiming: boolean;\n    wireframe: WireframeOptions;\n};\n\ntype TileBoundsBuffers = {\n    tileBoundsBuffer: VertexBuffer;\n    tileBoundsIndexBuffer: IndexBuffer;\n    tileBoundsSegments: SegmentVector;\n};\n\ntype GPUTimers = {\n    [layerId: string]: any;\n};\n\nconst draw = {\n    symbol,\n    circle,\n    heatmap,\n    line,\n    fill,\n    'fill-extrusion': fillExtrusion,\n    hillshade,\n    raster,\n    'raster-particle': rasterParticle,\n    background,\n    sky,\n    debug,\n    custom,\n    model\n};\n\nconst prepare = {\n    model: modelPrepare,\n    raster: prepareRaster,\n    'raster-particle': prepareRasterParticle\n};\n\n/**\n * Initialize a new painter object.\n *\n * @param {Canvas} gl an experimental-webgl drawing context\n * @private\n */\nclass Painter {\n    context: Context;\n    transform: Transform;\n    _tileTextures: {\n        [_: number]: Array<Texture>;\n    };\n    numSublayers: number;\n    depthEpsilon: number;\n    emptyProgramConfiguration: ProgramConfiguration;\n    width: number;\n    height: number;\n    tileExtentBuffer: VertexBuffer;\n    tileExtentSegments: SegmentVector;\n    debugBuffer: VertexBuffer;\n    debugIndexBuffer: IndexBuffer;\n    debugSegments: SegmentVector;\n    viewportBuffer: VertexBuffer;\n    viewportSegments: SegmentVector;\n    quadTriangleIndexBuffer: IndexBuffer;\n    mercatorBoundsBuffer: VertexBuffer;\n    mercatorBoundsSegments: SegmentVector;\n    _tileClippingMaskIDs: {\n        [_: number]: number;\n    };\n    stencilClearMode: StencilMode;\n    style: Style;\n    options: PainterOptions;\n    imageManager: ImageManager;\n    glyphManager: GlyphManager;\n    modelManager: ModelManager;\n    depthRangeFor3D: DepthRangeType;\n    depthOcclusion: boolean;\n    opaquePassCutoff: number;\n    frameCounter: number;\n    renderPass: RenderPass;\n    currentLayer: number;\n    currentStencilSource: string | null | undefined;\n    currentShadowCascade: number;\n    nextStencilID: number;\n    id: string;\n    _showOverdrawInspector: boolean;\n    _shadowMapDebug: boolean;\n    cache: {\n        [_: string]: Program<any>;\n    };\n    symbolFadeChange: number;\n    gpuTimers: GPUTimers;\n    deferredRenderGpuTimeQueries: Array<any>;\n    emptyTexture: Texture;\n    identityMat: Float32Array;\n    debugOverlayTexture: Texture;\n    debugOverlayCanvas: HTMLCanvasElement;\n    _terrain: Terrain | null | undefined;\n    _forceTerrainMode: boolean;\n    globeSharedBuffers: GlobeSharedBuffers | null | undefined;\n    tileLoaded: boolean;\n    frameCopies: Array<WebGLTexture>;\n    loadTimeStamps: Array<number>;\n    _backgroundTiles: {\n        [key: number]: Tile;\n    };\n    _atmosphere: Atmosphere | null | undefined;\n    replacementSource: ReplacementSource;\n    conflationActive: boolean;\n    firstLightBeamLayer: number;\n    _lastOcclusionLayer: number;\n    layersWithOcclusionOpacity: Array<number>;\n    longestCutoffRange: number;\n    minCutoffZoom: number;\n    renderDefaultNorthPole: boolean;\n    renderDefaultSouthPole: boolean;\n    renderElevatedRasterBackface: boolean;\n    _fogVisible: boolean;\n    _cachedTileFogOpacities: {\n        [key: number]: [number, number];\n    };\n\n    _shadowRenderer: ShadowRenderer | null | undefined;\n\n    _wireframeDebugCache: WireframeDebugCache;\n\n    tp: ITrackedParameters;\n\n    _debugParams: {\n        showTerrainProxyTiles: boolean;\n        fpsWindow: number;\n        continousRedraw: boolean;\n        enabledLayers: any;\n    };\n\n    _timeStamp: number;\n    _dt: number;\n\n    _averageFPS: number;\n\n    _fpsHistory: Array<number>;\n\n    // Depth for occlusion\n    // FBO+Underlying texture & empty depth texture\n    depthFBO: Framebuffer;\n    depthTexture: Texture;\n    emptyDepthTexture: Texture;\n\n    occlusionParams: OcclusionParams;\n\n    constructor(gl: WebGL2RenderingContext, contextCreateOptions: ContextOptions, transform: Transform, tp: ITrackedParameters) {\n        this.context = new Context(gl, contextCreateOptions);\n\n        this.transform = transform;\n        this._tileTextures = {};\n        this.frameCopies = [];\n        this.loadTimeStamps = [];\n        this.tp = tp;\n\n        this._timeStamp = browser.now();\n        this._averageFPS = 0;\n        this._fpsHistory = [];\n        this._dt = 0;\n\n        this._debugParams = {\n            showTerrainProxyTiles: false,\n            fpsWindow: 30,\n            continousRedraw:false,\n            enabledLayers: {\n            }\n        };\n\n        const layerTypes = [\"fill\", \"line\", \"symbol\", \"circle\", \"heatmap\", \"fill-extrusion\", \"raster\", \"raster-particle\", \"hillshade\", \"model\", \"background\", \"sky\"];\n\n        for (const layerType of layerTypes) {\n            this._debugParams.enabledLayers[layerType] = true;\n        }\n\n        tp.registerParameter(this._debugParams, [\"Terrain\"], \"showTerrainProxyTiles\", {}, () => {\n            this.style.map.triggerRepaint();\n        });\n\n        tp.registerParameter(this._debugParams, [\"FPS\"], \"fpsWindow\", {min: 1, max: 100, step: 1});\n        tp.registerBinding(this._debugParams, [\"FPS\"], 'continousRedraw', {\n            readonly:true,\n            label: \"continuous redraw\"\n        });\n        tp.registerBinding(this, [\"FPS\"], '_averageFPS', {\n            readonly:true,\n            label: \"value\"\n        });\n        tp.registerBinding(this, [\"FPS\"], '_averageFPS', {\n            readonly:true,\n            label: \"graph\",\n            view:'graph',\n            min: 0,\n            max: 200\n        });\n        // Layers\n        for (const layerType of layerTypes) {\n            tp.registerParameter(this._debugParams.enabledLayers, [\"Debug\", \"Layers\"], layerType);\n        }\n\n        this.occlusionParams = new OcclusionParams(tp);\n\n        this.setup();\n\n        // Within each layer there are multiple distinct z-planes that can be drawn to.\n        // This is implemented using the WebGL depth buffer.\n        this.numSublayers = SourceCache.maxUnderzooming + SourceCache.maxOverzooming + 1;\n        this.depthEpsilon = 1 / Math.pow(2, 16);\n\n        this.deferredRenderGpuTimeQueries = [];\n        this.gpuTimers = {};\n        this.frameCounter = 0;\n        this._backgroundTiles = {};\n\n        this.conflationActive = false;\n        this.replacementSource = new ReplacementSource();\n        this.longestCutoffRange = 0.0;\n        this.minCutoffZoom = 0.0;\n        this._fogVisible = false;\n        this._cachedTileFogOpacities = {};\n        this._shadowRenderer = new ShadowRenderer(this);\n\n        this._wireframeDebugCache = new WireframeDebugCache();\n        this.renderDefaultNorthPole = true;\n        this.renderDefaultSouthPole = true;\n        this.layersWithOcclusionOpacity = [];\n\n        const emptyDepth = new RGBAImage({width: 1, height: 1}, Uint8Array.of(0, 0, 0, 0));\n        this.emptyDepthTexture = new Texture(this.context, emptyDepth, gl.RGBA);\n    }\n\n    updateTerrain(style: Style, adaptCameraAltitude: boolean) {\n        const enabled = !!style && !!style.terrain && this.transform.projection.supportsTerrain;\n        if (!enabled && (!this._terrain || !this._terrain.enabled)) return;\n\n        if (!this._terrain) {\n            this._terrain = new Terrain(this, style);\n        }\n        const terrain: Terrain = this._terrain;\n        this.transform.elevation = enabled ? terrain : null;\n        terrain.update(style, this.transform, adaptCameraAltitude);\n        if (this.transform.elevation && !terrain.enabled) {\n            // for zoom based exaggeration change, terrain.update can disable terrain.\n            this.transform.elevation = null;\n        }\n    }\n\n    _updateFog(style: Style) {\n        // Globe makes use of thin fog overlay with a fixed fog range,\n        // so we can skip updating fog tile culling for this projection\n        const isGlobe = this.transform.projection.name === 'globe';\n\n        const fog = style.fog;\n\n        if (!fog || isGlobe || fog.getOpacity(this.transform.pitch) < 1 || fog.properties.get('horizon-blend') < 0.03) {\n            this.transform.fogCullDistSq = null;\n            return;\n        }\n\n        // We start culling where the fog opacity function hits\n        // 98% which leaves a non-noticeable change threshold.\n        const [start, end] = fog.getFovAdjustedRange(this.transform._fov);\n\n        if (start > end) {\n            this.transform.fogCullDistSq = null;\n            return;\n        }\n\n        const fogBoundFraction = 0.78;\n        const fogCullDist = start + (end - start) * fogBoundFraction;\n\n        this.transform.fogCullDistSq = fogCullDist * fogCullDist;\n    }\n\n    get terrain(): Terrain | null | undefined {\n        return (this.transform._terrainEnabled() && this._terrain && this._terrain.enabled) || this._forceTerrainMode ?\n            this._terrain :\n            null;\n    }\n\n    get forceTerrainMode(): boolean {\n        return this._forceTerrainMode;\n    }\n\n    set forceTerrainMode(value: boolean) {\n        if (value && !this._terrain) {\n            this._terrain = new Terrain(this, this.style);\n        }\n        this._forceTerrainMode = value;\n    }\n\n    get shadowRenderer(): ShadowRenderer | null | undefined {\n        return this._shadowRenderer && this._shadowRenderer.enabled ? this._shadowRenderer : null;\n    }\n\n    get wireframeDebugCache(): WireframeDebugCache {\n        return this._wireframeDebugCache;\n    }\n\n    /*\n     * Update the GL viewport, projection matrix, and transforms to compensate\n     * for a new width and height value.\n     */\n    resize(width: number, height: number) {\n        this.width = width * browser.devicePixelRatio;\n        this.height = height * browser.devicePixelRatio;\n        this.context.viewport.set([0, 0, this.width, this.height]);\n\n        if (this.style) {\n            for (const layerId of this.style.order) {\n                this.style._mergedLayers[layerId].resize();\n            }\n        }\n    }\n\n    setup() {\n        const context = this.context;\n\n        const tileExtentArray = new PosArray();\n        tileExtentArray.emplaceBack(0, 0);\n        tileExtentArray.emplaceBack(EXTENT, 0);\n        tileExtentArray.emplaceBack(0, EXTENT);\n        tileExtentArray.emplaceBack(EXTENT, EXTENT);\n        this.tileExtentBuffer = context.createVertexBuffer(tileExtentArray, posAttributes.members);\n        this.tileExtentSegments = SegmentVector.simpleSegment(0, 0, 4, 2);\n\n        const debugArray = new PosArray();\n        debugArray.emplaceBack(0, 0);\n        debugArray.emplaceBack(EXTENT, 0);\n        debugArray.emplaceBack(0, EXTENT);\n        debugArray.emplaceBack(EXTENT, EXTENT);\n        this.debugBuffer = context.createVertexBuffer(debugArray, posAttributes.members);\n        this.debugSegments = SegmentVector.simpleSegment(0, 0, 4, 5);\n\n        const viewportArray = new PosArray();\n        viewportArray.emplaceBack(-1, -1);\n        viewportArray.emplaceBack(1, -1);\n        viewportArray.emplaceBack(-1, 1);\n        viewportArray.emplaceBack(1, 1);\n        this.viewportBuffer = context.createVertexBuffer(viewportArray, posAttributes.members);\n        this.viewportSegments = SegmentVector.simpleSegment(0, 0, 4, 2);\n\n        const tileBoundsArray = new TileBoundsArray();\n        tileBoundsArray.emplaceBack(0, 0, 0, 0);\n        tileBoundsArray.emplaceBack(EXTENT, 0, EXTENT, 0);\n        tileBoundsArray.emplaceBack(0, EXTENT, 0, EXTENT);\n        tileBoundsArray.emplaceBack(EXTENT, EXTENT, EXTENT, EXTENT);\n        this.mercatorBoundsBuffer = context.createVertexBuffer(tileBoundsArray, boundsAttributes.members);\n        this.mercatorBoundsSegments = SegmentVector.simpleSegment(0, 0, 4, 2);\n\n        const quadTriangleIndices = new TriangleIndexArray();\n        quadTriangleIndices.emplaceBack(0, 1, 2);\n        quadTriangleIndices.emplaceBack(2, 1, 3);\n        this.quadTriangleIndexBuffer = context.createIndexBuffer(quadTriangleIndices);\n\n        const tileLineStripIndices = new LineStripIndexArray();\n        for (const i of [0, 1, 3, 2, 0]) tileLineStripIndices.emplaceBack(i);\n        this.debugIndexBuffer = context.createIndexBuffer(tileLineStripIndices);\n\n        this.emptyTexture = new Texture(context,\n            new RGBAImage({width: 1, height: 1}, Uint8Array.of(0, 0, 0, 0)), context.gl.RGBA);\n\n        // @ts-expect-error - TS2322 - Type 'mat4' is not assignable to type 'Float32Array'.\n        this.identityMat = mat4.create();\n\n        const gl = this.context.gl;\n        this.stencilClearMode = new StencilMode({func: gl.ALWAYS, mask: 0}, 0x0, 0xFF, gl.ZERO, gl.ZERO, gl.ZERO);\n        this.loadTimeStamps.push(performance.now());\n    }\n\n    getMercatorTileBoundsBuffers(): TileBoundsBuffers {\n        return {\n            tileBoundsBuffer: this.mercatorBoundsBuffer,\n            tileBoundsIndexBuffer: this.quadTriangleIndexBuffer,\n            tileBoundsSegments: this.mercatorBoundsSegments\n        };\n    }\n\n    getTileBoundsBuffers(tile: Tile): TileBoundsBuffers {\n        tile._makeTileBoundsBuffers(this.context, this.transform.projection);\n        if (tile._tileBoundsBuffer) {\n            const tileBoundsBuffer = tile._tileBoundsBuffer;\n            const tileBoundsIndexBuffer = tile._tileBoundsIndexBuffer;\n            const tileBoundsSegments = tile._tileBoundsSegments;\n            return {tileBoundsBuffer, tileBoundsIndexBuffer, tileBoundsSegments};\n        } else {\n            return this.getMercatorTileBoundsBuffers();\n        }\n    }\n\n    /*\n     * Reset the drawing canvas by clearing the stencil buffer so that we can draw\n     * new tiles at the same location, while retaining previously drawn pixels.\n     */\n    clearStencil() {\n        const context = this.context;\n        const gl = context.gl;\n\n        this.nextStencilID = 1;\n        this.currentStencilSource = undefined;\n        this._tileClippingMaskIDs = {};\n\n        // As a temporary workaround for https://github.com/mapbox/mapbox-gl-js/issues/5490,\n        // pending an upstream fix, we draw a fullscreen stencil=0 clipping mask here,\n        // effectively clearing the stencil buffer: once an upstream patch lands, remove\n        // this function in favor of context.clear({ stencil: 0x0 })\n        // @ts-expect-error - TS2554 - Expected 12-16 arguments, but got 11.\n        this.getOrCreateProgram('clippingMask').draw(this, gl.TRIANGLES,\n            DepthMode.disabled, this.stencilClearMode, ColorMode.disabled, CullFaceMode.disabled,\n            clippingMaskUniformValues(this.identityMat),\n            '$clipping', this.viewportBuffer,\n            this.quadTriangleIndexBuffer, this.viewportSegments);\n    }\n\n    resetStencilClippingMasks() {\n        if (!this.terrain) {\n            this.currentStencilSource = undefined;\n            this._tileClippingMaskIDs = {};\n        }\n    }\n\n    _renderTileClippingMasks(layer: StyleLayer, sourceCache?: SourceCache, tileIDs?: Array<OverscaledTileID>) {\n        if (!sourceCache || this.currentStencilSource === sourceCache.id || !layer.isTileClipped() || !tileIDs || tileIDs.length === 0) {\n            return;\n        }\n\n        if (this._tileClippingMaskIDs && !this.terrain) {\n            let dirtyStencilClippingMasks = false;\n            // Equivalent tile set is already rendered in stencil\n            for (const coord of tileIDs) {\n                if (this._tileClippingMaskIDs[coord.key] === undefined) {\n                    dirtyStencilClippingMasks = true;\n                    break;\n                }\n            }\n            if (!dirtyStencilClippingMasks) {\n                return;\n            }\n        }\n\n        this.currentStencilSource = sourceCache.id;\n\n        const context = this.context;\n        const gl = context.gl;\n\n        if (this.nextStencilID + tileIDs.length > 256) {\n            // we'll run out of fresh IDs so we need to clear and start from scratch\n            this.clearStencil();\n        }\n\n        context.setColorMode(ColorMode.disabled);\n        context.setDepthMode(DepthMode.disabled);\n\n        const program = this.getOrCreateProgram('clippingMask');\n\n        this._tileClippingMaskIDs = {};\n\n        for (const tileID of tileIDs) {\n            const tile = sourceCache.getTile(tileID);\n            const id = this._tileClippingMaskIDs[tileID.key] = this.nextStencilID++;\n            const {tileBoundsBuffer, tileBoundsIndexBuffer, tileBoundsSegments} = this.getTileBoundsBuffers(tile);\n\n            // @ts-expect-error - TS2554 - Expected 12-16 arguments, but got 11.\n            program.draw(this, gl.TRIANGLES, DepthMode.disabled,\n            // Tests will always pass, and ref value will be written to stencil buffer.\n            new StencilMode({func: gl.ALWAYS, mask: 0}, id, 0xFF, gl.KEEP, gl.KEEP, gl.REPLACE),\n            ColorMode.disabled, CullFaceMode.disabled, clippingMaskUniformValues(tileID.projMatrix),\n            '$clipping', tileBoundsBuffer,\n            tileBoundsIndexBuffer, tileBoundsSegments);\n        }\n    }\n\n    stencilModeFor3D(): StencilMode {\n        this.currentStencilSource = undefined;\n\n        if (this.nextStencilID + 1 > 256) {\n            this.clearStencil();\n        }\n\n        const id = this.nextStencilID++;\n        const gl = this.context.gl;\n        return new StencilMode({func: gl.NOTEQUAL, mask: 0xFF}, id, 0xFF, gl.KEEP, gl.KEEP, gl.REPLACE);\n    }\n\n    stencilModeForClipping(tileID: OverscaledTileID): Readonly<StencilMode> {\n        if (this.terrain) return this.terrain.stencilModeForRTTOverlap(tileID);\n        const gl = this.context.gl;\n        return new StencilMode({func: gl.EQUAL, mask: 0xFF}, this._tileClippingMaskIDs[tileID.key], 0x00, gl.KEEP, gl.KEEP, gl.REPLACE);\n    }\n\n    /*\n     * Sort coordinates by Z as drawing tiles is done in Z-descending order.\n     * All children with the same Z write the same stencil value.  Children\n     * stencil values are greater than parent's.  This is used only for raster\n     * and raster-dem tiles, which are already clipped to tile boundaries, to\n     * mask area of tile overlapped by children tiles.\n     * Stencil ref values continue range used in _tileClippingMaskIDs.\n     *\n     * Returns [StencilMode for tile overscaleZ map, sortedCoords].\n     */\n    stencilConfigForOverlap(tileIDs: Array<OverscaledTileID>): [{\n        [_: number]: Readonly<StencilMode>;\n    }, Array<OverscaledTileID>] {\n        const gl = this.context.gl;\n        const coords = tileIDs.sort((a, b) => b.overscaledZ - a.overscaledZ);\n        const minTileZ = coords[coords.length - 1].overscaledZ;\n        const stencilValues = coords[0].overscaledZ - minTileZ + 1;\n        if (stencilValues > 1) {\n            this.currentStencilSource = undefined;\n            if (this.nextStencilID + stencilValues > 256) {\n                this.clearStencil();\n            }\n            const zToStencilMode: Record<string, any> = {};\n            for (let i = 0; i < stencilValues; i++) {\n                zToStencilMode[i + minTileZ] = new StencilMode({func: gl.GEQUAL, mask: 0xFF}, i + this.nextStencilID, 0xFF, gl.KEEP, gl.KEEP, gl.REPLACE);\n            }\n            this.nextStencilID += stencilValues;\n            return [zToStencilMode, coords];\n        }\n        return [{[minTileZ]: StencilMode.disabled}, coords];\n    }\n\n    colorModeForRenderPass(): Readonly<ColorMode> {\n        const gl = this.context.gl;\n        i