 {\n        painter.layersWithOcclusionOpacity.push(painter.currentLayer);\n    }\n    if (hasZOffset) painter.forceTerrainMode = false;\n}\n","import StencilMode from '../gl/stencil_mode';\nimport DepthMode from '../gl/depth_mode';\nimport CullFaceMode from '../gl/cull_face_mode';\nimport Tile from '../source/tile';\nimport {\n    backgroundUniformValues,\n    backgroundPatternUniformValues\n} from './program/background_program';\nimport {OverscaledTileID} from '../source/tile_id';\n\nimport type Painter from './painter';\nimport type SourceCache from '../source/source_cache';\nimport type BackgroundStyleLayer from '../style/style_layer/background_style_layer';\nimport type {ImagePosition} from \"./image_atlas\";\n\nexport default drawBackground;\n\nfunction drawBackground(painter: Painter, sourceCache: SourceCache, layer: BackgroundStyleLayer, coords: Array<OverscaledTileID>) {\n    const color = layer.paint.get('background-color');\n    const opacity = layer.paint.get('background-opacity');\n    const emissiveStrength = layer.paint.get('background-emissive-strength');\n\n    if (opacity === 0) return;\n\n    const context = painter.context;\n    const gl = context.gl;\n    const transform = painter.transform;\n    const tileSize = transform.tileSize;\n    const image = layer.paint.get('background-pattern');\n    let patternPosition: ImagePosition | null | undefined;\n    if (image !== undefined) {\n        // Check if pattern image is loaded and retrieve position\n        if (image === null) {\n            return;\n        }\n        patternPosition = painter.imageManager.getPattern(image.toString(), layer.scope, painter.style.getLut(layer.scope));\n        if (!patternPosition) {\n            return;\n        }\n    }\n\n    const pass = (!image && color.a === 1 && opacity === 1 && painter.opaquePassEnabledForLayer()) ? 'opaque' : 'translucent';\n    if (painter.renderPass !== pass) return;\n\n    const stencilMode = StencilMode.disabled;\n    const depthMode = painter.depthModeForSublayer(0, pass === 'opaque' ? DepthMode.ReadWrite : DepthMode.ReadOnly);\n\n    const colorMode = painter.colorModeForDrapableLayerRenderPass(emissiveStrength);\n    const programName = image ? 'backgroundPattern' : 'background';\n\n    let tileIDs = coords;\n    let backgroundTiles;\n    if (!tileIDs) {\n        backgroundTiles = painter.getBackgroundTiles();\n        tileIDs = Object.values(backgroundTiles).map(tile => (tile as any).tileID);\n    }\n\n    if (image) {\n        context.activeTexture.set(gl.TEXTURE0);\n        painter.imageManager.bind(painter.context, layer.scope);\n    }\n\n    for (const tileID of tileIDs) {\n        const affectedByFog = painter.isTileAffectedByFog(tileID);\n        const program = painter.getOrCreateProgram(programName, {overrideFog: affectedByFog});\n        const unwrappedTileID = tileID.toUnwrapped();\n        const matrix = coords ? tileID.projMatrix : painter.transform.calculateProjMatrix(unwrappedTileID);\n        painter.prepareDrawTile();\n\n        const tile = sourceCache ? sourceCache.getTile(tileID) :\n            backgroundTiles ? backgroundTiles[tileID.key] : new Tile(tileID, tileSize, transform.zoom, painter);\n\n        const uniformValues = image ?\n\n            backgroundPatternUniformValues(matrix, emissiveStrength, opacity, painter, image, layer.scope, patternPosition, {tileID, tileSize}) :\n\n            backgroundUniformValues(matrix, emissiveStrength, opacity, color.toRenderColor(layer.lut));\n\n        painter.uploadCommonUniforms(context, program, unwrappedTileID);\n\n        const {tileBoundsBuffer, tileBoundsIndexBuffer, tileBoundsSegments} = painter.getTileBoundsBuffers(tile);\n\n        // @ts-expect-error - TS2554 - Expected 12-16 arguments, but got 11.\n        program.draw(painter, gl.TRIANGLES, depthMode, stencilMode, colorMode, CullFaceMode.disabled,\n            uniformValues, layer.id, tileBoundsBuffer,\n                tileBoundsIndexBuffer, tileBoundsSegments);\n    }\n}\n","export default drawCustom;\n\nimport DepthMode from '../gl/depth_mode';\nimport StencilMode from '../gl/stencil_mode';\nimport {warnOnce} from '../util/util';\nimport {globeToMercatorTransition} from './../geo/projection/globe_util';\n\nimport type Painter from './painter';\nimport type {OverscaledTileID} from '../source/tile_id';\nimport type SourceCache from '../source/source_cache';\nimport type CustomStyleLayer from '../style/style_layer/custom_style_layer';\nimport MercatorCoordinate from '../geo/mercator_coordinate';\nimport assert from 'assert';\n\nfunction drawCustom(painter: Painter, sourceCache: SourceCache, layer: CustomStyleLayer, coords: Array<OverscaledTileID>) {\n\n    const context = painter.context;\n    const implementation = layer.implementation;\n\n    if (painter.transform.projection.unsupportedLayers && painter.transform.projection.unsupportedLayers.includes(\"custom\") &&\n        !(painter.terrain && (painter.terrain.renderingToTexture || painter.renderPass === 'offscreen') && layer.isDraped(sourceCache))) {\n        warnOnce('Custom layers are not yet supported with this projection. Use mercator or globe to enable usage of custom layers.');\n        return;\n    }\n\n    if (painter.renderPass === 'offscreen') {\n\n        const prerender = implementation.prerender;\n        if (prerender) {\n            painter.setCustomLayerDefaults();\n            context.setColorMode(painter.colorModeForRenderPass());\n\n            if (painter.transform.projection.name === \"globe\") {\n                const center = painter.transform.pointMerc;\n                prerender.call(implementation, context.gl, painter.transform.customLayerMatrix(), painter.transform.getProjection(), painter.transform.globeToMercatorMatrix(),  globeToMercatorTransition(painter.transform.zoom), [center.x, center.y], painter.transform.pixelsPerMeterRatio);\n            } else {\n                prerender.call(implementation, context.gl, painter.transform.customLayerMatrix());\n            }\n\n            context.setDirty();\n            painter.setBaseState();\n        }\n\n    } else if (painter.renderPass === 'translucent') {\n\n        if (painter.terrain && painter.terrain.renderingToTexture) {\n            assert(implementation.renderToTile);\n            assert(coords.length === 1);\n            const renderToTile = implementation.renderToTile;\n            if (renderToTile) {\n                const c = coords[0].canonical;\n                const unwrapped = new MercatorCoordinate(c.x + coords[0].wrap * (1 << c.z), c.y, c.z);\n\n                context.setDepthMode(DepthMode.disabled);\n                context.setStencilMode(StencilMode.disabled);\n                context.setColorMode(painter.colorModeForRenderPass());\n                painter.setCustomLayerDefaults();\n\n                renderToTile.call(implementation, context.gl, unwrapped);\n                context.setDirty();\n                painter.setBaseState();\n            }\n            return;\n        }\n\n        painter.setCustomLayerDefaults();\n\n        context.setColorMode(painter.colorModeForRenderPass());\n        context.setStencilMode(StencilMode.disabled);\n\n        const depthMode = implementation.renderingMode === '3d' ?\n            new DepthMode(painter.context.gl.LEQUAL, DepthMode.ReadWrite, painter.depthRangeFor3D) :\n            painter.depthModeForSublayer(0, DepthMode.ReadOnly);\n\n        context.setDepthMode(depthMode);\n\n        if (painter.transform.projection.name === \"globe\") {\n            const center = painter.transform.pointMerc;\n            implementation.render(context.gl, painter.transform.customLayerMatrix(), painter.transform.getProjection(), painter.transform.globeToMercatorMatrix(), globeToMercatorTransition(painter.transform.zoom), [center.x, center.y], painter.transform.pixelsPerMeterRatio);\n        } else {\n            implementation.render(context.gl, painter.transform.customLayerMatrix());\n        }\n\n        context.setDirty();\n        painter.setBaseState();\n        context.bindFramebuffer.set(null);\n    }\n}\n","import Point from '@mapbox/point-geometry';\nimport {getBounds, clamp, polygonizeBounds, bufferConvexPolygon} from '../util/util';\nimport {polygonIntersectsBox, polygonContainsPoint} from '../util/intersection_tests';\nimport EXTENT from '../style-spec/data/extent';\nimport pixelsToTileUnits from '../source/pixels_to_tile_units';\nimport {vec3, vec4, mat4} from 'gl-matrix';\nimport {Ray} from '../util/primitives';\nimport MercatorCoordinate, {mercatorXfromLng} from '../geo/mercator_coordinate';\nimport {getTilePoint, getTileVec3} from '../geo/projection/tile_transform';\nimport resample from '../geo/projection/resample';\nimport {GLOBE_RADIUS} from '../geo/projection/globe_constants';\nimport {number as interpolate} from '../style-spec/util/interpolate';\n\nimport type Transform from '../geo/transform';\nimport type Tile from '../source/tile';\nimport type {PointLike} from '../types/point-like';\nimport type {OverscaledTileID} from '../source/tile_id';\n\ntype CachedPolygon = {\n    // Query rectangle projected on the map plane\n    polygon: MercatorCoordinate[];\n    // A flag tellingwhether the query polygon might span across mercator boundaries [0, 1]\n    unwrapped: boolean;\n};\n\n/**\n * A data-class that represents a screenspace query from `Map#queryRenderedFeatures`.\n * All the internal geometries and data are intented to be immutable and read-only.\n * Its lifetime is only for the duration of the query and fixed state of the map while the query is being processed.\n *\n * @class QueryGeometry\n */\nexport class QueryGeometry {\n    screenBounds: Point[];\n    cameraPoint: Point;\n    screenGeometry: Point[];\n    screenGeometryMercator: CachedPolygon;\n\n    _screenRaycastCache: {\n        [_: number]: CachedPolygon;\n    };\n    _cameraRaycastCache: {\n        [_: number]: CachedPolygon;\n    };\n\n    isAboveHorizon: boolean;\n\n    constructor(screenBounds: Point[], cameraPoint: Point, aboveHorizon: boolean, transform: Transform) {\n        this.screenBounds = screenBounds;\n        this.cameraPoint = cameraPoint;\n        this._screenRaycastCache = {};\n        this._cameraRaycastCache = {};\n        this.isAboveHorizon = aboveHorizon;\n\n        this.screenGeometry = this.bufferedScreenGeometry(0);\n        this.screenGeometryMercator = this._bufferedScreenMercator(0, transform);\n    }\n\n    /**\n     * Factory method to help contruct an instance  while accounting for current map state.\n     *\n     * @static\n     * @param {(PointLike | [PointLike, PointLike])} geometry The query geometry.\n     * @param {Transform} transform The current map transform.\n     * @returns {QueryGeometry} An instance of the QueryGeometry class.\n     */\n    static createFromScreenPoints(geometry: PointLike | [PointLike, PointLike], transform: Transform): QueryGeometry {\n        let screenGeometry;\n        let aboveHorizon;\n\n        if (geometry instanceof Point || typeof geometry[0] === 'number') {\n            const pt = Point.convert(geometry);\n            screenGeometry = [pt];\n            // @ts-expect-error - TS2345 - Argument of type 'Point | [PointLike, PointLike]' is not assignable to parameter of type 'Point'.\n            aboveHorizon = transform.isPointAboveHorizon(pt);\n        } else {\n            const tl = Point.convert(geometry[0]);\n            const br = Point.convert(geometry[1]);\n            screenGeometry = [tl, br];\n            // @ts-expect-error - TS2345 - Argument of type 'number | Point' is not assignable to parameter of type 'Point'.\n            aboveHorizon = polygonizeBounds(tl, br).every((p) => transform.isPointAboveHorizon(p));\n        }\n\n        return new QueryGeometry(screenGeometry, transform.getCameraPoint(), aboveHorizon, transform);\n    }\n\n    /**\n     * Returns true if the initial query by the user was a single point.\n     *\n     * @returns {boolean} Returns `true` if the initial query geometry was a single point.\n     */\n    isPointQuery(): boolean {\n        return this.screenBounds.length === 1;\n    }\n\n    /**\n     * Due to data-driven styling features do not uniform size(eg `circle-radius`) and can be offset differntly\n     * from their original location(for example with `*-translate`). This means we have to expand our query region for\n     * each tile to account for variation in these properties.\n     * Each tile calculates a tile level max padding value (in screenspace pixels) when its parsed, this function\n     * lets us calculate a buffered version of the screenspace query geometry for each tile.\n     *\n     * @param {number} buffer The tile padding in screenspace pixels.\n     * @returns {Point[]} The buffered query geometry.\n     */\n    bufferedScreenGeometry(buffer: number): Point[] {\n        return polygonizeBounds(\n            this.screenBounds[0],\n            this.screenBounds.length === 1 ? this.screenBounds[0] : this.screenBounds[1],\n            buffer\n        );\n    }\n\n    /**\n     * When the map is pitched, some of the 3D features that intersect a query will not intersect\n     * the query at the surface of the earth. Instead the feature may be closer and only intersect\n     * the query because it extrudes into the air.\n     *\n     * This returns a geometry that is a convex polygon that encompasses the query frustum and the point underneath the camera.\n     * Similar to `bufferedScreenGeometry`, buffering is added to account for variation in paint properties.\n     *\n     * Case 1: point underneath camera is exactly behind query volume\n     *              +----------+\n     *              |          |\n     *              |          |\n     *              |          |\n     *              +          +\n     *               X        X\n     *                X      X\n     *                 X    X\n     *                  X  X\n     *                   XX.\n     *\n     * Case 2: point is behind and to the right\n     *              +----------+\n     *              |          X\n     *              |           X\n     *              |           XX\n     *              +            X\n     *              XXX          XX\n     *                 XXXX       X\n     *                    XXX     XX\n     *                        XX   X\n     *                           XXX.\n     *\n     * Case 3: point is behind and to the left\n     *              +----------+\n     *             X           |\n     *             X           |\n     *            XX           |\n     *            X            +\n     *           X          XXXX\n     *          XX       XXX\n     *          X    XXXX\n     *         X XXXX\n     *         XXX.\n     *\n     * @param {number} buffer The tile padding in screenspace pixels.\n     * @returns {Point[]} The buffered query geometry.\n     */\n    bufferedCameraGeometry(buffer: number): Point[] {\n        const min = this.screenBounds[0];\n        const max = this.screenBounds.length === 1 ? this.screenBounds[0].add(new Point(1, 1)) : this.screenBounds[1];\n        const cameraPolygon = polygonizeBounds(min, max, 0, false);\n\n        // Only need to account for point underneath camera if its behind query volume\n        if (this.cameraPoint.y > max.y) {\n            //case 1: insert point in the middle\n            if (this.cameraPoint.x > min.x && this.cameraPoint.x < max.x) {\n                cameraPolygon.splice(3, 0, this.cameraPoint);\n            //case 2: replace btm right point\n            } else if (this.cameraPoint.x >= max.x) {\n                cameraPolygon[2] = this.cameraPoint;\n            //case 3: replace btm left point\n            } else if (this.cameraPoint.x <= min.x) {\n                cameraPolygon[3] = this.cameraPoint;\n            }\n        }\n\n        return bufferConvexPolygon(cameraPolygon, buffer);\n    }\n\n    // Creates a convex polygon in screen coordinates that encompasses the query frustum and\n    // the camera location at globe's surface. Camera point can be at any side of the query polygon as\n    // opposed to `bufferedCameraGeometry` which restricts the location to underneath the polygon.\n    bufferedCameraGeometryGlobe(buffer: number): Point[] {\n        const min = this.screenBounds[0];\n        const max = this.screenBounds.length === 1 ? this.screenBounds[0].add(new Point(1, 1)) : this.screenBounds[1];\n\n        // Padding is added to the query polygon before inclusion of the camera location.\n        // Otherwise the buffered (narrow) polygon could penetrate the globe creating a lot of false positives\n        const cameraPolygon = polygonizeBounds(min, max, buffer);\n\n        const camPos = this.cameraPoint.clone();\n        // @ts-expect-error - TS2365 - Operator '+' cannot be applied to types 'boolean' and 'boolean'.\n        const column = (camPos.x > min.x) + (camPos.x > max.x);\n        // @ts-expect-error - TS2365 - Operator '+' cannot be applied to types 'boolean' and 'boolean'.\n        const row = (camPos.y > min.y) + (camPos.y > max.y);\n        const sector = row * 3 + column;\n\n        switch (sector) {\n        case 0:     // replace top-left point (closed polygon)\n            cameraPolygon[0] = camPos;\n            cameraPolygon[4] = camPos.clone();\n            break;\n        case 1:     // insert point in the middle of top-left and top-right\n            cameraPolygon.splice(1, 0, camPos);\n            break;\n        case 2:     // replace top-right point\n            cameraPolygon[1] = camPos;\n            break;\n        case 3:     // insert point in the middle of top-left and bottom-left\n            cameraPolygon.splice(4, 0, camPos);\n            break;\n        case 5:     // insert point in the middle of top-right and bottom-right\n            cameraPolygon.splice(2, 0, camPos);\n            break;\n        case 6:     // replace bottom-left point\n            cameraPolygon[3] = camPos;\n            break;\n        case 7:     // insert point in the middle of bottom-left and bottom-right\n            cameraPolygon.splice(3, 0, camPos);\n            break;\n        case 8:     // replace bottom-right point\n            cameraPolygon[2] = camPos;\n            break;\n        }\n\n        return cameraPolygon;\n    }\n\n    /**\n     * Checks if a tile is contained within this query geometry.\n     *\n     * @param {Tile} tile The tile to check.\n     * @param {Transform} transform The current map transform.\n     * @param {boolean} use3D A boolean indicating whether to query 3D features.\n     * @param {number} cameraWrap A wrap value for offsetting the camera position.\n     * @returns {?TilespaceQueryGeometry} Returns `undefined` if the tile does not intersect.\n     */\n    containsTile(tile: Tile, transform: Transform, use3D: boolean, cameraWrap: number = 0): TilespaceQueryGeometry | null | undefined {\n        // The buffer around the query geometry is applied in screen-space.\n        // transform._pixelsPerMercatorPixel is used to compensate any extra scaling applied from the currently active projection.\n        // Floating point errors when projecting into tilespace could leave a feature\n        // outside the query volume even if it looks like it overlaps visually, a 1px bias value overcomes that.\n        const bias = 1;\n        const padding = tile.queryPadding / transform._pixelsPerMercatorPixel + bias;\n\n        const cachedQuery = use3D ?\n            this._bufferedCameraMercator(padding, transform) :\n            this._bufferedScreenMercator(padding, transform);\n\n        let wrap = tile.tileID.wrap + (cachedQuery.unwrapped ? cameraWrap : 0);\n        const geometryForTileCheck = cachedQuery.polygon.map((p) => getTilePoint(tile.tileTransform, p, wrap));\n\n        if (!polygonIntersectsBox(geometryForTileCheck, 0, 0, EXTENT, EXTENT)) {\n            return undefined;\n        }\n\n        wrap = tile.tileID.wrap + (this.screenGeometryMercator.unwrapped ? cameraWrap : 0);\n        const tilespaceVec3s = this.screenGeometryMercator.polygon.map((p) => getTileVec3(tile.tileTransform, p, wrap));\n        const tilespaceGeometry = tilespaceVec3s.map((v) => new Point(v[0], v[1]));\n\n        const cameraMercator = transform.getFreeCameraOptions().position || new MercatorCoordinate(0, 0, 0);\n        const tilespaceCameraPosition = getTileVec3(tile.tileTransform, cameraMercator, wrap);\n        const tilespaceRays = tilespaceVec3s.map((tileVec) => {\n            const dir = vec3.sub(tileVec, tileVec, tilespaceCameraPosition);\n            vec3.normalize(dir, dir);\n            return new Ray(tilespaceCameraPosition, dir);\n        });\n        const pixelToTileUnitsFactor = pixelsToTileUnits(tile, 1, transform.zoom) * transform._pixelsPerMercatorPixel;\n\n        return {\n            queryGeometry: this,\n            tilespaceGeometry,\n            tilespaceRays,\n            bufferedTilespaceGeometry: geometryForTileCheck,\n            bufferedTilespaceBounds: clampBoundsToTileExtents(getBounds(geometryForTileCheck)),\n            tile,\n            tileID: tile.tileID,\n            pixelToTileUnitsFactor\n        };\n    }\n\n    /**\n     * These methods add caching on top of the terrain raycasting provided by `Transform#pointCoordinate3d`.\n     * Tiles come with different values of padding, however its very likely that multiple tiles share the same value of padding\n     * based on the style. In that case we want to reuse the result from a previously computed terrain raycast.\n     */\n\n    _bufferedScreenMercator(padding: number, transform: Transform): CachedPolygon {\n        const key = cacheKey(padding);\n        if (this._screenRaycastCache[key]) {\n            return this._screenRaycastCache[key];\n        } else {\n            let poly: CachedPolygon;\n\n            if (transform.projection.name === 'globe') {\n                poly = this._projectAndResample(this.bufferedScreenGeometry(padding), transform);\n            } else {\n                poly = {\n                    polygon: this.bufferedScreenGeometry(padding).map((p) => transform.pointCoordinate3D(p)),\n                    unwrapped: true\n                };\n            }\n\n            this._screenRaycastCache[key] = poly;\n            return poly;\n        }\n    }\n\n    _bufferedCameraMercator(padding: number, transform: Transform): CachedPolygon {\n        const key = cacheKey(padding);\n        if (this._cameraRaycastCache[key]) {\n            return this._cameraRaycastCache[key];\n        } else {\n            let poly: CachedPolygon;\n\n            if (transform.projection.name === 'globe') {\n                poly = this._projectAndResample(this.bufferedCameraGeometryGlobe(padding), transform);\n            } else {\n                poly = {\n                    polygon: this.bufferedCameraGeometry(padding).map((p) => transform.pointCoordinate3D(p)),\n                    unwrapped: true\n                };\n            }\n\n            this._cameraRaycastCache[key] = poly;\n            return poly;\n        }\n    }\n\n    _projectAndResample(polygon: Point[], transform: Transform): CachedPolygon {\n        // Handle a special case where either north or south pole is inside the query polygon\n        const polePolygon: CachedPolygon | null | undefined = projectPolygonCoveringPoles(polygon, transform);\n\n        if (polePolygon) {\n            return polePolygon;\n        }\n\n        // Resample the polygon by adding intermediate points so that straight lines of the shape\n        // are correctly projected on the surface of the globe.\n        const resampled = unwrapQueryPolygon(resamplePolygon(polygon, transform).map(p => new Point(wrap(p.x), p.y)), transform);\n\n        return {\n            polygon: resampled.polygon.map(p => new MercatorCoordinate(p.x, p.y)),\n            unwrapped: resampled.unwrapped\n        };\n    }\n}\n\n// Checks whether the provided polygon is crossing the antimeridian line and unwraps it if necessary.\n// The resulting polygon is continuous\nexport function unwrapQueryPolygon(polygon: Point[], tr: Transform): {\n    polygon: Point[];\n    unwrapped: boolean;\n} {\n    let unwrapped = false;\n\n    // Traverse edges of the polygon and unwrap vertices that are crossing the antimeridian.\n    let maxX = -Infinity;\n    let startEdge = 0;\n\n    for (let e = 0; e < polygon.length - 1; e++) {\n        if (polygon[e].x > maxX) {\n            maxX = polygon[e].x;\n            startEdge = e;\n        }\n    }\n\n    for (let i = 0; i < polygon.length - 1; i++) {\n        const edge = (startEdge + i) % (polygon.length - 1);\n        const a = polygon[edge];\n        const b = polygon[edge + 1];\n\n        if (Math.abs(a.x - b.x) > 0.5) {\n            // A straight line drawn on the globe can't have longer length than 0.5 on the x-axis\n            // without crossing the antimeridian\n            if (a.x < b.x) {\n                a.x += 1;\n\n                if (edge === 0) {\n                    // First and last points are duplicate for closed polygons\n                    polygon[polygon.length - 1].x += 1;\n                }\n            } else {\n                b.x += 1;\n\n                if (edge + 1 === polygon.length - 1) {\n                    polygon[0].x += 1;\n                }\n            }\n\n            unwrapped = true;\n        }\n    }\n\n    const cameraX = mercatorXfromLng(tr.center.lng);\n    if (unwrapped && cameraX < Math.abs(cameraX - 1)) {\n        polygon.forEach(p => { p.x -= 1; });\n    }\n\n    return {\n        polygon,\n        unwrapped\n    };\n}\n\n// Special function for handling scenarios where one of the poles is inside the query polygon.\n// Finding projection of these kind of polygons is more involving as projecting just the corners will\n// produce a degenerate (self-intersecting, non-continuous, etc.) polygon in mercator coordinates\nexport function projectPolygonCoveringPoles(polygon: Point[], tr: Transform): CachedPolygon | null | undefined {\n// @ts-expect-error - TS2345 - Argument of type 'Float64Array' is not assignable to parameter of type 'ReadonlyMat4'.\n    const matrix = mat4.multiply([] as any, tr.pixelMatrix, tr.globeMatrix);\n\n    // Transform north and south pole coordinates to the screen to see if they're\n    // inside the query polygon\n    const northPole = [0, -GLOBE_RADIUS, 0, 1];\n    const southPole = [0, GLOBE_RADIUS, 0, 1];\n    const center = [0, 0, 0, 1];\n\n    vec4.transformMat4(northPole as [number, number, number, number], northPole as [number, number, number, number], matrix);\n    vec4.transformMat4(southPole as [number, number, number, number], southPole as [number, number, number, number], matrix);\n    vec4.transformMat4(center as [number, number, number, number], center as [number, number, number, number], matrix);\n\n    const screenNp = new Point(northPole[0] / northPole[3], northPole[1] / northPole[3]);\n    const screenSp = new Point(southPole[0] / southPole[3], southPole[1] / southPole[3]);\n    const containsNp = polygonContainsPoint(polygon, screenNp) && northPole[3] < center[3];\n    const containsSp = polygonContainsPoint(polygon, screenSp) && southPole[3] < center[3];\n\n    if (!containsNp && !containsSp) {\n        return null;\n    }\n\n    // Project corner points of the polygon and traverse the ring to find the edge that's\n    // crossing the zero longitude border.\n    const result = findEdgeCrossingAntimeridian(polygon, tr, containsNp ? -1 : 1);\n\n    if (!result) {\n        return null;\n    }\n\n    // Start constructing the new polygon by resampling edges until the crossing edge\n    const {idx, t} = result;\n    let partA = idx > 1 ? resamplePolygon(polygon.slice(0, idx), tr) : [];\n    let partB = idx < polygon.length ? resamplePolygon(polygon.slice(idx), tr) : [];\n\n    partA = partA.map(p => new Point(wrap(p.x), p.y));\n    partB = partB.map(p => new Point(wrap(p.x), p.y));\n\n    // Resample first section of the ring (up to the edge that crosses the 0-line)\n    const resampled = [...partA];\n\n    if (resampled.length === 0) {\n        resampled.push(partB[partB.length - 1]);\n    }\n\n    // Find location of the crossing by interpolating mercator coordinates.\n    // This will produce slightly off result as the crossing edge is not actually\n    // linear on the globe.\n    const a = resampled[resampled.length - 1];\n    const b = partB.length === 0 ? partA[0] : partB[0];\n    const intersectionY = interpolate(a.y, b.y, t);\n\n    let mid;\n\n    if (containsNp) {\n        mid = [\n            new Point(0, intersectionY),\n            new Point(0, 0),\n            new Point(1, 0),\n            new Point(1, intersectionY)\n        ];\n    } else {\n        mid = [\n            new Point(1, intersectionY),\n            new Point(1, 1),\n            new Point(0, 1),\n            new Point(0, intersectionY)\n        ];\n    }\n\n    resampled.push(...mid);\n\n    // Resample to the second section of the ring\n    if (partB.length === 0) {\n        resampled.push(partA[0]);\n    } else {\n        resampled.push(...partB);\n    }\n\n    return {\n        polygon: resampled.map(p => new MercatorCoordinate(p.x, p.y)),\n        unwrapped: false\n    };\n}\n\nfunction resamplePolygon(polygon: Point[], transform: Transform): Point[] {\n    // Choose a tolerance value for the resampling logic that produces sufficiently\n    // accurate polygons without creating too many points. The value 1 / 256 was chosen\n    // based on empirical testing\n    const tolerance = 1.0 / 256.0;\n    return resample(\n        polygon,\n        p => {\n            const mc = transform.pointCoordinate3D(p);\n            p.x = mc.x;\n            p.y = mc.y;\n        },\n        tolerance);\n}\n\nfunction wrap(mercatorX: number): number {\n    return mercatorX < 0 ? 1 + (mercatorX % 1) : mercatorX % 1;\n}\n\nfunction findEdgeCrossingAntimeridian(polygon: Point[], tr: Transform, direction: number): {\n    idx: number;\n    t: number;\n} | null | undefined {\n    for (let i = 1; i < polygon.length; i++) {\n        const a = wrap(tr.pointCoordinate3D(polygon[i - 1]).x);\n        const b = wrap(tr.pointCoordinate3D(polygon[i]).x);\n\n        // direction < 0: mercator coordinate 0 will be crossed from left\n        // direction > 0: mercator coordinate 1 will be crossed from right\n        if (direction < 0) {\n            if (a < b) {\n                return {idx: i, t: -a / (b - 1 - a)};\n            }\n        } else {\n            if (b < a) {\n                return {idx: i, t: (1 - a) / (b + 1 - a)};\n            }\n        }\n    }\n\n    return null;\n}\n\n//Padding is in screen pixels and is only used as a coarse check, so 2 decimal places of precision should be good enough for a cache.\nfunction cacheKey(padding: number): number {\n    return (padding * 100) | 0;\n}\n\nexport type TilespaceQueryGeometry = {\n    queryGeometry: QueryGeometry;\n    tilespaceGeometry: Point[];\n    tilespaceRays: Ray[];\n    bufferedTilespaceGeometry: Point[];\n    bufferedTilespaceBounds: {\n        min: Point;\n        max: Point;\n    };\n    tile: Tile;\n    tileID: OverscaledTileID;\n    pixelToTileUnitsFactor: number;\n};\n\nfunction clampBoundsToTileExtents(\n    bounds: {\n        min: Point;\n        max: Point;\n    },\n): {\n    min: Point;\n    max: Point;\n} {\n    bounds.min.x = clamp(bounds.min.x, 0, EXTENT);\n    bounds.min.y = clamp(bounds.min.y, 0, EXTENT);\n\n    bounds.max.x = clamp(bounds.max.x, 0, EXTENT);\n    bounds.max.y = clamp(bounds.max.y, 0, EXTENT);\n    return bounds;\n}\n","import assert from 'assert';\nimport {mat4} from 'gl-matrix';\n\nimport type Point from '@mapbox/point-geometry';\nimport type SourceCache from './source_cache';\nimport type StyleLayer from '../style/style_layer';\nimport type CollisionIndex from '../symbol/collision_index';\nimport type Transform from '../geo/transform';\nimport type {GeoJSONFeature} from '../util/vectortile_to_geojson';\nimport type {OverscaledTileID} from './tile_id';\nimport type {RetainedQueryData} from '../symbol/placement';\nimport type {QueryGeometry, TilespaceQueryGeometry} from '../style/query_geometry';\nimport type {FilterSpecification, ExpressionSpecification} from '../style-spec/types';\n\nexport type QueryResult = {\n    [_: string]: Array<{\n        featureIndex: number;\n        feature: GeoJSONFeature;\n        intersectionZ: boolean | number;\n    }>;\n};\n\nexport type RenderedFeatureLayers = Array<{\n    wrappedTileID: number;\n    queryResults: QueryResult;\n}>;\n\nexport type QueryRenderedFeaturesParams = {\n    scope?: string;\n    layers?: string[];\n    filter?: FilterSpecification;\n    validate?: boolean;\n    availableImages?: string[];\n    serializedLayers?: {\n        [key: string]: StyleLayer;\n    };\n};\n\n/*\n * Returns a matrix that can be used to convert from tile coordinates to viewport pixel coordinates.\n */\nfunction getPixelPosMatrix(transform: Transform, tileID: OverscaledTileID) {\n    const t = mat4.identity([] as any);\n    mat4.scale(t, t, [transform.width * 0.5, -transform.height * 0.5, 1]);\n    mat4.translate(t, t, [1, -1, 0]);\n    mat4.multiply(t, t, transform.calculateProjMatrix(tileID.toUnwrapped()));\n    return Float32Array.from(t);\n}\n\nexport function queryRenderedFeatures(\n    sourceCache: SourceCache,\n    styleLayers: {\n        [_: string]: StyleLayer;\n    },\n    serializedLayers: {\n        [_: string]: any;\n    },\n    queryGeometry: QueryGeometry,\n    params: {\n        filter: FilterSpecification;\n        layers: Array<string>;\n        availableImages: Array<string>;\n    },\n    transform: Transform,\n    use3DQuery: boolean,\n    visualizeQueryGeometry: boolean = false,\n): QueryResult {\n    const tileResults = sourceCache.tilesIn(queryGeometry, use3DQuery, visualizeQueryGeometry);\n    tileResults.sort(sortTilesIn);\n    const renderedFeatureLayers: RenderedFeatureLayers = [];\n    for (const tileResult of tileResults) {\n        renderedFeatureLayers.push({\n            wrappedTileID: tileResult.tile.tileID.wrapped().key,\n            queryResults: tileResult.tile.queryRenderedFeatures(\n                styleLayers,\n                serializedLayers,\n                sourceCache._state,\n                tileResult,\n                params,\n                transform,\n                getPixelPosMatrix(sourceCache.transform, tileResult.tile.tileID),\n                visualizeQueryGeometry)\n        });\n    }\n\n    const result = mergeRenderedFeatureLayers(renderedFeatureLayers);\n\n    // Merge state from SourceCache into the results\n    for (const layerID in result) {\n        result[layerID].forEach((featureWrapper) => {\n            const feature = featureWrapper.feature;\n            const layer = feature.layer;\n\n            if (!layer || layer.type === 'background' || layer.type === 'sky' || layer.type === 'slot') return;\n\n            feature.source = layer.source;\n            if (layer['source-layer']) {\n                feature.sourceLayer = layer['source-layer'];\n            }\n            feature.state = feature.id !== undefined ? sourceCache.getFeatureState(layer['source-layer'], feature.id) : {};\n        });\n    }\n    return result;\n}\n\nexport function queryRenderedSymbols(\n    styleLayers: {\n        [_: string]: StyleLayer;\n    },\n    serializedLayers: {\n        [_: string]: StyleLayer;\n    },\n    getLayerSourceCache: (layer: StyleLayer) => SourceCache | void,\n    queryGeometry: Array<Point>,\n    params: {\n        filter: FilterSpecification;\n        layers: Array<string>;\n        availableImages: Array<string>;\n    },\n    collisionIndex: CollisionIndex,\n    retainedQueryData: {\n        [_: number]: RetainedQueryData;\n    },\n): QueryResult {\n    const result: Record<string, any> = {};\n    const renderedSymbols = collisionIndex.queryRenderedSymbols(queryGeometry);\n    const bucketQueryData = [];\n    for (const bucketInstanceId of Object.keys(renderedSymbols).map(Number)) {\n        bucketQueryData.push(retainedQueryData[bucketInstanceId]);\n    }\n    bucketQueryData.sort(sortTilesIn);\n\n    for (const queryData of bucketQueryData) {\n        const bucketSymbols = queryData.featureIndex.lookupSymbolFeatures(\n                renderedSymbols[queryData.bucketInstanceId],\n                serializedLayers,\n                queryData.bucketIndex,\n                queryData.sourceLayerIndex,\n                params.filter,\n                params.layers,\n                params.availableImages,\n                styleLayers);\n\n        for (const layerID in bucketSymbols) {\n            const resultFeatures = result[layerID] = result[layerID] || [];\n            const layerSymbols = bucketSymbols[layerID];\n            layerSymbols.sort((a, b) => {\n                // Match topDownFeatureComparator from FeatureIndex, but using\n                // most recent sorting of features from bucket.sortFeatures\n                const featureSortOrder = queryData.featureSortOrder;\n                if (featureSortOrder) {\n                    // queryRenderedSymbols documentation says we'll return features in\n                    // \"top-to-bottom\" rendering order (aka last-to-first).\n                    // Actually there can be multiple symbol instances per feature, so\n                    // we sort each feature based on the first matching symbol instance.\n                    const sortedA = featureSortOrder.indexOf(a.featureIndex);\n                    const sortedB = featureSortOrder.indexOf(b.featureIndex);\n                    assert(sortedA >= 0);\n                    assert(sortedB >= 0);\n                    return sortedB - sortedA;\n                } else {\n                    // Bucket hasn't been re-sorted based on angle, so use the\n                    // reverse of the order the features appeared in the data.\n                    return b.featureIndex - a.featureIndex;\n                }\n            });\n            for (const symbolFeature of layerSymbols) {\n                resultFeatures.push(symbolFeature);\n            }\n        }\n    }\n\n    // Merge state from SourceCache into the results\n    for (const layerName in result) {\n        result[layerName].forEach((featureWrapper) => {\n            const feature = featureWrapper.feature;\n            const layer = styleLayers[layerName];\n            const sourceCache = getLayerSourceCache(layer);\n            if (!sourceCache) return;\n\n            const state = sourceCache.getFeatureState(feature.layer['source-layer'], feature.id);\n            feature.source = feature.layer.source;\n            if (feature.layer['source-layer']) {\n                feature.sourceLayer = feature.layer['source-layer'];\n            }\n            feature.state = state;\n        });\n    }\n    return result;\n}\n\nexport function querySourceFeatures(sourceCache: SourceCache, params?: {\n    sourceLayer?: string;\n    filter?: FilterSpecification;\n    validate?: boolean;\n}): Array<GeoJSONFeature> {\n    const tiles = sourceCache.getRenderableIds().map((id) => {\n        return sourceCache.getTileByID(id);\n    });\n\n    const result = [];\n\n    const dataTiles: Record<string, any> = {};\n    for (let i = 0; i < tiles.length; i++) {\n        const tile = tiles[i];\n        const dataID = tile.tileID.canonical.key;\n        if (!dataTiles[dataID]) {\n            dataTiles[dataID] = true;\n            tile.querySourceFeatures(result, params);\n        }\n    }\n\n    return result;\n}\n\nfunction sortTilesIn(a: TilespaceQueryGeometry | RetainedQueryData, b: TilespaceQueryGeometry | RetainedQueryData) {\n    const idA = a.tileID;\n    const idB = b.tileID;\n    return (idA.overscaledZ - idB.overscaledZ) || (idA.canonical.y - idB.canonical.y) || (idA.wrap - idB.wrap) || (idA.canonical.x - idB.canonical.x);\n}\n\nfunction mergeRenderedFeatureLayers(tiles: RenderedFeatureLayers): QueryResult {\n    // Merge results from all tiles, but if two tiles share the same\n    // wrapped ID, don't duplicate features between the two tiles\n    const result: QueryResult = {};\n    const wrappedIDLayerMap: Record<string, any> = {};\n    for (const tile of tiles) {\n        const queryResults = tile.queryResults;\n        const wrappedID = tile.wrappedTileID;\n        const wrappedIDLayers = wrappedIDLayerMap[wrappedID] = wrappedIDLayerMap[wrappedID] || {};\n        for (const layerID in queryResults) {\n            const tileFeatures = queryResults[layerID];\n            const wrappedIDFeatures = wrappedIDLayers[layerID] = wrappedIDLayers[layerID] || {};\n            const resultFeatures = result[layerID] = result[layerID] || [];\n            for (const tileFeature of tileFeatures) {\n                if (!wrappedIDFeatures[tileFeature.featureIndex]) {\n                    wrappedIDFeatures[tileFeature.featureIndex] = true;\n                    resultFeatures.push(tileFeature);\n                }\n            }\n        }\n    }\n    return result;\n}\n","import FillExtrusionBucket from '../data/bucket/fill_extrusion_bucket';\nimport StyleLayer from '../style/style_layer';\nimport EXTENT from '../style-spec/data/extent';\nimport SymbolBucket from '../data/bucket/symbol_bucket';\nimport FillExtrusionStyleLayer from '../style/style_layer/fill_extrusion_style_layer';\nimport {OverscaledTileID} from './tile_id';\n\nimport type Style from '../style/style';\nimport type Tiled3dModelBucket from '../../3d-style/data/bucket/tiled_3d_model_bucket';\nimport type {Bucket} from '../data/bucket';\nimport ModelStyleLayer from '../../3d-style/style/style_layer/model_style_layer';\n\nclass BuildingIndex {\n    style: Style;\n    layers: Array<{\n        layer: StyleLayer;\n        visible: boolean;\n    }>;\n    currentBuildingBuckets: Array<{\n        bucket: Bucket | null | undefined;\n        tileID: OverscaledTileID;\n        verticalScale: number;\n    }>;\n    layersGotHidden: boolean; // when layer're hidden since the last frame, don't keep previous elevation, while loading tiles.\n\n    constructor(style: Style) {\n        this.style = style;\n        this.layersGotHidden = false;\n        this.layers = [];\n    }\n\n    processLayersChanged() {\n        this.layers = [];\n        const visible = false, visibilityChanged = false;\n        for (const layerId in this.style._mergedLayers) {\n            const layer = this.style._mergedLayers[layerId];\n            if (layer.type === 'fill-extrusion') {\n                // @ts-expect-error - TS2353 - Object literal may only specify known properties, and 'visibilityChanged' does not exist in type '{ layer: StyleLayer; visible: boolean; }'.\n                this.layers.push({layer, visible, visibilityChanged});\n            } else if (layer.type === 'model') {\n                const source = this.style.getLayerSource(layer);\n                if (source && source.type === 'batched-model') {\n                    // @ts-expect-error - TS2353 - Object literal may only specify known properties, and 'visibilityChanged' does not exist in type '{ layer: StyleLayer; visible: boolean; }'.\n                    this.layers.push({layer, visible, visibilityChanged});\n                }\n            }\n        }\n    }\n\n    // Check if some of the building layers are disabled or with opacity evaluated to 0.\n    onNewFrame(zoom: number) {\n        this.layersGotHidden = false;\n        for (const l of this.layers) {\n            const layer = l.layer;\n            let visible = false;\n            if (layer.type === 'fill-extrusion') {\n\n                visible = !layer.isHidden(zoom) && (layer as FillExtrusionStyleLayer).paint.get('fill-extrusion-opacity') > 0.0;\n            } else if (layer.type === 'model') {\n\n                visible = !layer.isHidden(zoom) && (layer as ModelStyleLayer).paint.get('model-opacity') > 0.0;\n            }\n            this.layersGotHidden = this.layersGotHidden || (!visible && l.visible);\n            l.visible = visible;\n        }\n    }\n\n    updateZOffset(symbolBucket: SymbolBucket, tileID: OverscaledTileID) {\n        // prepare lookup from bucket to overlapping buckets of all building layers.\n        this.currentBuildingBuckets = [];\n        for (const l of this.layers) {\n            const layer = l.layer;\n            const sourceCache = this.style.getLayerSourceCache(layer);\n\n            let verticalScale = 1;\n            if (layer.type === 'fill-extrusion') {\n\n                verticalScale = l.visible ? (layer as FillExtrusionStyleLayer).paint.get('fill-extrusion-vertical-scale') : 0;\n            }\n\n            let tile = sourceCache ? sourceCache.getTile(tileID) : null;\n\n            if (!tile && sourceCache && tileID.canonical.z > sourceCache.getSource().minzoom) {\n                let id = tileID.scaledTo(Math.min(sourceCache.getSource().maxzoom, tileID.overscaledZ - 1));\n                while (id.overscaledZ >= sourceCache.getSource().minzoom) {\n                    tile = sourceCache.getTile(id);\n                    if (tile || id.overscaledZ === 0) break;\n                    id = id.scaledTo(id.overscaledZ - 1);\n                }\n            }\n            this.currentBuildingBuckets.push({bucket: tile ? tile.getBucket(layer) : null, tileID: tile ? tile.tileID : tileID, verticalScale});\n        }\n\n        symbolBucket.hasAnyZOffset = false;\n        let dataChanged = false;\n        for (let s = 0; s < symbolBucket.symbolInstances.length; s++) {\n            const symbolInstance = symbolBucket.symbolInstances.get(s);\n            const currentZOffset = symbolInstance.zOffset;\n            const newZOffset = this._getHeightAtTileOffset(tileID, symbolInstance.tileAnchorX, symbolInstance.tileAnchorY);\n\n            // When zooming over integer zooms, keep the elevation while loading building buckets.\n            symbolInstance.zOffset = newZOffset !== Number