    this.precompilePrograms(layer, parameters);\n                    });\n                } else {\n                    this.precompilePrograms(layer, parameters);\n                }\n            }\n        }\n        if (this._shouldPrecompile) {\n            this._precompileDone = true;\n        }\n\n        if (this.terrain && layersUpdated) {\n            // Changed layers (layout properties only) could have become drapeable.\n            this.mergeLayers();\n        }\n\n        for (const sourceId in sourcesUsedBefore) {\n            const sourceCache = this._mergedSourceCaches[sourceId];\n            if (sourcesUsedBefore[sourceId] !== sourceCache.used) {\n                const source = sourceCache.getSource() as ISource;\n                source.fire(new Event('data', {sourceDataType: 'visibility', dataType:'source', sourceId: sourceCache.getSource().id}));\n            }\n        }\n\n        if (this.light) {\n            this.light.recalculate(parameters);\n        }\n\n        if (this.terrain) {\n            this.terrain.recalculate(parameters);\n        }\n\n        if (this.fog) {\n            this.fog.recalculate(parameters);\n        }\n\n        this.z = parameters.zoom;\n\n        if (this._markersNeedUpdate) {\n            this._updateMarkersOpacity();\n            this._markersNeedUpdate = false;\n        }\n\n        if (changed) {\n            this.fire(new Event('data', {dataType: 'style'}));\n        }\n    }\n\n    /*\n     * Apply any queued image changes.\n     */\n    _updateTilesForChangedImages() {\n        const updatedImages = this._changes.getUpdatedImages();\n        if (updatedImages.length) {\n            for (const name in this._sourceCaches) {\n                this._sourceCaches[name].reloadTilesForDependencies(['icons', 'patterns'], updatedImages);\n            }\n            this._changes.resetUpdatedImages();\n        }\n    }\n\n    _updateWorkerLayers(scope: string, updatedIds?: Array<string>, removedIds?: Array<string>) {\n        const fragmentStyle = this.getFragmentStyle(scope);\n        if (!fragmentStyle) return;\n\n        this.dispatcher.broadcast('updateLayers', {\n            layers: updatedIds ? fragmentStyle._serializeLayers(updatedIds) : [],\n            scope,\n            removedIds: removedIds || [],\n            options: fragmentStyle.options\n        });\n    }\n\n    /**\n     * Update this style's state to match the given style JSON, performing only\n     * the necessary mutations.\n     *\n     * May throw an Error ('Unimplemented: METHOD') if the mapbox-gl-style-spec\n     * diff algorithm produces an operation that is not supported.\n     *\n     * @returns {boolean} true if any changes were made; false otherwise\n     * @private\n     */\n    setState(nextState: StyleSpecification, onFinish?: () => void): boolean {\n        this._checkLoaded();\n\n        if (emitValidationErrors(this, validateStyle(nextState))) return false;\n\n        nextState = clone(nextState);\n        nextState.layers = deref(nextState.layers);\n\n        const changes = diffStyles(this.serialize(), nextState)\n            .filter(op => !(op.command in ignoredDiffOperations));\n\n        if (changes.length === 0) {\n            return false;\n        }\n\n        const unimplementedOps = changes.filter(op => !(op.command in supportedDiffOperations));\n        if (unimplementedOps.length > 0) {\n            throw new Error(`Unimplemented: ${unimplementedOps.map(op => op.command).join(', ')}.`);\n        }\n\n        const changesPromises = [];\n\n        changes.forEach((op) => {\n            changesPromises.push((this as any)[op.command].apply(this, op.args));\n        });\n\n        if (onFinish) {\n            Promise.all(changesPromises).then(onFinish);\n        }\n\n        this.stylesheet = nextState;\n        this.mergeAll();\n\n        this.dispatcher.broadcast('setLayers', {\n            layers: this._serializeLayers(this._order),\n            scope: this.scope,\n            options: this.options\n        });\n\n        return true;\n    }\n\n    addImage(id: string, image: StyleImage): this {\n        if (this.getImage(id)) {\n            return this.fire(new ErrorEvent(new Error('An image with this name already exists.')));\n        }\n        this.imageManager.addImage(id, this.scope, image);\n        this._afterImageUpdated(id);\n        return this;\n    }\n\n    updateImage(id: string, image: StyleImage) {\n        this.imageManager.updateImage(id, this.scope, image);\n    }\n\n    getImage(id: string): StyleImage | null | undefined {\n        return this.imageManager.getImage(id, this.scope);\n    }\n\n    removeImage(id: string): this {\n        if (!this.getImage(id)) {\n            return this.fire(new ErrorEvent(new Error('No image with this name exists.')));\n        }\n        this.imageManager.removeImage(id, this.scope);\n        this._afterImageUpdated(id);\n        return this;\n    }\n\n    _afterImageUpdated(id: string) {\n        this._availableImages = this.imageManager.listImages(this.scope);\n        this._changes.updateImage(id);\n        this.dispatcher.broadcast('setImages', {\n            scope: this.scope,\n            images: this._availableImages\n        });\n        this.fire(new Event('data', {dataType: 'style'}));\n    }\n\n    listImages(): Array<string> {\n        this._checkLoaded();\n        return this._availableImages.slice();\n    }\n\n    addModel(id: string, url: string, options: StyleSetterOptions = {}): this {\n        this._checkLoaded();\n        if (this._validate(validateModel, `models.${id}`, url, null, options)) return this;\n\n        this.modelManager.addModel(id, url, this.scope);\n        this._changes.setDirty();\n        return this;\n    }\n\n    hasModel(id: string): boolean {\n        return this.modelManager.hasModel(id, this.scope);\n    }\n\n    removeModel(id: string): this {\n        if (!this.hasModel(id)) {\n            return this.fire(new ErrorEvent(new Error('No model with this ID exists.')));\n        }\n        this.modelManager.removeModel(id, this.scope);\n        return this;\n    }\n\n    listModels(): Array<string> {\n        this._checkLoaded();\n        return this.modelManager.listModels(this.scope);\n    }\n\n    addSource(id: string, source: SourceSpecification, options: StyleSetterOptions = {}): void {\n        this._checkLoaded();\n\n        if (this.getOwnSource(id) !== undefined) {\n            throw new Error(`There is already a source with ID \"${id}\".`);\n        }\n\n        if (!source.type) {\n            throw new Error(`The type property must be defined, but only the following properties were given: ${Object.keys(source).join(', ')}.`);\n        }\n\n        const builtIns = ['vector', 'raster', 'geojson', 'video', 'image'];\n        const shouldValidate = builtIns.indexOf(source.type) >= 0;\n        if (shouldValidate && this._validate(validateSource, `sources.${id}`, source, null, options)) return;\n\n        if (this.map && this.map._collectResourceTiming) (source as any).collectResourceTiming = true;\n        const sourceInstance = createSource(id, source, this.dispatcher, this);\n        sourceInstance.scope = this.scope;\n\n        sourceInstance.setEventedParent(this, () => ({\n            isSourceLoaded: this._isSourceCacheLoaded(sourceInstance.id),\n            source: sourceInstance.serialize(),\n            sourceId: sourceInstance.id\n        }));\n\n        const addSourceCache = (onlySymbols: boolean) => {\n            const sourceCacheId = (onlySymbols ? 'symbol:' : 'other:') + sourceInstance.id;\n            const sourceCacheFQID = makeFQID(sourceCacheId, this.scope);\n            const sourceCache = this._sourceCaches[sourceCacheId] = new SourceCache(sourceCacheFQID, sourceInstance, onlySymbols);\n            (onlySymbols ? this._symbolSourceCaches : this._otherSourceCaches)[sourceInstance.id] = sourceCache;\n            sourceCache.onAdd(this.map);\n        };\n\n        addSourceCache(false);\n        if (source.type === 'vector' || source.type === 'geojson') {\n            addSourceCache(true);\n        }\n\n        if (sourceInstance.onAdd)\n            sourceInstance.onAdd(this.map);\n\n        // Avoid triggering redundant style update after adding initial sources.\n        if (!options.isInitialLoad) {\n            this.mergeSources();\n            this._changes.setDirty();\n        }\n    }\n\n    /**\n     * Remove a source from this stylesheet, given its ID.\n     * @param {string} id ID of the source to remove.\n     * @throws {Error} If no source is found with the given ID.\n     * @returns {Map} The {@link Map} object.\n     */\n    removeSource(id: string): this {\n        this._checkLoaded();\n\n        const source = this.getOwnSource(id);\n        if (!source) {\n            throw new Error('There is no source with this ID');\n        }\n        for (const layerId in this._layers) {\n            if (this._layers[layerId].source === id) {\n                return this.fire(new ErrorEvent(new Error(`Source \"${id}\" cannot be removed while layer \"${layerId}\" is using it.`)));\n            }\n        }\n        if (this.terrain && this.terrain.scope === this.scope && this.terrain.get().source === id) {\n            return this.fire(new ErrorEvent(new Error(`Source \"${id}\" cannot be removed while terrain is using it.`)));\n        }\n\n        const sourceCaches = this.getOwnSourceCaches(id);\n        for (const sourceCache of sourceCaches) {\n            const id = getNameFromFQID(sourceCache.id);\n            delete this._sourceCaches[id];\n            this._changes.discardSourceCacheUpdate(sourceCache.id);\n            sourceCache.fire(new Event('data', {sourceDataType: 'metadata', dataType:'source', sourceId: sourceCache.getSource().id}));\n            sourceCache.setEventedParent(null);\n            sourceCache.clearTiles();\n        }\n        delete this._otherSourceCaches[id];\n        delete this._symbolSourceCaches[id];\n        this.mergeSources();\n\n        source.setEventedParent(null);\n        if (source.onRemove)\n            source.onRemove(this.map);\n        this._changes.setDirty();\n        return this;\n    }\n\n    /**\n     * Set the data of a GeoJSON source, given its ID.\n     * @param {string} id ID of the source.\n     * @param {GeoJSON|string} data GeoJSON source.\n     */\n    setGeoJSONSourceData(id: string, data: GeoJSON.GeoJSON | string) {\n        this._checkLoaded();\n\n        assert(this.getOwnSource(id) !== undefined, 'There is no source with this ID');\n        const geojsonSource: GeoJSONSource = this.getOwnSource(id);\n        assert(geojsonSource.type === 'geojson');\n\n        geojsonSource.setData(data);\n        this._changes.setDirty();\n    }\n\n    /**\n     * Get a source by ID.\n     * @param {string} id ID of the desired source.\n     * @returns {?Source} The source object.\n     */\n    getOwnSource<T extends Source>(id: string): T | undefined {\n        const sourceCache = this.getOwnSourceCache(id);\n        return sourceCache && sourceCache.getSource();\n    }\n\n    getOwnSources(): Source[] {\n        const sources = [];\n        for (const id in this._otherSourceCaches) {\n            const sourceCache = this.getOwnSourceCache(id);\n            if (sourceCache) sources.push(sourceCache.getSource());\n        }\n\n        return sources;\n    }\n\n    areTilesLoaded(): boolean {\n        const sources = this._mergedSourceCaches;\n        for (const id in sources) {\n            const source = sources[id];\n            const tiles = source._tiles;\n            for (const t in tiles) {\n                const tile = tiles[t];\n                if (!(tile.state === 'loaded' || tile.state === 'errored')) return false;\n            }\n        }\n        return true;\n    }\n\n    setLights(lights?: Array<LightsSpecification> | null) {\n        this._checkLoaded();\n\n        if (!lights) {\n            delete this.ambientLight;\n            delete this.directionalLight;\n            return;\n        }\n\n        const transitionParameters = this._getTransitionParameters();\n\n        for (const light of lights) {\n            // @ts-expect-error - TS2554 - Expected 4-5 arguments, but got 3.\n            if (this._validate(validateLights, 'lights', light)) {\n                return;\n            }\n\n            switch (light.type) {\n            case 'ambient':\n                if (this.ambientLight) {\n                    const ambientLight = this.ambientLight;\n                    ambientLight.set(light);\n                    ambientLight.updateTransitions(transitionParameters);\n                } else {\n                    this.ambientLight = new Lights<Ambient>(light, getAmbientProps(), this.scope, this.options);\n                }\n                break;\n            case 'directional':\n                if (this.directionalLight) {\n                    const directionalLight = this.directionalLight;\n                    directionalLight.set(light);\n                    directionalLight.updateTransitions(transitionParameters);\n                } else {\n                    this.directionalLight = new Lights<Directional>(light, getDirectionalProps(), this.scope, this.options);\n                }\n                break;\n            default:\n                assert(false, `Unknown light type: ${light.type}`);\n            }\n        }\n\n        const evaluationParameters = new EvaluationParameters(this.z || 0, transitionParameters);\n\n        if (this.ambientLight) {\n            this.ambientLight.recalculate(evaluationParameters);\n        }\n\n        if (this.directionalLight) {\n            this.directionalLight.recalculate(evaluationParameters);\n        }\n\n        this._brightness = this.calculateLightsBrightness();\n        this.dispatcher.broadcast('setBrightness', this._brightness);\n    }\n\n    calculateLightsBrightness(): number | null | undefined {\n        const directional = this.directionalLight;\n        const ambient = this.ambientLight;\n\n        if (!directional || !ambient) {\n            return;\n        }\n\n        // Based on: https://www.w3.org/WAI/GL/wiki/Relative_luminance\n        const relativeLuminance = (color: [number, number, number, number]) => {\n            const r = color[0] <= 0.03928 ? (color[0] / 12.92) : Math.pow(((color[0] + 0.055) / 1.055), 2.4);\n            const g = color[1] <= 0.03928 ? (color[1] / 12.92) : Math.pow(((color[1] + 0.055) / 1.055), 2.4);\n            const b = color[2] <= 0.03928 ? (color[2] / 12.92) : Math.pow(((color[2] + 0.055) / 1.055), 2.4);\n            return 0.2126 * r + 0.7152 * g + 0.0722 * b;\n        };\n\n        const directionalColor = directional.properties.get('color').toRenderColor(null).toArray01();\n        const directionalIntensity = directional.properties.get('intensity');\n        const direction = directional.properties.get('direction');\n\n        const sphericalDirection = cartesianPositionToSpherical(direction.x, direction.y, direction.z);\n        const polarIntensity = 1.0 - sphericalDirection[2] / 90.0;\n\n        const directionalBrightness = relativeLuminance(directionalColor) * directionalIntensity * polarIntensity;\n\n        const ambientColor = ambient.properties.get('color').toRenderColor(null).toArray01();\n        const ambientIntensity = ambient.properties.get('intensity');\n\n        const ambientBrightness = relativeLuminance(ambientColor) * ambientIntensity;\n\n        return (directionalBrightness + ambientBrightness) / 2.0;\n    }\n\n    getBrightness(): number | null | undefined {\n        return this._brightness;\n    }\n\n    getLights(): Array<LightsSpecification> | null | undefined {\n        if (!this.enable3dLights()) return null;\n        const lights = [];\n        if (this.directionalLight) {\n            lights.push(this.directionalLight.get());\n        }\n        if (this.ambientLight) {\n            lights.push(this.ambientLight.get());\n        }\n        return lights;\n    }\n\n    enable3dLights(): boolean {\n        return !!this.ambientLight && !!this.directionalLight;\n    }\n\n    getFragmentStyle(fragmentId?: string): Style | null | undefined {\n        if (!fragmentId) return this;\n\n        if (isFQID(fragmentId)) {\n            const scope = getScopeFromFQID(fragmentId);\n            const fragment = this.fragments.find(({id}) => id === scope);\n            if (!fragment) throw new Error(`Style import not found: ${fragmentId}`);\n            const name = getNameFromFQID(fragmentId);\n            return fragment.style.getFragmentStyle(name);\n        } else {\n            const fragment = this.fragments.find(({id}) => id === fragmentId);\n            if (!fragment) throw new Error(`Style import not found: ${fragmentId}`);\n            return fragment.style;\n        }\n    }\n\n    getConfigProperty(fragmentId: string, key: string): unknown {\n        const fragmentStyle = this.getFragmentStyle(fragmentId);\n        if (!fragmentStyle) return null;\n        const fqid = makeFQID(key, fragmentStyle.scope);\n        const expressions = fragmentStyle.options.get(fqid);\n        const expression = expressions ? expressions.value || expressions.default : null;\n        return expression ? expression.serialize() : null;\n    }\n\n    setConfigProperty(fragmentId: string, key: string, value: unknown) {\n        const fragmentStyle = this.getFragmentStyle(fragmentId);\n        if (!fragmentStyle) return;\n\n        const schema = fragmentStyle.stylesheet.schema;\n        if (!schema || !schema[key]) return;\n\n        const expressionParsed = createExpression(value);\n        if (expressionParsed.result !== 'success') {\n            emitValidationErrors(this, expressionParsed.value);\n            return;\n        }\n\n        const expression = expressionParsed.value.expression;\n\n        const fqid = makeFQID(key, fragmentStyle.scope);\n        const expressions = fragmentStyle.options.get(fqid);\n        if (!expressions) return;\n\n        let defaultExpression;\n        const {minValue, maxValue, stepValue, type, values} = schema[key];\n        const defaultExpressionParsed = createExpression(schema[key].default);\n        if (defaultExpressionParsed.result === 'success') {\n            defaultExpression = defaultExpressionParsed.value.expression;\n        }\n\n        if (!defaultExpression) {\n            this.fire(new ErrorEvent(new Error(`No schema defined for the config option \"${key}\" in the \"${fragmentId}\" fragment.`)));\n            return;\n        }\n\n        this.options.set(fqid, {\n            ...expressions,\n            value: expression,\n            default: defaultExpression,\n            minValue, maxValue, stepValue, type, values\n        });\n\n        this.updateConfigDependencies(key);\n    }\n\n    getConfig(fragmentId: string): ConfigSpecification | null | undefined {\n        const fragmentStyle = this.getFragmentStyle(fragmentId);\n        if (!fragmentStyle) return null;\n\n        const schema = fragmentStyle.stylesheet.schema;\n        if (!schema) return null;\n\n        const config: Record<string, any> = {};\n        for (const key in schema) {\n            const fqid = makeFQID(key, fragmentStyle.scope);\n            const expressions = fragmentStyle.options.get(fqid);\n            const expression = expressions ? expressions.value || expressions.default : null;\n            config[key] = expression ? expression.serialize() : null;\n        }\n\n        return config;\n    }\n\n    setConfig(fragmentId: string, config?: ConfigSpecification | null) {\n        const fragmentStyle = this.getFragmentStyle(fragmentId);\n        if (!fragmentStyle) return;\n\n        const schema = fragmentStyle.stylesheet.schema;\n        fragmentStyle.updateConfig(config, schema);\n\n        this.updateConfigDependencies();\n    }\n\n    getSchema(fragmentId: string): SchemaSpecification | null | undefined {\n        const fragmentStyle = this.getFragmentStyle(fragmentId);\n        if (!fragmentStyle) return null;\n        return fragmentStyle.stylesheet.schema;\n    }\n\n    setSchema(fragmentId: string, schema: SchemaSpecification) {\n        const fragmentStyle = this.getFragmentStyle(fragmentId);\n        if (!fragmentStyle) return;\n\n        fragmentStyle.stylesheet.schema = schema;\n        fragmentStyle.updateConfig(fragmentStyle._config, schema);\n\n        this.updateConfigDependencies();\n    }\n\n    updateConfig(config?: ConfigSpecification | null, schema?: SchemaSpecification | null) {\n        this._config = config;\n\n        if (!config && !schema) return;\n\n        if (!schema) {\n            this.fire(new ErrorEvent(new Error(`Attempting to set config for a style without schema.`)));\n            return;\n        }\n\n        for (const id in schema) {\n            let defaultExpression;\n            let configExpression;\n\n            const expression = schema[id].default;\n            const expressionParsed = createExpression(expression);\n            if (expressionParsed.result === 'success') {\n                defaultExpression = expressionParsed.value.expression;\n            }\n\n            if (config && config[id] !== undefined) {\n                const expressionParsed = createExpression(config[id]);\n                if (expressionParsed.result === 'success') {\n                    configExpression = expressionParsed.value.expression;\n                }\n            }\n\n            const {minValue, maxValue, stepValue, type, values} = schema[id];\n\n            if (defaultExpression) {\n                const fqid = makeFQID(id, this.scope);\n                this.options.set(fqid, {\n                    default: defaultExpression,\n                    value: configExpression,\n                    minValue, maxValue, stepValue, type, values\n                });\n            } else {\n                this.fire(new ErrorEvent(new Error(`No schema defined for config option \"${id}\".`)));\n            }\n        }\n    }\n\n    updateConfigDependencies(configKey?: string) {\n        for (const id of this._configDependentLayers) {\n            const layer = this.getLayer(id);\n            if (layer) {\n                if (configKey && !layer.configDependencies.has(configKey)) {\n                    continue;\n                }\n\n                layer.possiblyEvaluateVisibility();\n                this._updateLayer(layer);\n            }\n        }\n\n        if (this.ambientLight) {\n            this.ambientLight.updateConfig(this.options);\n        }\n\n        if (this.directionalLight) {\n            this.directionalLight.updateConfig(this.options);\n        }\n\n        if (this.fog) {\n            this.fog.updateConfig(this.options);\n        }\n\n        this.forEachFragmentStyle((style: Style) => {\n            if (style._styleColorTheme.colorTheme) {\n                const data = style._evaluateColorThemeData(style._styleColorTheme.colorTheme);\n                if ((!style._styleColorTheme.lut && data !== '') || (style._styleColorTheme.lut && data !== style._styleColorTheme.lut.data)) {\n                    style.setColorTheme(style._styleColorTheme.colorTheme);\n                }\n            }\n        });\n\n        this._changes.setDirty();\n    }\n\n    /**\n     * Add a layer to the map style. The layer will be inserted before the layer with\n     * ID `before`, or appended if `before` is omitted.\n     * @param {Object | CustomLayerInterface} layerObject The style layer to add.\n     * @param {string} [before] ID of an existing layer to insert before.\n     * @param {Object} options Style setter options.\n     * @returns {Map} The {@link Map} object.\n     */\n    addLayer(layerObject: AnyLayer, before?: string, options: StyleSetterOptions = {}) {\n        this._checkLoaded();\n\n        const id = layerObject.id;\n\n        if (this._layers[id]) {\n            this.fire(new ErrorEvent(new Error(`Layer with id \"${id}\" already exists on this map`)));\n            return;\n        }\n\n        let layer;\n        if (layerObject.type === 'custom') {\n            if (emitValidationErrors(this, validateCustomStyleLayer(layerObject))) return;\n            layer = createStyleLayer(layerObject, this.scope, this._styleColorTheme.lut, this.options);\n        } else {\n            if (typeof layerObject.source === 'object') {\n                this.addSource(id, layerObject.source);\n                layerObject = clone(layerObject);\n                layerObject = (extend(layerObject, {source: id}));\n            }\n\n            // this layer is not in the style.layers array, so we pass an impossible array index\n            if (this._validate(validateLayer,\n                `layers.${id}`, layerObject, {arrayIndex: -1}, options)) return;\n\n            layer = createStyleLayer(layerObject as LayerSpecification, this.scope, this._styleColorTheme.lut, this.options);\n            this._validateLayer(layer);\n\n            layer.setEventedParent(this, {layer: {id}});\n            this._serializedLayers[layer.id] = layer.serialize();\n        }\n\n        if (layer.configDependencies.size !== 0) this._configDependentLayers.add(layer.fqid);\n\n        let index = this._order.length;\n        if (before) {\n            const beforeIndex = this._order.indexOf(before);\n            if (beforeIndex === -1) {\n                this.fire(new ErrorEvent(new Error(`Layer with id \"${before}\" does not exist on this map.`)));\n                return;\n            }\n\n            // If the layer we're inserting doesn't have a slot,\n            // or it has the same slot as the 'before' layer,\n            // then we can insert the new layer before the existing one.\n            const beforeLayer = this._layers[before];\n            if (layer.slot === beforeLayer.slot) index = beforeIndex;\n            else warnOnce(`Layer with id \"${before}\" has a different slot. Layers can only be rearranged within the same slot.`);\n        }\n\n        this._order.splice(index, 0, id);\n        this._layerOrderChanged = true;\n\n        this._layers[id] = layer;\n\n        const sourceCache = this.getOwnLayerSourceCache(layer);\n        const shadowsEnabled = !!this.directionalLight && this.directionalLight.shadowsEnabled();\n\n        if (sourceCache && layer.canCastShadows() && shadowsEnabled) {\n            sourceCache.castsShadows = true;\n        }\n\n        const removedLayer = this._changes.getRemovedLayer(layer);\n        if (removedLayer && layer.source && sourceCache && layer.type !== 'custom') {\n            // If, in the current batch, we have already removed this layer\n            // and we are now re-adding it with a different `type`, then we\n            // need to clear (rather than just reload) the underyling source's\n            // tiles.  Otherwise, tiles marked 'reloading' will have buckets /\n            // buffers that are set up for the _previous_ version of this\n            // layer, causing, e.g.:\n            // https://github.com/mapbox/mapbox-gl-js/issues/3633\n            this._changes.discardLayerRemoval(layer);\n            const fqid = makeFQID(layer.source, layer.scope);\n            if (removedLayer.type !== layer.type) {\n                this._changes.updateSourceCache(fqid, 'clear');\n            } else {\n                this._changes.updateSourceCache(fqid, 'reload');\n                sourceCache.pause();\n            }\n        }\n\n        this._updateLayer(layer);\n\n        if (layer.onAdd) {\n            layer.onAdd(this.map);\n        }\n\n        layer.scope = this.scope;\n\n        this.mergeLayers();\n    }\n\n    /**\n     * Moves a layer to a different z-position. The layer will be inserted before the layer with\n     * ID `before`, or appended if `before` is omitted.\n     * @param {string} id  ID of the layer to move.\n     * @param {string} [before] ID of an existing layer to insert before.\n     */\n    moveLayer(id: string, before?: string) {\n        this._checkLoaded();\n\n        const layer = this._checkLayer(id);\n        if (!layer) return;\n\n        if (id === before) {\n            return;\n        }\n\n        const index = this._order.indexOf(id);\n        this._order.splice(index, 1);\n\n        let newIndex = this._order.length;\n        if (before) {\n            const beforeIndex = this._order.indexOf(before);\n            if (beforeIndex === -1) {\n                this.fire(new ErrorEvent(new Error(`Layer with id \"${before}\" does not exist on this map.`)));\n                return;\n            }\n\n            // If the layer we're moving doesn't have a slot,\n            // or it has the same slot as the 'before' layer,\n            // then we can insert the new layer before the existing one.\n            const beforeLayer = this._layers[before];\n            if (layer.slot === beforeLayer.slot) newIndex = beforeIndex;\n            else warnOnce(`Layer with id \"${before}\" has a different slot. Layers can only be rearranged within the same slot.`);\n        }\n\n        this._order.splice(newIndex, 0, id);\n\n        this._changes.setDirty();\n        this._layerOrderChanged = true;\n\n        this.mergeLayers();\n    }\n\n    /**\n     * Remove the layer with the given id from the style.\n     *\n     * If no such layer exists, an `error` event is fired.\n     *\n     * @param {string} id ID of the layer to remove.\n     * @fires Map.event:error\n     */\n    removeLayer(id: string) {\n        this._checkLoaded();\n\n        const layer = this._checkLayer(id);\n        if (!layer) return;\n\n        layer.setEventedParent(null);\n\n        const index = this._order.indexOf(id);\n        this._order.splice(index, 1);\n\n        delete this._layers[id];\n        delete this._serializedLayers[id];\n\n        this._changes.setDirty();\n        this._layerOrderChanged = true;\n\n        this._configDependentLayers.delete(layer.fqid);\n        this._changes.removeLayer(layer);\n\n        const sourceCache = this.getOwnLayerSourceCache(layer);\n\n        if (sourceCache && sourceCache.castsShadows) {\n            let shadowCastersLeft = false;\n            for (const key in this._layers) {\n                if (this._layers[key].source === layer.source && this._layers[key].canCastShadows()) {\n                    shadowCastersLeft = true;\n                    break;\n                }\n            }\n\n            sourceCache.castsShadows = shadowCastersLeft;\n        }\n\n        if (layer.onRemove) {\n            layer.onRemove(this.map);\n        }\n\n        this.mergeLayers();\n    }\n\n    /**\n     * Return the style layer object with the given `id`.\n     *\n     * @param {string} id ID of the desired layer.\n     * @returns {?StyleLayer} A layer, if one with the given `id` exists.\n     */\n    getOwnLayer<T extends StyleLayer>(id: string): T | undefined {\n        return this._layers[id] as T;\n    }\n\n    /**\n     * Checks if a specific layer is present within the style.\n     *\n     * @param {string} id ID of the desired layer.\n     * @returns {boolean} A boolean specifying if the given layer is present.\n     */\n    hasLayer(id: string): boolean {\n        return id in this._mergedLayers;\n    }\n\n    /**\n     * Checks if a specific layer type is present within the style.\n     *\n     * @param {string} type Type of the desired layer.\n     * @returns {boolean} A boolean specifying if the given layer type is present.\n     */\n    hasLayerType(type: string): boolean {\n        for (const layerId in this._layers) {\n            const layer = this._layers[layerId];\n            if (layer.type === type) {\n                return true;\n            }\n        }\n        return false;\n    }\n\n    setLayerZoomRange(layerId: string, minzoom?: number | null, maxzoom?: number | null) {\n        this._checkLoaded();\n\n        const layer = this._checkLayer(layerId);\n        if (!layer) return;\n\n        if (layer.minzoom === minzoom && layer.maxzoom === maxzoom) return;\n\n        if (minzoom != null) {\n            layer.minzoom = minzoom;\n        }\n        if (maxzoom != null) {\n            layer.maxzoom = maxzoom;\n        }\n        this._updateLayer(layer);\n    }\n\n    getSlots(): string[] {\n        this._checkLoaded();\n        return this._mergedSlots;\n    }\n\n    setSlot(layerId: string, slot?: string | null) {\n        this._checkLoaded();\n\n        const layer = this._checkLayer(layerId);\n        if (!layer) return;\n\n        if (layer.slot === slot) {\n            return;\n        }\n\n        layer.slot = slot;\n        this._updateLayer(layer);\n    }\n\n    setFilter(layerId: string, filter?: FilterSpecification | null,  options: StyleSetterOptions = {}) {\n        this._checkLoaded();\n\n        const layer = this._checkLayer(layerId);\n        if (!layer) return;\n\n        if (deepEqual(layer.filter, filter)) {\n            return;\n        }\n\n        if (filter === null || filter === undefined) {\n            layer.filter = undefined;\n            this._updateLayer(layer);\n            return;\n        }\n\n        if (this._validate(validateFilter, `layers.${layer.id}.filter`, filter, {layerType: layer.type}, options)) {\n            return;\n        }\n\n        layer.filter = clone(filter);\n        this._updateLayer(layer);\n    }\n\n    /**\n     * Get a layer's filter object.\n     * @param {string} layerId The layer to inspect.\n     * @returns {*} The layer's filter, if any.\n     */\n    getFilter(layerId: string): FilterSpecification | null | undefined {\n        const layer = this._checkLayer(layerId);\n        if (!layer) return;\n        return clone(layer.filter);\n    }\n\n    setLayoutProperty(layerId: string, name: string, value: any, options: StyleSetterOptions = {}) {\n        this._checkLoaded();\n\n        const layer = this._checkLayer(layerId);\n        if (!layer) return;\n\n        if (deepEqual(layer.getLayoutProperty(name), value)) return;\n\n        if (value !== null && value !== undefined && !(options && options.validate === false)) {\n            const key = `layers.${layerId}.layout.${name}`;\n            const errors = emitValidationErrors(layer, validateLayoutProperty.call(validateStyle, {\n                key,\n                layerType: layer.type,\n                objectKey: name,\n                value,\n                styleSpec,\n                // Workaround for https://github.com/mapbox/mapbox-gl-js/issues/2407\n                style: {glyphs: true, sprite: true}\n            }));\n            if (errors) {\n                return;\n            }\n        }\n\n        layer.setLayoutProperty(name, value);\n        if (layer.configDependencies.size !== 0) this._configDependentLayers.add(layer.fqid);\n        this._updateLayer(layer);\n    }\n\n    /**\n     * Get a layout property's value from a given layer.\n     * @param {string} layerId The layer to inspect.\n     * @param {string} name The name of the layout property.\n     * @returns {*} The property value.\n     */\n    getLayoutProperty(layerId: string, name: string): PropertyValueSpecification<unknown> | null | undefined {\n        const layer = this._checkLayer(layerId);\n        if (!layer) return;\n        return layer.getLayoutProperty(name);\n    }\n\n    setPaintProperty(layerId: string, name: string, value: any, options: StyleSetterOptions = {}) {\n        this._checkLoaded();\n\n        const layer = this._checkLayer(layerId);\n        if (!layer) return;\n\n        if (deepEqual(layer.getPaintProperty(name), value)) return;\n\n        if (value !== null && value !== undefined && !(options && options.validate === false)) {\n            const key = `layers.${layerId}.paint.${name}`;\n            const errors = emitValidationErrors(layer, validatePaintProperty.call(validateStyle, {\n                key,\n                layerType: layer.type,\n                objectKey: name,\n                value,\n                styleSpec\n            }));\n            if (errors) {\n                return;\n            }\n        }\n\n        const requiresRelayout = layer.setPaintProperty(name, value);\n        if (layer.configDependencies.size !== 0) this._configDependentLayers.add(layer.fqid);\n        if (requiresRelayout) {\n            this._updateLayer(layer);\n        }\n\n        this._changes.updatePaintProperties(layer);\n    }\n\n    getPaintProperty(layerId: string, name: string): void | TransitionSpecification | PropertyValueSpecification<unknown> {\n        const layer = this._checkLayer(layerId);\n        if (!layer) return;\n        return layer.getPaintProperty(name);\n    }\n\n    setFeatureState(target: FeatureSelector | GeoJSONFeature, state: FeatureState) {\n        this._checkLoaded();\n        const sourceId = target.source;\n        const sourceLayer = target.sourceLayer;\n\n        const source = this._checkSource(sourceId);\n        if (!source) return;\n\n        const sourceType = source.type;\n        if (sourceType === 'geojson' && sourceLayer) {\n            this.fire(new ErrorEvent(new Error(`GeoJSON sources cannot have a sourceLayer parameter.`)));\n            return;\n        }\n        if (sourceType === 'vector' && !sourceLayer) {\n            this.fire(new ErrorEvent(new Error(`The sourceLayer parameter must be provided for vector source types.`)));\n            return;\n        }\n        if (target.id === undefined) {\n            this.fire(new ErrorEvent(new Error(`The feature id parameter must be provided.`)));\n        }\n\n        const sourceCaches = this.getOwnSourceCaches(sourceId);\n        for (const sourceCache of sourceCaches) {\n            sourceCache.setFeatureState(sourceLayer, target.id, state);\n        }\n    }\n\n    removeFeatureState(target: Omit<FeatureSelector, 'id'> & {id?: FeatureSelector['id']} | GeoJSONFeature, key?: string) {\n        this._checkLoaded();\n        const sourceId = target.source;\n\n        const source = this._checkSource(sourceId);\n        if (!source) return;\n\n        const sourceType = source.type;\n        const sourceLayer = sourceType === 'vector' ? target.sourceLayer : undefined;\n\n        if (sourceType === 'vector' && !sourceLayer) {\n            this.fire(new ErrorEvent(new Error(`The sourceLayer parameter must be provided for vector source types.`)));\n            return;\n        }\n\n        if (key && (typeof target.id !== 'string' && typeof target.id !== 'number')) {\n            this.fire(new ErrorEvent(new Error(`A feature id is required to remove its specific state property.`)));\n            return;\n        }\n\n        const sourceCaches = this.getOwnSourceCaches(sourceId);\n        for (const sourceCache of sourceCaches) {\n            sourceCache.removeFeatureState(sourceLayer, target.id, key);\n        }\n    }\n\n    getFeatureState(target: FeatureSelector | GeoJSONFeature): FeatureState | null | undefined {\n        this._checkLoaded();\n        const sourceId = target.source;\n        const sourceLayer = target.sourceLayer;\n\n        const source = this._checkSource(sourceId);\n        if (!source) return;\n\n        const sourceType = source.type;\n        if (sourceType === 'vector' && !sourceLayer) {\n            this.fire(new ErrorEvent(new Error(`The sourceLayer parameter must be provided for vector source types.`)));\n            return;\n        }\n        if (target.id === undefined) {\n            this.fire(new ErrorEvent(new Error(`The feature id parameter must be provided.`)));\n        }\n\n        const sourceCaches = this.getOwnSourceCaches(sourceId);\n        return sourceCaches[0].getFeatureState(sourceLayer, target.id);\n    }\n\n    setTransition(transition?: TransitionSpecification | null): Style {\n        this.stylesheet.transition = extend({}, this.stylesheet.transition, transition);\n        this.transition = this.stylesheet.transition;\n        return this;\n    }\n\n    getTransition(): TransitionSpecification {\n        return extend({}, this.stylesheet.transition);\n    }\n\n    serialize(): StyleSpecification {\n        this._checkLoaded();\n\n        const terrain = this.getTerrain();\n        const scopedTerrain = terrain && this.terrain && this.terrain.scope === this.scope ?\n            terrain :\n            this.stylesheet.terrain;\n\n        return filterObject({\n            version: this.stylesheet.version,\n            name: this.stylesheet.name,\n            metadata: this.stylesheet.metadata,\n            fragment: this.stylesheet.fragment,\n            imports: this._serializeImports(),\n            schema: this.stylesheet.schema,\n            camera: this.stylesheet.camera,\n            light: this.stylesheet.light,\n            lights: this.stylesheet.lights,\n            terrain: scopedTerrain,\n            fog: this.stylesheet.fog,\n            center: this.stylesheet.center,\n            \"color-theme\": this.stylesheet[\"color-theme\"],\n            zoom: this.stylesheet.zoom,\n            bearing: this.stylesheet.bearing,\n            pitch: this.stylesheet.pitch,\n            sprite: this.stylesheet.sprite,\n            glyphs: this.stylesheet.glyphs,\n            transition: this.stylesheet.transition,\n            projection: this.stylesheet.projection,\n            sources: this._serializeSources(),\n            layers: this._serializeLayers(this._order)\n        }, (value) => { return value !== undefined; });\n    }\n\n    _updateLayer(layer: StyleLayer) {\n        this._changes.updateLayer(layer);\n        const sourceCache = this.getLayerSourceCache(layer);\n        const fqid = makeFQID(layer.source, layer.scope);\n        const sourceCacheUpdates = this._changes.getUpdatedSourceCaches();\n        if (layer.source && !sourceCacheUpdates[fqid] &&\n            // Skip for raster layers (https://github.com/mapbox/mapbox-gl-js/issues/7865)\n            sourceCache && sourceCache.getSource().type !== 'raster') {\n            this._changes.updateSourceCache(fqid, 'reload');\n            sourceCache.pause();\n        }\n        layer.invalidateCompiledFilter();\n    }\n\n    _flattenAndSortRenderedFeatures(sourceResults: Array<QueryResult>): Array<GeoJSONFeature> {\n        // Feature order is complicated.\n        // The order between features in two 2D layers is determined by layer order (subject to draped rendering modification).\n        //  - if terrain/globe enabled layers are reordered in a drape-first, immediate-second manner\n        //  - if terrain/globe disabled layers are not reordered\n        // The order between features in two 3D layers is always determined by depth.\n        // The order between a feature in a 2D layer and a 3D layer is tricky:\n        //      Most often layer order determines the feature order in this case. If\n        //      a line layer is above a extrusion layer the line feature will be rendered\n        //      above the extrusion. If the line layer is below the extrusion layer,\n        //      it will be rendered below it.\n        //\n        //      There is a weird case though.\n        //      You have layers in this order: extrusion_layer_a, line_layer, extrusion_layer_b\n        //      Each layer has a feature that overlaps the other features.\n        //      The feature in extrusion_layer_a is closer than the feature in extrusion_layer_b so it is rendered above.\n        //      The feature in line_layer is rendered above extrusion_layer_a.\n        //      This means that that the line_layer feature is above the extrusion_layer_b feature despite\n        //      it being in an earlier layer.\n\n        const isLayer3D = (layerId: string) => this._mergedLayers[layerId].type === 'fill-extrusion' ||  this._mergedLayers[layerId].type === 'model';\n\n        const order = this.order;\n\n        const layerIndex: Record<string, any> = {};\n        const features3D = [];\n        for (let l = order.length - 1; l >= 0; l--) {\n            const layerId = order[l];\n            if (isLayer3D(layerId)) {\n                layerIndex[layerId] = l;\n                for (const sourceResult of sourceResults) {\n                    const layerFeatures = sourceResult[layerId];\n                    if (layerFeatures) {\n                        for (const featureWrapper of layerFeatures) {\n                            features3D.push(featureWrapper);\n                        }\n                    }\n                }\n            }\n        }\n\n        features3D.sort((a, b) => {\n            return b.intersectionZ - a.intersectionZ;\n        });\n\n        const features = [];\n        for (let l = order.length - 1; l >= 0; l--) {\n            const layerId = order[l];\n\n            if (isLayer3D(layerId)) {\n                // add all 3D features that are in or above the current layer\n                for (let i = features3D.length - 1; i >= 0; i--) {\n                    const topmost3D = features3D[i].feature;\n                    if (topmost3D.layer && layerIndex[topmost3D.layer.id] < l) break;\n                    features.push(topmost3D);\n                    features3D.pop();\n                }\n            } else {\n                for (const sourceResult of sourceResults) {\n                    const layerFeatures = sourceResult[layerId];\n                    if (layerFeatures) {\n                        for (const featureWrapper of layerFeatures) {\n                            features.push(featureWrapper.feature);\n                        }\n                    }\n                }\n            }\n        }\n\n        return features;\n    }\n\n    queryRenderedFeatures(\n        queryGeometry: PointLike | [PointLike, PointLike],\n        params: QueryRenderedFeaturesParams,\n        transform: Transform,\n    ): Array<GeoJSONFeature> {\n        if (params && params.filter) {\n            this._validate(validateFilter, 'queryRenderedFeatures.filter', params.filter, null, params);\n        }\n\n        params.scope = this.scope;\n        params.availableImages = this._availableImages;\n        params.serializedLayers = this._serializedLayers;\n\n        const includedSources: Record<string, any> = {};\n        if (params && params.layers) {\n            if (!Array.isArray(params.layers)) {\n                this.fire(new ErrorEvent(new Error('parameters.layers must be an Array.')));\n                return [];\n            }\n            for (const layerId of params.layers) {\n                const layer = this._mergedLayers[layerId];\n                if (!layer) {\n                    // this layer is not in the style.layers array\n                    this.fire(new ErrorEvent(new Error(`The layer '${layerId}' does not exist in the map's style and cannot be queried for features.`)));\n                    return [];\n                }\n                includedSources[layer.source] = true;\n            }\n        }\n\n        const sourceResults: Array<QueryResult> = [];\n        const serializedLayers = params.serializedLayers || {};\n\n        const has3DLayer = (params && params.layers) ?\n            params.layers.some((layerId) => {\n                const layer = this.getLayer(layerId);\n                return layer && layer.is3D();\n            }) : this.has3DLayers();\n\n        const queryGeometryStruct = QueryGeometry.createFromScreenPoints(queryGeometry, transform);\n\n        for (const id in this._mergedSourceCaches) {\n            const source = this._mergedSourceCaches[id].getSource();\n            if (!source || source.scope !== params.scope) continue;\n\n            const sourceId = this._mergedSourceCaches[id].getSource().id;\n            if (params.layers && !includedSources[sourceId]) continue;\n            const showQueryGeometry = !!this.map._showQueryGeometry;\n            sourceResults.push(\n                queryRenderedFeatures(\n                    this._mergedSourceCaches[id],\n                    this._mergedLayers,\n                    serializedLayers,\n                    queryGeometryStruct,\n                    (params as any),\n                    transform,\n                    has3DLayer,\n                    showQueryGeometry)\n            );\n        }\n\n        if (this.placement) {\n            // If a placement has run, query against its CollisionIndex\n            // for symbol results, and treat it as an extra source to merge\n            sourceResults.push(\n                queryRenderedSymbols(\n                    this._mergedLayers,\n                    serializedLayers,\n                    this.getLayerSourceCache.bind(this),\n                    queryGeometryStruct.screenGeometry,\n                    (params as any),\n                    this.placement.collisionIndex,\n                    this.placement.retainedQueryData)\n            );\n        }\n\n        return this._flattenAndSortRenderedFeatures(sourceResults);\n    }\n\n    querySourceFeatures(\n        sourceID: string,\n        params?: {\n            sourceLayer?: string;\n            filter?: FilterSpecification;\n            validate?: boolean;\n        },\n    ): Array<GeoJSONFeature> {\n        if (params && params.filter) {\n            this._validate(validateFilter, 'querySourceFeatures.filter', params.filter, null, params);\n        }\n        const sourceCaches = this.getOwnSourceCaches(sourceID);\n        let results = [];\n        for (const sourceCache of sourceCaches) {\n            results = results.concat(querySourceFeatures(sourceCache, params));\n        }\n        return results;\n    }\n\n    addSourceType(name: string, SourceType: SourceClass, callback: Callback<undefined>): void {\n        if (Style.getSourceType(name)) {\n            return callback(new Error(`A source type called \"${name}\" already exists.`));\n        }\n\n        Style.setSourceType(name, SourceType);\n\n        if (!SourceType.workerSourceURL) {\n            return callback(null, null);\n        }\n\n        this.dispatcher.broadcast('loadWorkerSource', {\n            name,\n            url: SourceType.workerSourceURL\n        }, callback);\n    }\n\n    getFlatLight(): LightSpecification {\n        return this.light.getLight();\n    }\n\n    setFlatLight(lightOptions: LightSpecification, id: string, options: StyleSetterOptions = {}) {\n        this._checkLoaded();\n\n        const light = this.light.getLight();\n        let _update = false;\n        for (const key in lightOptions) {\n            if (!deepEqual(lightOptions[key], light[key])) {\n                _update = true;\n                break;\n            }\n        }\n        if (!_update) return;\n\n        const parameters = this._getTransitionParameters();\n\n        this.light.setLight(lightOptions, id, options);\n        this.light.updateTransitions(parameters);\n    }\n\n    getTerrain(): TerrainSpecification | null | undefined {\n        return this.terrain && this.terrain.drapeRenderMode === DrapeRenderMode.elevated ? this.terrain.get() : null;\n    }\n\n    setTerrainForDraping() {\n        const mockTerrainOptions = {source: '', exaggeration: 0};\n        this.setTerrain(mockTerrainOptions, DrapeRenderMode.deferred);\n    }\n\n    checkCanvasFingerprintNoise() {\n        // This workaround disables terrain and hillshade\n        // if there is noise in the Canvas2D operations used for image decoding.\n        if (this.disableElevatedTerrain === undefined) {\n            this.disableElevatedTerrain = browser.hasCanvasFingerprintNoise();\n            if (this.disableElevatedTerrain) warnOnce('Terrain and hillshade are disabled because of Canvas2D limitations when fingerprinting protection is enabled (e.g. in private browsing mode).');\n        }\n    }\n\n    // eslint-disable-next-line no-warning-comments\n    // TODO: generic approach for root level property: light, terrain, skybox.\n    // It is not done here to prevent rebasing issues.\n    setTerrain(terrainOptions?: TerrainSpecification | null, drapeRenderMode: number = DrapeRenderMode.elevated) {\n        this._checkLoaded();\n\n        // Disabling\n        if (!terrainOptions) {\n            // This check prevents removing draping terrain not from #applyProjectionUpdate\n            if (!this.terrainSetForDrapingOnly()) {\n                delete this.terrain;\n\n                if (this.map.transform.projection.requiresDraping) {\n                    this.setTerrainForDraping();\n                }\n            }\n\n            if (drapeRenderMode === DrapeRenderMode.deferred) {\n                delete this.terrain;\n            }\n\n            if (terrainOptions === null) {\n                this.stylesheet.terrain = null;\n            } else {\n                delete this.stylesheet.terrain;\n            }\n\n            this._force3DLayerUpdate();\n            this._markersNeedUpdate = true;\n            return;\n        }\n\n        this.checkCanvasFingerprintNoise();\n\n        let options: TerrainSpecification = terrainOptions;\n        const isUpdating = terrainOptions.source == null;\n        if (drapeRenderMode === DrapeRenderMode.elevated) {\n            if (this.disableElevatedTerrain) return;\n\n            // Input validation and source object unrolling\n            if (typeof options.source === 'object') {\n                const id = 'terrain-dem-src';\n                this.addSource(id, options.source);\n                options = clone(options);\n                options = extend(options, {source: id});\n            }\n\n            const validationOptions = extend({}, options);\n            const validationProps: Record<string, any> = {};\n\n            if (this.terrain && isUpdating) {\n                validationOptions.source = this.terrain.get().source;\n\n                const fragmentStyle = this.terrain ? this.getFragmentStyle(this.terrain.scope) : null;\n                if (fragmentStyle) {\n                    validationProps.style = fragmentStyle.serialize();\n                }\n            }\n\n            if (this._validate(validateTerrain, 'terrain', validationOptions, validationProps)) {\n                return;\n            }\n        }\n\n        // Enabling\n        if (!this.terrain || (this.terrain.scope !== this.scope && !isUpdating) || (this.terrain && drapeRenderMode !== this.terrain.drapeRenderMode)) {\n            if (!options) return;\n            this._createTerrain(options, drapeRenderMode);\n            this.fire(new Event('data', {dataType: 'style'}));\n        } else { // Updating\n            const terrain = this.terrain;\n            const currSpec = terrain.get();\n\n            for (const name of Object.keys(styleSpec.terrain)) {\n                // Fallback to use default style specification when the properties wasn't set\n                if (!options.hasOwnProperty(name) && !!styleSpec.terrain[name].default) {\n                    options[name] = styleSpec.terrain[name].default;\n                }\n            }\n            for (const key in terrainOptions) {\n                if (!deepEqual(terrainOptions[key], currSpec[key])) {\n                    terrain.set(terrainOptions, this.options);\n                    this.stylesheet.terrain = terrainOptions;\n                    const parameters = this._getTransitionParameters({duration: 0});\n                    terrain.updateTransitions(parameters);\n                    this.fire(new Event('data', {dataType: 'style'}));\n                    break;\n                }\n            }\n        }\n\n        this.mergeTerrain();\n        this.updateDrapeFirstLayers();\n        this._markersNeedUpdate = true;\n    }\n\n    _createFog(fogOptions: FogSpecification) {\n        const fog = this.fog = new Fog(fogOptions, this.map.transform, this.scope, this.options);\n        this.stylesheet.fog = fog.get();\n        const parameters = this._getTransitionParameters({duration: 0});\n        fog.updateTransitions(parameters);\n    }\n\n    _updateMarkersOpacity() {\n        if (this.map._markers.length === 0) {\n            return;\n        }\n        this.map._requestDomTask(() => {\n            for (const marker of this.map._markers) {\n                marker._evaluateOpacity();\n            }\n        });\n    }\n\n    getFog(): FogSpecification | null | undefined {\n        return this.fog ? this.fog.get() : null;\n    }\n\n    setFog(fogOptions?: FogSpecification) {\n        this._checkLoaded();\n\n        if (!fogOptions) {\n            // Remove fog\n            delete this.fog;\n            delete this.stylesheet.fog;\n            this._markersNeedUpdate = true;\n            return;\n        }\n\n        if (!this.fog) {\n            // Initialize Fog\n            this._createFog(fogOptions);\n        } else {\n            // Updating fog\n            const fog = this.fog;\n            if (!deepEqual(fog.get(), fogOptions)) {\n                fog.set(fogOptions, this.options);\n                this.stylesheet.fog = fog.get();\n                const parameters = this._getTransitionParameters({duration: 0});\n                fog.updateTransitions(parameters);\n            }\n        }\n\n        this._markersNeedUpdate = true;\n    }\n\n    setColorTheme(colorTheme?: ColorThemeSpecification) {\n        this._checkLoaded();\n\n        const updateStyle = () => {\n            for (const layerId in this._layers) {\n                const layer = this._layers[layerId];\n                layer.lut = this._styleColorTheme.lut;\n            }\n            for (const id in this._sourceCaches) {\n                this._sourceCaches[id].clearTiles();\n            }\n        };\n\n        this._styleColorTheme.colorTheme = colorTheme;\n        if (!colorTheme) {\n            this._styleColorTheme.lut = null;\n            updateStyle();\n            return;\n        }\n\n        const data = this._evaluateColorThemeData(colorTheme);\n        this._loadColorTheme(data).then(() => {\n            this.fire(new Event('colorthemeset'));\n            updateStyle();\n        }).catch((e) => {\n            warnOnce(`Couldn\\'t set color theme: ${e}`);\n        });\n    }\n\n    _getTransitionParameters(transition?: TransitionSpecification | null): TransitionParameters {\n        return {\n            now: browser.now(),\n            transition: extend(this.transition, transition)\n        };\n    }\n\n    updateDrapeFirstLayers() {\n        if (!this.terrain) {\n            return;\n        }\n\n        const draped = [];\n        const nonDraped = [];\n        for (const layerId of this._mergedOrder) {\n            const layer = this._mergedLayers[layerId];\n            if (this.isLayerDraped(layer)) {\n                draped.push(layerId);\n            } else {\n                nonDraped.push(layerId);\n            }\n        }\n\n        this._drapedFirstOrder = [];\n        this._drapedFirstOrder.push(...draped);\n        this._drapedFirstOrder.push(...nonDraped);\n    }\n\n    _createTerrain(terrainOptions: TerrainSpecification, drapeRenderMode: number) {\n        const terrain = this.terrain = new Terrain(terrainOptions, drapeRenderMode, this.scope, this.options);\n\n        // We need to update the stylesheet only for the elevated mode,\n        // i.e., mock terrain shouldn't be propagated to the stylesheet\n        if (drapeRenderMode === DrapeRenderMode.elevated) {\n            this.stylesheet.terrain = terrainOptions;\n        }\n\n        this.mergeTerrain();\n        this.updateDrapeFirstLayers();\n        this._force3DLayerUpdate();\n        const parameters = this._getTransitionParameters({duration: 0});\n        terrain.updateTransitions(parameters);\n    }\n\n    _force3DLayerUpdate() {\n        for (const layerId in this._layers) {\n            const layer = this._layers[layerId];\n            if (layer.type === 'fill-extrusion') {\n                this._updateLayer(layer);\n            }\n        }\n    }\n\n    _forceSymbolLayerUpdate() {\n        for (const layerId in this._layers) {\n            const layer = this._layers[layerId];\n            if (layer.type === 'symbol') {\n                this._updateLayer(layer);\n            }\n        }\n    }\n\n    _validate(\n        validate: Validator,\n        key: string,\n        value: any,\n        props: any,\n        options: {\n            validate?: boolean;\n        } = {},\n    ): boolean {\n        if (options && options.validate === false) {\n            return false;\n        }\n\n        // Fallback to the default glyphs URL if none is specified\n        const style = extend({}, this.serialize());\n        return emitValidationErrors(this, validate.call(validateStyle, extend({\n            key,\n            style,\n            value,\n            styleSpec\n        }, props)));\n    }\n\n    _remove() {\n        if (this._request) {\n            this._request.cancel();\n            this._request = null;\n        }\n        if (this._spriteRequest) {\n            this._spriteRequest.cancel();\n            this._spriteRequest = null;\n        }\n\n        rtlTextPluginEvented.off('pluginStateChange', this._rtlTextPluginCallback);\n\n        for (const layerId in this._mergedLayers) {\n            const layer = this._mergedLayers[layerId];\n            layer.setEventedParent(null);\n        }\n\n        for (const id in this._mergedSourceCaches) {\n            this._mergedSourceCaches[id].clearTiles();\n            this._mergedSourceCaches[id].setEventedParent(null);\n        }\n\n        this.setEventedParent(null);\n\n        delete this.fog;\n        delete this.terrain;\n        delete this.ambientLight;\n        delete this.directionalLight;\n\n        // Shared managers should be removed only on removing the root style\n        if (this.isRootStyle()) {\n            this.imageManager.setEventedParent(null);\n            this.modelManager.setEventedParent(null);\n            this.dispatcher.remove();\n        }\n    }\n\n    clearSource(id: string) {\n        const sourceCaches = this.getSourceCaches(id);\n        for (const sourceCache of sourceCaches) {\n            sourceCache.clearTiles();\n        }\n    }\n\n    clearSources() {\n        for (const id in this._mergedSourceCaches) {\n            this._mergedSourceCaches[id].clearTiles();\n        }\n    }\n\n    reloadSource(id: string) {\n        const sourceCaches = this.getSourceCaches(id);\n        for (const sourceCache of sourceCaches) {\n            sourceCache.resume();\n            sourceCache.reload();\n        }\n    }\n\n    reloadSources() {\n        for (const source of this.getSources()) {\n            if (source.reload)\n                source.reload();\n        }\n    }\n\n    updateSources(transform: Transform) {\n        let lightDirection: vec3 | null | undefined;\n        if (this.directionalLight) {\n            lightDirection = shadowDirectionFromProperties(this.directionalLight);\n        }\n        for (const id in this._mergedSourceCaches) {\n            this._mergedSourceCaches[id].update(transform, undefined, undefined, lightDirection);\n        }\n    }\n\n    _generateCollisionBoxes() {\n        for (const id in this._sourceCaches) {\n            const sourceCache = this._sourceCaches[id];\n            sourceCache.resume();\n            sourceCache.reload();\n        }\n    }\n\n    _updatePlacement(\n        painter: Painter,\n        transform: Transform,\n        showCollisionBoxes: boolean,\n        fadeDuration: number,\n        crossSourceCollisions: boolean,\n        replacementSource: ReplacementSource,\n        forceFullPlacement: boolean = false,\n    ): {\n        needsRerender: boolean;\n    } {\n        let symbolBucketsChanged = false;\n        let placementCommitted = false;\n\n        const layerTiles: Record<string, any> = {};\n        const layerTilesInYOrder: Record<string, any> = {};\n\n        for (const layerId of this._mergedOrder) {\n            const styleLayer = this._mergedLayers[layerId];\n            if (styleLayer.type !== 'symbol') continue;\n\n            const sourceId = makeFQID(styleLayer.source, styleLayer.scope);\n\n            let sourceTiles = layerTiles[sourceId];\n\n            if (!sourceTiles) {\n                const sourceCache = this.getLayerSourceCache(styleLayer);\n                if (!sourceCache) continue;\n                const tiles = sourceCache.getRenderableIds(true).map((id) => sourceCache.getTileByID(id));\n                layerTilesInYOrder[sourceId] = tiles.slice();\n                sourceTiles = layerTiles[sourceId] =\n                    tiles.sort((a, b) => (b.tileID.overscaledZ - a.tileID.overscaledZ) || (a.tileID.isLessThan(b.tileID) ? -1 : 1));\n            }\n\n            const layerBucketsChanged = this.crossTileSymbolIndex.addLayer(styleLayer, sourceTiles, transform.center.lng, transform.projection);\n            symbolBucketsChanged = symbolBucketsChanged || layerBucketsChanged;\n        }\n        this.crossTileSymbolIndex.pruneUnusedLayers(this._mergedOrder);\n\n        // Anything that changes our \"in progress\" layer and tile indices requires us\n        // to start over. When we start over, we do a full placement instead of incremental\n        // to prevent starvation.\n        // We need to restart placement to keep layer indices in sync.\n        // Also force full placement when fadeDuration === 0 to ensure that newly loaded\n        // tiles will fully display symbols in their first frame\n        forceFullPlacement = forceFullPlacement || this._layerOrderChanged || fadeDuration === 0;\n\n        if (this._layerOrderChanged) {\n            this.fire(new Event('neworder'));\n        }\n\n        if (forceFullPlacement || !this.pauseablePlacement || (this.pauseablePlacement.isDone() && !this.placement.stillRecent(browser.now(), transform.zoom))) {\n            const fogState = this.fog && transform.projection.supportsFog ? this.fog.state : null;\n            this.pauseablePlacement = new PauseablePlacement(transform, this._mergedOrder, forceFullPlacement, showCollisionBoxes, fadeDuration, crossSourceCollisions, this.placement, fogState, this._buildingIndex);\n            this._layerOrderChanged = false;\n        }\n\n        if (this.pauseablePlacement.isDone()) {\n            // the last placement finished running, but the next one hasn’t\n            // started yet because of the `stillRecent` check immediately\n            // above, so mark it stale to ensure that we request another\n            // render frame\n            this.placement.setStale();\n        } else {\n            this.pauseablePlacement.continuePlacement(this._mergedOrder, this._mergedLayers, layerTiles, layerTilesInYOrder);\n\n            if (this.pauseablePlacement.isDone()) {\n                this.placement = this.pauseablePlacement.commit(browser.now());\n                placementCommitted = true;\n            }\n\n            if (symbolBucketsChanged) {\n                // since the placement gets split over multiple frames it is possible\n                // these buckets were processed before they were changed and so the\n                // placement is already stale while it is in progress\n                this.pauseablePlacement.placement.setStale();\n            }\n        }\n\n        if (placementCommitted || symbolBucketsChanged) {\n            this._buildingIndex.onNewFrame(transform.zoom);\n            for (let i = 0; i < this._mergedOrder.length; i++) {\n                const layerId = this._mergedOrder[i];\n                const styleLayer = this._mergedLayers[layerId];\n                if (styleLayer.type !== 'symbol') continue;\n                const checkAgainstClipLayer = this.isLayerClipped(styleLayer) && this._clipLayerIndices.some(c => i < c);\n                this.placement.updateLayerOpacities(styleLayer, layerTiles[makeFQID(styleLayer.source, styleLayer.scope)], i, checkAgainstClipLayer ? replacementSource : null);\n            }\n        }\n\n        // needsRender is false when we have just finished a placement that didn't change the visibility of any symbols\n        const needsRerender = !this.pauseablePlacement.isDone() || this.placement.hasTransitions(browser.now());\n        return {needsRerender};\n    }\n\n    _releaseSymbolFadeTiles() {\n        for (const id in this._sourceCaches) {\n            this._sourceCaches[id].releaseSymbolFadeTiles();\n        }\n    }\n\n    // Fragments and merging\n\n    addImport(importSpec: ImportSpecification, beforeId?: string | null): Promise<any> | void {\n        this._checkLoaded();\n\n        const imports = this.stylesheet.imports = this.stylesheet.imports || [];\n\n        const index = imports.findIndex(({id}) => id === importSpec.id);\n        if (index !== -1) {\n            this.fire(new ErrorEvent(new Error(`Import with id '${importSpec.id}' already exists in the map's style.`)));\n            return;\n        }\n\n        if (!beforeId) {\n            imports.push(importSpec);\n            return this._loadImports([importSpec], true);\n        }\n\n        const beforeIndex = imports.findIndex(({id}) => id === beforeId);\n\n        if (beforeIndex === -1) {\n            this.fire(new ErrorEvent(new Error(`Import with id \"${beforeId}\" does not exist on this map.`)));\n        }\n\n        this.stylesheet.imports = imports\n            .slice(0, beforeIndex)\n            .concat(importSpec)\n            .concat(imports.slice(beforeIndex));\n\n        return this._loadImports([importSpec], true, beforeId);\n    }\n\n    updateImport(importId: string, importSpecification: ImportSpecification | string): Style {\n        this._checkLoaded();\n\n        const imports = this.stylesheet.imports || [];\n        const index = this.getImportIndex(importId);\n        if (index === -1) return this;\n\n        if (typeof importSpecification === 'string') {\n            this.setImportUrl(importId, importSpecification);\n            return this;\n        }\n\n        if (importSpecification.url && importSpecification.url !== imports[index].url) {\n            this.setImportUrl(importId, importSpecification.url);\n        }\n\n        if (!deepEqual(importSpecification.config, imports[index].config)) {\n            this.setImportConfig(importId, importSpecification.config);\n        }\n\n        if (!deepEqual(importSpecification.data, imports[index].data)) {\n            this.setImportData(importId, importSpecification.data);\n        }\n\n        return this;\n    }\n\n    moveImport(importId: string, beforeId: string): Style {\n        this._checkLoaded();\n\n        let imports = this.stylesheet.imports || [];\n\n        const index = this.getImportIndex(importId);\n        if (index === -1) return this;\n\n        const beforeIndex = this.getImportIndex(beforeId);\n        if (beforeIndex === -1) return this;\n\n        const importSpec = imports[index];\n        const fragment = this.fragments[index];\n\n        imports = imports.filter(({id}) => id !== importId);\n\n        this.fragments = this.fragments.filter(({id}) => id !== importId);\n\n        this.stylesheet.imports = imports\n            .slice(0, beforeIndex)\n            .concat(importSpec)\n            .concat(imports.slice(beforeIndex));\n\n        this.fragments = this.fragments\n            .slice(0, beforeIndex)\n            .concat(fragment)\n            .concat(this.fragments.slice(beforeIndex));\n\n        this.mergeLayers();\n        return this;\n    }\n\n    setImportUrl(importId: string, url: string): Style {\n        this._checkLoaded();\n\n        const imports = this.stylesheet.imports || [];\n        const index = this.getImportIndex(importId);\n        if (index === -1) return this;\n\n        imports[index].url = url;\n\n        // Update related fragment\n        const fragment = this.fragments[index];\n        fragment.style = this._createFragmentStyle(imports[index]);\n\n        fragment.style.on('style.import.load', () => this.mergeAll());\n        fragment.style.loadURL(url);\n\n        return this;\n    }\n\n    setImportData(importId: string, stylesheet?: StyleSpecification | null): Style {\n        this._checkLoaded();\n\n        const index = this.getImportIndex(importId);\n        const imports = this.stylesheet.imports || [];\n        if (index === -1) return this;\n\n        // Reload import from the URL if import data is unset\n        if (!stylesheet) {\n            delete imports[index].data;\n            return this.setImportUrl(importId, imports[index].url);\n        }\n\n        // Update related fragment\n        const fragment = this.fragments[index];\n        fragment.style.setState(stylesheet);\n\n        this._reloadImports();\n        return this;\n    }\n\n    setImportConfig(importId: string, config?: ConfigSpecification | null): Style {\n        this._checkLoaded();\n\n        const index = this.getImportIndex(importId);\n        const imports = this.stylesheet.imports || [];\n        if (index === -1) return this;\n\n        if (config) {\n            imports[index].config = config;\n        } else {\n            delete imports[index].config;\n        }\n\n        // Update related fragment\n        const fragment = this.fragments[index];\n        const schema = fragment.style.stylesheet && fragment.style.stylesheet.schema;\n\n        fragment.config = config;\n        fragment.style.updateConfig(config, schema);\n\n        this.updateConfigDependencies();\n\n        return this;\n    }\n\n    removeImport(importId: string): void {\n        this._checkLoaded();\n\n        const imports = this.stylesheet.imports || [];\n        const index = this.getImportIndex(importId);\n        if (index === -1) return;\n\n        imports.splice(index, 1);\n\n        // Update related fragment\n        const fragment = this.fragments[index];\n        fragment.style._remove();\n        this.fragments.splice(index, 1);\n\n        this._reloadImports();\n    }\n\n    getImportIndex(importId: string): number {\n        const imports = this.stylesheet.imports || [];\n        const index = imports.findIndex((importSpec) => importSpec.id === importId);\n        if (index === -1) {\n            this.fire(new ErrorEvent(new Error(`Import '${importId}' does not exist in the map's style and cannot be updated.`)));\n        }\n        return index;\n    }\n\n    /**\n     * Return the style layer object with the given `id`.\n     *\n     * @param {string} id ID of the desired layer.\n     * @returns {?StyleLayer} A layer, if one with the given `id` exists.\n     */\n    getLayer(id: string): StyleLayer | null | undefined {\n        return this._mergedLayers[id];\n    }\n\n    getSources(): Source[] {\n        const sources = [];\n        for (const id in this._mergedOtherSourceCaches) {\n            const sourceCache = this._mergedOtherSourceCaches[id];\n            if (sourceCache) sources.push(sourceCache.getSource());\n        }\n\n        return sources;\n    }\n\n    /**\n     * Get a source by ID.\n     * @param {string} id ID of the desired source.\n     * @returns {?Source} The source object.\n     */\n    getSource(id: string, scope: string): Source | null | undefined {\n        const sourceCache = this.getSourceCache(id, scope);\n        return sourceCache && sourceCache.getSource();\n    }\n\n    getLayerSource(layer: StyleLayer): Source | null | undefined {\n        const sourceCache = this.getLayerSourceCache(layer);\n        return sourceCache && sourceCache.getSource();\n    }\n\n    getSourceCache(id: string, scope?: string | null): SourceCache | void {\n        const fqid = makeFQID(id, scope);\n        return this._mergedOtherSourceCaches[fqid];\n    }\n\n    getLayerSourceCache(layer: StyleLayer): SourceCache | void {\n        const fqid = makeFQID(layer.source, layer.scope);\n        return layer.type === 'symbol' ?\n            this._mergedSymbolSourceCaches[fqid] :\n            this._mergedOtherSourceCaches[fqid];\n    }\n\n    /**\n     * Returns all source caches for a given style FQID.\n     * If no FQID is provided, returns all source caches,\n     * including source caches in imported styles.\n     * @param {string} fqid Style FQID.\n     * @returns {Array<SourceCache>} List of source caches.\n     */\n    getSourceCaches(fqid?: string | null): Array<SourceCache> {\n        if (fqid == null)\n            return Object.values(this._mergedSourceCaches);\n\n        const sourceCaches = [];\n        if (this._mergedOtherSourceCaches[fqid]) {\n            sourceCaches.push(this._mergedOtherSourceCaches[fqid]);\n        }\n        if (this._mergedSymbolSourceCaches[fqid]) {\n            sourceCaches.push(this._mergedSymbolSourceCaches[fqid]);\n        }\n        return sourceCaches;\n    }\n\n    updateSourceCaches() {\n        const updatedSourceCaches = this._changes.getUpdatedSourceCaches();\n        for (const fqid in updatedSourceCaches) {\n            const action = updatedSourceCaches[fqid];\n            assert(action === 'reload' || action === 'clear');\n            if (action === 'reload') {\n                this.reloadSource(fqid);\n            } else if (action === 'clear') {\n                this.clearSource(fqid);\n            }\n        }\n    }\n\n    updateLayers(parameters: EvaluationParameters) {\n        const updatedPaintProps = this._changes.getUpdatedPaintProperties();\n        for (const id of updatedPaintProps) {\n            const layer = this.getLayer(id);\n            if (layer) layer.updateTransitions(parameters);\n        }\n    }\n\n    // Callbacks from web workers\n\n    getImages(mapId: string, params: {\n        icons: Array<string>;\n        source: string;\n        scope: string;\n        tileID: OverscaledTileID;\n        type: string;\n    }, callback: Callback<{\n        [_: string]: StyleImage;\n    }>) {\n        this.imageManager.getImages(params.icons, params.scope, callback);\n\n        // Apply queued image changes before setting the tile's dependencies so that the tile\n        // is not reloaded unecessarily. Without this forced update the reload could happen in cases\n        // like this one:\n        // - icons contains \"my-image\"\n        // - imageManager.getImages(...) triggers `onstyleimagemissing`\n        // - the user adds \"my-image\" within the callback\n        // - addImage adds \"my-image\" to this._changes.changedImages\n        // - the next frame triggers a reload of this tile even though it already has the latest version\n        this._updateTilesForChangedImages();\n\n        const setDependencies = (sourceCache: SourceCache) => {\n            if (sourceCache) {\n                sourceCache.setDependencies(params.tileID.key, params.type, params.icons);\n            }\n        };\n        setDependencies(this._otherSourceCaches[params.source]);\n        setDependencies(this._symbolSourceCaches[params.source]);\n    }\n\n    getGlyphs(mapId: string, params: {\n        stacks: {\n            [_: string]: Array<number>;\n        };\n        scope: string;\n    }, callback: Callback<{\n        [_: string]: {\n            glyphs: {\n                [_: number]: StyleGlyph | null | undefined;\n            };\n            ascender?: number;\n            descender?: number;\n        };\n    }>) {\n        this.glyphManager.getGlyphs(params.stacks, params.scope, callback);\n    }\n\n    getResource(mapId: string, params: RequestParameters, callback: ResponseCallback<any>): Cancelable {\n        return makeRequest(params, callback);\n    }\n\n    getOwnSourceCache(source: string): SourceCache | void {\n        return this._otherSourceCaches[source];\n    }\n\n    getOwnLayerSourceCache(layer: StyleLayer): SourceCache | void {\n        return layer.type === 'symbol' ?\n            this._symbolSourceCaches[layer.source] :\n            this._otherSourceCaches[layer.source];\n    }\n\n    getOwnSourceCaches(source: string): Array<SourceCache> {\n        const sourceCaches = [];\n        if (this._otherSourceCaches[source]) {\n            sourceCaches.push(this._otherSourceCaches[source]);\n        }\n        if (this._symbolSourceCaches[source]) {\n            sourceCaches.push(this._symbolSourceCaches[source]);\n        }\n        return sourceCaches;\n    }\n\n    _isSourceCacheLoaded(source: string): boolean {\n        const sourceCaches = this.getOwnSourceCaches(source);\n        if (sourceCaches.length === 0) {\n            this.fire(new ErrorEvent(new Error(`There is no source with ID '${source}'`)));\n            return false;\n        }\n        return sourceCaches.every(sc => sc.loaded());\n    }\n\n    has3DLayers(): boolean {\n        return this._has3DLayers;\n    }\n\n    hasSymbolLayers(): boolean {\n        return this._hasSymbolLayers;\n    }\n\n    hasCircleLayers(): boolean {\n        return this._hasCircleLayers;\n    }\n\n    isLayerClipped(layer: StyleLayer, source?: Source | null): boolean {\n        // fill-extrusions can be conflated by landmarks.\n        if (this._clipLayerIndices.length === 0 && layer.type !== 'fill-extrusion') return false;\n        const isFillExtrusion = layer.type === 'fill-extrusion' && layer.sourceLayer === 'building';\n\n        let layerMask = 0;\n        if (layer.is3D()) {\n            if (isFillExtrusion || (!!source && source.type === 'batched-model')) return true;\n            if (layer.type === 'model') {\n                layerMask = LayerTypeMask.Model;\n            }\n        } else {\n            if (layer.type === 'symbol') {\n                layerMask = LayerTypeMask.Symbol;\n            }\n        }\n\n        for (const i of this._clipLayerIndices) {\n            assert(i < this._mergedOrder.length);\n            const clipLayer: ClipStyleLayer = (this._mergedLayers[this._mergedOrder[i]] as any);\n            if (!clipLayer) continue;\n\n            const extraLayersToBeClipped = [];\n\n            for (const extra of clipLayer.layout.get('clip-layer-types'))\n                extraLayersToBeClipped.push(extra === 'model' ? LayerTypeMask.Model : (extra === 'symbol' ? LayerTypeMask.Symbol : LayerTypeMask.FillExtrusion));\n\n            for (const mask of extraLayersToBeClipped)\n                if (layerMask & mask)\n                    return true;\n        }\n\n        return false;\n    }\n\n    _clearWorkerCaches() {\n        // @ts-expect-error - TS2554 - Expected 2-3 arguments, but got 1.\n        this.dispatcher.broadcast('clearCaches');\n    }\n\n    destroy() {\n        this._clearWorkerCaches();\n        this.fragments.forEach(fragment => {\n            fragment.style._remove();\n        });\n        if (this.terrainSetForDrapingOnly()) {\n            delete this.terrain;\n            delete this.stylesheet.terrain;\n        }\n    }\n}\n\nStyle.getSourceType = getSourceType;\nStyle.setSourceType = setSourceType;\nStyle.registerForPluginStateChange = registerForPluginStateChange;\n\nexport default Style;\n","import type {StyleSpecification} from './types';\n\nexport default function emptyStyle(): StyleSpecification {\n    return {\n        version: 8,\n        layers: [],\n        sources: {}\n    };\n}\n","import {getJSON, getImage, ResourceType} from '../util/ajax';\n\nimport browser from '../util/browser';\nimport {RGBAImage} from '../util/image';\n\nimport type {StyleImage} from './style_image';\nimport type {RequestManager} from '../util/mapbox';\nimport type {Callback} from '../types/callback';\nimport type {Cancelable} from '../types/cancelable';\n\nexport default function(\n    baseURL: string,\n    requestManager: RequestManager,\n    callback: Callback<{\n        [_: string]: StyleImage;\n    }>,\n): Cancelable {\n    let json: any, image, error;\n    const format = browser.devicePixelRatio > 1 ? '@2x' : '';\n\n    // @ts-expect-error - TS2345 - Argument of type 'string' is not assignable to parameter of type '\"Unknown\" | \"Style\" | \"Source\" | \"Tile\" | \"Glyphs\" | \"SpriteImage\" | \"SpriteJSON\" | \"Image\" | \"Model\"'.\n    let jsonRequest: Cancelable | null | undefined = getJSON(requestManager.transformRequest(requestManager.normalizeSpriteURL(baseURL, format, '.json'), ResourceType.SpriteJSON), (err?: Error | null, data?: any | null) => {\n        jsonRequest = null;\n        if (!error) {\n            error = err;\n            json = data;\n            maybeComplete();\n        }\n    });\n\n    // @ts-expect-error - TS2345 - Argument of type 'string' is not assignable to parameter of type '\"Unknown\" | \"Style\" | \"Source\" | \"Tile\" | \"Glyphs\" | \"SpriteImage\" | \"SpriteJSON\" | \"Image\" | \"Model\"'.\n    let imageRequest: Cancelable | null | undefined = getImage(requestManager.transformRequest(requestManager.normalizeSpriteURL(baseURL, format, '.png'), ResourceType.SpriteImage), (err, img) => {\n        imageRequest = null;\n        if (!error) {\n            error = err;\n            image = img;\n            maybeComplete();\n        }\n    });\n\n    function maybeComplete() {\n        if (error) {\n            callback(error);\n        } else if (json && image) {\n            const imageData = browser.getImageData(image);\n            const result: Record<string, any> = {};\n\n            for (const id in json) {\n                const {width, height, x, y, sdf, pixelRatio, stretchX, stretchY, content} = json[id];\n                const data = new RGBAImage({width, height});\n                RGBAImage.copy(imageData, data, {x, y}, {x: 0, y: 0}, {width, height}, null);\n                result[id] = {data, pixelRatio, sdf, stretchX, stretchY, content};\n            }\n\n            callback(null, result);\n        }\n    }\n\n    return {\n        cancel() {\n            if (jsonRequest) {\n                jsonRequest.cancel();\n                jsonRequest = null;\n            }\n            if (imageRequest) {\n                imageRequest.cancel();\n                imageRequest = null;\n            }\n        }\n    };\n}\n","/**\n * Throttle the given function to run at most every `period` milliseconds.\n * @private\n */\nexport default function throttle(fn: () => void, time: number): () => number | null | undefined {\n    let pending = false;\n    let timerId: number | null | undefined = null;\n\n    const later = () => {\n        timerId = null;\n        if (pending) {\n            fn();\n            // @ts-expect-error - TS2322 - Type 'Timeout' is not assignable to type 'number'.\n            timerId = setTimeout(later, time);\n            pending = false;\n        }\n    };\n\n    return () => {\n        pending = true;\n        if (!timerId) {\n            later();\n        }\n        return timerId;\n    };\n}\n","import {bindAll} from '../util/util';\nimport throttle from '../util/throttle';\n\nimport type {Map} from './map';\n\n/*\n * Adds the map's position to its page's location hash.\n * Passed as an option to the map object.\n *\n * @returns {Hash} `this`\n */\nexport default class Hash {\n    _map: Map | null | undefined;\n    _updateHash: () => number | null | undefined;\n    _hashName: string | null | undefined;\n\n    constructor(hashName?: string | null) {\n        this._hashName = hashName && encodeURIComponent(hashName);\n        bindAll([\n            '_getCurrentHash',\n            '_onHashChange',\n            '_updateHash'\n        ], this);\n\n        // Mobile Safari doesn't allow updating the hash more than 100 times per 30 seconds.\n        this._updateHash = throttle(this._updateHashUnthrottled.bind(this), 30 * 1000 / 100);\n    }\n\n    /*\n     * Map element to listen for coordinate changes\n     *\n     * @param {Object} map\n     * @returns {Hash} `this`\n     */\n    addTo(map: Map): this {\n        this._map = map;\n        window.addEventListener('hashchange', this._onHashChange, false);\n        map.on('moveend', this._updateHash);\n        return this;\n    }\n\n    /*\n     * Removes hash\n     *\n     * @returns {Popup} `this`\n     */\n    remove(): this {\n        if (!this._map) return this;\n\n        this._map.off('moveend', this._updateHash);\n        window.removeEventListener('hashchange', this._onHashChange, false);\n        clearTimeout(this._updateHash());\n\n        this._map = undefined;\n        return this;\n    }\n\n    getHashString(): string {\n        const map = this._map;\n        if (!map) return '';\n\n        const hash = getHashString(map);\n\n        if (this._hashName) {\n            const hashName = this._hashName;\n            let found = false;\n            const parts = location.hash.slice(1).split('&').map(part => {\n                const key = part.split('=')[0];\n                if (key === hashName) {\n                    found = true;\n                    return `${key}=${hash}`;\n                }\n                return part;\n            }).filter(a => a);\n            if (!found) {\n                parts.push(`${hashName}=${hash}`);\n            }\n            return `#${parts.join('&')}`;\n        }\n\n        return `#${hash}`;\n    }\n\n    _getCurrentHash(): Array<string> {\n        // Get the current hash from location, stripped from its number sign\n        const hash = location.hash.replace('#', '');\n        if (this._hashName) {\n            // Split the parameter-styled hash into parts and find the value we need\n            let keyval;\n            hash.split('&').map(\n                part => part.split('=')\n            ).forEach(part => {\n                if (part[0] === this._hashName) {\n                    keyval = part;\n                }\n            });\n            return (keyval ? keyval[1] || '' : '').split('/');\n        }\n        return hash.split('/');\n    }\n\n    _onHashChange(): boolean {\n        const map = this._map;\n        if (!map) return false;\n        const loc = this._getCurrentHash();\n        // @ts-expect-error - TS2345 - Argument of type 'string' is not assignable to parameter of type 'number'.\n        if (loc.length >= 3 && !loc.some(v => isNaN(v))) {\n            const bearing = map.dragRotate.isEnabled() && map.touchZoomRotate.isEnabled() ? +(loc[3] || 0) : map.getBearing();\n            map.jumpTo({\n                center: [+loc[2], +loc[1]],\n                zoom: +loc[0],\n                bearing,\n                pitch: +(loc[4] || 0)\n            });\n            return true;\n        }\n        return false;\n    }\n\n    _updateHashUnthrottled() {\n        // Replace if already present, else append the updated hash string\n        history.replaceState(history.state, '', location.href.replace(/(#.+)?$/, this.getHashString()));\n    }\n}\n\nexport function getHashString(map: Map, mapFeedback?: boolean): string {\n    const center = map.getCenter(),\n        zoom = Math.round(map.getZoom() * 100) / 100,\n        // derived from equation: 512px * 2^z / 360 / 10^d < 0.5px\n        precision = Math.ceil((zoom * Math.LN2 + Math.log(512 / 360 / 0.5)) / Math.LN10),\n        m = Math.pow(10, precision),\n        lng = Math.round(center.lng * m) / m,\n        lat = Math.round(center.lat * m) / m,\n        bearing = map.getBearing(),\n        pitch = map.getPitch();\n\n    // new map feedback site has some constraints that don't allow\n    // us to use the same hash format as we do for the Map hash option.\n    let hash = mapFeedback ? `/${lng}/${lat}/${zoom}` : `${zoom}/${lat}/${lng}`;\n\n    if (bearing || pitch) hash += (`/${Math.round(bearing * 10) / 10}`);\n    if (pitch) hash += (`/${Math.round(pitch)}`);\n\n    return hash;\n}\n","import browser from '../util/browser';\nimport type {Map} from './map';\nimport {bezier, clamp, extend} from '../util/util';\nimport Point from '@mapbox/point-geometry';\n\nimport type {DragPanOptions} from './handler/shim/drag_pan';\nimport type {EasingOptions} from '../ui/camera';\n\nconst defaultInertiaOptions = {\n    linearity: 0.3,\n    easing: bezier(0, 0, 0.3, 1),\n};\n\nconst defaultPanInertiaOptions = extend({\n    deceleration: 2500,\n    maxSpeed: 1400\n}, defaultInertiaOptions);\n\nconst defaultZoomInertiaOptions = extend({\n    deceleration: 20,\n    maxSpeed: 1400\n}, defaultInertiaOptions);\n\nconst defaultBearingInertiaOptions = extend({\n    deceleration: 1000,\n    maxSpeed: 360\n}, defaultInertiaOptions);\n\nconst defaultPitchInertiaOptions = extend({\n    deceleration: 1000,\n    maxSpeed: 90\n}, defaultInertiaOptions);\n\nexport type InertiaOptions = {\n    linearity: number;\n    easing: (t: number) => number;\n    deceleration: number;\n    maxSpeed: number;\n};\n\nexport type InputEvent = MouseEvent | TouchEvent | KeyboardEvent | WheelEvent;\n\nexport default class HandlerInertia {\n    _map: Map;\n    _inertiaBuffer: Array<{\n        time: number;\n        settings: any;\n    }>;\n\n    constructor(map: Map) {\n        this._map = map;\n        this.clear();\n    }\n\n    clear() {\n        this._inertiaBuffer = [];\n    }\n\n    record(settings: any) {\n        this._drainInertiaBuffer();\n        this._inertiaBuffer.push({time: browser.now(), settings});\n    }\n\n    _drainInertiaBuffer() {\n        const inertia = this._inertiaBuffer,\n            now = browser.now(),\n            cutoff = 160;   //msec\n\n        while (inertia.length > 0 && now - inertia[0].time > cutoff)\n            inertia.shift();\n    }\n\n    _onMoveEnd(panInertiaOptions?: DragPanOptions): EasingOptions & {\n        easeId?: string;\n    } | null | undefined {\n        if (this._map._prefersReducedMotion()) {\n            return;\n        }\n\n        this._drainInertiaBuffer();\n        if (this._inertiaBuffer.length < 2) {\n            return;\n        }\n\n        const deltas = {\n            zoom: 0,\n            bearing: 0,\n            pitch: 0,\n            pan: new Point(0, 0),\n            pinchAround: undefined,\n            around: undefined\n        };\n\n        for (const {settings} of this._inertiaBuffer) {\n            deltas.zoom += settings.zoomDelta || 0;\n            deltas.bearing += settings.bearingDelta || 0;\n            deltas.pitch += settings.pitchDelta || 0;\n            if (settings.panDelta) deltas.pan._add(settings.panDelta);\n            if (settings.around) deltas.around = settings.around;\n            if (settings.pinchAround) deltas.pinchAround = settings.pinchAround;\n        }\n\n        const lastEntry = this._inertiaBuffer[this._inertiaBuffer.length - 1];\n        const duration = (lastEntry.time - this._inertiaBuffer[0].time);\n\n        const easeOptions: Record<string, any> = {};\n\n        if (deltas.pan.mag()) {\n            const result = calculateEasing(deltas.pan.mag(), duration, extend({}, defaultPanInertiaOptions, panInertiaOptions || {}));\n            easeOptions.offset = deltas.pan.mult(result.amount / deltas.pan.mag());\n            easeOptions.center = this._map.transform.center;\n            extendDuration(easeOptions, result);\n        }\n\n        if (deltas.zoom) {\n            const result = calculateEasing(deltas.zoom, duration, defaultZoomInertiaOptions);\n            easeOptions.zoom = this._map.transform.zoom + result.amount;\n            extendDuration(easeOptions, result);\n        }\n\n        if (deltas.bearing) {\n            const result = calculateEasing(deltas.bearing, duration, defaultBearingInertiaOptions);\n            easeOptions.bearing = this._map.transform.bearing + clamp(result.amount, -179, 179);\n            extendDuration(easeOptions, result);\n        }\n\n        if (deltas.pitch) {\n            const result = calculateEasing(deltas.pitch, duration, defaultPitchInertiaOptions);\n            easeOptions.pitch = this._map.transform.pitch + result.amount;\n            extendDuration(easeOptions, result);\n        }\n\n        if (easeOptions.zoom || easeOptions.bearing) {\n            const last = deltas.pinchAround === undefined ? deltas.around : deltas.pinchAround;\n            easeOptions.around = last ? this._map.unproject(last) : this._map.getCenter();\n        }\n\n        this.clear();\n        easeOptions.noMoveStart = true;\n        return easeOptions;\n    }\n}\n\n// Unfortunately zoom, bearing, etc can't have different durations and easings so\n// we need to choose one. We use the longest duration and it's corresponding easing.\nfunction extendDuration(easeOptions: EasingOptions, result: {\n    amount: number;\n    duration: number;\n    easing: (t: number) => number;\n}) {\n    if (!easeOptions.duration || easeOptions.duration < result.duration) {\n        easeOptions.duration = result.duration;\n        easeOptions.easing = result.easing;\n    }\n}\n\nfunction calculateEasing(amount: number, inertiaDuration: number, inertiaOptions: InertiaOptions) {\n    const {maxSpeed, linearity, deceleration} = inertiaOptions;\n    const speed = clamp(\n        amount * linearity / (inertiaDuration / 1000),\n        -maxSpeed,\n        maxSpeed);\n    const duration = Math.abs(speed) / (deceleration * linearity);\n    return {\n        easing: inertiaOptions.easing,\n        duration: duration * 1000,\n        amount: speed * (duration / 2)\n    };\n}\n","import {Event} from '../util/evented';\n\nimport * as DOM from '../util/dom';\nimport Point from '@mapbox/point-geometry';\nimport {extend} from '../util/util';\n\nimport type Tile from '../source/tile';\nimport type {Map} from './map';\nimport type LngLat from '../geo/lng_lat';\nimport type {GeoJSONFeature} from '../util/vectortile_to_geojson';\nimport type {EventData, EventOf} from '../util/evented';\nimport type {SourceSpecification} from '../style-spec/types';\n\ntype MapMouseEventType =\n    | 'mousedown'\n    | 'mouseup'\n    | 'preclick'\n    | 'click'\n    | 'dblclick'\n    | 'mousemove'\n    | 'mouseover'\n    | 'mouseenter'\n    | 'mouseleave'\n    | 'mouseout'\n    | 'contextmenu';\n\ntype MapTouchEventType =\n    | 'touchstart'\n    | 'touchend'\n    | 'touchcancel';\n\n/**\n * `MapMouseEvent` is a class used by other classes to generate\n * mouse events of specific types such as 'click' or 'hover'.\n * For a full list of available events, see [`Map` events](/mapbox-gl-js/api/map/#map-events).\n *\n * @extends {Object}\n * @example\n * // Example of a MapMouseEvent of type \"click\"\n * map.on('click', (e) => {\n *     console.log(e);\n *     // {\n *     //     lngLat: {\n *     //         lng: 40.203,\n *     //         lat: -74.451\n *     //     },\n *     //     originalEvent: {...},\n *     //     point: {\n *     //         x: 266,\n *     //         y: 464\n *     //     },\n *     //      target: {...},\n *     //      type: \"click\"\n *     // }\n * });\n * @see [Reference: `Map` events API documentation](https://docs.mapbox.com/mapbox-gl-js/api/map/#map-events)\n * @see [Example: Display popup on click](https://docs.mapbox.com/mapbox-gl-js/example/popup-on-click/)\n * @see [Example: Display popup on hover](https://www.mapbox.com/mapbox-gl-js/example/popup-on-hover/)\n */\nexport class MapMouseEvent extends Event<MapEvents, MapMouseEventType> {\n    /**\n     * The type of originating event. For a full list of available events, see [`Map` events](/mapbox-gl-js/api/map/#map-events).\n     */\n    type: MapMouseEventType;\n\n    /**\n     * The `Map` object that fired the event.\n     */\n    target: Map;\n\n    /**\n     * The DOM event which caused the map event.\n     */\n    originalEvent: MouseEvent;\n\n    /**\n     * The pixel coordinates of the mouse cursor, relative to the map and measured from the top left corner.\n     */\n    point: Point;\n\n    /**\n     * The geographic location on the map of the mouse cursor.\n     */\n    lngLat: LngLat;\n\n    /**\n     * If a single `layerId`(as a single string) or multiple `layerIds` (as an array of strings) were specified when adding the event listener with {@link Map#on},\n     * `features` will be an array of [GeoJSON](http://geojson.org/) [Feature objects](https://tools.ietf.org/html/rfc7946#section-3.2).\n     * The array will contain all features from that layer that are rendered at the event's point,\n     * in the order that they are rendered with the topmost feature being at the start of the array.\n     * The `features` are identical to those returned by {@link Map#queryRenderedFeatures}.\n     *\n     * If no `layerId` was specified when adding the event listener, `features` will be `undefined`.\n     * You can get the features at the point with `map.queryRenderedFeatures(e.point)`.\n     *\n     * @example\n     * // logging features for a specific layer (with `e.features`)\n     * map.on('click', 'myLayerId', (e) => {\n     *     console.log(`There are ${e.features.length} features at point ${e.point}`);\n     * });\n     *\n     * @example\n     * // logging features for two layers (with `e.features`)\n     * map.on('click', ['layer1', 'layer2'], (e) => {\n     *     console.log(`There are ${e.features.length} features at point ${e.point}`);\n     * });\n     *\n     * @example\n     * // logging all features for all layers (without `e.features`)\n     * map.on('click', (e) => {\n     *     const features = map.queryRenderedFeatures(e.point);\n     *     console.log(`There are ${features.length} features at point ${e.point}`);\n     * });\n     */\n    features?: Array<GeoJSONFeature>;\n\n    /**\n     * Prevents subsequent default processing of the event by the map.\n     *\n     * Calling this method will prevent the following default map behaviors:\n     *\n     *   * On `mousedown` events, the behavior of {@link DragPanHandler}.\n     *   * On `mousedown` events, the behavior of {@link DragRotateHandler}.\n     *   * On `mousedown` events, the behavior of {@link BoxZoomHandler}.\n     *   * On `dblclick` events, the behavior of {@link DoubleClickZoomHandler}.\n     *\n     * @example\n     * map.on('click', (e) => {\n     *     e.preventDefault();\n     * });\n     */\n    preventDefault() {\n        this._defaultPrevented = true;\n    }\n\n    /**\n     * `true` if `preventDefault` has been called.\n     * @private\n     */\n    get defaultPrevented(): boolean {\n        return this._defaultPrevented;\n    }\n\n    /**\n     * @private\n     */\n    _defaultPrevented: boolean;\n\n    /**\n     * @private\n     */\n    constructor(type: MapMouseEventType, map: Map, originalEvent: MouseEvent, data: EventData = {}) {\n        const point = DOM.mousePos(map.getCanvasContainer(), originalEvent);\n        const lngLat = map.unproject(point);\n        super(type, extend({point, lngLat, originalEvent}, data) as MapEvents[MapMouseEventType]);\n        this._defaultPrevented = false;\n        this.target = map;\n    }\n}\n\n/**\n * `MapTouchEvent` is a class used by other classes to generate\n * mouse events of specific types such as 'touchstart' or 'touchend'.\n * For a full list of available events, see [`Map` events](/mapbox-gl-js/api/map/#map-events).\n *\n * @extends {Object}\n *\n * @example\n * // Example of a MapTouchEvent of type \"touch\"\n * map.on('touchstart', (e) => {\n *     console.log(e);\n *     // {\n *     //   lngLat: {\n *     //      lng: 40.203,\n *     //      lat: -74.451\n *     //   },\n *     //   lngLats: [\n *     //      {\n *     //         lng: 40.203,\n *     //         lat: -74.451\n *     //      }\n *     //   ],\n *     //   originalEvent: {...},\n *     //   point: {\n *     //      x: 266,\n *     //      y: 464\n *     //   },\n *     //   points: [\n *     //      {\n *     //         x: 266,\n *     //         y: 464\n *     //      }\n *     //   ]\n *     //   preventDefault(),\n *     //   target: {...},\n *     //   type: \"touchstart\"\n *     // }\n * });\n * @see [Reference: `Map` events API documentation](https://docs.mapbox.com/mapbox-gl-js/api/map/#map-events)\n * @see [Example: Create a draggable point](https://docs.mapbox.com/mapbox-gl-js/example/drag-a-point/)\n */\nexport class MapTouchEvent extends Event<MapEvents, MapTouchEventType> {\n    /**\n     * The type of originating event. For a full list of available events, see [`Map` events](/mapbox-gl-js/api/map/#map-events).\n     */\n    type: MapTouchEventType;\n\n    /**\n     * The `Map` object that fired the event.\n     */\n    target: Map;\n\n    /**\n     * The DOM event which caused the map event.\n     */\n    originalEvent: TouchEvent;\n\n    /**\n     * The geographic location on the map of the center of the touch event points.\n     */\n    lngLat: LngLat;\n\n    /**\n     * The pixel coordinates of the center of the touch event points, relative to the map and measured from the top left\n     * corner.\n     */\n    point: Point;\n\n    /**\n     * The array of pixel coordinates corresponding to a\n     * [touch event's `touches`](https://developer.mozilla.org/en-US/docs/Web/API/TouchEvent/touches) property.\n     */\n    points: Array<Point>;\n\n    /**\n     * The geographical locations on the map corresponding to a\n     * [touch event's `touches`](https://developer.mozilla.org/en-US/docs/Web/API/TouchEvent/touches) property.\n     */\n    lngLats: Array<LngLat>;\n\n    /**\n     * If a `layerId` was specified when adding the event listener with {@link Map#on}, `features` will be an array of\n     * [GeoJSON](http://geojson.org/) [Feature objects](https://tools.ietf.org/html/rfc7946#section-3.2).\n     * The array will contain all features from that layer that are rendered at the event's point.\n     * The `features` are identical to those returned by {@link Map#queryRenderedFeatures}.\n     *\n     * If no `layerId` was specified when adding the event listener, `features` will be `undefined`.\n     * You can get the features at the point with `map.queryRenderedFeatures(e.point)`.\n     *\n     * @example\n     * // logging features for a specific layer (with `e.features`)\n     * map.on('touchstart', 'myLayerId', (e) => {\n     *     console.log(`There are ${e.features.length} features at point ${e.point}`);\n     * });\n     *\n     * @example\n     * // logging all features for all layers (without `e.features`)\n     * map.on('touchstart', (e) => {\n     *     const features = map.queryRenderedFeatures(e.point);\n     *     console.log(`There are ${features.length} features at point ${e.point}`);\n     * });\n     */\n    features: Array<GeoJSONFeature> | undefined;\n\n    /**\n     * Prevents subsequent default processing of the event by the map.\n     *\n     * Calling this method will prevent the following default map behaviors:\n     *\n     *   * On `touchstart` events, the behavior of {@link DragPanHandler}.\n     *   * On `touchstart` events, the behavior of {@link TouchZoomRotateHandler}.\n     *\n     * @example\n     * map.on('touchstart', (e) => {\n     *     e.preventDefault();\n     * });\n     */\n    preventDefault() {\n        this._defaultPrevented = true;\n    }\n\n    /**\n     * Returns `true` if `preventDefault` has been called.\n     * @private\n     */\n    get defaultPrevented(): boolean {\n        return this._defaultPrevented;\n    }\n\n    _defaultPrevented: boolean;\n\n    /**\n     * @private\n     */\n    constructor(type: MapTouchEventType, map: Map, originalEvent: TouchEvent) {\n        const touches = type === \"touchend\" ? originalEvent.changedTouches : originalEvent.touches;\n        const points = DOM.touchPos(map.getCanvasContainer(), touches);\n        const lngLats = points.map((t) => map.unproject(t));\n        const point = points.reduce((prev, curr, i, arr) => {\n            return prev.add(curr.div(arr.length));\n        }, new Point(0, 0));\n        const lngLat = map.unproject(point);\n        super(type, {points, point, lngLats, lngLat, originalEvent} as MapEvents[MapTouchEventType]);\n        this._defaultPrevented = false;\n    }\n}\n\n/**\n * `MapWheelEvent` is a class used by other classes to generate\n * mouse events of specific types such as 'wheel'.\n * For a full list of available events, see [`Map` events](/mapbox-gl-js/api/map/#map-events).\n *\n * @extends {Object}\n * @example\n * // Example event trigger for a MapWheelEvent of type \"wheel\"\n * map.on('wheel', (e) => {\n *     console.log('event type:', e.type);\n *     // event type: wheel\n * });\n * @example\n * // Example of a MapWheelEvent of type \"wheel\"\n * // {\n * //   originalEvent: WheelEvent {...},\n * // \t target: Map {...},\n * // \t type: \"wheel\"\n * // }\n * @see [Reference: `Map` events API documentation](https://docs.mapbox.com/mapbox-gl-js/api/map/#map-events)\n */\nexport class MapWheelEvent extends Event<MapEvents, 'wheel'> {\n    /**\n     * The type of originating event. For a full list of available events, see [`Map` events](/mapbox-gl-js/api/map/#map-events).\n     */\n    type: 'wheel';\n\n    /**\n     * The `Map` object that fired the event.\n     */\n    target: Map;\n\n    /**\n     * The DOM event which caused the map event.\n     */\n    originalEvent: WheelEvent;\n\n    /**\n     * Prevents subsequent default processing of the event by the map.\n     * Calling this method will prevent the the behavior of {@link ScrollZoomHandler}.\n     *\n     * @example\n     * map.on('wheel', (e) => {\n     *     // Prevent the default map scroll zoom behavior.\n     *     e.preventDefault();\n     * });\n     */\n    preventDefault() {\n        this._defaultPrevented = true;\n    }\n\n    /**\n     * `true` if `preventDefault` has been called.\n     * @private\n     */\n    get defaultPrevented(): boolean {\n        return this._defaultPrevented;\n    }\n\n    _defaultPrevented: boolean;\n\n    /**\n     * @private\n     */\n    constructor(map: Map, originalEvent: WheelEvent) {\n        super('wheel', {originalEvent} as MapEvents['wheel']);\n        this._defaultPrevented = false;\n    }\n}\n\n/**\n * `MapBoxZoomEvent` is a class used to generate\n * the events 'boxzoomstart', 'boxzoomend', and 'boxzoomcancel'.\n * For a full list of available events, see [`Map` events](/mapbox-gl-js/api/map/#map-events).\n *\n * @typedef {Object} MapBoxZoomEvent\n * @property {MouseEvent} originalEvent The DOM event that triggered the boxzoom event. Can be a `MouseEvent` or `KeyboardEvent`.\n * @property {('boxzoomstart' | 'boxzoomend' | 'boxzoomcancel')} type The type of originating event. For a full list of available events, see [`Map` events](/mapbox-gl-js/api/map/#map-events).\n * @property {Map} target The `Map` instance that triggered the event.\n * @example\n * // Example trigger of a BoxZoomEvent of type \"boxzoomstart\"\n * map.on('boxzoomstart', (e) => {\n *     console.log('event type:', e.type);\n *     // event type: boxzoomstart\n * });\n * @example\n * // Example of a BoxZoomEvent of type \"boxzoomstart\"\n * // {\n * //   originalEvent: {...},\n * //   type: \"boxzoomstart\",\n * //   target: {...}\n * // }\n * @see [Reference: `Map` events API documentation](https://docs.mapbox.com/mapbox-gl-js/api/map/#map-events)\n * @see [Example: Highlight features within a bounding box](https://docs.mapbox.com/mapbox-gl-js/example/using-box-queryrenderedfeatures/)\n */\n\nexport type MapStyleDataEvent = {\n    dataType: 'style';\n};\n\nexport type MapSourceDataEvent = {\n    dataType: 'source';\n    isSourceLoaded?: boolean;\n    source?: SourceSpecification;\n    sourceId?: string;\n    sourceCacheId?: string;\n    sourceDataType?: 'metadata' | 'content' | 'visibility' | 'error';\n    tile?: Tile;\n    coord?: Tile['tileID'];\n};\n\n/**\n * `MapDataEvent` is a type of events related to loading data, styles, and sources.\n * For a full list of available events, see [`Map` events](/mapbox-gl-js/api/map/#map-events).\n *\n * @typedef {Object} MapDataEvent\n * @property {('data' | 'dataloading' | 'styledata' | 'styledataloading' | 'sourcedata'| 'sourcedataloading')} type The type of originating event. For a full list of available events, see [`Map` events](/mapbox-gl-js/api/map/#map-events).\n * @property {('source' | 'style')} dataType The type of data that has changed. One of `'source'` or `'style'`, where `'source'` refers to the data associated with any source, and `'style'` refers to the entire [style](https://docs.mapbox.com/help/glossary/style/) used by the map.\n * @property {boolean} [isSourceLoaded] True if the event has a `dataType` of `source` and the source has no outstanding network requests.\n * @property {Object} [source] The [style spec representation of the source](https://docs.mapbox.com/mapbox-gl-js/style-spec/sources/) if the event has a `dataType` of `source`.\n * @property {string} [sourceId] The `id` of the [`source`](https://docs.mapbox.com/mapbox-gl-js/style-spec/sources/) that triggered the event, if the event has a `dataType` of `source`. Same as the `id` of the object in the `source` property.\n * @property {string} [sourceDataType] Included if the event has a `dataType` of `source` and the event signals\n * that internal data has been received or changed. Possible values are `metadata`, `content` and `visibility`, and `error`.\n * @property {Object} [tile] The tile being loaded or changed, if the event has a `dataType` of `source` and\n * the event is related to loading of a tile.\n * @property {Coordinate} [coord] The coordinate of the tile if the event has a `dataType` of `source` and\n * the event is related to loading of a tile.\n * @example\n * // Example of a MapDataEvent of type \"sourcedata\"\n * map.on('sourcedata', (e) => {\n *     console.log(e);\n *     // {\n *     //   dataType: \"source\",\n *     //   isSourceLoaded: false,\n *     //   source: {\n *     //     type: \"vector\",\n *     //     url: \"mapbox://mapbox.mapbox-streets-v8,mapbox.mapbox-terrain-v2\"\n *     //   },\n *     //   sourceDataType: \"visibility\",\n *     //   sourceId: \"composite\",\n *     //   style: {...},\n *     //   target: {...},\n *     //   type: \"sourcedata\"\n *     // }\n * });\n * @see [Reference: `Map` events API documentation](https://docs.mapbox.com/mapbox-gl-js/api/map/#map-events)\n * @see [Example: Change a map's style](https://docs.mapbox.com/mapbox-gl-js/example/setstyle/)\n * @see [Example: Add a GeoJSON line](https://docs.mapbox.com/mapbox-gl-js/example/geojson-line/)\n */\nexport type MapDataEvent = MapStyleDataEvent | MapSourceDataEvent\n\nexport type MapContextEvent = MapEventOf<'webglcontextlost' | 'webglcontextrestored'>\n\nexport type MapEvents = {\n    /** @section {Interaction}\n     * @event\n     * @instance\n     * @memberof Map\n     */\n\n    /**\n     * Fired when a pointing device (usually a mouse) is pressed within the map.\n     *\n     * **Note:** This event is compatible with the optional `layerId` parameter.\n     * If `layerId` is included as the second argument in {@link Map#on}, the event listener will fire only when the\n     * the cursor is pressed while inside a visible portion of the specifed layer.\n     *\n     * @event mousedown\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener\n     * map.on('mousedown', () => {\n     *     console.log('A mousedown event has occurred.');\n     * });\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener for a specific layer\n     * map.on('mousedown', 'poi-label', () => {\n     *     console.log('A mousedown event has occurred on a visible portion of the poi-label layer.');\n     * });\n     * @see [Example: Highlight features within a bounding box](https://docs.mapbox.com/mapbox-gl-js/example/using-box-queryrenderedfeatures/)\n     * @see [Example: Create a draggable point](https://docs.mapbox.com/mapbox-gl-js/example/drag-a-point/)\n     */\n    'mousedown': MapMouseEvent;\n\n    /**\n     * Fired when a pointing device (usually a mouse) is released within the map.\n     *\n     * **Note:** This event is compatible with the optional `layerId` parameter.\n     * If `layerId` is included as the second argument in {@link Map#on}, the event listener will fire only when the\n     * the cursor is released while inside a visible portion of the specifed layer.\n     *\n     * @event mouseup\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener\n     * map.on('mouseup', () => {\n     *     console.log('A mouseup event has occurred.');\n     * });\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener for a specific layer\n     * map.on('mouseup', 'poi-label', () => {\n     *     console.log('A mouseup event has occurred on a visible portion of the poi-label layer.');\n     * });\n     * @see [Example: Highlight features within a bounding box](https://docs.mapbox.com/mapbox-gl-js/example/using-box-queryrenderedfeatures/)\n     * @see [Example: Create a draggable point](https://docs.mapbox.com/mapbox-gl-js/example/drag-a-point/)\n     */\n    'mouseup': MapMouseEvent;\n\n    /**\n     * Fired when a pointing device (usually a mouse) is moved within the map.\n     * As you move the cursor across a web page containing a map,\n     * the event will fire each time it enters the map or any child elements.\n     *\n     * **Note:** This event is compatible with the optional `layerId` parameter.\n     * If `layerId` is included as the second argument in {@link Map#on}, the event listener will fire only when the\n     * the cursor is moved inside a visible portion of the specifed layer.\n     *\n     * @event mouseover\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener\n     * map.on('mouseover', () => {\n     *     console.log('A mouseover event has occurred.');\n     * });\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener for a specific layer\n     * map.on('mouseover', 'poi-label', () => {\n     *     console.log('A mouseover event has occurred on a visible portion of the poi-label layer.');\n     * });\n     * @see [Example: Get coordinates of the mouse pointer](https://www.mapbox.com/mapbox-gl-js/example/mouse-position/)\n     * @see [Example: Highlight features under the mouse pointer](https://www.mapbox.com/mapbox-gl-js/example/hover-styles/)\n     * @see [Example: Display a popup on hover](https://www.mapbox.com/mapbox-gl-js/example/popup-on-hover/)\n     */\n    'mouseover': MapMouseEvent;\n\n    /**\n     * Fired when a pointing device (usually a mouse) is moved while the cursor is inside the map.\n     * As you move the cursor across the map, the event will fire every time the cursor changes position within the map.\n     *\n     * **Note:** This event is compatible with the optional `layerId` parameter.\n     * If `layerId` is included as the second argument in {@link Map#on}, the event listener will fire only when the\n     * the cursor is inside a visible portion of the specified layer.\n     *\n     * @event mousemove\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener\n     * map.on('mousemove', () => {\n     *     console.log('A mousemove event has occurred.');\n     * });\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener for a specific layer\n     * map.on('mousemove', 'poi-label', () => {\n     *     console.log('A mousemove event has occurred on a visible portion of the poi-label layer.');\n     * });\n     * @see [Example: Get coordinates of the mouse pointer](https://www.mapbox.com/mapbox-gl-js/example/mouse-position/)\n     * @see [Example: Highlight features under the mouse pointer](https://www.mapbox.com/mapbox-gl-js/example/hover-styles/)\n     * @see [Example: Display a popup on over](https://www.mapbox.com/mapbox-gl-js/example/popup-on-hover/)\n     */\n    'mousemove': MapMouseEvent;\n\n    /**\n     * Triggered when a click event occurs and is fired before the click event.\n     * Primarily implemented to ensure closeOnClick for pop-ups is fired before any other listeners.\n     *\n     * @event preclick\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent}\n     */\n    'preclick': MapMouseEvent;\n\n    /**\n     * Fired when a pointing device (usually a mouse) is pressed and released at the same point on the map.\n     *\n     * **Note:** This event is compatible with the optional `layerId` parameter.\n     * If `layerId` is included as the second argument in {@link Map#on}, the event listener will fire only when the\n     * point that is pressed and released contains a visible portion of the specifed layer.\n     *\n     * @event click\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener\n     * map.on('click', (e) => {\n     *     console.log(`A click event has occurred at ${e.lngLat}`);\n     * });\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener for a specific layer\n     * map.on('click', 'poi-label', (e) => {\n     *     console.log(`A click event has occurred on a visible portion of the poi-label layer at ${e.lngLat}`);\n     * });\n     * @see [Example: Measure distances](https://www.mapbox.com/mapbox-gl-js/example/measure/)\n     * @see [Example: Center the map on a clicked symbol](https://www.mapbox.com/mapbox-gl-js/example/center-on-symbol/)\n     */\n    'click': MapMouseEvent;\n\n    /**\n     * Fired when a pointing device (usually a mouse) is pressed and released twice at the same point on\n     * the map in rapid succession.\n     *\n     * **Note:** This event is compatible with the optional `layerId` parameter.\n     * If `layerId` is included as the second argument in {@link Map#on}, the event listener will fire only\n     * when the point that is clicked twice contains a visible portion of the specifed layer.\n     *\n     * @event dblclick\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener\n     * map.on('dblclick', (e) => {\n     *     console.log(`A dblclick event has occurred at ${e.lngLat}`);\n     * });\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener for a specific layer\n     * map.on('dblclick', 'poi-label', (e) => {\n     *     console.log(`A dblclick event has occurred on a visible portion of the poi-label layer at ${e.lngLat}`);\n     * });\n     */\n    'dblclick': MapMouseEvent;\n\n    /**\n     * Fired when a pointing device (usually a mouse) enters a visible portion of a specified layer from\n     * outside that layer or outside the map canvas.\n     *\n     * **Important:** This event can only be listened for when {@link Map#on} includes three arguments,\n     * where the second argument specifies the desired layer.\n     *\n     * @event mouseenter\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener\n     * map.on('mouseenter', 'water', () => {\n     *     console.log('A mouseenter event occurred on a visible portion of the water layer.');\n     * });\n     * @see [Example: Center the map on a clicked symbol](https://docs.mapbox.com/mapbox-gl-js/example/center-on-symbol/)\n     * @see [Example: Display a popup on click](https://docs.mapbox.com/mapbox-gl-js/example/popup-on-click/)\n     */\n    'mouseenter': MapMouseEvent;\n\n    /**\n     * Fired when a pointing device (usually a mouse) leaves a visible portion of a specified layer or moves\n     * from the specified layer to outside the map canvas.\n     *\n     * **Note:** To detect when the mouse leaves the canvas, independent of layer, use {@link Map.event:mouseout} instead.\n     *\n     * **Important:** This event can only be listened for when {@link Map#on} includes three arguments,\n     * where the second argument specifies the desired layer.\n     *\n     * @event mouseleave\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when the pointing device leaves\n     * // a visible portion of the specified layer.\n     * map.on('mouseleave', 'water', () => {\n     *     console.log('A mouseleave event occurred.');\n     * });\n     * @see [Example: Highlight features under the mouse pointer](https://www.mapbox.com/mapbox-gl-js/example/hover-styles/)\n     * @see [Example: Display a popup on click](https://docs.mapbox.com/mapbox-gl-js/example/popup-on-click/)\n     */\n    'mouseleave': MapMouseEvent;\n\n    /**\n     * Fired when a point device (usually a mouse) leaves the map's canvas.\n     *\n     * @event mouseout\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when the pointing device leaves\n     * // the map's canvas.\n     * map.on('mouseout', () => {\n     *     console.log('A mouseout event occurred.');\n     * });\n     */\n    'mouseout': MapMouseEvent;\n\n    /**\n     * Fired when the right button of the mouse is clicked or the context menu key is pressed within the map.\n     *\n     * @event contextmenu\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when the right mouse button is\n     * // pressed within the map.\n     * map.on('contextmenu', () => {\n     *     console.log('A contextmenu event occurred.');\n     * });\n     */\n    'contextmenu': MapMouseEvent;\n\n    /**\n     * Fired when a [`wheel`](https://developer.mozilla.org/en-US/docs/Web/Events/wheel) event occurs within the map.\n     *\n     * @event wheel\n     * @memberof Map\n     * @instance\n     * @type {MapWheelEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when a wheel event occurs within the map.\n     * map.on('wheel', () => {\n     *     console.log('A wheel event occurred.');\n     * });\n     */\n    'wheel': MapWheelEvent;\n\n    /**\n     * Fired when a [`touchstart`](https://developer.mozilla.org/en-US/docs/Web/Events/touchstart) event occurs within the map.\n     *\n     * @event touchstart\n     * @memberof Map\n     * @instance\n     * @type {MapTouchEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when a `touchstart` event occurs within the map.\n     * map.on('touchstart', () => {\n     *     console.log('A touchstart event occurred.');\n     * });\n     * @see [Example: Create a draggable point](https://docs.mapbox.com/mapbox-gl-js/example/drag-a-point/)\n     */\n    'touchstart': MapTouchEvent;\n\n    /**\n     * Fired when a [`touchend`](https://developer.mozilla.org/en-US/docs/Web/Events/touchend) event occurs within the map.\n     *\n     * @event touchend\n     * @memberof Map\n     * @instance\n     * @type {MapTouchEvent}\n     * @example\n     * // Initialize the map.\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires when a `touchstart` event occurs within the map.\n     * map.on('touchstart', () => {\n     *     console.log('A touchstart event occurred.');\n     * });\n     * @see [Example: Create a draggable point](https://docs.mapbox.com/mapbox-gl-js/example/drag-a-point/)\n     */\n    'touchend': MapTouchEvent;\n\n    /**\n     * Fired when a [`touchmove`](https://developer.mozilla.org/en-US/docs/Web/Events/touchmove) event occurs within the map.\n     *\n     * @event touchmove\n     * @memberof Map\n     * @instance\n     * @type {MapTouchEvent}\n     * @example\n     * // Initialize the map.\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires when a touchmove event occurs within the map.\n     * map.on('touchmove', () => {\n     *     console.log('A touchmove event occurred.');\n     * });\n     * @see [Example: Create a draggable point](https://docs.mapbox.com/mapbox-gl-js/example/drag-a-point/)\n     */\n    'touchmove': MapTouchEvent;\n\n    /**\n     * Fired when a [`touchcancel`](https://developer.mozilla.org/en-US/docs/Web/Events/touchcancel) event occurs within the map.\n     *\n     * @event touchcancel\n     * @memberof Map\n     * @instance\n     * @type {MapTouchEvent}\n     * @example\n     * // Initialize the map.\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires when a `touchcancel` event occurs within the map.\n     * map.on('touchcancel', () => {\n     *     console.log('A touchcancel event occurred.');\n     * });\n     */\n    'touchcancel': MapTouchEvent;\n\n    /** @section {Movement}\n     * @event\n     * @instance\n     * @memberof Map */\n\n    /**\n     * Fired just before the map begins a transition from one view to another, as the result of either user interaction or methods such as {@link Map#jumpTo}.\n     *\n     * @event movestart\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map.\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires just before the map begins a transition from one view to another.\n     * map.on('movestart', () => {\n     *     console.log('A movestart` event occurred.');\n     * });\n     */\n    'movestart': {originalEvent?: MouseEvent | WheelEvent | TouchEvent};\n\n    /**\n     * Fired repeatedly during an animated transition from one view to another, as the result of either user interaction or methods such as {@link Map#flyTo}.\n     *\n     * @event move\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map.\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires repeatedly during an animated transition.\n     * map.on('move', () => {\n     *     console.log('A move event occurred.');\n     * });\n     * @see [Example: Display HTML clusters with custom properties](https://docs.mapbox.com/mapbox-gl-js/example/cluster-html/)\n     * @see [Example: Filter features within map view](https://docs.mapbox.com/mapbox-gl-js/example/filter-features-within-map-view/)\n     */\n    'move': {originalEvent?: MouseEvent | WheelEvent | TouchEvent};\n\n    /**\n     * Fired just after the map completes a transition from one\n     * view to another, as the result of either user interaction or methods such as {@link Map#jumpTo}.\n     *\n     * @event moveend\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // just after the map completes a transition.\n     * map.on('moveend', () => {\n     *     console.log('A moveend event occurred.');\n     * });\n     * @see [Example: Play map locations as a slideshow](https://www.mapbox.com/mapbox-gl-js/example/playback-locations/)\n     * @see [Example: Filter features within map view](https://www.mapbox.com/mapbox-gl-js/example/filter-features-within-map-view/)\n     * @see [Example: Display HTML clusters with custom properties](https://docs.mapbox.com/mapbox-gl-js/example/cluster-html/)\n     */\n    'moveend': {originalEvent?: MouseEvent | WheelEvent | TouchEvent};\n\n    /**\n     * Fired when a \"drag to pan\" interaction starts. See {@link DragPanHandler}.\n     *\n     * @event dragstart\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when a \"drag to pan\" interaction starts.\n     * map.on('dragstart', () => {\n     *     console.log('A dragstart event occurred.');\n     * });\n     */\n    'dragstart': {originalEvent?: MouseEvent | TouchEvent};\n\n    /**\n     * Fired repeatedly during a \"drag to pan\" interaction. See {@link DragPanHandler}.\n     *\n     * @event drag\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // repeatedly during a \"drag to pan\" interaction.\n     * map.on('drag', () => {\n     *     console.log('A drag event occurred.');\n     * });\n     */\n    'drag': {originalEvent?: MouseEvent | TouchEvent};\n\n    /**\n     * Fired when a \"drag to pan\" interaction ends. See {@link DragPanHandler}.\n     *\n     * @event dragend\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when a \"drag to pan\" interaction ends.\n     * map.on('dragend', () => {\n     *     console.log('A dragend event occurred.');\n     * });\n     * @see [Example: Create a draggable marker](https://docs.mapbox.com/mapbox-gl-js/example/drag-a-marker/)\n     */\n    'dragend': {originalEvent?: MouseEvent | TouchEvent};\n\n    /**\n     * Fired just before the map begins a transition from one zoom level to another,\n     * as the result of either user interaction or methods such as {@link Map#flyTo}.\n     *\n     * @event zoomstart\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // just before a zoom transition starts.\n     * map.on('zoomstart', () => {\n     *     console.log('A zoomstart event occurred.');\n     * });\n     */\n    'zoomstart': {originalEvent?: WheelEvent | TouchEvent} | void;\n\n    /**\n     * Fired repeatedly during an animated transition from one zoom level to another,\n     * as the result of either user interaction or methods such as {@link Map#flyTo}.\n     *\n     * @event zoom\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // repeatedly during a zoom transition.\n     * map.on('zoom', () => {\n     *     console.log('A zoom event occurred.');\n     * });\n     * @see [Example: Update a choropleth layer by zoom level](https://www.mapbox.com/mapbox-gl-js/example/updating-choropleth/)\n     */\n    'zoom': {originalEvent?: WheelEvent | TouchEvent} | void;\n\n    /**\n     * Fired just after the map completes a transition from one zoom level to another\n     * as the result of either user interaction or methods such as {@link Map#flyTo}.\n     * The zoom transition will usually end before rendering is finished, so if you\n     * need to wait for rendering to finish, use the {@link Map.event:idle} event instead.\n     *\n     * @event zoomend\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // just after a zoom transition finishes.\n     * map.on('zoomend', () => {\n     *     console.log('A zoomend event occurred.');\n     * });\n     */\n    'zoomend': {originalEvent?: WheelEvent | TouchEvent} | void;\n\n    /**\n     * Fired when a \"drag to rotate\" interaction starts. See {@link DragRotateHandler}.\n     *\n     * @event rotatestart\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // just before a \"drag to rotate\" interaction starts.\n     * map.on('rotatestart', () => {\n     *     console.log('A rotatestart event occurred.');\n     * });\n     */\n    'rotatestart': {originalEvent?: MouseEvent | TouchEvent};\n\n    /**\n     * Fired repeatedly during a \"drag to rotate\" interaction. See {@link DragRotateHandler}.\n     *\n     * @event rotate\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // repeatedly during \"drag to rotate\" interaction.\n     * map.on('rotate', () => {\n     *     console.log('A rotate event occurred.');\n     * });\n     */\n    'rotate': {originalEvent?: MouseEvent | TouchEvent};\n\n    /**\n     * Fired when a \"drag to rotate\" interaction ends. See {@link DragRotateHandler}.\n     *\n     * @event rotateend\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // just after a \"drag to rotate\" interaction ends.\n     * map.on('rotateend', () => {\n     *     console.log('A rotateend event occurred.');\n     * });\n     */\n    'rotateend': {originalEvent?: MouseEvent | TouchEvent};\n\n    /**\n     * Fired whenever the map's pitch (tilt) begins a change as\n     * the result of either user interaction or methods such as {@link Map#flyTo} .\n     *\n     * @event pitchstart\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // just before a pitch (tilt) transition starts.\n     * map.on('pitchstart', () => {\n     *     console.log('A pitchstart event occurred.');\n     * });\n     */\n    'pitchstart': {originalEvent?: MouseEvent | TouchEvent} | void;\n\n    /**\n     * Fired repeatedly during the map's pitch (tilt) animation between\n     * one state and another as the result of either user interaction\n     * or methods such as {@link Map#flyTo}.\n     *\n     * @event pitch\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // repeatedly during a pitch (tilt) transition.\n     * map.on('pitch', () => {\n     *     console.log('A pitch event occurred.');\n     * });\n     */\n    'pitch': {originalEvent?: MouseEvent | TouchEvent} | void;\n\n    /**\n     * Fired immediately after the map's pitch (tilt) finishes changing as\n     * the result of either user interaction or methods such as {@link Map#flyTo}.\n     *\n     * @event pitchend\n     * @memberof Map\n     * @instance\n     * @type {MapMouseEvent | MapTouchEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // just after a pitch (tilt) transition ends.\n     * map.on('pitchend', () => {\n     *     console.log('A pitchend event occurred.');\n     * });\n     */\n    'pitchend': {originalEvent?: MouseEvent | TouchEvent} | void;\n\n    /**\n     * Fired when a \"box zoom\" interaction starts. See {@link BoxZoomHandler}.\n     *\n     * @event boxzoomstart\n     * @memberof Map\n     * @instance\n     * @type {MapBoxZoomEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // just before a \"box zoom\" interaction starts.\n     * map.on('boxzoomstart', () => {\n     *     console.log('A boxzoomstart event occurred.');\n     * });\n     */\n    'boxzoomstart': {originalEvent?: MouseEvent | KeyboardEvent};\n\n    /**\n     * Fired when a \"box zoom\" interaction ends.  See {@link BoxZoomHandler}.\n     *\n     * @event boxzoomend\n     * @memberof Map\n     * @instance\n     * @type {MapBoxZoomEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // just after a \"box zoom\" interaction ends.\n     * map.on('boxzoomend', () => {\n     *     console.log('A boxzoomend event occurred.');\n     * });\n     */\n    'boxzoomend': {originalEvent?: MouseEvent};\n\n    /**\n     * Fired when the user cancels a \"box zoom\" interaction, or when the bounding box does not meet the minimum size threshold.\n     * See {@link BoxZoomHandler}.\n     *\n     * @event boxzoomcancel\n     * @memberof Map\n     * @instance\n     * @type {MapBoxZoomEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // the user cancels a \"box zoom\" interaction.\n     * map.on('boxzoomcancel', () => {\n     *     console.log('A boxzoomcancel event occurred.');\n     * });\n     */\n    'boxzoomcancel': {originalEvent?: MouseEvent | KeyboardEvent};\n\n    /**\n     * Fired immediately after the map has been resized.\n     *\n     * @event resize\n     * @memberof Map\n     * @instance\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // immediately after the map has been resized.\n     * map.on('resize', () => {\n     *     console.log('A resize event occurred.');\n     * });\n     */\n    'resize': object | void;\n\n    /** @section {Lifecycle}\n     * @event\n     * @instance\n     * @memberof Map */\n\n    /**\n     * Fired immediately after all necessary resources have been downloaded\n     * and the first visually complete rendering of the map has occurred.\n     *\n     * @event load\n     * @memberof Map\n     * @instance\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when the map has finished loading.\n     * map.on('load', () => {\n     *     console.log('A load event occurred.');\n     * });\n     * @see [Example: Draw GeoJSON points](https://www.mapbox.com/mapbox-gl-js/example/geojson-markers/)\n     * @see [Example: Add live realtime data](https://www.mapbox.com/mapbox-gl-js/example/live-geojson/)\n     * @see [Example: Animate a point](https://www.mapbox.com/mapbox-gl-js/example/animate-point-along-line/)\n     */\n    'load': void;\n\n    /**\n     * Fired whenever the rendering process of the map is started.\n     * This event can be used in pair with the \"render\" event,\n     * to measure the time spent on the CPU during the rendering\n     * of a single frame.\n     *\n     * @event renderstart\n     * @memberof Map\n     * @instance\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when the map begins rendering.\n     * map.on('renderstart', () => {\n     *     console.log('A renderstart event occurred.');\n     * });\n     */\n    'renderstart': void;\n\n    /**\n     * Fired whenever the map is drawn to the screen, as the result of:\n     *\n     * - a change to the map's position, zoom, pitch, or bearing\n     * - a change to the map's style\n     * - a change to a GeoJSON source\n     * - the loading of a vector tile, GeoJSON file, glyph, or sprite.\n     *\n     * @event render\n     * @memberof Map\n     * @instance\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // whenever the map is drawn to the screen.\n     * map.on('render', () => {\n     *     console.log('A render event occurred.');\n     * });\n     */\n    'render': void;\n\n    /**\n     * Fired after the last frame rendered before the map enters an\n     * \"idle\" state:\n     *\n     * - No camera transitions are in progress\n     * - All currently requested tiles have loaded\n     * - All fade/transition animations have completed.\n     *\n     * @event idle\n     * @memberof Map\n     * @instance\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // just before the map enters an \"idle\" state.\n     * map.on('idle', () => {\n     *     console.log('A idle event occurred.');\n     * });\n     */\n    'idle': void;\n\n    /**\n     * Fired immediately after the map has been removed with {@link Map.event:remove}.\n     *\n     * @event remove\n     * @memberof Map\n     * @instance\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // just after the map is removed.\n     * map.on('remove', () => {\n     *     console.log('A remove event occurred.');\n     * });\n     */\n    'remove': void;\n\n    /**\n     * Fired when an error occurs. This is Mapbox GL JS's primary error reporting\n     * mechanism. We use an event instead of `throw` to better accommodate\n     * asyncronous operations. If no listeners are bound to the `error` event, the\n     * error will be printed to the console.\n     *\n     * @event error\n     * @memberof Map\n     * @instance\n     * @property {string} message Error message.\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when an error occurs.\n     * map.on('error', () => {\n     *     console.log('A error event occurred.');\n     * });\n     */\n    'error': {error: Error};\n\n    /**\n     * Fired when the WebGL context is lost.\n     *\n     * @event webglcontextlost\n     * @memberof Map\n     * @instance\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when the WebGL context is lost.\n     * map.on('webglcontextlost', () => {\n     *     console.log('A webglcontextlost event occurred.');\n     * });\n     */\n    'webglcontextlost': {originalEvent?: WebGLContextEvent}\n\n    /**\n     * Fired when the WebGL context is restored.\n     *\n     * @event webglcontextrestored\n     * @memberof Map\n     * @instance\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when the WebGL context is restored.\n     * map.on('webglcontextrestored', () => {\n     *     console.log('A webglcontextrestored event occurred.');\n     * });\n     */\n    'webglcontextrestored': {originalEvent?: WebGLContextEvent};\n\n    /** @section {Data loading}\n     * @event\n     * @instance\n     * @memberof Map */\n\n    /**\n     * Fired when any map data loads or changes. See {@link MapDataEvent}\n     * for more information.\n     *\n     * @event data\n     * @memberof Map\n     * @instance\n     * @type {MapDataEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when map data loads or changes.\n     * map.on('data', () => {\n     *     console.log('A data event occurred.');\n     * });\n     * @see [Example: Display HTML clusters with custom properties](https://docs.mapbox.com/mapbox-gl-js/example/cluster-html/)\n     */\n    'data': MapDataEvent;\n\n    /**\n     * Fired when the map's style loads or changes. See\n     * {@link MapDataEvent} for more information.\n     *\n     * @event styledata\n     * @memberof Map\n     * @instance\n     * @type {MapDataEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when the map's style loads or changes.\n     * map.on('styledata', () => {\n     *     console.log('A styledata event occurred.');\n     * });\n     */\n    'styledata': MapStyleDataEvent;\n\n    /**\n     * Fired when one of the map's sources loads or changes, including if a tile belonging\n     * to a source loads or changes. See {@link MapDataEvent} for more information.\n     *\n     * @event sourcedata\n     * @memberof Map\n     * @instance\n     * @type {MapDataEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when one of the map's sources loads or changes.\n     * map.on('sourcedata', () => {\n     *     console.log('A sourcedata event occurred.');\n     * });\n     */\n    'sourcedata': MapSourceDataEvent;\n\n    /**\n     * Fired when any map data (style, source, tile, etc) begins loading or\n     * changing asynchronously. All `dataloading` events are followed by a `data`\n     * or `error` event. See {@link MapDataEvent} for more information.\n     *\n     * @event dataloading\n     * @memberof Map\n     * @instance\n     * @type {MapDataEvent}\n     * @example\n     * // Initialize the map\n     * const map = new mapboxgl.Map({});\n     * // Set an event listener that fires\n     * // when any map data begins loading\n     * // or changing asynchronously.\n     * map.on('dataloading', () => {\n     *     console.log('A dataloading event occurred.');\n     * });\n     */\n    'dataloading': MapDataEvent;\n\n    /**\n     * Fired when the map's style begins loading or changing asynchronously.\n     * All `styledata