meout(this._alertTimer);\n            this._alertContainer.remove();\n        }\n    }\n\n    wheel(e: WheelEvent) {\n        if (!this.isEnabled()) return;\n\n        if (this._map._cooperativeGestures) {\n            if (!e.ctrlKey && !e.metaKey && !this.isZooming() && !isFullscreen()) {\n                this._showBlockerAlert();\n                return;\n            } else if (this._alertContainer.style.visibility !== 'hidden') {\n                // immediately hide alert if it is visible when ctrl or ⌘ is pressed while scroll zooming.\n                this._alertContainer.style.visibility = 'hidden';\n                clearTimeout(this._alertTimer);\n            }\n        }\n\n        let value = e.deltaMode === WheelEvent.DOM_DELTA_LINE ? e.deltaY * 40 : e.deltaY;\n        const now = browser.now(),\n            timeDelta = now - (this._lastWheelEventTime || 0);\n\n        this._lastWheelEventTime = now;\n\n        if (value !== 0 && (value % wheelZoomDelta) === 0) {\n            // This one is definitely a mouse wheel event.\n            this._type = 'wheel';\n\n        } else if (value !== 0 && Math.abs(value) < 4) {\n            // This one is definitely a trackpad event because it is so small.\n            this._type = 'trackpad';\n\n        } else if (timeDelta > 400) {\n            // This is likely a new scroll action.\n            this._type = null;\n            this._lastValue = value;\n\n            // Start a timeout in case this was a singular event, and delay it by up to 40ms.\n            this._timeout = window.setTimeout(this._onTimeout, 40, e);\n\n        } else if (!this._type) {\n            // This is a repeating event, but we don't know the type of event just yet.\n            // If the delta per time is small, we assume it's a fast trackpad; otherwise we switch into wheel mode.\n            this._type = (Math.abs(timeDelta * value) < 200) ? 'trackpad' : 'wheel';\n\n            // Make sure our delayed event isn't fired again, because we accumulate\n            // the previous event (which was less than 40ms ago) into this event.\n            if (this._timeout) {\n                clearTimeout(this._timeout);\n                this._timeout = null;\n                value += this._lastValue;\n            }\n        }\n\n        // Slow down zoom if shift key is held for more precise zooming\n        if (e.shiftKey && value) value = value / 4;\n\n        // Only fire the callback if we actually know what type of scrolling device the user uses.\n        if (this._type) {\n            this._lastWheelEvent = e;\n            this._delta -= value;\n            if (!this._active) {\n                this._start(e);\n            }\n        }\n\n        e.preventDefault();\n    }\n\n    _onTimeout(initialEvent: WheelEvent) {\n        this._type = 'wheel';\n        this._delta -= this._lastValue;\n        if (!this._active) {\n            this._start(initialEvent);\n        }\n    }\n\n    _start(e: WheelEvent) {\n        if (!this._delta) return;\n\n        if (this._frameId) {\n            this._frameId = null;\n        }\n\n        this._active = true;\n        if (!this.isZooming()) {\n            this._zooming = true;\n        }\n\n        if (this._finishTimeout) {\n            clearTimeout(this._finishTimeout);\n            delete this._finishTimeout;\n        }\n\n        const pos = DOM.mousePos(this._el, e);\n        this._aroundPoint = this._aroundCenter ? this._map.transform.centerPoint : pos;\n        this._aroundCoord = this._map.transform.pointCoordinate3D(this._aroundPoint);\n        this._targetZoom = undefined;\n\n        if (!this._frameId) {\n            this._frameId = true;\n            this._handler._triggerRenderFrame();\n        }\n    }\n\n    renderFrame(): HandlerResult | null | undefined {\n        if (!this._frameId) return;\n        this._frameId = null;\n\n        if (!this.isActive()) return;\n\n        const tr = this._map.transform;\n\n        // If projection wraps and center crosses the antimeridian, reset previous mouse scroll easing settings to resolve https://github.com/mapbox/mapbox-gl-js/issues/11910\n        if (this._type === 'wheel' && tr.projection.wrap && (tr._center.lng >= 180 || tr._center.lng <= -180)) {\n            this._prevEase = null;\n            this._easing = null;\n            this._lastWheelEvent = null;\n            this._lastWheelEventTime = 0;\n        }\n\n        const startingZoom = () => {\n            return (tr._terrainEnabled() && this._aroundCoord) ? tr.computeZoomRelativeTo(this._aroundCoord) : tr.zoom;\n        };\n\n        // if we've had scroll events since the last render frame, consume the\n        // accumulated delta, and update the target zoom level accordingly\n        if (this._delta !== 0) {\n            // For trackpad events and single mouse wheel ticks, use the default zoom rate\n            const zoomRate = (this._type === 'wheel' && Math.abs(this._delta) > wheelZoomDelta) ? this._wheelZoomRate : this._defaultZoomRate;\n            // Scale by sigmoid of scroll wheel delta.\n            let scale = maxScalePerFrame / (1 + Math.exp(-Math.abs(this._delta * zoomRate)));\n\n            if (this._delta < 0 && scale !== 0) {\n                scale = 1 / scale;\n            }\n\n            const startZoom = startingZoom();\n            const startScale = Math.pow(2.0, startZoom);\n\n            const fromScale = typeof this._targetZoom === 'number' ? tr.zoomScale(this._targetZoom) : startScale;\n            this._targetZoom = Math.min(tr.maxZoom, Math.max(tr.minZoom, tr.scaleZoom(fromScale * scale)));\n\n            // if this is a mouse wheel, refresh the starting zoom and easing\n            // function we're using to smooth out the zooming between wheel\n            // events\n            if (this._type === 'wheel') {\n                this._startZoom = startZoom;\n                this._easing = this._smoothOutEasing(200);\n            }\n            this._lastDelta = this._delta;\n            this._delta = 0;\n        }\n        const targetZoom = typeof this._targetZoom === 'number' ?\n            this._targetZoom : startingZoom();\n        const startZoom = this._startZoom;\n        const easing = this._easing;\n\n        let finished = false;\n        let zoom;\n        if (this._type === 'wheel' && startZoom && easing) {\n            assert(easing && typeof startZoom === 'number');\n\n            const t = Math.min((browser.now() - this._lastWheelEventTime) / 200, 1);\n            const k = easing(t);\n            zoom = interpolate(startZoom, targetZoom, k);\n            if (t < 1) {\n                if (!this._frameId) {\n                    this._frameId = true;\n                }\n            } else {\n                finished = true;\n            }\n        } else {\n            zoom = targetZoom;\n            finished = true;\n        }\n\n        this._active = true;\n\n        if (finished) {\n            this._active = false;\n            this._finishTimeout = window.setTimeout(() => {\n                this._zooming = false;\n                this._handler._triggerRenderFrame();\n                delete this._targetZoom;\n                delete this._finishTimeout;\n            }, 200);\n        }\n\n        let zoomDelta = zoom - startingZoom();\n        if (zoomDelta * this._lastDelta < 0) {\n            // prevent recenter zoom in opposite direction from zoom\n            zoomDelta = 0;\n        }\n        return {\n            noInertia: true,\n            needsRenderFrame: !finished,\n            zoomDelta,\n            around: this._aroundPoint,\n            aroundCoord: this._aroundCoord,\n            originalEvent: this._lastWheelEvent\n        };\n    }\n\n    _smoothOutEasing(duration: number): (arg1: number) => number {\n        let easing = _ease;\n\n        if (this._prevEase) {\n            const ease = this._prevEase,\n                t = (browser.now() - ease.start) / ease.duration,\n                speed = ease.easing(t + 0.01) - ease.easing(t),\n\n                // Quick hack to make new bezier that is continuous with last\n                x = 0.27 / Math.sqrt(speed * speed + 0.0001) * 0.01,\n                y = Math.sqrt(0.27 * 0.27 - x * x);\n\n            easing = bezier(x, y, 0.25, 1);\n        }\n\n        this._prevEase = {\n            start: browser.now(),\n            duration,\n            easing\n        };\n\n        return easing;\n    }\n\n    blur() {\n        this.reset();\n    }\n\n    reset() {\n        this._active = false;\n    }\n\n    _addScrollZoomBlocker() {\n        if (this._map && !this._alertContainer) {\n            this._alertContainer = DOM.create('div', 'mapboxgl-scroll-zoom-blocker', this._map._container);\n\n            if (/(Mac|iPad)/i.test(navigator.userAgent)) {\n                this._alertContainer.textContent = this._map._getUIString('ScrollZoomBlocker.CmdMessage');\n            } else {\n                this._alertContainer.textContent = this._map._getUIString('ScrollZoomBlocker.CtrlMessage');\n            }\n\n            // dynamically set the font size of the scroll zoom blocker alert message\n            this._alertContainer.style.fontSize = `${Math.max(10, Math.min(24, Math.floor(this._el.clientWidth * 0.05)))}px`;\n        }\n    }\n\n    _showBlockerAlert() {\n        this._alertContainer.style.visibility = 'visible';\n        this._alertContainer.classList.add('mapboxgl-scroll-zoom-blocker-show');\n        this._alertContainer.setAttribute(\"role\", \"alert\");\n\n        clearTimeout(this._alertTimer);\n\n        this._alertTimer = window.setTimeout(() => {\n            this._alertContainer.classList.remove('mapboxgl-scroll-zoom-blocker-show');\n            this._alertContainer.removeAttribute(\"role\");\n        }, 200);\n    }\n\n}\n\nexport default ScrollZoomHandler;\n","import type ClickZoomHandler from '../click_zoom';\nimport type TapZoomHandler from './../tap_zoom';\n\n/**\n * The `DoubleClickZoomHandler` allows the user to zoom the map at a point by\n * double clicking or double tapping.\n *\n * @see [Example: Toggle interactions](https://docs.mapbox.com/mapbox-gl-js/example/toggle-interaction-handlers/)\n */\nexport default class DoubleClickZoomHandler {\n\n    _clickZoom: ClickZoomHandler;\n    _tapZoom: TapZoomHandler;\n\n    /**\n     * @private\n    */\n    constructor(clickZoom: ClickZoomHandler, TapZoom: TapZoomHandler) {\n        this._clickZoom = clickZoom;\n        this._tapZoom = TapZoom;\n    }\n\n    /**\n     * Enables the \"double click to zoom\" interaction.\n     *\n     * @example\n     * map.doubleClickZoom.enable();\n     */\n    enable() {\n        this._clickZoom.enable();\n        this._tapZoom.enable();\n    }\n\n    /**\n     * Disables the \"double click to zoom\" interaction.\n     *\n     * @example\n     * map.doubleClickZoom.disable();\n     */\n    disable() {\n        this._clickZoom.disable();\n        this._tapZoom.disable();\n    }\n\n    /**\n     * Returns a Boolean indicating whether the \"double click to zoom\" interaction is enabled.\n     *\n     * @returns {boolean} Returns `true` if the \"double click to zoom\" interaction is enabled.\n     * @example\n     * const isDoubleClickZoomEnabled = map.doubleClickZoom.isEnabled();\n     */\n    isEnabled(): boolean {\n        return this._clickZoom.isEnabled() && this._tapZoom.isEnabled();\n    }\n\n    /**\n     * Returns a Boolean indicating whether the \"double click to zoom\" interaction is active (currently being used).\n     *\n     * @returns {boolean} Returns `true` if the \"double click to zoom\" interaction is active.\n     * @example\n     * const isDoubleClickZoomActive = map.doubleClickZoom.isActive();\n     */\n    isActive(): boolean {\n        return this._clickZoom.isActive() || this._tapZoom.isActive();\n    }\n}\n","import type Point from '@mapbox/point-geometry';\nimport type {Map} from '../map';\nimport type {Handler, HandlerResult} from '../handler';\n\nexport default class ClickZoomHandler implements Handler {\n    _enabled: boolean;\n    _active: boolean;\n\n    constructor() {\n        this.reset();\n    }\n\n    reset() {\n        this._active = false;\n    }\n\n    blur() {\n        this.reset();\n    }\n\n    dblclick(e: MouseEvent, point: Point): HandlerResult {\n        e.preventDefault();\n        return {\n            cameraAnimation: (map: Map) => {\n                map.easeTo({\n                    duration: 300,\n                    zoom: map.getZoom() + (e.shiftKey ? -1 : 1),\n                    around: map.unproject(point)\n                }, {originalEvent: e});\n            }\n        };\n    }\n\n    enable() {\n        this._enabled = true;\n    }\n\n    disable() {\n        this._enabled = false;\n        this.reset();\n    }\n\n    isEnabled(): boolean {\n        return this._enabled;\n    }\n\n    isActive(): boolean {\n        return this._active;\n    }\n}\n","import {TapRecognizer, MAX_TAP_INTERVAL} from './tap_recognizer';\nimport type Point from '@mapbox/point-geometry';\nimport type {Handler, HandlerResult} from '../handler';\n\nexport default class TapDragZoomHandler implements Handler {\n    _enabled: boolean;\n    _active: boolean;\n    _swipePoint: Point | null | undefined;\n    _swipeTouch: number;\n    _tapTime: number;\n    _tap: TapRecognizer;\n\n    constructor() {\n\n        this._tap = new TapRecognizer({\n            numTouches: 1,\n            numTaps: 1\n        });\n\n        this.reset();\n    }\n\n    reset() {\n        this._active = false;\n        this._swipePoint = undefined;\n        this._swipeTouch = 0;\n        this._tapTime = 0;\n        this._tap.reset();\n    }\n\n    touchstart(e: TouchEvent, points: Array<Point>, mapTouches: Array<Touch>) {\n        if (this._swipePoint) return;\n\n        if (this._tapTime && e.timeStamp - this._tapTime > MAX_TAP_INTERVAL) {\n            this.reset();\n        }\n\n        if (!this._tapTime) {\n            this._tap.touchstart(e, points, mapTouches);\n        } else if (mapTouches.length > 0) {\n            this._swipePoint = points[0];\n            this._swipeTouch = mapTouches[0].identifier;\n        }\n\n    }\n\n    touchmove(e: TouchEvent, points: Array<Point>, mapTouches: Array<Touch>): HandlerResult | null | undefined {\n        if (!this._tapTime) {\n            this._tap.touchmove(e, points, mapTouches);\n        } else if (this._swipePoint) {\n            if (mapTouches[0].identifier !== this._swipeTouch) {\n                return;\n            }\n\n            const newSwipePoint = points[0];\n            const dist = newSwipePoint.y - this._swipePoint.y;\n            this._swipePoint = newSwipePoint;\n\n            e.preventDefault();\n            this._active = true;\n\n            return {\n                zoomDelta: dist / 128\n            };\n        }\n    }\n\n    touchend(e: TouchEvent, points: Array<Point>, mapTouches: Array<Touch>) {\n        if (!this._tapTime) {\n            const point = this._tap.touchend(e, points, mapTouches);\n            if (point) {\n                this._tapTime = e.timeStamp;\n            }\n        } else if (this._swipePoint) {\n            if (mapTouches.length === 0) {\n                this.reset();\n            }\n        }\n    }\n\n    touchcancel() {\n        this.reset();\n    }\n\n    enable() {\n        this._enabled = true;\n    }\n\n    disable() {\n        this._enabled = false;\n        this.reset();\n    }\n\n    isEnabled(): boolean {\n        return this._enabled;\n    }\n\n    isActive(): boolean {\n        return this._active;\n    }\n}\n","import type {MousePanHandler} from '../mouse';\nimport type TouchPanHandler from './../touch_pan';\n\nexport type DragPanOptions = {\n    linearity?: number;\n    easing?: (t: number) => number;\n    deceleration?: number;\n    maxSpeed?: number;\n};\n\n/**\n * The `DragPanHandler` allows the user to pan the map by clicking and dragging\n * the cursor.\n *\n * @see [Example: Toggle interactions](https://docs.mapbox.com/mapbox-gl-js/example/toggle-interaction-handlers/)\n * @see [Example: Highlight features within a bounding box](https://docs.mapbox.com/mapbox-gl-js/example/using-box-queryrenderedfeatures/)\n */\nexport default class DragPanHandler {\n\n    _el: HTMLElement;\n    _mousePan: MousePanHandler;\n    _touchPan: TouchPanHandler;\n    _inertiaOptions: DragPanOptions;\n\n    /**\n     * @private\n    */\n    constructor(el: HTMLElement, mousePan: MousePanHandler, touchPan: TouchPanHandler) {\n        this._el = el;\n        this._mousePan = mousePan;\n        this._touchPan = touchPan;\n    }\n\n    /**\n     * Enables the \"drag to pan\" interaction and accepts options to control the behavior of the panning inertia.\n     *\n     * @param {Object} [options] Options object.\n     * @param {number} [options.linearity=0] Factor used to scale the drag velocity.\n     * @param {Function} [options.easing] Optional easing function applied to {@link Map#panTo} when applying the drag. Defaults to bezier function using [@mapbox/unitbezier](https://github.com/mapbox/unitbezier).\n     * @param {number} [options.maxSpeed=1400] The maximum value of the drag velocity.\n     * @param {number} [options.deceleration=2500] The rate at which the speed reduces after the pan ends.\n     *\n     * @example\n     * map.dragPan.enable();\n     * @example\n     * map.dragPan.enable({\n     *     linearity: 0.3,\n     *     easing: t => t,\n     *     maxSpeed: 1400,\n     *     deceleration: 2500\n     * });\n     * @see [Example: Highlight features within a bounding box](https://docs.mapbox.com/mapbox-gl-js/example/using-box-queryrenderedfeatures/)\n     */\n    enable(options?: DragPanOptions) {\n        this._inertiaOptions = options || {};\n        this._mousePan.enable();\n        this._touchPan.enable();\n        this._el.classList.add('mapboxgl-touch-drag-pan');\n    }\n\n    /**\n     * Disables the \"drag to pan\" interaction.\n     *\n     * @example\n     * map.dragPan.disable();\n     */\n    disable() {\n        this._mousePan.disable();\n        this._touchPan.disable();\n        this._el.classList.remove('mapboxgl-touch-drag-pan');\n    }\n\n    /**\n     * Returns a Boolean indicating whether the \"drag to pan\" interaction is enabled.\n     *\n     * @returns {boolean} Returns `true` if the \"drag to pan\" interaction is enabled.\n     * @example\n     * const isDragPanEnabled = map.dragPan.isEnabled();\n     */\n    isEnabled(): boolean {\n        return this._mousePan.isEnabled() && this._touchPan.isEnabled();\n    }\n\n    /**\n     * Returns a Boolean indicating whether the \"drag to pan\" interaction is active (currently being used).\n     *\n     * @returns {boolean} Returns `true` if the \"drag to pan\" interaction is active.\n     * @example\n     * const isDragPanActive = map.dragPan.isActive();\n     */\n    isActive(): boolean {\n        return this._mousePan.isActive() || this._touchPan.isActive();\n    }\n}\n","import type {MouseRotateHandler, MousePitchHandler} from '../mouse';\n\n/**\n * The `DragRotateHandler` allows the user to rotate the map by clicking and\n * dragging the cursor while holding the right mouse button or `ctrl` key.\n *\n * @see [Example: Toggle interactions](https://docs.mapbox.com/mapbox-gl-js/example/toggle-interaction-handlers/)\n * @see [Example: Disable map rotation](https://docs.mapbox.com/mapbox-gl-js/example/disable-rotation/)\n */\nexport default class DragRotateHandler {\n\n    _mouseRotate: MouseRotateHandler;\n    _mousePitch: MousePitchHandler;\n    _pitchWithRotate: boolean;\n\n    /**\n     * @param {Object} [options]\n     * @param {number} [options.bearingSnap] The threshold, measured in degrees, that determines when the map's\n     *   bearing will snap to north.\n     * @param {bool} [options.pitchWithRotate=true] Control the map pitch in addition to the bearing\n     * @private\n     */\n    constructor(options: {\n     pitchWithRotate: boolean;\n    }, mouseRotate: MouseRotateHandler, mousePitch: MousePitchHandler) {\n        this._pitchWithRotate = options.pitchWithRotate;\n        this._mouseRotate = mouseRotate;\n        this._mousePitch = mousePitch;\n    }\n\n    /**\n     * Enables the \"drag to rotate\" interaction.\n     *\n     * @example\n     * map.dragRotate.enable();\n     */\n    enable() {\n        this._mouseRotate.enable();\n        if (this._pitchWithRotate) this._mousePitch.enable();\n    }\n\n    /**\n     * Disables the \"drag to rotate\" interaction.\n     *\n     * @example\n     * map.dragRotate.disable();\n     */\n    disable() {\n        this._mouseRotate.disable();\n        this._mousePitch.disable();\n    }\n\n    /**\n     * Returns a Boolean indicating whether the \"drag to rotate\" interaction is enabled.\n     *\n     * @returns {boolean} `true` if the \"drag to rotate\" interaction is enabled.\n     * @example\n     * const isDragRotateEnabled = map.dragRotate.isEnabled();\n     */\n    isEnabled(): boolean {\n        return this._mouseRotate.isEnabled() && (!this._pitchWithRotate || this._mousePitch.isEnabled());\n    }\n\n    /**\n     * Returns a Boolean indicating whether the \"drag to rotate\" interaction is active (currently being used).\n     *\n     * @returns {boolean} Returns `true` if the \"drag to rotate\" interaction is active.\n     * @example\n     * const isDragRotateActive = map.dragRotate.isActive();\n     */\n    isActive(): boolean {\n        return this._mouseRotate.isActive() || this._mousePitch.isActive();\n    }\n}\n","import type {TouchZoomHandler, TouchRotateHandler} from '../touch_zoom_rotate';\nimport type TapDragZoomHandler from '../tap_drag_zoom';\n\nexport type TouchZoomRotateHandlerOptions = {\n    around?: 'center';\n};\n\n/**\n * The `TouchZoomRotateHandler` allows the user to zoom and rotate the map by\n * pinching on a touchscreen.\n *\n * They can zoom with one finger by double tapping and dragging. On the second tap,\n * hold the finger down and drag up or down to zoom in or out.\n *\n * @see [Example: Toggle interactions](https://docs.mapbox.com/mapbox-gl-js/example/toggle-interaction-handlers/)\n */\nexport default class TouchZoomRotateHandler {\n    _el: HTMLElement;\n    _touchZoom: TouchZoomHandler;\n    _touchRotate: TouchRotateHandler;\n    _tapDragZoom: TapDragZoomHandler;\n    _rotationDisabled: boolean;\n    _enabled: boolean;\n\n    /**\n     * @private\n    */\n    constructor(el: HTMLElement, touchZoom: TouchZoomHandler, touchRotate: TouchRotateHandler, tapDragZoom: TapDragZoomHandler) {\n        this._el = el;\n        this._touchZoom = touchZoom;\n        this._touchRotate = touchRotate;\n        this._tapDragZoom = tapDragZoom;\n        this._rotationDisabled = false;\n        this._enabled = true;\n    }\n\n    /**\n     * Enables the \"pinch to rotate and zoom\" interaction.\n     *\n     * @param {Object} [options] Options object.\n     * @param {string} [options.around] If \"center\" is passed, map will zoom around the center.\n     *\n     * @example\n     * map.touchZoomRotate.enable();\n     * @example\n     * map.touchZoomRotate.enable({around: 'center'});\n     */\n    enable(options?: TouchZoomRotateHandlerOptions) {\n        this._touchZoom.enable(options);\n        if (!this._rotationDisabled) this._touchRotate.enable(options);\n        this._tapDragZoom.enable();\n        this._el.classList.add('mapboxgl-touch-zoom-rotate');\n    }\n\n    /**\n     * Disables the \"pinch to rotate and zoom\" interaction.\n     *\n     * @example\n     * map.touchZoomRotate.disable();\n     */\n    disable() {\n        this._touchZoom.disable();\n        this._touchRotate.disable();\n        this._tapDragZoom.disable();\n        this._el.classList.remove('mapboxgl-touch-zoom-rotate');\n    }\n\n    /**\n     * Returns a Boolean indicating whether the \"pinch to rotate and zoom\" interaction is enabled.\n     *\n     * @returns {boolean} `true` if the \"pinch to rotate and zoom\" interaction is enabled.\n     * @example\n     * const isTouchZoomRotateEnabled = map.touchZoomRotate.isEnabled();\n     */\n    isEnabled(): boolean {\n        return this._touchZoom.isEnabled() &&\n            (this._rotationDisabled || this._touchRotate.isEnabled()) &&\n            this._tapDragZoom.isEnabled();\n    }\n\n    /**\n     * Returns true if the handler is enabled and has detected the start of a zoom/rotate gesture.\n     *\n     * @returns {boolean} `true` if enabled and a zoom/rotate gesture was detected.\n     * @example\n     * const isTouchZoomRotateActive = map.touchZoomRotate.isActive();\n     */\n    isActive(): boolean {\n        return this._touchZoom.isActive() || this._touchRotate.isActive() || this._tapDragZoom.isActive();\n    }\n\n    /**\n     * Disables the \"pinch to rotate\" interaction, leaving the \"pinch to zoom\"\n     * interaction enabled.\n     *\n     * @example\n     * map.touchZoomRotate.disableRotation();\n     */\n    disableRotation() {\n        this._rotationDisabled = true;\n        this._touchRotate.disable();\n    }\n\n    /**\n     * Enables the \"pinch to rotate\" interaction.\n     *\n     * @example\n     * map.touchZoomRotate.enable();\n     * map.touchZoomRotate.enableRotation();\n     */\n    enableRotation() {\n        this._rotationDisabled = false;\n        if (this._touchZoom.isEnabled()) this._touchRotate.enable();\n    }\n}\n","import {Event} from '../util/evented';\nimport * as DOM from '../util/dom';\nimport HandlerInertia from './handler_inertia';\nimport {MapEventHandler, BlockableMapEventHandler} from './handler/map_event';\nimport BoxZoomHandler from './handler/box_zoom';\nimport TapZoomHandler from './handler/tap_zoom';\nimport {MousePanHandler, MouseRotateHandler, MousePitchHandler} from './handler/mouse';\nimport TouchPanHandler from './handler/touch_pan';\nimport {TouchZoomHandler, TouchRotateHandler, TouchPitchHandler} from './handler/touch_zoom_rotate';\nimport KeyboardHandler from './handler/keyboard';\nimport ScrollZoomHandler from './handler/scroll_zoom';\nimport DoubleClickZoomHandler from './handler/shim/dblclick_zoom';\nimport ClickZoomHandler from './handler/click_zoom';\nimport TapDragZoomHandler from './handler/tap_drag_zoom';\nimport DragPanHandler from './handler/shim/drag_pan';\nimport DragRotateHandler from './handler/shim/drag_rotate';\nimport TouchZoomRotateHandler from './handler/shim/touch_zoom_rotate';\nimport {bindAll, extend} from '../util/util';\nimport Point from '@mapbox/point-geometry';\nimport assert from 'assert';\nimport {vec3} from 'gl-matrix';\nimport MercatorCoordinate, {latFromMercatorY, mercatorScale} from '../geo/mercator_coordinate';\n\nimport type {Map} from './map';\nimport type {MapEvents} from './events';\nimport type {Handler, HandlerResult} from './handler';\n\nexport type InputEvent = MouseEvent | TouchEvent | KeyboardEvent | WheelEvent;\n\ntype EventsInProgress = {\n    [T in keyof MapEvents]?: MapEvents[T];\n};\n\nconst isMoving = (p: {\n    [key: string]: any;\n}) => p.zoom || p.drag || p.pitch || p.rotate;\n\nclass RenderFrameEvent extends Event<{renderFrame: {timeStamp: number}}, 'renderFrame'> {\n    type: 'renderFrame';\n    timeStamp: number;\n}\n\nclass TrackingEllipsoid {\n    constants: Array<number>;\n    radius: number;\n\n    constructor() {\n        // a, b, c in the equation x²/a² + y²/b² + z²/c² = 1\n        this.constants = [1, 1, 0.01];\n        this.radius = 0;\n    }\n\n    setup(center: vec3, pointOnSurface: vec3) {\n        const centerToSurface = vec3.sub([] as any, pointOnSurface, center);\n        if (centerToSurface[2] < 0) {\n            // @ts-expect-error - TS2345 - Argument of type 'number[]' is not assignable to parameter of type 'ReadonlyVec3'.\n            this.radius = vec3.length(vec3.div([] as any, centerToSurface, this.constants));\n        } else {\n            // The point on surface is above the center. This can happen for example when the camera is\n            // below the clicked point (like a mountain